-- =====================================================================
-- BASELINE de MOVI (proyecto Supabase qhwvuuyjhcennqccgvse)
-- Generado el 2026-10-15 a partir del esquema real de producción.
-- Reemplaza las 1,326 migraciones históricas (archivadas en
-- supabase/migrations_archive/). Ver supabase/README_MIGRACIONES.md.
--
-- Incluye: extensiones, esquemas public/private, tipos, secuencias, tablas,
-- funciones, defaults, constraints, índices, vistas, triggers, RLS,
-- políticas (public + storage), comentarios, grants, publicación realtime
-- y buckets de storage.
-- NO incluye: datos, jobs de pg_cron, secretos de vault (no deben correr
-- en ramas de preview).
-- =====================================================================
SET statement_timeout = 0;
SET lock_timeout = 0;
SET check_function_bodies = false;
SET client_min_messages = warning;
SELECT pg_catalog.set_config('search_path', 'public, extensions', false);

CREATE EXTENSION IF NOT EXISTS pg_net WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS http WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS unaccent WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS cube WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS earthdistance WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS pg_cron WITH SCHEMA pg_catalog;
CREATE EXTENSION IF NOT EXISTS vector WITH SCHEMA public;

CREATE SCHEMA IF NOT EXISTS private;

