CREATE OR REPLACE FUNCTION private.cleanup_tramite_relationships_on_role_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.rol = 'Agente' and old.rol is distinct from new.rol then
    delete from public.tramites_grupos_miembros
    where usuario_id = new.id;
  elsif old.rol = 'Agente' and new.rol is distinct from old.rol then
    update public.tramites_grupos_reglas
    set activo = false
    where usuario_id = new.id
      and activo = true;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.prevent_agent_tramite_team_membership()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM public.usuarios u
    WHERE u.id = NEW.usuario_id
      AND u.rol = 'Agente'
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Un agente no puede ser miembro de un equipo de trámites; configure el equipo que lo atiende en tramites_grupos_reglas';
  END IF;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.accept_seguwallet_terms(p_terms_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_terms_version text;
BEGIN
SELECT version INTO v_terms_version
FROM seguwallet_terms
WHERE id = p_terms_id AND is_active = true;

IF v_terms_version IS NULL THEN
RETURN jsonb_build_object('success', false, 'error', 'Terms not found or not active');
END IF;

UPDATE seguwallet_customers SET
terms_accepted = true,
terms_accepted_at = now(),
terms_version_accepted = v_terms_version,
terms_id_accepted = p_terms_id,
updated_at = now()
WHERE auth_user_id = auth.uid();

RETURN jsonb_build_object('success', true);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.acquire_sicas_lock(p_lock_type text, p_lock_key text, p_process_type text, p_user_id uuid DEFAULT NULL::uuid, p_duration_minutes integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_existing record;
v_lock_id uuid;
BEGIN
-- Expire old locks
UPDATE sicas_process_locks
SET is_active = false
WHERE lock_type = p_lock_type
AND lock_key = p_lock_key
AND is_active = true
AND expires_at < now();

-- Check for active lock
SELECT * INTO v_existing
FROM sicas_process_locks
WHERE lock_type = p_lock_type
AND lock_key = p_lock_key
AND is_active = true
AND expires_at >= now()
LIMIT 1;

IF v_existing IS NOT NULL THEN
RETURN jsonb_build_object(
'acquired', false,
'reason', 'lock_active',
'existing_lock_id', v_existing.id,
'started_at', v_existing.started_at,
'expires_at', v_existing.expires_at,
'process_type', v_existing.process_type
);
END IF;

-- Acquire lock
INSERT INTO sicas_process_locks (lock_type, lock_key, process_type, user_id, expires_at)
VALUES (p_lock_type, p_lock_key, p_process_type, p_user_id, now() + (p_duration_minutes || ' minutes')::interval)
RETURNING id INTO v_lock_id;

RETURN jsonb_build_object(
'acquired', true,
'lock_id', v_lock_id
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.activate_fiscal_rule(p_rule_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_regimen text;
v_vigente_desde date;
BEGIN
-- Obtener datos de la regla a activar
SELECT regimen_codigo, vigente_desde
INTO v_regimen, v_vigente_desde
FROM fiscal_regime_rules
WHERE id = p_rule_id;

IF NOT FOUND THEN
RAISE EXCEPTION 'Regla fiscal no encontrada: %', p_rule_id;
END IF;

-- Desactivar otras versiones activas del mismo régimen
UPDATE fiscal_regime_rules
SET
activo = false,
estado = 'inactivo',
updated_at = now()
WHERE regimen_codigo = v_regimen
AND id != p_rule_id
AND activo = true;

-- Activar esta versión
UPDATE fiscal_regime_rules
SET
activo = true,
estado = 'activo',
updated_at = now()
WHERE id = p_rule_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.activate_multicotizador_tariff(p_package_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_product text;
BEGIN
SELECT product INTO v_product FROM multicotizador_gmm_packages WHERE id = p_package_id;
IF v_product IS NULL THEN
RAISE EXCEPTION 'Package not found';
END IF;

UPDATE multicotizador_gmm_packages
SET status = 'archived', activated_at = NULL
WHERE product = v_product AND status = 'active';

UPDATE multicotizador_gmm_packages
SET status = 'active', activated_at = now(), activated_by = auth.uid()
WHERE id = p_package_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.activate_tariff_package(p_package_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
-- Desactivar todas las tarifas activas
UPDATE tariff_packages
SET status = 'archived'
WHERE status = 'active';

-- Activar la nueva tarifa
UPDATE tariff_packages
SET
status = 'active',
activated_at = now(),
activated_by = auth.uid()
WHERE id = p_package_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.actualizar_asignaciones_cache()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
IF TG_OP = 'INSERT' THEN
INSERT INTO ticket_asignaciones_cache (ticket_id, ejecutivos_ids)
VALUES (NEW.ticket_id, ARRAY[NEW.ejecutivo_id])
ON CONFLICT (ticket_id) 
DO UPDATE SET 
ejecutivos_ids = array_append(ticket_asignaciones_cache.ejecutivos_ids, NEW.ejecutivo_id),
updated_at = now();
ELSIF TG_OP = 'DELETE' THEN
UPDATE ticket_asignaciones_cache
SET ejecutivos_ids = array_remove(ejecutivos_ids, OLD.ejecutivo_id),
updated_at = now()
WHERE ticket_id = OLD.ticket_id;
END IF;
RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.actualizar_fecha_completado_tarea()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
IF NEW.completada = true AND (OLD.completada IS NULL OR OLD.completada = false) THEN
NEW.fecha_completado := now();
ELSIF NEW.completada = false THEN
NEW.fecha_completado := NULL;
END IF;
RETURN NEW;
END;
$function$
;

