 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Cortar si estamos dentro de otro trigger (evita loops)
  IF pg_trigger_depth() > 1 THEN
    RETURN NEW;
  END IF;

  UPDATE tickets
  SET ultima_accion_por = NEW.usuario_id
  WHERE id = NEW.ticket_id;

  RETURN NEW;
END;
$function$
;

