CREATE OR REPLACE FUNCTION public.apply_agent_mapping(agent_key_param text, user_id_param uuid DEFAULT NULL::uuid)
 RETURNS TABLE(updated_count bigint)
 LANGUAGE plpgsql
AS $function$
DECLARE
mapping_record RECORD;
update_count BIGINT;
BEGIN
IF user_id_param IS NOT NULL THEN
UPDATE imported_documents
SET 
movi_user_id = user_id_param,
match_status = 'matched_manual',
match_method = 'manual',
match_confidence = 100
WHERE agent_key = agent_key_param;

GET DIAGNOSTICS update_count = ROW_COUNT;

RETURN QUERY SELECT update_count;
ELSE
SELECT * INTO mapping_record
FROM agent_user_mappings
WHERE agent_key = agent_key_param AND is_active = true
LIMIT 1;

IF mapping_record.matched_user_id IS NOT NULL THEN
UPDATE imported_documents
SET 
movi_user_id = mapping_record.matched_user_id,
match_status = CASE 
WHEN mapping_record.mapping_source = 'manual' THEN 'matched_manual'
ELSE 'matched_auto'
END,
match_method = mapping_record.mapping_source,
match_confidence = mapping_record.confidence
WHERE agent_key = agent_key_param;

GET DIAGNOSTICS update_count = ROW_COUNT;

RETURN QUERY SELECT update_count;
ELSE
RETURN QUERY SELECT 0::BIGINT;
END IF;
END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.apply_vendor_mapping_to_batch(p_batch_id uuid, p_vendor_key text, p_movi_user_id uuid, p_assigned_by uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
v_updated_count integer;
v_mapping_id uuid;
v_source_type text;
v_source_value text;
BEGIN
-- Parsear vendor_key
IF p_vendor_key LIKE 'email:%' THEN
v_source_type := 'email';
v_source_value := SUBSTRING(p_vendor_key FROM 7);
ELSIF p_vendor_key LIKE 'name:%' THEN
v_source_type := 'name';
v_source_value := SUBSTRING(p_vendor_key FROM 6);
ELSE
v_source_type := 'name';
v_source_value := p_vendor_key;
END IF;

-- Insertar/actualizar mapping CORRECTAMENTE (sin WHERE)
INSERT INTO vendor_mappings (
source_type,
source_value,
movi_user_id,
status,
created_by,
updated_by
) VALUES (
v_source_type,
v_source_value,
p_movi_user_id,
'active',
p_assigned_by,
p_assigned_by
)
ON CONFLICT (source_type, source_value)
DO UPDATE SET
movi_user_id = p_movi_user_id,
status = 'active',
updated_by = p_assigned_by,
updated_at = now()
RETURNING id INTO v_mapping_id;

-- Aplicar a commission_details
UPDATE commission_details
SET
movi_user_id = p_movi_user_id,
match_method = 'manual',
pending_assignment = false,
assigned_at = now()
WHERE batch_id = p_batch_id
AND vendor_key = p_vendor_key
AND pending_assignment = true;

GET DIAGNOSTICS v_updated_count = ROW_COUNT;

RETURN jsonb_build_object(
'updated_count', v_updated_count,
'mapping_id', v_mapping_id,
'vendor_key', p_vendor_key,
'source_type', v_source_type,
'source_value', v_source_value,
'movi_user_id', p_movi_user_id
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.apply_vendor_mapping_to_commissions()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
UPDATE sicas_comisiones_pendientes cp
SET usuario_id = vm.usuario_id,
updated_at = now()
FROM vendor_mappings vm
WHERE cp.vend_id = vm.vendor_id
AND cp.desp_id = vm.despacho_id
AND cp.usuario_id IS NULL;

UPDATE sicas_comisiones_pagadas cpg
SET usuario_id = vm.usuario_id,
updated_at = now()
FROM vendor_mappings vm
WHERE cpg.vend_id = vm.vendor_id
AND cpg.desp_id = vm.despacho_id
AND cpg.usuario_id IS NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.apply_vendor_mapping_to_production(p_vendor_key text, p_user_id uuid)
 RETURNS TABLE(records_updated integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_count integer;
BEGIN
-- Actualizar todos los registros de producción con este vendor_key
UPDATE production_records
SET
user_id = p_user_id,
pending_assignment = false,
updated_at = now()
WHERE vendor_key = p_vendor_key
AND (user_id IS NULL OR user_id != p_user_id OR pending_assignment = true);

GET DIAGNOSTICS v_count = ROW_COUNT;

RETURN QUERY SELECT v_count;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.apply_vendor_mappings_to_batch(p_batch_id uuid)
 RETURNS TABLE(matched_count integer, unmatched_count integer, total_processed integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_matched INTEGER := 0;
v_unmatched INTEGER := 0;
v_total INTEGER := 0;
v_detail RECORD;
v_mapping RECORD;
BEGIN
-- Procesar todos los commission_details sin usuario asignado
FOR v_detail IN
SELECT id, vendor_email_raw, vendor_name_raw, vend_id_sicas
FROM commission_details
WHERE batch_id = p_batch_id
AND (usuario_id IS NULL OR is_unmatched = true)
LOOP
v_total := v_total + 1;

-- Buscar mapeo usando la función mejorada
SELECT * INTO v_mapping
FROM find_vendor_mapping_with_sicas(
v_detail.vendor_email_raw,
v_detail.vendor_name_raw,
v_detail.vend_id_sicas
);

IF v_mapping.movi_user_id IS NOT NULL THEN
-- Match encontrado
UPDATE commission_details
SET
usuario_id = v_mapping.movi_user_id,
match_method = v_mapping.match_method,
is_unmatched = false,
updated_at = NOW()
WHERE id = v_detail.id;

v_matched := v_matched + 1;
ELSE
-- Sin match
UPDATE commission_details
SET
match_method = 'none',
is_unmatched = true,
updated_at = NOW()
WHERE id = v_detail.id;

v_unmatched := v_unmatched + 1;
END IF;
END LOOP;

RETURN QUERY SELECT v_matched, v_unmatched, v_total;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.apply_vendor_mappings_to_commission_details(batch_id_param uuid)
 RETURNS TABLE(success boolean, message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
mapping_result RECORD;
updated_count INTEGER := 0;
BEGIN
FOR mapping_result IN
SELECT 
vm.vendor_name_normalized,
vm.movi_user_id,
vm.id as mapping_id
FROM vendor_mappings vm
WHERE vm.is_active = TRUE
LOOP
UPDATE commission_details cd
SET 
usuario_id = mapping_result.movi_user_id,
vendor_mapping_id = mapping_result.mapping_id,
updated_at = NOW()
WHERE cd.batch_id = batch_id_param
AND normalize_vendor_name(cd.vendor_name) = mapping_result.vendor_name_normalized
AND cd.usuario_id IS NULL;

updated_count := updated_count + 1;
END LOOP;

RETURN QUERY SELECT TRUE, format('Se aplicaron %s mapeos de vendedores', updated_count);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.apply_vendor_mappings_to_staging_session(p_session_id uuid)
 RETURNS TABLE(total_processed integer, matched integer, still_unmatched integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
total_count INTEGER := 0;
matched_count INTEGER := 0;
unmatched_count INTEGER := 0;
staging_record RECORD;
mapping_result RECORD;
BEGIN
-- Procesar cada item en staging sin match o con pending_assignment
FOR staging_record IN
SELECT id, vendor_email_raw, vendor_name_raw, movi_user_id, pending_assignment
FROM commission_items_staging
WHERE staging_session_id = p_session_id
AND (pending_assignment = true OR movi_user_id IS NULL)
LOOP
total_count := total_count + 1;

-- Buscar mapeo usando la función existente
SELECT * INTO mapping_result
FROM find_vendor_mapping(staging_record.vendor_email_raw, staging_record.vendor_name_raw);

IF mapping_result.movi_user_id IS NOT NULL THEN
-- Actualizar el item de staging con el match encontrado
UPDATE commission_items_staging
SET
movi_user_id = mapping_result.movi_user_id,
match_method = mapping_result.match_method,
pending_assignment = false,
assigned_at = NOW(),
updated_at = NOW()
WHERE id = staging_record.id;

matched_count := matched_count + 1;
ELSE
-- Marcar como pendiente de asignación
UPDATE commission_items_staging
SET
movi_user_id = NULL,
match_method = 'none',
pending_assignment = true,
updated_at = NOW()
WHERE id = staging_record.id;

unmatched_count := unmatched_count + 1;
END IF;
END LOOP;

-- Actualizar contadores en la sesión
UPDATE commission_staging_sessions
SET
recognized_count = (
SELECT COUNT(*)
FROM commission_items_staging
WHERE staging_session_id = p_session_id
AND movi_user_id IS NOT NULL
AND pending_assignment = false
),
pending_assignment_count = (
SELECT COUNT(*)
FROM commission_items_staging
WHERE staging_session_id = p_session_id
AND pending_assignment = true
),
updated_at = NOW()
WHERE id = p_session_id;

RETURN QUERY SELECT total_count, matched_count, unmatched_count;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.assign_lesson_categories(p_lesson_id uuid, p_category_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
-- Delete existing category assignments for this lesson
DELETE FROM seguros_lesson_categories
WHERE lesson_id = p_lesson_id;

-- Insert new category assignments
INSERT INTO seguros_lesson_categories (lesson_id, category_id)
SELECT p_lesson_id, unnest(p_category_ids)
ON CONFLICT (lesson_id, category_id) DO NOTHING;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.assign_unassigned_conversation(p_old_agent_id uuid, p_new_agent_id uuid, p_assigned_by uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_count int;
BEGIN
UPDATE contact_center_messages
SET agent_user_id = p_new_agent_id,
metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('reassigned_from', p_old_agent_id::text, 'reassigned_by', p_assigned_by::text, 'reassigned_at', now()::text)
WHERE agent_user_id = p_old_agent_id;
GET DIAGNOSTICS v_count = ROW_COUNT;
UPDATE contact_center_attachments SET agent_user_id = p_new_agent_id WHERE agent_user_id = p_old_agent_id;
RETURN v_count;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.assign_vendor_by_key(p_batch_id uuid, p_vendor_key text, p_movi_user_id uuid, p_save_mapping boolean DEFAULT true, p_created_by uuid DEFAULT NULL::uuid)
 RETURNS TABLE(updated_count integer, mapping_saved boolean, error text)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_updated_count INTEGER := 0;
v_mapping_saved BOOLEAN := false;
v_vendor_name_raw TEXT;
v_vendor_email_raw TEXT;
v_vendor_name_norm TEXT;
v_vendor_email_norm TEXT;
v_source_type TEXT;
v_source_value TEXT;
BEGIN
-- Validar que el batch y el grupo existan
IF NOT EXISTS (
SELECT 1 FROM imported_documents
WHERE batch_id = p_batch_id
AND vendor_key = p_vendor_key
AND is_unmatched = true
) THEN
RETURN QUERY SELECT 0, false, 'No se encontraron documentos para este grupo'::TEXT;
RETURN;
END IF;

-- Obtener ejemplo de datos del vendedor
SELECT vendor_name_raw, vendor_email_raw, vendor_name_norm, vendor_email_norm
INTO v_vendor_name_raw, v_vendor_email_raw, v_vendor_name_norm, v_vendor_email_norm
FROM imported_documents
WHERE batch_id = p_batch_id
AND vendor_key = p_vendor_key
AND is_unmatched = true
LIMIT 1;

-- Actualizar todos los documentos del grupo en el batch
UPDATE imported_documents
SET
movi_user_id = p_movi_user_id,
match_method = 'manual',
is_unmatched = false,
updated_at = now()
WHERE batch_id = p_batch_id
AND vendor_key = p_vendor_key
AND is_unmatched = true;

GET DIAGNOSTICS v_updated_count = ROW_COUNT;

-- Guardar mapeo si se solicita
IF p_save_mapping THEN
-- Determinar qué tipo de mapeo guardar (prioridad: nombre > email)
IF v_vendor_name_norm IS NOT NULL AND v_vendor_name_norm != '' THEN
v_source_type := 'name';
v_source_value := v_vendor_name_norm;
ELSIF v_vendor_email_norm IS NOT NULL AND v_vendor_email_norm != '' THEN
v_source_type := 'email';
v_source_value := v_vendor_email_norm;
ELSE
v_source_type := NULL;
v_source_value := NULL;
END IF;

IF v_source_type IS NOT NULL THEN
-- Insertar o actualizar mapeo
INSERT INTO vendor_mappings (
source_type,
source_value,
movi_user_id,
status,
created_by,
updated_by,
source_raw_examples
)
VALUES (
v_source_type,
v_source_value,
p_movi_user_id,
'active',
COALESCE(p_created_by, auth.uid()),
COALESCE(p_created_by, auth.uid()),
jsonb_build_array(
jsonb_build_object(
'name', v_vendor_name_raw,
'email', v_vendor_email_raw
)
)
)
ON CONFLICT (source_type, source_value)
DO UPDATE SET
movi_user_id = p_movi_user_id,
updated_by = COALESCE(p_created_by, auth.uid()),
updated_at = now(),
status = 'active',
source_raw_examples = CASE
WHEN NOT vendor_mappings.source_raw_examples @> jsonb_build_array(jsonb_build_object('name', v_vendor_name_raw))
THEN vendor_mappings.source_raw_examples || jsonb_build_object('name', v_vendor_name_raw, 'email', v_vendor_email_raw)
ELSE vendor_mappings.source_raw_examples
END;

v_mapping_saved := true;
END IF;
END IF;

-- Actualizar contadores del batch
PERFORM update_batch_counters(p_batch_id);

RETURN QUERY SELECT v_updated_count, v_mapping_saved, NULL::TEXT;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.assign_vendor_by_name(p_batch_id uuid, p_vendor_name_norm text, p_movi_user_id uuid, p_save_mapping boolean DEFAULT true, p_created_by uuid DEFAULT NULL::uuid)
 RETURNS TABLE(updated_count integer, mapping_saved boolean, error text)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_updated_count INTEGER := 0;
v_mapping_saved BOOLEAN := false;
v_vendor_name_raw TEXT;
v_vendor_email_raw TEXT;
v_unique_emails TEXT[];
BEGIN
-- Validar que existan documentos con este nombre
IF NOT EXISTS (
SELECT 1 FROM imported_documents
WHERE batch_id = p_batch_id
AND (
(p_vendor_name_norm = 'unknown' AND (vendor_name_norm IS NULL OR vendor_name_norm = '') AND (vendor_email_norm IS NULL OR vendor_email_norm = ''))
OR
(p_vendor_name_norm != 'unknown' AND vendor_name_norm = p_vendor_name_norm)
OR
(p_vendor_name_norm NOT IN ('unknown') AND (vendor_name_norm IS NULL OR vendor_name_norm = '') AND vendor_email_norm = p_vendor_name_norm)
)
AND is_unmatched = true
) THEN
RETURN QUERY SELECT 0, false, 'No se encontraron documentos para este vendedor'::TEXT;
RETURN;
END IF;

-- Obtener ejemplo de datos
SELECT vendor_name_raw, vendor_email_raw
INTO v_vendor_name_raw, v_vendor_email_raw
FROM imported_documents
WHERE batch_id = p_batch_id
AND (
(p_vendor_name_norm = 'unknown' AND (vendor_name_norm IS NULL OR vendor_name_norm = '') AND (vendor_email_norm IS NULL OR vendor_email_norm = ''))
OR
(p_vendor_name_norm != 'unknown' AND vendor_name_norm = p_vendor_name_norm)
OR
(p_vendor_name_norm NOT IN ('unknown') AND (vendor_name_norm IS NULL OR vendor_name_norm = '') AND vendor_email_norm = p_vendor_name_norm)
)
AND is_unmatched = true
LIMIT 1;

-- Obtener todos los emails únicos del grupo
SELECT ARRAY_AGG(DISTINCT vendor_email_raw)
INTO v_unique_emails
FROM imported_documents
WHERE batch_id = p_batch_id
AND (
(p_vendor_name_norm = 'unknown' AND (vendor_name_norm IS NULL OR vendor_name_norm = '') AND (vendor_email_norm IS NULL OR vendor_email_norm = ''))
OR
(p_vendor_name_norm != 'unknown' AND vendor_name_norm = p_vendor_name_norm)
OR
(p_vendor_name_norm NOT IN ('unknown') AND (vendor_name_norm IS NULL OR vendor_name_norm = '') AND vendor_email_norm = p_vendor_name_norm)
)
AND is_unmatched = true
AND vendor_email_raw IS NOT NULL
AND vendor_email_raw != '';

-- Actualizar todos los documentos del grupo
UPDATE imported_documents
SET
movi_user_id = p_movi_user_id,
match_method = 'manual',
is_unmatched = false,
updated_at = now()
WHERE batch_id = p_batch_id
AND (
(p_vendor_name_norm = 'unknown' AND (vendor_name_norm IS NULL OR vendor_name_norm = '') AND (vendor_email_norm IS NULL OR vendor_email_norm = ''))
OR
(p_vendor_name_norm != 'unknown' AND vendor_name_norm = p_vendor_name_norm)
OR
(p_vendor_name_norm NOT IN ('unknown') AND (vendor_name_norm IS NULL OR vendor_name_norm = '') AND vendor_email_norm = p_vendor_name_norm)
)
AND is_unmatched = true;

GET DIAGNOSTICS v_updated_count = ROW_COUNT;

-- Guardar mapeo si se solicita
IF p_save_mapping AND p_vendor_name_norm != 'unknown' THEN
-- Guardar mapeo por nombre si existe
IF p_vendor_name_norm IS NOT NULL AND p_vendor_name_norm != '' AND LEFT(p_vendor_name_norm, 6) != 'email:' THEN
INSERT INTO vendor_mappings (
source_type,
source_value,
movi_user_id,
status,
created_by,
updated_by,
source_raw_examples
)
VALUES (
'name',
p_vendor_name_norm,
p_movi_user_id,
'active',
COALESCE(p_created_by, auth.uid()),
COALESCE(p_created_by, auth.uid()),
jsonb_build_array(
jsonb_build_object(
'name', v_vendor_name_raw,
'emails', v_unique_emails
)
)
)
ON CONFLICT (source_type, source_value)
DO UPDATE SET
movi_user_id = p_movi_user_id,
updated_by = COALESCE(p_created_by, auth.uid()),
updated_at = now(),
status = 'active';

v_mapping_saved := true;
END IF;

-- Si hay emails, también guardar mapeos por cada email único
IF v_unique_emails IS NOT NULL THEN
DECLARE
v_email TEXT;
BEGIN
FOREACH v_email IN ARRAY v_unique_emails
LOOP
IF v_email IS NOT NULL AND v_email != '' THEN
INSERT INTO vendor_mappings (
source_type,
source_value,
movi_user_id,
status,
created_by,
updated_by,
source_raw_examples
)
VALUES (
'email',
LOWER(TRIM(v_email)),
p_movi_user_id,
'active',
COALESCE(p_created_by, auth.uid()),
COALESCE(p_created_by, auth.uid()),
jsonb_build_array(
jsonb_build_object(
'name', v_vendor_name_raw,
'email', v_email
)
)
)
ON CONFLICT (source_type, source_value)
DO UPDATE SET
movi_user_id = p_movi_user_id,
updated_by = COALESCE(p_created_by, auth.uid()),
updated_at = now(),
status = 'active';
END IF;
END LOOP;
END;
END IF;
END IF;

-- Actualizar contadores del batch
PERFORM update_batch_counters(p_batch_id);

RETURN QUERY SELECT v_updated_count, v_mapping_saved, NULL::TEXT;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.assign_vendor_group_by_name(p_batch_id uuid, p_vendor_name_norm text, p_movi_user_id uuid, p_save_mapping boolean DEFAULT true, p_created_by uuid DEFAULT NULL::uuid)
 RETURNS TABLE(updated_count integer, mapping_saved boolean, error text)
