$function$
;

CREATE OR REPLACE FUNCTION public.assign_vendor_manually(batch_id_param uuid, vendor_key_param text, movi_user_id_param uuid, save_mapping boolean, created_by_param uuid)
 RETURNS TABLE(updated_count bigint, mapping_created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_updated_count BIGINT := 0;
v_mapping_created BOOLEAN := false;
v_source_type TEXT;
v_source_value TEXT;
v_example_email TEXT;
v_example_name TEXT;
BEGIN
-- Actualizar commission_details (ahora usa usuario_id en lugar de agent_id)
WITH updated AS (
UPDATE commission_details
SET 
usuario_id = movi_user_id_param,
match_method = 'manual',
is_unmatched = false
WHERE batch_id = batch_id_param
AND vendor_key = vendor_key_param
AND is_unmatched = true
RETURNING id, vendor_email_raw, vendor_name_raw
)
SELECT 
COUNT(*),
MAX(vendor_email_raw),
MAX(vendor_name_raw)
INTO v_updated_count, v_example_email, v_example_name
FROM updated;

-- Guardar mapping si se solicita
IF save_mapping AND v_updated_count > 0 THEN
-- Parsear vendor_key
IF vendor_key_param LIKE 'email:%' THEN
v_source_type := 'email';
v_source_value := SUBSTRING(vendor_key_param FROM 7);
ELSIF vendor_key_param LIKE 'name:%' THEN
v_source_type := 'name';
v_source_value := SUBSTRING(vendor_key_param FROM 6);
END IF;

IF v_source_type IS NOT NULL THEN
-- PASO 1: Desactivar mapeo activo existente con el mismo source
UPDATE vendor_mappings
SET 
status = 'inactive',
updated_by = created_by_param,
updated_at = NOW()
WHERE source_type = v_source_type
AND source_value = v_source_value
AND status = 'active';

-- PASO 2: Desactivar cualquier otro mapeo activo del usuario
UPDATE vendor_mappings
SET 
status = 'inactive',
updated_by = created_by_param,
updated_at = NOW()
WHERE movi_user_id = movi_user_id_param
AND status = 'active';

-- PASO 3: Insertar nuevo mapeo activo
INSERT INTO vendor_mappings (
source_type,
source_value,
source_raw_examples,
movi_user_id,
status,
created_by,
updated_by
)
VALUES (
v_source_type,
v_source_value,
JSONB_BUILD_ARRAY(
JSONB_BUILD_OBJECT(
'email', v_example_email,
'name', v_example_name
)
),
movi_user_id_param,
'active',
created_by_param,
created_by_param
);

v_mapping_created := true;
END IF;
END IF;

RETURN QUERY SELECT v_updated_count, v_mapping_created;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.assign_vendor_manually_to_commission_detail(detail_id_param uuid, movi_user_id_param uuid)
 RETURNS TABLE(success boolean, message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
vendor_name_val TEXT;
mapping_id_val UUID;
BEGIN
SELECT vendor_name INTO vendor_name_val
FROM commission_details
WHERE id = detail_id_param;

IF vendor_name_val IS NULL THEN
RETURN QUERY SELECT FALSE, 'Detalle de comisión no encontrado'::TEXT;
RETURN;
END IF;

INSERT INTO vendor_mappings (vendor_name_normalized, movi_user_id, is_active)
VALUES (normalize_vendor_name(vendor_name_val), movi_user_id_param, TRUE)
ON CONFLICT (vendor_name_normalized) 
DO UPDATE SET 
movi_user_id = movi_user_id_param,
is_active = TRUE,
updated_at = NOW()
RETURNING id INTO mapping_id_val;

UPDATE commission_details
SET 
usuario_id = movi_user_id_param,
vendor_mapping_id = mapping_id_val,
updated_at = NOW()
WHERE id = detail_id_param;

RETURN QUERY SELECT TRUE, 'Vendedor asignado correctamente'::TEXT;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.assign_vendor_to_user(p_batch_id uuid, p_vendor_key text, p_movi_user_id uuid, p_save_mapping boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_source_type text;
v_source_value text;
v_updated_count int;
v_result jsonb;
BEGIN
-- Actualizar todos los documentos con ese vendor_key en el batch
UPDATE imported_documents
SET
movi_user_id = p_movi_user_id,
match_method = 'manual',
is_unmatched = false,
updated_at = now()
WHERE batch_id = p_batch_id
AND vendor_key = p_vendor_key;

GET DIAGNOSTICS v_updated_count = ROW_COUNT;

-- Si se debe guardar el mapeo
IF p_save_mapping THEN
-- Determinar tipo y valor según el vendor_key
IF p_vendor_key LIKE 'email:%' THEN
v_source_type := 'email';
v_source_value := substring(p_vendor_key from 7);
ELSIF p_vendor_key LIKE 'name:%' THEN
v_source_type := 'name';
v_source_value := substring(p_vendor_key from 6);
ELSE
v_source_type := NULL;
v_source_value := NULL;
END IF;

-- Insertar o actualizar mapeo
IF v_source_type IS NOT NULL THEN
INSERT INTO vendor_mappings (
source_type,
source_value,
movi_user_id,
status,
created_by,
updated_by
)
VALUES (
v_source_type,
v_source_value,
p_movi_user_id,
'active',
auth.uid(),
auth.uid()
)
ON CONFLICT (source_type, source_value)
DO UPDATE SET
movi_user_id = p_movi_user_id,
status = 'active',
updated_by = auth.uid(),
updated_at = now();
END IF;
END IF;

-- Actualizar contadores del batch
PERFORM update_batch_counters(p_batch_id);

-- Retornar resultado
v_result := jsonb_build_object(
'success', true,
'updated_count', v_updated_count,
'mapping_saved', p_save_mapping AND v_source_type IS NOT NULL
);

RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.auto_calculate_week_staging()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
week_data record;
BEGIN
IF NEW.date_fpago IS NOT NULL THEN
SELECT * INTO week_data FROM calculate_iso_week_data(NEW.date_fpago);

NEW.week_number := week_data.week_number;
NEW.week_year := week_data.week_year;
NEW.week_start_date := week_data.week_start_date;
NEW.week_end_date := week_data.week_end_date;
END IF;

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.auto_provision_links_on_user_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
-- Only provision if user is active and has a web_slug
IF NEW.activo = true AND NEW.web_slug IS NOT NULL AND NEW.web_slug != '' AND NEW.deleted_at IS NULL THEN
-- Only if becoming active or getting web_slug for first time
IF (OLD IS NULL) OR 
(OLD.activo = false AND NEW.activo = true) OR 
(OLD.web_slug IS NULL AND NEW.web_slug IS NOT NULL) OR
(OLD.web_slug = '' AND NEW.web_slug != '') THEN
PERFORM provision_shared_links_for_user(NEW.id);
END IF;
END IF;
RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.auto_publish_user_web_page()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_web_page_id uuid;
v_category_id uuid;
v_insurer_id uuid;
BEGIN
-- Solo procesar si el usuario tiene web_slug configurado
IF NEW.web_slug IS NOT NULL AND NEW.web_slug != '' THEN

-- Crear o actualizar la página web
INSERT INTO user_web_pages (
user_id,
primary_color,
secondary_color,
custom_text,
is_published
)
VALUES (
NEW.id,
'#2563eb', -- Azul por defecto
'#10b981', -- Verde por defecto
'Asesor profesional de seguros comprometido con tu protección y tranquilidad. Te ofrezco soluciones personalizadas y las mejores opciones del mercado.',
true -- Publicada automáticamente
)
ON CONFLICT (user_id) 
DO UPDATE SET 
is_published = true,
updated_at = now()
RETURNING id INTO v_web_page_id;

-- Agregar todas las categorías activas si no existen
INSERT INTO user_web_page_categories (user_web_page_id, category_id)
SELECT v_web_page_id, id
FROM web_page_categories
WHERE is_active = true
ON CONFLICT (user_web_page_id, category_id) DO NOTHING;

-- Agregar todas las aseguradoras activas si no existen
INSERT INTO user_web_page_insurers (user_web_page_id, insurer_id)
SELECT v_web_page_id, id
FROM web_page_insurers
WHERE is_active = true
ON CONFLICT (user_web_page_id, insurer_id) DO NOTHING;

END IF;

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.buscar_centro_digital_chunks(query_embedding vector, similitud_minima double precision DEFAULT 0.72, max_resultados integer DEFAULT 8, solo_externo boolean DEFAULT false)
 RETURNS TABLE(chunk_id uuid, archivo_id uuid, carpeta_id uuid, archivo_nombre text, carpeta_nombre text, contenido text, metadata jsonb, similitud double precision, knowledge_priority integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN QUERY
SELECT
ch.id AS chunk_id,
ch.archivo_id,
ch.carpeta_id,
a.nombre AS archivo_nombre,
c.nombre AS carpeta_nombre,
ch.contenido,
ch.metadata,
(1 - (ch.embedding <=> query_embedding))::float AS similitud,
c.knowledge_priority
FROM centro_digital_chunks ch
JOIN centro_digital_archivos a ON a.id = ch.archivo_id
JOIN centro_digital_carpetas c ON c.id = ch.carpeta_id
WHERE c.activa = true
AND c.enable_chava_ai = true
AND a.estado = 'activo'
AND ch.embedding IS NOT NULL
AND (1 - (ch.embedding <=> query_embedding)) >= similitud_minima
AND (NOT solo_externo OR c.external_chava_access = true)
ORDER BY
c.knowledge_priority DESC,
ch.embedding <=> query_embedding
LIMIT max_resultados;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.buscar_conocimiento_chava(query_embedding vector, similitud_minima double precision DEFAULT 0.72, max_resultados integer DEFAULT 5, usuario_rol text DEFAULT 'Agente'::text)
 RETURNS TABLE(id uuid, documento_id uuid, documento_titulo text, carpeta_nombre text, contenido text, similitud double precision, metadata jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN QUERY
SELECT
f.id,
f.documento_id,
d.titulo AS documento_titulo,
c.nombre AS carpeta_nombre,
f.contenido,
1 - (f.embedding <=> query_embedding) AS similitud,
f.metadata
FROM chava_fragmentos f
JOIN chava_documentos d ON d.id = f.documento_id
LEFT JOIN chava_carpetas c ON c.id = d.carpeta_id
WHERE d.estado = 'ready'
AND (
d.acceso = 'todos'
OR (d.acceso = 'administrador' AND usuario_rol = 'Administrador')
OR (d.acceso = 'gerente' AND usuario_rol IN ('Administrador', 'Gerente'))
OR (d.acceso = 'ejecutivo' AND usuario_rol IN ('Administrador', 'Gerente', 'Ejecutivo'))
OR (d.acceso = 'agente' AND usuario_rol IN ('Administrador', 'Gerente', 'Ejecutivo', 'Agente'))
)
AND 1 - (f.embedding <=> query_embedding) >= similitud_minima
ORDER BY f.embedding <=> query_embedding
LIMIT max_resultados;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.buscar_conocimiento_digital_center(query_embedding vector, similitud_minima double precision DEFAULT 0.72, max_resultados integer DEFAULT 5)
 RETURNS TABLE(chunk_id uuid, document_id uuid, documento_titulo text, aseguradora text, ramo text, categoria text, contenido text, similitud double precision)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN QUERY
SELECT
c.id AS chunk_id,
c.document_id,
d.titulo AS documento_titulo,
d.aseguradora,
d.ramo,
d.categoria,
c.contenido,
1 - (c.embedding <=> query_embedding) AS similitud
FROM digital_center_knowledge_chunks c
JOIN digital_center_documents d ON d.id = c.document_id
WHERE d.activo = true
AND c.embedding IS NOT NULL
AND 1 - (c.embedding <=> query_embedding) >= similitud_minima
ORDER BY c.embedding <=> query_embedding
LIMIT max_resultados;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.buscar_empleado_por_nombre(p_busqueda text)
 RETURNS TABLE(id uuid, nombre_completo text, nombre text, apellidos text, rol text, puesto text, oficina text, celular_laboral text, celular_personal text, extension_telefonica text, email_laboral text, email_personal text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN QUERY
SELECT 
u.id,
u.nombre || ' ' || u.apellidos as nombre_completo,
u.nombre,
u.apellidos,
u.rol,
u.puesto,
o.nombre as oficina,
u.celular_laboral,
u.celular_personal,
u.extension_telefonica,
u.email_laboral,
u.email_personal
FROM usuarios u
LEFT JOIN oficinas o ON u.oficina_id = o.id
WHERE u.activo = true
AND (
-- Búsqueda en nombre completo
(u.nombre || ' ' || u.apellidos) ILIKE '%' || p_busqueda || '%'
-- O búsqueda por palabras individuales
OR u.nombre ILIKE '%' || p_busqueda || '%'
OR u.apellidos ILIKE '%' || p_busqueda || '%'
-- O búsqueda por partes del nombre
OR EXISTS (
SELECT 1
FROM unnest(string_to_array(lower(p_busqueda), ' ')) AS palabra
WHERE lower(u.nombre) LIKE '%' || palabra || '%'
OR lower(u.apellidos) LIKE '%' || palabra || '%'
)
)
ORDER BY 
-- Ordenar por mejor coincidencia
CASE 
WHEN lower(u.nombre || ' ' || u.apellidos) = lower(p_busqueda) THEN 1
WHEN lower(u.nombre || ' ' || u.apellidos) LIKE lower(p_busqueda) || '%' THEN 2
WHEN lower(u.nombre) LIKE lower(p_busqueda) || '%' THEN 3
ELSE 4
END,
u.nombre, 
u.apellidos;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.calcular_desglose_fiscal_asimilados(p_batch_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
v_usuario_id UUID;
v_regimen_fiscal TEXT;
v_total_comision NUMERIC;
v_vida NUMERIC := 0;
v_sin_vida NUMERIC := 0;
v_ret_contable NUMERIC := 0;
v_dispersion NUMERIC := 0;
v_isr_vida NUMERIC := 0;
v_isr_danios NUMERIC := 0;
v_isr_total NUMERIC := 0;
v_total_pagar NUMERIC := 0;
v_result JSON;
BEGIN
-- ============================================
-- PASO 1: OBTENER USUARIO Y RÉGIMEN FISCAL
-- ============================================

-- Get the first usuario_id from batch details
SELECT DISTINCT cd.usuario_id
INTO v_usuario_id
FROM commission_details cd
WHERE cd.batch_id = p_batch_id
LIMIT 1;

IF v_usuario_id IS NULL THEN
RETURN json_build_object(
'error', 'No se encontró usuario en el lote',
'es_asimilados', false,
'total_comision', 0,
'vida', 0,
'sin_vida', 0,
'ret_contable', 0,
'dispersion', 0,
'iva', 0,
'isr_vida', 0,
'isr_danios', 0,
'isr_total', 0,
'total_pagar', 0
);
END IF;

-- Get regimen fiscal from usuarios
SELECT UPPER(COALESCE(cfr.name, 'HONORARIOS'))
INTO v_regimen_fiscal
FROM usuarios u
LEFT JOIN commission_fiscal_regimes cfr ON u.regimen_fiscal_id = cfr.id
WHERE u.id = v_usuario_id;

-- Si no es ASIMILADOS, retornar valores en cero
IF v_regimen_fiscal IS NULL OR v_regimen_fiscal NOT LIKE '%ASIMILAD%' THEN
RETURN json_build_object(
'regimen_fiscal', COALESCE(v_regimen_fiscal, 'DESCONOCIDO'),
'es_asimilados', false,
'total_comision', 0,
'vida', 0,
'sin_vida', 0,
'ret_contable', 0,
'dispersion', 0,
'iva', 0,
'isr_vida', 0,
'isr_danios', 0,
'isr_total', 0,
'total_pagar', 0
);
END IF;

-- ============================================
-- PASO 2: SUMAR COMISIONES POR VIDA Y SIN VIDA
-- ============================================

SELECT
SUM(CASE
WHEN cd.is_manual_adjusted THEN COALESCE(cd.adjusted_commission_neta, 0)
ELSE cd.commission_neta
END),
SUM(CASE
WHEN LOWER(cd.ramo) = 'vida' THEN
CASE
WHEN cd.is_manual_adjusted THEN COALESCE(cd.adjusted_commission_neta, 0)
ELSE cd.commission_neta
END
ELSE 0
END),
SUM(CASE
WHEN LOWER(cd.ramo) != 'vida' THEN
CASE
WHEN cd.is_manual_adjusted THEN COALESCE(cd.adjusted_commission_neta, 0)
ELSE cd.commission_neta
END
ELSE 0
END)
INTO v_total_comision, v_vida, v_sin_vida
FROM commission_details cd
WHERE cd.batch_id = p_batch_id
AND cd.usuario_id = v_usuario_id;

-- Garantizar valores no nulos
v_total_comision := COALESCE(v_total_comision, 0);
v_vida := COALESCE(v_vida, 0);
v_sin_vida := COALESCE(v_sin_vida, 0);

-- ============================================
-- PASO 3: APLICAR FÓRMULAS FISCALES CORRECTAS
-- ============================================

-- Retención Contable (SOLO VIDA) - 16%
v_ret_contable := ROUND((v_vida * 0.16)::numeric, 2);

-- Costo de Dispersión (SOLO SIN VIDA) - 9%
v_dispersion := ROUND((v_sin_vida * 0.09)::numeric, 2);

-- ISR VIDA = (vida - (retContable / 1.09)) × 0.10
v_isr_vida := ROUND(((v_vida - (v_ret_contable / 1.09)) * 0.10)::numeric, 2);

-- ISR DAÑOS = (sinVida - (costoDispersion / 1.09)) × 0.10
v_isr_danios := ROUND(((v_sin_vida - (v_dispersion / 1.09)) * 0.10)::numeric, 2);

-- ISR TOTAL
v_isr_total := ROUND((v_isr_vida + v_isr_danios)::numeric, 2);

-- TOTAL A PAGAR = total - retContable - dispersion - isrTotal
v_total_pagar := ROUND((v_total_comision - v_ret_contable - v_dispersion - v_isr_total)::numeric, 2);

-- ============================================
-- PASO 4: RETORNAR RESULTADO COMO JSON
-- ============================================

v_result := json_build_object(
'regimen_fiscal', v_regimen_fiscal,
'es_asimilados', true,
'total_comision', v_total_comision,
'vida', v_vida,
'sin_vida', v_sin_vida,
'ret_contable', v_ret_contable,
'dispersion', v_dispersion,
'iva', 0.00,
'isr_vida', v_isr_vida,
'isr_danios', v_isr_danios,
'isr_total', v_isr_total,
'total_pagar', v_total_pagar
);

RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.calcular_desglose_fiscal_general(p_batch_id uuid, p_regimen_fiscal text DEFAULT NULL::text)
 RETURNS TABLE(usuario_id uuid, usuario_nombre text, regimen_fiscal text, total_comision_bruta numeric, total_comision_neta numeric, total_iva_trasladado numeric, total_iva_retenido numeric, total_isr numeric, total_importe_a_pagar numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
BEGIN
RETURN QUERY
SELECT
u.id as usuario_id,
u.nombre_completo as usuario_nombre,
COALESCE(cfr.name, 'HONORARIOS') as regimen_fiscal,
SUM(cd.commission_bruta)::NUMERIC as total_comision_bruta,
SUM(cd.commission_neta)::NUMERIC as total_comision_neta,
SUM(cd.iva_trasladado)::NUMERIC as total_iva_trasladado,
SUM(cd.iva_retenido)::NUMERIC as total_iva_retenido,
SUM(cd.isr)::NUMERIC as total_isr,
SUM(cd.importe_pago)::NUMERIC as total_importe_a_pagar
FROM commission_details cd
INNER JOIN usuarios u ON u.id = cd.usuario_id
LEFT JOIN commission_fiscal_regimes cfr ON cfr.id = u.regimen_fiscal_id
WHERE cd.batch_id = p_batch_id
AND (p_regimen_fiscal IS NULL OR COALESCE(cfr.name, 'HONORARIOS') = p_regimen_fiscal)
GROUP BY u.id, u.nombre_completo, cfr.name
ORDER BY u.nombre_completo;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.calcular_duracion_conexion()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
IF NEW.salida_at IS NOT NULL AND NEW.ingreso_at IS NOT NULL THEN
NEW.duracion_conexion_segundos = EXTRACT(EPOCH FROM (NEW.salida_at - NEW.ingreso_at))::integer;
END IF;
RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_agent_level(p_xp_total integer)
 RETURNS TABLE(nivel integer, rango text)
 LANGUAGE plpgsql
 STABLE
AS $function$
BEGIN
RETURN QUERY
SELECT al.nivel, al.rango
FROM agent_levels al
WHERE p_xp_total >= al.xp_min
AND (al.xp_max IS NULL OR p_xp_total <= al.xp_max)
ORDER BY al.nivel DESC
LIMIT 1;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_asimilados_fiscal_desglose(p_batch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
v_comision_total numeric := 0;
v_comision_vida numeric := 0;
v_comision_sin_vida numeric := 0;
v_ret_contable numeric := 0;
v_costo_dispersion numeric := 0;
v_isr_vida numeric := 0;
v_isr_danios numeric := 0;
v_isr_total numeric := 0;
v_total_final numeric := 0;
v_result jsonb;
BEGIN
-- 1. Calcular Comisión Vida (suma de commission_neta donde ramo = 'Vida')
SELECT COALESCE(SUM(commission_neta), 0) INTO v_comision_vida
FROM commission_details
WHERE batch_id = p_batch_id
AND LOWER(ramo) = 'vida';

-- 2. Calcular Comisión Total (suma de todos los commission_neta)
SELECT COALESCE(SUM(commission_neta), 0) INTO v_comision_total
FROM commission_details
WHERE batch_id = p_batch_id;

-- 3. Comisión Sin Vida = Comisión Total - Comisión Vida
v_comision_sin_vida := v_comision_total - v_comision_vida;

-- 4. Retención Contable: SOLO en Vida (16%)
v_ret_contable := ROUND((v_comision_vida * 0.16)::numeric, 2);

-- 5. Costo de Dispersión: SOLO en Sin Vida (9% para ASIMILADOS)
v_costo_dispersion := ROUND((v_comision_sin_vida * 0.09)::numeric, 2);

-- 6. ISR Vida: (Comisión Vida - Retención Contable) × 10%
v_isr_vida := ROUND(((v_comision_vida - v_ret_contable) * 0.10)::numeric, 2);

-- 7. ISR Daños: (Comisión Sin Vida - Costo Dispersión) × 10%
v_isr_danios := ROUND(((v_comision_sin_vida - v_costo_dispersion) * 0.10)::numeric, 2);

-- 8. ISR Total
v_isr_total := ROUND((v_isr_vida + v_isr_danios)::numeric, 2);

-- 9. Total Final = Comisión Total - Retención - Dispersión - ISR Total
v_total_final := ROUND(
(v_comision_total - v_ret_contable - v_costo_dispersion - v_isr_total)::numeric,
2
);

-- 10. Construir resultado JSON
v_result := jsonb_build_object(
'regimen_fiscal', 'ASIMILADOS',
'base_calculo', 'Comisión Neta',
'comision_total', v_comision_total,
'comision_vida', v_comision_vida,
'comision_sin_vida', v_comision_sin_vida,
'retencion_contable', v_ret_contable,
'costo_dispersion', v_costo_dispersion,
'isr_vida', v_isr_vida,
'isr_danios', v_isr_danios,
'isr_total', v_isr_total,
'total_final', v_total_final,
'formula_isr_vida', '(Comisión Vida - Retención Contable) × 0.10',
'formula_isr_danios', '(Comisión Sin Vida - Dispersión) × 0.10',
'formula_total', 'Comisión Total - Retención - Dispersión - ISR Total',
'calculated_at', NOW()
);

RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_batch_asimilados_fiscal(p_batch_id uuid, p_usuario_id uuid)
 RETURNS TABLE(vida numeric, danios numeric, ret_contable numeric, costo_dispersion numeric, isr_vida numeric, isr_danios numeric, isr_total numeric, total_a_pagar numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE
v_total_vida NUMERIC := 0;
v_total_danios NUMERIC := 0;
v_ret_contable NUMERIC;
v_costo_dispersion NUMERIC;
v_isr_vida_sin_redondear NUMERIC;
v_isr_danios_sin_redondear NUMERIC;
v_isr_total_sin_redondear NUMERIC;
v_isr_vida NUMERIC;
v_isr_danios NUMERIC;
v_isr_total NUMERIC;
v_total_pagar NUMERIC;
BEGIN
-- Sumar totales por tipo de ramo
SELECT 
COALESCE(SUM(CASE WHEN tipo_ramo = 'VIDA' THEN commission_neta ELSE 0 END), 0),
COALESCE(SUM(CASE WHEN tipo_ramo = 'DAÑOS' THEN commission_neta ELSE 0 END), 0)
INTO v_total_vida, v_total_danios
FROM commission_details
WHERE batch_id = p_batch_id
AND usuario_id = p_usuario_id
AND regimen_fiscal = 'ASIMILADOS';

-- Calcular retenciones (estas sí se redondean individualmente)
v_ret_contable := ROUND(v_total_vida * 0.16, 2);
v_costo_dispersion := ROUND(v_total_danios * 0.09, 2);

-- Calcular ISR SIN REDONDEAR
v_isr_vida_sin_redondear := (v_total_vida / 1.16) * 0.10;
v_isr_danios_sin_redondear := (v_total_danios / 1.09) * 0.10;

-- Sumar ISR sin redondear
v_isr_total_sin_redondear := v_isr_vida_sin_redondear + v_isr_danios_sin_redondear;

-- Redondear solo al final
v_isr_total := ROUND(v_isr_total_sin_redondear, 2);

-- Para reporte individual (opcional, puede mostrar la proporción)
v_isr_vida := ROUND(v_isr_vida_sin_redondear, 2);
v_isr_danios := ROUND(v_isr_danios_sin_redondear, 2);

-- Total a pagar
v_total_pagar := ROUND((v_total_vida + v_total_danios) - v_ret_contable - v_costo_dispersion - v_isr_total, 2);

RETURN QUERY SELECT
v_total_vida,
v_total_danios,
v_ret_contable,
v_costo_dispersion,
v_isr_vida,
v_isr_danios,
v_isr_total,
v_total_pagar;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_batch_fiscal_aggregates(p_batch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
-- Redirigir a la nueva función V2
RETURN calculate_batch_fiscal_aggregates_v2(p_batch_id);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_batch_fiscal_aggregates_v2(p_batch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_regimen_count integer;
v_regimen_fiscal text;
v_commission_vida numeric := 0;      -- COMISION EXENTA
v_commission_sinvida numeric := 0;   -- COMISION GRAVADA
v_commission_total numeric := 0;
v_retencion_contable numeric := 0;
v_costo_dispersion numeric := 0;
v_iva numeric := 0;
v_ret_isr numeric := 0;
v_ret_iva numeric := 0;
v_total_neto numeric := 0;
v_detail_count integer := 0;

-- Variables de cálculo intermedio
v_base_isr_exenta numeric;
v_isr_exenta numeric;
v_base_isr_gravada numeric;
v_isr_gravada numeric;
BEGIN
-- Verificar que el batch existe
IF NOT EXISTS (SELECT 1 FROM commission_batches WHERE id = p_batch_id) THEN
RETURN jsonb_build_object(
'success', false,
'error', 'El lote no existe'
);
END IF;

-- Contar details
SELECT COUNT(*)
INTO v_detail_count
FROM commission_details
WHERE batch_id = p_batch_id;

IF v_detail_count = 0 THEN
RETURN jsonb_build_object(
'success', false,
'error', 'El lote no tiene pólizas asociadas'
);
END IF;

-- Sumar comisiones VIDA (exenta) y NO VIDA (gravada)
SELECT 
COALESCE(SUM(CASE WHEN UPPER(tipo_ramo) = 'VIDA' THEN commission_neta ELSE 0 END), 0),
COALESCE(SUM(CASE WHEN UPPER(tipo_ramo) != 'VIDA' THEN commission_neta ELSE 0 END), 0),
COALESCE(SUM(commission_neta), 0)
INTO 
v_commission_vida,
v_commission_sinvida,
v_commission_total
FROM commission_details
WHERE batch_id = p_batch_id;

-- Determinar régimen fiscal del lote
SELECT COUNT(DISTINCT regimen_fiscal), MAX(regimen_fiscal)
INTO v_regimen_count, v_regimen_fiscal
FROM commission_details
WHERE batch_id = p_batch_id
AND regimen_fiscal IS NOT NULL;

IF v_regimen_count > 1 THEN
-- Múltiples regímenes - no se puede calcular automáticamente
v_regimen_fiscal := NULL;
RETURN jsonb_build_object(
'success', false,
'skipped', true,
'reason', 'El lote contiene múltiples regímenes fiscales'
);
END IF;

-- ========================================================================
-- CÁLCULOS POR RÉGIMEN FISCAL (FÓRMULAS EXACTAS)
-- ========================================================================

IF v_regimen_fiscal = 'ASIMILADOS' THEN
-- ASIMILADOS
v_retencion_contable := ROUND(v_commission_vida * 0.16, 2);
v_costo_dispersion := ROUND(v_commission_sinvida * 0.09, 2);
v_iva := 0;

-- ISR: Calcular por separado para exenta y gravada
v_base_isr_exenta := v_commission_vida / 1.16;
v_isr_exenta := ROUND(v_base_isr_exenta * 0.10, 2);

v_base_isr_gravada := v_commission_sinvida / 1.09;
v_isr_gravada := ROUND(v_base_isr_gravada * 0.10, 2);

v_ret_isr := ROUND(v_isr_exenta + v_isr_gravada, 2);
v_ret_iva := 0;

v_total_neto := ROUND(
v_commission_total - v_retencion_contable - v_costo_dispersion - v_ret_isr,
2
);

ELSIF v_regimen_fiscal = 'HONORARIOS' THEN
-- HONORARIOS
v_retencion_contable := 0;
v_costo_dispersion := 0;
v_iva := ROUND(v_commission_sinvida * 0.16, 2);
v_ret_isr := ROUND(v_commission_total * 0.10, 2);
v_ret_iva := ROUND(v_iva * (2.0 / 3.0), 2);

v_total_neto := ROUND(
v_commission_total + v_iva - v_ret_isr - v_ret_iva,
2
);

ELSIF v_regimen_fiscal = 'RESICO' THEN
-- RESICO
v_retencion_contable := 0;
v_costo_dispersion := 0;
v_iva := ROUND(v_commission_sinvida * 0.16, 2);
v_ret_isr := ROUND(v_commission_total * 0.0125, 2);
v_ret_iva := ROUND(v_iva * (2.0 / 3.0), 2);

v_total_neto := ROUND(
v_commission_total + v_iva - v_ret_isr - v_ret_iva,
2
);

ELSE
-- Régimen no reconocido
RETURN jsonb_build_object(
'success', false,
'error', 'Régimen fiscal no reconocido: ' || COALESCE(v_regimen_fiscal, 'NULL')
);
END IF;

-- Actualizar el batch
UPDATE commission_batches
SET
regimen_fiscal = v_regimen_fiscal,
commission_vida = v_commission_vida,
commission_sinvida = v_commission_sinvida,
commission_total = v_commission_total,
retencion_contable = v_retencion_contable,
costo_dispersion = v_costo_dispersion,
iva = v_iva,
ret_isr = v_ret_isr,
ret_iva = v_ret_iva,
total_neto = v_total_neto,
calculated_at = NOW(),
tax_version = '2026-v2-exact',
updated_at = NOW()
WHERE id = p_batch_id;

-- Retornar resultado
RETURN jsonb_build_object(
'success', true,
'regimen_fiscal', v_regimen_fiscal,
'commission_vida', v_commission_vida,
'commission_sinvida', v_commission_sinvida,
'commission_total', v_commission_total,
'retencion_contable', v_retencion_contable,
'costo_dispersion', v_costo_dispersion,
'iva', v_iva,
'ret_isr', v_ret_isr,
'ret_iva', v_ret_iva,
'total_neto', v_total_neto,
'detail_count', v_detail_count,
'tax_version', '2026-v2-exact'
);

END;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_batch_fiscal_desglose(p_batch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_usuario_id uuid;
v_regime_name text;
v_result jsonb;
BEGIN
-- 1. Obtener el usuario del lote (asumiendo que todos los detalles son del mismo usuario)
SELECT DISTINCT usuario_id INTO v_usuario_id
FROM commission_details
WHERE batch_id = p_batch_id
LIMIT 1;

IF v_usuario_id IS NULL THEN
RETURN jsonb_build_object(
'error', 'No se encontró usuario para este lote',
'batch_id', p_batch_id
);
END IF;

-- 2. Obtener régimen fiscal del usuario
SELECT cfr.name INTO v_regime_name
FROM usuarios u
LEFT JOIN commission_fiscal_regimes cfr ON u.regimen_fiscal_id = cfr.id
WHERE u.id = v_usuario_id;

-- 3. Calcular según régimen
IF UPPER(v_regime_name) = 'HONORARIOS' THEN
v_result := calculate_honorarios_fiscal_desglose(p_batch_id);
ELSIF UPPER(v_regime_name) = 'ASIMILADOS' THEN
v_result := calculate_asimilados_fiscal_desglose(p_batch_id);
ELSIF UPPER(v_regime_name) = 'RESICO' THEN
v_result := calculate_resico_fiscal_desglose(p_batch_id);
ELSE
-- Si no hay régimen definido, usar HONORARIOS por defecto
v_result := calculate_honorarios_fiscal_desglose(p_batch_id);
END IF;

RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_batch_status_v2(batch_id_param uuid)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
total_docs int;
unmatched_docs int;
missing_dates int;
current_status text;
BEGIN
-- Obtener el estado actual
SELECT status INTO current_status 
FROM document_import_batches 
WHERE id = batch_id_param;

-- Si ya fue convertido, mantener ese estado
IF current_status = 'converted' THEN
RETURN 'converted';
END IF;

-- Contar documentos
SELECT COUNT(*) INTO total_docs
FROM imported_documents
WHERE batch_id = batch_id_param;

-- Si no hay documentos, uploaded
IF total_docs = 0 THEN
RETURN 'uploaded';
END IF;

-- Contar documentos sin asignar (YA NO BLOQUEA)
SELECT COUNT(*) INTO unmatched_docs
FROM imported_documents
WHERE batch_id = batch_id_param 
AND (movi_user_id IS NULL OR is_unmatched = true);

-- Verificar que todos tengan fecha
SELECT COUNT(*) INTO missing_dates
FROM imported_documents
WHERE batch_id = batch_id_param 
AND (document_data->>'fecha_pago' IS NULL OR document_data->>'fecha_pago' = '');

-- Si faltan fechas, error
IF missing_dates > 0 THEN
RETURN 'error';
END IF;

-- Si tiene documentos y todos tienen fecha válida, LISTO PARA CONVERTIR
-- (incluso si hay sin asignar)
IF unmatched_docs > 0 THEN
RETURN 'ready_to_convert'; -- Cambio: antes era 'needs_mapping'
END IF;

-- Si todo está perfecto
RETURN 'ready_to_convert';
END;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_commission_bruta()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
-- Si importe_base o porcentaje_base son NULL, commission_bruta debe ser NULL (no 0 silencioso)
IF NEW.importe_base IS NULL OR NEW.porcentaje_base IS NULL THEN
NEW.commission_bruta := NULL;
NEW.commission_neta := NULL;
ELSE
-- Calcular commission_bruta = importe_base × (porcentaje_base / 100)
-- Redondear a 2 decimales
NEW.commission_bruta := ROUND((NEW.importe_base * (NEW.porcentaje_base / 100.0))::numeric, 2);

-- Por defecto, commission_neta = commission_bruta (antes de impuestos)
-- Si ya tiene un valor manual ajustado, respetarlo
IF NEW.is_manual_adjusted = TRUE AND NEW.adjusted_commission_neta IS NOT NULL THEN
-- Respetar el ajuste manual
NEW.commission_neta := NEW.adjusted_commission_neta;
ELSE
NEW.commission_neta := NEW.commission_bruta;
END IF;
END IF;

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_commission_with_fiscal_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
v_regime_name text;
v_ramo_lower text;
BEGIN
-- 1. Calcular commission_bruta solo si ambos valores existen
IF NEW.importe_base IS NOT NULL AND NEW.porcentaje_comision IS NOT NULL THEN
NEW.commission_bruta := ROUND((NEW.importe_base * NEW.porcentaje_comision / 100)::numeric, 2);
ELSE
NEW.commission_bruta := NULL;
END IF;

-- 2. Obtener régimen fiscal del usuario
IF NEW.usuario_id IS NOT NULL THEN
SELECT cfr.name INTO v_regime_name
FROM usuarios u
LEFT JOIN commission_fiscal_regimes cfr ON u.regimen_fiscal_id = cfr.id
WHERE u.id = NEW.usuario_id;
END IF;

-- 3. Para cálculos a nivel de póliza individual:
-- commission_neta = commission_bruta (los impuestos se aplican a nivel de lote)
-- Esto es correcto porque las retenciones ISR/IVA se calculan sobre totales agregados
IF NEW.commission_bruta IS NOT NULL THEN
NEW.commission_neta := NEW.commission_bruta;
ELSE
NEW.commission_neta := NULL;
END IF;

-- 4. Guardar metadata del régimen en impuestos_json
IF v_regime_name IS NOT NULL THEN
-- Normalizar el ramo
v_ramo_lower := LOWER(COALESCE(NEW.ramo, ''));

-- Guardar información básica del régimen
NEW.impuestos_json := jsonb_build_object(
'regimen_fiscal', v_regime_name,
'ramo', NEW.ramo,
'es_vida', (v_ramo_lower = 'vida'),
'nota', 'Retenciones fiscales se calculan a nivel de lote completo'
);
ELSE
NEW.impuestos_json := jsonb_build_object(
'regimen_fiscal', 'NO_DEFINIDO',
'nota', 'Usuario sin régimen fiscal asignado'
);
END IF;

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_detail_fiscal_values()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_regimen_fiscal TEXT;
v_tipo_ramo TEXT;
BEGIN
-- Obtener régimen fiscal del usuario y normalizar
SELECT UPPER(TRIM(COALESCE(cfr.name, 'HONORARIOS')))
INTO v_regimen_fiscal
FROM usuarios u
LEFT JOIN commission_fiscal_regimes cfr ON cfr.id = u.regimen_fiscal_id
WHERE u.id = NEW.usuario_id;

-- Asegurar que siempre tenga un valor válido
IF v_regimen_fiscal IS NULL OR v_regimen_fiscal = '' THEN
v_regimen_fiscal := 'HONORARIOS';
END IF;

-- Normalizar variantes comunes
IF v_regimen_fiscal LIKE '%RESICO%' OR v_regimen_fiscal LIKE '%SIMPLIFICADO%' THEN
v_regimen_fiscal := 'RESICO';
ELSIF v_regimen_fiscal LIKE '%ASIMILAD%' THEN
v_regimen_fiscal := 'ASIMILADOS';
ELSIF v_regimen_fiscal LIKE '%HONORARIO%' THEN
v_regimen_fiscal := 'HONORARIOS';
END IF;

-- Calcular tipo_ramo desde el campo ramo
IF UPPER(NEW.ramo) = 'VIDA' THEN
v_tipo_ramo := 'VIDA';
ELSE
v_tipo_ramo := 'DAÑOS';
END IF;

-- SOLO guardar régimen y tipo, NO calcular valores fiscales individuales
NEW.regimen_fiscal := v_regimen_fiscal;
NEW.tipo_ramo := v_tipo_ramo;

-- Inicializar valores fiscales en 0 (se calcularán a nivel de lote)
NEW.iva := 0;
NEW.ret_isr := 0;
NEW.ret_iva := 0;
NEW.retencion_contable := 0;
NEW.costo_dispersion := 0;
NEW.total_neto := NEW.commission_neta;
NEW.calculated_at := NOW();

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_honorarios_fiscal_desglose(p_batch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
v_prima_total numeric := 0;
v_prima_vida numeric := 0;
v_prima_sin_vida numeric := 0;
v_ret_contable numeric := 0;
v_costo_dispersion numeric := 0;
v_isr_vida numeric := 0;
v_isr_danios numeric := 0;
v_isr_total numeric := 0;
v_total_final numeric := 0;
v_result jsonb;
BEGIN
-- 1. Calcular Prima Vida (suma de importe_base donde ramo = 'Vida')
SELECT COALESCE(SUM(importe_base), 0) INTO v_prima_vida
FROM commission_details
WHERE batch_id = p_batch_id
AND LOWER(ramo) = 'vida';

-- 2. Calcular Prima Total (suma de todos los importe_base)
SELECT COALESCE(SUM(importe_base), 0) INTO v_prima_total
FROM commission_details
WHERE batch_id = p_batch_id;

-- 3. Prima Sin Vida = Prima Total - Prima Vida
v_prima_sin_vida := v_prima_total - v_prima_vida;

-- 4. Retención Contable: SOLO en Vida (16%)
v_ret_contable := ROUND((v_prima_vida * 0.16)::numeric, 2);

-- 5. Costo de Dispersión: SOLO en Sin Vida (9%, no 10%)
v_costo_dispersion := ROUND((v_prima_sin_vida * 0.09)::numeric, 2);

-- 6. ISR Vida: (Prima Vida / 1.16) × 10% - NO resta retención
IF v_prima_vida > 0 THEN
v_isr_vida := ROUND(((v_prima_vida / 1.16) * 0.10)::numeric, 2);
ELSE
v_isr_vida := 0;
END IF;

-- 7. ISR Daños: (Prima Sin Vida / 1.09) × 10%
IF v_prima_sin_vida > 0 THEN
v_isr_danios := ROUND(((v_prima_sin_vida / 1.09) * 0.10)::numeric, 2);
ELSE
v_isr_danios := 0;
END IF;

-- 8. ISR Total
v_isr_total := ROUND((v_isr_vida + v_isr_danios)::numeric, 2);

-- 9. Total Final = Prima Total - Retención - Dispersión - ISR Total
v_total_final := ROUND(
(v_prima_total - v_ret_contable - v_costo_dispersion - v_isr_total)::numeric,
2
);

-- 10. Construir resultado JSON con todos los valores para auditoría
v_result := jsonb_build_object(
'regimen_fiscal', 'HONORARIOS',
'base_calculo', 'Prima Total (importe_base)',
'prima_total', v_prima_total,
'prima_vida', v_prima_vida,
'prima_sin_vida', v_prima_sin_vida,
'retencion_contable', v_ret_contable,
'costo_dispersion', v_costo_dispersion,
'isr_vida', v_isr_vida,
'isr_danios', v_isr_danios,
'isr_total', v_isr_total,
'total_final', v_total_final,
'formula_isr_vida', '(Prima Vida / 1.16) × 0.10 (NO resta retención)',
'formula_isr_danios', '(Prima Sin Vida / 1.09) × 0.10',
'formula_total', 'Prima Total - Retención - Dispersión - ISR Total',
'calculated_at', NOW()
);

RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_iso_week_data(input_date date)
 RETURNS TABLE(week_number integer, week_year integer, week_start_date date, week_end_date date)
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
week_num int;
year_num int;
start_date date;
end_date date;
BEGIN
-- Calcular semana ISO (1-53)
week_num := EXTRACT(WEEK FROM input_date)::int;
year_num := EXTRACT(YEAR FROM input_date)::int;

-- Calcular inicio de semana (lunes)
start_date := input_date - ((EXTRACT(DOW FROM input_date)::int + 6) % 7);

-- Calcular fin de semana (domingo)
end_date := start_date + 6;

-- Ajustar año si la semana 1 pertenece al año anterior
IF week_num >= 52 AND EXTRACT(MONTH FROM input_date) = 1 THEN
year_num := year_num - 1;
ELSIF week_num = 1 AND EXTRACT(MONTH FROM input_date) = 12 THEN
year_num := year_num + 1;
END IF;

RETURN QUERY SELECT week_num, year_num, start_date, end_date;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_ticket_resultado()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
v_activity_type_name text;
v_estatus_nombre text;
v_is_cotizacion_emision boolean := false;
BEGIN
-- Only applies to registro_actividad and cotizacion_emision
IF NEW.tipo_tramite NOT IN ('registro_actividad', 'cotizacion_emision') THEN
RETURN NEW;
END IF;

-- For cotizacion_emision tipo_tramite, it's always a cotizacion/emision
IF NEW.tipo_tramite = 'cotizacion_emision' THEN
v_is_cotizacion_emision := true;
ELSIF NEW.activity_subtype_id IS NOT NULL THEN
SELECT nombre INTO v_activity_type_name
FROM tramite_activity_types
WHERE id = NEW.activity_subtype_id;
v_is_cotizacion_emision := (
lower(v_activity_type_name) LIKE '%cotizaci%' OR
lower(v_activity_type_name) LIKE '%emisi%'
);
END IF;

IF NEW.estatus_id IS NOT NULL THEN
SELECT nombre INTO v_estatus_nombre
FROM ticket_estatus
WHERE id = NEW.estatus_id;
END IF;

IF v_is_cotizacion_emision THEN
IF v_estatus_nombre IN ('Emitido (Ganado)', 'Emitido') THEN
NEW.resultado := 'ganado';
NEW.cerrado := true;
IF NEW.fecha_cierre IS NULL THEN
NEW.fecha_cierre := now();
END IF;
ELSIF v_estatus_nombre IN ('No Emitido (Perdido)', 'No Emitido') THEN
NEW.resultado := 'perdido';
NEW.cerrado := true;
IF NEW.fecha_cierre IS NULL THEN
NEW.fecha_cierre := now();
END IF;
ELSE
NEW.resultado := 'en_progreso';
END IF;
ELSE
IF v_estatus_nombre IN ('Emitido (Ganado)', 'No Emitido (Perdido)', 'Cerrado') THEN
NEW.cerrado := true;
IF NEW.fecha_cierre IS NULL THEN
NEW.fecha_cierre := now();
END IF;
END IF;
END IF;

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_vendor_key(vendor_email text, vendor_name text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
normalized_email text;
normalized_name text;
BEGIN
-- Intentar usar email primero
normalized_email := normalize_email(vendor_email);
IF normalized_email IS NOT NULL AND normalized_email != '' THEN
RETURN 'email:' || normalized_email;
END IF;

-- Fallback a nombre
normalized_name := normalize_name(vendor_name);
IF normalized_name IS NOT NULL AND normalized_name != '' THEN
RETURN 'name:' || normalized_name;
END IF;

-- Si no hay ni email ni nombre
RETURN 'unknown';
END;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_veteran_multiplier(p_anios numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
BEGIN
-- 2% por año de antigüedad: 1.00 + (años × 0.02)
RETURN GREATEST(1.00, 1.00 + (p_anios * 0.02));
END;
$function$
;

CREATE OR REPLACE FUNCTION public.can_access_ticket(p_ticket_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.tickets t
    WHERE t.id = p_ticket_id
      AND (
        public.is_admin_or_manager()
        OR t.creado_por = auth.uid()
        OR t.assigned_to_user_id = auth.uid()
        OR t.attending_user_id = auth.uid()
        OR t.agente_id = auth.uid()
        OR EXISTS (
          SELECT 1 FROM public.usuarios u
          WHERE u.id = auth.uid() AND u.rol = 'Empleado'
        )
      )
  );
$function$
;

CREATE OR REPLACE FUNCTION public.catalogo_vehiculos_opciones(p_nivel text, p_marca text DEFAULT NULL::text, p_modelo text DEFAULT NULL::text, p_version text DEFAULT NULL::text)
 RETURNS TABLE(valor text, claves bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    CASE p_nivel
      WHEN 'marca'   THEN marca
      WHEN 'modelo'  THEN modelo
      WHEN 'version' THEN version
    END AS valor,
    COUNT(*) AS claves
  FROM catalogo_vehiculos
  WHERE activo
    -- Cada filtro se ignora cuando el nivel pedido ES ese filtro: si no, pedir
    -- las marcas teniendo una marca elegida devolvería solo esa.
    AND (p_marca   IS NULL OR p_nivel = 'marca'   OR marca   = p_marca)
    AND (p_modelo  IS NULL OR p_nivel = 'modelo'  OR modelo  = p_modelo)
    AND (p_version IS NULL OR p_nivel = 'version' OR version = p_version)
  GROUP BY 1
  HAVING CASE p_nivel
      WHEN 'marca'   THEN marca
      WHEN 'modelo'  THEN modelo
      WHEN 'version' THEN version
    END IS NOT NULL
  ORDER BY 1;
$function$
;

CREATE OR REPLACE FUNCTION public.check_admin_permissions()
 RETURNS TABLE(current_user_id uuid, user_exists boolean, user_role text, can_insert boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  RETURN QUERY
  SELECT 
    auth.uid() as current_user_id,
    EXISTS(SELECT 1 FROM usuarios WHERE id = auth.uid()) as user_exists,
    COALESCE((SELECT rol FROM usuarios WHERE id = auth.uid()), 'No encontrado') as user_role,
    EXISTS(
      SELECT 1 FROM usuarios 
      WHERE id = auth.uid() 
      AND rol = 'Administrador'
    ) as can_insert;
END;
$function$
;

