CREATE OR REPLACE FUNCTION public.check_mission_progress(p_user_id uuid, p_mission_id uuid, p_incremento integer DEFAULT 1)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_mission agent_missions;
v_progress agent_mission_progress;
v_periodo TEXT;
v_completada BOOLEAN := false;
BEGIN
-- Obtener misión
SELECT * INTO v_mission
FROM agent_missions
WHERE id = p_mission_id AND activa = true;

IF NOT FOUND THEN
RETURN false;
END IF;

-- Calcular periodo
IF v_mission.tipo_periodo = 'semanal' THEN
v_periodo := to_char(CURRENT_DATE, 'IYYY-IW');
ELSIF v_mission.tipo_periodo = 'mensual' THEN
v_periodo := to_char(CURRENT_DATE, 'YYYY-MM');
ELSIF v_mission.tipo_periodo = 'unica' THEN
v_periodo := 'unica';
ELSE
v_periodo := 'permanente';
END IF;

-- Obtener o crear progreso
INSERT INTO agent_mission_progress (
user_id,
mission_id,
periodo,
progreso_actual,
meta_requerida
) VALUES (
p_user_id,
p_mission_id,
v_periodo,
0,
(v_mission.regla_json->>'cantidad')::INTEGER
)
ON CONFLICT (user_id, mission_id, periodo)
DO NOTHING;

-- Actualizar progreso
UPDATE agent_mission_progress
SET 
progreso_actual = progreso_actual + p_incremento,
updated_at = now()
WHERE user_id = p_user_id
AND mission_id = p_mission_id
AND periodo = v_periodo
AND NOT completada
RETURNING * INTO v_progress;

-- Verificar si se completó
IF v_progress.progreso_actual >= v_progress.meta_requerida AND NOT v_progress.completada THEN
UPDATE agent_mission_progress
SET 
completada = true,
fecha_completada = now()
WHERE id = v_progress.id;

-- Otorgar recompensa
PERFORM add_gamification_event(
p_user_id := p_user_id,
p_tipo_evento := 'mision_completada',
p_referencia_tipo := 'mision',
p_referencia_id := p_mission_id::TEXT,
p_xp_delta := v_mission.xp_reward,
p_jc_delta := v_mission.jc_reward,
p_metadata := jsonb_build_object(
'mision_nombre', v_mission.nombre,
'periodo', v_periodo
)
);

v_completada := true;
END IF;

RETURN v_completada;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.check_sicas_circuit_breaker()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_state record;
BEGIN
SELECT * INTO v_state FROM sicas_circuit_breaker LIMIT 1;

IF v_state IS NULL THEN
INSERT INTO sicas_circuit_breaker (is_open, error_count_5min, timeout_count_5min)
VALUES (false, 0, 0)
RETURNING * INTO v_state;
END IF;

-- If open and past close time, auto-close
IF v_state.is_open AND v_state.closes_at IS NOT NULL AND v_state.closes_at <= now() THEN
UPDATE sicas_circuit_breaker
SET is_open = false, error_count_5min = 0, timeout_count_5min = 0, updated_at = now()
WHERE id = v_state.id;

RETURN jsonb_build_object('is_open', false, 'reason', 'auto_closed');
END IF;

RETURN jsonb_build_object(
'is_open', v_state.is_open,
'reason', v_state.reason,
'closes_at', v_state.closes_at,
'error_count_5min', v_state.error_count_5min,
'timeout_count_5min', v_state.timeout_count_5min
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.check_sicas_stale_sync()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_last_completed_at   timestamptz;
v_hours_since_sync    numeric;
v_admin_id            uuid;
v_recent_alert_count  int;
BEGIN
-- Get last successful sync completion
SELECT finished_at INTO v_last_completed_at
FROM sicas_sync_jobs
WHERE status = 'completed'
ORDER BY finished_at DESC
LIMIT 1;

-- Calculate hours since last sync (NULL = never synced = treat as 9999 hours)
IF v_last_completed_at IS NULL THEN
v_hours_since_sync := 9999;
ELSE
v_hours_since_sync := EXTRACT(EPOCH FROM (now() - v_last_completed_at)) / 3600.0;
END IF;

-- Only alert if stale (>48h)
IF v_hours_since_sync < 48 THEN
RETURN;
END IF;

-- Dedup: skip if we already sent an alert in the last 6 hours
SELECT COUNT(*) INTO v_recent_alert_count
FROM notificaciones_globales
WHERE tipo = 'alerta'
AND titulo ILIKE '%sincronización SICAS%'
AND created_at > now() - interval '6 hours';

IF v_recent_alert_count > 0 THEN
RETURN;
END IF;

-- Notify all admin users
FOR v_admin_id IN
SELECT id FROM usuarios
WHERE rol = 'admin'
AND activo = true
AND (eliminado IS NULL OR eliminado = false)
LOOP
INSERT INTO notificaciones_globales (
usuario_id,
tipo,
titulo,
mensaje,
url,
leida,
created_at
) VALUES (
v_admin_id,
'alerta',
'Sincronización SICAS desactualizada',
CASE
WHEN v_last_completed_at IS NULL
THEN 'No se ha completado ninguna sincronización con SICAS. Verifica la conexión y el estado del servidor.'
ELSE format(
'La última sincronización exitosa con SICAS fue hace %.0f horas (%s). Se esperaba sincronización cada 30 minutos.',
v_hours_since_sync,
to_char(v_last_completed_at AT TIME ZONE 'America/Mexico_City', 'DD/MM/YYYY HH24:MI')
)
END,
'/produccion/configuracion',
false,
now()
);
END LOOP;

END;
$function$
;

CREATE OR REPLACE FUNCTION public.check_user_can_login(user_id_to_check uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
user_record RECORD;
BEGIN
-- Get user info
SELECT 
id,
nombre,
rol,
activo,
is_deleted,
estado,
deleted_at
INTO user_record
FROM usuarios
WHERE id = user_id_to_check;

-- User not found in usuarios table
IF NOT FOUND THEN
RETURN jsonb_build_object(
'can_login', false,
'error', 'Usuario no encontrado en el sistema',
'error_code', 'USER_NOT_FOUND'
);
END IF;

-- User is soft deleted
IF user_record.is_deleted = true THEN
RETURN jsonb_build_object(
'can_login', false,
'error', 'Tu cuenta ha sido desactivada. Contacta al administrador.',
'error_code', 'USER_DELETED',
'deleted_at', user_record.deleted_at
);
END IF;

-- User is inactive
IF user_record.activo = false THEN
RETURN jsonb_build_object(
'can_login', false,
'error', 'Tu cuenta está inactiva. Contacta al administrador.',
'error_code', 'USER_INACTIVE'
);
END IF;

-- User is suspended
IF user_record.estado = 'suspendido' THEN
RETURN jsonb_build_object(
'can_login', false,
'error', 'Tu cuenta está suspendida. Contacta al administrador.',
'error_code', 'USER_SUSPENDED'
);
END IF;

-- User can login
RETURN jsonb_build_object(
'can_login', true,
'user_id', user_record.id,
'user_name', user_record.nombre,
'user_rol', user_record.rol
);

EXCEPTION
WHEN OTHERS THEN
RETURN jsonb_build_object(
'can_login', false,
'error', 'Error al verificar acceso',
'error_code', 'UNEXPECTED_ERROR',
'message', SQLERRM
);
END;
$function$
;

