CREATE OR REPLACE FUNCTION public.claim_express_lead(p_lead_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_habilitado boolean; v_activo boolean;
  v_lead public.express_leads%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'no_autenticado');
  END IF;

  SELECT seguros_express_habilitado, activo INTO v_habilitado, v_activo
  FROM public.usuarios WHERE id = v_uid;

  IF NOT COALESCE(v_habilitado, false) OR NOT COALESCE(v_activo, false) THEN
    RETURN jsonb_build_object('success', false, 'reason', 'no_habilitado');
  END IF;

  IF NOT public.express_lead_en_alcance(p_lead_id) THEN
    RETURN jsonb_build_object('success', false, 'reason', 'fuera_de_alcance');
  END IF;

  UPDATE public.express_leads
     SET agente_asignado_id = v_uid, estado = 'contactado', updated_at = now()
   WHERE id = p_lead_id AND agente_asignado_id IS NULL AND estado = 'notificado'
  RETURNING * INTO v_lead;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'reason', 'ya_tomado');
  END IF;

  PERFORM public.enviar_notificacion_individual(
    v_uid, 'Lead seguros.express tomado',
    format('Tomaste el lead de %s (%s). Contáctalo pronto.',
           COALESCE(v_lead.nombre, 'cliente'), COALESCE(v_lead.tipo_seguro_interes, 'seguro')),
    'CRM', '/mi-crm/leads-seguros-express', true
  );

  RETURN jsonb_build_object(
    'success', true,
    'lead', jsonb_build_object(
      'id', v_lead.id, 'nombre', v_lead.nombre, 'telefono', v_lead.telefono,
      'email', v_lead.email, 'tipo_seguro_interes', v_lead.tipo_seguro_interes,
      'direccion_manual', v_lead.direccion_manual, 'lat', v_lead.lat, 'lng', v_lead.lng,
      'estado', v_lead.estado
    )
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.claim_notification_jobs(p_batch_size integer DEFAULT 50)
 RETURNS TABLE(id uuid, event_code text, user_id uuid, channel text, status text, payload jsonb, attempt_count integer, max_attempts integer, idempotency_key text, attachments jsonb, created_at timestamp with time zone, updated_at timestamp with time zone, next_retry_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
-- Primero: reciclar jobs atascados en 'processing' por más de 5 minutos
-- (instancia que murió a la mitad)
UPDATE notification_jobs
SET
status               = 'pending',
processing_started_at = NULL,
updated_at           = NOW()
WHERE status = 'processing'
AND processing_started_at IS NOT NULL
AND processing_started_at < NOW() - INTERVAL '5 minutes'
AND attempt_count < COALESCE(max_attempts, 3);

-- Reclamar jobs usando FOR UPDATE SKIP LOCKED (atómico, sin race condition)
RETURN QUERY
WITH claimed AS (
SELECT nj.id
FROM notification_jobs nj
WHERE nj.status = 'pending'
AND (nj.next_retry_at IS NULL OR nj.next_retry_at <= NOW())
ORDER BY nj.created_at ASC
LIMIT p_batch_size
FOR UPDATE SKIP LOCKED
)
UPDATE notification_jobs j
SET
status                = 'processing',
processing_started_at = NOW(),
updated_at            = NOW()
FROM claimed
WHERE j.id = claimed.id
RETURNING
j.id,
j.event_code,
j.user_id,
j.channel,
j.status,
j.payload,
j.attempt_count,
j.max_attempts,
j.idempotency_key,
j.attachments,
j.created_at,
j.updated_at,
j.next_retry_at;
END;
$function$
;

