CREATE OR REPLACE FUNCTION public.cleanup_stale_notification_jobs()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_recycled int;
v_failed   int;
BEGIN
-- Reciclar processing atascados > 5 min con reintentos disponibles
UPDATE notification_jobs
SET
status                = 'pending',
processing_started_at = NULL,
updated_at            = NOW()
WHERE status = 'processing'
AND processing_started_at < NOW() - INTERVAL '5 minutes'
AND attempt_count < COALESCE(max_attempts, 3);

GET DIAGNOSTICS v_recycled = ROW_COUNT;

-- Marcar como failed los que superaron max_attempts y siguen atascados
UPDATE notification_jobs
SET
status     = 'failed',
last_error = 'Excedió reintentos máximos o tiempo de procesamiento',
updated_at = NOW()
WHERE status = 'processing'
AND processing_started_at < NOW() - INTERVAL '10 minutes';

GET DIAGNOSTICS v_failed = ROW_COUNT;

IF v_recycled > 0 OR v_failed > 0 THEN
RAISE NOTICE '[NOTIFICATION CLEANUP] Reciclados: %, Fallidos definitivos: %',
v_recycled, v_failed;
END IF;

RETURN v_recycled + v_failed;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.complete_seguwallet_profile(p_state text, p_municipality text, p_birth_date date, p_gender text, p_terms_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_customer_id uuid;
v_already_completed boolean;
v_terms_version text;
v_now timestamptz := now();
BEGIN
SELECT id, profile_completed INTO v_customer_id, v_already_completed
FROM seguwallet_customers
WHERE auth_user_id = auth.uid();

IF v_customer_id IS NULL THEN
RETURN jsonb_build_object('success', false, 'error', 'Customer not found');
END IF;

SELECT version INTO v_terms_version
FROM seguwallet_terms
WHERE id = p_terms_id AND is_active = true;

IF v_terms_version IS NULL THEN
RETURN jsonb_build_object('success', false, 'error', 'Terms not found or not active');
END IF;

IF p_gender NOT IN ('Masculino', 'Femenino', 'Otro', 'Prefiero no decirlo') THEN
RETURN jsonb_build_object('success', false, 'error', 'Género inválido');
END IF;

UPDATE seguwallet_customers SET
state = p_state,
municipality = p_municipality,
birth_date = p_birth_date,
gender = p_gender,
profile_completed = true,
profile_completed_at = CASE WHEN NOT COALESCE(v_already_completed, false) THEN v_now ELSE profile_completed_at END,
terms_accepted = true,
terms_accepted_at = v_now,
terms_version_accepted = v_terms_version,
terms_id_accepted = p_terms_id,
updated_at = v_now
WHERE auth_user_id = auth.uid();

RETURN jsonb_build_object('success', true, 'profile_completed', true);
END;
$function$
;

