CREATE OR REPLACE FUNCTION public.confirm_fuzzy_matches(p_threshold numeric DEFAULT 0.92)
 RETURNS TABLE(confirmed_count integer, vendor_mappings_created integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_confirmed INT := 0;
  v_vm_created INT := 0;
  rec RECORD;
BEGIN
  FOR rec IN
    SELECT DISTINCT ON (vm.id)
      vm.id AS vendor_id,
      vm.vend_id,
      vm.vend_nombre,
      u.id AS usuario_id,
      similarity(UPPER(vm.vend_nombre), UPPER(u.nombre || ' ' || u.apellidos))::NUMERIC AS sim_score
    FROM sicas_vendor_user_mappings vm
    JOIN usuarios u ON similarity(UPPER(vm.vend_nombre), UPPER(u.nombre || ' ' || u.apellidos)) >= p_threshold
    WHERE vm.status = 'pending_review'
      AND vm.movi_user_id IS NULL
      AND u.estado = 'activo'
    ORDER BY vm.id, sim_score DESC
  LOOP
    UPDATE sicas_vendor_user_mappings
    SET movi_user_id = rec.usuario_id,
        match_type = 'auto_fuzzy',
        confidence_score = rec.sim_score * 100,
        status = 'active',
        match_details = jsonb_build_object('method', 'auto_fuzzy_confirm', 'score', rec.sim_score, 'confirmed_at', NOW()),
        updated_at = NOW()
    WHERE id = rec.vendor_id;
    v_confirmed := v_confirmed + 1;

    UPDATE usuarios
    SET id_sicas = COALESCE(id_sicas, rec.vend_id),
        nombre_sicas = COALESCE(nombre_sicas, rec.vend_nombre),
        updated_at = NOW()
    WHERE id = rec.usuario_id;

    INSERT INTO vendor_mappings (source_type, source_value, movi_user_id, status, notes)
    VALUES (
      'name',
      LOWER(TRIM(REGEXP_REPLACE(TRANSLATE(rec.vend_nombre, 'ÁÉÍÓÚÜÑáéíóúüñ', 'AEIOUUNaeiouun'), '\s+', ' ', 'g'))),
      rec.usuario_id,
      'active',
      'Auto-confirmado por fuzzy match (score: ' || ROUND(rec.sim_score, 3) || ')'
    )
    ON CONFLICT (source_type, source_value) WHERE status = 'active'
    DO NOTHING;
    v_vm_created := v_vm_created + 1;

    IF rec.vend_id IS NOT NULL AND TRIM(rec.vend_id) != '' THEN
      INSERT INTO vendor_mappings (source_type, source_value, movi_user_id, status, notes)
      VALUES (
        'id',
        LOWER(TRIM(rec.vend_id)),
        rec.usuario_id,
        'active',
        'Auto-confirmado por fuzzy match ID (score: ' || ROUND(rec.sim_score, 3) || ')'
      )
      ON CONFLICT (source_type, source_value) WHERE status = 'active'
      DO NOTHING;
    END IF;

    BEGIN
      IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'sicas_mapeo_vendedor_usuario') THEN
        INSERT INTO sicas_mapeo_vendedor_usuario (id_sicas_vendedor, movi_user_id, mapped_at)
        VALUES (rec.vend_id, rec.usuario_id, NOW())
        ON CONFLICT (id_sicas_vendedor)
        DO UPDATE SET
          movi_user_id = EXCLUDED.movi_user_id,
          mapped_at = NOW(),
          updated_at = NOW();
      END IF;
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END LOOP;

  confirmed_count := v_confirmed;
  vendor_mappings_created := v_vm_created;
  RETURN NEXT;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.convert_express_lead_to_crm(p_lead_id uuid, p_notas text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_lead public.express_leads%ROWTYPE;
  v_contacto_id uuid; v_tarea_id uuid; v_tipo text;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'no_autenticado');
  END IF;

  SELECT * INTO v_lead FROM public.express_leads WHERE id = p_lead_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'reason', 'no_encontrado');
  END IF;

  IF v_lead.agente_asignado_id IS DISTINCT FROM v_uid THEN
    RETURN jsonb_build_object('success', false, 'reason', 'no_es_tuyo');
  END IF;

  IF v_lead.estado = 'convertido' AND v_lead.crm_contacto_id IS NOT NULL THEN
    RETURN jsonb_build_object('success', true, 'contacto_id', v_lead.crm_contacto_id, 'ya_convertido', true);
  END IF;

  v_tipo := COALESCE(NULLIF(trim(v_lead.tipo_seguro_interes), ''), 'seguro');

  SELECT id INTO v_contacto_id FROM public.crm_contactos
  WHERE creado_por = v_uid AND celular = v_lead.telefono
  ORDER BY fecha_creacion DESC NULLS LAST LIMIT 1;

  IF v_contacto_id IS NULL THEN
    INSERT INTO public.crm_contactos (
      tipo_contacto, nombre_completo, celular, email, estatus,
      fuente_origen, fuente_canal, tipo_lead, tipo_seguro, interes,
      notas_origen, etiquetas_segmentacion, campos_personalizados, creado_por
    ) VALUES (
      'Persona', COALESCE(NULLIF(trim(v_lead.nombre), ''), 'Lead seguros.express'),
      v_lead.telefono, v_lead.email, 'Prospecto',
      'seguros.express', 'seguros.express', 'cotizacion',
      v_lead.tipo_seguro_interes, v_lead.tipo_seguro_interes, p_notas,
      ARRAY['seguros-express', 'lead-' || v_tipo],
      jsonb_build_object('origen','seguros.express','express_lead_id',v_lead.id,
        'direccion_manual',v_lead.direccion_manual,'lat',v_lead.lat,'lng',v_lead.lng),
      v_uid
    ) RETURNING id INTO v_contacto_id;
  ELSE
    UPDATE public.crm_contactos
       SET tipo_seguro = COALESCE(tipo_seguro, v_lead.tipo_seguro_interes),
           interes = COALESCE(interes, v_lead.tipo_seguro_interes),
           notas_origen = COALESCE(notas_origen, p_notas), actualizado_en = now()
     WHERE id = v_contacto_id;
  END IF;

  INSERT INTO public.crm_tareas (
    contacto_id, descripcion, titulo, tipo_actividad, fecha_vencimiento,
    estatus, prioridad, creado_por, asignado_a, fuente, canal
  ) VALUES (
    v_contacto_id,
    format('Dar seguimiento al lead de %s de seguros.express', v_tipo),
    format('Seguimiento lead seguros.express — %s', v_tipo),
    'Llamada', now() + interval '1 day', 'Pendiente', 'Alta',
    v_uid, v_uid, 'seguros.express', 'seguros.express'
  ) RETURNING id INTO v_tarea_id;

  UPDATE public.express_leads
     SET estado = 'convertido', crm_contacto_id = v_contacto_id, updated_at = now()
   WHERE id = p_lead_id;

  RETURN jsonb_build_object('success', true, 'contacto_id', v_contacto_id, 'tarea_id', v_tarea_id);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.convert_lead_to_crm(p_lead_id uuid, p_nombre text DEFAULT NULL::text, p_celular text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_notas text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_lead RECORD;
v_user_id uuid := auth.uid();
v_contacto_id uuid;
v_tarea_id uuid;
v_nombre_final text;
v_producto text;
BEGIN
-- Check admin
IF NOT is_chava_admin() THEN
RAISE EXCEPTION 'Acceso denegado: solo administradores pueden convertir leads';
END IF;

-- Get lead
SELECT * INTO v_lead FROM chava_lead_signals WHERE id = p_lead_id;
IF NOT FOUND THEN
RAISE EXCEPTION 'Lead no encontrado';
END IF;

IF v_lead.estado = 'convertido' THEN
RAISE EXCEPTION 'Este lead ya fue convertido al CRM';
END IF;

-- Determine name from datos_capturados or params
v_nombre_final := COALESCE(
p_nombre,
v_lead.datos_capturados->>'nombre',
v_lead.datos_capturados->>'nombre_completo',
'Lead Chava AI'
);

v_producto := COALESCE(v_lead.producto, 'general');

-- Create CRM contact
INSERT INTO crm_contactos (
tipo_contacto,
nombre_completo,
celular,
email,
estatus,
fuente_origen,
etiquetas_segmentacion,
campos_personalizados,
creado_por
) VALUES (
'Persona',
v_nombre_final,
COALESCE(p_celular, v_lead.datos_capturados->>'telefono', v_lead.datos_capturados->>'celular', ''),
COALESCE(p_email, v_lead.datos_capturados->>'email', ''),
'Prospecto',
'Chava AI',
ARRAY['chava-ai', 'lead-' || v_producto],
jsonb_build_object(
'origen', 'chava_ai',
'calidad_lead', v_lead.calidad,
'intent', v_lead.intent_codigo,
'producto_interes', v_producto,
'datos_originales', v_lead.datos_capturados
),
v_user_id
)
RETURNING id INTO v_contacto_id;

-- Create CRM follow-up task
INSERT INTO crm_tareas (
contacto_id,
descripcion,
tipo_actividad,
fecha_vencimiento,
estatus,
prioridad,
completada,
creado_por,
asignado_a
) VALUES (
v_contacto_id,
'Seguimiento lead Chava AI: ' || v_nombre_final || ' - Interesado en ' || v_producto ||
CASE WHEN p_notas IS NOT NULL THEN E'\n\nNotas: ' || p_notas ELSE '' END,
'Llamada',
NOW() + interval '1 day',
'Pendiente',
CASE v_lead.calidad WHEN 'alta' THEN 'Alta' WHEN 'media' THEN 'Media' ELSE 'Baja' END,
false,
v_user_id,
v_user_id
)
RETURNING id INTO v_tarea_id;

-- Update lead signal
UPDATE chava_lead_signals SET
estado = 'convertido',
crm_contacto_id = v_contacto_id,
crm_tarea_id = v_tarea_id,
convertido_at = NOW(),
convertido_por = v_user_id,
updated_at = NOW()
WHERE id = p_lead_id;

RETURN jsonb_build_object(
'success', true,
'contacto_id', v_contacto_id,
'tarea_id', v_tarea_id,
'nombre', v_nombre_final
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.correo_liberado(p_user_id uuid)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT 'deleted-' || left(p_user_id::text, 8) || '@deleted.local';
$function$
;

CREATE OR REPLACE FUNCTION public.crear_ticket_cambio_bancario(p_usuario_id uuid, p_regimen_fiscal_nombre text DEFAULT NULL::text, p_banco text DEFAULT NULL::text, p_clabe text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_ticket_id uuid;
v_ticket_folio text;
v_estatus_nuevo_id uuid;
v_ticket_existente_id uuid;
v_instrucciones text;
v_usuario_nombre text;
v_usuario_apellidos text;
v_oficina_id uuid;
v_resultado jsonb;
BEGIN
-- Obtener datos del usuario
SELECT nombre, apellidos, oficina_id
INTO v_usuario_nombre, v_usuario_apellidos, v_oficina_id
FROM usuarios
WHERE id = p_usuario_id;

-- Obtener estatus "Nuevo"
SELECT id INTO v_estatus_nuevo_id
FROM ticket_estatus
WHERE nombre = 'Nuevo'
LIMIT 1;

IF v_estatus_nuevo_id IS NULL THEN
RAISE EXCEPTION 'No se encontró el estatus "Nuevo" para tickets';
END IF;

-- Construir descripción con los nuevos datos
v_instrucciones := E'CAMBIO DE INFORMACIÓN DE PAGO\n\n';

IF p_regimen_fiscal_nombre IS NOT NULL THEN
v_instrucciones := v_instrucciones || 'Régimen fiscal: ' || p_regimen_fiscal_nombre || E'\n';
END IF;

IF p_banco IS NOT NULL THEN
v_instrucciones := v_instrucciones || 'Banco (nuevo): ' || p_banco || E'\n';
END IF;

IF p_clabe IS NOT NULL THEN
v_instrucciones := v_instrucciones || 'CLABE (nuevo): ' || p_clabe || E'\n';
END IF;

v_instrucciones := v_instrucciones || E'\n⏱️ Este cambio tarda de 24 a 72 horas en aplicarse.';

-- Verificar si existe un ticket reciente de cambios bancarios (últimos 15 minutos)
SELECT id INTO v_ticket_existente_id
FROM tickets
WHERE agente_id = p_usuario_id
AND poliza = 'CAMBIOS BANCARIOS'
AND fecha_creacion >= (now() - interval '15 minutes')
AND cerrado_en IS NULL
ORDER BY fecha_creacion DESC
LIMIT 1;

IF v_ticket_existente_id IS NOT NULL THEN
-- Actualizar ticket existente
UPDATE tickets
SET
instrucciones = v_instrucciones,
ultima_modificacion = now(),
modificado_por = p_usuario_id
WHERE id = v_ticket_existente_id;

v_ticket_id := v_ticket_existente_id;

-- Obtener folio del ticket existente
SELECT folio INTO v_ticket_folio
FROM tickets
WHERE id = v_ticket_id;

-- Agregar comentario indicando actualización
INSERT INTO ticket_comentarios (ticket_id, usuario_id, mensaje)
VALUES (
v_ticket_id,
p_usuario_id,
'Información actualizada con nuevos datos de pago.'
);

v_resultado := jsonb_build_object(
'ticket_id', v_ticket_id,
'folio', v_ticket_folio,
'accion', 'actualizado',
'mensaje', 'Ticket de cambios bancarios actualizado'
);

ELSE
-- Crear nuevo ticket
INSERT INTO tickets (
tipo_tramite,
agente_id,
estatus_id,
prioridad,
poliza,
instrucciones,
creado_por,
fecha_creacion
)
VALUES (
'cambio_datos_pago',
p_usuario_id,
v_estatus_nuevo_id,
'Alta',
'CAMBIOS BANCARIOS',
v_instrucciones,
p_usuario_id,
now()
)
RETURNING id, folio INTO v_ticket_id, v_ticket_folio;

-- Enviar notificación in-app al usuario
PERFORM enviar_notificacion_completa(
'ticket_creado',
p_usuario_id,
jsonb_build_object(
'ticket_folio', v_ticket_folio,
'tipo_tramite', 'Cambio de datos bancarios'
)
);

-- Enviar notificación a administradores
PERFORM enviar_notificacion_completa(
'ticket_cambio_bancario_admin',
admin.id,
jsonb_build_object(
'ticket_folio', v_ticket_folio,
'usuario_nombre', v_usuario_nombre || ' ' || v_usuario_apellidos,
'usuario_id', p_usuario_id
)
)
FROM usuarios admin
WHERE admin.rol = 'Administrador' AND admin.estado = 'Activo';

v_resultado := jsonb_build_object(
'ticket_id', v_ticket_id,
'folio', v_ticket_folio,
'accion', 'creado',
'mensaje', 'Ticket de cambios bancarios creado exitosamente'
);
END IF;

RETURN v_resultado;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.create_all_sistema_campos(p_tipo_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  -- Campos fijos (siempre presentes, no movibles)
  PERFORM public.ensure_sistema_campo(p_tipo_id, 'area',                'Área',                     'area',                  -7, '{}'::jsonb, 'area');
  PERFORM public.ensure_sistema_campo(p_tipo_id, 'equipo',              'Equipo',                   'equipo',                -6, '{}'::jsonb, 'equipo');
  PERFORM public.ensure_sistema_campo(p_tipo_id, 'estatus_tramite',     'Estatus',                  'estatus',               -5,
    '{"opciones":[{"label":"Iniciado","slug":"iniciado","clasificacion":"inicio"},{"label":"Terminado","slug":"terminado","clasificacion":"terminacion"}]}'::jsonb,
    'estatus');
  PERFORM public.ensure_sistema_campo(p_tipo_id, 'agente_vendedor',     'Agente / Vendedor',        'agente_vendedor',       -4, '{}'::jsonb, 'agente_vendedor');
  PERFORM public.ensure_sistema_campo(p_tipo_id, 'oficina_jiro',        'Oficina Jiro',             'oficina_jiro',          -3, '{}'::jsonb, 'oficina_jiro');
  PERFORM public.ensure_sistema_campo(p_tipo_id, 'fecha_creacion',      'Fecha de Creación',        'fecha_creacion',        -2, '{}'::jsonb, 'fecha_creacion');
  PERFORM public.ensure_sistema_campo(p_tipo_id, 'fecha_finalizacion',  'Fecha de Finalización',    'fecha_finalizacion',    -1, '{}'::jsonb, 'fecha_finalizacion');
  PERFORM public.ensure_sistema_campo(p_tipo_id, 'creado_por',          'Trámite Creado Por',       'creado_por',             0, '{}'::jsonb, 'creado_por');
  -- Campos configurables (el admin puede reordenar, ocultar, marcar como obligatorio)
  PERFORM public.ensure_sistema_campo(p_tipo_id, 'asignado_a',          'Asignar a',                'asignado_a',            80, '{}'::jsonb, 'asignado_a');
  PERFORM public.ensure_sistema_campo(p_tipo_id, 'prioridad',           'Prioridad',                'prioridad',             85, '{}'::jsonb, 'prioridad');
  PERFORM public.ensure_sistema_campo(p_tipo_id, 'descripcion',         'Descripción / Notas',      'descripcion',           100,'{}'::jsonb, 'descripcion');
  PERFORM public.ensure_sistema_campo(p_tipo_id, 'fecha_promesa_entrega','Fecha Promesa de Entrega','fecha_promesa_entrega', 110,'{}'::jsonb, 'fecha_promesa_entrega');
  PERFORM public.ensure_sistema_campo(p_tipo_id, 'archivos_adjuntos',   'Archivos Adjuntos',        'archivos_adjuntos',     120,'{}'::jsonb, 'archivos_adjuntos');
END;
$function$
;

CREATE OR REPLACE FUNCTION public.create_auth_user(user_email text, user_password text, user_nombre text, user_apellidos text, user_rol text, user_oficina_id uuid, user_puesto text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  new_user_id uuid;
  encrypted_pw text;
  username_base text;
  final_username text;
  counter int := 0;
BEGIN
  new_user_id := gen_random_uuid();
  encrypted_pw := crypt(user_password, gen_salt('bf'));
  username_base := split_part(user_email, '@', 1);
  final_username := username_base;
  
  WHILE EXISTS (SELECT 1 FROM usuarios WHERE username = final_username) LOOP
    counter := counter + 1;
    final_username := username_base || counter::text;
  END LOOP;
  
  -- Insertar en auth.users SIN confirmed_at (es una columna generada)
  INSERT INTO auth.users (
    id,
    instance_id,
    email,
    encrypted_password,
    email_confirmed_at,
    aud,
    role,
    raw_app_meta_data,
    raw_user_meta_data,
    is_super_admin,
    created_at,
    updated_at,
    is_sso_user,
    is_anonymous
  ) VALUES (
    new_user_id,
    '00000000-0000-0000-0000-000000000000',
    user_email,
    encrypted_pw,
    now(),
    'authenticated',
    'authenticated',
    '{"provider":"email","providers":["email"]}'::jsonb,
    '{}'::jsonb,
    false,
    now(),
    now(),
    false,
    false
  );
  
  -- Insertar identity
  INSERT INTO auth.identities (
    id,
    user_id,
    identity_data,
    provider,
    provider_id,
    last_sign_in_at,
    created_at,
    updated_at
  ) VALUES (
    gen_random_uuid(),
    new_user_id,
    jsonb_build_object(
      'sub', new_user_id::text,
      'email', user_email,
      'email_verified', true,
      'phone_verified', false
    ),
    'email',
    new_user_id::text,
    now(),
    now(),
    now()
  );
  
  -- Insertar en usuarios
  INSERT INTO usuarios (
    id,
    username,
    nombre,
    apellidos,
    rol,
    email_laboral,
    puesto,
    oficina_id,
    activo,
    estado
  ) VALUES (
    new_user_id,
    final_username,
    user_nombre,
    user_apellidos,
    user_rol,
    user_email,
    user_puesto,
    user_oficina_id,
    true,
    'activo'
  );
  
  RETURN new_user_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.create_crm_lead_and_task_from_public_form(p_agent_id uuid, p_office_id uuid DEFAULT NULL::uuid, p_client_name text DEFAULT NULL::text, p_client_phone text DEFAULT NULL::text, p_client_whatsapp text DEFAULT NULL::text, p_client_email text DEFAULT NULL::text, p_form_type text DEFAULT NULL::text, p_form_title text DEFAULT NULL::text, p_quote_form_id uuid DEFAULT NULL::uuid, p_ticket_id uuid DEFAULT NULL::uuid, p_shared_link_id uuid DEFAULT NULL::uuid, p_public_submission_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_lead_id uuid;
v_task_id uuid;
v_note_id uuid;
v_is_new_lead boolean := true;
v_existing_lead record;
v_due_date timestamptz;
v_task_title text;
v_task_description text;
v_lead_name text;
v_celular text;
v_has_contact boolean;
v_note_content text;
BEGIN
-- STEP 1: Prepare data
v_lead_name := TRIM(COALESCE(p_client_name, 'Sin nombre'));
v_celular := COALESCE(NULLIF(TRIM(p_client_phone), ''), NULLIF(TRIM(p_client_whatsapp), ''), '');
v_has_contact := (NULLIF(TRIM(p_client_phone), '') IS NOT NULL)
OR (NULLIF(TRIM(p_client_whatsapp), '') IS NOT NULL)
OR (NULLIF(TRIM(p_client_email), '') IS NOT NULL);

-- Calculate due date: next business day at 10:00 AM local time
v_due_date := (now() AT TIME ZONE 'America/Mexico_City' + interval '1 day');
IF EXTRACT(DOW FROM v_due_date) = 6 THEN
v_due_date := v_due_date + interval '2 days';
ELSIF EXTRACT(DOW FROM v_due_date) = 0 THEN
v_due_date := v_due_date + interval '1 day';
END IF;
v_due_date := date_trunc('day', v_due_date) + interval '10 hours';
v_due_date := v_due_date AT TIME ZONE 'America/Mexico_City';

-- STEP 2: Check for duplicate lead
IF v_has_contact THEN
SELECT id, estatus INTO v_existing_lead
FROM crm_contactos
WHERE creado_por = p_agent_id
AND (
(NULLIF(TRIM(p_client_email), '') IS NOT NULL AND email = TRIM(p_client_email))
OR (NULLIF(TRIM(p_client_phone), '') IS NOT NULL AND celular = TRIM(p_client_phone))
OR (NULLIF(TRIM(p_client_whatsapp), '') IS NOT NULL AND whatsapp = TRIM(p_client_whatsapp))
OR (NULLIF(TRIM(p_client_phone), '') IS NOT NULL AND whatsapp = TRIM(p_client_phone))
OR (NULLIF(TRIM(p_client_whatsapp), '') IS NOT NULL AND celular = TRIM(p_client_whatsapp))
)
ORDER BY fecha_creacion DESC
LIMIT 1;
END IF;

-- STEP 3: Create or update lead
IF v_existing_lead.id IS NOT NULL THEN
v_lead_id := v_existing_lead.id;
v_is_new_lead := false;

IF v_existing_lead.estatus IN ('Perdido') THEN
UPDATE crm_contactos
SET estatus = 'Prospecto', actualizado_en = now()
WHERE id = v_lead_id;
END IF;

UPDATE crm_contactos
SET quote_form_id = COALESCE(p_quote_form_id, quote_form_id),
ticket_id = COALESCE(p_ticket_id, ticket_id),
shared_link_id = COALESCE(p_shared_link_id, shared_link_id),
public_submission_id = COALESCE(p_public_submission_id, public_submission_id),
tipo_seguro = COALESCE(p_form_type, tipo_seguro),
interes = COALESCE(p_form_title, interes),
actualizado_en = now()
WHERE id = v_lead_id;

v_note_content := 'Nueva solicitud de cotizacion recibida desde formulario publico.' || chr(10)
|| 'Tipo de seguro: ' || COALESCE(p_form_title, p_form_type, 'No especificado') || chr(10)
|| 'Tramite relacionado: ' || COALESCE(p_ticket_id::text, 'N/A');

IF v_existing_lead.estatus IN ('Perdido') THEN
v_note_content := 'Lead reactivado por nuevo formulario publico recibido.' || chr(10) || v_note_content;
END IF;

INSERT INTO crm_notas (contacto_id, contenido, creado_por)
VALUES (v_lead_id, v_note_content, p_agent_id)
RETURNING id INTO v_note_id;

ELSE
INSERT INTO crm_contactos (
tipo_contacto, nombre_completo, celular, email, whatsapp,
estatus, fuente_origen, fuente_canal, tipo_lead, tipo_seguro, interes,
notas_origen, creado_por, quote_form_id, ticket_id, shared_link_id,
public_submission_id, contacto_incompleto, etiquetas_segmentacion, metadata_json
) VALUES (
'Persona',
v_lead_name,
v_celular,
NULLIF(TRIM(p_client_email), ''),
NULLIF(TRIM(p_client_whatsapp), ''),
'Prospecto',
'formulario_publico',
'link_publico',
'cotizacion',
p_form_type,
p_form_title,
p_notes,
p_agent_id,
p_quote_form_id,
p_ticket_id,
p_shared_link_id,
p_public_submission_id,
NOT v_has_contact,
CASE WHEN NOT v_has_contact THEN ARRAY['contacto_incompleto'] ELSE ARRAY['formulario_publico'] END,
jsonb_build_object(
'source', 'formulario_compartido',
'channel', 'link_publico',
'form_type', p_form_type,
'created_at', now()
)
)
RETURNING id INTO v_lead_id;

v_note_content := 'Nueva solicitud de cotizacion recibida desde formulario publico.' || chr(10)
|| 'Tipo de seguro: ' || COALESCE(p_form_title, p_form_type, 'No especificado') || chr(10)
|| 'Cliente: ' || v_lead_name || chr(10)
|| 'Tramite relacionado: ' || COALESCE(p_ticket_id::text, 'N/A');

IF NOT v_has_contact THEN
v_note_content := v_note_content || chr(10) || chr(10)
|| 'ATENCION: Este lead no tiene datos de contacto completos. Verificar informacion.';
END IF;

INSERT INTO crm_notas (contacto_id, contenido, creado_por)
VALUES (v_lead_id, v_note_content, p_agent_id)
RETURNING id INTO v_note_id;
END IF;

-- STEP 4: Create follow-up task
v_task_title := 'Seguimiento: ' || COALESCE(p_form_title, p_form_type, 'Formulario publico') || ' - ' || v_lead_name;

v_task_description := 'Se recibio una nueva solicitud de cotizacion desde un formulario publico compartido.' || chr(10) || chr(10)
|| 'Cliente: ' || v_lead_name || chr(10)
|| 'Seguro: ' || COALESCE(p_form_title, p_form_type, 'No especificado') || chr(10)
|| 'Origen: Link publico' || chr(10) || chr(10)
|| 'Revisar informacion, contactar al cliente y continuar seguimiento.';

INSERT INTO crm_tareas (
contacto_id, titulo, descripcion, tipo_actividad,
fecha_vencimiento, estatus, prioridad, creado_por, asignado_a,
quote_form_id, ticket_id, shared_link_id, public_submission_id, metadata_json
) VALUES (
v_lead_id,
v_task_title,
v_task_description,
'Llamada',
v_due_date,
'Pendiente',
'Alta',
p_agent_id,
p_agent_id,
p_quote_form_id,
p_ticket_id,
p_shared_link_id,
p_public_submission_id,
jsonb_build_object(
'auto_created', true,
'source', 'formulario_compartido',
'form_type', p_form_type,
'is_new_lead', v_is_new_lead
)
)
RETURNING id INTO v_task_id;

-- STEP 5: Add ticket history entries (if ticket exists)
IF p_ticket_id IS NOT NULL THEN
INSERT INTO ticket_historial (ticket_id, accion, descripcion, usuario_id)
VALUES (
p_ticket_id,
'nota',
CASE WHEN v_is_new_lead 
THEN 'Lead creado automaticamente en Mi CRM desde formulario publico.'
ELSE 'Lead existente relacionado automaticamente desde formulario publico.'
END,
p_agent_id
);

INSERT INTO ticket_historial (ticket_id, accion, descripcion, usuario_id)
VALUES (
p_ticket_id,
'nota',
'Tarea de seguimiento creada automaticamente en Mi CRM.',
p_agent_id
);
END IF;

-- STEP 6: Return result
RETURN json_build_object(
'lead_id', v_lead_id,
'task_id', v_task_id,
'note_id', v_note_id,
'is_new_lead', v_is_new_lead,
'due_date', v_due_date
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.create_public_agenda_booking(p_event_type_id uuid, p_start_at timestamp with time zone, p_guest_name text, p_guest_email text, p_guest_phone text, p_location_type text)
 RETURNS TABLE(booking_id uuid, meeting_url text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$declare v_event agenda_event_types%rowtype;v_slot record;v_id uuid:=gen_random_uuid();v_url text;begin if length(trim(p_guest_name))<2 or p_guest_email!~*'^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'Datos del invitado inválidos';end if;perform pg_advisory_xact_lock(hashtext(p_event_type_id::text));select * into v_event from agenda_event_types where id=p_event_type_id and is_active;if not found or not(v_event.allowed_locations?p_location_type) then raise exception 'Tipo de cita o modalidad inválida';end if;select * into v_slot from get_agenda_available_slots(p_event_type_id,(p_start_at at time zone(select timezone from agenda_calendars where id=v_event.calendar_id))::date) where start_at=p_start_at;if not found then raise exception 'El horario ya no está disponible';end if;if p_location_type='jitsi' then v_url:='https://meet.jit.si/movi-'||replace(v_id::text,'-','');end if;insert into agenda_bookings(id,event_type_id,guest_name,guest_email,guest_phone,location_type,meeting_url,start_at,end_at) values(v_id,p_event_type_id,trim(p_guest_name),lower(trim(p_guest_email)),nullif(trim(p_guest_phone),''),p_location_type,v_url,v_slot.start_at,v_slot.end_at);booking_id:=v_id;meeting_url:=v_url;return next;end$function$
;

CREATE OR REPLACE FUNCTION public.create_user_with_password(user_email text, user_password text, user_nombre text, user_apellidos text, user_rol text, user_oficina_id uuid DEFAULT NULL::uuid, user_puesto text DEFAULT ''::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  new_user_id uuid;
  encrypted_pw text;
  base_username text;
  final_username text;
  counter int := 0;
BEGIN
  new_user_id := gen_random_uuid();
  encrypted_pw := crypt(user_password, gen_salt('bf'));
  base_username := split_part(user_email, '@', 1);
  final_username := base_username;
  
  -- Asegurar que el username sea único
  WHILE EXISTS (SELECT 1 FROM usuarios WHERE username = final_username) LOOP
    counter := counter + 1;
    final_username := base_username || counter::text;
  END LOOP;
  
  -- Insertar en auth.users
  INSERT INTO auth.users (
    id,
    instance_id,
    email,
    encrypted_password,
    email_confirmed_at,
    created_at,
    updated_at,
    aud,
    role
  ) VALUES (
    new_user_id,
    '00000000-0000-0000-0000-000000000000',
    user_email,
    encrypted_pw,
    now(),
    now(),
    now(),
    'authenticated',
    'authenticated'
  );
  
  -- Insertar en tabla usuarios
  INSERT INTO usuarios (
    id,
    username,
    nombre,
    apellidos,
    rol,
    email_laboral,
    puesto,
    oficina_id,
    activo,
    estado
  ) VALUES (
    new_user_id,
    final_username,
    user_nombre,
    user_apellidos,
    user_rol,
    user_email,
    user_puesto,
    user_oficina_id,
    true,
    'activo'
  );
  
  RETURN new_user_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.crm_create_board(p_name text, p_owner_office_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_board_id uuid;
  v_user_id uuid := (select auth.uid());
  v_owner_office_id uuid;
  v_board_name text := btrim(coalesce(p_name, ''));
begin
  if v_user_id is null then
    raise exception 'Debes iniciar sesión para crear un tablero';
  end if;

  if char_length(v_board_name) = 0 or char_length(v_board_name) > 120 then
    raise exception 'El nombre del tablero debe tener entre 1 y 120 caracteres';
  end if;

  select u.oficina_id
    into v_owner_office_id
  from public.usuarios u
  where u.id = v_user_id
    and u.activo = true
    and (u.estado is null or lower(u.estado) = 'activo');

  if not found then
    raise exception 'Tu usuario no está activo';
  end if;

  -- La oficina se toma del perfil autenticado. El parámetro se conserva por
  -- compatibilidad con clientes ya publicados, pero no autoriza suplantarla.
  insert into public.crm_boards (name, owner_user_id, owner_office_id)
  values (v_board_name, v_user_id, v_owner_office_id)
  returning id into v_board_id;

  insert into public.crm_board_members (board_id, user_id, member_role, added_by)
  values (v_board_id, v_user_id, 'owner', v_user_id);

  insert into public.crm_board_activity (board_id, actor_user_id, action, meta)
  values (v_board_id, v_user_id, 'board_created', jsonb_build_object('name', v_board_name));

  return v_board_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.crm_get_board_members(p_board_id uuid)
 RETURNS TABLE(member_id uuid, user_id uuid, user_name text, user_office text, user_role_global text, member_role text, added_by_name text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
BEGIN
RETURN QUERY
SELECT
bm.id AS member_id,
bm.user_id,
CONCAT(u.nombre, ' ', u.apellidos) AS user_name,
o.nombre AS user_office,
u.rol AS user_role_global,
bm.member_role,
CONCAT(adder.nombre, ' ', adder.apellidos) AS added_by_name,
bm.created_at
FROM crm_board_members bm
INNER JOIN usuarios u ON u.id = bm.user_id
LEFT JOIN oficinas o ON o.id = u.oficina_id
LEFT JOIN usuarios adder ON adder.id = bm.added_by
WHERE bm.board_id = p_board_id
ORDER BY
CASE bm.member_role
WHEN 'owner' THEN 1
WHEN 'admin' THEN 2
WHEN 'editor' THEN 3
WHEN 'viewer' THEN 4
END,
u.nombre;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.crm_invite_member(p_board_id uuid, p_identifier text, p_member_role text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := (select auth.uid());
  v_identifier text := btrim(coalesce(p_identifier, ''));
  v_phone text := regexp_replace(btrim(coalesce(p_identifier, '')), '\D', '', 'g');
  v_is_email boolean;
  v_is_phone boolean;
  v_target_ids uuid[];
  v_target_user_id uuid;
  v_member_id uuid;
begin
  if v_user_id is null then
    raise exception 'Debes iniciar sesión para invitar miembros';
  end if;

  if p_member_role not in ('admin', 'editor', 'viewer') then
    raise exception 'Rol inválido. Debe ser: admin, editor o viewer';
  end if;

  if not exists (
    select 1
    from public.crm_boards b
    join public.crm_board_members bm
      on bm.board_id = b.id
     and bm.user_id = v_user_id
     and bm.member_role in ('owner', 'admin')
    where b.id = p_board_id
      and b.deleted_at is null
  ) then
    raise exception 'Solo los propietarios y administradores del tablero pueden invitar miembros';
  end if;

  v_is_email := v_identifier ~* '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$';
  v_is_phone := v_identifier ~ '^[0-9+() .-]+$'
    and char_length(v_phone) between 7 and 15;

  if not v_is_email and not v_is_phone then
    raise exception 'Escribe un email laboral completo o un teléfono laboral válido';
  end if;

  select array_agg(u.id order by u.id::text)
    into v_target_ids
  from public.usuarios u
  where u.activo = true
    and (u.estado is null or lower(u.estado) = 'activo')
    and (
      (v_is_email and lower(btrim(coalesce(u.email_laboral, ''))) = lower(v_identifier))
      or
      (v_is_phone and regexp_replace(coalesce(u.celular_laboral, ''), '\D', '', 'g') = v_phone)
    );

  if coalesce(cardinality(v_target_ids), 0) = 0 then
    raise exception 'No se encontró un usuario activo con ese email o teléfono laboral';
  end if;

  if cardinality(v_target_ids) > 1 then
    raise exception 'Ese dato laboral está asociado a más de un usuario; solicita su corrección antes de invitar';
  end if;

  v_target_user_id := v_target_ids[1];

  if v_target_user_id = v_user_id then
    raise exception 'Ya eres miembro de este tablero';
  end if;

  insert into public.crm_board_members (board_id, user_id, member_role, added_by)
  values (p_board_id, v_target_user_id, p_member_role, v_user_id)
  on conflict (board_id, user_id)
  do update set member_role = excluded.member_role
  returning id into v_member_id;

  insert into public.crm_board_activity (board_id, actor_user_id, action, meta)
  values (
    p_board_id,
    v_user_id,
    'member_invited',
    jsonb_build_object('user_id', v_target_user_id, 'role', p_member_role)
  );

  return v_member_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.crm_list_boards_for_user()
 RETURNS TABLE(board_id uuid, board_name text, is_owner boolean, my_role text, owner_name text, owner_office text, members_count bigint, created_at timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
BEGIN
RETURN QUERY
SELECT
b.id AS board_id,
b.name AS board_name,
(b.owner_user_id = auth.uid()) AS is_owner,
COALESCE(bm.member_role, 'owner') AS my_role,
CONCAT(u.nombre, ' ', u.apellidos) AS owner_name,
o.nombre AS owner_office,
(SELECT COUNT(*) FROM crm_board_members cbm WHERE cbm.board_id = b.id) AS members_count,
b.created_at,
b.updated_at
FROM crm_boards b
LEFT JOIN crm_board_members bm ON bm.board_id = b.id AND bm.user_id = auth.uid()
LEFT JOIN usuarios u ON u.id = b.owner_user_id
LEFT JOIN oficinas o ON o.id = b.owner_office_id
WHERE
b.deleted_at IS NULL
AND (
b.owner_user_id = auth.uid()
OR EXISTS (
SELECT 1 FROM crm_board_members cbm2
WHERE cbm2.board_id = b.id
AND cbm2.user_id = auth.uid()
)
)
ORDER BY b.updated_at DESC;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.crm_remove_member(p_board_id uuid, p_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_my_board_role text;
BEGIN
-- Validar que el caller es owner o admin
SELECT member_role INTO v_my_board_role
FROM crm_board_members
WHERE board_id = p_board_id AND user_id = auth.uid();

IF v_my_board_role NOT IN ('owner', 'admin') THEN
RAISE EXCEPTION 'Solo owners y admins pueden remover miembros';
END IF;

-- No se puede remover al owner
IF EXISTS (
SELECT 1 FROM crm_board_members
WHERE board_id = p_board_id AND user_id = p_user_id AND member_role = 'owner'
) THEN
RAISE EXCEPTION 'No se puede remover al owner del tablero';
END IF;

-- Remover miembro
DELETE FROM crm_board_members
WHERE board_id = p_board_id AND user_id = p_user_id;

-- Registrar actividad
INSERT INTO crm_board_activity (board_id, actor_user_id, action, meta)
VALUES (
p_board_id,
auth.uid(),
'member_removed',
jsonb_build_object('user_id', p_user_id)
);

RETURN true;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.crm_search_shareable_users(p_board_id uuid, p_query text)
 RETURNS TABLE(id uuid, nombre_completo text, oficina_nombre text, rol text, avatar_url text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := (select auth.uid());
  v_query text := btrim(coalesce(p_query, ''));
  v_phone text := regexp_replace(btrim(coalesce(p_query, '')), '\D', '', 'g');
  v_is_email boolean;
  v_is_phone boolean;
begin
  if v_user_id is null then
    raise exception 'Debes iniciar sesión para buscar usuarios';
  end if;

  v_is_email := v_query ~* '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$';
  v_is_phone := v_query ~ '^[0-9+() .-]+$'
    and char_length(v_phone) between 7 and 15;

  if not v_is_email and not v_is_phone then
    raise exception 'Escribe un email laboral completo o un teléfono laboral válido';
  end if;

  if not exists (
    select 1
    from public.crm_boards b
    join public.crm_board_members bm
      on bm.board_id = b.id
     and bm.user_id = v_user_id
     and bm.member_role in ('owner', 'admin')
    where b.id = p_board_id
      and b.deleted_at is null
  ) then
    raise exception 'Solo los propietarios y administradores del tablero pueden buscar invitados';
  end if;

  return query
  select
    u.id,
    btrim(concat_ws(' ', u.nombre, u.apellidos)) as nombre_completo,
    coalesce(o.nombre, 'Sin oficina') as oficina_nombre,
    u.rol,
    u.imagen_perfil_url as avatar_url
  from public.usuarios u
  left join public.oficinas o on o.id = u.oficina_id
  where u.id <> v_user_id
    and u.activo = true
    and (u.estado is null or lower(u.estado) = 'activo')
    and not exists (
      select 1
      from public.crm_board_members existing_member
      where existing_member.board_id = p_board_id
        and existing_member.user_id = u.id
    )
    and (
      (v_is_email and lower(btrim(coalesce(u.email_laboral, ''))) = lower(v_query))
      or
      (v_is_phone and regexp_replace(coalesce(u.celular_laboral, ''), '\D', '', 'g') = v_phone)
    )
  order by u.nombre, u.apellidos
  limit 2;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.crm_update_member_role(p_board_id uuid, p_user_id uuid, p_new_role text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_my_board_role text;
BEGIN
-- Validar que el caller es owner o admin
SELECT member_role INTO v_my_board_role
FROM crm_board_members
WHERE board_id = p_board_id AND user_id = auth.uid();

IF v_my_board_role NOT IN ('owner', 'admin') THEN
RAISE EXCEPTION 'Solo owners y admins pueden cambiar roles';
END IF;

-- No se puede cambiar el rol del owner
IF EXISTS (
SELECT 1 FROM crm_board_members
WHERE board_id = p_board_id AND user_id = p_user_id AND member_role = 'owner'
) THEN
RAISE EXCEPTION 'No se puede cambiar el rol del owner';
END IF;

-- Validar rol válido
IF p_new_role NOT IN ('admin', 'editor', 'viewer') THEN
RAISE EXCEPTION 'Rol inválido';
END IF;

-- Actualizar rol
UPDATE crm_board_members
SET member_role = p_new_role
WHERE board_id = p_board_id AND user_id = p_user_id;

-- Registrar actividad
INSERT INTO crm_board_activity (board_id, actor_user_id, action, meta)
VALUES (
p_board_id,
auth.uid(),
'member_role_updated',
jsonb_build_object('user_id', p_user_id, 'new_role', p_new_role)
);

RETURN true;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.current_user_is_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM usuarios
    WHERE id = auth.uid()
    AND rol = 'Administrador'
  );
$function$
;

CREATE OR REPLACE FUNCTION public.deactivate_plantilla(plantilla_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
user_role text;
BEGIN
-- Get user role from usuarios table
SELECT rol INTO user_role
FROM usuarios
WHERE id = auth.uid();

-- Check if user is admin
IF user_role != 'Administrador' THEN
RAISE EXCEPTION 'Solo los administradores pueden desactivar plantillas';
END IF;

-- Update plantilla
UPDATE publicidad_plantillas
SET activa = false
WHERE id = plantilla_id;

RETURN true;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.debug_storage_permissions(p_user_id uuid, p_bucket text)
 RETURNS TABLE(check_type text, passed boolean, details text)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
-- Check 1: Usuario existe y está activo
RETURN QUERY
SELECT 
'Usuario activo'::text,
EXISTS (
SELECT 1 FROM usuarios WHERE id = p_user_id AND estado = 'activo'
),
COALESCE(
(SELECT rol || ' - ' || email_laboral FROM usuarios WHERE id = p_user_id),
'Usuario no encontrado'
);

-- Check 2: Es Administrador
RETURN QUERY
SELECT 
'Es Administrador'::text,
EXISTS (
SELECT 1 FROM usuarios
WHERE id = p_user_id AND rol = 'Administrador' AND estado = 'activo'
),
COALESCE(
(SELECT rol FROM usuarios WHERE id = p_user_id),
'N/A'
);

-- Check 3: Tiene permiso en seguros_education
RETURN QUERY
SELECT 
'Tiene permiso seguros_education'::text,
EXISTS (
SELECT 1 
FROM usuarios u
JOIN permisos_adicionales_gerente pag ON pag.usuario_id = u.id
JOIN modulos_sistema ms ON ms.id = pag.modulo_id
WHERE u.id = p_user_id
AND ms.codigo = 'seguros_education'
AND ms.activo = true
),
COALESCE(
(SELECT STRING_AGG(ms.codigo, ', ')
FROM permisos_adicionales_gerente pag
JOIN modulos_sistema ms ON ms.id = pag.modulo_id
WHERE pag.usuario_id = p_user_id),
'Sin permisos adicionales'
);

-- Check 4: Debería pasar la política del bucket
RETURN QUERY
SELECT 
'Debería poder subir a ' || p_bucket,
(
EXISTS (
SELECT 1 FROM usuarios
WHERE id = p_user_id AND rol = 'Administrador' AND estado = 'activo'
)
OR
EXISTS (
SELECT 1 
FROM usuarios u
JOIN permisos_adicionales_gerente pag ON pag.usuario_id = u.id
JOIN modulos_sistema ms ON ms.id = pag.modulo_id
WHERE u.id = p_user_id
AND u.rol = 'Gerente'
AND u.estado = 'activo'
AND ms.codigo = 'seguros_education'
AND ms.activo = true
)
),
'Combinación de checks anteriores';
END;
$function$
;

CREATE OR REPLACE FUNCTION public.decrementar_stock(p_producto_id uuid, p_cantidad integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
UPDATE store_productos
SET stock = GREATEST(0, stock - p_cantidad)
WHERE id = p_producto_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.delete_import_batch(p_batch_id uuid)
 RETURNS TABLE(success boolean, documents_deleted integer, error text)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_documents_deleted INTEGER := 0;
v_user_role TEXT;
BEGIN
-- Verificar que el usuario es administrador
SELECT rol INTO v_user_role
FROM usuarios
WHERE id = auth.uid();

IF v_user_role IS NULL OR v_user_role != 'Administrador' THEN
RETURN QUERY SELECT false, 0, 'No tienes permisos para eliminar batches de importación'::TEXT;
RETURN;
END IF;

-- Verificar que el batch existe (usando el nombre correcto de tabla)
IF NOT EXISTS (
SELECT 1 FROM document_import_batches WHERE id = p_batch_id
) THEN
RETURN QUERY SELECT false, 0, 'El batch no existe'::TEXT;
RETURN;
END IF;

-- Eliminar todos los documentos asociados al batch
DELETE FROM imported_documents
WHERE batch_id = p_batch_id;

GET DIAGNOSTICS v_documents_deleted = ROW_COUNT;

-- Eliminar el batch (usando el nombre correcto de tabla)
DELETE FROM document_import_batches
WHERE id = p_batch_id;

-- Verificar que el batch fue eliminado
IF NOT FOUND THEN
RETURN QUERY SELECT false, 0, 'Error al eliminar el batch'::TEXT;
RETURN;
END IF;

RETURN QUERY SELECT true, v_documents_deleted, NULL::TEXT;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.derive_agent_slug(p_user_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
v_user record;
v_slug text;
BEGIN
SELECT web_slug, nombre, apellidos
INTO v_user
FROM usuarios
WHERE id = p_user_id;

IF v_user IS NULL THEN
RETURN 'agente';
END IF;

-- Use web_slug if available
IF v_user.web_slug IS NOT NULL AND v_user.web_slug != '' THEN
RETURN v_user.web_slug;
END IF;

-- Derive from name
v_slug := lower(COALESCE(v_user.nombre, '') || COALESCE(v_user.apellidos, ''));
v_slug := regexp_replace(v_slug, '[^a-z0-9]', '', 'g');
IF length(v_slug) > 12 THEN
v_slug := substring(v_slug from 1 for 12);
END IF;
IF v_slug = '' THEN
v_slug := 'agente';
END IF;

RETURN v_slug;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.detect_sicas_cross_sell(p_usuario_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_created integer := 0;
v_vendor_id text;
v_oficina_id uuid;
BEGIN
-- Use the same helper as all other SICAS functions
v_vendor_id := get_sicas_user_vend_id(p_usuario_id);

SELECT oficina_id INTO v_oficina_id FROM usuarios WHERE id = p_usuario_id;

IF v_vendor_id IS NULL THEN
RETURN jsonb_build_object('success', false, 'error', 'No vendor mapping');
END IF;

-- Clear old dismissed/converted opportunities older than 90 days
DELETE FROM sicas_cross_sell_opportunities
WHERE usuario_id = p_usuario_id
AND status IN ('dismissed', 'converted')
AND updated_at < now() - interval '90 days';

-- Rule: Auto sin GMM
INSERT INTO sicas_cross_sell_opportunities (
usuario_id, sicas_vendor_id, oficina_id, customer_profile_id, client_name,
opportunity_type, current_products, suggested_product, priority, description,
recommended_message, premium_current
)
SELECT
p_usuario_id, v_vendor_id, v_oficina_id, cp.id, cp.client_name,
'auto_sin_gmm', cp.ramos_activos, 'Gastos Medicos Mayores', 'medium',
'Cliente con Auto activo sin GMM. Puede ser candidato para proteccion familiar.',
'Hola ' || split_part(cp.client_name, ' ', 1) || ', te escribo porque vi que tienes tu seguro de Auto con nosotros. Me gustaria platicarte sobre opciones de Gastos Medicos Mayores para complementar tu proteccion.',
cp.total_premium_active
FROM sicas_customer_profiles cp
WHERE cp.usuario_id = p_usuario_id
AND cp.total_policies_active > 0
AND ('AUTOS' = ANY(cp.ramos_activos) OR 'AUTOMOVILES' = ANY(cp.ramos_activos))
AND NOT ('GMM' = ANY(cp.ramos_activos) OR 'GASTOS MEDICOS' = ANY(cp.ramos_activos) OR 'GASTOS MEDICOS MAYORES' = ANY(cp.ramos_activos))
AND NOT EXISTS (
SELECT 1 FROM sicas_cross_sell_opportunities o
WHERE o.usuario_id = p_usuario_id AND o.customer_profile_id = cp.id AND o.opportunity_type = 'auto_sin_gmm'
AND o.status NOT IN ('dismissed', 'converted')
);
GET DIAGNOSTICS v_created = ROW_COUNT;

-- Rule: Single policy client
INSERT INTO sicas_cross_sell_opportunities (
usuario_id, sicas_vendor_id, oficina_id, customer_profile_id, client_name,
opportunity_type, current_products, suggested_product, priority, description,
recommended_message, premium_current
)
SELECT
p_usuario_id, v_vendor_id, v_oficina_id, cp.id, cp.client_name,
'single_policy', cp.ramos_activos, 'Venta cruzada', 'low',
'Cliente con una sola poliza. Puede ser candidato a venta cruzada.',
'Hola ' || split_part(cp.client_name, ' ', 1) || ', me gustaria platicarte sobre opciones adicionales de proteccion que podrian complementar tu seguro actual.',
cp.total_premium_active
FROM sicas_customer_profiles cp
WHERE cp.usuario_id = p_usuario_id
AND cp.total_policies_active = 1
AND NOT EXISTS (
SELECT 1 FROM sicas_cross_sell_opportunities o
WHERE o.usuario_id = p_usuario_id AND o.customer_profile_id = cp.id AND o.opportunity_type = 'single_policy'
AND o.status NOT IN ('dismissed', 'converted')
);

-- Rule: High-value client
INSERT INTO sicas_cross_sell_opportunities (
usuario_id, sicas_vendor_id, oficina_id, customer_profile_id, client_name,
opportunity_type, current_products, suggested_product, priority, description,
recommended_message, premium_current
)
SELECT
p_usuario_id, v_vendor_id, v_oficina_id, cp.id, cp.client_name,
'high_value_client', cp.ramos_activos, 'Seguimiento prioritario', 'high',
'Cliente de alta prima. Conviene darle seguimiento prioritario.',
'Hola ' || split_part(cp.client_name, ' ', 1) || ', como tu asesor me gustaria revisar contigo tus coberturas actuales para asegurarme de que tengas la mejor proteccion posible.',
cp.total_premium_active
FROM sicas_customer_profiles cp
WHERE cp.usuario_id = p_usuario_id
AND cp.is_high_value = true
AND cp.total_policies_active >= 2
AND NOT EXISTS (
SELECT 1 FROM sicas_cross_sell_opportunities o
WHERE o.usuario_id = p_usuario_id AND o.customer_profile_id = cp.id AND o.opportunity_type = 'high_value_client'
AND o.status NOT IN ('dismissed', 'converted')
);

-- Rule: Recoverable policy
INSERT INTO sicas_cross_sell_opportunities (
usuario_id, sicas_vendor_id, oficina_id, customer_profile_id, client_name,
opportunity_type, current_products, suggested_product, priority, description,
recommended_message, premium_current
)
SELECT
p_usuario_id, v_vendor_id, v_oficina_id, cp.id, cp.client_name,
'recoverable_policy', cp.ramos_activos, 'Reactivacion', 'high',
'Cliente con poliza vencida recuperable. Conviene contactarlo para reactivacion.',
'Hola ' || split_part(cp.client_name, ' ', 1) || ', te escribo porque note que tu poliza vencio recientemente. Me gustaria ayudarte a renovarla para que sigas protegido.',
cp.total_premium_active
FROM sicas_customer_profiles cp
WHERE cp.usuario_id = p_usuario_id
AND cp.portfolio_status = 'expired'
AND cp.total_policies_expired > 0
AND NOT EXISTS (
SELECT 1 FROM sicas_cross_sell_opportunities o
WHERE o.usuario_id = p_usuario_id AND o.customer_profile_id = cp.id AND o.opportunity_type = 'recoverable_policy'
AND o.status NOT IN ('dismissed', 'converted')
);

RETURN jsonb_build_object('success', true, 'opportunities_created', v_created);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.disparar_recurrencia_manual(p_recurrencia_id uuid, p_marcar_log boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  hoy                   date;
  rec                   RECORD;
  miembro               RECORD;
  v_fallback_estatus_id uuid;
  v_system_user_id      uuid;
  v_estatus_id          uuid;
  v_creado_por          uuid;
  v_tickets_creados     int := 0;
  ya_ejecutado          boolean;
BEGIN
  hoy := (NOW() AT TIME ZONE 'America/Mexico_City')::date;

  SELECT r.*, t.value AS tipo_tramite_value
  INTO rec
  FROM ticket_tipos_recurrencia r
  JOIN ticket_tipos t ON t.id = r.ticket_tipo_id
  WHERE r.id = p_recurrencia_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Recurrencia no encontrada');
  END IF;

  ya_ejecutado := EXISTS (
    SELECT 1 FROM ticket_recurrencia_log
    WHERE recurrencia_id = p_recurrencia_id AND fecha_generada = hoy
  );

  SELECT id INTO v_fallback_estatus_id
    FROM ticket_estatus WHERE activo = true ORDER BY orden ASC LIMIT 1;

  SELECT id INTO v_system_user_id
    FROM usuarios WHERE rol IN ('Administrador', 'Gerente') ORDER BY created_at ASC LIMIT 1;

  v_estatus_id := COALESCE(rec.estatus_id_inicial, v_fallback_estatus_id);
  v_creado_por := COALESCE(rec.created_by, v_system_user_id);

  IF rec.asignacion_tipo = 'usuario_especifico' AND rec.usuario_id IS NOT NULL THEN

    INSERT INTO tickets (
      tipo_tramite, estatus_id, prioridad, instrucciones,
      creado_por, modificado_por, assigned_to_user_id, grupo_asignado_id,
      recurrencia_id, fecha_vencimiento_tarea
    ) VALUES (
      rec.tipo_tramite_value, v_estatus_id, 'Media', rec.nombre,
      v_creado_por, v_creado_por, rec.usuario_id, rec.grupo_id,
      rec.id, hoy + rec.dias_para_vencer
    );
    v_tickets_creados := 1;

  ELSIF rec.asignacion_tipo = 'usuarios_especificos' THEN

    FOR miembro IN
      SELECT usuario_id FROM ticket_tipos_recurrencia_usuarios WHERE recurrencia_id = rec.id
    LOOP
      INSERT INTO tickets (
        tipo_tramite, estatus_id, prioridad, instrucciones,
        creado_por, modificado_por, assigned_to_user_id, grupo_asignado_id,
        recurrencia_id, fecha_vencimiento_tarea
      ) VALUES (
        rec.tipo_tramite_value, v_estatus_id, 'Media', rec.nombre,
        v_creado_por, v_creado_por, miembro.usuario_id, rec.grupo_id,
        rec.id, hoy + rec.dias_para_vencer
      );
      v_tickets_creados := v_tickets_creados + 1;
    END LOOP;

  ELSIF rec.asignacion_tipo = 'pool' THEN

    INSERT INTO tickets (
      tipo_tramite, estatus_id, prioridad, instrucciones,
      creado_por, modificado_por, assigned_to_user_id, grupo_asignado_id,
      recurrencia_id, fecha_vencimiento_tarea
    ) VALUES (
      rec.tipo_tramite_value, v_estatus_id, 'Media', rec.nombre,
      v_creado_por, v_creado_por, NULL, rec.grupo_id,
      rec.id, hoy + rec.dias_para_vencer
    );
    v_tickets_creados := 1;

  ELSIF rec.asignacion_tipo = 'todos_del_grupo' AND rec.grupo_id IS NOT NULL THEN

    FOR miembro IN
      SELECT usuario_id FROM tramites_grupos_miembros WHERE grupo_id = rec.grupo_id
    LOOP
      INSERT INTO tickets (
        tipo_tramite, estatus_id, prioridad, instrucciones,
        creado_por, modificado_por, assigned_to_user_id, grupo_asignado_id,
        recurrencia_id, fecha_vencimiento_tarea
      ) VALUES (
        rec.tipo_tramite_value, v_estatus_id, 'Media', rec.nombre,
        v_creado_por, v_creado_por, miembro.usuario_id, rec.grupo_id,
        rec.id, hoy + rec.dias_para_vencer
      );
      v_tickets_creados := v_tickets_creados + 1;
    END LOOP;

  END IF;

  IF p_marcar_log THEN
    INSERT INTO ticket_recurrencia_log (recurrencia_id, fecha_generada, tickets_creados)
    VALUES (p_recurrencia_id, hoy, v_tickets_creados)
    ON CONFLICT (recurrencia_id, fecha_generada) DO UPDATE
      SET tickets_creados = ticket_recurrencia_log.tickets_creados + EXCLUDED.tickets_creados;
  END IF;

  RETURN jsonb_build_object(
    'tickets_creados', v_tickets_creados,
    'ya_ejecutado',    ya_ejecutado
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.duplicate_fiscal_rule(p_source_id uuid, p_new_version text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_new_id uuid;
v_source fiscal_regime_rules%ROWTYPE;
BEGIN
SELECT * INTO v_source FROM fiscal_regime_rules WHERE id = p_source_id;

IF NOT FOUND THEN
RAISE EXCEPTION 'Regla fuente no encontrada: %', p_source_id;
END IF;

-- Insertar nueva cabecera como borrador
INSERT INTO fiscal_regime_rules (
regimen_codigo,
nombre_regimen,
version,
vigente_desde,
vigente_hasta,
activo,
estado,
notas,
created_by
) VALUES (
v_source.regimen_codigo,
v_source.nombre_regimen,
p_new_version,
CURRENT_DATE,
NULL,
false,
'borrador',
'Copia de versión ' || v_source.version,
auth.uid()
)
RETURNING id INTO v_new_id;

-- Copiar todas las líneas
INSERT INTO fiscal_regime_rule_lines (
fiscal_regime_rule_id,
concepto_codigo,
concepto_nombre,
base_codigo,
tipo_regla,
valor_porcentaje,
formula_texto,
signo_resultado,
orden_visual,
mostrar_en_pdf,
mostrar_en_ui,
activo,
notas
)
SELECT
v_new_id,
concepto_codigo,
concepto_nombre,
base_codigo,
tipo_regla,
valor_porcentaje,
formula_texto,
signo_resultado,
orden_visual,
mostrar_en_pdf,
mostrar_en_ui,
activo,
notas
FROM fiscal_regime_rule_lines
WHERE fiscal_regime_rule_id = p_source_id;

RETURN v_new_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.ejecutar_recurrencias()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  hoy                   date;
  dow                   int;
  dom                   int;
  v_hora                int;
  v_fallback_estatus_id uuid;
  v_system_user_id      uuid;
  rec                   RECORD;
  miembro               RECORD;
  v_estatus_id          uuid;
  v_creado_por          uuid;
  v_tickets_creados     int;
  v_total               int := 0;
BEGIN
  hoy    := (NOW() AT TIME ZONE 'America/Mexico_City')::date;
  dow    := EXTRACT(DOW  FROM NOW() AT TIME ZONE 'America/Mexico_City')::int;
  dom    := EXTRACT(DAY  FROM NOW() AT TIME ZONE 'America/Mexico_City')::int;
  v_hora := EXTRACT(HOUR FROM NOW() AT TIME ZONE 'America/Mexico_City')::int;

  SELECT id INTO v_fallback_estatus_id
    FROM ticket_estatus WHERE activo = true ORDER BY orden ASC LIMIT 1;

  -- ▼ ÚNICO CAMBIO: usuario dedicado en vez del admin más antiguo.
  SELECT id INTO v_system_user_id FROM usuarios WHERE username = 'sistema';
  IF v_system_user_id IS NULL THEN
    SELECT id INTO v_system_user_id
      FROM usuarios WHERE rol IN ('Administrador', 'Gerente') ORDER BY created_at ASC LIMIT 1;
  END IF;
  -- ▲ FIN DEL CAMBIO

  FOR rec IN
    SELECT r.*, t.value AS tipo_tramite_value
    FROM ticket_tipos_recurrencia r
    JOIN ticket_tipos t ON t.id = r.ticket_tipo_id
    WHERE r.activo = true
      AND r.fecha_inicio <= hoy
      AND (r.fecha_fin IS NULL OR r.fecha_fin >= hoy)
      AND EXTRACT(HOUR FROM r.hora_disparo) = v_hora
      AND NOT EXISTS (
        SELECT 1 FROM ticket_recurrencia_log l
        WHERE l.recurrencia_id = r.id AND l.fecha_generada = hoy
      )
  LOOP
    -- Filtrar por frecuencia
    IF rec.frecuencia = 'semanal' AND NOT (dow = ANY(COALESCE(rec.dias_semana, '{}'::int[]))) THEN
      CONTINUE;
    END IF;
    IF rec.frecuencia = 'mensual' AND (rec.dia_mes IS NULL OR rec.dia_mes <> dom) THEN
      CONTINUE;
    END IF;

    -- Reservar slot en log (guard contra doble ejecución por race condition)
    INSERT INTO ticket_recurrencia_log (recurrencia_id, fecha_generada, tickets_creados)
    VALUES (rec.id, hoy, 0)
    ON CONFLICT (recurrencia_id, fecha_generada) DO NOTHING;

    IF NOT FOUND THEN CONTINUE; END IF;

    v_estatus_id      := COALESCE(rec.estatus_id_inicial, v_fallback_estatus_id);
    v_creado_por      := COALESCE(rec.created_by, v_system_user_id);
    v_tickets_creados := 0;

    IF rec.asignacion_tipo = 'usuario_especifico' AND rec.usuario_id IS NOT NULL THEN

      INSERT INTO tickets (
        tipo_tramite, estatus_id, prioridad, instrucciones,
        creado_por, modificado_por, assigned_to_user_id, grupo_asignado_id,
        recurrencia_id, fecha_vencimiento_tarea
      ) VALUES (
        rec.tipo_tramite_value, v_estatus_id, 'Media', rec.nombre,
        v_creado_por, v_creado_por, rec.usuario_id, rec.grupo_id,
        rec.id, hoy + rec.dias_para_vencer
      );
      v_tickets_creados := 1;

    ELSIF rec.asignacion_tipo = 'usuarios_especificos' THEN

      FOR miembro IN
        SELECT usuario_id FROM ticket_tipos_recurrencia_usuarios WHERE recurrencia_id = rec.id
      LOOP
        INSERT INTO tickets (
          tipo_tramite, estatus_id, prioridad, instrucciones,
          creado_por, modificado_por, assigned_to_user_id, grupo_asignado_id,
          recurrencia_id, fecha_vencimiento_tarea
        ) VALUES (
          rec.tipo_tramite_value, v_estatus_id, 'Media', rec.nombre,
          v_creado_por, v_creado_por, miembro.usuario_id, rec.grupo_id,
          rec.id, hoy + rec.dias_para_vencer
        );
        v_tickets_creados := v_tickets_creados + 1;
      END LOOP;

    ELSIF rec.asignacion_tipo = 'pool' THEN

      INSERT INTO tickets (
        tipo_tramite, estatus_id, prioridad, instrucciones,
        creado_por, modificado_por, assigned_to_user_id, grupo_asignado_id,
        recurrencia_id, fecha_vencimiento_tarea
      ) VALUES (
        rec.tipo_tramite_value, v_estatus_id, 'Media', rec.nombre,
        v_creado_por, v_creado_por, NULL, rec.grupo_id,
        rec.id, hoy + rec.dias_para_vencer
      );
      v_tickets_creados := 1;

    ELSIF rec.asignacion_tipo = 'todos_del_grupo' AND rec.grupo_id IS NOT NULL THEN

      FOR miembro IN
        SELECT usuario_id FROM tramites_grupos_miembros WHERE grupo_id = rec.grupo_id
      LOOP
        INSERT INTO tickets (
          tipo_tramite, estatus_id, prioridad, instrucciones,
          creado_por, modificado_por, assigned_to_user_id, grupo_asignado_id,
          recurrencia_id, fecha_vencimiento_tarea
        ) VALUES (
          rec.tipo_tramite_value, v_estatus_id, 'Media', rec.nombre,
          v_creado_por, v_creado_por, miembro.usuario_id, rec.grupo_id,
          rec.id, hoy + rec.dias_para_vencer
        );
        v_tickets_creados := v_tickets_creados + 1;
      END LOOP;

    END IF;

    UPDATE ticket_recurrencia_log
    SET tickets_creados = v_tickets_creados
    WHERE recurrencia_id = rec.id AND fecha_generada = hoy;

    v_total := v_total + v_tickets_creados;
  END LOOP;

  RETURN jsonb_build_object('fecha', hoy, 'hora', v_hora, 'tickets_creados', v_total);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.eliminar_chat(p_chat_id uuid, p_usuario_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
-- Verificar que el usuario sea miembro del chat
IF NOT EXISTS (
SELECT 1 FROM chat_miembros
WHERE chat_id = p_chat_id
AND usuario_id = p_usuario_id
) THEN
RAISE EXCEPTION 'Usuario no es miembro de este chat';
END IF;

-- Eliminar el chat (soft delete)
UPDATE chat_miembros
SET eliminado = true,
eliminado_at = now(),
oculto = true,
oculto_at = now()
WHERE chat_id = p_chat_id
AND usuario_id = p_usuario_id;

RETURN true;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.email_cred_get(p_usuario_id uuid, p_key text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result text;
BEGIN
  SELECT extensions.pgp_sym_decrypt(password_cifrada, p_key) INTO v_result
  FROM public.email_credenciales WHERE usuario_id = p_usuario_id;
  RETURN v_result;
EXCEPTION WHEN OTHERS THEN
  RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.email_cred_set(p_usuario_id uuid, p_password text, p_key text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO public.email_credenciales (usuario_id, password_cifrada, updated_at)
  VALUES (p_usuario_id, extensions.pgp_sym_encrypt(p_password, p_key), now())
  ON CONFLICT (usuario_id) DO UPDATE
    SET password_cifrada = excluded.password_cifrada, updated_at = now();
END;
$function$
;

CREATE OR REPLACE FUNCTION public.enforce_single_active_terms()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
IF NEW.is_active = true THEN
UPDATE seguwallet_terms
SET is_active = false
WHERE id != NEW.id AND is_active = true;
END IF;
RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.enforce_single_default_channel()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
IF NEW.is_default = true THEN
UPDATE notification_channels
SET is_default = false, updated_at = now()
WHERE type = NEW.type
AND id <> NEW.id
AND is_default = true;
END IF;
RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.ensure_absolute_url(p_url text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
BEGIN
IF p_url IS NULL OR p_url = '' THEN
RETURN 'https://app.movi.digital/dashboard';
END IF;

IF p_url LIKE 'http://%' OR p_url LIKE 'https://%' THEN
RETURN p_url;
END IF;

IF p_url LIKE '/%' THEN
RETURN 'https://app.movi.digital' || p_url;
END IF;

RETURN 'https://app.movi.digital/' || p_url;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.ensure_default_avatar()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
-- Si imagen_perfil_url es NULL, vacío o solo espacios, asignar avatar por defecto
IF NEW.imagen_perfil_url IS NULL 
OR TRIM(NEW.imagen_perfil_url) = '' THEN
NEW.imagen_perfil_url = '/display-avatar.png';
END IF;

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.ensure_seccion_header(p_tipo_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_seccion_id uuid;
  v_color      text;
BEGIN
  SELECT color INTO v_color FROM ticket_tipos WHERE id = p_tipo_id;

  SELECT id INTO v_seccion_id
    FROM tramite_tipo_secciones
   WHERE tramite_tipo_id = p_tipo_id AND sistema_key = 'header';

  IF v_seccion_id IS NULL THEN
    INSERT INTO tramite_tipo_secciones
      (tramite_tipo_id, nombre, descripcion, orden, opcional, activo, sistema_key, config)
    VALUES
      (p_tipo_id, 'Encabezado',
       'Lo que se ve arriba del trámite: área, nombre, folio y estatus.',
       -1, false, true, 'header',
       jsonb_build_object('fondo', jsonb_build_object('tipo', 'color', 'color', COALESCE(v_color, '#6B7280'))))
    RETURNING id INTO v_seccion_id;
  END IF;

  -- El estatus se muestra y se cambia en el encabezado, así que ahí pertenece.
  UPDATE tramite_tipo_campos
     SET seccion_id = v_seccion_id
   WHERE tramite_tipo_id = p_tipo_id
     AND sistema_key = 'estatus'
     AND (seccion_id IS DISTINCT FROM v_seccion_id);
END $function$
;

CREATE OR REPLACE FUNCTION public.ensure_seccion_personas(p_tipo_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_seccion_id uuid;
BEGIN
  SELECT id INTO v_seccion_id
    FROM tramite_tipo_secciones
   WHERE tramite_tipo_id = p_tipo_id AND sistema_key = 'personas_asignacion';

  IF v_seccion_id IS NULL THEN
    INSERT INTO tramite_tipo_secciones (tramite_tipo_id, nombre, descripcion, orden, opcional, activo, sistema_key)
    VALUES (p_tipo_id, 'Personas y Asignación',
            'Quién solicita, quién registra y quién atiende este trámite.',
            0, false, true, 'personas_asignacion')
    RETURNING id INTO v_seccion_id;
  END IF;

  -- Los campos se mueven a la sección solo si no están ya ahí. No se fuerza el
  -- `orden` de cada uno: dentro de la sección se pueden reordenar libremente.
  UPDATE tramite_tipo_campos
     SET seccion_id = v_seccion_id
   WHERE tramite_tipo_id = p_tipo_id
     AND sistema_key IN ('agente_vendedor', 'creado_por', 'asignado_a', 'area', 'equipo', 'oficina_jiro')
     AND (seccion_id IS DISTINCT FROM v_seccion_id);
END $function$
;

CREATE OR REPLACE FUNCTION public.ensure_sistema_campo(p_tipo_id uuid, p_key text, p_label text, p_tipo text, p_order integer, p_config jsonb, p_skey text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.tramite_tipo_campos
    WHERE tramite_tipo_id = p_tipo_id
      AND is_sistema = true
      AND sistema_key = p_skey
  ) THEN
    INSERT INTO public.tramite_tipo_campos
      (tramite_tipo_id, key, label, tipo, requerido, display_order, config, activo, is_sistema, sistema_key)
    VALUES
      (p_tipo_id, p_key, p_label, p_tipo, true, p_order, p_config, true, true, p_skey);
  END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.enviar_notificacion_completa(p_tipo_codigo text, p_user_id uuid, p_titulo text, p_mensaje text, p_modulo text DEFAULT 'general'::text, p_datos_adicionales jsonb DEFAULT '{}'::jsonb, p_accion_url text DEFAULT NULL::text)
 RETURNS uuid[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_result jsonb;
v_notif_ids uuid[] := ARRAY[]::uuid[];
v_payload jsonb;
v_absolute_url text;
BEGIN
v_absolute_url := ensure_absolute_url(COALESCE(p_accion_url, '/dashboard'));

v_payload := p_datos_adicionales || jsonb_build_object(
'titulo', p_titulo,
'mensaje', p_mensaje,
'modulo', p_modulo,
'url', v_absolute_url
);

SELECT notify(
p_tipo_codigo,
ARRAY[p_user_id],
v_payload,
NULL
) INTO v_result;

RAISE LOG '[enviar_notificacion_completa] Resultado de notify(): %', v_result;

RETURN v_notif_ids;

EXCEPTION WHEN OTHERS THEN
RAISE WARNING '[enviar_notificacion_completa] Error: %', SQLERRM;
RETURN v_notif_ids;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.enviar_notificacion_global(p_titulo text, p_mensaje text, p_accion_url text, p_filtros jsonb DEFAULT '{}'::jsonb, p_evento_id uuid DEFAULT NULL::uuid, p_enviar_whatsapp boolean DEFAULT true)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_usuarios_ids uuid[];
v_usuario_id uuid;
v_notif_id uuid;
v_usuarios_count integer := 0;
v_notif_count integer := 0;
v_supabase_url text;
v_anon_key text;
v_user_record record;
v_telefono text;
v_telefono_normalizado text;
v_request_id bigint;
BEGIN
v_supabase_url := current_setting('app.settings.supabase_url', true);
v_anon_key := current_setting('app.settings.supabase_anon_key', true);

IF v_supabase_url IS NULL THEN
v_supabase_url := 'https://hiorlqynmkqejfmpkogb.supabase.co';
END IF;

IF v_anon_key IS NULL THEN
RAISE WARNING 'Supabase anon key no configurada. WhatsApp no se enviará.';
p_enviar_whatsapp := false;
END IF;

SELECT ARRAY_AGG(DISTINCT id)
INTO v_usuarios_ids
FROM usuarios
WHERE estado = 'activo'
AND (
(p_filtros->>'rol' IS NULL OR rol = p_filtros->>'rol')
AND (p_filtros->>'oficina_id' IS NULL OR oficina_id::text = p_filtros->>'oficina_id')
);

IF v_usuarios_ids IS NULL OR array_length(v_usuarios_ids, 1) IS NULL THEN
RAISE NOTICE 'No se encontraron usuarios que cumplan los filtros';
RETURN json_build_object('usuarios_notificados', 0, 'notificaciones_creadas', 0);
END IF;

RAISE NOTICE 'Usuarios encontrados: %', array_length(v_usuarios_ids, 1);

FOREACH v_usuario_id IN ARRAY v_usuarios_ids
LOOP
INSERT INTO notificaciones (
usuario_id,
titulo,
mensaje,
tipo,
modulo,
accion_url,
leida,
prioridad
)
VALUES (
v_usuario_id,
p_titulo,
p_mensaje,
'info',
'Comunicados',
p_accion_url,
false,
'normal'
)
RETURNING id INTO v_notif_id;

v_notif_count := v_notif_count + 1;

IF p_enviar_whatsapp THEN
BEGIN
SELECT
u.*,
COALESCE(NULLIF(u.celular_laboral, ''), NULLIF(u.celular_personal, '')) as telefono
INTO v_user_record
FROM usuarios u
WHERE u.id = v_usuario_id;

v_telefono := v_user_record.telefono;

IF v_telefono IS NOT NULL AND LENGTH(v_telefono) >= 10 THEN
v_telefono_normalizado := regexp_replace(v_telefono, '[^0-9]', '', 'g');

IF LENGTH(v_telefono_normalizado) = 10 THEN
v_telefono_normalizado := '521' || v_telefono_normalizado;
END IF;

RAISE NOTICE 'Enviando WhatsApp a: % (normalizado: %)', v_telefono, v_telefono_normalizado;

SELECT INTO v_request_id net.http_post(
url := v_supabase_url || '/functions/v1/enviar-whatsapp',
headers := jsonb_build_object(
'Content-Type', 'application/json',
'Authorization', 'Bearer ' || v_anon_key
),
body := jsonb_build_object(
'tipo', 'notificacion_global',
'numero', v_telefono_normalizado,
'datos', jsonb_build_object(
'nombre', v_user_record.nombre,
'apellidos', v_user_record.apellidos,
'titulo', p_titulo,
'mensaje', p_mensaje,
'accion_url', p_accion_url
),
'evento_id', p_evento_id
)
);

RAISE NOTICE 'WhatsApp enviado (request_id: %)', v_request_id;
ELSE
RAISE NOTICE 'Usuario % no tiene teléfono válido', v_usuario_id;
END IF;

EXCEPTION WHEN OTHERS THEN
RAISE WARNING 'Error enviando WhatsApp a usuario %: %', v_usuario_id, SQLERRM;
END;
END IF;

v_usuarios_count := v_usuarios_count + 1;
END LOOP;

RAISE NOTICE 'Proceso completado: % usuarios, % notificaciones', v_usuarios_count, v_notif_count;

RETURN json_build_object('usuarios_notificados', v_usuarios_count, 'notificaciones_creadas', v_notif_count);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.enviar_notificacion_global(p_titulo text, p_mensaje text, p_accion_url text, p_filtros jsonb DEFAULT '{}'::jsonb, p_evento_id uuid DEFAULT NULL::uuid, p_enviar_whatsapp boolean DEFAULT true, p_enviado_por uuid DEFAULT NULL::uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_usuarios_ids uuid[];
v_usuario_id uuid;
v_notif_id uuid;
v_usuarios_count integer := 0;
v_notif_count integer := 0;
v_wa_enviados integer := 0;
v_wa_fallidos integer := 0;
v_supabase_url text;
v_anon_key text;
v_user_record record;
v_telefono text;
v_telefono_normalizado text;
v_request_id bigint;
v_global_id uuid;
BEGIN
v_supabase_url := COALESCE(
NULLIF(current_setting('app.settings.supabase_url', true), ''),
'https://qhwvuuyjhcennqccgvse.supabase.co'
);

v_anon_key := COALESCE(
NULLIF(current_setting('app.settings.supabase_anon_key', true), ''),
'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InFod3Z1dXlqaGNlbm5xY2NndnNlIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NjE3MjA5OTAsImV4cCI6MjA3NzI5Njk5MH0.bIlGsgeAC6oxGUalODg0C5-l6KaJip0wWa9IbQ7MjTQ'
);

-- Get target users
SELECT ARRAY_AGG(DISTINCT id)
INTO v_usuarios_ids
FROM usuarios
WHERE estado = 'activo'
AND (
(p_filtros->>'rol' IS NULL OR rol = p_filtros->>'rol')
AND (p_filtros->>'oficina_id' IS NULL OR oficina_id::text = p_filtros->>'oficina_id')
);

IF v_usuarios_ids IS NULL OR array_length(v_usuarios_ids, 1) IS NULL THEN
RAISE NOTICE 'No se encontraron usuarios que cumplan los filtros';
RETURN json_build_object('usuarios_notificados', 0, 'notificaciones_creadas', 0);
END IF;

-- Insert history record — if no sender provided, pick first admin
IF p_enviado_por IS NULL THEN
SELECT id INTO p_enviado_por FROM usuarios WHERE rol = 'admin' AND estado = 'activo' LIMIT 1;
END IF;

IF p_enviado_por IS NOT NULL THEN
INSERT INTO notificaciones_globales (
titulo, mensaje, accion_url, destinatarios, enviado_por, enviar_whatsapp, whatsapp_enviado
) VALUES (
p_titulo, p_mensaje, p_accion_url, p_filtros, p_enviado_por, p_enviar_whatsapp, false
)
RETURNING id INTO v_global_id;
END IF;

FOREACH v_usuario_id IN ARRAY v_usuarios_ids
LOOP
INSERT INTO notificaciones (
usuario_id, titulo, mensaje, tipo, modulo, accion_url, leida, prioridad
) VALUES (
v_usuario_id, p_titulo, p_mensaje, 'info', 'Comunicados', p_accion_url, false, 'normal'
)
RETURNING id INTO v_notif_id;

v_notif_count := v_notif_count + 1;

IF p_enviar_whatsapp THEN
BEGIN
SELECT
u.nombre,
u.apellidos,
COALESCE(NULLIF(u.celular_laboral, ''), NULLIF(u.celular_personal, '')) as telefono
INTO v_user_record
FROM usuarios u
WHERE u.id = v_usuario_id;

v_telefono := v_user_record.telefono;

IF v_telefono IS NOT NULL AND LENGTH(v_telefono) >= 10 THEN
v_telefono_normalizado := regexp_replace(v_telefono, '[^0-9]', '', 'g');

IF LENGTH(v_telefono_normalizado) = 10 THEN
v_telefono_normalizado := '521' || v_telefono_normalizado;
ELSIF LENGTH(v_telefono_normalizado) = 12 AND v_telefono_normalizado LIKE '52%' THEN
v_telefono_normalizado := '521' || SUBSTRING(v_telefono_normalizado FROM 3);
ELSIF LENGTH(v_telefono_normalizado) = 13 AND v_telefono_normalizado NOT LIKE '521%' THEN
v_telefono_normalizado := '521' || SUBSTRING(v_telefono_normalizado FROM 4);
END IF;

SELECT INTO v_request_id net.http_post(
url := v_supabase_url || '/functions/v1/enviar-whatsapp',
headers := jsonb_build_object(
'Content-Type', 'application/json',
'Authorization', 'Bearer ' || v_anon_key
),
body := jsonb_build_object(
'tipo', 'notificacion_global',
'numero', v_telefono_normalizado,
'datos', jsonb_build_object(
'nombre', v_user_record.nombre,
'apellidos', v_user_record.apellidos,
'titulo', p_titulo,
'mensaje', p_mensaje,
'accion_url', p_accion_url
),
'evento_id', p_evento_id
)
);
v_wa_enviados := v_wa_enviados + 1;
ELSE
v_wa_fallidos := v_wa_fallidos + 1;
END IF;
EXCEPTION WHEN OTHERS THEN
RAISE WARNING 'Error enviando WhatsApp a usuario %: %', v_usuario_id, SQLERRM;
v_wa_fallidos := v_wa_fallidos + 1;
END;
END IF;

v_usuarios_count := v_usuarios_count + 1;
END LOOP;

IF v_global_id IS NOT NULL THEN
UPDATE notificaciones_globales
SET
whatsapp_enviado = (v_wa_enviados > 0),
whatsapp_fecha_envio = CASE WHEN v_wa_enviados > 0 THEN now() ELSE NULL END,
whatsapp_total_enviados = v_wa_enviados,
whatsapp_total_fallidos = v_wa_fallidos
WHERE id = v_global_id;
END IF;

RETURN json_build_object(
'usuarios_notificados', v_usuarios_count,
'notificaciones_creadas', v_notif_count,
'whatsapp_enviados', v_wa_enviados,
'whatsapp_fallidos', v_wa_fallidos
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.enviar_notificacion_individual(p_user_id uuid, p_titulo text, p_mensaje text, p_modulo text, p_accion_url text DEFAULT NULL::text, p_enviar_whatsapp boolean DEFAULT true)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_notif_id uuid;
v_user_record record;
v_telefono text;
v_telefono_normalizado text;
v_supabase_url text;
v_anon_key text;
v_request_id bigint;
BEGIN
v_supabase_url := COALESCE(
NULLIF(current_setting('app.settings.supabase_url', true), ''),
'https://qhwvuuyjhcennqccgvse.supabase.co'
);

