'apellidos', v_user_record.apellidos,
'titulo', p_titulo,
'mensaje', p_mensaje,
'modulo', p_modulo
)
)
);

RAISE NOTICE 'WhatsApp request_id: % para %', v_request_id, v_telefono_normalizado;
EXCEPTION WHEN OTHERS THEN
RAISE WARNING 'Error enviando WhatsApp a %: %', v_telefono, SQLERRM;
END;
END IF;

RETURN v_notif_id;
END;
