;

CREATE OR REPLACE FUNCTION public.enviar_notificacion_transaccional(p_codigo_tipo text, p_destinatario_id uuid, p_variables jsonb DEFAULT '{}'::jsonb, p_adjuntos jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_template record;
v_destinatario record;
v_channels text[];
v_idem_base text;
BEGIN
SELECT 
id,
nombre_completo,
email_laboral,
celular_laboral
INTO v_destinatario
FROM usuarios
WHERE id = p_destinatario_id
AND deleted_at IS NULL
AND estado != 'eliminado';

IF NOT FOUND THEN
RAISE WARNING '[NOTIF TRANSACCIONAL] Destinatario no encontrado o inactivo: %', p_destinatario_id;
RETURN;
END IF;

SELECT
t.codigo,
t.nombre as tipo_nombre,
p.asunto,
p.html_cuerpo,
p.whatsapp_plantilla,
COALESCE(p.enviar_correo, true) as enviar_correo,
COALESCE(p.enviar_whatsapp, true) as enviar_whatsapp,
COALESCE(p.enviar_notificacion, true) as enviar_notificacion
INTO v_template
FROM correo_tipos_notificacion t
LEFT JOIN correo_plantillas p ON p.tipo_notificacion_id = t.id AND p.es_plantilla_default = true
WHERE t.codigo = p_codigo_tipo
AND t.activo = true;

IF NOT FOUND THEN
RAISE WARNING '[NOTIF TRANSACCIONAL] Tipo de notificación no encontrado o inactivo: %', p_codigo_tipo;
RETURN;
END IF;

v_channels := ARRAY[]::text[];
IF v_template.enviar_correo THEN
v_channels := v_channels || ARRAY['email'];
END IF;
IF v_template.enviar_whatsapp THEN
v_channels := v_channels || ARRAY['whatsapp'];
END IF;
IF v_template.enviar_notificacion THEN
v_channels := v_channels || ARRAY['in_app'];
END IF;

IF array_length(v_channels, 1) IS NULL THEN
v_channels := ARRAY['email', 'whatsapp', 'in_app'];
END IF;

v_idem_base := p_codigo_tipo || '_' || p_destinatario_id::text || '_' || to_char(date_trunc('minute', now()), 'YYYYMMDD_HH24MI');

IF 'email' = ANY(v_channels) AND v_destinatario.email_laboral IS NOT NULL THEN
INSERT INTO notification_jobs (
event_code,
user_id,
channel,
payload,
attachments,
status,
idempotency_key
) VALUES (
p_codigo_tipo,
p_destinatario_id,
'email',
p_variables || jsonb_build_object(
'email', v_destinatario.email_laboral,
'nombre_completo', v_destinatario.nombre_completo
),
p_adjuntos,
'pending',
v_idem_base || '_email'
)
ON CONFLICT (idempotency_key) DO NOTHING;

RAISE NOTICE '[NOTIF TRANSACCIONAL] Email job creado para % (adjuntos: %)', 
v_destinatario.email_laboral, 
CASE WHEN p_adjuntos IS NOT NULL THEN jsonb_array_length(p_adjuntos) ELSE 0 END;
END IF;

IF 'whatsapp' = ANY(v_channels) AND v_destinatario.celular_laboral IS NOT NULL THEN
INSERT INTO notification_jobs (
event_code,
user_id,
channel,
payload,
status,
idempotency_key
) VALUES (
p_codigo_tipo,
p_destinatario_id,
'whatsapp',
p_variables || jsonb_build_object(
'phone', v_destinatario.celular_laboral,
'nombre_completo', v_destinatario.nombre_completo
),
'pending',
v_idem_base || '_whatsapp'
)
ON CONFLICT (idempotency_key) DO NOTHING;

RAISE NOTICE '[NOTIF TRANSACCIONAL] WhatsApp job creado para %', v_destinatario.celular_laboral;
END IF;

IF 'in_app' = ANY(v_channels) THEN
INSERT INTO notification_jobs (
event_code,
user_id,
channel,
payload,
status,
idempotency_key
) VALUES (
p_codigo_tipo,
p_destinatario_id,
'in_app',
p_variables || jsonb_build_object(
'nombre_completo', v_destinatario.nombre_completo
),
'pending',
v_idem_base || '_in_app'
)
ON CONFLICT (idempotency_key) DO NOTHING;

RAISE NOTICE '[NOTIF TRANSACCIONAL] In-app job creado';
END IF;

END;
$function$
;

CREATE OR REPLACE FUNCTION public.es_reporte_de_bug(p_ticket_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (SELECT 1 FROM bug_reportes WHERE ticket_id = p_ticket_id);
$function$
;

CREATE OR REPLACE FUNCTION public.expire_jiro_coins()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_expired_event agent_gamification_events;
v_expired_count INTEGER := 0;
BEGIN
FOR v_expired_event IN
SELECT *
FROM agent_gamification_events
WHERE fecha_expiracion_jc IS NOT NULL
AND fecha_expiracion_jc <= now()
AND reversed_by_event_id IS NULL
AND jc_delta > 0
LOOP
-- Crear evento de expiración
PERFORM add_gamification_event(
p_user_id := v_expired_event.user_id,
p_tipo_evento := 'expiracion_jc',
p_referencia_tipo := 'evento',
p_referencia_id := v_expired_event.id::TEXT,
p_xp_delta := 0,
p_jc_delta := -v_expired_event.jc_delta,
p_reversible := false,
p_jc_expiration_months := 0,
p_metadata := jsonb_build_object(
'original_event_id', v_expired_event.id,
'motivo', 'expiracion'
)
);

-- Marcar como expirado
UPDATE agent_gamification_events
SET reversed_by_event_id = v_expired_event.id
WHERE id = v_expired_event.id;

v_expired_count := v_expired_count + 1;
END LOOP;

RETURN v_expired_count;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.express_agentes_pendientes_notificar(p_lead_id uuid)
 RETURNS TABLE(usuario_id uuid, distancia_km numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_lead public.express_leads%ROWTYPE;
BEGIN
  SELECT * INTO v_lead FROM public.express_leads WHERE id = p_lead_id;
  IF NOT FOUND OR v_lead.estado <> 'notificado' OR v_lead.agente_asignado_id IS NOT NULL THEN RETURN; END IF;
  RETURN QUERY
  SELECT u.id, public.express_distancia_km(u.ubicacion_lat, u.ubicacion_lng, v_lead.lat, v_lead.lng)
  FROM public.usuarios u
  WHERE u.seguros_express_habilitado = true
    AND COALESCE(u.activo, false) = true
    AND COALESCE(u.is_deleted, false) = false
    AND NOT EXISTS (
      SELECT 1 FROM public.express_lead_agentes_notificados n
      WHERE n.lead_id = p_lead_id AND n.usuario_id = u.id)
    AND (
      (v_lead.lat IS NULL OR v_lead.lng IS NULL)
      OR (u.ubicacion_lat IS NOT NULL AND u.ubicacion_lng IS NOT NULL
          AND public.express_distancia_km(u.ubicacion_lat, u.ubicacion_lng, v_lead.lat, v_lead.lng) <= v_lead.anillo_km_actual)
    );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.express_aplicar_defaults_beta(p_usuario_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.usuarios u
  SET
    seguros_express_habilitado = true,
    ubicacion_lat = CASE WHEN u.ubicacion_metodo IS NULL THEN o.ubicacion_lat ELSE u.ubicacion_lat END,
    ubicacion_lng = CASE WHEN u.ubicacion_metodo IS NULL THEN o.ubicacion_lng ELSE u.ubicacion_lng END,
    ubicacion_direccion_manual = CASE WHEN u.ubicacion_metodo IS NULL THEN NULLIF(trim(o.domicilio), '') ELSE u.ubicacion_direccion_manual END,
    ubicacion_metodo = CASE WHEN u.ubicacion_metodo IS NULL AND (o.ubicacion_lat IS NOT NULL OR o.ubicacion_lng IS NOT NULL OR NULLIF(trim(o.domicilio), '') IS NOT NULL) THEN 'oficina' ELSE u.ubicacion_metodo END,
    ubicacion_updated_at = CASE WHEN u.ubicacion_metodo IS NULL AND (o.ubicacion_lat IS NOT NULL OR o.ubicacion_lng IS NOT NULL OR NULLIF(trim(o.domicilio), '') IS NOT NULL) THEN now() ELSE u.ubicacion_updated_at END,
    updated_at = now()
  FROM public.oficinas o
  WHERE u.id = p_usuario_id AND o.id = u.oficina_id;

  UPDATE public.usuarios
  SET seguros_express_habilitado = true, updated_at = now()
  WHERE id = p_usuario_id AND oficina_id IS NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.express_defaults_al_alta_beta()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.express_aplicar_defaults_beta(NEW.usuario_id);
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.express_distancia_km(p_lat1 numeric, p_lng1 numeric, p_lat2 numeric, p_lng2 numeric)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  SELECT CASE
    WHEN p_lat1 IS NULL OR p_lng1 IS NULL OR p_lat2 IS NULL OR p_lng2 IS NULL THEN NULL
    ELSE earth_distance(ll_to_earth(p_lat1::float8, p_lng1::float8), ll_to_earth(p_lat2::float8, p_lng2::float8)) / 1000.0
  END;
$function$
;

CREATE OR REPLACE FUNCTION public.express_es_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (SELECT 1 FROM public.usuarios WHERE id = auth.uid() AND rol = 'Administrador');
$function$
;

CREATE OR REPLACE FUNCTION public.express_lead_en_alcance(p_lead_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_habilitado boolean; v_activo boolean; v_ag_lat numeric; v_ag_lng numeric;
  v_lead public.express_leads%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN RETURN false; END IF;
  SELECT seguros_express_habilitado, activo, ubicacion_lat, ubicacion_lng
    INTO v_habilitado, v_activo, v_ag_lat, v_ag_lng
  FROM public.usuarios WHERE id = v_uid;
  IF NOT COALESCE(v_habilitado, false) OR NOT COALESCE(v_activo, false) THEN RETURN false; END IF;
  SELECT * INTO v_lead FROM public.express_leads WHERE id = p_lead_id;
  IF NOT FOUND THEN RETURN false; END IF;
  IF v_lead.lat IS NULL OR v_lead.lng IS NULL THEN RETURN true; END IF;
  IF v_ag_lat IS NULL OR v_ag_lng IS NULL THEN RETURN false; END IF;
  RETURN public.express_distancia_km(v_ag_lat, v_ag_lng, v_lead.lat, v_lead.lng) <= v_lead.anillo_km_actual;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.express_preparar_ubicacion_usuario()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE oficina record;
BEGIN
  IF NOT COALESCE(NEW.seguros_express_habilitado, false)
    OR NEW.oficina_id IS NULL
    OR NEW.ubicacion_metodo IN ('gps', 'manual') THEN
    RETURN NEW;
  END IF;

  SELECT domicilio, ubicacion_lat, ubicacion_lng INTO oficina
  FROM public.oficinas WHERE id = NEW.oficina_id;

  IF FOUND THEN
    NEW.ubicacion_lat := oficina.ubicacion_lat;
    NEW.ubicacion_lng := oficina.ubicacion_lng;
    NEW.ubicacion_direccion_manual := NULLIF(trim(oficina.domicilio), '');
    IF oficina.ubicacion_lat IS NOT NULL OR oficina.ubicacion_lng IS NOT NULL OR NULLIF(trim(oficina.domicilio), '') IS NOT NULL THEN
      NEW.ubicacion_metodo := 'oficina';
      NEW.ubicacion_updated_at := now();
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.express_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.express_sincronizar_ubicacion_oficina()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.usuarios
  SET ubicacion_lat = NEW.ubicacion_lat,
      ubicacion_lng = NEW.ubicacion_lng,
      ubicacion_direccion_manual = NULLIF(trim(NEW.domicilio), ''),
      ubicacion_updated_at = now(),
      updated_at = now()
  WHERE oficina_id = NEW.id AND ubicacion_metodo = 'oficina';
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.extract_sicas_catalog_name()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
-- For Despachos (catalog_type_id = 11)
IF NEW.catalog_type_id = 11 THEN
NEW.nombre = COALESCE(NEW.raw->>'DespNombre', NEW.nombre);
END IF;

-- For Vendedores (catalog_type_id = 32)
IF NEW.catalog_type_id = 32 THEN
NEW.nombre = COALESCE(NEW.raw->>'VendNombre', NEW.nombre);
END IF;

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.find_movi_user_for_vendor(vendor_email text, vendor_name text, OUT user_id uuid, OUT method text)
 RETURNS record
 LANGUAGE plpgsql
AS $function$
DECLARE
normalized_email text;
normalized_name text;
vendor_key_value text;
BEGIN
user_id := NULL;
method := 'none';

-- Paso 1: Búsqueda directa por email
normalized_email := normalize_email(vendor_email);
IF normalized_email IS NOT NULL THEN
SELECT id INTO user_id
FROM usuarios
WHERE normalize_email(email) = normalized_email
LIMIT 1;

IF user_id IS NOT NULL THEN
method := 'direct_email';
RETURN;
END IF;
END IF;

-- Paso 2: Búsqueda en mapeos por email
IF normalized_email IS NOT NULL THEN
SELECT movi_user_id INTO user_id
FROM vendor_mappings
WHERE source_type = 'email'
AND source_value = normalized_email
AND status = 'active'
LIMIT 1;

IF user_id IS NOT NULL THEN
method := 'mapping_email';
RETURN;
END IF;
END IF;

-- Paso 3: Búsqueda en mapeos por nombre
normalized_name := normalize_name(vendor_name);
IF normalized_name IS NOT NULL THEN
SELECT movi_user_id INTO user_id
FROM vendor_mappings
WHERE source_type = 'name'
AND source_value = normalized_name
AND status = 'active'
LIMIT 1;

IF user_id IS NOT NULL THEN
method := 'mapping_name';
RETURN;
END IF;
END IF;

-- No se encontró match
method := 'none';
END;
$function$
;

CREATE OR REPLACE FUNCTION public.find_vendor_mapping(vendor_email text, vendor_name text)
 RETURNS TABLE(movi_user_id uuid, match_method text, mapping_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
normalized_email TEXT;
normalized_name TEXT;
found_user_id UUID;
found_method TEXT;
found_mapping_id UUID;
BEGIN
normalized_email := normalize_email(vendor_email);
normalized_name := normalize_name(vendor_name);

-- Paso 1: Buscar por email directo en usuarios
IF normalized_email IS NOT NULL THEN
SELECT u.id INTO found_user_id
FROM usuarios u
WHERE normalize_email(COALESCE(u.email_laboral, u.email_personal)) = normalized_email
LIMIT 1;

IF FOUND THEN
RETURN QUERY SELECT found_user_id, 'direct_email'::TEXT, NULL::UUID;
RETURN;
END IF;
END IF;

-- Paso 2: Buscar mapeo por email
IF normalized_email IS NOT NULL THEN
SELECT vm.movi_user_id, vm.id
INTO found_user_id, found_mapping_id
FROM vendor_mappings vm
WHERE vm.source_type = 'email'
AND vm.source_value = normalized_email
AND vm.status = 'active'
LIMIT 1;

IF FOUND THEN
RETURN QUERY SELECT found_user_id, 'mapping_email'::TEXT, found_mapping_id;
RETURN;
END IF;
END IF;

-- Paso 3: Buscar mapeo por nombre
IF normalized_name IS NOT NULL THEN
SELECT vm.movi_user_id, vm.id
INTO found_user_id, found_mapping_id
FROM vendor_mappings vm
WHERE vm.source_type = 'name'
AND vm.source_value = normalized_name
AND vm.status = 'active'
LIMIT 1;

IF FOUND THEN
RETURN QUERY SELECT found_user_id, 'mapping_name'::TEXT, found_mapping_id;
RETURN;
END IF;
END IF;

-- No se encontró match
RETURN QUERY SELECT NULL::UUID, 'none'::TEXT, NULL::UUID;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.find_vendor_mapping_with_sicas(vendor_email text DEFAULT NULL::text, vendor_name text DEFAULT NULL::text, vend_id_sicas text DEFAULT NULL::text)
 RETURNS TABLE(movi_user_id uuid, match_method text, match_confidence integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_email_normalized TEXT;
v_name_normalized TEXT;
v_result RECORD;
BEGIN
-- Normalizar inputs
v_email_normalized := LOWER(TRIM(COALESCE(vendor_email, '')));
v_name_normalized := normalize_person_name(COALESCE(vendor_name, ''));

-- PASO 1: Buscar por ID SICAS directo (máxima prioridad)
IF vend_id_sicas IS NOT NULL AND vend_id_sicas != '' THEN
SELECT
smu.movi_user_id,
'mapping_sicas_id'::TEXT,
100
INTO v_result
FROM sicas_mapeo_vendedor_usuario smu
WHERE smu.id_sicas_vendedor = vend_id_sicas
LIMIT 1;

IF FOUND THEN
RETURN QUERY SELECT v_result.movi_user_id, v_result.match_method, v_result.match_confidence;
RETURN;
END IF;
END IF;

-- PASO 2: Email directo en tabla usuarios
IF v_email_normalized != '' THEN
SELECT
u.id,
'direct_email'::TEXT,
100
INTO v_result
FROM usuarios u
WHERE LOWER(u.email_laboral) = v_email_normalized
AND u.estado != 'eliminado'
LIMIT 1;

IF FOUND THEN
RETURN QUERY SELECT v_result.movi_user_id, v_result.match_method, v_result.match_confidence;
RETURN;
END IF;
END IF;

-- PASO 3: Mapeo por email en vendor_mappings
IF v_email_normalized != '' THEN
SELECT
vm.movi_user_id,
'mapping_email'::TEXT,
95
INTO v_result
FROM vendor_mappings vm
WHERE vm.source_type = 'email'
AND vm.source_value = v_email_normalized
AND vm.status = 'active'
LIMIT 1;

IF FOUND THEN
RETURN QUERY SELECT v_result.movi_user_id, v_result.match_method, v_result.match_confidence;
RETURN;
END IF;
END IF;

-- PASO 4: Nombre en SICAS (vendedores mapeados)
IF v_name_normalized != '' THEN
SELECT
smu.movi_user_id,
'mapping_sicas_name'::TEXT,
95
INTO v_result
FROM sicas_vendedores sv
INNER JOIN sicas_mapeo_vendedor_usuario smu
ON sv.id_sicas = smu.id_sicas_vendedor
WHERE normalize_person_name(sv.nombre) = v_name_normalized
LIMIT 1;

IF FOUND THEN
RETURN QUERY SELECT v_result.movi_user_id, v_result.match_method, v_result.match_confidence;
RETURN;
END IF;
END IF;

-- PASO 5: Mapeo por nombre en vendor_mappings
IF v_name_normalized != '' THEN
SELECT
vm.movi_user_id,
'mapping_name'::TEXT,
90
INTO v_result
FROM vendor_mappings vm
WHERE vm.source_type = 'name'
AND vm.source_value = v_name_normalized
AND vm.status = 'active'
LIMIT 1;

IF FOUND THEN
RETURN QUERY SELECT v_result.movi_user_id, v_result.match_method, v_result.match_confidence;
RETURN;
END IF;
END IF;

-- PASO 6: Búsqueda fuzzy por nombre en usuarios (similitud >= 92%)
IF v_name_normalized != '' THEN
SELECT
u.id,
'auto_fuzzy'::TEXT,
name_similarity(v_name_normalized, u.nombre_completo_norm)
INTO v_result
FROM usuarios u
WHERE u.nombre_completo_norm IS NOT NULL
AND u.estado != 'eliminado'
AND name_similarity(v_name_normalized, u.nombre_completo_norm) >= 92
ORDER BY name_similarity(v_name_normalized, u.nombre_completo_norm) DESC
LIMIT 1;

IF FOUND THEN
RETURN QUERY SELECT v_result.movi_user_id, v_result.match_method, v_result.match_confidence;
RETURN;
END IF;
END IF;

-- Sin match
RETURN QUERY SELECT NULL::UUID, 'none'::TEXT, 0;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_actualizar_progreso_mision(p_user_id uuid, p_mission_id uuid, p_incremento integer DEFAULT 1)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_mision agent_missions%ROWTYPE;
v_periodo TEXT;
v_meta INTEGER;
v_nuevo_progreso INTEGER;
BEGIN
-- Obtener misión
SELECT * INTO v_mision
FROM agent_missions
WHERE id = p_mission_id AND activa = true;

IF NOT FOUND THEN
RETURN;
END IF;

-- Determinar periodo
CASE v_mision.tipo_periodo
WHEN 'semanal' THEN
v_periodo := TO_CHAR(now(), 'IYYY-IW');
WHEN 'mensual' THEN
v_periodo := TO_CHAR(now(), 'YYYY-MM');
WHEN 'unica' THEN
v_periodo := 'unico';
ELSE
v_periodo := 'permanente';
END CASE;

-- Obtener meta requerida de la regla
v_meta := COALESCE((v_mision.regla_json->>'cantidad')::INTEGER, 1);

-- Actualizar o crear progreso
INSERT INTO agent_mission_progress (
user_id,
mission_id,
periodo,
progreso_actual,
meta_requerida,
completada
)
VALUES (
p_user_id,
p_mission_id,
v_periodo,
p_incremento,
v_meta,
p_incremento >= v_meta
)
ON CONFLICT (user_id, mission_id, periodo) DO UPDATE
SET
progreso_actual = agent_mission_progress.progreso_actual + p_incremento,
completada = (agent_mission_progress.progreso_actual + p_incremento) >= agent_mission_progress.meta_requerida,
updated_at = now();

-- Si se completó, otorgar recompensa
SELECT progreso_actual INTO v_nuevo_progreso
FROM agent_mission_progress
WHERE user_id = p_user_id AND mission_id = p_mission_id AND periodo = v_periodo;

IF v_nuevo_progreso >= v_meta THEN
PERFORM fn_registrar_evento_gamificacion(
p_user_id,
'mision_completada',
v_mision.xp_reward,
v_mision.jc_reward,
'agent_missions',
p_mission_id::TEXT,
false,
180,
jsonb_build_object(
'mision_nombre', v_mision.nombre,
'periodo', v_periodo
)
);

UPDATE agent_mission_progress
SET
fecha_completada = now(),
recompensa_reclamada = true
WHERE user_id = p_user_id AND mission_id = p_mission_id AND periodo = v_periodo;
END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_aplicar_bono_antiguedad(p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
v_perfil agent_gamification_profile;
v_anios_nuevos NUMERIC;
v_xp_bono INTEGER;
v_nuevo_multiplicador NUMERIC;
BEGIN
SELECT * INTO v_perfil
FROM agent_gamification_profile
WHERE user_id = p_user_id;

IF NOT FOUND THEN
RETURN;
END IF;

v_anios_nuevos := fn_calcular_anios_antiguedad(v_perfil.fecha_ingreso_empresa);

IF v_anios_nuevos >= (v_perfil.anios_antiguedad + 1.0) THEN
-- Solo XP: 100 puntos por año
v_xp_bono := 100 * FLOOR(v_anios_nuevos - v_perfil.anios_antiguedad);
v_nuevo_multiplicador := fn_calcular_multiplicador_veterano(v_anios_nuevos);

PERFORM fn_registrar_evento_gamificacion(
p_user_id := p_user_id,
p_tipo_evento := 'bono_antiguedad'::gamification_event_type,
p_xp_delta := v_xp_bono,
p_jc_delta := 0,
p_reversible := false,
p_metadata := jsonb_build_object(
'anios_cumplidos', FLOOR(v_anios_nuevos - v_perfil.anios_antiguedad),
'anios_totales', v_anios_nuevos,
'multiplicador_veterano', v_nuevo_multiplicador
)
);

UPDATE agent_gamification_profile
SET anios_antiguedad = v_anios_nuevos,
multiplicador_veterano = v_nuevo_multiplicador,
updated_at = now()
WHERE user_id = p_user_id;
END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_aplicar_bonos_antiguedad_masivo()
 RETURNS TABLE(user_id uuid, nombre_completo text, anios_antiguedad numeric, xp_otorgado integer)
 LANGUAGE plpgsql
AS $function$
DECLARE
v_agente RECORD;
BEGIN
FOR v_agente IN
SELECT agp.user_id, u.nombre_completo, agp.anios_antiguedad AS anios_previos,
fn_calcular_anios_antiguedad(agp.fecha_ingreso_empresa) AS anios_actuales
FROM agent_gamification_profile agp
JOIN public.usuarios u ON u.id = agp.user_id
WHERE u.rol = 'Agente' AND LOWER(u.estado) = 'activo' AND u.deleted_at IS NULL
AND fn_calcular_anios_antiguedad(agp.fecha_ingreso_empresa) >= (agp.anios_antiguedad + 1.0)
LOOP
PERFORM fn_aplicar_bono_antiguedad(v_agente.user_id);
user_id := v_agente.user_id;
nombre_completo := v_agente.nombre_completo;
anios_antiguedad := v_agente.anios_actuales;
xp_otorgado := (100 * FLOOR(v_agente.anios_actuales - v_agente.anios_previos))::INTEGER;
RETURN NEXT;
END LOOP;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_auto_cleanup_deleted_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_dummy_email text;
BEGIN
  IF (NEW.is_deleted = true OR NEW.estado = 'eliminado') AND 
     (OLD.is_deleted IS DISTINCT FROM true OR OLD.estado IS DISTINCT FROM 'eliminado') THEN
    
    v_dummy_email := 'deleted-' || LEFT(NEW.id::text, 8) || '@deleted.local';
    NEW.email_laboral := v_dummy_email;
    NEW.email_personal := NULL;
    NEW.activo := false;
    NEW.estado := 'eliminado';
    NEW.is_deleted := true;

    -- Liberar en auth.users
    BEGIN
      UPDATE auth.users
      SET email = v_dummy_email, email_confirmed_at = NULL, updated_at = NOW()
      WHERE id = NEW.id;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING '[auto_cleanup_deleted_user] Error actualizando auth.users: %', SQLERRM;
    END;

    -- Limpiezas condicionales
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'tramites_grupos_miembros') THEN
      DELETE FROM public.tramites_grupos_miembros WHERE usuario_id = NEW.id;
    END IF;

    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'tramites_reglas_por_tipo') THEN
      DELETE FROM public.tramites_reglas_por_tipo WHERE usuario_id = NEW.id;
    END IF;

    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'sicas_mapeo_vendedor_usuario') THEN
      DELETE FROM public.sicas_mapeo_vendedor_usuario WHERE movi_user_id = NEW.id;
    END IF;

    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'vendor_mappings') THEN
      UPDATE public.vendor_mappings SET status = 'inactive', updated_at = NOW() WHERE movi_user_id = NEW.id AND status = 'active';
    END IF;

  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_calcular_anios_antiguedad(fecha_ingreso date)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
AS $function$
BEGIN
RETURN ROUND((CURRENT_DATE - fecha_ingreso)::NUMERIC / 365.25, 2);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_calcular_multiplicador_veterano(anios numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
BEGIN
-- 1.0 base + 0.02 por cada año
RETURN 1.0 + (anios * 0.02);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_calcular_nivel(xp_total integer)
 RETURNS TABLE(nivel integer, rango text)
 LANGUAGE plpgsql
 STABLE
AS $function$
BEGIN
RETURN QUERY
SELECT al.nivel, al.rango
FROM agent_levels al
WHERE xp_total >= al.xp_min
AND (al.xp_max IS NULL OR xp_total <= al.xp_max)
ORDER BY al.nivel DESC
LIMIT 1;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_calcular_progreso_modulo(p_user_id uuid, p_modulo_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user uuid := auth.uid(); v_total integer; v_completadas integer; v_porcentaje integer;
BEGIN
  IF v_user IS NULL OR (p_user_id IS NOT NULL AND p_user_id <> v_user) THEN
    RAISE EXCEPTION 'No autorizado' USING ERRCODE = '42501';
  END IF;
  SELECT COUNT(*) INTO v_total FROM cedula_a_lecciones WHERE modulo_id = p_modulo_id;
  SELECT COUNT(*) INTO v_completadas FROM cedula_a_progreso_lecciones pl JOIN cedula_a_lecciones l ON l.id = pl.leccion_id
  WHERE pl.user_id = v_user AND l.modulo_id = p_modulo_id AND pl.completado = true;
  v_porcentaje := CASE WHEN v_total > 0 THEN ROUND((v_completadas::numeric / v_total) * 100) ELSE 0 END;
  INSERT INTO cedula_a_progreso_modulos (user_id, modulo_id, lecciones_completadas, porcentaje_completado, updated_at)
  VALUES (v_user, p_modulo_id, v_completadas, v_porcentaje, now())
  ON CONFLICT (user_id, modulo_id) DO UPDATE SET
    lecciones_completadas = EXCLUDED.lecciones_completadas, porcentaje_completado = EXCLUDED.porcentaje_completado, updated_at = now(),
    fecha_completado = CASE WHEN EXCLUDED.porcentaje_completado = 100 THEN COALESCE(cedula_a_progreso_modulos.fecha_completado, now())
      ELSE cedula_a_progreso_modulos.fecha_completado END;
  RETURN v_porcentaje;
END; $function$
;

CREATE OR REPLACE FUNCTION public.fn_estadisticas_gamificacion()
 RETURNS TABLE(total_agentes integer, total_xp_otorgado bigint, total_jc_circulacion bigint, promedio_xp_agente numeric, promedio_jc_agente numeric, agentes_por_rango jsonb, eventos_ultimos_30_dias integer, misiones_completadas_mes integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
BEGIN
RETURN QUERY
SELECT
COUNT(DISTINCT agp.user_id)::INTEGER as total_agentes,
SUM(agp.xp_total)::BIGINT as total_xp_otorgado,
SUM(agp.jiro_coins_balance)::BIGINT as total_jc_circulacion,
ROUND(AVG(agp.xp_total), 2) as promedio_xp_agente,
ROUND(AVG(agp.jiro_coins_balance), 2) as promedio_jc_agente,
(
SELECT jsonb_object_agg(rango_actual, cuenta)
FROM (
SELECT rango_actual, COUNT(*) as cuenta
FROM agent_gamification_profile
GROUP BY rango_actual
) rangos
) as agentes_por_rango,
(
SELECT COUNT(*)::INTEGER
FROM agent_gamification_events
WHERE fecha_evento >= now() - INTERVAL '30 days'
) as eventos_ultimos_30_dias,
(
SELECT COUNT(*)::INTEGER
FROM agent_mission_progress
WHERE completada = true
AND fecha_completada >= DATE_TRUNC('month', CURRENT_DATE)
) as misiones_completadas_mes
FROM agent_gamification_profile agp;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_evaluar_examen(p_user_id uuid, p_examen_id uuid, p_respuestas jsonb, p_tiempo_minutos integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid(); v_intento_id uuid; v_certificado_id uuid;
  v_total_preguntas integer := 0; v_respuestas_correctas integer := 0; v_puntaje integer; v_aprobado boolean;
  v_puntaje_minimo integer; v_tipo_examen text; v_pregunta record; v_retroalimentacion jsonb := '[]'::jsonb; v_es_correcta boolean;
BEGIN
  IF v_user IS NULL OR (p_user_id IS NOT NULL AND p_user_id <> v_user) THEN
    RAISE EXCEPTION 'No autorizado' USING ERRCODE = '42501';
  END IF;
  SELECT tipo, puntaje_minimo_aprobacion INTO v_tipo_examen, v_puntaje_minimo FROM cedula_a_examenes WHERE id = p_examen_id;
  IF v_tipo_examen IS NULL THEN RAISE EXCEPTION 'Examen no encontrado'; END IF;
  FOR v_pregunta IN SELECT id, respuesta_correcta, explicacion, pregunta, opciones FROM cedula_a_preguntas WHERE examen_id = p_examen_id ORDER BY orden LOOP
    v_total_preguntas := v_total_preguntas + 1;
    v_es_correcta := (p_respuestas ->> v_pregunta.id::text) = v_pregunta.respuesta_correcta;
    IF v_es_correcta THEN v_respuestas_correctas := v_respuestas_correctas + 1; END IF;
    v_retroalimentacion := v_retroalimentacion || jsonb_build_object(
      'pregunta_id', v_pregunta.id, 'pregunta', v_pregunta.pregunta,
      'opciones', (SELECT COALESCE(jsonb_agg(jsonb_build_object('letra', chr(64 + o.idx::int), 'texto', o.texto) ORDER BY o.idx), '[]'::jsonb)
                   FROM jsonb_array_elements_text(v_pregunta.opciones) WITH ORDINALITY AS o(texto, idx)),
      'respuesta_usuario', p_respuestas -> v_pregunta.id::text, 'respuesta_correcta', v_pregunta.respuesta_correcta,
      'es_correcta', COALESCE(v_es_correcta, false), 'explicacion', v_pregunta.explicacion);
  END LOOP;
  v_puntaje := CASE WHEN v_total_preguntas > 0 THEN ROUND((v_respuestas_correctas::numeric / v_total_preguntas) * 100) ELSE 0 END;
  v_aprobado := v_puntaje >= COALESCE(v_puntaje_minimo, 80);
  INSERT INTO cedula_a_intentos_examen (user_id, examen_id, respuestas, puntaje, total_preguntas, aprobado, tiempo_empleado_minutos, fecha_intento)
  VALUES (v_user, p_examen_id, p_respuestas, v_puntaje, v_total_preguntas, v_aprobado, COALESCE(p_tiempo_minutos, 0), now())
  RETURNING id INTO v_intento_id;
  IF v_aprobado AND v_tipo_examen = 'final' THEN v_certificado_id := fn_generar_certificado(v_user, v_intento_id); END IF;
  RETURN jsonb_build_object('intento_id', v_intento_id, 'certificado_id', v_certificado_id, 'puntaje', v_puntaje,
    'total_preguntas', v_total_preguntas, 'respuestas_correctas', v_respuestas_correctas,
    'respuestas_incorrectas', v_total_preguntas - v_respuestas_correctas, 'aprobado', v_aprobado, 'retroalimentacion', v_retroalimentacion);
END; $function$
;

CREATE OR REPLACE FUNCTION public.fn_generar_certificado(p_user_id uuid, p_intento_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_certificado_id uuid; v_examen_id uuid; v_puntaje integer;
BEGIN
  SELECT examen_id, puntaje INTO v_examen_id, v_puntaje FROM cedula_a_intentos_examen
  WHERE id = p_intento_id AND user_id = p_user_id AND aprobado = true;
  IF v_examen_id IS NULL THEN RAISE EXCEPTION 'Intento no válido para certificado'; END IF;
  INSERT INTO cedula_a_certificados (user_id, examen_final_id, intento_id, puntaje_final, codigo_verificacion)
  VALUES (p_user_id, v_examen_id, p_intento_id, v_puntaje, 'CA-' || UPPER(substring(gen_random_uuid()::text, 1, 8)))
  RETURNING id INTO v_certificado_id;
  RETURN v_certificado_id;
END; $function$
;

CREATE OR REPLACE FUNCTION public.fn_historial_eventos(p_user_id uuid, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, tipo_evento gamification_event_type, xp_delta integer, jc_delta integer, xp_despues integer, jc_despues integer, fecha_evento timestamp with time zone, referencia_tipo text, referencia_id text, metadata jsonb, reversed_by_event_id uuid, is_reversal boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
BEGIN
RETURN QUERY
SELECT
age.id,
age.tipo_evento,
age.xp_delta,
age.jc_delta,
age.xp_despues,
age.jc_despues,
age.fecha_evento,
age.referencia_tipo,
age.referencia_id,
age.metadata,
age.reversed_by_event_id,
age.is_reversal
FROM agent_gamification_events age
WHERE age.user_id = p_user_id
ORDER BY age.fecha_evento DESC
LIMIT p_limit OFFSET p_offset;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_misiones_agente(p_user_id uuid)
 RETURNS TABLE(mission_id uuid, nombre text, descripcion text, tipo_periodo mission_period_type, xp_reward integer, jc_reward integer, icono text, color text, progreso_actual integer, meta_requerida integer, completada boolean, porcentaje_completado numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE
v_periodo TEXT;
BEGIN
RETURN QUERY
SELECT
am.id as mission_id,
am.nombre,
am.descripcion,
am.tipo_periodo,
am.xp_reward,
am.jc_reward,
am.icono,
am.color,
COALESCE(amp.progreso_actual, 0) as progreso_actual,
COALESCE((am.regla_json->>'cantidad')::INTEGER, 1) as meta_requerida,
COALESCE(amp.completada, false) as completada,
ROUND(
(COALESCE(amp.progreso_actual, 0)::NUMERIC / 
COALESCE((am.regla_json->>'cantidad')::INTEGER, 1)::NUMERIC * 100),
1
) as porcentaje_completado
FROM agent_missions am
LEFT JOIN agent_mission_progress amp ON (
amp.mission_id = am.id 
AND amp.user_id = p_user_id
AND amp.periodo = CASE am.tipo_periodo
WHEN 'semanal' THEN TO_CHAR(now(), 'IYYY-IW')
WHEN 'mensual' THEN TO_CHAR(now(), 'YYYY-MM')
WHEN 'unica' THEN 'unico'
ELSE 'permanente'
END
)
WHERE am.activa = true
ORDER BY am.orden, am.created_at;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_obtener_estadisticas_curso(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user uuid := COALESCE(p_user_id, auth.uid()); v_total_lecciones integer; v_lecciones_completadas integer;
BEGIN
  IF auth.uid() IS NULL OR (v_user <> auth.uid() AND NOT se_es_admin()) THEN
    RAISE EXCEPTION 'No autorizado' USING ERRCODE = '42501';
  END IF;
  SELECT COUNT(*) INTO v_total_lecciones FROM cedula_a_lecciones;
  SELECT COUNT(*) INTO v_lecciones_completadas FROM cedula_a_progreso_lecciones WHERE user_id = v_user AND completado = true;
  RETURN jsonb_build_object(
    'total_lecciones', v_total_lecciones, 'lecciones_completadas', v_lecciones_completadas,
    'total_modulos', (SELECT COUNT(*) FROM cedula_a_modulos),
    'modulos_completados', (SELECT COUNT(*) FROM cedula_a_progreso_modulos WHERE user_id = v_user AND porcentaje_completado = 100),
    'tiempo_total_segundos', (SELECT COALESCE(SUM(tiempo_estudio_segundos), 0) FROM cedula_a_progreso_lecciones WHERE user_id = v_user),
    'intentos_examenes', (SELECT COUNT(*) FROM cedula_a_intentos_examen WHERE user_id = v_user),
    'mejor_puntaje', (SELECT COALESCE(MAX(puntaje), 0) FROM cedula_a_intentos_examen WHERE user_id = v_user),
    'certificados', (SELECT COUNT(*) FROM cedula_a_certificados WHERE user_id = v_user),
    'porcentaje_global', CASE WHEN v_total_lecciones > 0 THEN ROUND((v_lecciones_completadas::numeric / v_total_lecciones) * 100) ELSE 0 END);
END; $function$
;

CREATE OR REPLACE FUNCTION public.fn_obtener_posicion_agente(p_user_id uuid)
 RETURNS TABLE(posicion_global bigint, posicion_oficina bigint, total_agentes bigint, total_agentes_oficina bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE
v_oficina_id UUID;
BEGIN
-- Obtener oficina del agente
SELECT oficina_id INTO v_oficina_id
FROM usuarios
WHERE id = p_user_id;

RETURN QUERY
WITH ranking_global AS (
SELECT
agp.user_id,
ROW_NUMBER() OVER (ORDER BY agp.xp_total DESC) as pos
FROM agent_gamification_profile agp
INNER JOIN usuarios u ON agp.user_id = u.id
WHERE u.rol = 'Agente' AND u.estado = 'Activo'
),
ranking_oficina AS (
SELECT
agp.user_id,
ROW_NUMBER() OVER (ORDER BY agp.xp_total DESC) as pos
FROM agent_gamification_profile agp
INNER JOIN usuarios u ON agp.user_id = u.id
WHERE u.rol = 'Agente' 
AND u.estado = 'Activo'
AND u.oficina_id = v_oficina_id
)
SELECT
rg.pos as posicion_global,
ro.pos as posicion_oficina,
(SELECT COUNT(*) FROM ranking_global) as total_agentes,
(SELECT COUNT(*) FROM ranking_oficina) as total_agentes_oficina
FROM ranking_global rg
LEFT JOIN ranking_oficina ro ON ro.user_id = rg.user_id
WHERE rg.user_id = p_user_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_procesar_expiracion_jc()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_evento RECORD;
v_total_expirados INTEGER := 0;
BEGIN
-- Encontrar eventos con JC que expiran hoy
FOR v_evento IN
SELECT
user_id,
jc_delta,
id,
referencia_tipo,
referencia_id
FROM agent_gamification_events
WHERE fecha_expiracion_jc IS NOT NULL
AND fecha_expiracion_jc <= now()
AND jc_delta > 0
AND reversed_by_event_id IS NULL
AND NOT EXISTS (
SELECT 1 FROM agent_gamification_events e2
WHERE e2.tipo_evento = 'expiracion_jc'
AND e2.metadata->>'evento_original' = v_evento.id::TEXT
)
LOOP
-- Registrar evento de expiración
PERFORM fn_registrar_evento_gamificacion(
v_evento.user_id,
'expiracion_jc',
0,
-v_evento.jc_delta,
'evento_expirado',
v_evento.id::TEXT,
false,
0,
jsonb_build_object(
'evento_original', v_evento.id,
'motivo', 'Expiración después de 6 meses'
)
);

v_total_expirados := v_total_expirados + 1;
END LOOP;

RETURN v_total_expirados;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_proximos_niveles(p_limit integer DEFAULT 20)
 RETURNS TABLE(user_id uuid, nombre_completo text, nivel_actual integer, xp_total integer, xp_para_siguiente integer, porcentaje_progreso numeric, siguiente_nivel integer, siguiente_rango text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
BEGIN
RETURN QUERY
SELECT
agp.user_id,
u.nombre_completo,
agp.nivel_actual,
agp.xp_total,
(al_siguiente.xp_min - agp.xp_total) as xp_para_siguiente,
ROUND(
((agp.xp_total - al_actual.xp_min)::NUMERIC / 
(al_siguiente.xp_min - al_actual.xp_min)::NUMERIC * 100),
1
) as porcentaje_progreso,
al_siguiente.nivel as siguiente_nivel,
al_siguiente.rango as siguiente_rango
FROM agent_gamification_profile agp
INNER JOIN usuarios u ON agp.user_id = u.id
INNER JOIN agent_levels al_actual ON agp.nivel_actual = al_actual.nivel
LEFT JOIN agent_levels al_siguiente ON al_siguiente.nivel = agp.nivel_actual + 1
WHERE u.rol = 'Agente'
AND u.estado = 'Activo'
AND al_siguiente.nivel IS NOT NULL
ORDER BY porcentaje_progreso DESC
LIMIT p_limit;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_ranking_global(p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS TABLE(posicion bigint, user_id uuid, nombre_completo text, oficina_nombre text, xp_total integer, nivel_actual integer, rango_actual text, jiro_coins_balance integer, total_polizas_emitidas integer, anios_antiguedad numeric)
 LANGUAGE plpgsql
 STABLE
AS $function$
BEGIN
RETURN QUERY
SELECT
ROW_NUMBER() OVER (ORDER BY agp.xp_total DESC) as posicion,
agp.user_id,
u.nombre_completo,
o.nombre as oficina_nombre,
agp.xp_total,
agp.nivel_actual,
agp.rango_actual,
agp.jiro_coins_balance,
agp.total_polizas_emitidas,
agp.anios_antiguedad
FROM agent_gamification_profile agp
INNER JOIN usuarios u ON agp.user_id = u.id
LEFT JOIN oficinas o ON u.oficina_id = o.id
WHERE u.rol = 'Agente'
AND LOWER(u.estado) = 'activo'
AND u.deleted_at IS NULL
ORDER BY agp.xp_total DESC
LIMIT p_limit OFFSET p_offset;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_ranking_jiro_coins(p_limit integer DEFAULT 20)
 RETURNS TABLE(posicion bigint, user_id uuid, nombre_completo text, oficina_nombre text, jiro_coins_balance integer, nivel_actual integer, rango_actual text)
 LANGUAGE plpgsql
 STABLE
AS $function$
BEGIN
RETURN QUERY
SELECT
ROW_NUMBER() OVER (ORDER BY agp.jiro_coins_balance DESC) as posicion,
agp.user_id,
u.nombre_completo,
o.nombre as oficina_nombre,
agp.jiro_coins_balance,
agp.nivel_actual,
agp.rango_actual
FROM agent_gamification_profile agp
INNER JOIN usuarios u ON agp.user_id = u.id
LEFT JOIN oficinas o ON u.oficina_id = o.id
WHERE u.rol = 'Agente'
AND LOWER(u.estado) = 'activo'
AND u.deleted_at IS NULL
AND agp.jiro_coins_balance > 0
ORDER BY agp.jiro_coins_balance DESC
LIMIT p_limit;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_ranking_oficina(p_oficina_id uuid, p_limit integer DEFAULT 20)
 RETURNS TABLE(posicion bigint, user_id uuid, nombre_completo text, xp_total integer, nivel_actual integer, rango_actual text, jiro_coins_balance integer, total_polizas_emitidas integer)
 LANGUAGE plpgsql
 STABLE
AS $function$
BEGIN
RETURN QUERY
SELECT
ROW_NUMBER() OVER (ORDER BY agp.xp_total DESC) as posicion,
agp.user_id,
u.nombre_completo,
agp.xp_total,
agp.nivel_actual,
agp.rango_actual,
agp.jiro_coins_balance,
agp.total_polizas_emitidas
FROM agent_gamification_profile agp
INNER JOIN usuarios u ON agp.user_id = u.id
WHERE u.rol = 'Agente'
AND LOWER(u.estado) = 'activo'
AND u.deleted_at IS NULL
AND u.oficina_id = p_oficina_id
ORDER BY agp.xp_total DESC
LIMIT p_limit;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_registrar_evento_gamificacion(p_user_id uuid, p_tipo_evento gamification_event_type, p_xp_delta integer DEFAULT 0, p_jc_delta integer DEFAULT 0, p_referencia_tipo text DEFAULT NULL::text, p_referencia_id text DEFAULT NULL::text, p_reversible boolean DEFAULT true, p_expiracion_dias integer DEFAULT 180, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_event_id UUID;
v_xp_antes INTEGER;
v_xp_despues INTEGER;
v_jc_antes INTEGER;
v_jc_despues INTEGER;
v_nuevo_nivel INTEGER;
v_nuevo_rango TEXT;
v_fecha_expiracion TIMESTAMPTZ;
BEGIN
-- Verificar que el usuario sea agente
IF NOT EXISTS (SELECT 1 FROM usuarios WHERE id = p_user_id AND rol = 'Agente') THEN
RAISE EXCEPTION 'El usuario no es agente';
END IF;

-- Crear perfil si no existe
INSERT INTO agent_gamification_profile (user_id)
VALUES (p_user_id)
ON CONFLICT (user_id) DO NOTHING;

-- Obtener valores actuales
SELECT xp_total, jiro_coins_balance
INTO v_xp_antes, v_jc_antes
FROM agent_gamification_profile
WHERE user_id = p_user_id;

-- Calcular nuevos valores
v_xp_despues := v_xp_antes + p_xp_delta;
v_jc_despues := v_jc_antes + p_jc_delta;

-- Calcular fecha de expiración para JC
IF p_jc_delta > 0 AND p_expiracion_dias > 0 THEN
v_fecha_expiracion := now() + (p_expiracion_dias || ' days')::INTERVAL;
END IF;

-- Registrar evento
INSERT INTO agent_gamification_events (
user_id,
tipo_evento,
referencia_tipo,
referencia_id,
xp_delta,
jc_delta,
xp_antes,
xp_despues,
jc_antes,
jc_despues,
fecha_evento,
fecha_expiracion_jc,
reversible,
metadata
) VALUES (
p_user_id,
p_tipo_evento,
p_referencia_tipo,
p_referencia_id,
p_xp_delta,
p_jc_delta,
v_xp_antes,
v_xp_despues,
v_jc_antes,
v_jc_despues,
now(),
v_fecha_expiracion,
p_reversible,
p_metadata
)
RETURNING id INTO v_event_id;

-- Calcular nuevo nivel
SELECT nivel, rango INTO v_nuevo_nivel, v_nuevo_rango
FROM fn_calcular_nivel(v_xp_despues);

-- Actualizar perfil
UPDATE agent_gamification_profile
SET
xp_total = v_xp_despues,
jiro_coins_balance = v_jc_despues,
nivel_actual = v_nuevo_nivel,
rango_actual = v_nuevo_rango,
updated_at = now()
WHERE user_id = p_user_id;

RETURN v_event_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_revertir_evento_gamificacion(p_event_id uuid, p_motivo text DEFAULT 'Cancelación'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_evento agent_gamification_events%ROWTYPE;
v_reversal_id UUID;
BEGIN
-- Obtener evento original
SELECT * INTO v_evento
FROM agent_gamification_events
WHERE id = p_event_id AND reversible = true AND reversed_by_event_id IS NULL;

IF NOT FOUND THEN
RAISE EXCEPTION 'Evento no encontrado o no reversible';
END IF;

-- Crear evento de reversa
v_reversal_id := fn_registrar_evento_gamificacion(
v_evento.user_id,
'cancelacion',
-v_evento.xp_delta,
-v_evento.jc_delta,
v_evento.referencia_tipo,
v_evento.referencia_id,
false,
0,
jsonb_build_object(
'motivo', p_motivo,
'evento_original', p_event_id
)
);

-- Marcar evento original como revertido
UPDATE agent_gamification_events
SET
reversed_by_event_id = v_reversal_id,
metadata = metadata || jsonb_build_object('revertido', true, 'motivo', p_motivo)
WHERE id = p_event_id;

RETURN v_reversal_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_verificar_misiones_usuario(p_user_id uuid, p_tipo_evento gamification_event_type)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_mision RECORD;
BEGIN
-- Buscar misiones activas que correspondan al tipo de evento
FOR v_mision IN
SELECT id, regla_json
FROM agent_missions
WHERE activa = true
AND (
(p_tipo_evento = 'poliza_emitida' AND regla_json->>'tipo' = 'polizas_emitidas')
OR (p_tipo_evento = 'curso_completado' AND regla_json->>'tipo' = 'cursos_completados')
OR (p_tipo_evento = 'renovacion' AND regla_json->>'tipo' = 'renovaciones')
OR (p_tipo_evento = 'prospecto' AND regla_json->>'tipo' = 'prospectos')
)
LOOP
PERFORM fn_actualizar_progreso_mision(p_user_id, v_mision.id, 1);
END LOOP;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.folio_iniciales(p_nombre text, p_apellidos text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  palabra text;
  res text := '';
BEGIN
  FOREACH palabra IN ARRAY regexp_split_to_array(
    trim(public.folio_normaliza(coalesce(p_nombre, '') || ' ' || coalesce(p_apellidos, ''))), '\s+')
  LOOP
    IF palabra <> '' THEN
      res := res || substring(palabra from 1 for 1);
    END IF;
    EXIT WHEN length(res) >= 3;
  END LOOP;
  RETURN rpad(res, 3, 'X');
END $function$
;

CREATE OR REPLACE FUNCTION public.folio_legible(p_prefijo text, p_consecutivo bigint, p_usuario_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  u record;
BEGIN
  SELECT us.nombre, us.apellidos, o.nombre AS oficina
    INTO u
    FROM usuarios us
    LEFT JOIN oficinas o ON o.id = us.oficina_id
   WHERE us.id = p_usuario_id;

  RETURN p_prefijo
      || '-' || lpad(p_consecutivo::text, 5, '0')
      || '-' || folio_siglas(coalesce(u.oficina, 'SIN'), 3)
      || '-' || folio_iniciales(u.nombre, u.apellidos);
END $function$
;

CREATE OR REPLACE FUNCTION public.folio_normaliza(p_texto text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT upper(regexp_replace(
    translate(coalesce(p_texto, ''),
      'áéíóúüñÁÉÍÓÚÜÑàèìòùÀÈÌÒÙâêîôûÂÊÎÔÛäëïöÄËÏÖçÇ',
      'aeiouunAEIOUUNaeiouAEIOUaeiouAEIOUaeioAEIOcC'),
    '[^A-Za-z ]', '', 'g'));
$function$
;

CREATE OR REPLACE FUNCTION public.folio_siglas(p_texto text, p_largo integer)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT rpad(
    substring(replace(public.folio_normaliza(p_texto), ' ', '') from 1 for p_largo),
    p_largo, 'X');
$function$
;

CREATE OR REPLACE FUNCTION public.form_type_to_slug(p_form_type text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN CASE p_form_type
WHEN 'auto_individual' THEN 'auto'
WHEN 'auto_residente' THEN 'auto-res'
WHEN 'flotilla_autos' THEN 'flotilla'
WHEN 'gmm_individual' THEN 'gmm'
WHEN 'gmm_colectivo_empresarial' THEN 'gmm-col'
WHEN 'vida_individual' THEN 'vida'
WHEN 'vida_grupo_colectivo' THEN 'vida-grupo'
WHEN 'ap_individual' THEN 'ap'
WHEN 'ap_colectivo' THEN 'ap-col'
WHEN 'accidentes_personales_individual' THEN 'ap'
WHEN 'salud_gastos_menores' THEN 'salud'
WHEN 'dental_vision' THEN 'dental'
WHEN 'hogar_casa_habitacion' THEN 'hogar'
WHEN 'empresa_paquete' THEN 'empresa'
WHEN 'empresa_paquete_empresarial' THEN 'empresa'
WHEN 'pyme_comercio' THEN 'pyme'
WHEN 'rc_general' THEN 'rc-gen'
WHEN 'rc_productos' THEN 'rc-prod'
WHEN 'rc_profesional' THEN 'rc-prof'
WHEN 'rc_transportistas' THEN 'rc-trans'
WHEN 'fianzas' THEN 'fianzas'
WHEN 'caucion' THEN 'caucion'
WHEN 'credito_comercial' THEN 'credito'
WHEN 'cyber_riesgos_ciberneticos' THEN 'cyber'
WHEN 'd_o' THEN 'do'
WHEN 'responsabilidad_laboral' THEN 'resp-lab'
WHEN 'fidelidad_empleados' THEN 'fidelidad'
WHEN 'crime_empresarial' THEN 'crime'
WHEN 'transporte_carga' THEN 'transp'
WHEN 'transporte_maritimo' THEN 'maritimo'
WHEN 'transporte_valores' THEN 'valores'
WHEN 'obra_civil' THEN 'obra'
WHEN 'todo_riesgo_construccion' THEN 'construc'
WHEN 'equipo_contratistas' THEN 'eq-cont'
WHEN 'maquinaria_equipo_electronico' THEN 'maq-elec'
WHEN 'calderas_maquinas' THEN 'calderas'
WHEN 'seguro_agricola' THEN 'agricola'
WHEN 'seguro_ganadero' THEN 'ganadero'
WHEN 'maquinaria_agricola' THEN 'maq-agri'
WHEN 'eventos' THEN 'evento'
WHEN 'mascotas' THEN 'mascota'
WHEN 'arrendamiento' THEN 'arrend'
WHEN 'condominal' THEN 'condom'
WHEN 'obras_arte' THEN 'arte'
WHEN 'incendio' THEN 'incendio'
WHEN 'equipo_electronico' THEN 'eq-elec'
WHEN 'aviacion' THEN 'aviacion'
ELSE regexp_replace(substring(p_form_type from 1 for 15), '_', '-', 'g')
END;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generar_folio_oc()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
folio text;
existe boolean;
intentos integer := 0;
max_intentos integer := 100;
BEGIN
LOOP
-- Generar folio alfanumérico de 8 caracteres (mayúsculas y números)
folio := upper(
substring(md5(random()::text || clock_timestamp()::text) from 1 for 8)
);

-- Verificar si existe
SELECT EXISTS(
SELECT 1 FROM store_pedidos WHERE folio_oc = folio
) INTO existe;

EXIT WHEN NOT existe;

intentos := intentos + 1;
IF intentos >= max_intentos THEN
RAISE EXCEPTION 'No se pudo generar folio único después de % intentos', max_intentos;
END IF;
END LOOP;

RETURN folio;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generar_folio_oc(p_usuario_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  folio text;
  intentos integer := 0;
BEGIN
  LOOP
    folio := folio_legible('ARTMKT', nextval('folio_artmkt_seq'), p_usuario_id);
    EXIT WHEN NOT EXISTS (SELECT 1 FROM store_pedidos WHERE folio_oc = folio);
    intentos := intentos + 1;
    IF intentos >= 100 THEN
      RAISE EXCEPTION 'No se pudo generar un folio de OC único después de 100 intentos';
    END IF;
  END LOOP;
  RETURN folio;
END $function$
;

CREATE OR REPLACE FUNCTION public.generar_folio_premium(p_usuario_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  folio text;
  intentos integer := 0;
BEGIN
  LOOP
    folio := folio_legible('MKTPRMM', nextval('folio_mktprmm_seq'), p_usuario_id);
    EXIT WHEN NOT EXISTS (SELECT 1 FROM usuarios WHERE mkt_premium_folio = folio);
    intentos := intentos + 1;
    IF intentos >= 100 THEN
      RAISE EXCEPTION 'No se pudo generar un folio de Premium único después de 100 intentos';
    END IF;
  END LOOP;
  RETURN folio;
END $function$
;

CREATE OR REPLACE FUNCTION public.generar_folio_ticket()
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
nuevo_folio text;
existe boolean;
BEGIN
LOOP
-- Generar folio de 6 caracteres alfanuméricos (TK + 5 caracteres)
nuevo_folio := 'TK' || upper(substring(md5(random()::text) from 1 for 5));

-- Verificar si ya existe
SELECT EXISTS(SELECT 1 FROM tickets WHERE folio = nuevo_folio) INTO existe;

EXIT WHEN NOT existe;
END LOOP;

RETURN nuevo_folio;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_gmm_folio()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_year  int  := EXTRACT(YEAR FROM now())::int;
v_seq   int;
BEGIN
INSERT INTO gmm_folio_counters (year, last_seq)
VALUES (v_year, 1)
ON CONFLICT (year) DO UPDATE
SET last_seq = gmm_folio_counters.last_seq + 1
RETURNING last_seq INTO v_seq;

RETURN 'GMM-' || v_year || '-' || lpad(v_seq::text, 5, '0');
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_link_code(p_length integer DEFAULT 7)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
chars text := 'abcdefghijklmnopqrstuvwxyz0123456789';
result text := '';
i integer;
BEGIN
FOR i IN 1..p_length LOOP
result := result || substr(chars, floor(random() * length(chars) + 1)::integer, 1);
END LOOP;
RETURN result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_multicotizador_gmm_folio()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_year integer := EXTRACT(YEAR FROM now())::integer;
v_number integer;
BEGIN
INSERT INTO multicotizador_gmm_folio_counter (year, last_number)
VALUES (v_year, 1)
ON CONFLICT (year)
DO UPDATE SET last_number = multicotizador_gmm_folio_counter.last_number + 1
RETURNING last_number INTO v_number;

RETURN 'MGMM-' || v_year || '-' || LPAD(v_number::text, 5, '0');
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_next_folio()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
current_year integer := EXTRACT(YEAR FROM CURRENT_DATE)::integer;
seed_number integer := 0;
next_number integer;
new_folio text;
existing_max text;
BEGIN
IF NOT EXISTS (SELECT 1 FROM ticket_folio_counters WHERE year = current_year) THEN
SELECT folio INTO existing_max
FROM tickets
WHERE tipo_tramite = 'registro_actividad'
AND folio LIKE 'RA-' || current_year || '-%'
ORDER BY folio DESC
LIMIT 1;

IF existing_max IS NOT NULL THEN
seed_number := COALESCE(
CAST(SUBSTRING(existing_max FROM 'RA-[0-9]{4}-([0-9]+)') AS integer),
0
);
END IF;

INSERT INTO ticket_folio_counters (year, last_number)
VALUES (current_year, seed_number)
ON CONFLICT (year) DO NOTHING;
END IF;

UPDATE ticket_folio_counters
SET last_number = last_number + 1,
updated_at = now()
WHERE year = current_year
RETURNING last_number INTO next_number;

new_folio := 'RA-' || current_year || '-' || LPAD(next_number::text, 4, '0');

WHILE EXISTS (SELECT 1 FROM tickets WHERE folio = new_folio) LOOP
UPDATE ticket_folio_counters
SET last_number = last_number + 1,
updated_at = now()
WHERE year = current_year
RETURNING last_number INTO next_number;

new_folio := 'RA-' || current_year || '-' || LPAD(next_number::text, 4, '0');
END LOOP;

RETURN new_folio;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_quote_form_folio()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
today_str text;
seq_num int;
new_folio text;
BEGIN
today_str := to_char(now(), 'YYYYMMDD');

SELECT COALESCE(MAX(
CASE
WHEN folio ~ ('^COT-' || today_str || '-\d{4}$')
THEN (substring(folio from '\d{4}$'))::int
ELSE 0
END
), 0) + 1
INTO seq_num
FROM quote_forms
WHERE folio LIKE 'COT-' || today_str || '-%';

new_folio := 'COT-' || today_str || '-' || lpad(seq_num::text, 4, '0');
RETURN new_folio;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_quote_number()
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
v_year text;
v_count int;
v_number text;
BEGIN
v_year := TO_CHAR(NOW(), 'YYYY');

SELECT COUNT(*) + 1 INTO v_count
FROM gmm_quotes
WHERE EXTRACT(YEAR FROM created_at) = EXTRACT(YEAR FROM NOW());

v_number := 'BXP-' || v_year || '-' || LPAD(v_count::text, 5, '0');

RETURN v_number;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_sicas_agent_alerts(p_usuario_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_alerts_created integer := 0;
v_vendor_id text;
v_oficina_id uuid;
BEGIN
-- Use same helper as dashboard
v_vendor_id := get_sicas_user_vend_id(p_usuario_id);

IF v_vendor_id IS NULL THEN
RETURN jsonb_build_object('success', false, 'error', 'No vendor mapping');
END IF;

SELECT oficina_id INTO v_oficina_id FROM usuarios WHERE id = p_usuario_id;

-- Clear old unresolved alerts older than 90 days
DELETE FROM sicas_agent_alerts
WHERE usuario_id = p_usuario_id
AND status = 'new'
AND created_at < now() - interval '90 days';

-- Alert: Renewals within 15 days (HIGH priority)
INSERT INTO sicas_agent_alerts (usuario_id, sicas_vendor_id, oficina_id, alert_type, priority, title, description, client_name, document_id, policy_number, due_date, recommended_action, related_data)
SELECT
p_usuario_id, v_vendor_id, v_oficina_id, 'renewal_upcoming', 'high',
'Renovacion urgente: ' || d.cliente,
'La poliza ' || coalesce(d.poliza, d.id_docto) || ' de ' || d.compania || ' vence en ' || 
extract(day from d.vigencia_hasta - now())::integer || ' dias.',
d.cliente, d.id_docto, d.poliza, d.vigencia_hasta::date,
'Contactar al cliente para asegurar la renovacion.',
jsonb_build_object('ramo', d.ramo, 'aseguradora', d.compania, 'prima_neta', d.prima_neta)
FROM sicas_documents d
WHERE d.vend_id = v_vendor_id
AND d.is_vigente = true
AND d.vigencia_hasta BETWEEN now() AND now() + interval '15 days'
AND NOT EXISTS (
SELECT 1 FROM sicas_agent_alerts a
WHERE a.usuario_id = p_usuario_id
AND a.document_id = d.id_docto
AND a.alert_type = 'renewal_upcoming'
AND a.created_at > now() - interval '30 days'
);
GET DIAGNOSTICS v_alerts_created = ROW_COUNT;

-- Alert: Renewals 15-30 days (MEDIUM priority)
INSERT INTO sicas_agent_alerts (usuario_id, sicas_vendor_id, oficina_id, alert_type, priority, title, description, client_name, document_id, policy_number, due_date, recommended_action, related_data)
SELECT
p_usuario_id, v_vendor_id, v_oficina_id, 'renewal_upcoming', 'medium',
'Renovacion proxima: ' || d.cliente,
'La poliza ' || coalesce(d.poliza, d.id_docto) || ' vence el ' || to_char(d.vigencia_hasta, 'DD/MM/YYYY') || '.',
d.cliente, d.id_docto, d.poliza, d.vigencia_hasta::date,
'Programar contacto con el cliente.',
jsonb_build_object('ramo', d.ramo, 'aseguradora', d.compania, 'prima_neta', d.prima_neta)
FROM sicas_documents d
WHERE d.vend_id = v_vendor_id
AND d.is_vigente = true
AND d.vigencia_hasta BETWEEN now() + interval '15 days' AND now() + interval '30 days'
AND NOT EXISTS (
SELECT 1 FROM sicas_agent_alerts a
WHERE a.usuario_id = p_usuario_id
AND a.document_id = d.id_docto
AND a.alert_type = 'renewal_upcoming'
AND a.created_at > now() - interval '30 days'
);

-- Alert: Expired policies recoverable (< 90 days)
INSERT INTO sicas_agent_alerts (usuario_id, sicas_vendor_id, oficina_id, alert_type, priority, title, description, client_name, document_id, policy_number, due_date, recommended_action, related_data)
SELECT
p_usuario_id, v_vendor_id, v_oficina_id, 'recoverable_policy', 'high',
'Poliza vencida recuperable: ' || d.cliente,
'La poliza ' || coalesce(d.poliza, d.id_docto) || ' vencio hace ' || 
extract(day from now() - d.vigencia_hasta)::integer || ' dias. Aun se puede recuperar.',
d.cliente, d.id_docto, d.poliza, d.vigencia_hasta::date,
'Contactar al cliente para reactivar la poliza.',
jsonb_build_object('ramo', d.ramo, 'aseguradora', d.compania, 'prima_neta', d.prima_neta)
FROM sicas_documents d
WHERE d.vend_id = v_vendor_id
AND d.is_vigente = false
AND d.vigencia_hasta BETWEEN now() - interval '90 days' AND now()
AND NOT EXISTS (
SELECT 1 FROM sicas_agent_alerts a
WHERE a.usuario_id = p_usuario_id
AND a.document_id = d.id_docto
AND a.alert_type = 'recoverable_policy'
AND a.created_at > now() - interval '30 days'
);

-- Alert: High-value renewals (top premium policies renewing soon)
INSERT INTO sicas_agent_alerts (usuario_id, sicas_vendor_id, oficina_id, alert_type, priority, title, description, client_name, document_id, policy_number, due_date, recommended_action, related_data)
SELECT
p_usuario_id, v_vendor_id, v_oficina_id, 'high_value_renewal', 'high',
'Renovacion de alta prima: ' || d.cliente,
'Poliza con prima de $' || to_char(d.prima_neta, 'FM999,999,999') || ' vence el ' || to_char(d.vigencia_hasta, 'DD/MM/YYYY') || '.',
d.cliente, d.id_docto, d.poliza, d.vigencia_hasta::date,
'Dar seguimiento prioritario a esta renovacion de alta prima.',
jsonb_build_object('ramo', d.ramo, 'aseguradora', d.compania, 'prima_neta', d.prima_neta)
FROM sicas_documents d
WHERE d.vend_id = v_vendor_id
AND d.is_vigente = true
AND d.vigencia_hasta BETWEEN now() AND now() + interval '60 days'
AND d.prima_neta > (
SELECT percentile_cont(0.8) WITHIN GROUP (ORDER BY prima_neta)
FROM sicas_documents WHERE vend_id = v_vendor_id AND is_vigente = true AND prima_neta > 0
)
AND NOT EXISTS (
SELECT 1 FROM sicas_agent_alerts a
WHERE a.usuario_id = p_usuario_id
AND a.document_id = d.id_docto
AND a.alert_type = 'high_value_renewal'
AND a.created_at > now() - interval '30 days'
);

RETURN jsonb_build_object('success', true, 'alerts_created', v_alerts_created);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_ticket_notification_url()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
IF NEW.titulo LIKE '%trámite%' AND NEW.accion_url IS NULL THEN
DECLARE
folio_match TEXT;
ticket_id_found UUID;
BEGIN
folio_match := (regexp_matches(NEW.mensaje, 'TK[A-Z0-9]+'))[1];

IF folio_match IS NOT NULL THEN
SELECT id INTO ticket_id_found
FROM tickets
WHERE folio = folio_match
LIMIT 1;

IF ticket_id_found IS NOT NULL THEN
NEW.accion_url := 'https://app.movi.digital/tramites/' || ticket_id_found;
END IF;
END IF;
END;
END IF;

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_active_fiscal_rule(p_regimen text, p_fecha date DEFAULT CURRENT_DATE)
 RETURNS TABLE(rule_id uuid, regimen_codigo text, nombre_regimen text, version text, vigente_desde date, vigente_hasta date)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
SELECT
id,
regimen_codigo,
nombre_regimen,
version,
vigente_desde,
vigente_hasta
FROM fiscal_regime_rules
WHERE regimen_codigo = lower(p_regimen)
AND activo = true
AND estado = 'activo'
AND vigente_desde <= p_fecha
AND (vigente_hasta IS NULL OR vigente_hasta >= p_fecha)
ORDER BY vigente_desde DESC
LIMIT 1;
$function$
;

CREATE OR REPLACE FUNCTION public.get_active_seguwallet_terms()
 RETURNS TABLE(id uuid, title text, content text, version text, published_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN QUERY
SELECT t.id, t.title, t.content, t.version, t.published_at
FROM seguwallet_terms t
WHERE t.is_active = true
LIMIT 1;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_activity_kpis()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
result jsonb;
v_caller_role text;
BEGIN
SELECT rol INTO v_caller_role FROM usuarios WHERE id = auth.uid();
IF v_caller_role != 'Administrador' THEN
RETURN jsonb_build_object('error', 'Unauthorized');
END IF;

SELECT jsonb_build_object(
'active_today', (
SELECT COUNT(DISTINCT user_id) FROM unified_activity_view
WHERE created_at >= CURRENT_DATE
),
'active_this_week', (
SELECT COUNT(DISTINCT user_id) FROM unified_activity_view
WHERE created_at >= date_trunc('week', CURRENT_DATE)
),
'active_this_month', (
SELECT COUNT(DISTINCT user_id) FROM unified_activity_view
WHERE created_at >= date_trunc('month', CURRENT_DATE)
),
'total_logins_today', (
SELECT COUNT(*) FROM unified_activity_view
WHERE created_at >= CURRENT_DATE AND action = 'login'
),
'total_logins_week', (
SELECT COUNT(*) FROM unified_activity_view
WHERE created_at >= date_trunc('week', CURRENT_DATE) AND action = 'login'
),
'inactive_users', (
SELECT COUNT(*) FROM usuarios u
WHERE u.activo = true AND u.rol != 'Administrador'
AND NOT EXISTS (
SELECT 1 FROM unified_activity_view al
WHERE al.user_id = u.id AND al.created_at >= CURRENT_DATE - interval '30 days'
)
),
'profile_changes_month', (
SELECT COUNT(*) FROM unified_activity_view
WHERE created_at >= date_trunc('month', CURRENT_DATE) AND event_type = 'profile'
),
'publicity_created_month', (
SELECT COUNT(*) FROM unified_activity_view
WHERE created_at >= date_trunc('month', CURRENT_DATE) AND module = 'publicidad'
),
'courses_started_month', (
SELECT COUNT(*) FROM unified_activity_view
WHERE created_at >= date_trunc('month', CURRENT_DATE) AND action = 'course_start'
),
'courses_completed_month', (
SELECT COUNT(*) FROM unified_activity_view
WHERE created_at >= date_trunc('month', CURRENT_DATE) AND action = 'course_complete'
),
'tramites_responded_month', (
SELECT COUNT(*) FROM unified_activity_view
WHERE created_at >= date_trunc('month', CURRENT_DATE) AND module = 'tramites'
),
'crm_actions_month', (
SELECT COUNT(*) FROM unified_activity_view
WHERE created_at >= date_trunc('month', CURRENT_DATE) AND module = 'crm'
),
'total_events_today', (
SELECT COUNT(*) FROM unified_activity_view WHERE created_at >= CURRENT_DATE
),
'total_events_month', (
SELECT COUNT(*) FROM unified_activity_view WHERE created_at >= date_trunc('month', CURRENT_DATE)
)
) INTO result;

RETURN result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_activity_logs(p_user_id_filter uuid DEFAULT NULL::uuid, p_office_id_filter uuid DEFAULT NULL::uuid, p_role_filter text DEFAULT NULL::text, p_module_filter text DEFAULT NULL::text, p_event_type_filter text DEFAULT NULL::text, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_caller_role text;
result jsonb;
total_count int;
BEGIN
SELECT rol INTO v_caller_role FROM usuarios WHERE id = auth.uid();
IF v_caller_role != 'Administrador' THEN
RETURN jsonb_build_object('error', 'Unauthorized');
END IF;

-- Count total matching records
SELECT COUNT(*) INTO total_count
FROM unified_activity_view al
WHERE (p_user_id_filter IS NULL OR al.user_id = p_user_id_filter)
AND (p_office_id_filter IS NULL OR al.office_id = p_office_id_filter)
AND (p_role_filter IS NULL OR al.role_snapshot = p_role_filter)
AND (p_module_filter IS NULL OR al.module = p_module_filter)
AND (p_event_type_filter IS NULL OR al.event_type = p_event_type_filter)
AND (p_date_from IS NULL OR al.created_at >= p_date_from)
AND (p_date_to IS NULL OR al.created_at <= p_date_to)
AND (p_search IS NULL OR p_search = '' OR
al.summary ILIKE '%' || p_search || '%' OR
al.user_name_snapshot ILIKE '%' || p_search || '%' OR
al.email_snapshot ILIKE '%' || p_search || '%' OR
al.action ILIKE '%' || p_search || '%'
);

-- Get paginated results
SELECT jsonb_build_object(
'total', total_count,
'logs', COALESCE((
SELECT jsonb_agg(row_to_json(r))
FROM (
SELECT
al.id, al.user_id, al.user_name_snapshot, al.email_snapshot,
al.office_id, al.office_name_snapshot, al.role_snapshot,
al.module, al.event_type, al.action, al.entity_type, al.entity_id,
al.summary, al.details, al.metadata, al.status, al.created_at
FROM unified_activity_view al
WHERE (p_user_id_filter IS NULL OR al.user_id = p_user_id_filter)
AND (p_office_id_filter IS NULL OR al.office_id = p_office_id_filter)
AND (p_role_filter IS NULL OR al.role_snapshot = p_role_filter)
AND (p_module_filter IS NULL OR al.module = p_module_filter)
AND (p_event_type_filter IS NULL OR al.event_type = p_event_type_filter)
AND (p_date_from IS NULL OR al.created_at >= p_date_from)
AND (p_date_to IS NULL OR al.created_at <= p_date_to)
AND (p_search IS NULL OR p_search = '' OR
al.summary ILIKE '%' || p_search || '%' OR
al.user_name_snapshot ILIKE '%' || p_search || '%' OR
al.email_snapshot ILIKE '%' || p_search || '%' OR
al.action ILIKE '%' || p_search || '%'
)
ORDER BY al.created_at DESC
LIMIT p_limit OFFSET p_offset
) r
), '[]'::jsonb)
) INTO result;

RETURN result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_admin_tramites_attention_count()
 RETURNS bigint
 LANGUAGE sql
 STABLE
AS $function$
  SELECT COUNT(*)::bigint FROM tickets t
  WHERE t.eliminado_at IS NULL
    AND t.cerrado_en IS NULL
    AND (
      t.requiere_atencion_manual
      OR (
        t.ultima_accion_por IS NOT NULL
        AND (t.ultima_accion_por = t.agente_id OR t.ultima_accion_por = t.agente_usuario_id)
        AND t.agente_id IS DISTINCT FROM auth.uid()
        AND t.agente_usuario_id IS DISTINCT FROM auth.uid()
      )
    );
$function$
;

