CREATE OR REPLACE FUNCTION public.get_agenda_available_slots(p_event_type_id uuid, p_date date)
 RETURNS TABLE(start_at timestamp with time zone, end_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$declare v_event agenda_event_types%rowtype;v_calendar agenda_calendars%rowtype;v_rule agenda_availability_rules%rowtype;v_cursor timestamptz;v_end timestamptz;v_day_count integer;begin select * into v_event from agenda_event_types where id=p_event_type_id and is_active;if not found then return;end if;select * into v_calendar from agenda_calendars where id=v_event.calendar_id and is_active;if not found then return;end if;if exists(select 1 from agenda_availability_exceptions where calendar_id=v_calendar.id and exception_date=p_date and is_full_day) then return;end if;select count(*) into v_day_count from agenda_bookings b where b.event_type_id=p_event_type_id and b.status='confirmed' and (b.start_at at time zone v_calendar.timezone)::date=p_date;if v_event.daily_limit is not null and v_day_count>=v_event.daily_limit then return;end if;for v_rule in select * from agenda_availability_rules where calendar_id=v_calendar.id and weekday=extract(dow from p_date)::int and is_active loop v_cursor:=(p_date+v_rule.start_time) at time zone v_calendar.timezone;v_end:=(p_date+v_rule.end_time) at time zone v_calendar.timezone;while v_cursor+make_interval(mins=>v_event.duration_minutes)<=v_end loop if v_cursor>=now()+make_interval(mins=>v_event.min_notice_minutes) and not exists(select 1 from agenda_bookings b where b.event_type_id in(select id from agenda_event_types where calendar_id=v_calendar.id) and b.status='confirmed' and tstzrange(b.start_at-make_interval(mins=>v_event.buffer_before_minutes),b.end_at+make_interval(mins=>v_event.buffer_after_minutes),'[)')&&tstzrange(v_cursor,v_cursor+make_interval(mins=>v_event.duration_minutes),'[)')) then start_at:=v_cursor;end_at:=v_cursor+make_interval(mins=>v_event.duration_minutes);return next;end if;v_cursor:=v_cursor+interval '15 minutes';end loop;end loop;end$function$
;

CREATE OR REPLACE FUNCTION public.get_agent_brand_config(p_agent_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_user RECORD;
v_office RECORD;
v_web RECORD;
v_brand jsonb;
v_primary text;
v_secondary text;
BEGIN
SELECT nombre, apellidos, oficina_id, nombre_publico,
mi_logotipo_url, imagen_perfil_url, web_slug, celular_laboral
INTO v_user
FROM usuarios
WHERE id = p_agent_id;

IF v_user.oficina_id IS NOT NULL THEN
SELECT nombre, logo_url, accent_color INTO v_office
FROM oficinas WHERE id = v_user.oficina_id;
END IF;

SELECT primary_color, secondary_color INTO v_web
FROM user_web_pages WHERE user_id = p_agent_id LIMIT 1;

-- Color priority: web_pages > office > default
v_primary := COALESCE(v_web.primary_color, v_office.accent_color, '#2563eb');
v_secondary := COALESCE(v_web.secondary_color, '#1e40af');

v_brand := jsonb_build_object(
'agent_name',         COALESCE(v_user.nombre_publico, v_user.nombre || ' ' || COALESCE(v_user.apellidos, '')),
'office_name',        COALESCE(v_office.nombre, ''),
'primary_color',      v_primary,
'secondary_color',    v_secondary,
'logo_url',           COALESCE(v_user.mi_logotipo_url, v_office.logo_url, '/logojiro.png'),
'profile_image_url',  v_user.imagen_perfil_url,
'agent_slug',         v_user.web_slug,
'agent_whatsapp',     v_user.celular_laboral,
'footer_text',        'Formulario enviado a través de MOVI Digital.'
);

RETURN v_brand;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_agent_brand_for_seguwallet(p_agent_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_user        RECORD;
v_office      RECORD;
v_web_page    RECORD;
v_logo_url    text;
v_primary     text;
v_secondary   text;
BEGIN
-- Load agent data
SELECT
u.nombre,
u.apellidos,
u.nombre_publico,
u.celular_laboral,
u.email_laboral,
u.imagen_perfil_url,
u.mi_logotipo_url,
u.web_slug,
u.oficina_id
INTO v_user
FROM usuarios u
WHERE u.id = p_agent_id
AND u.activo = true;

IF NOT FOUND THEN
RETURN jsonb_build_object(
'logo_url',         null,
'profile_image_url',null,
'primary_color',    '#1C37E0',
'secondary_color',  '#1228B8',
'agent_name',       'Tu Agente',
'office_name',      null,
'phone',            null,
'email',            null,
'web_slug',         null
);
END IF;

-- Load office data if agent belongs to one
IF v_user.oficina_id IS NOT NULL THEN
SELECT o.nombre, o.logo_url
INTO v_office
FROM oficinas o
WHERE o.id = v_user.oficina_id;
END IF;

-- Load Mi Pagina Web config for colors
SELECT uwp.primary_color, uwp.secondary_color
INTO v_web_page
FROM user_web_pages uwp
WHERE uwp.user_id = p_agent_id
LIMIT 1;

-- Logo priority: agent Mi Marca → office logo → null (frontend shows Seguwallet logo)
v_logo_url := COALESCE(
NULLIF(trim(v_user.mi_logotipo_url), ''),
NULLIF(trim(v_office.logo_url), ''),
null
);

-- Color priority: Mi Pagina Web → Seguwallet default
v_primary   := COALESCE(NULLIF(trim(v_web_page.primary_color), ''),   '#1C37E0');
v_secondary := COALESCE(NULLIF(trim(v_web_page.secondary_color), ''), '#1228B8');

RETURN jsonb_build_object(
'logo_url',         v_logo_url,
'profile_image_url',NULLIF(trim(v_user.imagen_perfil_url), ''),
'primary_color',    v_primary,
'secondary_color',  v_secondary,
'agent_name',       COALESCE(
NULLIF(trim(v_user.nombre_publico), ''),
trim(v_user.nombre || ' ' || COALESCE(v_user.apellidos, ''))
),
'office_name',      NULLIF(trim(v_office.nombre), ''),
'phone',            NULLIF(trim(v_user.celular_laboral), ''),
'email',            NULLIF(trim(v_user.email_laboral), ''),
'web_slug',         NULLIF(trim(v_user.web_slug), '')
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_agent_grouping(batch_id_param uuid)
 RETURNS TABLE(agent_key text, agent_name_raw text, doc_count bigint, match_status text, matched_user_id uuid, matched_user_name text, confidence integer, sample_polizas text[])
 LANGUAGE plpgsql
AS $function$
BEGIN
RETURN QUERY
SELECT 
id.agent_key,
id.agent_name_raw,
COUNT(*)::BIGINT AS doc_count,
id.match_status,
id.movi_user_id,
u.nombre_completo,
id.match_confidence,
ARRAY(
SELECT document_id 
FROM imported_documents 
WHERE agent_key = id.agent_key AND batch_id = batch_id_param 
LIMIT 5
) AS sample_polizas
FROM imported_documents id
LEFT JOIN usuarios u ON u.id = id.movi_user_id
WHERE id.batch_id = batch_id_param
AND id.agent_key IS NOT NULL
GROUP BY 
id.agent_key,
id.agent_name_raw,
id.match_status,
id.movi_user_id,
u.nombre_completo,
id.match_confidence
ORDER BY doc_count DESC;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_agent_jc_rank(p_user_id uuid)
 RETURNS TABLE(rank bigint, total bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
BEGIN
RETURN QUERY
WITH ranked_agents AS (
SELECT 
user_id,
jiro_coins_balance,
ROW_NUMBER() OVER (ORDER BY jiro_coins_balance DESC, created_at ASC) as position
FROM agent_gamification_profile
),
total_count AS (
SELECT COUNT(*) as cnt FROM agent_gamification_profile
)
SELECT 
COALESCE(ra.position, 0)::BIGINT as rank,
tc.cnt::BIGINT as total
FROM total_count tc
LEFT JOIN ranked_agents ra ON ra.user_id = p_user_id;
END;
$function$
;

