CREATE OR REPLACE FUNCTION public.get_available_commission_batches_for_user(p_user_id uuid)
 RETURNS TABLE(batch_id uuid, batch_name text, date_from date, date_to date, status text, total_records bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
BEGIN
RETURN QUERY
SELECT 
cb.id as batch_id,
cb.name as batch_name,
cb.date_from,
cb.date_to,
cb.status,
COUNT(cd2.id) as total_records
FROM commission_batches cb
INNER JOIN commission_details cd2 ON cd2.batch_id = cb.id
INNER JOIN usuarios u ON u.id = cd2.usuario_id
WHERE u.id = p_user_id
AND cb.status IN ('confirmed', 'closed')
GROUP BY cb.id, cb.name, cb.date_from, cb.date_to, cb.status
ORDER BY cb.date_from DESC;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_calendar_events_for_month(p_year integer, p_month integer)
 RETURNS TABLE(id uuid, titulo text, descripcion text, fecha_inicio timestamp with time zone, fecha_fin timestamp with time zone, todo_el_dia boolean, tipo_evento text, color text, entidad_tipo text, entidad_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
RETURN QUERY
SELECT 
dce.id,
dce.titulo,
dce.descripcion,
dce.fecha_inicio,
dce.fecha_fin,
dce.todo_el_dia,
dce.tipo_evento,
dce.color,
dce.entidad_tipo,
dce.entidad_id
FROM dashboard_calendar_events dce
WHERE 
dce.usuario_id = auth.uid()
AND EXTRACT(YEAR FROM dce.fecha_inicio) = p_year
AND EXTRACT(MONTH FROM dce.fecha_inicio) = p_month
ORDER BY dce.fecha_inicio;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_catalog_anios(p_marca text)
 RETURNS TABLE(anio integer)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT DISTINCT v.anio
  FROM public.multi_autos_catalogo_vehiculos v
  WHERE v.active = true AND v.marca = p_marca
    AND (
      (public.qualitas_catalog_is_loaded() AND v.catalog_source = 'qualitas_official')
      OR (NOT public.qualitas_catalog_is_loaded() AND v.catalog_source <> 'qualitas_official')
    )
  ORDER BY v.anio DESC;
$function$
;

