CREATE OR REPLACE FUNCTION public.get_centro_digital_indexing_stats()
 RETURNS TABLE(total_carpetas_ai integer, total_archivos_indexados integer, total_chunks integer, total_pendientes integer, total_errores integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN QUERY
SELECT
(SELECT count(*)::integer FROM centro_digital_carpetas WHERE activa = true AND enable_chava_ai = true),
(SELECT count(DISTINCT archivo_id)::integer FROM centro_digital_chunks),
(SELECT count(*)::integer FROM centro_digital_chunks),
(SELECT count(*)::integer FROM centro_digital_indexing_jobs WHERE estado = 'pendiente'),
(SELECT count(*)::integer FROM centro_digital_indexing_jobs WHERE estado = 'error');
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_chava_bi_dashboard(p_dias integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_result jsonb;
v_fecha_inicio timestamptz := NOW() - (p_dias || ' days')::interval;
BEGIN
IF NOT is_chava_admin() THEN
RAISE EXCEPTION 'Acceso denegado';
END IF;

SELECT jsonb_build_object(
'uso', jsonb_build_object(
'total_interacciones', (SELECT COUNT(*) FROM chava_interaction_analytics WHERE created_at >= v_fecha_inicio),
'usuarios_unicos',     (SELECT COUNT(DISTINCT COALESCE(chava_user_id::text, usuario_id::text)) FROM chava_interaction_analytics WHERE created_at >= v_fecha_inicio),
'usuarios_movi',       (SELECT COUNT(DISTINCT usuario_id) FROM chava_interaction_analytics WHERE plataforma_origen = 'movi' AND created_at >= v_fecha_inicio),
'usuarios_externos',   (SELECT COUNT(DISTINCT chava_user_id) FROM chava_interaction_analytics WHERE plataforma_origen = 'chava_agente' AND created_at >= v_fecha_inicio),
'sin_respuesta',       (SELECT COUNT(*) FROM chava_interaction_analytics WHERE tuvo_respuesta = false AND created_at >= v_fecha_inicio),
'con_kb',              (SELECT COUNT(*) FROM chava_interaction_analytics WHERE uso_base_conocimiento = true AND created_at >= v_fecha_inicio)
),
'comercial', jsonb_build_object(
'leads_detectados',    (SELECT COUNT(*) FROM chava_lead_signals WHERE created_at >= v_fecha_inicio),
'leads_alta_calidad',  (SELECT COUNT(*) FROM chava_lead_signals WHERE calidad = 'alta' AND created_at >= v_fecha_inicio),
'top_productos',       (SELECT COALESCE(jsonb_agg(r), '[]'::jsonb) FROM (SELECT producto_detectado as producto, COUNT(*) as conteo FROM chava_interaction_analytics WHERE producto_detectado IS NOT NULL AND created_at >= v_fecha_inicio GROUP BY producto_detectado ORDER BY conteo DESC LIMIT 6) r),
'top_estados',         (SELECT COALESCE(jsonb_agg(r), '[]'::jsonb) FROM (SELECT estado_detectado as estado, COUNT(*) as conteo FROM chava_interaction_analytics WHERE estado_detectado IS NOT NULL AND created_at >= v_fecha_inicio GROUP BY estado_detectado ORDER BY conteo DESC LIMIT 8) r)
),
'conocimiento', jsonb_build_object(
'top_intents',         (SELECT COALESCE(jsonb_agg(r), '[]'::jsonb) FROM (SELECT intent_principal as intent, COUNT(*) as conteo FROM chava_interaction_analytics WHERE intent_principal IS NOT NULL AND created_at >= v_fecha_inicio GROUP BY intent_principal ORDER BY conteo DESC LIMIT 10) r),
'sin_documentacion',   (SELECT COUNT(*) FROM chava_interaction_analytics WHERE consulta_sin_documentacion = true AND created_at >= v_fecha_inicio),
'pendientes_revision', (SELECT COUNT(*) FROM chava_knowledge_review_queue WHERE estado = 'pendiente'),
'sugerencias_total',   (SELECT COUNT(*) FROM chava_knowledge_review_queue)
),
'tecnologia', jsonb_build_object(
'mejoras_nuevas',      (SELECT COUNT(*) FROM chava_improvement_suggestions WHERE estado = 'nuevo'),
'mejoras_total',       (SELECT COUNT(*) FROM chava_improvement_suggestions),
'por_plataforma',      (SELECT COALESCE(jsonb_agg(r), '[]'::jsonb) FROM (SELECT plataforma, COUNT(*) as conteo FROM chava_improvement_suggestions WHERE estado IN ('nuevo','en_revision') GROUP BY plataforma ORDER BY conteo DESC) r)
),
'insights_recientes',    (SELECT COALESCE(jsonb_agg(r), '[]'::jsonb) FROM (SELECT id, tipo, titulo, resumen, categoria, impacto, variacion_pct, created_at FROM chava_bi_insights WHERE publicado = true ORDER BY created_at DESC LIMIT 8) r)
) INTO v_result;

RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_chava_stats()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
result jsonb;
BEGIN
SELECT jsonb_build_object(
'total_documentos', (SELECT count(*) FROM chava_documentos WHERE estado = 'ready'),
'total_fragmentos', (SELECT count(*) FROM chava_fragmentos),
'total_carpetas', (SELECT count(*) FROM chava_carpetas WHERE activo = true),
'total_modulos', (SELECT count(*) FROM chava_modulos_descubiertos WHERE activo = true),
'consultas_hoy', (SELECT count(*) FROM chava_consultas_log WHERE created_at >= CURRENT_DATE),
'consultas_semana', (SELECT count(*) FROM chava_consultas_log WHERE created_at >= CURRENT_DATE - interval '7 days'),
'consultas_mes', (SELECT count(*) FROM chava_consultas_log WHERE created_at >= CURRENT_DATE - interval '30 days'),
'tokens_mes', (SELECT COALESCE(sum(tokens_entrada + tokens_salida), 0) FROM chava_consultas_log WHERE created_at >= CURRENT_DATE - interval '30 days'),
'errores_semana', (SELECT count(*) FROM chava_consultas_log WHERE error IS NOT NULL AND created_at >= CURRENT_DATE - interval '7 days'),
'satisfaccion_promedio', (SELECT COALESCE(round(avg(satisfaccion)::numeric, 1), 0) FROM chava_consultas_log WHERE satisfaccion IS NOT NULL AND created_at >= CURRENT_DATE - interval '30 days'),
'documentos_pendientes', (SELECT count(*) FROM chava_documentos WHERE estado = 'pending'),
'jobs_activos', (SELECT count(*) FROM chava_entrenamiento_jobs WHERE estado IN ('pending', 'processing'))
) INTO result;

RETURN result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_chava_tier_config(tier_id text)
 RETURNS TABLE(solo_externo_filter boolean, max_tokens_respuesta integer, max_historial_mensajes integer, max_consultas_sesion integer, modelo_ia text, temperatura numeric, rag_similitud_minima numeric, max_fragmentos_rag integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
SELECT 
t.solo_externo_filter,
t.max_tokens_respuesta,
t.max_historial_mensajes,
t.max_consultas_sesion,
t.modelo_ia,
t.temperatura,
t.rag_similitud_minima,
t.max_fragmentos_rag
FROM chava_access_tiers t
WHERE t.id = tier_id AND t.activo = true;
$function$
;

CREATE OR REPLACE FUNCTION public.get_commission_documents_for_batch(p_batch_id uuid)
 RETURNS TABLE(id uuid, poliza text, nombre_asegurado text, aseguradora text, importe_base double precision, prima_neta double precision, date_fpago date, concepto text)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
RETURN QUERY
SELECT 
cd.id,
cd.poliza,
cd.nombre_asegurado,
cd.aseguradora,
cd.importe_base,
cd.prima_neta,
cd.date_fpago,
cd.concepto
FROM commission_details cd
WHERE cd.batch_id = p_batch_id
ORDER BY cd.date_fpago DESC, cd.poliza;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_companias_por_ramo(p_ramo_id uuid)
 RETURNS TABLE(id uuid, nombre text, convenio boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  SELECT DISTINCT mc.id, mc.nombre, mc.convenio
  FROM   public.maestro_companias mc
  JOIN   public.maestro_combinaciones c ON c.compania_id = mc.id
  WHERE  c.ramo_id = p_ramo_id
    AND  c.activo  = true
    AND  mc.activo = true
  ORDER  BY mc.nombre;
$function$
;

CREATE OR REPLACE FUNCTION public.get_contact_center_summary(p_user_id uuid, p_channel text DEFAULT NULL::text, p_message_type text DEFAULT NULL::text, p_office_id uuid DEFAULT NULL::uuid, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS TABLE(agent_user_id uuid, agent_name text, agent_email text, agent_phone text, agent_office_id uuid, office_name text, agent_rol text, agent_activo boolean, last_message_body text, last_message_channel text, last_message_at timestamp with time zone, last_message_status text, total_messages bigint, unread_count bigint, contact_phone_ext text, contact_name_ext text, is_external boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_user_rol text;
v_user_office uuid;
BEGIN
SELECT u.rol, u.oficina_id INTO v_user_rol, v_user_office
FROM usuarios u WHERE u.id = p_user_id;

IF v_user_rol IS NULL OR v_user_rol NOT IN ('Administrador', 'Gerente', 'Empleado', 'Ejecutivo') THEN
RETURN;
END IF;

RETURN QUERY
WITH last_msgs_users AS (
SELECT DISTINCT ON (m.agent_user_id)
m.agent_user_id,
NULL::text AS ext_phone,
NULL::text AS ext_name,
false AS ext,
m.body AS last_body,
m.channel AS last_channel,
m.created_at AS last_at,
m.status AS last_status
FROM contact_center_messages m
WHERE m.agent_user_id IS NOT NULL
AND (p_channel IS NULL OR m.channel = p_channel)
AND (p_message_type IS NULL OR m.message_type = p_message_type)
ORDER BY m.agent_user_id, m.created_at DESC
),
last_msgs_ext AS (
SELECT DISTINCT ON (m.contact_phone)
NULL::uuid AS agent_user_id,
m.contact_phone AS ext_phone,
(SELECT m2.contact_name FROM contact_center_messages m2
WHERE m2.contact_phone = m.contact_phone AND m2.contact_name IS NOT NULL
ORDER BY m2.created_at DESC LIMIT 1) AS ext_name,
true AS ext,
m.body AS last_body,
m.channel AS last_channel,
m.created_at AS last_at,
m.status AS last_status
FROM contact_center_messages m
WHERE m.agent_user_id IS NULL
AND m.contact_phone IS NOT NULL
AND (p_channel IS NULL OR m.channel = p_channel)
AND (p_message_type IS NULL OR m.message_type = p_message_type)
ORDER BY m.contact_phone, m.created_at DESC
),
combined AS (
SELECT * FROM last_msgs_users
UNION ALL
SELECT * FROM last_msgs_ext
),
msg_counts AS (
SELECT
COALESCE(m.agent_user_id::text, m.contact_phone) AS conv_key,
COUNT(*) AS cnt
FROM contact_center_messages m
WHERE (p_channel IS NULL OR m.channel = p_channel)
AND (p_message_type IS NULL OR m.message_type = p_message_type)
GROUP BY COALESCE(m.agent_user_id::text, m.contact_phone)
),
unread AS (
SELECT
COALESCE(m.agent_user_id::text, m.contact_phone) AS conv_key,
COUNT(*) AS unread_cnt
FROM contact_center_messages m
WHERE m.direction = 'inbound' AND m.read_at IS NULL
GROUP BY COALESCE(m.agent_user_id::text, m.contact_phone)
),
allowed_agents AS (
SELECT DISTINCT t.agente_usuario_id AS uid
FROM tickets t
JOIN ticket_asignaciones ta ON ta.ticket_id = t.id
WHERE ta.ejecutivo_id = p_user_id
AND t.cerrado = false
AND t.agente_usuario_id IS NOT NULL
)
SELECT
c.agent_user_id,
CASE WHEN c.ext THEN COALESCE(c.ext_name, c.ext_phone) ELSE COALESCE(u.nombre_completo, u.nombre)::text END,
CASE WHEN c.ext THEN NULL ELSE COALESCE(u.email_laboral, u.email_personal)::text END,
CASE WHEN c.ext THEN c.ext_phone ELSE COALESCE(u.celular_laboral, u.celular_personal)::text END,
CASE WHEN c.ext THEN NULL ELSE u.oficina_id END,
CASE WHEN c.ext THEN NULL ELSE o.nombre::text END,
CASE WHEN c.ext THEN 'external'::text ELSE u.rol::text END,
CASE WHEN c.ext THEN true ELSE u.activo END,
c.last_body::text,
c.last_channel::text,
c.last_at,
c.last_status::text,
COALESCE(mc.cnt, 0)::bigint,
COALESCE(ur.unread_cnt, 0)::bigint,
c.ext_phone::text,
c.ext_name::text,
c.ext
FROM combined c
LEFT JOIN usuarios u ON u.id = c.agent_user_id
LEFT JOIN oficinas o ON o.id = u.oficina_id
LEFT JOIN msg_counts mc ON mc.conv_key = COALESCE(c.agent_user_id::text, c.ext_phone)
LEFT JOIN unread ur ON ur.conv_key = COALESCE(c.agent_user_id::text, c.ext_phone)
WHERE (
v_user_rol = 'Administrador'
OR (v_user_rol = 'Gerente' AND (c.ext OR u.oficina_id = v_user_office))
OR (v_user_rol IN ('Empleado', 'Ejecutivo') AND (c.ext OR c.agent_user_id IN (SELECT aa.uid FROM allowed_agents aa)))
)
AND (p_office_id IS NULL OR c.ext OR u.oficina_id = p_office_id)
AND (p_search IS NULL OR (
(c.ext AND (c.ext_phone ILIKE '%' || p_search || '%' OR c.ext_name ILIKE '%' || p_search || '%'))
OR (NOT c.ext AND (
COALESCE(u.nombre_completo, u.nombre) ILIKE '%' || p_search || '%'
OR COALESCE(u.email_laboral, '') ILIKE '%' || p_search || '%'
OR COALESCE(u.celular_laboral, '') ILIKE '%' || p_search || '%'
))
))
ORDER BY c.last_at DESC
LIMIT p_limit OFFSET p_offset;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_conversion_kpis(p_fecha_inicio timestamp with time zone DEFAULT NULL::timestamp with time zone, p_fecha_fin timestamp with time zone DEFAULT NULL::timestamp with time zone, p_oficina_id uuid DEFAULT NULL::uuid, p_usuario_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(total_tramites bigint, total_emitidos bigint, total_no_emitidos bigint, total_en_proceso bigint, tasa_conversion numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN QUERY
WITH base AS (
SELECT t.resultado, u.oficina_id
FROM tickets t
LEFT JOIN usuarios u ON u.id = t.agente_usuario_id
WHERE t.tipo_tramite = 'registro_actividad'
AND t.activity_subtype_id IN (
SELECT id FROM tramite_activity_types
WHERE lower(nombre) LIKE '%cotizaci%' OR lower(nombre) LIKE '%emisi%'
)
AND (p_fecha_inicio IS NULL OR t.fecha_creacion >= p_fecha_inicio)
AND (p_fecha_fin IS NULL OR t.fecha_creacion <= p_fecha_fin)
AND (p_oficina_id IS NULL OR u.oficina_id = p_oficina_id)
AND (p_usuario_id IS NULL OR t.agente_usuario_id = p_usuario_id)
AND t.deleted_at IS NULL
)
SELECT
COUNT(*)::bigint,
COUNT(*) FILTER (WHERE resultado = 'ganado')::bigint,
COUNT(*) FILTER (WHERE resultado = 'perdido')::bigint,
COUNT(*) FILTER (WHERE resultado = 'en_progreso' OR resultado IS NULL)::bigint,
CASE WHEN COUNT(*) > 0
THEN ROUND((COUNT(*) FILTER (WHERE resultado = 'ganado')::numeric / COUNT(*)::numeric) * 100, 1)
ELSE 0
END
FROM base;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_conversion_ranking(p_fecha_inicio timestamp with time zone DEFAULT NULL::timestamp with time zone, p_fecha_fin timestamp with time zone DEFAULT NULL::timestamp with time zone, p_oficina_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(agente_id uuid, agente_nombre text, oficina_nombre text, total_tramites bigint, total_emitidos bigint, total_no_emitidos bigint, total_en_proceso bigint, tasa_conversion numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN QUERY
SELECT
u.id,
u.nombre_completo,
COALESCE(o.nombre, 'Sin oficina'),
COUNT(t.id)::bigint,
COUNT(t.id) FILTER (WHERE t.resultado = 'ganado')::bigint,
COUNT(t.id) FILTER (WHERE t.resultado = 'perdido')::bigint,
COUNT(t.id) FILTER (WHERE t.resultado = 'en_progreso' OR t.resultado IS NULL)::bigint,
CASE WHEN COUNT(t.id) > 0
THEN ROUND((COUNT(t.id) FILTER (WHERE t.resultado = 'ganado')::numeric / COUNT(t.id)::numeric) * 100, 1)
ELSE 0
END
FROM usuarios u
LEFT JOIN tickets t ON t.agente_usuario_id = u.id
AND t.tipo_tramite = 'registro_actividad'
AND t.activity_subtype_id IN (
SELECT id FROM tramite_activity_types
WHERE lower(nombre) LIKE '%cotizaci%' OR lower(nombre) LIKE '%emisi%'
)
AND (p_fecha_inicio IS NULL OR t.fecha_creacion >= p_fecha_inicio)
AND (p_fecha_fin IS NULL OR t.fecha_creacion <= p_fecha_fin)
AND t.deleted_at IS NULL
LEFT JOIN oficinas o ON o.id = u.oficina_id
WHERE (p_oficina_id IS NULL OR u.oficina_id = p_oficina_id)
AND u.estado = 'activo'
GROUP BY u.id, u.nombre_completo, o.nombre
HAVING COUNT(t.id) > 0
ORDER BY COUNT(t.id) FILTER (WHERE t.resultado = 'ganado') DESC;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_cp_dashboard_kpis(p_user_id uuid, p_rol text DEFAULT 'Agente'::text, p_oficina_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
result jsonb;
current_year int := EXTRACT(year FROM NOW())::int;
prev_year int := current_year - 1;
current_doy int := EXTRACT(doy FROM NOW())::int;
v_month_start date := date_trunc('month', CURRENT_DATE)::date;
v_prev_month_start date := (date_trunc('month', CURRENT_DATE) - interval '1 month')::date;
v_prev_month_end date := (v_month_start - interval '1 day')::date;
v_ytd_prima numeric := 0;
v_ytd_polizas int := 0;
v_prev_ytd_prima numeric := 0;
v_meta_prima numeric := 0;
v_avance_meta_pct numeric := 0;
v_month_prima numeric := 0;
v_prev_month_prima numeric := 0;
v_month_growth numeric := 0;
v_month_polizas int := 0;
v_cobranza_count int := 0;
v_cobranza_prima numeric := 0;
v_renov_30 int := 0;
v_renov_60 int := 0;
v_renov_90 int := 0;
v_comisiones_mes numeric := 0;
v_top_ramos jsonb := '[]'::jsonb;
is_admin boolean := p_rol = 'Administrador';
is_gerente boolean := p_rol = 'Gerente';
BEGIN
IF is_admin OR is_gerente THEN
SELECT COALESCE(SUM(prima_neta), 0), COUNT(*)
INTO v_ytd_prima, v_ytd_polizas
FROM sicas_documents
WHERE fecha_captura >= make_date(current_year, 1, 1)
AND fecha_captura < NOW()
AND (is_admin OR oficina_id = p_oficina_id);

SELECT COALESCE(SUM(prima_neta), 0) INTO v_prev_ytd_prima
FROM sicas_documents
WHERE fecha_captura >= make_date(prev_year, 1, 1)
AND fecha_captura < (make_date(prev_year, 1, 1) + (current_doy || ' days')::interval)
AND (is_admin OR oficina_id = p_oficina_id);
ELSE
SELECT COALESCE(SUM(sd.prima_neta), 0), COUNT(*)
INTO v_ytd_prima, v_ytd_polizas
FROM sicas_documents sd
JOIN sicas_mapeo_usuario_vendedor m ON m.vendedor_clave = sd.vendedor_clave AND m.usuario_id = p_user_id
WHERE sd.fecha_captura >= make_date(current_year, 1, 1) AND sd.fecha_captura < NOW();

SELECT COALESCE(SUM(sd.prima_neta), 0) INTO v_prev_ytd_prima
FROM sicas_documents sd
JOIN sicas_mapeo_usuario_vendedor m ON m.vendedor_clave = sd.vendedor_clave AND m.usuario_id = p_user_id
WHERE sd.fecha_captura >= make_date(prev_year, 1, 1)
AND sd.fecha_captura < (make_date(prev_year, 1, 1) + (current_doy || ' days')::interval);
END IF;

v_meta_prima := v_prev_ytd_prima * 1.20;
IF v_meta_prima > 0 THEN
v_avance_meta_pct := ROUND((v_ytd_prima / v_meta_prima) * 100, 1);
END IF;

IF is_admin OR is_gerente THEN
SELECT COALESCE(SUM(prima_neta), 0), COUNT(*)
INTO v_month_prima, v_month_polizas
FROM sicas_documents
WHERE fecha_emision >= v_month_start AND (is_admin OR oficina_id = p_oficina_id);

SELECT COALESCE(SUM(prima_neta), 0) INTO v_prev_month_prima
FROM sicas_documents
WHERE fecha_emision >= v_prev_month_start AND fecha_emision <= v_prev_month_end
AND (is_admin OR oficina_id = p_oficina_id);
ELSE
SELECT COALESCE(SUM(sd.prima_neta), 0), COUNT(*)
INTO v_month_prima, v_month_polizas
FROM sicas_documents sd
JOIN sicas_mapeo_usuario_vendedor m ON m.vendedor_clave = sd.vendedor_clave AND m.usuario_id = p_user_id
WHERE sd.fecha_emision >= v_month_start;

SELECT COALESCE(SUM(sd.prima_neta), 0) INTO v_prev_month_prima
FROM sicas_documents sd
JOIN sicas_mapeo_usuario_vendedor m ON m.vendedor_clave = sd.vendedor_clave AND m.usuario_id = p_user_id
WHERE sd.fecha_emision >= v_prev_month_start AND sd.fecha_emision <= v_prev_month_end;
END IF;

IF v_prev_month_prima > 0 THEN
v_month_growth := ROUND(((v_month_prima - v_prev_month_prima) / v_prev_month_prima) * 100, 1);
ELSIF v_month_prima > 0 THEN
v_month_growth := 100;
END IF;

IF is_admin OR is_gerente THEN
SELECT COUNT(*), COALESCE(SUM(prima_neta), 0)
INTO v_cobranza_count, v_cobranza_prima
FROM sicas_documents
WHERE vigencia_hasta >= CURRENT_DATE AND vigencia_hasta <= (CURRENT_DATE + interval '30 days')
AND status_cobro IS DISTINCT FROM 'Pagado'
AND (is_admin OR oficina_id = p_oficina_id);
ELSE
SELECT COUNT(*), COALESCE(SUM(sd.prima_neta), 0)
INTO v_cobranza_count, v_cobranza_prima
FROM sicas_documents sd
JOIN sicas_mapeo_usuario_vendedor m ON m.vendedor_clave = sd.vendedor_clave AND m.usuario_id = p_user_id
WHERE sd.vigencia_hasta >= CURRENT_DATE AND sd.vigencia_hasta <= (CURRENT_DATE + interval '30 days')
AND sd.status_cobro IS DISTINCT FROM 'Pagado';
END IF;

IF is_admin OR is_gerente THEN
SELECT
COUNT(*) FILTER (WHERE vigencia_hasta <= CURRENT_DATE + interval '30 days'),
COUNT(*) FILTER (WHERE vigencia_hasta > CURRENT_DATE + interval '30 days' AND vigencia_hasta <= CURRENT_DATE + interval '60 days'),
COUNT(*) FILTER (WHERE vigencia_hasta > CURRENT_DATE + interval '60 days' AND vigencia_hasta <= CURRENT_DATE + interval '90 days')
INTO v_renov_30, v_renov_60, v_renov_90
FROM sicas_documents
WHERE vigencia_hasta >= CURRENT_DATE AND vigencia_hasta <= (CURRENT_DATE + interval '90 days')
AND (is_admin OR oficina_id = p_oficina_id);
ELSE
SELECT
COUNT(*) FILTER (WHERE sd.vigencia_hasta <= CURRENT_DATE + interval '30 days'),
COUNT(*) FILTER (WHERE sd.vigencia_hasta > CURRENT_DATE + interval '30 days' AND sd.vigencia_hasta <= CURRENT_DATE + interval '60 days'),
COUNT(*) FILTER (WHERE sd.vigencia_hasta > CURRENT_DATE + interval '60 days' AND sd.vigencia_hasta <= CURRENT_DATE + interval '90 days')
INTO v_renov_30, v_renov_60, v_renov_90
FROM sicas_documents sd
JOIN sicas_mapeo_usuario_vendedor m ON m.vendedor_clave = sd.vendedor_clave AND m.usuario_id = p_user_id
WHERE sd.vigencia_hasta >= CURRENT_DATE AND sd.vigencia_hasta <= (CURRENT_DATE + interval '90 days');
END IF;

SELECT COALESCE(SUM(commission_neta), 0) INTO v_comisiones_mes
FROM commission_details WHERE usuario_id = p_user_id AND created_at >= v_month_start;

IF is_admin OR is_gerente THEN
SELECT COALESCE(jsonb_agg(r), '[]'::jsonb) INTO v_top_ramos
FROM (
SELECT ramo AS nombre, COUNT(*) AS polizas, ROUND(SUM(prima_neta), 0) AS prima
FROM sicas_documents
WHERE fecha_captura >= make_date(current_year, 1, 1) AND ramo IS NOT NULL AND ramo != ''
AND (is_admin OR oficina_id = p_oficina_id)
GROUP BY ramo ORDER BY SUM(prima_neta) DESC LIMIT 3
) r;
ELSE
SELECT COALESCE(jsonb_agg(r), '[]'::jsonb) INTO v_top_ramos
FROM (
SELECT sd.ramo AS nombre, COUNT(*) AS polizas, ROUND(SUM(sd.prima_neta), 0) AS prima
FROM sicas_documents sd
JOIN sicas_mapeo_usuario_vendedor m ON m.vendedor_clave = sd.vendedor_clave AND m.usuario_id = p_user_id
WHERE sd.fecha_captura >= make_date(current_year, 1, 1) AND sd.ramo IS NOT NULL AND sd.ramo != ''
GROUP BY sd.ramo ORDER BY SUM(sd.prima_neta) DESC LIMIT 3
) r;
END IF;

result := jsonb_build_object(
'ytd_prima', ROUND(v_ytd_prima, 0),
'ytd_polizas', v_ytd_polizas,
'meta_prima', ROUND(v_meta_prima, 0),
'avance_meta_pct', v_avance_meta_pct,
'month_prima', ROUND(v_month_prima, 0),
'month_polizas', v_month_polizas,
'month_growth', v_month_growth,
'prev_month_prima', ROUND(v_prev_month_prima, 0),
'cobranza_count', v_cobranza_count,
'cobranza_prima', ROUND(v_cobranza_prima, 0),
'renov_30', v_renov_30,
'renov_60', v_renov_60,
'renov_90', v_renov_90,
'comisiones_mes', ROUND(v_comisiones_mes, 0),
'top_ramos', v_top_ramos,
'current_year', current_year
);

RETURN result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_current_user_office()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
