CREATE OR REPLACE FUNCTION public.get_customer_external_policies(p_customer_id uuid)
 RETURNS TABLE(id uuid, insurer_name text, ramo text, subramo text, policy_number text, contractor_name text, insured_name text, start_date date, end_date date, status text, total_premium numeric, currency text, notes text, created_at timestamp with time zone, documents jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_caller_id uuid := auth.uid();
v_rol       text;
v_agent_id  uuid;
BEGIN
-- Resolve caller role
SELECT u.rol INTO v_rol FROM usuarios u WHERE u.id = v_caller_id LIMIT 1;

-- If not a MOVI user, check if seguwallet agent owns this customer
IF v_rol IS NULL THEN
RAISE EXCEPTION 'Unauthorized';
END IF;

-- Admin sees all; agent sees only own customers
IF v_rol NOT IN ('Administrador', 'admin', 'superadmin') THEN
SELECT sc.agent_user_id INTO v_agent_id
FROM seguwallet_customers sc
WHERE sc.id = p_customer_id
LIMIT 1;

IF v_agent_id IS DISTINCT FROM v_caller_id THEN
RAISE EXCEPTION 'Unauthorized: this customer does not belong to you';
END IF;
END IF;

RETURN QUERY
SELECT
p.id,
p.insurer_name,
p.ramo,
p.subramo,
p.policy_number,
p.contractor_name,
p.insured_name,
p.start_date,
p.end_date,
p.status,
p.total_premium,
p.currency,
p.notes,
p.created_at,
COALESCE(
(
SELECT jsonb_agg(jsonb_build_object(
'id',            d.id,
'document_type', d.document_type,
'document_name', d.document_name,
'file_path',     d.file_path,
'file_size',     d.file_size,
'mime_type',     d.mime_type,
'created_at',    d.created_at
) ORDER BY d.created_at)
FROM seguwallet_external_policy_documents d
WHERE d.external_policy_id = p.id
AND d.deleted_at IS NULL
),
'[]'::jsonb
) AS documents
FROM seguwallet_external_policies p
WHERE p.seguwallet_customer_id = p_customer_id
AND p.deleted_at IS NULL
ORDER BY p.created_at DESC;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_dashboard_kpis(p_user_id uuid, p_rol text, p_oficina_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
result jsonb;
v_current_month_start date;
v_previous_month_start date;
v_previous_month_end date;
v_current_prod numeric := 0;
v_previous_prod numeric := 0;
v_current_comisiones numeric := 0;
v_tramites_pending int := 0;
v_tramites_in_progress int := 0;
v_contactos_total int := 0;
v_crm_tareas_abiertas int := 0;
v_notificaciones_sin_leer int := 0;
v_polizas_vigentes int := 0;
v_prod_growth numeric := 0;
BEGIN
v_current_month_start := date_trunc('month', CURRENT_DATE)::date;
v_previous_month_start := (date_trunc('month', CURRENT_DATE) - interval '1 month')::date;
v_previous_month_end := (v_current_month_start - interval '1 day')::date;

-- Production current month (use fecha_captura as it reflects recent activity)
IF p_rol IN ('Administrador', 'Gerente') THEN
SELECT COALESCE(SUM(prima_neta), 0) INTO v_current_prod
FROM sicas_documents
WHERE fecha_captura >= v_current_month_start
AND (p_rol = 'Administrador' OR oficina_id = p_oficina_id);

SELECT COALESCE(SUM(prima_neta), 0) INTO v_previous_prod
FROM sicas_documents
WHERE fecha_captura >= v_previous_month_start
AND fecha_captura <= v_previous_month_end
AND (p_rol = 'Administrador' OR oficina_id = p_oficina_id);
ELSE
SELECT COALESCE(SUM(sd.prima_neta), 0) INTO v_current_prod
FROM sicas_documents sd
JOIN sicas_mapeo_vendedor_usuario m ON m.id_sicas_vendedor = sd.vend_id AND m.movi_user_id = p_user_id
WHERE sd.fecha_captura >= v_current_month_start;

SELECT COALESCE(SUM(sd.prima_neta), 0) INTO v_previous_prod
FROM sicas_documents sd
JOIN sicas_mapeo_vendedor_usuario m ON m.id_sicas_vendedor = sd.vend_id AND m.movi_user_id = p_user_id
WHERE sd.fecha_captura >= v_previous_month_start
AND sd.fecha_captura <= v_previous_month_end;
END IF;

IF v_previous_prod > 0 THEN
v_prod_growth := ROUND(((v_current_prod - v_previous_prod) / v_previous_prod) * 100, 1);
ELSIF v_current_prod > 0 THEN
v_prod_growth := 100;
END IF;

-- Commissions current month
SELECT COALESCE(SUM(COALESCE(commission_neta, 0)), 0) INTO v_current_comisiones
FROM commission_details
WHERE movi_user_id = p_user_id
AND created_at >= v_current_month_start;

-- Tramites
IF p_rol IN ('Administrador', 'Gerente') THEN
SELECT COUNT(*) INTO v_tramites_pending
FROM tickets t
JOIN ticket_estatus te ON te.id = t.estatus_id
WHERE te.nombre = 'Iniciado'
AND (p_rol = 'Administrador' OR EXISTS (
SELECT 1 FROM usuarios u WHERE u.id = t.agente_id AND u.oficina_id = p_oficina_id
));
SELECT COUNT(*) INTO v_tramites_in_progress
FROM tickets t
JOIN ticket_estatus te ON te.id = t.estatus_id
WHERE te.nombre IN ('En Proceso', 'Espera Agente', 'Espera Aseguradora', 'Cotizado')
AND (p_rol = 'Administrador' OR EXISTS (
SELECT 1 FROM usuarios u WHERE u.id = t.agente_id AND u.oficina_id = p_oficina_id
));
ELSE
SELECT COUNT(*) INTO v_tramites_pending
FROM tickets t
JOIN ticket_estatus te ON te.id = t.estatus_id
WHERE te.nombre = 'Iniciado'
AND (t.agente_id = p_user_id OR t.agente_usuario_id = p_user_id OR t.assigned_to_user_id = p_user_id);
SELECT COUNT(*) INTO v_tramites_in_progress
FROM tickets t
JOIN ticket_estatus te ON te.id = t.estatus_id
WHERE te.nombre IN ('En Proceso', 'Espera Agente', 'Espera Aseguradora', 'Cotizado')
AND (t.agente_id = p_user_id OR t.agente_usuario_id = p_user_id OR t.assigned_to_user_id = p_user_id);
END IF;

-- CRM tareas abiertas
SELECT COUNT(*) INTO v_crm_tareas_abiertas
FROM crm_tareas
WHERE (creado_por = p_user_id OR asignado_a = p_user_id)
AND estatus IN ('pendiente', 'en_progreso');

-- Contactos CRM
SELECT COUNT(*) INTO v_contactos_total
FROM crm_contactos
WHERE creado_por = p_user_id;

-- Notificaciones sin leer
SELECT COUNT(*) INTO v_notificaciones_sin_leer
FROM notificaciones_internas
WHERE usuario_id = p_user_id
AND leido = false;

-- Polizas vigentes
IF p_rol IN ('Administrador', 'Gerente') THEN
SELECT COUNT(*) INTO v_polizas_vigentes
FROM sicas_documents
WHERE is_vigente = true
AND (p_rol = 'Administrador' OR oficina_id = p_oficina_id);
ELSE
SELECT COUNT(*) INTO v_polizas_vigentes
FROM sicas_documents sd
JOIN sicas_mapeo_vendedor_usuario m ON m.id_sicas_vendedor = sd.vend_id AND m.movi_user_id = p_user_id
WHERE sd.is_vigente = true;
END IF;

result := jsonb_build_object(
'produccion_mes', v_current_prod,
'produccion_anterior', v_previous_prod,
'produccion_growth', v_prod_growth,
'comisiones_mes', v_current_comisiones,
'tramites_pendientes', v_tramites_pending,
'tramites_en_proceso', v_tramites_in_progress,
'crm_tareas_abiertas', v_crm_tareas_abiertas,
'contactos_total', v_contactos_total,
'notificaciones_sin_leer', v_notificaciones_sin_leer,
'polizas_vigentes', v_polizas_vigentes
);

RETURN result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_dashboard_renovaciones_breakdown(p_user_id uuid, p_rol text DEFAULT 'Agente'::text, p_oficina_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
result jsonb;
v_30 int := 0;
v_60 int := 0;
v_90 int := 0;
v_total_prima_30 numeric := 0;
BEGIN
IF p_rol IN ('Administrador', 'Gerente') THEN
SELECT
COUNT(*) FILTER (WHERE vigencia_hasta BETWEEN CURRENT_DATE AND CURRENT_DATE + 30),
COUNT(*) FILTER (WHERE vigencia_hasta BETWEEN CURRENT_DATE + 31 AND CURRENT_DATE + 60),
COUNT(*) FILTER (WHERE vigencia_hasta BETWEEN CURRENT_DATE + 61 AND CURRENT_DATE + 90),
COALESCE(SUM(prima_neta) FILTER (WHERE vigencia_hasta BETWEEN CURRENT_DATE AND CURRENT_DATE + 30), 0)
INTO v_30, v_60, v_90, v_total_prima_30
FROM sicas_documents
WHERE is_vigente = true
AND vigencia_hasta BETWEEN CURRENT_DATE AND CURRENT_DATE + 90
AND (p_rol = 'Administrador' OR oficina_id = p_oficina_id);
ELSE
SELECT
COUNT(*) FILTER (WHERE sd.vigencia_hasta BETWEEN CURRENT_DATE AND CURRENT_DATE + 30),
COUNT(*) FILTER (WHERE sd.vigencia_hasta BETWEEN CURRENT_DATE + 31 AND CURRENT_DATE + 60),
COUNT(*) FILTER (WHERE sd.vigencia_hasta BETWEEN CURRENT_DATE + 61 AND CURRENT_DATE + 90),
COALESCE(SUM(sd.prima_neta) FILTER (WHERE sd.vigencia_hasta BETWEEN CURRENT_DATE AND CURRENT_DATE + 30), 0)
INTO v_30, v_60, v_90, v_total_prima_30
FROM sicas_documents sd
JOIN sicas_mapeo_vendedor_usuario m ON m.id_sicas_vendedor = sd.vend_id AND m.movi_user_id = p_user_id
WHERE sd.is_vigente = true
AND sd.vigencia_hasta BETWEEN CURRENT_DATE AND CURRENT_DATE + 90;
END IF;

result := jsonb_build_object(
'proximas_30', v_30,
'proximas_60', v_60,
'proximas_90', v_90,
'total', v_30 + v_60 + v_90,
'prima_30', v_total_prima_30
);

RETURN result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_dashboard_top_aseguradoras(p_user_id uuid, p_rol text, p_oficina_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 7)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
result jsonb;
v_year_start date;
BEGIN
v_year_start := date_trunc('year', CURRENT_DATE)::date;

IF p_rol IN ('Administrador', 'Gerente') THEN
SELECT COALESCE(jsonb_agg(row_to_json(sub)::jsonb), '[]'::jsonb)
INTO result
FROM (
SELECT
COALESCE(compania, aseguradora_nombre, 'Sin nombre') as nombre,
COUNT(*) as polizas,
ROUND(SUM(prima_neta)::numeric, 2) as prima_total
FROM sicas_documents
WHERE fecha_captura >= v_year_start
AND (p_rol = 'Administrador' OR oficina_id = p_oficina_id)
AND (compania IS NOT NULL OR aseguradora_nombre IS NOT NULL)
GROUP BY COALESCE(compania, aseguradora_nombre, 'Sin nombre')
ORDER BY prima_total DESC
LIMIT p_limit
) sub;
ELSE
SELECT COALESCE(jsonb_agg(row_to_json(sub)::jsonb), '[]'::jsonb)
INTO result
FROM (
SELECT
COALESCE(sd.compania, sd.aseguradora_nombre, 'Sin nombre') as nombre,
COUNT(*) as polizas,
ROUND(SUM(sd.prima_neta)::numeric, 2) as prima_total
FROM sicas_documents sd
JOIN sicas_mapeo_vendedor_usuario m ON m.id_sicas_vendedor = sd.vend_id AND m.movi_user_id = p_user_id
WHERE sd.fecha_captura >= v_year_start
AND (sd.compania IS NOT NULL OR sd.aseguradora_nombre IS NOT NULL)
GROUP BY COALESCE(sd.compania, sd.aseguradora_nombre, 'Sin nombre')
ORDER BY prima_total DESC
LIMIT p_limit
) sub;
END IF;

RETURN result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_dashboard_tramites_resumen(p_user_id uuid, p_rol text DEFAULT 'Agente'::text, p_oficina_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
result jsonb;
v_por_estatus jsonb;
v_recientes jsonb;
BEGIN
-- Count by status (excluding closed)
IF p_rol IN ('Administrador', 'Gerente') THEN
SELECT jsonb_object_agg(te.nombre, cnt)
INTO v_por_estatus
FROM (
SELECT t.estatus_id, COUNT(*) as cnt
FROM tickets t
JOIN ticket_estatus te2 ON te2.id = t.estatus_id
WHERE te2.nombre != 'Cerrado'
AND (p_rol = 'Administrador' OR EXISTS (
SELECT 1 FROM usuarios u WHERE u.id = t.agente_id AND u.oficina_id = p_oficina_id
))
GROUP BY t.estatus_id
) sub
JOIN ticket_estatus te ON te.id = sub.estatus_id;
ELSE
SELECT jsonb_object_agg(te.nombre, cnt)
INTO v_por_estatus
FROM (
SELECT t.estatus_id, COUNT(*) as cnt
FROM tickets t
JOIN ticket_estatus te2 ON te2.id = t.estatus_id
WHERE te2.nombre != 'Cerrado'
AND (t.agente_id = p_user_id OR t.agente_usuario_id = p_user_id OR t.assigned_to_user_id = p_user_id)
GROUP BY t.estatus_id
) sub
JOIN ticket_estatus te ON te.id = sub.estatus_id;
END IF;

-- Recent open tickets with status name
IF p_rol IN ('Administrador', 'Gerente') THEN
SELECT COALESCE(jsonb_agg(row_to_json(rec)::jsonb ORDER BY rec.ultima_modificacion DESC), '[]'::jsonb)
INTO v_recientes
FROM (
SELECT t.id, t.folio, t.tipo_tramite as tipo, te.nombre as estatus, t.ultima_modificacion
FROM tickets t
JOIN ticket_estatus te ON te.id = t.estatus_id
WHERE te.nombre != 'Cerrado'
AND (p_rol = 'Administrador' OR EXISTS (
SELECT 1 FROM usuarios u WHERE u.id = t.agente_id AND u.oficina_id = p_oficina_id
))
ORDER BY t.ultima_modificacion DESC
LIMIT p_limit
) rec;
ELSE
SELECT COALESCE(jsonb_agg(row_to_json(rec)::jsonb ORDER BY rec.ultima_modificacion DESC), '[]'::jsonb)
INTO v_recientes
FROM (
SELECT t.id, t.folio, t.tipo_tramite as tipo, te.nombre as estatus, t.ultima_modificacion
FROM tickets t
JOIN ticket_estatus te ON te.id = t.estatus_id
WHERE te.nombre != 'Cerrado'
AND (t.agente_id = p_user_id OR t.agente_usuario_id = p_user_id OR t.assigned_to_user_id = p_user_id)
ORDER BY t.ultima_modificacion DESC
LIMIT p_limit
) rec;
END IF;

result := jsonb_build_object(
'por_estatus', COALESCE(v_por_estatus, '{}'::jsonb),
'recientes', COALESCE(v_recientes, '[]'::jsonb)
);

RETURN result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_directorio_usuarios(p_oficina_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, nombre text, apellidos text, email_laboral text, email_personal text, celular_personal text, celular_laboral text, username text, rol text, estado text, activo boolean, oficina_id uuid, puesto text, imagen_perfil_url text, is_deleted boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
SELECT 
u.id, u.nombre, u.apellidos, u.email_laboral, u.email_personal,
u.celular_personal, u.celular_laboral, u.username, u.rol, u.estado,
u.activo, u.oficina_id, u.puesto, u.imagen_perfil_url, u.is_deleted
FROM usuarios u
WHERE (u.is_deleted = false OR u.is_deleted IS NULL)
AND u.estado IN ('activo', 'inactivo', 'pendiente')
AND (p_oficina_id IS NULL OR u.oficina_id = p_oficina_id)
ORDER BY u.nombre
LIMIT 2000;
$function$
;

CREATE OR REPLACE FUNCTION public.get_directory_users(p_oficina_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, nombre text, apellidos text, email_laboral text, email_personal text, celular_personal text, celular_laboral text, username text, rol text, estado text, activo boolean, oficina_id uuid, puesto text, imagen_perfil_url text, is_deleted boolean, oficina_nombre text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- If a specific office is requested, filter by it
  IF p_oficina_id IS NOT NULL THEN
    RETURN QUERY
    SELECT u.id, u.nombre, u.apellidos, u.email_laboral, u.email_personal,
      u.celular_personal, u.celular_laboral, u.username, u.rol, u.estado,
      u.activo, u.oficina_id, u.puesto, u.imagen_perfil_url, u.is_deleted,
      o.nombre AS oficina_nombre
    FROM usuarios u
    LEFT JOIN oficinas o ON o.id = u.oficina_id
    WHERE u.is_deleted = false
      AND u.oficina_id = p_oficina_id
    ORDER BY u.nombre
    LIMIT 2000;
  ELSE
    RETURN QUERY
    SELECT u.id, u.nombre, u.apellidos, u.email_laboral, u.email_personal,
      u.celular_personal, u.celular_laboral, u.username, u.rol, u.estado,
      u.activo, u.oficina_id, u.puesto, u.imagen_perfil_url, u.is_deleted,
      o.nombre AS oficina_nombre
    FROM usuarios u
    LEFT JOIN oficinas o ON o.id = u.oficina_id
    WHERE u.is_deleted = false
    ORDER BY u.nombre
    LIMIT 2000;
  END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_documents_by_vendor_group(p_batch_id uuid, p_vendor_name_norm text, p_limit integer DEFAULT 10, p_offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, document_id text, vendor_name_raw text, vendor_email_raw text, document_data jsonb, created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE
AS $function$
BEGIN
RETURN QUERY
SELECT
doc.id,
doc.document_id,
doc.vendor_name_raw,
doc.vendor_email_raw,
doc.document_data,
doc.created_at
FROM imported_documents doc
WHERE doc.batch_id = p_batch_id
AND doc.vendor_name_norm = p_vendor_name_norm
AND doc.is_unmatched = true
ORDER BY doc.created_at DESC
LIMIT p_limit
OFFSET p_offset;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_documents_by_vendor_key(p_batch_id uuid, p_vendor_key text, p_limit integer DEFAULT 10, p_offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, document_id text, vendor_name_raw text, vendor_email_raw text, document_data jsonb, created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE
AS $function$
BEGIN
RETURN QUERY
SELECT
doc.id,
doc.document_id,
doc.vendor_name_raw,
doc.vendor_email_raw,
doc.document_data,
doc.created_at
FROM imported_documents doc
WHERE doc.batch_id = p_batch_id
AND doc.vendor_key = p_vendor_key
AND doc.is_unmatched = true
ORDER BY doc.created_at DESC
LIMIT p_limit
OFFSET p_offset;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_effective_user_logo(p_user_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_logo_url text;
v_oficina_logo text;
BEGIN
-- First try: User's personal logo
SELECT mi_logotipo_url INTO v_logo_url
FROM usuarios
WHERE id = p_user_id;

IF v_logo_url IS NOT NULL AND v_logo_url != '' THEN
RETURN v_logo_url;
END IF;

-- Second try: Office logo
SELECT o.logo_url INTO v_oficina_logo
FROM usuarios u
JOIN oficinas o ON u.oficina_id = o.id
WHERE u.id = p_user_id;

IF v_oficina_logo IS NOT NULL AND v_oficina_logo != '' THEN
RETURN v_oficina_logo;
END IF;

-- Third try: Default JIRO logo
RETURN '/logojiro.png';
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_equipos_para_tipo(p_tipo_id uuid)
 RETURNS TABLE(equipo_id uuid, equipo_nombre text, area_nombre text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    tgv.id       AS equipo_id,
    tgv.nombre   AS equipo_nombre,
    ta.nombre    AS area_nombre
  FROM  public.tramites_equipos_areas tea
  JOIN  public.tramites_grupos_visualizacion tgv ON tgv.id = tea.equipo_id
  JOIN  public.tramites_areas               ta  ON ta.id  = tea.area_id
  WHERE tea.tramites_activos @> ARRAY[p_tipo_id]
    AND tgv.activo = true
  ORDER BY tgv.nombre;
$function$
;

CREATE OR REPLACE FUNCTION public.get_firma_asignada(p_usuario_id uuid)
 RETURNS TABLE(template_id uuid, template_nombre text, template_html text, prioridad integer, tipo_asignacion text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_usuario RECORD;
v_row RECORD;
BEGIN
SELECT * INTO v_usuario FROM usuarios WHERE id = p_usuario_id;
IF NOT FOUND THEN RETURN; END IF;

-- 1. User-specific (highest priority)
SELECT ft.id, ft.nombre, ft.html, fa.prioridad, fa.tipo
INTO v_row
FROM firma_asignaciones fa
JOIN firma_templates ft ON ft.id = fa.template_id
WHERE fa.tipo = 'usuario'
AND fa.ref_usuario_id = p_usuario_id
AND ft.es_activa = true
ORDER BY fa.prioridad DESC
LIMIT 1;
IF FOUND THEN
template_id := v_row.id;
template_nombre := v_row.nombre;
template_html := v_row.html;
prioridad := v_row.prioridad;
tipo_asignacion := v_row.tipo;
RETURN NEXT;
RETURN;
END IF;

-- 2. Role-based
SELECT ft.id, ft.nombre, ft.html, fa.prioridad, fa.tipo
INTO v_row
FROM firma_asignaciones fa
JOIN firma_templates ft ON ft.id = fa.template_id
WHERE fa.tipo = 'rol'
AND fa.ref_rol = v_usuario.rol
AND ft.es_activa = true
ORDER BY fa.prioridad DESC
LIMIT 1;
IF FOUND THEN
template_id := v_row.id;
template_nombre := v_row.nombre;
template_html := v_row.html;
prioridad := v_row.prioridad;
tipo_asignacion := v_row.tipo;
RETURN NEXT;
RETURN;
END IF;

-- 3. Office-based
IF v_usuario.oficina_id IS NOT NULL THEN
SELECT ft.id, ft.nombre, ft.html, fa.prioridad, fa.tipo
INTO v_row
FROM firma_asignaciones fa
JOIN firma_templates ft ON ft.id = fa.template_id
WHERE fa.tipo = 'oficina'
AND fa.ref_oficina_id = v_usuario.oficina_id
AND ft.es_activa = true
ORDER BY fa.prioridad DESC
LIMIT 1;
IF FOUND THEN
template_id := v_row.id;
template_nombre := v_row.nombre;
template_html := v_row.html;
prioridad := v_row.prioridad;
tipo_asignacion := v_row.tipo;
RETURN NEXT;
RETURN;
END IF;
END IF;

-- 4. Global default
SELECT ft.id, ft.nombre, ft.html, fa.prioridad, fa.tipo
INTO v_row
FROM firma_asignaciones fa
JOIN firma_templates ft ON ft.id = fa.template_id
WHERE fa.tipo = 'global'
AND ft.es_activa = true
ORDER BY fa.prioridad DESC
LIMIT 1;
IF FOUND THEN
template_id := v_row.id;
template_nombre := v_row.nombre;
template_html := v_row.html;
prioridad := v_row.prioridad;
tipo_asignacion := v_row.tipo;
RETURN NEXT;
RETURN;
END IF;

END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_grupo_miembros(p_grupo_id uuid)
 RETURNS TABLE(id uuid, nombre_completo text, oficina_nombre text, rol text, oficina_id uuid, rol_en_equipo text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    u.id,
    COALESCE(u.nombre_completo, UPPER(COALESCE(u.nombre, '') || ' ' || COALESCE(u.apellidos, ''))) AS nombre_completo,
    o.nombre  AS oficina_nombre,
    u.rol,
    u.oficina_id,
    m.rol_en_equipo
  FROM usuarios u
  INNER JOIN tramites_grupos_miembros m ON m.usuario_id = u.id
  LEFT  JOIN oficinas o ON o.id = u.oficina_id
  WHERE m.grupo_id = p_grupo_id
    AND u.estado   = 'activo'
  ORDER BY
    CASE m.rol_en_equipo WHEN 'lider' THEN 1 WHEN 'ejecutivo' THEN 2 ELSE 3 END,
    u.nombre_completo;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_grupo_miembros_ejecutivos(p_grupo_id uuid)
 RETURNS TABLE(id uuid, nombre_completo text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    u.id,
    COALESCE(u.nombre_completo, UPPER(COALESCE(u.nombre, '') || ' ' || COALESCE(u.apellidos, ''))) AS nombre_completo
  FROM usuarios u
  INNER JOIN tramites_grupos_miembros m ON m.usuario_id = u.id
  WHERE m.grupo_id          = p_grupo_id
    AND m.rol_en_equipo     IN ('lider', 'ejecutivo')
    AND u.estado            = 'activo'
  ORDER BY
    CASE m.rol_en_equipo WHEN 'lider' THEN 1 ELSE 2 END,
    u.nombre_completo;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_grupo_oficinas(p_grupo_id uuid)
 RETURNS TABLE(id uuid, oficina_id uuid, oficina_nombre text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
SELECT
go.id,
go.oficina_id,
o.nombre AS oficina_nombre
FROM tramites_grupos_oficinas go
JOIN oficinas o ON o.id = go.oficina_id
WHERE go.grupo_id = p_grupo_id
ORDER BY o.nombre;
$function$
;

CREATE OR REPLACE FUNCTION public.get_grupo_para_ticket(p_agente_id uuid, p_tipo_tramite text DEFAULT NULL::text)
 RETURNS TABLE(grupo_id uuid, ejecutivo_id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tipo_id    uuid;
  v_area       text;
  v_oficina_id uuid;
BEGIN
  IF p_tipo_tramite IS NOT NULL THEN
    SELECT tt.id, LOWER(tt.area)
      INTO v_tipo_id, v_area
    FROM ticket_tipos tt
    WHERE tt.value  = p_tipo_tramite
      AND tt.activo = true
    LIMIT 1;
  END IF;

  SELECT u.oficina_id INTO v_oficina_id FROM usuarios u WHERE u.id = p_agente_id;

  -- ── Nivel 1: override manual (agente + tipo específico) ──────────────────────
  IF v_tipo_id IS NOT NULL THEN
    RETURN QUERY
    SELECT r.grupo_id, r.ejecutivo_id
    FROM tramites_reglas_por_tipo r
    JOIN tramites_grupos_visualizacion g ON g.id = r.grupo_id
    WHERE r.usuario_id = p_agente_id
      AND r.tipo_id    = v_tipo_id
      AND r.activo     = true
      AND g.activo     = true
    LIMIT 1;

    IF FOUND THEN RETURN; END IF;
  END IF;

  -- ── Nivel 2: regla individual agente + área ("ASIGNACIÓN POR EQUIPOS") ───────
  -- Más específica que el enrutamiento automático por oficina: si el agente ya
  -- tiene un ejecutivo (o equipo) asignado a mano para esta área, gana aquí.
  IF v_area IS NOT NULL THEN
    RETURN QUERY
    SELECT r.grupo_id, r.ejecutivo_id
    FROM tramites_grupos_reglas r
    JOIN tramites_grupos_visualizacion g ON g.id = r.grupo_id
    WHERE r.usuario_id  = p_agente_id
      AND LOWER(r.area) = v_area
      AND r.activo      = true
      AND g.activo      = true
    LIMIT 1;

    IF FOUND THEN RETURN; END IF;
  END IF;

  -- Comodín (area IS NULL) de la misma capa — antes de caer al enrutamiento por oficina.
  RETURN QUERY
  SELECT r.grupo_id, r.ejecutivo_id
  FROM tramites_grupos_reglas r
  JOIN tramites_grupos_visualizacion g ON g.id = r.grupo_id
  WHERE r.usuario_id = p_agente_id
    AND r.area       IS NULL
    AND r.activo     = true
    AND g.activo     = true
  LIMIT 1;

  IF FOUND THEN RETURN; END IF;

  -- ── Nivel 3: automático por oficina (equipos habilitados para el tipo) ───────
  -- Solo aplica si el agente no tiene ninguna regla individual (arriba). Nunca
  -- trae ejecutivo — es enrutamiento a nivel equipo, queda como "pool".
  IF v_tipo_id IS NOT NULL AND v_oficina_id IS NOT NULL THEN
    -- Prioridad: equipo con oficina específica coincidente
    RETURN QUERY
    SELECT g.id, NULL::uuid
    FROM tramite_team_tipo_config c
    JOIN tramites_grupos_visualizacion g ON g.id = c.team_id
    JOIN tramites_grupos_oficinas go ON go.grupo_id = g.id
    WHERE c.tipo_id     = v_tipo_id
      AND c.habilitado  = true
      AND g.activo      = true
      AND go.oficina_id = v_oficina_id
    LIMIT 1;

    IF FOUND THEN RETURN; END IF;

    -- Catch-all: equipo habilitado marcado "todas las oficinas"
    RETURN QUERY
    SELECT g.id, NULL::uuid
    FROM tramite_team_tipo_config c
    JOIN tramites_grupos_visualizacion g ON g.id = c.team_id
    WHERE c.tipo_id      = v_tipo_id
      AND c.habilitado   = true
      AND g.activo       = true
      AND g.all_offices  = true
    LIMIT 1;

    IF FOUND THEN RETURN; END IF;
  END IF;

  -- ── Nivel 4: nada encontrado -> sin filas (comportamiento actual) ────────────
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_home_latest_emissions(p_user_id uuid, p_limit integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
user_rol text;
user_oficina_id uuid;
result jsonb;
BEGIN
SELECT rol, oficina_id INTO user_rol, user_oficina_id
FROM usuarios WHERE id = p_user_id;

IF user_rol IS NULL THEN
RETURN '[]'::jsonb;
END IF;

IF user_rol IN ('Administrador', 'Gerente', 'Empleado') THEN
SELECT COALESCE(jsonb_agg(row_to_json(r)), '[]'::jsonb)
INTO result
FROM (
SELECT id, id_docto, poliza, cliente, compania, ramo, prima_neta, fecha_captura, status_texto
FROM sicas_documents
WHERE fecha_captura IS NOT NULL
AND (
user_rol = 'Administrador'
OR oficina_id = user_oficina_id
)
ORDER BY fecha_captura DESC
LIMIT p_limit
) r;
ELSE
-- Agente: use vendor mapping (fixed typo: mowi → movi)
SELECT COALESCE(jsonb_agg(row_to_json(r)), '[]'::jsonb)
INTO result
FROM (
SELECT sd.id, sd.id_docto, sd.poliza, sd.cliente, sd.compania, sd.ramo, sd.prima_neta, sd.fecha_captura, sd.status_texto
FROM sicas_documents sd
JOIN sicas_mapeo_vendedor_usuario m ON m.id_sicas_vendedor = sd.vend_id AND m.movi_user_id = p_user_id
WHERE sd.fecha_captura IS NOT NULL
ORDER BY sd.fecha_captura DESC
LIMIT p_limit
) r;
END IF;

RETURN result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_home_next_renewals(p_user_id uuid, p_limit integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
user_rol text;
user_oficina_id uuid;
result jsonb;
BEGIN
SELECT rol, oficina_id INTO user_rol, user_oficina_id
FROM usuarios WHERE id = p_user_id;

IF user_rol IS NULL THEN
RETURN '[]'::jsonb;
END IF;

IF user_rol IN ('Administrador', 'Gerente', 'Empleado') THEN
SELECT COALESCE(jsonb_agg(row_to_json(r)), '[]'::jsonb)
INTO result
FROM (
SELECT
id, id_docto, poliza, cliente, compania, ramo, prima_neta, vigencia_hasta,
GREATEST(0, EXTRACT(day FROM vigencia_hasta - NOW())::int) as dias_restantes,
CASE
WHEN vigencia_hasta <= NOW() + interval '7 days' THEN 'critico'
WHEN vigencia_hasta <= NOW() + interval '15 days' THEN 'urgente'
WHEN vigencia_hasta <= NOW() + interval '30 days' THEN 'proximo'
ELSE 'normal'
END as urgencia
FROM sicas_documents
WHERE vigencia_hasta > NOW()
AND vigencia_hasta < NOW() + interval '90 days'
AND is_vigente = true
AND (
user_rol = 'Administrador'
OR oficina_id = user_oficina_id
)
ORDER BY vigencia_hasta ASC
LIMIT p_limit
) r;
ELSE
-- Agente: use vendor mapping
SELECT COALESCE(jsonb_agg(row_to_json(r)), '[]'::jsonb)
INTO result
FROM (
SELECT
sd.id, sd.id_docto, sd.poliza, sd.cliente, sd.compania, sd.ramo, sd.prima_neta, sd.vigencia_hasta,
GREATEST(0, EXTRACT(day FROM sd.vigencia_hasta - NOW())::int) as dias_restantes,
CASE
WHEN sd.vigencia_hasta <= NOW() + interval '7 days' THEN 'critico'
WHEN sd.vigencia_hasta <= NOW() + interval '15 days' THEN 'urgente'
WHEN sd.vigencia_hasta <= NOW() + interval '30 days' THEN 'proximo'
ELSE 'normal'
END as urgencia
FROM sicas_documents sd
JOIN sicas_mapeo_vendedor_usuario m ON m.id_sicas_vendedor = sd.vend_id AND m.movi_user_id = p_user_id
WHERE sd.vigencia_hasta > NOW()
AND sd.vigencia_hasta < NOW() + interval '90 days'
AND sd.is_vigente = true
ORDER BY sd.vigencia_hasta ASC
LIMIT p_limit
) r;
END IF;

RETURN result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_home_production_comparison(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
user_rol text;
user_oficina_id uuid;
current_year int := EXTRACT(year FROM NOW())::int;
prev_year int := current_year - 1;
current_doy int := EXTRACT(doy FROM NOW())::int;
result jsonb;
curr_prima numeric := 0;
curr_polizas int := 0;
prev_prima numeric := 0;
prev_polizas int := 0;
meta_prima numeric := 0;
meta_polizas int := 0;
BEGIN
SELECT rol, oficina_id INTO user_rol, user_oficina_id
FROM usuarios WHERE id = p_user_id;

IF user_rol IS NULL THEN
RETURN jsonb_build_object('error', 'User not found');
END IF;

IF user_rol = 'Administrador' THEN
SELECT COALESCE(SUM(prima_neta), 0), COUNT(*)
INTO curr_prima, curr_polizas
FROM sicas_documents
WHERE fecha_captura >= make_date(current_year, 1, 1) AND fecha_captura < NOW();

SELECT COALESCE(SUM(prima_neta), 0), COUNT(*)
INTO prev_prima, prev_polizas
FROM sicas_documents
WHERE fecha_captura >= make_date(prev_year, 1, 1)
AND fecha_captura < (make_date(prev_year, 1, 1) + (current_doy || ' days')::interval);

ELSIF user_rol IN ('Gerente', 'Empleado') THEN
SELECT COALESCE(SUM(prima_neta), 0), COUNT(*)
INTO curr_prima, curr_polizas
FROM sicas_documents
WHERE fecha_captura >= make_date(current_year, 1, 1)
AND fecha_captura < NOW()
AND oficina_id = user_oficina_id;

SELECT COALESCE(SUM(prima_neta), 0), COUNT(*)
INTO prev_prima, prev_polizas
FROM sicas_documents
WHERE fecha_captura >= make_date(prev_year, 1, 1)
AND fecha_captura < (make_date(prev_year, 1, 1) + (current_doy || ' days')::interval)
AND oficina_id = user_oficina_id;

ELSE
-- Agente: use vendor mapping
SELECT COALESCE(SUM(sd.prima_neta), 0), COUNT(*)
INTO curr_prima, curr_polizas
FROM sicas_documents sd
JOIN sicas_mapeo_vendedor_usuario m ON m.id_sicas_vendedor = sd.vend_id AND m.movi_user_id = p_user_id
WHERE sd.fecha_captura >= make_date(current_year, 1, 1) AND sd.fecha_captura < NOW();

SELECT COALESCE(SUM(sd.prima_neta), 0), COUNT(*)
INTO prev_prima, prev_polizas
FROM sicas_documents sd
JOIN sicas_mapeo_vendedor_usuario m ON m.id_sicas_vendedor = sd.vend_id AND m.movi_user_id = p_user_id
WHERE sd.fecha_captura >= make_date(prev_year, 1, 1)
AND sd.fecha_captura < (make_date(prev_year, 1, 1) + (current_doy || ' days')::interval);
END IF;

meta_prima := prev_prima * 1.20;
meta_polizas := CEIL(prev_polizas * 1.20);

result := jsonb_build_object(
'current_year', current_year,
'prev_year', prev_year,
'current_prima', ROUND(curr_prima, 2),
'current_polizas', curr_polizas,
'prev_prima', ROUND(prev_prima, 2),
'prev_polizas', prev_polizas,
'meta_prima', ROUND(meta_prima, 2),
'meta_polizas', meta_polizas,
'growth_prima_pct', CASE WHEN prev_prima > 0 THEN ROUND(((curr_prima - prev_prima) / prev_prima) * 100, 1) ELSE 0 END,
'growth_polizas_pct', CASE WHEN prev_polizas > 0 THEN ROUND(((curr_polizas::numeric - prev_polizas) / prev_polizas) * 100, 1) ELSE 0 END,
'avance_meta_prima_pct', CASE WHEN meta_prima > 0 THEN ROUND((curr_prima / meta_prima) * 100, 1) ELSE 0 END,
'avance_meta_polizas_pct', CASE WHEN meta_polizas > 0 THEN ROUND((curr_polizas::numeric / meta_polizas) * 100, 1) ELSE 0 END
);

RETURN result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_import_diagnostic(p_batch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_result jsonb;
v_total_count int;
v_valid_count int;
v_warning_count int;
v_discard_count int;
v_batch_info jsonb;
v_top_reasons jsonb;
v_samples jsonb;
BEGIN
-- Obtener info del batch
SELECT jsonb_build_object(
'batch_id', id,
'file_name', file_name,
'sheet_name_used', sheet_name_used,
'detected_format', detected_format,
'imported_at', imported_at
)
INTO v_batch_info
FROM document_import_batches
WHERE id = p_batch_id;

-- Conteos por status
SELECT
COUNT(*) FILTER (WHERE status = 'valid'),
COUNT(*) FILTER (WHERE status = 'warning'),
COUNT(*) FILTER (WHERE status = 'discard'),
COUNT(*)
INTO v_valid_count, v_warning_count, v_discard_count, v_total_count
FROM document_import_items
WHERE import_batch_id = p_batch_id;

-- Top 10 razones de descarte
SELECT jsonb_agg(reason_data ORDER BY count DESC)
INTO v_top_reasons
FROM (
SELECT
discard_reason as reason,
COUNT(*) as count
FROM document_import_items
WHERE import_batch_id = p_batch_id
AND status = 'discard'
AND discard_reason IS NOT NULL
GROUP BY discard_reason
ORDER BY COUNT(*) DESC
LIMIT 10
) AS reason_data;

-- Muestras de filas descartadas (20 ejemplos)
SELECT jsonb_agg(sample_data ORDER BY row_index)
INTO v_samples
FROM (
SELECT
row_index,
vendor_name_raw,
documento,
ramo,
importe_base,
porcentaje,
fpago,
fpago_raw,
aseguradora,
discard_reason,
warnings
FROM document_import_items
WHERE import_batch_id = p_batch_id
AND status = 'discard'
ORDER BY row_index
LIMIT 20
) AS sample_data;

-- Construir resultado
v_result := jsonb_build_object(
'batch_info', COALESCE(v_batch_info, '{}'::jsonb),
'counts_by_status', jsonb_build_object(
'total', v_total_count,
'valid', v_valid_count,
'warning', v_warning_count,
'discard', v_discard_count
),
'top_discard_reasons', COALESCE(v_top_reasons, '[]'::jsonb),
'discard_samples', COALESCE(v_samples, '[]'::jsonb),
'insertables', v_valid_count + v_warning_count
);

RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_insertable_items(p_batch_id uuid)
 RETURNS TABLE(id uuid, row_index integer, agent_key text, agent_name_raw text, agent_name_norm text, agent_name_signature text, documento text, endoso text, fpago date, aseguradora text, ramo text, importe_base numeric, porcentaje numeric, comision_calculada numeric, prima_neta_info numeric, concepto text, oficina text, movi_user_id uuid, match_status text, match_method text, match_confidence integer, raw_json jsonb)
 LANGUAGE plpgsql
AS $function$
BEGIN
RETURN QUERY
SELECT
i.id,
i.row_index,
i.agent_key,
i.agent_name_raw,
i.agent_name_norm,
i.agent_name_signature,
i.documento,
i.endoso,
i.fpago,
i.aseguradora,
i.ramo,
i.importe_base,
i.porcentaje,
i.comision_calculada,
i.prima_neta_info,
i.concepto,
i.oficina,
i.movi_user_id,
i.match_status,
i.match_method,
i.match_confidence,
i.raw_json
FROM document_import_items i
WHERE i.import_batch_id = p_batch_id
AND i.status IN ('valid', 'warning')
ORDER BY i.row_index;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_latest_successful_batch()
 RETURNS uuid
 LANGUAGE sql
 STABLE
AS $function$
SELECT id 
FROM production_import_batches
WHERE status = 'success' 
AND visible_to_agents = true
ORDER BY finished_at DESC NULLS LAST, created_at DESC
LIMIT 1;
$function$
;

CREATE OR REPLACE FUNCTION public.get_lesson_categories(p_lesson_id uuid)
 RETURNS TABLE(category_id uuid, category_name text, category_icon text)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
RETURN QUERY
SELECT
sc.id,
sc.nombre,
sc.icono
FROM seguros_lesson_categories slc
JOIN seguros_categories sc ON sc.id = slc.category_id
WHERE slc.lesson_id = p_lesson_id
ORDER BY sc.nombre;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_logo_info(user_id_input uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE
result jsonb;
BEGIN
SELECT jsonb_build_object(
'usuario_id', u.id,
'usuario_nombre', u.nombre || ' ' || u.apellidos,
'mi_logotipo_url', u.mi_logotipo_url,
'oficina_id', o.id,
'oficina_nombre', o.nombre,
'oficina_logo_url', o.logo_url,
'logo_efectivo', COALESCE(
NULLIF(u.mi_logotipo_url, ''),
NULLIF(o.logo_url, ''),
'/logojiro.png'
),
'origen_logo', CASE
WHEN u.mi_logotipo_url IS NOT NULL AND u.mi_logotipo_url != '' THEN 'usuario'
WHEN o.logo_url IS NOT NULL AND o.logo_url != '' THEN 'oficina'
ELSE 'jiro'
END
)
INTO result
FROM public.usuarios u
LEFT JOIN public.oficinas o ON u.oficina_id = o.id
WHERE u.id = user_id_input
LIMIT 1;

RETURN COALESCE(result, jsonb_build_object('error', 'Usuario no encontrado'));
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_matched_vendors_by_name(p_batch_id uuid)
 RETURNS TABLE(movi_user_id uuid, user_name text, user_email text, document_count bigint, vendor_names_detected text[], vendor_emails_detected text[], example_documents jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_is_converted BOOLEAN;
v_commission_batch_ids UUID[];
BEGIN
-- Verificar si el lote ha sido convertido a comisiones
SELECT
EXISTS (
SELECT 1 FROM commission_batches cb
WHERE cb.source_import_batch_id = p_batch_id
)
INTO v_is_converted;

IF v_is_converted THEN
-- CASO 1: El lote ha sido convertido a comisiones
-- Buscar en commission_batches y commission_details

-- Obtener IDs de los lotes de comisiones generados
SELECT ARRAY_AGG(cb.id)
INTO v_commission_batch_ids
FROM commission_batches cb
WHERE cb.source_import_batch_id = p_batch_id;

-- Agrupar por usuario_id
RETURN QUERY
SELECT
cd.usuario_id as movi_user_id,
u.nombre_completo as user_name,
COALESCE(u.email_laboral, u.email_personal) as user_email,
COUNT(cd.id) as document_count,
ARRAY(
SELECT DISTINCT cd2.vendor_name
FROM commission_details cd2
WHERE cd2.batch_id = ANY(v_commission_batch_ids)
AND cd2.usuario_id = cd.usuario_id
AND cd2.vendor_name IS NOT NULL
AND cd2.vendor_name != ''
) as vendor_names_detected,
ARRAY[]::TEXT[] as vendor_emails_detected, -- No hay emails en commission_details
(
SELECT jsonb_agg(
jsonb_build_object(
'poliza', cd4.poliza,
'aseguradora', cd4.aseguradora,
'vendor_name', cd4.vendor_name,
'commission_bruta', cd4.commission_bruta
)
)
FROM (
SELECT cd4.poliza, cd4.aseguradora, cd4.vendor_name, cd4.commission_bruta, cd4.created_at
FROM commission_details cd4
WHERE cd4.batch_id = ANY(v_commission_batch_ids)
AND cd4.usuario_id = cd.usuario_id
ORDER BY cd4.created_at DESC
LIMIT 10
) sample_docs
) as example_documents
FROM commission_details cd
LEFT JOIN usuarios u ON u.id = cd.usuario_id
WHERE cd.batch_id = ANY(v_commission_batch_ids)
AND cd.usuario_id IS NOT NULL
AND cd.pending_assignment = false
GROUP BY cd.usuario_id, u.nombre_completo, u.email_laboral, u.email_personal
ORDER BY document_count DESC;

ELSE
-- CASO 2: El lote AÚN NO ha sido convertido a comisiones
-- Buscar en imported_documents
RETURN QUERY
SELECT
doc.movi_user_id,
u.nombre_completo as user_name,
COALESCE(u.email_laboral, u.email_personal) as user_email,
COUNT(doc.id) as document_count,
ARRAY(
SELECT DISTINCT unnest(ARRAY_AGG(doc2.vendor_name_raw))
FROM imported_documents doc2
WHERE doc2.batch_id = p_batch_id
AND doc2.is_unmatched = false
AND doc2.movi_user_id = doc.movi_user_id
AND doc2.vendor_name_raw IS NOT NULL
AND doc2.vendor_name_raw != ''
) as vendor_names_detected,
ARRAY(
SELECT DISTINCT unnest(ARRAY_AGG(doc3.vendor_email_raw))
FROM imported_documents doc3
WHERE doc3.batch_id = p_batch_id
AND doc3.is_unmatched = false
AND doc3.movi_user_id = doc.movi_user_id
AND doc3.vendor_email_raw IS NOT NULL
AND doc3.vendor_email_raw != ''
) as vendor_emails_detected,
(
SELECT jsonb_agg(
jsonb_build_object(
'id', doc4.id,
'poliza', doc4.poliza,
'aseguradora', doc4.aseguradora,
'vendor_name_raw', doc4.vendor_name_raw,
'vendor_email_raw', doc4.vendor_email_raw,
'importe_comision', doc4.importe_comision
)
)
FROM (
SELECT doc4.*
FROM imported_documents doc4
WHERE doc4.batch_id = p_batch_id
AND doc4.is_unmatched = false
AND doc4.movi_user_id = doc.movi_user_id
ORDER BY doc4.created_at DESC
LIMIT 10
) sample_docs
) as example_documents
FROM imported_documents doc
LEFT JOIN usuarios u ON u.id = doc.movi_user_id
WHERE doc.batch_id = p_batch_id
AND doc.is_unmatched = false
AND doc.movi_user_id IS NOT NULL
GROUP BY doc.movi_user_id, u.nombre_completo, u.email_laboral, u.email_personal
ORDER BY document_count DESC;

END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_mi_agente(p_user_id uuid)
 RETURNS TABLE(agente_id uuid, nombre text, despacho text, gerencia text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  SELECT
    a.id             AS agente_id,
    a.nombre,
    d.nombre         AS despacho,
    g.nombre         AS gerencia
  FROM   public.maestro_usuario_agente mua
  JOIN   public.maestro_agentes     a ON a.id = mua.agente_id
  JOIN   public.maestro_despachos   d ON d.id = a.despacho_id
  LEFT JOIN public.maestro_gerencias g ON g.id = a.gerencia_id
  WHERE  mua.user_id = p_user_id
    AND  mua.activo  = true
    AND  a.activo    = true
  LIMIT 1;
$function$
;

