CREATE OR REPLACE FUNCTION public.get_next_alternate_report()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_config RECORD;
v_current_index INT;
v_next_code TEXT;
BEGIN
-- Obtener configuración actual
SELECT * INTO v_config
FROM sicas_config
LIMIT 1;

IF NOT FOUND THEN
RETURN 'H03117';
END IF;

-- Buscar índice del código actual
SELECT idx - 1 INTO v_current_index
FROM unnest(v_config.alternate_report_codes) WITH ORDINALITY AS t(code, idx)
WHERE code = v_config.current_report_code;

-- Si no se encontró o es el último, volver al primero
IF v_current_index IS NULL OR v_current_index >= array_length(v_config.alternate_report_codes, 1) THEN
v_next_code := v_config.alternate_report_codes[1];
ELSE
v_next_code := v_config.alternate_report_codes[v_current_index + 2];
END IF;

RETURN v_next_code;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_notification_channel(p_type text, p_channel_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_channel notification_channels;
BEGIN
-- 1. Canal específico solicitado
IF p_channel_id IS NOT NULL THEN
SELECT * INTO v_channel
FROM notification_channels
WHERE id = p_channel_id AND type = p_type AND is_active = true;

IF FOUND THEN
RETURN row_to_json(v_channel)::jsonb;
END IF;
END IF;

-- 2. Canal default activo
SELECT * INTO v_channel
FROM notification_channels
WHERE type = p_type AND is_active = true AND is_default = true
LIMIT 1;

IF FOUND THEN
RETURN row_to_json(v_channel)::jsonb;
END IF;

-- 3. Cualquier canal activo del tipo
SELECT * INTO v_channel
FROM notification_channels
WHERE type = p_type AND is_active = true
ORDER BY created_at ASC
LIMIT 1;

IF FOUND THEN
RETURN row_to_json(v_channel)::jsonb;
END IF;

RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_notification_channel_for_platform(p_platform text, p_channel_type text)
 RETURNS TABLE(id uuid, name text, type text, provider text, config jsonb, branding jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_channel_name text;
BEGIN
-- Map platform + channel_type to the correct notification_channels row
IF p_channel_type = 'email' THEN
IF p_platform = 'seguwallet' THEN
v_channel_name := 'Resend Seguwallet';
ELSE
v_channel_name := 'Resend Default';
END IF;
ELSIF p_channel_type = 'whatsapp' THEN
IF p_platform = 'seguwallet' THEN
v_channel_name := 'WhatsApp Seguwallet';
ELSE
v_channel_name := 'WhatsApp Default';
END IF;
END IF;

RETURN QUERY
SELECT nc.id, nc.name, nc.type, nc.provider, nc.config, nc.branding
FROM notification_channels nc
WHERE nc.name = v_channel_name
AND nc.is_active = true
LIMIT 1;

-- Fallback to default channel if specific not found
IF NOT FOUND THEN
RETURN QUERY
SELECT nc.id, nc.name, nc.type, nc.provider, nc.config, nc.branding
FROM notification_channels nc
WHERE nc.is_default = true
AND nc.type = CASE 
WHEN p_channel_type = 'email' THEN 'email_resend'
WHEN p_channel_type = 'whatsapp' THEN 'whatsapp_wazzup24'
END
LIMIT 1;
END IF;

RETURN;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_office_users_for_requester()
 RETURNS TABLE(id uuid, nombre_completo text, rol text, oficina_id uuid, oficina_nombre text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_user_rol text;
v_user_oficina_id uuid;
BEGIN
-- Obtener rol y oficina del usuario actual
SELECT usuarios.rol, usuarios.oficina_id 
INTO v_user_rol, v_user_oficina_id
FROM usuarios
WHERE usuarios.id = auth.uid();

-- Retornar usuarios según permisos
RETURN QUERY
SELECT 
u.id,
u.nombre_completo,
u.rol,
u.oficina_id,
o.nombre as oficina_nombre
FROM usuarios u
LEFT JOIN oficinas o ON o.id = u.oficina_id
WHERE u.estado = 'activo'
AND u.deleted_at IS NULL
AND (
-- Admin ve todos
v_user_rol = 'Administrador'
OR
-- Gerente ve usuarios de su oficina
(v_user_rol = 'Gerente' AND u.oficina_id = v_user_oficina_id)
OR
-- Empleado ve usuarios de su oficina
(v_user_rol = 'Empleado' AND u.oficina_id = v_user_oficina_id)
)
ORDER BY u.nombre_completo;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_or_create_active_conversation(p_usuario_id uuid, p_modulo text, p_titulo text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_conversation_id uuid;
v_titulo text;
BEGIN
SELECT id INTO v_conversation_id
FROM conversaciones_chatgpt
WHERE usuario_id = p_usuario_id
AND modulo_origen = p_modulo
AND es_asistente = true
AND updated_at > now() - interval '24 hours'
ORDER BY updated_at DESC
LIMIT 1;

IF v_conversation_id IS NOT NULL THEN
RETURN v_conversation_id;
END IF;

v_titulo := COALESCE(p_titulo, 'Conversación en ' || p_modulo);

INSERT INTO conversaciones_chatgpt (usuario_id, titulo, es_asistente, modulo_origen)
VALUES (p_usuario_id, v_titulo, true, p_modulo)
RETURNING id INTO v_conversation_id;

RETURN v_conversation_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_or_create_direct_chat(p_user1_id uuid, p_user2_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_chat_id uuid;
BEGIN
-- Buscar chat directo existente entre estos dos usuarios
SELECT c.id INTO v_chat_id
FROM chats c
WHERE c.tipo = 'direct'
AND EXISTS (
SELECT 1 FROM chat_miembros cm1
WHERE cm1.chat_id = c.id AND cm1.usuario_id = p_user1_id
)
AND EXISTS (
SELECT 1 FROM chat_miembros cm2
WHERE cm2.chat_id = c.id AND cm2.usuario_id = p_user2_id
)
AND (
SELECT COUNT(*) FROM chat_miembros
WHERE chat_miembros.chat_id = c.id
) = 2
LIMIT 1;

-- Si existe, retornar el ID
IF v_chat_id IS NOT NULL THEN
RETURN v_chat_id;
END IF;

-- Si no existe, crear nuevo chat
INSERT INTO chats (tipo, creador_id, ultimo_mensaje_at)
VALUES ('direct', p_user1_id, now())
RETURNING id INTO v_chat_id;

-- Agregar ambos usuarios como miembros
INSERT INTO chat_miembros (chat_id, usuario_id, unido_at)
VALUES 
(v_chat_id, p_user1_id, now()),
(v_chat_id, p_user2_id, now());

RETURN v_chat_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_permisos_adicionales_usuario(p_usuario_id uuid)
 RETURNS TABLE(modulo_id uuid, modulo_codigo text, modulo_nombre text, categoria text, fecha_asignacion timestamp with time zone)
