CREATE OR REPLACE FUNCTION public.get_production_cache_metadata(p_cache_key text DEFAULT 'production_vendors_main'::text)
 RETURNS TABLE(last_fetched_at timestamp with time zone, last_fetch_duration_ms integer, total_records integer, total_vendors integer, ttl_minutes integer, is_valid boolean, minutes_until_expiry numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
RETURN QUERY
SELECT
pcm.last_fetched_at,
pcm.last_fetch_duration_ms,
pcm.total_records,
pcm.total_vendors,
pcm.ttl_minutes,
is_production_cache_valid(p_cache_key) as is_valid,
CASE
WHEN is_production_cache_valid(p_cache_key) THEN
EXTRACT(EPOCH FROM (pcm.last_fetched_at + (pcm.ttl_minutes * INTERVAL '1 minute') - NOW())) / 60
ELSE
0
END as minutes_until_expiry
FROM production_cache_metadata pcm
WHERE pcm.cache_key = p_cache_key;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_public_agenda_event_type(p_event_type_id uuid)
 RETURNS TABLE(id uuid, calendar_id uuid, name text, description text, color text, duration_minutes integer, buffer_before_minutes integer, buffer_after_minutes integer, min_notice_minutes integer, daily_limit integer, allowed_locations jsonb, location_details jsonb, is_active boolean, calendar_name text, timezone text, organizer_name text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$select et.id,et.calendar_id,et.name,et.description,et.color,et.duration_minutes,et.buffer_before_minutes,et.buffer_after_minutes,et.min_notice_minutes,et.daily_limit,et.allowed_locations,et.location_details,et.is_active,c.name,c.timezone,coalesce(u.nombre_publico,u.nombre_completo,'Asesor') from agenda_event_types et join agenda_calendars c on c.id=et.calendar_id join usuarios u on u.id=c.user_id where et.id=p_event_type_id and et.is_active and c.is_active$function$
;

CREATE OR REPLACE FUNCTION public.get_public_web_page(p_slug text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_result json;
  v_app_url text := 'https://agentedeseguros.website';
  v_storage_url text;
BEGIN
  v_storage_url := current_setting('app.settings.storage_url', true);
  
  SELECT json_build_object(
    'user', json_build_object(
      'name', u.nombre_completo,
      'email', u.email_laboral,
      'phone', u.celular_laboral,
      'photo_url', CASE 
        WHEN u.imagen_perfil_url IS NOT NULL AND u.imagen_perfil_url != '' 
        THEN u.imagen_perfil_url
        ELSE v_app_url || '/display-avatar.png'
      END,
      'logo_url', u.mi_logotipo_url,
      'office_name', o.nombre,
      'web_slug', u.web_slug
    ),
    'config', json_build_object(
      'primary_color', COALESCE(wc.primary_color, '#2563eb'),
      'secondary_color', COALESCE(wc.secondary_color, '#1e40af'),
      'custom_text', COALESCE(wc.custom_text, '')
    ),
    'insurers', COALESCE(
      (SELECT json_agg(json_build_object(
        'id', i.id,
        'name', i.nombre,
        'logo_url', i.logo_url
      ))
      FROM web_page_insurers wpi
      JOIN web_catalogos_aseguradoras i ON i.id = wpi.insurer_id
      WHERE wpi.user_id = u.id AND wpi.active = true
      ), '[]'::json
    ),
    'categories', COALESCE(
      (SELECT json_agg(json_build_object(
        'id', c.id,
        'name', c.nombre,
        'icon', c.icono,
        'description', c.descripcion
      ))
      FROM web_page_categories wpc
      JOIN web_catalogos_categorias c ON c.id = wpc.category_id
      WHERE wpc.user_id = u.id AND wpc.active = true
      ), '[]'::json
    )
  ) INTO v_result
  FROM usuarios u
  LEFT JOIN oficinas o ON o.id = u.oficina_id
  LEFT JOIN web_page_config wc ON wc.user_id = u.id
  WHERE u.web_slug = p_slug
    AND u.estado = 'activo'
    AND u.deleted_at IS NULL;

  RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_public_web_page_by_slug(p_slug text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_user_id uuid;
v_user_record record;
v_config record;
v_office_record record;
v_result json;
v_insurers json;
v_form_links json;
v_form_templates json;
v_has_featured boolean;
v_user_name text;
v_links_exist boolean;
BEGIN
-- Find user by web_slug
SELECT id, nombre, apellidos, nombre_publico, email_laboral,
celular_laboral, mi_logotipo_url, imagen_perfil_url, oficina_id
INTO v_user_record
FROM usuarios
WHERE web_slug = p_slug
AND activo = true
AND (deleted_at IS NULL)
LIMIT 1;

IF v_user_record.id IS NULL THEN
RETURN NULL;
END IF;

v_user_id := v_user_record.id;

-- Build user display name
v_user_name := COALESCE(
NULLIF(TRIM(v_user_record.nombre_publico), ''),
TRIM(COALESCE(v_user_record.nombre, '') || ' ' || COALESCE(v_user_record.apellidos, ''))
);

-- Get office info
IF v_user_record.oficina_id IS NOT NULL THEN
SELECT nombre, logo_url
INTO v_office_record
FROM oficinas
WHERE id = v_user_record.oficina_id
LIMIT 1;
END IF;

-- Ensure shared links exist for this user (lazy provision)
SELECT EXISTS(
SELECT 1 FROM shared_quote_form_links
WHERE agent_id = v_user_id AND status = 'active'
LIMIT 1
) INTO v_links_exist;

IF NOT v_links_exist THEN
PERFORM provision_shared_links_for_user(v_user_id);
END IF;

-- Get web page config
SELECT *
INTO v_config
FROM user_web_pages
WHERE user_id = v_user_id
LIMIT 1;

-- Check if user has configured any featured forms
SELECT EXISTS(
SELECT 1 FROM user_web_featured_forms WHERE user_id = v_user_id
) INTO v_has_featured;

-- Get all active form templates with featured status AND public_url from shared links
SELECT COALESCE(json_agg(
json_build_object(
'id', qft.id,
'form_type', qft.form_type,
'title', qft.title,
'category', qft.category,
'icon', qft.icon,
'slug', qft.slug,
'public_url', sqfl.public_url,
'link_slug', sqfl.slug,
'is_featured', CASE
WHEN v_has_featured THEN (uwff.id IS NOT NULL)
ELSE (qft.form_type IN ('auto_individual', 'vida_individual', 'gmm_individual', 'hogar_casa_habitacion', 'accidentes_personales_individual', 'empresa_paquete'))
END,
'featured_order', CASE
WHEN v_has_featured THEN COALESCE(uwff.featured_order, 999)
ELSE CASE qft.form_type
WHEN 'auto_individual' THEN 1
WHEN 'vida_individual' THEN 2
WHEN 'gmm_individual' THEN 3
WHEN 'hogar_casa_habitacion' THEN 4
WHEN 'accidentes_personales_individual' THEN 5
WHEN 'empresa_paquete' THEN 6
ELSE 999
END
END
) ORDER BY
CASE
WHEN v_has_featured THEN COALESCE(uwff.featured_order, 999)
ELSE CASE qft.form_type
WHEN 'auto_individual' THEN 1
WHEN 'vida_individual' THEN 2
WHEN 'gmm_individual' THEN 3
WHEN 'hogar_casa_habitacion' THEN 4
WHEN 'accidentes_personales_individual' THEN 5
WHEN 'empresa_paquete' THEN 6
ELSE 999
END
END,
qft.category, qft.title
), '[]'::json)
INTO v_form_templates
FROM quote_form_templates qft
LEFT JOIN user_web_featured_forms uwff
ON uwff.form_template_id = qft.id AND uwff.user_id = v_user_id
LEFT JOIN shared_quote_form_links sqfl
ON sqfl.quote_form_template_id = qft.id AND sqfl.agent_id = v_user_id AND sqfl.status = 'active'
WHERE qft.is_active = true;

-- Get insurers
SELECT COALESCE(json_agg(
json_build_object(
'id', wpi.id,
'name', wpi.name,
'logo_url', wpi.logo_url
) ORDER BY wpi.name
), '[]'::json)
INTO v_insurers
FROM user_web_page_insurers uwpi
JOIN web_page_insurers wpi ON wpi.id = uwpi.insurer_id
WHERE uwpi.user_web_page_id = (SELECT id FROM user_web_pages WHERE user_id = v_user_id LIMIT 1);

-- Get active shared quote form links (for backward compat)
SELECT COALESCE(json_agg(
json_build_object(
'slug', sqfl.slug,
'form_title', sqfl.form_title,
'form_type', sqfl.form_type,
'form_slug', sqfl.form_slug,
'quote_form_template_id', sqfl.quote_form_template_id,
'featured_on_website', sqfl.featured_on_website,
'featured_order', sqfl.featured_order
) ORDER BY sqfl.created_at
), '[]'::json)
INTO v_form_links
FROM shared_quote_form_links sqfl
WHERE sqfl.agent_id = v_user_id
AND sqfl.status = 'active';

-- Build result
v_result := json_build_object(
'user', json_build_object(
'id', v_user_record.id,
'name', v_user_name,
'email', v_user_record.email_laboral,
'phone', v_user_record.celular_laboral,
'photo_url', v_user_record.imagen_perfil_url,
'logo_url', v_user_record.mi_logotipo_url,
'office', CASE 
WHEN v_office_record.nombre IS NOT NULL THEN
json_build_object(
'name', v_office_record.nombre,
'logo_url', v_office_record.logo_url
)
ELSE NULL
END
),
'config', CASE WHEN v_config IS NOT NULL THEN
json_build_object(
'id', v_config.id,
'primary_color', v_config.primary_color,
'secondary_color', v_config.secondary_color,
'custom_text', v_config.custom_text,
'is_published', v_config.is_published
)
ELSE NULL END,
'insurers', v_insurers,
'form_links', v_form_links,
'form_templates', v_form_templates
);

RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_public_website_calendar_blocks(p_slug text)
 RETURNS TABLE(id uuid, name text, description text, duration_minutes integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$select et.id,et.name,et.description,et.duration_minutes from website_calendar_blocks wb join usuarios u on u.id=wb.user_id join agenda_event_types et on et.id=wb.event_type_id join agenda_calendars c on c.id=et.calendar_id where u.web_slug=p_slug and wb.is_visible and et.is_active and c.is_active order by wb.display_order,wb.created_at$function$
;

CREATE OR REPLACE FUNCTION public.get_ramos_por_compania(p_compania_id uuid)
 RETURNS TABLE(id uuid, nombre text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  SELECT DISTINCT mr.id, mr.nombre
  FROM   public.maestro_ramos mr
  JOIN   public.maestro_combinaciones c ON c.ramo_id = mr.id
  WHERE  c.compania_id = p_compania_id
    AND  c.activo      = true
    AND  mr.activo     = true
  ORDER  BY mr.nombre;
$function$
;

