;

CREATE OR REPLACE FUNCTION public.get_seguwallet_policy_billing(p_auth_id uuid, p_poliza text, p_id_docto text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, cliente text, no_poliza text, id_documento text, importe_pendiente numeric, fecha_limite timestamp with time zone, dias_vencidos integer, status text, vend_id text, vend_nombre text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_customer_id uuid;
BEGIN
-- 1. Resolve customer
SELECT sc.id INTO v_customer_id
FROM seguwallet_customers sc
WHERE sc.auth_user_id = p_auth_id
AND sc.status = 'active'
AND sc.deleted_at IS NULL
LIMIT 1;

IF v_customer_id IS NULL THEN
INSERT INTO seguwallet_billing_logs(customer_id, poliza, id_docto, result, error_message)
VALUES (NULL, p_poliza, p_id_docto, 'denied', 'customer_not_found');
RETURN;
END IF;

-- 2. Validate policy belongs to one of this customer's SICAS clients
IF NOT EXISTS (
SELECT 1 FROM sicas_documents d
JOIN seguwallet_customer_sicas_clients sc_link
ON sc_link.sicas_client_id = d.cliente
AND sc_link.seguwallet_customer_id = v_customer_id
WHERE d.poliza = p_poliza
AND d.is_poliza = true
) THEN
INSERT INTO seguwallet_billing_logs(customer_id, poliza, id_docto, result, error_message)
VALUES (v_customer_id, p_poliza, p_id_docto, 'denied', 'policy_not_owned');
RETURN;
END IF;

-- 3. Log successful query
INSERT INTO seguwallet_billing_logs(customer_id, poliza, id_docto, result, records_returned)
SELECT
v_customer_id, p_poliza, p_id_docto, 'success',
COUNT(*)::integer
FROM sicas_cobranza_pendiente c
WHERE c.no_poliza = p_poliza;

-- 4. Return billing records
RETURN QUERY
SELECT
c.id,
c.cliente,
c.no_poliza,
c.id_documento,
c.importe_pendiente,
c.fecha_limite,
c.dias_vencidos,
c.status,
c.vend_id,
c.vend_nombre
FROM sicas_cobranza_pendiente c
WHERE c.no_poliza = p_poliza
ORDER BY c.fecha_limite ASC NULLS LAST;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_seguwallet_poliza_counts(p_auth_id uuid)
 RETURNS TABLE(total_vigentes bigint, proximas_vencer bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
SELECT
COUNT(*) FILTER (WHERE d.is_vigente = true) AS total_vigentes,
COUNT(*) FILTER (
WHERE d.is_vigente = true
AND d.vigencia_hasta <= (CURRENT_DATE + INTERVAL '30 days')
) AS proximas_vencer
FROM sicas_documents d
WHERE d.is_poliza = true
AND d.cliente IN (
SELECT sc_link.sicas_client_id
FROM seguwallet_customer_sicas_clients sc_link
JOIN seguwallet_customers sc ON sc.id = sc_link.seguwallet_customer_id
WHERE sc.auth_user_id = p_auth_id
AND sc.status = 'active'
);
$function$
;

CREATE OR REPLACE FUNCTION public.get_seguwallet_polizas(p_auth_id uuid)
 RETURNS TABLE(id uuid, id_docto text, poliza text, aseguradora_nombre text, compania text, ramo text, subramo text, tipo_documento text, subtipo_documento text, cliente text, vend_nombre text, agente_nombre text, desp_nombre text, oficina_nombre text, vigencia_desde timestamp with time zone, vigencia_hasta timestamp with time zone, fecha_emision timestamp with time zone, fecha_captura timestamp with time zone, is_vigente boolean, is_cancelada boolean, is_renewable boolean, renewal_days_remaining integer, status_texto text, status_cobro text, prima_neta numeric, prima_total numeric, derechos numeric, impuestos numeric, recargos numeric, importe numeric, moneda text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
SELECT
d.id,
d.id_docto,
d.poliza,
d.aseguradora_nombre,
d.compania,
d.ramo,
d.subramo,
d.tipo_documento,
d.subtipo_documento,
d.cliente,
d.vend_nombre,
d.agente_nombre,
d.desp_nombre,
d.oficina_nombre,
d.vigencia_desde,
d.vigencia_hasta,
d.fecha_emision,
d.fecha_captura,
d.is_vigente,
d.is_cancelada,
d.is_renewable,
d.renewal_days_remaining,
d.status_texto,
d.status_cobro,
d.prima_neta,
d.prima_total,
d.derechos,
d.impuestos,
d.recargos,
d.importe,
d.moneda
FROM sicas_documents d
WHERE d.is_poliza = true
AND d.cliente IN (
SELECT sc_link.sicas_client_id
FROM seguwallet_customer_sicas_clients sc_link
JOIN seguwallet_customers sc ON sc.id = sc_link.seguwallet_customer_id
WHERE sc.auth_user_id = p_auth_id
AND sc.status = 'active'
)
ORDER BY d.vigencia_hasta DESC NULLS LAST
LIMIT 300;
$function$
;

CREATE OR REPLACE FUNCTION public.get_sicas_avance_comercial(p_user_id uuid, p_scope text DEFAULT NULL::text, p_oficina_id uuid DEFAULT NULL::uuid, p_vendedor_id text DEFAULT NULL::text, p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
v_rol text;
v_oficina uuid;
v_scope text;
v_vend_id text;

v_desde date;
v_hasta date;
v_desde_ant date;
v_hasta_ant date;
v_ytd_desde date;
v_ytd_hasta date;
v_ytd_ant_desde date;
v_ytd_ant_hasta date;
v_anio_ant_desde date;
v_anio_ant_hasta date;
v_dia_del_mes int;
v_mes_actual int;

v_cur_prima numeric;
v_cur_polizas int;
v_cur_fianzas int;
v_cur_total int;
v_cur_clientes int;
v_cur_prima_total numeric;

v_ant_prima numeric;
v_ant_polizas int;
v_ant_fianzas int;
v_ant_total int;
v_ant_clientes int;
v_ant_prima_total numeric;

v_ytd_prima numeric;
v_ytd_polizas int;
v_ytd_total int;

v_ytd_ant_prima numeric;
v_ytd_ant_polizas int;
v_ytd_ant_total int;

v_full_ant_prima numeric;
v_full_ant_polizas int;
v_full_ant_total int;

v_meta_prima numeric;
v_meta_polizas numeric;
v_meta_mensual_prima numeric;
v_meta_mensual_polizas numeric;
BEGIN
SELECT rol, oficina_id INTO v_rol, v_oficina FROM usuarios WHERE id = p_user_id;
IF v_rol IS NULL THEN
RETURN jsonb_build_object('error', 'Usuario no encontrado');
END IF;

IF v_rol = 'Administrador' THEN
v_scope := COALESCE(p_scope, 'admin');
ELSIF v_rol IN ('Gerente', 'Empleado', 'Ejecutivo') THEN
v_scope := COALESCE(p_scope, 'office');
IF v_scope = 'admin' THEN v_scope := 'office'; END IF;
ELSE
v_scope := 'self';
END IF;

IF p_oficina_id IS NOT NULL AND v_scope = 'admin' THEN
v_oficina := p_oficina_id;
v_scope := 'office';
ELSIF v_scope = 'office' THEN
v_oficina := COALESCE(p_oficina_id, v_oficina);
END IF;

IF v_scope = 'self' THEN
v_vend_id := get_sicas_user_vend_id(p_user_id);
END IF;

v_desde := COALESCE(p_fecha_desde, date_trunc('month', CURRENT_DATE)::date);
v_hasta := COALESCE(p_fecha_hasta, CURRENT_DATE);
v_desde_ant := v_desde - interval '1 year';
v_hasta_ant := v_hasta - interval '1 year';

v_ytd_desde := date_trunc('year', CURRENT_DATE)::date;
v_ytd_hasta := CURRENT_DATE;
v_ytd_ant_desde := (date_trunc('year', CURRENT_DATE) - interval '1 year')::date;
v_ytd_ant_hasta := (CURRENT_DATE - interval '1 year')::date;

v_anio_ant_desde := (date_trunc('year', CURRENT_DATE) - interval '1 year')::date;
v_anio_ant_hasta := (date_trunc('year', CURRENT_DATE) - interval '1 day')::date;

v_dia_del_mes := EXTRACT(DAY FROM CURRENT_DATE)::int;
v_mes_actual := EXTRACT(MONTH FROM CURRENT_DATE)::int;

-- CURRENT PERIOD
SELECT
COALESCE(SUM(d.prima_neta), 0),
COALESCE(SUM(GREATEST(COALESCE(d.prima_total, 0), COALESCE(d.importe, 0))), 0),
COUNT(*) FILTER (WHERE NOT COALESCE(d.is_fianza, false)),
COUNT(*) FILTER (WHERE COALESCE(d.is_fianza, false)),
COUNT(*),
COUNT(DISTINCT d.cliente)
INTO v_cur_prima, v_cur_prima_total, v_cur_polizas, v_cur_fianzas, v_cur_total, v_cur_clientes
FROM sicas_documents d
WHERE d.fecha_captura::date BETWEEN v_desde AND v_hasta
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id);

-- SAME PERIOD LAST YEAR
SELECT
COALESCE(SUM(d.prima_neta), 0),
COALESCE(SUM(GREATEST(COALESCE(d.prima_total, 0), COALESCE(d.importe, 0))), 0),
COUNT(*) FILTER (WHERE NOT COALESCE(d.is_fianza, false)),
COUNT(*) FILTER (WHERE COALESCE(d.is_fianza, false)),
COUNT(*),
COUNT(DISTINCT d.cliente)
INTO v_ant_prima, v_ant_prima_total, v_ant_polizas, v_ant_fianzas, v_ant_total, v_ant_clientes
FROM sicas_documents d
WHERE d.fecha_captura::date BETWEEN v_desde_ant AND v_hasta_ant
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id);

-- YTD CURRENT
SELECT
COALESCE(SUM(d.prima_neta), 0),
COUNT(*) FILTER (WHERE NOT COALESCE(d.is_fianza, false)),
COUNT(*)
INTO v_ytd_prima, v_ytd_polizas, v_ytd_total
FROM sicas_documents d
WHERE d.fecha_captura::date BETWEEN v_ytd_desde AND v_ytd_hasta
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id);

-- YTD LAST YEAR
SELECT
COALESCE(SUM(d.prima_neta), 0),
COUNT(*) FILTER (WHERE NOT COALESCE(d.is_fianza, false)),
COUNT(*)
INTO v_ytd_ant_prima, v_ytd_ant_polizas, v_ytd_ant_total
FROM sicas_documents d
WHERE d.fecha_captura::date BETWEEN v_ytd_ant_desde AND v_ytd_ant_hasta
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id);

-- FULL PREVIOUS YEAR
SELECT
COALESCE(SUM(d.prima_neta), 0),
COUNT(*) FILTER (WHERE NOT COALESCE(d.is_fianza, false)),
COUNT(*)
INTO v_full_ant_prima, v_full_ant_polizas, v_full_ant_total
FROM sicas_documents d
WHERE d.fecha_captura::date BETWEEN v_anio_ant_desde AND v_anio_ant_hasta
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id);

-- CALCULATE GOALS
v_meta_prima := ROUND(v_full_ant_prima * 1.20, 2);
v_meta_polizas := CEIL(v_full_ant_polizas * 1.20);
v_meta_mensual_prima := ROUND(v_meta_prima / 12.0, 2);
v_meta_mensual_polizas := CEIL(v_meta_polizas / 12.0);

RETURN jsonb_build_object(
'periodo_actual', jsonb_build_object(
'prima_neta', ROUND(v_cur_prima, 2),
'prima_total', ROUND(v_cur_prima_total, 2),
'polizas', v_cur_polizas,
'fianzas', v_cur_fianzas,
'total_docs', v_cur_total,
'clientes', v_cur_clientes,
'fecha_desde', v_desde::text,
'fecha_hasta', v_hasta::text
),
'periodo_anterior', jsonb_build_object(
'prima_neta', ROUND(v_ant_prima, 2),
'prima_total', ROUND(v_ant_prima_total, 2),
'polizas', v_ant_polizas,
'fianzas', v_ant_fianzas,
'total_docs', v_ant_total,
'clientes', v_ant_clientes,
'fecha_desde', v_desde_ant::text,
'fecha_hasta', v_hasta_ant::text
),
'ytd_actual', jsonb_build_object(
'prima_neta', ROUND(v_ytd_prima, 2),
'polizas', v_ytd_polizas,
'total_docs', v_ytd_total,
'fecha_desde', v_ytd_desde::text,
'fecha_hasta', v_ytd_hasta::text
),
'ytd_anterior', jsonb_build_object(
'prima_neta', ROUND(v_ytd_ant_prima, 2),
'polizas', v_ytd_ant_polizas,
'total_docs', v_ytd_ant_total,
'fecha_desde', v_ytd_ant_desde::text,
'fecha_hasta', v_ytd_ant_hasta::text
),
'anual_anterior_completo', jsonb_build_object(
'prima_neta', ROUND(v_full_ant_prima, 2),
'polizas', v_full_ant_polizas,
'total_docs', v_full_ant_total,
'fecha_desde', v_anio_ant_desde::text,
'fecha_hasta', v_anio_ant_hasta::text
),
'meta_anual', jsonb_build_object(
'prima_neta', v_meta_prima,
'polizas', v_meta_polizas::int,
'total_docs', CEIL(v_full_ant_total * 1.20)::int
),
'meta_mensual', jsonb_build_object(
'prima_neta', v_meta_mensual_prima,
'polizas', v_meta_mensual_polizas::int
),
'crecimiento', jsonb_build_object(
'prima_vs_anterior', CASE
WHEN v_ant_prima > 0 THEN ROUND((v_cur_prima - v_ant_prima) * 100.0 / v_ant_prima, 2)
WHEN v_cur_prima > 0 THEN 100
ELSE 0
END,
'polizas_vs_anterior', CASE
WHEN v_ant_polizas > 0 THEN ROUND((v_cur_polizas - v_ant_polizas) * 100.0 / v_ant_polizas, 2)
WHEN v_cur_polizas > 0 THEN 100
ELSE 0
END,
'prima_delta', ROUND(v_cur_prima - v_ant_prima, 2),
'polizas_delta', v_cur_polizas - v_ant_polizas,
'avance_meta_prima_pct', CASE
WHEN v_meta_mensual_prima > 0 THEN ROUND(v_cur_prima * 100.0 / v_meta_mensual_prima, 2)
WHEN v_cur_prima > 0 THEN 100
ELSE 0
END,
'avance_meta_polizas_pct', CASE
WHEN v_meta_mensual_polizas > 0 THEN ROUND(v_cur_polizas * 100.0 / v_meta_mensual_polizas, 2)
WHEN v_cur_polizas > 0 THEN 100
ELSE 0
END,
'falta_prima', CASE
WHEN v_meta_mensual_prima > 0 THEN GREATEST(ROUND(v_meta_mensual_prima - v_cur_prima, 2), 0)
ELSE 0
END,
'falta_polizas', CASE
WHEN v_meta_mensual_polizas > 0 THEN GREATEST(v_meta_mensual_polizas - v_cur_polizas, 0)
ELSE 0
END,
'ytd_prima_vs_anterior', CASE
WHEN v_ytd_ant_prima > 0 THEN ROUND((v_ytd_prima - v_ytd_ant_prima) * 100.0 / v_ytd_ant_prima, 2)
WHEN v_ytd_prima > 0 THEN 100
ELSE 0
END,
'ytd_polizas_vs_anterior', CASE
WHEN v_ytd_ant_polizas > 0 THEN ROUND((v_ytd_polizas - v_ytd_ant_polizas) * 100.0 / v_ytd_ant_polizas, 2)
WHEN v_ytd_polizas > 0 THEN 100
ELSE 0
END,
'avance_meta_anual_prima_pct', CASE
WHEN v_meta_prima > 0 THEN ROUND(v_ytd_prima * 100.0 / v_meta_prima, 2)
WHEN v_ytd_prima > 0 THEN 100
ELSE 0
END,
'avance_meta_anual_polizas_pct', CASE
WHEN v_meta_polizas > 0 THEN ROUND(v_ytd_polizas * 100.0 / v_meta_polizas, 2)
WHEN v_ytd_polizas > 0 THEN 100
ELSE 0
END
),
'has_previous_year_data', (v_full_ant_prima > 0),
'scope', v_scope,
'dia_del_mes', v_dia_del_mes,
'mes_actual', v_mes_actual
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_sicas_catalog_stats()
 RETURNS TABLE(catalog_type_id integer, catalog_name text, total_records bigint, mapped_records bigint, last_sync timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
RETURN QUERY
SELECT 
ct.id as catalog_type_id,
ct.name as catalog_name,
COUNT(sc.id) as total_records,
COUNT(sc.id) FILTER (WHERE sc.is_mapped = true) as mapped_records,
MAX(sc.last_sync_at) as last_sync
FROM public.sicas_catalog_types ct
LEFT JOIN public.sicas_catalogos sc ON sc.catalog_type_id = ct.id
GROUP BY ct.id, ct.name
ORDER BY ct.id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_sicas_config(p_key text, p_default text DEFAULT ''::text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
SELECT COALESCE(
(SELECT config_value FROM sicas_rate_config WHERE config_key = p_key),
p_default
);
$function$
;

CREATE OR REPLACE FUNCTION public.get_sicas_configuration_status()
 RETURNS TABLE(total_catalog_types bigint, mappable_catalogs bigint, synced_catalogs bigint, total_catalog_records numeric, last_global_sync timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    COUNT(*) as total_catalog_types,
    COUNT(*) FILTER (WHERE is_mappable = true) as mappable_catalogs,
    COUNT(DISTINCT sc.catalog_type_id) as synced_catalogs,
    COALESCE(SUM(record_count), 0) as total_catalog_records,
    MAX(last_sync) as last_global_sync
  FROM sicas_catalog_types ct
  LEFT JOIN (
    SELECT
      catalog_type_id,
      COUNT(*) as record_count,
      MAX(last_sync_at) as last_sync
    FROM sicas_catalogos
    GROUP BY catalog_type_id
  ) sc ON sc.catalog_type_id = ct.id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_sicas_coverage_stats()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
result jsonb;
BEGIN
SELECT jsonb_build_object(
'total_docs',           COUNT(*),
'docs_with_user',       COUNT(usuario_id),
'docs_without_user',    COUNT(*) - COUNT(usuario_id),
'coverage_pct',         CASE WHEN COUNT(*) > 0 THEN ROUND((COUNT(usuario_id)::numeric / COUNT(*)) * 100, 1) ELSE 0 END,
'total_vigentes',       COUNT(*) FILTER (WHERE is_vigente = true),
'vigentes_with_user',   COUNT(*) FILTER (WHERE is_vigente = true AND usuario_id IS NOT NULL),
'vigentes_without_user', COUNT(*) FILTER (WHERE is_vigente = true AND usuario_id IS NULL),
'prima_total',          COALESCE(SUM(prima_neta), 0),
'prima_asignada',       COALESCE(SUM(prima_neta) FILTER (WHERE usuario_id IS NOT NULL), 0),
'prima_sin_asignar',    COALESCE(SUM(prima_neta) FILTER (WHERE usuario_id IS NULL), 0),
'prima_coverage_pct',   CASE WHEN SUM(prima_neta) > 0 
THEN ROUND((SUM(prima_neta) FILTER (WHERE usuario_id IS NOT NULL) / SUM(prima_neta)) * 100, 1) 
ELSE 0 END,
'unique_vendors',       COUNT(DISTINCT vend_id),
'last_sync',            MAX(synced_at)
) INTO result
FROM sicas_documents;

-- Add vendor mapping stats
SELECT result || jsonb_build_object(
'total_vendor_mappings',   COUNT(*),
'active_vendor_mappings',  COUNT(*) FILTER (WHERE status = 'active' AND movi_user_id IS NOT NULL),
'pending_vendor_mappings', COUNT(*) FILTER (WHERE status = 'pending_review' OR movi_user_id IS NULL)
) INTO result
FROM sicas_vendor_user_mappings;

RETURN result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_sicas_dashboard_charts(p_user_id uuid, p_scope text DEFAULT NULL::text, p_oficina_id uuid DEFAULT NULL::uuid, p_meses integer DEFAULT 24, p_vendedor_id text DEFAULT NULL::text, p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
v_rol text;
v_oficina uuid;
v_scope text;
v_vend_id text;
v_desde date;
v_dim_desde date;
v_dim_hasta date;
v_prima_por_mes jsonb;
v_por_aseguradora jsonb;
v_por_ramo jsonb;
v_por_subramo jsonb;
v_por_cliente jsonb;
v_por_oficina jsonb;
v_por_vendedor jsonb;
v_renovaciones jsonb;
BEGIN
SELECT rol, oficina_id INTO v_rol, v_oficina FROM usuarios WHERE id = p_user_id;
IF v_rol IS NULL THEN RETURN '{}'::jsonb; END IF;

IF v_rol = 'Administrador' THEN
v_scope := COALESCE(p_scope, 'admin');
ELSIF v_rol IN ('Gerente', 'Empleado', 'Ejecutivo') THEN
v_scope := COALESCE(p_scope, 'office');
IF v_scope = 'admin' THEN v_scope := 'office'; END IF;
ELSE
v_scope := 'self';
END IF;

IF p_oficina_id IS NOT NULL AND v_scope = 'admin' THEN
v_oficina := p_oficina_id;
v_scope := 'office';
ELSIF v_scope = 'office' THEN
v_oficina := COALESCE(p_oficina_id, v_oficina);
END IF;

IF v_scope = 'self' THEN
v_vend_id := get_sicas_user_vend_id(p_user_id);
END IF;

v_desde := CURRENT_DATE - (p_meses || ' months')::interval;
v_dim_desde := COALESCE(p_fecha_desde, date_trunc('year', CURRENT_DATE)::date);
v_dim_hasta := COALESCE(p_fecha_hasta, CURRENT_DATE);

-- Prima por mes
SELECT COALESCE(jsonb_agg(row_to_json(t) ORDER BY t.mes), '[]'::jsonb) INTO v_prima_por_mes
FROM (
SELECT
to_char(d.fecha_captura, 'YYYY-MM') AS mes,
EXTRACT(YEAR FROM d.fecha_captura)::int AS anio,
EXTRACT(MONTH FROM d.fecha_captura)::int AS mes_num,
COUNT(*) AS emisiones,
COALESCE(SUM(d.prima_neta), 0) AS prima_neta,
COALESCE(SUM(GREATEST(COALESCE(d.prima_total, 0), COALESCE(d.importe, 0))), 0) AS prima_total,
COUNT(*) FILTER (WHERE NOT COALESCE(d.is_fianza, false)) AS polizas,
COUNT(*) FILTER (WHERE COALESCE(d.is_fianza, false)) AS fianzas
FROM sicas_documents d
WHERE d.fecha_captura::date >= LEAST(v_desde, COALESCE(p_fecha_desde, v_desde))
AND (p_fecha_hasta IS NULL OR d.fecha_captura::date <= p_fecha_hasta)
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id)
GROUP BY to_char(d.fecha_captura, 'YYYY-MM'), EXTRACT(YEAR FROM d.fecha_captura), EXTRACT(MONTH FROM d.fecha_captura)
ORDER BY mes
) t;

-- Por aseguradora
SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) INTO v_por_aseguradora
FROM (
SELECT d.compania AS nombre, COUNT(*) AS cantidad, COALESCE(SUM(d.prima_neta), 0) AS prima
FROM sicas_documents d
WHERE d.compania IS NOT NULL AND d.fecha_captura::date BETWEEN v_dim_desde AND v_dim_hasta
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id)
GROUP BY d.compania ORDER BY prima DESC LIMIT 15
) t;

-- Por ramo
SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) INTO v_por_ramo
FROM (
SELECT d.ramo AS nombre, COUNT(*) AS cantidad, COALESCE(SUM(d.prima_neta), 0) AS prima
FROM sicas_documents d
WHERE d.ramo IS NOT NULL AND d.fecha_captura::date BETWEEN v_dim_desde AND v_dim_hasta
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id)
GROUP BY d.ramo ORDER BY prima DESC LIMIT 15
) t;

-- Por subramo
SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) INTO v_por_subramo
FROM (
SELECT d.subramo AS nombre, COUNT(*) AS cantidad, COALESCE(SUM(d.prima_neta), 0) AS prima
FROM sicas_documents d
WHERE d.subramo IS NOT NULL AND d.fecha_captura::date BETWEEN v_dim_desde AND v_dim_hasta
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id)
GROUP BY d.subramo ORDER BY prima DESC LIMIT 15
) t;

-- Por cliente
SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) INTO v_por_cliente
FROM (
SELECT d.cliente AS nombre, COUNT(*) AS cantidad, COALESCE(SUM(d.prima_neta), 0) AS prima
FROM sicas_documents d
WHERE d.cliente IS NOT NULL AND d.fecha_captura::date BETWEEN v_dim_desde AND v_dim_hasta
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id)
GROUP BY d.cliente ORDER BY prima DESC LIMIT 15
) t;

-- Por oficina
SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) INTO v_por_oficina
FROM (
SELECT COALESCE(o.nombre, d.oficina_nombre, d.desp_nombre, 'Sin oficina') AS nombre,
d.oficina_id,
COUNT(*) AS cantidad,
COALESCE(SUM(d.prima_neta), 0) AS prima
FROM sicas_documents d
LEFT JOIN oficinas o ON o.id = d.oficina_id
WHERE d.fecha_captura::date BETWEEN v_dim_desde AND v_dim_hasta
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id)
GROUP BY d.oficina_id, o.nombre, d.oficina_nombre, d.desp_nombre
ORDER BY prima DESC LIMIT 15
) t;

-- Por vendedor
SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) INTO v_por_vendedor
FROM (
SELECT d.vend_nombre AS nombre,
d.vend_id,
COUNT(*) AS cantidad,
COALESCE(SUM(d.prima_neta), 0) AS prima
FROM sicas_documents d
WHERE d.vend_id IS NOT NULL AND d.fecha_captura::date BETWEEN v_dim_desde AND v_dim_hasta
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id)
GROUP BY d.vend_nombre, d.vend_id
ORDER BY prima DESC LIMIT 15
) t;

-- Renovaciones horizonte
SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) INTO v_renovaciones
FROM (
SELECT
CASE
WHEN d.renewal_days_remaining BETWEEN 0 AND 7 THEN '0-7 dias'
WHEN d.renewal_days_remaining BETWEEN 8 AND 15 THEN '8-15 dias'
WHEN d.renewal_days_remaining BETWEEN 16 AND 30 THEN '16-30 dias'
WHEN d.renewal_days_remaining BETWEEN 31 AND 60 THEN '31-60 dias'
WHEN d.renewal_days_remaining BETWEEN 61 AND 90 THEN '61-90 dias'
END AS periodo,
COUNT(*) AS cantidad,
COALESCE(SUM(d.prima_neta), 0) AS prima
FROM sicas_documents d
WHERE d.is_vigente = true AND d.renewal_days_remaining BETWEEN 0 AND 90
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id)
GROUP BY 1
ORDER BY MIN(d.renewal_days_remaining)
) t;

RETURN jsonb_build_object(
'prima_por_mes', v_prima_por_mes,
'por_aseguradora', v_por_aseguradora,
'por_ramo', v_por_ramo,
'por_subramo', v_por_subramo,
'por_cliente', v_por_cliente,
'por_oficina', v_por_oficina,
'por_vendedor', v_por_vendedor,
'renovaciones_horizonte', v_renovaciones
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_sicas_dashboard_kpis(p_user_id uuid, p_scope text DEFAULT NULL::text, p_oficina_id uuid DEFAULT NULL::uuid, p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date, p_vendedor_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
v_rol text;
v_oficina uuid;
v_scope text;
v_vend_id text;
v_periodo_inicio date;
v_periodo_fin date;
v_custom_range boolean;
v_mes_actual_inicio date;
v_mes_actual_fin date;
v_mes_anterior_inicio date;
v_mes_anterior_fin date;
v_mismo_mes_anio_ant_inicio date;
v_mismo_mes_anio_ant_fin date;
v_anio_actual_inicio date;
v_mismo_periodo_ant_inicio date;
v_mismo_periodo_ant_fin date;

v_polizas_emitidas int;
v_fianzas_emitidas int;
v_total_emitidos int;
v_prima_neta_emitida numeric;
v_prima_total_emitida numeric;
v_clientes_emision int;
v_ticket_promedio numeric;
v_docs_vigentes int;
v_prima_vigente numeric;
v_clientes_vigentes int;
v_renov_pendientes int;
v_prima_por_renovar numeric;
v_renov_7 int;
v_renov_15 int;
v_renov_30 int;
v_cancelaciones int;
v_prima_mes_anterior numeric;
v_prima_mismo_mes_ant numeric;
v_acumulado_ytd numeric;
v_acumulado_ytd_ant numeric;
v_top_cliente jsonb;
v_top_aseguradora jsonb;
v_top_ramo jsonb;
v_top_oficina jsonb;
v_top_vendedor jsonb;
v_conc_top5_clientes numeric;
v_conc_top3_aseguradoras numeric;
v_last_sync text;
BEGIN
SELECT rol, oficina_id INTO v_rol, v_oficina FROM usuarios WHERE id = p_user_id;
IF v_rol IS NULL THEN
RETURN jsonb_build_object('error', 'Usuario no encontrado');
END IF;

IF v_rol = 'Administrador' THEN
v_scope := COALESCE(p_scope, 'admin');
ELSIF v_rol IN ('Gerente', 'Empleado', 'Ejecutivo') THEN
v_scope := COALESCE(p_scope, 'office');
IF v_scope = 'admin' THEN v_scope := 'office'; END IF;
ELSE
v_scope := 'self';
END IF;

IF p_oficina_id IS NOT NULL AND v_scope = 'admin' THEN
v_oficina := p_oficina_id;
v_scope := 'office';
ELSIF v_scope = 'office' THEN
v_oficina := COALESCE(p_oficina_id, v_oficina);
END IF;

-- Resolve vendor ID for self scope
IF v_scope = 'self' THEN
v_vend_id := get_sicas_user_vend_id(p_user_id);
END IF;

v_custom_range := (p_fecha_desde IS NOT NULL AND p_fecha_hasta IS NOT NULL);

v_mes_actual_inicio := date_trunc('month', CURRENT_DATE)::date;
v_mes_actual_fin := (date_trunc('month', CURRENT_DATE) + interval '1 month' - interval '1 day')::date;

IF v_custom_range THEN
v_periodo_inicio := p_fecha_desde;
v_periodo_fin := p_fecha_hasta;
ELSE
v_periodo_inicio := v_mes_actual_inicio;
v_periodo_fin := v_mes_actual_fin;
END IF;

v_mes_anterior_inicio := (date_trunc('month', CURRENT_DATE) - interval '1 month')::date;
v_mes_anterior_fin := (date_trunc('month', CURRENT_DATE) - interval '1 day')::date;
v_mismo_mes_anio_ant_inicio := (date_trunc('month', CURRENT_DATE) - interval '1 year')::date;
v_mismo_mes_anio_ant_fin := (date_trunc('month', CURRENT_DATE) - interval '1 year' + interval '1 month' - interval '1 day')::date;
v_anio_actual_inicio := date_trunc('year', CURRENT_DATE)::date;
v_mismo_periodo_ant_inicio := (date_trunc('year', CURRENT_DATE) - interval '1 year')::date;
v_mismo_periodo_ant_fin := (CURRENT_DATE - interval '1 year');

-- Emissions in the selected period
SELECT
COUNT(*) FILTER (WHERE NOT COALESCE(d.is_fianza, false)),
COUNT(*) FILTER (WHERE COALESCE(d.is_fianza, false)),
COUNT(*),
COALESCE(SUM(d.prima_neta), 0),
COALESCE(SUM(GREATEST(COALESCE(d.prima_total, 0), COALESCE(d.importe, 0))), 0),
COUNT(DISTINCT d.cliente)
INTO v_polizas_emitidas, v_fianzas_emitidas, v_total_emitidos, v_prima_neta_emitida, v_prima_total_emitida, v_clientes_emision
FROM sicas_documents d
WHERE d.fecha_captura::date BETWEEN v_periodo_inicio AND v_periodo_fin
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id);

v_ticket_promedio := CASE WHEN v_total_emitidos > 0 THEN v_prima_neta_emitida / v_total_emitidos ELSE 0 END;

-- Vigentes
SELECT COUNT(*), COALESCE(SUM(d.prima_neta), 0), COUNT(DISTINCT d.cliente)
INTO v_docs_vigentes, v_prima_vigente, v_clientes_vigentes
FROM sicas_documents d
WHERE d.is_vigente = true
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id);

-- Renovaciones
SELECT
COUNT(*),
COALESCE(SUM(d.prima_neta), 0),
COUNT(*) FILTER (WHERE d.renewal_days_remaining BETWEEN 0 AND 7),
COUNT(*) FILTER (WHERE d.renewal_days_remaining BETWEEN 0 AND 15),
COUNT(*) FILTER (WHERE d.renewal_days_remaining BETWEEN 0 AND 30)
INTO v_renov_pendientes, v_prima_por_renovar, v_renov_7, v_renov_15, v_renov_30
FROM sicas_documents d
WHERE d.is_vigente = true AND d.renewal_days_remaining BETWEEN 0 AND 90
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id);

-- Cancelaciones
SELECT COUNT(*) INTO v_cancelaciones
FROM sicas_documents d
WHERE d.is_cancelada = true AND d.fecha_captura::date BETWEEN v_periodo_inicio AND v_periodo_fin
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id);

-- Previous month
SELECT COALESCE(SUM(d.prima_neta), 0) INTO v_prima_mes_anterior
FROM sicas_documents d
WHERE d.fecha_captura::date BETWEEN v_mes_anterior_inicio AND v_mes_anterior_fin
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id);

-- Same month last year
SELECT COALESCE(SUM(d.prima_neta), 0) INTO v_prima_mismo_mes_ant
FROM sicas_documents d
WHERE d.fecha_captura::date BETWEEN v_mismo_mes_anio_ant_inicio AND v_mismo_mes_anio_ant_fin
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id);

-- YTD
SELECT COALESCE(SUM(d.prima_neta), 0) INTO v_acumulado_ytd
FROM sicas_documents d
WHERE d.fecha_captura::date BETWEEN v_anio_actual_inicio AND CURRENT_DATE
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id);

SELECT COALESCE(SUM(d.prima_neta), 0) INTO v_acumulado_ytd_ant
FROM sicas_documents d
WHERE d.fecha_captura::date BETWEEN v_mismo_periodo_ant_inicio AND v_mismo_periodo_ant_fin
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id);

-- Top client
SELECT jsonb_build_object('nombre', t.cliente, 'prima', t.p) INTO v_top_cliente
FROM (
SELECT d.cliente, SUM(d.prima_neta) as p
FROM sicas_documents d
WHERE d.cliente IS NOT NULL AND d.fecha_captura::date BETWEEN v_periodo_inicio AND v_periodo_fin
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id)
GROUP BY d.cliente ORDER BY p DESC LIMIT 1
) t;

-- Top aseguradora
SELECT jsonb_build_object('nombre', t.compania, 'prima', t.p) INTO v_top_aseguradora
FROM (
SELECT d.compania, SUM(d.prima_neta) as p
FROM sicas_documents d
WHERE d.compania IS NOT NULL AND d.fecha_captura::date BETWEEN v_periodo_inicio AND v_periodo_fin
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id)
GROUP BY d.compania ORDER BY p DESC LIMIT 1
) t;

-- Top ramo
SELECT jsonb_build_object('nombre', t.ramo, 'prima', t.p) INTO v_top_ramo
FROM (
SELECT d.ramo, SUM(d.prima_neta) as p
FROM sicas_documents d
WHERE d.ramo IS NOT NULL AND d.fecha_captura::date BETWEEN v_periodo_inicio AND v_periodo_fin
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id)
GROUP BY d.ramo ORDER BY p DESC LIMIT 1
) t;

-- Top oficina
SELECT jsonb_build_object('nombre', t.nombre, 'prima', t.p, 'oficina_id', t.oid) INTO v_top_oficina
FROM (
SELECT COALESCE(o.nombre, d.oficina_nombre, d.desp_nombre, 'Sin oficina') as nombre,
d.oficina_id as oid, SUM(d.prima_neta) as p
FROM sicas_documents d
LEFT JOIN oficinas o ON o.id = d.oficina_id
WHERE d.fecha_captura::date BETWEEN v_periodo_inicio AND v_periodo_fin
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id)
GROUP BY d.oficina_id, o.nombre, d.oficina_nombre, d.desp_nombre ORDER BY p DESC LIMIT 1
) t;

-- Top vendedor
SELECT jsonb_build_object('nombre', t.vend_nombre, 'prima', t.p, 'vend_id', t.vid) INTO v_top_vendedor
FROM (
SELECT d.vend_nombre, d.vend_id as vid, SUM(d.prima_neta) as p
FROM sicas_documents d
WHERE d.vend_id IS NOT NULL AND d.fecha_captura::date BETWEEN v_periodo_inicio AND v_periodo_fin
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id)
GROUP BY d.vend_nombre, d.vend_id ORDER BY p DESC LIMIT 1
) t;

-- Concentration top 5 clients
SELECT CASE WHEN v_prima_neta_emitida > 0 THEN
COALESCE((
SELECT SUM(sub.p) * 100.0 / v_prima_neta_emitida
FROM (
SELECT SUM(d.prima_neta) as p
FROM sicas_documents d
WHERE d.cliente IS NOT NULL AND d.fecha_captura::date BETWEEN v_periodo_inicio AND v_periodo_fin
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id)
GROUP BY d.cliente ORDER BY p DESC LIMIT 5
) sub
), 0)
ELSE 0 END
INTO v_conc_top5_clientes;

-- Concentration top 3 aseguradoras
SELECT CASE WHEN v_prima_neta_emitida > 0 THEN
COALESCE((
SELECT SUM(sub.p) * 100.0 / v_prima_neta_emitida
FROM (
SELECT SUM(d.prima_neta) as p
FROM sicas_documents d
WHERE d.compania IS NOT NULL AND d.fecha_captura::date BETWEEN v_periodo_inicio AND v_periodo_fin
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id)
GROUP BY d.compania ORDER BY p DESC LIMIT 3
) sub
), 0)
ELSE 0 END
INTO v_conc_top3_aseguradoras;

-- Last sync
SELECT MAX(d.synced_at)::text INTO v_last_sync FROM sicas_documents d;

RETURN jsonb_build_object(
'polizas_emitidas', v_polizas_emitidas,
'fianzas_emitidas', v_fianzas_emitidas,
'total_emitidos', v_total_emitidos,
'prima_neta_emitida', ROUND(v_prima_neta_emitida, 2),
'prima_total_emitida', ROUND(v_prima_total_emitida, 2),
'clientes_emision', v_clientes_emision,
'ticket_promedio', ROUND(v_ticket_promedio, 2),
'documentos_vigentes', v_docs_vigentes,
'prima_vigente', ROUND(v_prima_vigente, 2),
'clientes_vigentes', v_clientes_vigentes,
'renovaciones_pendientes', v_renov_pendientes,
'prima_por_renovar', ROUND(v_prima_por_renovar, 2),
'renovaciones_7dias', v_renov_7,
'renovaciones_15dias', v_renov_15,
'renovaciones_30dias', v_renov_30,
'cancelaciones_periodo', v_cancelaciones,
'prima_mes_anterior', ROUND(v_prima_mes_anterior, 2),
'prima_mismo_mes_ant', ROUND(v_prima_mismo_mes_ant, 2),
'variacion_mes_anterior', CASE
WHEN v_prima_mes_anterior > 0 THEN ROUND((v_prima_neta_emitida - v_prima_mes_anterior) * 100.0 / v_prima_mes_anterior, 2)
WHEN v_prima_neta_emitida > 0 THEN 100
ELSE 0
END,
'variacion_interanual', CASE
WHEN v_prima_mismo_mes_ant > 0 THEN ROUND((v_prima_neta_emitida - v_prima_mismo_mes_ant) * 100.0 / v_prima_mismo_mes_ant, 2)
WHEN v_prima_neta_emitida > 0 THEN 100
ELSE 0
END,
'acumulado_ytd', ROUND(v_acumulado_ytd, 2),
'acumulado_ytd_anterior', ROUND(v_acumulado_ytd_ant, 2),
'crecimiento_ytd', CASE
WHEN v_acumulado_ytd_ant > 0 THEN ROUND((v_acumulado_ytd - v_acumulado_ytd_ant) * 100.0 / v_acumulado_ytd_ant, 2)
WHEN v_acumulado_ytd > 0 THEN 100
ELSE 0
END,
'top_cliente', COALESCE(v_top_cliente, '{"nombre":null,"prima":0}'::jsonb),
'top_aseguradora', COALESCE(v_top_aseguradora, '{"nombre":null,"prima":0}'::jsonb),
'top_ramo', COALESCE(v_top_ramo, '{"nombre":null,"prima":0}'::jsonb),
'top_oficina', COALESCE(v_top_oficina, '{"nombre":null,"prima":0}'::jsonb),
'top_vendedor', COALESCE(v_top_vendedor, '{"nombre":null,"prima":0}'::jsonb),
'concentracion_top5_clientes', ROUND(v_conc_top5_clientes, 2),
'concentracion_top3_aseguradoras', ROUND(v_conc_top3_aseguradoras, 2),
'scope', v_scope,
'last_sync', v_last_sync
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_sicas_dashboard_top(p_user_id uuid, p_dimension text DEFAULT 'cliente'::text, p_limit integer DEFAULT 10, p_scope text DEFAULT NULL::text, p_oficina_id uuid DEFAULT NULL::uuid, p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date, p_vendedor_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
v_rol text;
v_oficina uuid;
v_scope text;
v_vend_id text;
v_desde timestamp;
v_hasta timestamp;
v_result jsonb;
BEGIN
SELECT rol, oficina_id INTO v_rol, v_oficina FROM usuarios WHERE id = p_user_id;
IF v_rol IS NULL THEN RETURN '[]'::jsonb; END IF;

IF v_rol = 'Administrador' THEN
v_scope := COALESCE(p_scope, 'admin');
ELSIF v_rol IN ('Gerente', 'Empleado', 'Ejecutivo') THEN
v_scope := COALESCE(p_scope, 'office');
IF v_scope = 'admin' THEN v_scope := 'office'; END IF;
ELSE
v_scope := 'self';
END IF;

IF p_oficina_id IS NOT NULL AND v_scope = 'admin' THEN
v_oficina := p_oficina_id;
v_scope := 'office';
END IF;

IF v_scope = 'self' THEN
v_vend_id := get_sicas_user_vend_id(p_user_id);
END IF;

v_desde := COALESCE(p_fecha_desde, date_trunc('year', CURRENT_DATE)::date)::timestamp;
v_hasta := (COALESCE(p_fecha_hasta, CURRENT_DATE) + interval '1 day')::timestamp;

IF p_dimension = 'cliente' THEN
SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) INTO v_result
FROM (
SELECT
d.cliente AS nombre,
COUNT(*) AS documentos,
COALESCE(SUM(d.prima_neta), 0) AS prima_neta,
COALESCE(SUM(GREATEST(COALESCE(d.prima_total,0), COALESCE(d.importe,0))), 0) AS prima_total,
COUNT(DISTINCT d.compania) AS aseguradoras,
COUNT(DISTINCT d.ramo) AS ramos,
MIN(d.vigencia_hasta)::text AS proxima_renovacion
FROM sicas_documents d
WHERE d.cliente IS NOT NULL
AND d.fecha_captura >= v_desde AND d.fecha_captura < v_hasta
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id)
GROUP BY d.cliente
ORDER BY prima_neta DESC
LIMIT p_limit
) t;

ELSIF p_dimension = 'aseguradora' THEN
SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) INTO v_result
FROM (
SELECT
d.compania AS nombre,
COUNT(*) AS documentos,
COALESCE(SUM(d.prima_neta), 0) AS prima_neta,
COALESCE(SUM(GREATEST(COALESCE(d.prima_total,0), COALESCE(d.importe,0))), 0) AS prima_total,
COUNT(DISTINCT d.cliente) AS clientes,
COUNT(DISTINCT d.ramo) AS ramos
FROM sicas_documents d
WHERE d.compania IS NOT NULL
AND d.fecha_captura >= v_desde AND d.fecha_captura < v_hasta
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id)
GROUP BY d.compania
ORDER BY prima_neta DESC
LIMIT p_limit
) t;

ELSIF p_dimension = 'ramo' THEN
SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) INTO v_result
FROM (
SELECT
d.ramo AS nombre,
COUNT(*) AS documentos,
COALESCE(SUM(d.prima_neta), 0) AS prima_neta,
COALESCE(SUM(GREATEST(COALESCE(d.prima_total,0), COALESCE(d.importe,0))), 0) AS prima_total,
COUNT(DISTINCT d.cliente) AS clientes,
COUNT(DISTINCT d.compania) AS aseguradoras
FROM sicas_documents d
WHERE d.ramo IS NOT NULL
AND d.fecha_captura >= v_desde AND d.fecha_captura < v_hasta
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id)
GROUP BY d.ramo
ORDER BY prima_neta DESC
LIMIT p_limit
) t;

ELSIF p_dimension = 'subramo' THEN
SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) INTO v_result
FROM (
SELECT
d.subramo AS nombre,
d.ramo,
COUNT(*) AS documentos,
COALESCE(SUM(d.prima_neta), 0) AS prima_neta,
COALESCE(SUM(GREATEST(COALESCE(d.prima_total,0), COALESCE(d.importe,0))), 0) AS prima_total,
COUNT(DISTINCT d.cliente) AS clientes
FROM sicas_documents d
WHERE d.subramo IS NOT NULL
AND d.fecha_captura >= v_desde AND d.fecha_captura < v_hasta
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id)
GROUP BY d.subramo, d.ramo
ORDER BY prima_neta DESC
LIMIT p_limit
) t;

ELSIF p_dimension = 'oficina' THEN
SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) INTO v_result
FROM (
SELECT
COALESCE(o.nombre, d.oficina_nombre, d.desp_nombre, 'Sin oficina') AS nombre,
d.oficina_id,
COUNT(*) AS documentos,
COALESCE(SUM(d.prima_neta), 0) AS prima_neta,
COALESCE(SUM(GREATEST(COALESCE(d.prima_total,0), COALESCE(d.importe,0))), 0) AS prima_total,
COUNT(DISTINCT d.cliente) AS clientes,
COUNT(DISTINCT d.vend_id) AS vendedores,
COUNT(DISTINCT d.compania) AS aseguradoras
FROM sicas_documents d
LEFT JOIN oficinas o ON o.id = d.oficina_id
WHERE d.fecha_captura >= v_desde AND d.fecha_captura < v_hasta
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id)
GROUP BY d.oficina_id, o.nombre, d.oficina_nombre, d.desp_nombre
ORDER BY prima_neta DESC
LIMIT p_limit
) t;

ELSIF p_dimension = 'vendedor' THEN
SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) INTO v_result
FROM (
SELECT
COALESCE(d.vend_nombre, 'Sin vendedor') AS nombre,
d.vend_id,
COUNT(*) AS documentos,
COALESCE(SUM(d.prima_neta), 0) AS prima_neta,
COALESCE(SUM(GREATEST(COALESCE(d.prima_total,0), COALESCE(d.importe,0))), 0) AS prima_total,
COUNT(DISTINCT d.cliente) AS clientes,
COUNT(DISTINCT d.compania) AS aseguradoras,
COUNT(DISTINCT d.ramo) AS ramos
FROM sicas_documents d
WHERE d.vend_id IS NOT NULL
AND d.fecha_captura >= v_desde AND d.fecha_captura < v_hasta
AND (v_scope = 'admin' OR (v_scope = 'office' AND d.oficina_id = v_oficina) OR (v_scope = 'self' AND d.vend_id = v_vend_id))
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id)
GROUP BY d.vend_nombre, d.vend_id
ORDER BY prima_neta DESC
LIMIT p_limit
) t;

ELSE
v_result := '[]'::jsonb;
END IF;

RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_sicas_documents(p_user_id uuid, p_scope text DEFAULT 'all'::text, p_oficina_id uuid DEFAULT NULL::uuid, p_vendedor_id text DEFAULT NULL::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 50, p_search text DEFAULT NULL::text, p_cliente text DEFAULT NULL::text, p_aseguradora text DEFAULT NULL::text, p_ramo text DEFAULT NULL::text, p_subramo text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_tipo text DEFAULT NULL::text, p_moneda text DEFAULT NULL::text, p_fecha_desde text DEFAULT NULL::text, p_fecha_hasta text DEFAULT NULL::text, p_solo_renovaciones boolean DEFAULT false, p_dias_renovacion integer DEFAULT 90, p_order_by text DEFAULT 'fecha_captura'::text, p_order_asc boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
v_rol text;
v_oficina_id uuid;
v_vend_id text;
v_scope text;
v_result jsonb;
v_data jsonb;
v_count bigint;
v_offset int;
v_safe_search text;
BEGIN
-- Get user role and office
SELECT rol, oficina_id INTO v_rol, v_oficina_id
FROM usuarios WHERE id = p_user_id;

IF v_rol IS NULL THEN
RETURN jsonb_build_object('data', '[]'::jsonb, 'count', 0);
END IF;

-- Determine scope (same logic as KPI functions)
IF v_rol IN ('Administrador', 'Ejecutivo') THEN
v_scope := 'admin';
ELSIF v_rol IN ('Gerente', 'Empleado') THEN
v_scope := 'office';
ELSE
v_scope := 'self';
END IF;

-- For self scope, resolve the SICAS vendor ID
IF v_scope = 'self' THEN
v_vend_id := get_sicas_user_vend_id(p_user_id);
END IF;

v_offset := (p_page - 1) * p_page_size;
v_safe_search := regexp_replace(COALESCE(p_search, ''), '[%_]', '', 'g');

-- Build and execute dynamic query
WITH filtered_docs AS (
SELECT
d.id, d.id_docto, d.vend_id, d.vend_nombre, d.desp_id, d.desp_nombre,
d.usuario_id, d.oficina_id, d.oficina_nombre,
d.ramo, d.subramo, d.compania, d.aseguradora_nombre,
d.poliza, d.cliente, d.fecha_captura, d.fecha_emision,
d.vigencia_desde, d.vigencia_hasta,
d.importe, d.prima_neta, d.prima_total, d.derechos, d.impuestos, d.recargos,
d.moneda, d.tipo_documento, d.subtipo_documento, d.agente_nombre,
d.status_codigo, d.status_texto, d.status_cobro,
d.is_poliza, d.is_fianza, d.is_vigente, d.is_cancelada,
d.is_renewable, d.renewal_days_remaining,
d.source_keycode, d.synced_at
FROM sicas_documents d
WHERE
-- Scope/permission filtering
CASE
WHEN v_scope = 'admin' THEN true
WHEN v_scope = 'office' THEN d.oficina_id = v_oficina_id
ELSE d.vend_id = v_vend_id
END
-- Optional office filter (for admin drilling into specific office)
AND (p_oficina_id IS NULL OR d.oficina_id = p_oficina_id)
-- Optional vendor filter
AND (p_vendedor_id IS NULL OR d.vend_id = p_vendedor_id)
-- Search
AND (v_safe_search = '' OR (
d.cliente ILIKE '%' || v_safe_search || '%'
OR d.poliza ILIKE '%' || v_safe_search || '%'
OR d.compania ILIKE '%' || v_safe_search || '%'
OR d.ramo ILIKE '%' || v_safe_search || '%'
OR d.vend_nombre ILIKE '%' || v_safe_search || '%'
))
-- Specific filters
AND (p_cliente IS NULL OR d.cliente ILIKE '%' || regexp_replace(p_cliente, '[%_]', '', 'g') || '%')
AND (p_aseguradora IS NULL OR d.compania = p_aseguradora)
AND (p_ramo IS NULL OR d.ramo = p_ramo)
AND (p_subramo IS NULL OR d.subramo = p_subramo)
AND (p_moneda IS NULL OR d.moneda = p_moneda)
-- Status filter
AND (
p_status IS NULL
OR (p_status = 'vigente' AND d.is_vigente = true)
OR (p_status = 'cancelada' AND d.is_cancelada = true)
OR (p_status NOT IN ('vigente', 'cancelada') AND d.status_texto = p_status)
)
-- Type filter
AND (
p_tipo IS NULL
OR (p_tipo = 'polizas' AND d.is_poliza = true)
OR (p_tipo = 'fianzas' AND d.is_fianza = true)
)
-- Date range
AND (p_fecha_desde IS NULL OR d.fecha_captura >= p_fecha_desde::timestamptz)
AND (p_fecha_hasta IS NULL OR d.fecha_captura <= (p_fecha_hasta || 'T23:59:59')::timestamptz)
-- Renewals
AND (
NOT p_solo_renovaciones
OR (d.is_vigente = true AND d.renewal_days_remaining >= 0 AND d.renewal_days_remaining <= p_dias_renovacion)
)
)
SELECT
jsonb_agg(row_to_json(paged.*) ORDER BY
CASE WHEN p_order_by = 'fecha_captura' AND NOT p_order_asc THEN paged.fecha_captura END DESC NULLS LAST,
CASE WHEN p_order_by = 'fecha_captura' AND p_order_asc THEN paged.fecha_captura END ASC NULLS LAST,
CASE WHEN p_order_by = 'prima_total' AND NOT p_order_asc THEN paged.prima_total END DESC NULLS LAST,
CASE WHEN p_order_by = 'prima_total' AND p_order_asc THEN paged.prima_total END ASC NULLS LAST,
CASE WHEN p_order_by = 'cliente' AND NOT p_order_asc THEN paged.cliente END DESC NULLS LAST,
CASE WHEN p_order_by = 'cliente' AND p_order_asc THEN paged.cliente END ASC NULLS LAST,
CASE WHEN p_order_by NOT IN ('fecha_captura','prima_total','cliente') AND NOT p_order_asc THEN paged.fecha_captura END DESC NULLS LAST,
CASE WHEN p_order_by NOT IN ('fecha_captura','prima_total','cliente') AND p_order_asc THEN paged.fecha_captura END ASC NULLS LAST
),
(SELECT count(*) FROM filtered_docs)
INTO v_data, v_count
FROM (
SELECT * FROM filtered_docs
ORDER BY
CASE WHEN p_order_by = 'fecha_captura' AND NOT p_order_asc THEN fecha_captura END DESC NULLS LAST,
CASE WHEN p_order_by = 'fecha_captura' AND p_order_asc THEN fecha_captura END ASC NULLS LAST,
CASE WHEN p_order_by = 'prima_total' AND NOT p_order_asc THEN prima_total END DESC NULLS LAST,
CASE WHEN p_order_by = 'prima_total' AND p_order_asc THEN prima_total END ASC NULLS LAST,
CASE WHEN p_order_by = 'cliente' AND NOT p_order_asc THEN cliente END DESC NULLS LAST,
CASE WHEN p_order_by = 'cliente' AND p_order_asc THEN cliente END ASC NULLS LAST,
CASE WHEN p_order_by NOT IN ('fecha_captura','prima_total','cliente') AND NOT p_order_asc THEN fecha_captura END DESC NULLS LAST,
CASE WHEN p_order_by NOT IN ('fecha_captura','prima_total','cliente') AND p_order_asc THEN fecha_captura END ASC NULLS LAST
LIMIT p_page_size OFFSET v_offset
) paged;

RETURN jsonb_build_object(
'data', COALESCE(v_data, '[]'::jsonb),
'count', COALESCE(v_count, 0)
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_sicas_documents_count()
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
user_role text;
user_oficina_id uuid;
user_id_sicas text;
result bigint;
BEGIN
SELECT rol, oficina_id, id_sicas INTO user_role, user_oficina_id, user_id_sicas
FROM usuarios WHERE id = auth.uid();

IF user_role IS NULL THEN
RETURN 0;
END IF;

IF user_role IN ('Administrador', 'Ejecutivo') THEN
SELECT count(*) INTO result FROM sicas_documents;
ELSIF user_role = 'Gerente' AND user_oficina_id IS NOT NULL THEN
SELECT count(*) INTO result FROM sicas_documents WHERE oficina_id = user_oficina_id;
ELSIF user_role = 'Agente' AND user_id_sicas IS NOT NULL THEN
SELECT count(*) INTO result FROM sicas_documents WHERE vend_id = user_id_sicas;
ELSIF user_role = 'Empleado' AND user_oficina_id IS NOT NULL THEN
SELECT count(*) INTO result FROM sicas_documents WHERE oficina_id = user_oficina_id;
ELSE
RETURN 0;
END IF;

RETURN COALESCE(result, 0);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_sicas_entity_aggregates(p_user_id uuid, p_dimension text, p_entity_name text, p_entity_id text DEFAULT NULL::text, p_fecha_desde text DEFAULT NULL::text, p_fecha_hasta text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '15s'
AS $function$
DECLARE
v_rol text;
v_oficina_id uuid;
v_vend_id text;
v_scope text;
v_result jsonb;
BEGIN
SELECT rol, oficina_id INTO v_rol, v_oficina_id
FROM usuarios WHERE id = p_user_id;

IF v_rol IS NULL THEN
RETURN jsonb_build_object('total_docs', 0, 'prima_neta_total', 0, 'prima_vigente', 0, 'unique_count', 0, 'polizas_vigentes', 0, 'polizas_canceladas', 0);
END IF;

IF v_rol IN ('Administrador', 'Ejecutivo') THEN
v_scope := 'admin';
ELSIF v_rol IN ('Gerente', 'Empleado') THEN
v_scope := 'office';
ELSE
v_scope := 'self';
END IF;

IF v_scope = 'self' THEN
v_vend_id := get_sicas_user_vend_id(p_user_id);
END IF;

SELECT jsonb_build_object(
'total_docs', count(*),
'prima_neta_total', coalesce(sum(d.prima_neta), 0),
'prima_vigente', coalesce(sum(d.prima_neta) FILTER (WHERE d.is_vigente = true), 0),
'polizas_vigentes', count(*) FILTER (WHERE d.is_vigente = true),
'polizas_canceladas', count(*) FILTER (WHERE d.is_cancelada = true),
'unique_count', CASE
WHEN p_dimension = 'cliente' THEN (SELECT count(DISTINCT d2.compania) FROM sicas_documents d2
WHERE d2.cliente ILIKE '%' || regexp_replace(p_entity_name, '[%_]', '', 'g') || '%'
AND CASE WHEN v_scope = 'admin' THEN true WHEN v_scope = 'office' THEN d2.oficina_id = v_oficina_id ELSE d2.vend_id = v_vend_id END)
ELSE (SELECT count(DISTINCT d2.cliente) FROM sicas_documents d2
WHERE CASE
WHEN p_dimension = 'aseguradora' THEN d2.compania = p_entity_name
WHEN p_dimension = 'ramo' THEN d2.ramo = p_entity_name
WHEN p_dimension = 'oficina' THEN d2.oficina_id = p_entity_id::uuid
WHEN p_dimension = 'vendedor' THEN d2.vend_id = p_entity_id
ELSE false
END
AND CASE WHEN v_scope = 'admin' THEN true WHEN v_scope = 'office' THEN d2.oficina_id = v_oficina_id ELSE d2.vend_id = v_vend_id END)
END
) INTO v_result
FROM sicas_documents d
WHERE
CASE
WHEN v_scope = 'admin' THEN true
WHEN v_scope = 'office' THEN d.oficina_id = v_oficina_id
ELSE d.vend_id = v_vend_id
END
AND CASE
WHEN p_dimension = 'cliente' THEN d.cliente ILIKE '%' || regexp_replace(p_entity_name, '[%_]', '', 'g') || '%'
WHEN p_dimension = 'aseguradora' THEN d.compania = p_entity_name
WHEN p_dimension = 'ramo' THEN d.ramo = p_entity_name
WHEN p_dimension = 'oficina' THEN d.oficina_id = p_entity_id::uuid
WHEN p_dimension = 'vendedor' THEN d.vend_id = p_entity_id
ELSE false
END
AND (p_fecha_desde IS NULL OR d.fecha_captura >= p_fecha_desde::timestamptz)
AND (p_fecha_hasta IS NULL OR d.fecha_captura <= (p_fecha_hasta || 'T23:59:59')::timestamptz);

RETURN COALESCE(v_result, jsonb_build_object('total_docs', 0, 'prima_neta_total', 0, 'prima_vigente', 0, 'unique_count', 0, 'polizas_vigentes', 0, 'polizas_canceladas', 0));
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_sicas_filter_options(p_user_id uuid, p_scope text DEFAULT 'all'::text, p_oficina_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
v_rol text;
v_oficina_id uuid;
v_vend_id text;
v_scope text;
v_aseguradoras jsonb;
v_ramos jsonb;
v_subramos jsonb;
v_monedas jsonb;
v_vendedores jsonb;
BEGIN
-- Get user role and office
SELECT rol, oficina_id INTO v_rol, v_oficina_id
FROM usuarios WHERE id = p_user_id;

IF v_rol IS NULL THEN
RETURN jsonb_build_object(
'aseguradoras', '[]'::jsonb,
'ramos', '[]'::jsonb,
'subramos', '[]'::jsonb,
'monedas', '[]'::jsonb,
'vendedores', '[]'::jsonb
);
END IF;

-- Determine scope (same logic as KPI functions)
IF v_rol IN ('Administrador', 'Ejecutivo') THEN
v_scope := 'admin';
ELSIF v_rol IN ('Gerente', 'Empleado') THEN
v_scope := 'office';
ELSE
v_scope := 'self';
END IF;

-- For self scope, resolve the SICAS vendor ID
IF v_scope = 'self' THEN
v_vend_id := get_sicas_user_vend_id(p_user_id);
END IF;

SELECT COALESCE(jsonb_agg(DISTINCT d.compania ORDER BY d.compania), '[]'::jsonb)
INTO v_aseguradoras
FROM sicas_documents d
WHERE d.compania IS NOT NULL
AND CASE
WHEN v_scope = 'admin' THEN (p_oficina_id IS NULL OR d.oficina_id = p_oficina_id)
WHEN v_scope = 'office' THEN d.oficina_id = v_oficina_id
ELSE d.vend_id = v_vend_id
END;

SELECT COALESCE(jsonb_agg(DISTINCT d.ramo ORDER BY d.ramo), '[]'::jsonb)
INTO v_ramos
FROM sicas_documents d
WHERE d.ramo IS NOT NULL
AND CASE
WHEN v_scope = 'admin' THEN (p_oficina_id IS NULL OR d.oficina_id = p_oficina_id)
WHEN v_scope = 'office' THEN d.oficina_id = v_oficina_id
ELSE d.vend_id = v_vend_id
END;

SELECT COALESCE(jsonb_agg(DISTINCT d.subramo ORDER BY d.subramo), '[]'::jsonb)
INTO v_subramos
FROM sicas_documents d
WHERE d.subramo IS NOT NULL
AND CASE
WHEN v_scope = 'admin' THEN (p_oficina_id IS NULL OR d.oficina_id = p_oficina_id)
WHEN v_scope = 'office' THEN d.oficina_id = v_oficina_id
ELSE d.vend_id = v_vend_id
END;

SELECT COALESCE(jsonb_agg(DISTINCT d.moneda ORDER BY d.moneda), '[]'::jsonb)
INTO v_monedas
FROM sicas_documents d
WHERE d.moneda IS NOT NULL
AND CASE
WHEN v_scope = 'admin' THEN (p_oficina_id IS NULL OR d.oficina_id = p_oficina_id)
WHEN v_scope = 'office' THEN d.oficina_id = v_oficina_id
ELSE d.vend_id = v_vend_id
END;

SELECT COALESCE(jsonb_agg(jsonb_build_object('id', v.vend_id, 'nombre', v.vend_nombre) ORDER BY v.vend_nombre), '[]'::jsonb)
INTO v_vendedores
FROM (
SELECT DISTINCT d.vend_id, d.vend_nombre
FROM sicas_documents d
WHERE d.vend_id IS NOT NULL AND d.vend_nombre IS NOT NULL
AND CASE
WHEN v_scope = 'admin' THEN (p_oficina_id IS NULL OR d.oficina_id = p_oficina_id)
WHEN v_scope = 'office' THEN d.oficina_id = v_oficina_id
ELSE d.vend_id = v_vend_id
END
) v;

RETURN jsonb_build_object(
'aseguradoras', v_aseguradoras,
'ramos', v_ramos,
'subramos', v_subramos,
'monedas', v_monedas,
'vendedores', v_vendedores
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_sicas_global_summary(p_oficina_id uuid DEFAULT NULL::uuid, p_ramo text DEFAULT NULL::text, p_compania text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
result jsonb;
BEGIN
SELECT jsonb_build_object(
'total_docs',         COUNT(*),
'total_vigentes',     COUNT(*) FILTER (WHERE is_vigente),
'total_canceladas',   COUNT(*) FILTER (WHERE is_cancelada),
'total_vencidas',     COUNT(*) FILTER (WHERE NOT is_vigente AND NOT is_cancelada AND vigencia_hasta < now()),
'prima_total',        COALESCE(SUM(prima_neta), 0),
'prima_vigente',      COALESCE(SUM(prima_neta) FILTER (WHERE is_vigente), 0),
'renovaciones_60d',   COUNT(*) FILTER (WHERE is_vigente AND renewal_days_remaining BETWEEN 0 AND 60),
'renovaciones_30d',   COUNT(*) FILTER (WHERE is_vigente AND renewal_days_remaining BETWEEN 0 AND 30),
'unique_vendors',     COUNT(DISTINCT vend_id),
'unique_aseguradoras',COUNT(DISTINCT compania),
'unique_ramos',       COUNT(DISTINCT ramo),
'unique_clientes',    COUNT(DISTINCT cliente),
'docs_with_user',     COUNT(usuario_id),
'docs_without_user',  COUNT(*) - COUNT(usuario_id)
) INTO result
FROM sicas_documents
WHERE (p_oficina_id IS NULL OR oficina_id = p_oficina_id)
AND (p_ramo IS NULL OR ramo = p_ramo)
AND (p_compania IS NULL OR compania = p_compania);

RETURN result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_sicas_local_dashboard(p_user_id uuid DEFAULT NULL::uuid, p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date, p_tipo text DEFAULT 'all'::text, p_status text DEFAULT NULL::text, p_ramo text DEFAULT NULL::text, p_subramo text DEFAULT NULL::text, p_aseguradora text DEFAULT NULL::text, p_cliente text DEFAULT NULL::text, p_moneda text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_vend_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_result jsonb;
v_total_docs integer;
v_polizas_emitidas integer;
v_fianzas_emitidas integer;
v_prima_neta_total numeric;
v_prima_total_total numeric;
v_polizas_vigentes integer;
v_fianzas_vigentes integer;
v_prima_vigente numeric;
v_cancelaciones integer;
v_clientes_total integer;
v_renew_7 integer;
v_renew_15 integer;
v_renew_30 integer;
v_prima_renovar numeric;
BEGIN
-- Refresh renewal flags
PERFORM refresh_sicas_document_renewal_flags();

-- Base counts using conditional aggregation
SELECT
COUNT(*),
COUNT(*) FILTER (WHERE is_poliza = true),
COUNT(*) FILTER (WHERE is_fianza = true),
COALESCE(SUM(prima_neta), 0),
COALESCE(SUM(prima_total), 0),
COUNT(*) FILTER (WHERE is_vigente = true AND is_poliza = true),
COUNT(*) FILTER (WHERE is_vigente = true AND is_fianza = true),
COALESCE(SUM(prima_total) FILTER (WHERE is_vigente = true), 0),
COUNT(*) FILTER (WHERE is_cancelada = true),
COUNT(DISTINCT cliente) FILTER (WHERE cliente IS NOT NULL AND cliente != ''),
COUNT(*) FILTER (WHERE is_renewable = true AND renewal_days_remaining BETWEEN 0 AND 7),
COUNT(*) FILTER (WHERE is_renewable = true AND renewal_days_remaining BETWEEN 0 AND 15),
COUNT(*) FILTER (WHERE is_renewable = true AND renewal_days_remaining BETWEEN 0 AND 30),
COALESCE(SUM(prima_total) FILTER (WHERE is_renewable = true AND renewal_days_remaining BETWEEN 0 AND 30), 0)
INTO
v_total_docs, v_polizas_emitidas, v_fianzas_emitidas,
v_prima_neta_total, v_prima_total_total,
v_polizas_vigentes, v_fianzas_vigentes, v_prima_vigente,
v_cancelaciones, v_clientes_total,
v_renew_7, v_renew_15, v_renew_30, v_prima_renovar
FROM sicas_documents d
WHERE
(p_user_id IS NULL OR EXISTS (
SELECT 1 FROM sicas_document_user_map m
WHERE m.sicas_id_docto = d.id_docto AND m.movi_user_id = p_user_id
))
AND (p_vend_id IS NULL OR d.vend_id = p_vend_id)
AND (p_fecha_desde IS NULL OR d.vigencia_desde >= p_fecha_desde)
AND (p_fecha_hasta IS NULL OR d.vigencia_hasta <= p_fecha_hasta)
AND (p_tipo = 'all' OR (p_tipo = 'policies' AND is_poliza = true) OR (p_tipo = 'bonds' AND is_fianza = true))
AND (p_status IS NULL OR LOWER(d.status_texto) = LOWER(p_status))
AND (p_ramo IS NULL OR d.ramo ILIKE '%' || p_ramo || '%')
AND (p_subramo IS NULL OR d.subramo ILIKE '%' || p_subramo || '%')
AND (p_aseguradora IS NULL OR d.aseguradora_nombre ILIKE '%' || p_aseguradora || '%')
AND (p_cliente IS NULL OR d.cliente ILIKE '%' || p_cliente || '%')
AND (p_moneda IS NULL OR d.moneda = p_moneda)
AND (p_search IS NULL OR (
d.poliza ILIKE '%' || p_search || '%'
OR d.cliente ILIKE '%' || p_search || '%'
OR d.aseguradora_nombre ILIKE '%' || p_search || '%'
));

v_result := jsonb_build_object(
'ok', true,
'source', 'local',
'totalRecords', v_total_docs,
'recordsAnalyzed', v_total_docs,
'kpis', jsonb_build_object(
'polizasEmitidas', v_polizas_emitidas,
'fianzasEmitidas', v_fianzas_emitidas,
'totalDocumentos', v_total_docs,
'primaNetaEmitida', ROUND(v_prima_neta_total, 2),
'primaTotalEmitida', ROUND(v_prima_total_total, 2),
'polizasVigentes', v_polizas_vigentes,
'fianzasVigentes', v_fianzas_vigentes,
'primaVigente', ROUND(v_prima_vigente, 2),
'renovaciones7dias', v_renew_7,
'renovaciones15dias', v_renew_15,
'renovaciones30dias', v_renew_30,
'primaRenovar', ROUND(v_prima_renovar, 2),
'cancelaciones', v_cancelaciones,
'clientesTotal', v_clientes_total,
'ticketPromedio', CASE WHEN v_total_docs > 0 THEN ROUND(v_prima_total_total / v_total_docs, 2) ELSE 0 END
)
);

-- Top ramos
v_result := v_result || jsonb_build_object('topRamos', (
SELECT COALESCE(jsonb_agg(r ORDER BY r->>'prima' DESC), '[]'::jsonb)
FROM (
SELECT jsonb_build_object('name', ramo, 'count', COUNT(*), 'prima', ROUND(SUM(prima_total), 2)) AS r
FROM sicas_documents d
WHERE ramo IS NOT NULL AND ramo != ''
AND (p_user_id IS NULL OR EXISTS (SELECT 1 FROM sicas_document_user_map m WHERE m.sicas_id_docto = d.id_docto AND m.movi_user_id = p_user_id))
AND (p_vend_id IS NULL OR d.vend_id = p_vend_id)
AND (p_fecha_desde IS NULL OR d.vigencia_desde >= p_fecha_desde)
AND (p_fecha_hasta IS NULL OR d.vigencia_hasta <= p_fecha_hasta)
GROUP BY ramo ORDER BY SUM(prima_total) DESC LIMIT 10
) sub
));

-- Top aseguradoras
v_result := v_result || jsonb_build_object('topAseguradoras', (
SELECT COALESCE(jsonb_agg(r ORDER BY r->>'prima' DESC), '[]'::jsonb)
FROM (
SELECT jsonb_build_object('name', aseguradora_nombre, 'count', COUNT(*), 'prima', ROUND(SUM(prima_total), 2)) AS r
FROM sicas_documents d
WHERE aseguradora_nombre IS NOT NULL AND aseguradora_nombre != ''
AND (p_user_id IS NULL OR EXISTS (SELECT 1 FROM sicas_document_user_map m WHERE m.sicas_id_docto = d.id_docto AND m.movi_user_id = p_user_id))
AND (p_vend_id IS NULL OR d.vend_id = p_vend_id)
AND (p_fecha_desde IS NULL OR d.vigencia_desde >= p_fecha_desde)
AND (p_fecha_hasta IS NULL OR d.vigencia_hasta <= p_fecha_hasta)
GROUP BY aseguradora_nombre ORDER BY SUM(prima_total) DESC LIMIT 10
) sub
));

-- Top clientes
v_result := v_result || jsonb_build_object('topClientes', (
SELECT COALESCE(jsonb_agg(r ORDER BY r->>'prima' DESC), '[]'::jsonb)
FROM (
SELECT jsonb_build_object('name', cliente, 'count', COUNT(*), 'prima', ROUND(SUM(prima_total), 2)) AS r
FROM sicas_documents d
WHERE cliente IS NOT NULL AND cliente != ''
AND (p_user_id IS NULL OR EXISTS (SELECT 1 FROM sicas_document_user_map m WHERE m.sicas_id_docto = d.id_docto AND m.movi_user_id = p_user_id))
AND (p_vend_id IS NULL OR d.vend_id = p_vend_id)
AND (p_fecha_desde IS NULL OR d.vigencia_desde >= p_fecha_desde)
AND (p_fecha_hasta IS NULL OR d.vigencia_hasta <= p_fecha_hasta)
GROUP BY cliente ORDER BY SUM(prima_total) DESC LIMIT 10
) sub
));

-- Available filters
v_result := v_result || jsonb_build_object('availableFilters', jsonb_build_object(
'ramos', (SELECT COALESCE(jsonb_agg(DISTINCT ramo ORDER BY ramo), '[]'::jsonb) FROM sicas_documents WHERE ramo IS NOT NULL AND ramo != ''),
'subramos', (SELECT COALESCE(jsonb_agg(DISTINCT subramo ORDER BY subramo), '[]'::jsonb) FROM sicas_documents WHERE subramo IS NOT NULL AND subramo != ''),
'aseguradoras', (SELECT COALESCE(jsonb_agg(DISTINCT aseguradora_nombre ORDER BY aseguradora_nombre), '[]'::jsonb) FROM sicas_documents WHERE aseguradora_nombre IS NOT NULL AND aseguradora_nombre != ''),
'monedas', (SELECT COALESCE(jsonb_agg(DISTINCT moneda ORDER BY moneda), '[]'::jsonb) FROM sicas_documents WHERE moneda IS NOT NULL AND moneda != '')
));

-- Renewals list (next 30 days, up to 50)
v_result := v_result || jsonb_build_object('renewals', (
SELECT COALESCE(jsonb_agg(jsonb_build_object(
'idDocto', d.id_docto,
'documento', d.poliza,
'tipo', d.tipo_documento,
'ramo', d.ramo,
'subramo', d.subramo,
'aseguradora', d.aseguradora_nombre,
'cliente', d.cliente,
'fechaDesde', d.vigencia_desde,
'fechaHasta', d.vigencia_hasta,
'primaNeta', d.prima_neta,
'primaTotal', d.prima_total,
'moneda', d.moneda,
'status', d.status_texto,
'vendedor', d.vend_nombre,
'vendedorId', d.vend_id,
'daysRemaining', d.renewal_days_remaining
) ORDER BY d.renewal_days_remaining ASC), '[]'::jsonb)
FROM sicas_documents d
WHERE d.is_renewable = true AND d.renewal_days_remaining BETWEEN 0 AND 30
AND (p_user_id IS NULL OR EXISTS (SELECT 1 FROM sicas_document_user_map m WHERE m.sicas_id_docto = d.id_docto AND m.movi_user_id = p_user_id))
AND (p_vend_id IS NULL OR d.vend_id = p_vend_id)
LIMIT 50
));

-- Status distribution
v_result := v_result || jsonb_build_object('porEstatus', (
SELECT COALESCE(jsonb_agg(jsonb_build_object('estatus', status_texto, 'count', cnt, 'prima', prima)), '[]'::jsonb)
FROM (
SELECT status_texto, COUNT(*) AS cnt, ROUND(SUM(prima_total), 2) AS prima
FROM sicas_documents d
WHERE status_texto IS NOT NULL AND status_texto != ''
AND (p_user_id IS NULL OR EXISTS (SELECT 1 FROM sicas_document_user_map m WHERE m.sicas_id_docto = d.id_docto AND m.movi_user_id = p_user_id))
AND (p_vend_id IS NULL OR d.vend_id = p_vend_id)
AND (p_fecha_desde IS NULL OR d.vigencia_desde >= p_fecha_desde)
AND (p_fecha_hasta IS NULL OR d.vigencia_hasta <= p_fecha_hasta)
GROUP BY status_texto
) sub
));

RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_sicas_monthly_prima(p_vend_id text DEFAULT NULL::text, p_fecha_desde text DEFAULT NULL::text, p_fecha_hasta text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_result json;
BEGIN
SELECT json_agg(row_data ORDER BY mes)
INTO v_result
FROM (
SELECT
to_char(vigencia_desde, 'YYYY-MM') AS mes,
COUNT(*) AS count,
COALESCE(SUM(prima_neta), 0)::numeric(14,2) AS "primaNeta",
COALESCE(SUM(prima_total), 0)::numeric(14,2) AS "primaTotal",
COUNT(*) AS emisiones
FROM sicas_documents
WHERE vigencia_desde IS NOT NULL
AND (p_vend_id IS NULL OR vend_id = p_vend_id)
AND (p_fecha_desde IS NULL OR vigencia_desde >= p_fecha_desde::date)
AND (p_fecha_hasta IS NULL OR vigencia_desde <= p_fecha_hasta::date)
GROUP BY to_char(vigencia_desde, 'YYYY-MM')
) row_data;

RETURN COALESCE(v_result, '[]'::json);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_sicas_oficinas_con_documentos()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN COALESCE((
SELECT jsonb_agg(row_to_json(t) ORDER BY t.nombre)
FROM (
SELECT
d.oficina_id AS id,
COALESCE(o.nombre, d.oficina_nombre, d.desp_nombre, 'Sin oficina') AS nombre,
COUNT(*) AS documentos
FROM sicas_documents d
LEFT JOIN oficinas o ON o.id = d.oficina_id
WHERE d.oficina_id IS NOT NULL
GROUP BY d.oficina_id, o.nombre, d.oficina_nombre, d.desp_nombre
ORDER BY nombre
) t
), '[]'::jsonb);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_sicas_sync_diagnostics()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_result jsonb;
v_total integer;
v_polizas integer;
v_fianzas integer;
v_vigentes integer;
v_canceladas integer;
v_renewables integer;
v_distinct_vendors integer;
v_distinct_aseguradoras integer;
v_with_user_id integer;
v_with_oficina_id integer;
v_last_sync_at timestamptz;
v_last_sync_status text;
v_last_sync_records integer;
v_stuck_runs integer;
v_mapped_vendor_ids integer;
v_unmapped_vendor_ids integer;
v_unmapped_vendor_list jsonb;
v_user_map_entries integer;
BEGIN
SELECT
COUNT(*),
COUNT(*) FILTER (WHERE is_poliza = true),
COUNT(*) FILTER (WHERE is_fianza = true),
COUNT(*) FILTER (WHERE is_vigente = true),
COUNT(*) FILTER (WHERE is_cancelada = true),
COUNT(*) FILTER (WHERE is_renewable = true),
COUNT(DISTINCT vend_id) FILTER (WHERE vend_id IS NOT NULL AND vend_id != ''),
COUNT(DISTINCT aseguradora_nombre) FILTER (WHERE aseguradora_nombre IS NOT NULL AND aseguradora_nombre != ''),
COUNT(*) FILTER (WHERE usuario_id IS NOT NULL),
COUNT(*) FILTER (WHERE oficina_id IS NOT NULL)
INTO
v_total, v_polizas, v_fianzas, v_vigentes, v_canceladas, v_renewables,
v_distinct_vendors, v_distinct_aseguradoras, v_with_user_id, v_with_oficina_id
FROM sicas_documents;

SELECT finished_at, status, records_upserted
INTO v_last_sync_at, v_last_sync_status, v_last_sync_records
FROM sicas_sync_runs
WHERE status IN ('completed', 'success')
ORDER BY finished_at DESC NULLS LAST
LIMIT 1;

SELECT COUNT(*)
INTO v_stuck_runs
FROM sicas_sync_runs
WHERE status = 'running'
AND started_at < NOW() - INTERVAL '30 minutes';

SELECT COUNT(DISTINCT sd.vend_id)
INTO v_mapped_vendor_ids
FROM sicas_documents sd
WHERE sd.vend_id IS NOT NULL AND sd.vend_id != ''
AND (
EXISTS (SELECT 1 FROM sicas_mapeo_vendedor_usuario m WHERE m.id_sicas_vendedor::text = sd.vend_id)
OR EXISTS (SELECT 1 FROM usuarios u WHERE u.id_sicas = sd.vend_id AND u.activo = true)
);

SELECT COUNT(DISTINCT sd.vend_id)
INTO v_unmapped_vendor_ids
FROM sicas_documents sd
WHERE sd.vend_id IS NOT NULL AND sd.vend_id != ''
AND NOT EXISTS (SELECT 1 FROM sicas_mapeo_vendedor_usuario m WHERE m.id_sicas_vendedor::text = sd.vend_id)
AND NOT EXISTS (SELECT 1 FROM usuarios u WHERE u.id_sicas = sd.vend_id AND u.activo = true);

SELECT COALESCE(jsonb_agg(jsonb_build_object(
'vendId', sub.vend_id,
'vendName', sub.vend_name,
'docCount', sub.cnt
) ORDER BY sub.cnt DESC), '[]'::jsonb)
INTO v_unmapped_vendor_list
FROM (
SELECT sd.vend_id, MAX(sd.vend_nombre) as vend_name, COUNT(*) as cnt
FROM sicas_documents sd
WHERE sd.vend_id IS NOT NULL AND sd.vend_id != ''
AND NOT EXISTS (SELECT 1 FROM sicas_mapeo_vendedor_usuario m WHERE m.id_sicas_vendedor::text = sd.vend_id)
AND NOT EXISTS (SELECT 1 FROM usuarios u WHERE u.id_sicas = sd.vend_id AND u.activo = true)
GROUP BY sd.vend_id
) sub;

SELECT COUNT(*)
INTO v_user_map_entries
FROM sicas_document_user_map;

v_result := jsonb_build_object(
'totalDocs', v_total,
'polizas', v_polizas,
'fianzas', v_fianzas,
'vigentes', v_vigentes,
'canceladas', v_canceladas,
'renewables', v_renewables,
'distinctVendors', v_distinct_vendors,
'distinctAseguradoras', v_distinct_aseguradoras,
'withUserId', v_with_user_id,
'withOficinaId', v_with_oficina_id,
'lastSyncAt', v_last_sync_at,
'lastSyncStatus', v_last_sync_status,
'lastSyncRecords', COALESCE(v_last_sync_records, 0),
'stuckRuns', v_stuck_runs,
'mappedVendorIds', v_mapped_vendor_ids,
'unmappedVendorIds', v_unmapped_vendor_ids,
'unmappedVendors', v_unmapped_vendor_list,
'userMapEntries', v_user_map_entries
);

RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_sicas_sync_stats()
 RETURNS TABLE(despachos_count bigint, vendedores_count bigint, documents_count bigint, polizas_vigentes_count bigint, last_sync_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
RETURN QUERY
SELECT
(SELECT COUNT(*) FROM sicas_despachos)::bigint,
(SELECT COUNT(*) FROM sicas_vendedores)::bigint,
(SELECT COUNT(*) FROM sicas_documents)::bigint,
(SELECT COUNT(*) FROM sicas_polizas_vigentes)::bigint,
(SELECT MAX(synced_at) FROM sicas_documents);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_sicas_user_scope(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_rol text;
v_oficina_id uuid;
v_scope text;
v_id_sicas text;
v_vend_id text;
BEGIN
SELECT rol, oficina_id, id_sicas
INTO v_rol, v_oficina_id, v_id_sicas
FROM usuarios
WHERE id = p_user_id AND (deleted_at IS NULL);

IF v_rol IS NULL THEN
RETURN jsonb_build_object('error', 'User not found');
END IF;

IF v_rol = 'Administrador' THEN
v_scope := 'admin';
ELSIF v_rol IN ('Gerente', 'Empleado', 'Ejecutivo') THEN
v_scope := 'office';
ELSE
v_scope := 'self';
END IF;

-- Resolve vendor ID for self-scope users
IF v_scope = 'self' THEN
v_vend_id := get_sicas_user_vend_id(p_user_id);
END IF;

RETURN jsonb_build_object(
'scope', v_scope,
'rol', v_rol,
'oficina_id', v_oficina_id,
'id_sicas', v_id_sicas,
'vend_id', v_vend_id
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_sicas_user_vend_id(p_user_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_vend_id text;
v_nombre_sicas text;
BEGIN
-- Priority 1: explicit mapping table
SELECT mvu.id_sicas_vendedor INTO v_vend_id
FROM sicas_mapeo_vendedor_usuario mvu
WHERE mvu.movi_user_id = p_user_id
LIMIT 1;

IF v_vend_id IS NOT NULL THEN
RETURN v_vend_id;
END IF;

-- Priority 2: usuarios.id_sicas field
SELECT u.id_sicas INTO v_vend_id
FROM usuarios u
WHERE u.id = p_user_id AND u.id_sicas IS NOT NULL;

IF v_vend_id IS NOT NULL THEN
RETURN v_vend_id;
END IF;

-- Priority 3: match by nombre_sicas
SELECT u.nombre_sicas INTO v_nombre_sicas
FROM usuarios u
WHERE u.id = p_user_id AND u.nombre_sicas IS NOT NULL;

IF v_nombre_sicas IS NOT NULL THEN
SELECT sv.id_sicas INTO v_vend_id
FROM sicas_vendedores sv
WHERE UPPER(sv.nombre) = UPPER(v_nombre_sicas)
LIMIT 1;
END IF;

RETURN v_vend_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_sicas_vendors_unmapped(p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_search text DEFAULT NULL::text)
 RETURNS TABLE(vend_id text, vend_nombre text, desp_nombre text, total_docs bigint, vigentes bigint, prima_neta numeric, prima_vigente numeric, ultimo_documento timestamp with time zone, suggested_user_id uuid, suggested_user_name text, mapping_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN QUERY
WITH vendor_stats AS (
SELECT
d.vend_id,
MAX(d.vend_nombre) AS vend_nombre,
MAX(d.desp_nombre) AS desp_nombre,
COUNT(*) AS total_docs,
COUNT(*) FILTER (WHERE d.is_vigente) AS vigentes,
COALESCE(SUM(d.prima_neta), 0) AS prima_neta,
COALESCE(SUM(d.prima_neta) FILTER (WHERE d.is_vigente), 0) AS prima_vigente,
MAX(d.synced_at) AS ultimo_documento
FROM sicas_documents d
WHERE d.usuario_id IS NULL
AND d.vend_id IS NOT NULL
AND (p_search IS NULL OR d.vend_id ILIKE '%' || p_search || '%' OR d.vend_nombre ILIKE '%' || p_search || '%')
GROUP BY d.vend_id
)
SELECT
vs.vend_id,
vs.vend_nombre,
vs.desp_nombre,
vs.total_docs,
vs.vigentes,
vs.prima_neta,
vs.prima_vigente,
vs.ultimo_documento,
m.movi_user_id AS suggested_user_id,
NULL::text AS suggested_user_name,
COALESCE(m.status, 'pending_review') AS mapping_status
FROM vendor_stats vs
LEFT JOIN sicas_vendor_user_mappings m ON m.vend_id = vs.vend_id
ORDER BY vs.prima_neta DESC
LIMIT p_limit OFFSET p_offset;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_smart_assistant_intent_map()
 RETURNS TABLE(intent text, keywords text[], boost_keywords text[], form_type_slug text, assistant_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
