$function$
;

CREATE OR REPLACE FUNCTION public.get_subramos_por_combinacion(p_ramo_id uuid, p_compania_id uuid)
 RETURNS TABLE(id uuid, nombre text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  SELECT DISTINCT ms.id, ms.nombre
  FROM   public.maestro_subramos ms
  JOIN   public.maestro_combinaciones c ON c.subramo_id = ms.id
  WHERE  c.ramo_id     = p_ramo_id
    AND  c.compania_id = p_compania_id
    AND  c.activo      = true
    AND  ms.activo     = true
  ORDER  BY ms.nombre;
$function$
;

CREATE OR REPLACE FUNCTION public.get_tareas_vencidas()
 RETURNS TABLE(id uuid, descripcion text, tipo_actividad text, fecha_vencimiento timestamp with time zone, prioridad text, estatus text, dias_vencidos integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
RETURN QUERY
SELECT
t.id,
t.descripcion,
t.tipo_actividad,
t.fecha_vencimiento,
t.prioridad,
t.estatus,
EXTRACT(DAY FROM (now() - t.fecha_vencimiento))::INTEGER as dias_vencidos
FROM crm_tareas t
WHERE t.creado_por = auth.uid()
AND t.estatus != 'Completada'
AND t.fecha_vencimiento < now()
ORDER BY t.fecha_vencimiento ASC;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_ticket_comisiones_pendientes(p_ticket_id uuid)
 RETURNS TABLE(id uuid, numero_poliza text, aseguradora text, fecha_pago date, orden integer, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
RETURN QUERY
SELECT
tcp.id,
tcp.numero_poliza,
tcp.aseguradora,
tcp.fecha_pago,
tcp.orden,
tcp.created_at
FROM ticket_comisiones_pendientes tcp
WHERE tcp.ticket_id = p_ticket_id
ORDER BY tcp.orden ASC;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_tickets_agente_premium(p_agente_id uuid)
 RETURNS TABLE(ticket_id uuid, folio text, tipo_tramite text, fecha_creacion timestamp with time zone, custom_estatus_label text, creado_por uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller_rol   text;
  v_tiene_acceso boolean := false;
BEGIN
  SELECT rol INTO v_caller_rol FROM usuarios WHERE id = auth.uid();

  IF v_caller_rol IN ('Administrador', 'Gerente') THEN
    v_tiene_acceso := true;
  ELSE
    SELECT EXISTS (
      SELECT 1
      FROM tramites_grupos_miembros tgm
      JOIN mkt_equipos_acceso mea ON mea.grupo_id = tgm.grupo_id
      WHERE tgm.usuario_id = auth.uid()
    ) INTO v_tiene_acceso;
  END IF;

  IF NOT v_tiene_acceso THEN RETURN; END IF;

  RETURN QUERY
  SELECT t.id, t.folio, t.tipo_tramite, t.fecha_creacion, t.custom_estatus_label, t.creado_por
  FROM tickets t
  WHERE (t.agente_id = p_agente_id OR t.agente_usuario_id = p_agente_id)
    AND t.eliminado_at IS NULL
  ORDER BY t.fecha_creacion DESC;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_tipos_para_equipo(p_equipo_id uuid)
 RETURNS TABLE(tipo_id uuid, value text, label text, area text, color text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT DISTINCT
    tt.id    AS tipo_id,
    tt.value,
    tt.label,
    ta.nombre AS area,
    tt.color
  FROM  public.tramites_equipos_areas tea
  JOIN  public.ticket_tipos           tt  ON tt.id = ANY(tea.tramites_activos)
  JOIN  public.tramites_areas         ta  ON ta.id = tea.area_id
  WHERE tea.equipo_id = p_equipo_id
    AND tt.activo    = true
    AND ta.activa    = true
  ORDER BY ta.nombre, tt.label;
$function$
;

CREATE OR REPLACE FUNCTION public.get_top_active_users()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_caller_role text;
BEGIN
SELECT rol INTO v_caller_role FROM usuarios WHERE id = auth.uid();
IF v_caller_role != 'Administrador' THEN
RETURN '[]'::jsonb;
END IF;

RETURN COALESCE((
SELECT jsonb_agg(row_to_json(r))
FROM (
SELECT
al.user_id,
al.user_name_snapshot AS nombre,
al.role_snapshot AS rol,
al.office_name_snapshot AS oficina,
COUNT(*) AS total_acciones,
MAX(al.created_at) AS ultima_actividad
FROM unified_activity_view al
WHERE al.created_at >= date_trunc('month', CURRENT_DATE)
AND al.user_id IS NOT NULL
GROUP BY al.user_id, al.user_name_snapshot, al.role_snapshot, al.office_name_snapshot
ORDER BY total_acciones DESC
LIMIT 8
) r
), '[]'::jsonb);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_top_active_users(p_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_caller_role text;
result jsonb;
BEGIN
SELECT rol INTO v_caller_role FROM usuarios WHERE id = auth.uid();
IF v_caller_role != 'Administrador' THEN
RETURN '[]'::jsonb;
END IF;

SELECT COALESCE(jsonb_agg(row_to_json(r)), '[]'::jsonb) INTO result
FROM (
SELECT 
al.user_id,
al.user_name_snapshot as nombre,
al.role_snapshot as rol,
al.office_name_snapshot as oficina,
COUNT(*) as total_actions,
MAX(al.created_at) as last_activity
FROM user_activity_logs al
WHERE al.created_at >= date_trunc('month', CURRENT_DATE)
GROUP BY al.user_id, al.user_name_snapshot, al.role_snapshot, al.office_name_snapshot
ORDER BY total_actions DESC
LIMIT p_limit
) r;

RETURN result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_top_agents(p_order_by text DEFAULT 'xp_total'::text, p_limit integer DEFAULT 10)
 RETURNS TABLE(user_id uuid, nombre_completo text, oficina text, xp_total integer, jiro_coins_balance integer, nivel_actual integer, rango_actual text, total_polizas_emitidas integer, rank bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
BEGIN
RETURN QUERY
SELECT 
agp.user_id,
u.nombre_completo,
o.nombre as oficina,
agp.xp_total,
agp.jiro_coins_balance,
agp.nivel_actual,
agp.rango_actual,
agp.total_polizas_emitidas,
ROW_NUMBER() OVER (
ORDER BY 
CASE WHEN p_order_by = 'xp_total' THEN agp.xp_total END DESC,
CASE WHEN p_order_by = 'jiro_coins_balance' THEN agp.jiro_coins_balance END DESC,
CASE WHEN p_order_by = 'total_polizas_emitidas' THEN agp.total_polizas_emitidas END DESC,
agp.created_at ASC
) as rank
FROM agent_gamification_profile agp
INNER JOIN usuarios u ON u.id = agp.user_id
LEFT JOIN oficinas o ON o.id = u.oficina_id
WHERE u.rol = 'Agente'
ORDER BY rank
LIMIT p_limit;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_top_modules()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_caller_role text;
BEGIN
SELECT rol INTO v_caller_role FROM usuarios WHERE id = auth.uid();
IF v_caller_role != 'Administrador' THEN
RETURN '[]'::jsonb;
END IF;

RETURN COALESCE((
SELECT jsonb_agg(row_to_json(r))
FROM (
SELECT
al.module,
COUNT(*) AS total,
COUNT(DISTINCT al.user_id) AS usuarios_unicos
FROM unified_activity_view al
WHERE al.created_at >= date_trunc('month', CURRENT_DATE)
GROUP BY al.module
ORDER BY total DESC
LIMIT 10
) r
), '[]'::jsonb);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_tramite_attachments(p_ticket_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_attachments jsonb;
BEGIN
-- Use explicit column selection to avoid RLS GROUP BY issues
SELECT jsonb_agg(
jsonb_build_object(
'filename', ta.nombre,
'path', ta.url,
'content_type', COALESCE(ta.tipo, 'application/octet-stream'),
'size', ta.tamano
)
)
INTO v_attachments
FROM (
SELECT 
id,
nombre,
url,
tipo,
tamano,
fecha_subida
FROM ticket_archivos
WHERE ticket_id = p_ticket_id
ORDER BY fecha_subida ASC
) ta;

RETURN COALESCE(v_attachments, '[]'::jsonb);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_tramite_teams_full()
 RETURNS TABLE(id uuid, nombre text, descripcion text, color text, area_categoria text, activo boolean, all_offices boolean, created_at timestamp with time zone, updated_at timestamp with time zone, member_count bigint, office_count bigint)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
SELECT
g.id,
g.nombre,
g.descripcion,
g.color,
g.area_categoria,
g.activo,
g.all_offices,
g.created_at,
g.updated_at,
COUNT(DISTINCT m.usuario_id) AS member_count,
COUNT(DISTINCT o.oficina_id) AS office_count
FROM tramites_grupos_visualizacion g
LEFT JOIN tramites_grupos_miembros m ON m.grupo_id = g.id
LEFT JOIN tramites_grupos_oficinas o ON o.grupo_id = g.id
GROUP BY g.id
ORDER BY g.activo DESC, g.area_categoria, g.nombre;
$function$
;

CREATE OR REPLACE FUNCTION public.get_tramites_kpis(p_fecha_inicio timestamp with time zone DEFAULT NULL::timestamp with time zone, p_fecha_fin timestamp with time zone DEFAULT NULL::timestamp with time zone, p_oficina_id uuid DEFAULT NULL::uuid, p_usuario_id uuid DEFAULT NULL::uuid, p_tipo_tramite text DEFAULT NULL::text, p_avance integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_result jsonb;
v_total int;
v_pendientes int;
v_en_proceso int;
v_finalizados int;
v_tiempo_promedio numeric;
v_porcentaje_finalizacion numeric;
v_avance_promedio numeric;
BEGIN
WITH filtered_tickets AS (
SELECT DISTINCT t.*
FROM tickets t
LEFT JOIN ticket_asignaciones ta ON t.id = ta.ticket_id
LEFT JOIN usuarios u ON ta.ejecutivo_id = u.id
WHERE (p_fecha_inicio IS NULL OR t.fecha_creacion >= p_fecha_inicio)
AND (p_fecha_fin IS NULL OR t.fecha_creacion <= p_fecha_fin)
AND (p_oficina_id IS NULL OR u.oficina_id = p_oficina_id)
AND (p_usuario_id IS NULL OR ta.ejecutivo_id = p_usuario_id)
AND (p_tipo_tramite IS NULL OR t.tipo_tramite = p_tipo_tramite)
AND (p_avance IS NULL OR t.progress_percent = p_avance)
)
SELECT
COUNT(*),
COUNT(CASE WHEN COALESCE(progress_percent, 0) = 0 THEN 1 END),
COUNT(CASE WHEN progress_percent > 0 AND progress_percent < 100 THEN 1 END),
COUNT(CASE WHEN progress_percent = 100 THEN 1 END),
ROUND(AVG(
CASE 
WHEN cerrado_en IS NOT NULL THEN
EXTRACT(EPOCH FROM (cerrado_en - fecha_creacion)) / 86400.0
ELSE NULL
END
), 2),
ROUND(AVG(COALESCE(progress_percent, 0)), 2)
INTO v_total, v_pendientes, v_en_proceso, v_finalizados, v_tiempo_promedio, v_avance_promedio
FROM filtered_tickets;

IF v_total > 0 THEN
v_porcentaje_finalizacion := ROUND((v_finalizados::numeric / v_total * 100), 2);
ELSE
v_porcentaje_finalizacion := 0;
END IF;

v_result := jsonb_build_object(
'total_tramites', COALESCE(v_total, 0),
'tramites_pendientes', COALESCE(v_pendientes, 0),
'tramites_en_proceso', COALESCE(v_en_proceso, 0),
'tramites_finalizados', COALESCE(v_finalizados, 0),
'tiempo_promedio_resolucion_dias', COALESCE(v_tiempo_promedio, 0),
'porcentaje_finalizacion', COALESCE(v_porcentaje_finalizacion, 0),
'avance_promedio', COALESCE(v_avance_promedio, 0)
);

RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_tramites_kpis_by_status(p_fecha_inicio timestamp with time zone DEFAULT NULL::timestamp with time zone, p_fecha_fin timestamp with time zone DEFAULT NULL::timestamp with time zone, p_oficina_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(estatus_nombre text, estatus_color text, total bigint, porcentaje numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN QUERY
WITH base AS (
SELECT te.nombre, te.color, COUNT(t.id)::bigint as cnt
FROM tickets t
JOIN ticket_estatus te ON te.id = t.estatus_id
LEFT JOIN usuarios u ON u.id = t.agente_usuario_id
WHERE t.tipo_tramite = 'registro_actividad'
AND (p_fecha_inicio IS NULL OR t.fecha_creacion >= p_fecha_inicio)
AND (p_fecha_fin IS NULL OR t.fecha_creacion <= p_fecha_fin)
AND (p_oficina_id IS NULL OR u.oficina_id = p_oficina_id)
AND t.deleted_at IS NULL
GROUP BY te.nombre, te.color
),
total_cte AS (SELECT COALESCE(SUM(cnt), 1) as grand_total FROM base)
SELECT b.nombre, b.color, b.cnt,
ROUND((b.cnt::numeric / tc.grand_total::numeric) * 100, 1)
FROM base b, total_cte tc
ORDER BY b.cnt DESC;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_unified_contactos(p_user_id uuid DEFAULT NULL::uuid, p_search text DEFAULT NULL::text, p_estatus text DEFAULT NULL::text, p_has_seguwallet boolean DEFAULT NULL::boolean, p_limit integer DEFAULT 200, p_offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, source text, nombre_completo text, email text, celular text, whatsapp text, tipo_contacto text, estatus text, fuente_origen text, creado_por uuid, agente_id uuid, fecha_creacion timestamp with time zone, actualizado_en timestamp with time zone, seguwallet_customer_id uuid, seguwallet_status text, seguwallet_profile_completed boolean, seguwallet_last_login timestamp with time zone, seguwallet_agent_id uuid, sicas_count integer, agente_nombre text, oficina_nombre text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET row_security TO 'off'
AS $function$
DECLARE
  v_caller      uuid;
  v_rol         text;
  v_oficina_id  uuid;
BEGIN
  -- Never trust a caller-supplied user id for authorization.
  v_caller := auth.uid();

  SELECT u.rol, u.oficina_id
    INTO v_rol, v_oficina_id
    FROM usuarios u
   WHERE u.id = v_caller
   LIMIT 1;

  RETURN QUERY
  WITH crm_with_sw AS (
    SELECT
      c.id                                                       AS cws_id,
      'crm'::text                                               AS cws_source,
      c.nombre_completo                                         AS cws_nombre_completo,
      c.email                                                   AS cws_email,
      c.celular                                                 AS cws_celular,
      c.whatsapp                                                AS cws_whatsapp,
      c.tipo_contacto                                           AS cws_tipo_contacto,
      c.estatus                                                 AS cws_estatus,
      c.fuente_origen                                           AS cws_fuente_origen,
      c.creado_por                                              AS cws_creado_por,
      c.agente_id                                               AS cws_agente_id,
      c.fecha_creacion                                          AS cws_fecha_creacion,
      c.actualizado_en                                          AS cws_actualizado_en,
      sw.id                                                     AS cws_sw_id,
      sw.status                                                 AS cws_sw_status,
      sw.profile_completed                                      AS cws_sw_profile_completed,
      sw.last_login_at                                          AS cws_sw_last_login,
      sw.agent_user_id                                          AS cws_sw_agent_id,
      COALESCE((
        SELECT COUNT(*)::integer
          FROM seguwallet_customer_sicas_clients scsc
         WHERE scsc.seguwallet_customer_id = sw.id
      ), 0)                                                     AS cws_sicas_count,
      CASE WHEN v_rol = 'Administrador' THEN owner.nombre_completo ELSE NULL END AS cws_agente_nombre,
      CASE WHEN v_rol = 'Administrador' THEN office.nombre ELSE NULL END AS cws_oficina_nombre
    FROM crm_contactos c
    LEFT JOIN seguwallet_customers sw ON sw.crm_contact_id = c.id
    LEFT JOIN usuarios owner ON owner.id = c.agente_id
    LEFT JOIN oficinas office ON office.id = c.oficina_id
    WHERE
      (
        v_rol = 'Administrador'
        OR (
          v_rol IN ('Gerente','Empleado','Ejecutivo')
          AND (
            c.agente_id = v_caller
            OR c.oficina_id = v_oficina_id
          )
        )
        OR (
          v_rol = 'Agente'
          AND c.agente_id = v_caller
        )
        OR c.agente_id = v_caller
      )
      AND (
        p_search IS NULL
        OR c.nombre_completo ILIKE '%' || p_search || '%'
        OR c.email           ILIKE '%' || p_search || '%'
        OR c.celular         ILIKE '%' || p_search || '%'
      )
      AND (p_estatus IS NULL OR c.estatus = p_estatus)
      AND (
        p_has_seguwallet IS NULL
        OR (p_has_seguwallet = true  AND sw.id IS NOT NULL)
        OR (p_has_seguwallet = false AND sw.id IS NULL)
      )
  ),
  sw_only AS (
    SELECT
      sw2.id                                                    AS so_id,
      'seguwallet'::text                                        AS so_source,
      COALESCE(sw2.full_name, sw2.email, 'Sin nombre')         AS so_nombre_completo,
      sw2.email                                                 AS so_email,
      sw2.phone                                                 AS so_celular,
      sw2.whatsapp                                              AS so_whatsapp,
      'Cliente Seguwallet'::text                               AS so_tipo_contacto,
      CASE WHEN sw2.status = 'active' THEN 'activo' ELSE 'inactivo' END AS so_estatus,
      'seguwallet'::text                                        AS so_fuente_origen,
      sw2.agent_user_id                                         AS so_creado_por,
      sw2.agent_user_id                                         AS so_agente_id,
      sw2.created_at                                            AS so_fecha_creacion,
      sw2.updated_at                                            AS so_actualizado_en,
      sw2.id                                                    AS so_sw_id,
      sw2.status                                                AS so_sw_status,
      sw2.profile_completed                                     AS so_sw_profile_completed,
      sw2.last_login_at                                         AS so_sw_last_login,
      sw2.agent_user_id                                         AS so_sw_agent_id,
      COALESCE((
        SELECT COUNT(*)::integer
          FROM seguwallet_customer_sicas_clients scsc2
         WHERE scsc2.seguwallet_customer_id = sw2.id
      ), 0)                                                     AS so_sicas_count,
      CASE WHEN v_rol = 'Administrador' THEN sw_owner.nombre_completo ELSE NULL END AS so_agente_nombre,
      CASE WHEN v_rol = 'Administrador' THEN sw_office.nombre ELSE NULL END AS so_oficina_nombre
    FROM seguwallet_customers sw2
    LEFT JOIN usuarios sw_owner ON sw_owner.id = sw2.agent_user_id
    LEFT JOIN oficinas sw_office ON sw_office.id = sw_owner.oficina_id
    WHERE sw2.crm_contact_id IS NULL
      AND sw2.deleted_at IS NULL
      AND (
        v_rol = 'Administrador'
        OR (
          v_rol IN ('Gerente','Empleado','Ejecutivo')
          AND sw2.agent_user_id IN (
            SELECT u3.id FROM usuarios u3 WHERE u3.oficina_id = v_oficina_id
          )
        )
        OR sw2.agent_user_id = v_caller
      )
      AND (
        p_search IS NULL
        OR COALESCE(sw2.full_name,'') ILIKE '%' || p_search || '%'
        OR sw2.email                        ILIKE '%' || p_search || '%'
        OR sw2.phone                        ILIKE '%' || p_search || '%'
      )
      AND (p_has_seguwallet IS NULL OR p_has_seguwallet = true)
  )
  SELECT
    cws_id,
    cws_source,
    cws_nombre_completo,
    cws_email,
    cws_celular,
    cws_whatsapp,
    cws_tipo_contacto,
    cws_estatus,
    cws_fuente_origen,
    cws_creado_por,
    cws_agente_id,
    cws_fecha_creacion,
    cws_actualizado_en,
    cws_sw_id,
    cws_sw_status,
    cws_sw_profile_completed,
    cws_sw_last_login,
    cws_sw_agent_id,
    cws_sicas_count,
    cws_agente_nombre,
    cws_oficina_nombre
  FROM crm_with_sw

  UNION ALL

  SELECT
    so_id,
    so_source,
    so_nombre_completo,
    so_email,
    so_celular,
    so_whatsapp,
    so_tipo_contacto,
    so_estatus,
    so_fuente_origen,
    so_creado_por,
    so_agente_id,
    so_fecha_creacion,
    so_actualizado_en,
    so_sw_id,
    so_sw_status,
    so_sw_profile_completed,
    so_sw_last_login,
    so_sw_agent_id,
    so_sicas_count,
    so_agente_nombre,
    so_oficina_nombre
  FROM sw_only

  ORDER BY 11 DESC
  LIMIT p_limit
  OFFSET p_offset;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_unmatched_vendor_groups_all(p_batch_id uuid)
 RETURNS TABLE(vendor_key text, vendor_name_norm text, vendor_name_raw text, vendor_email_norm text, vendor_email_raw text, document_count bigint, grouping_type text, example_documents jsonb)
 LANGUAGE plpgsql
 STABLE
AS $function$
BEGIN
RETURN QUERY
SELECT
doc.vendor_key,
doc.vendor_name_norm,
MODE() WITHIN GROUP (ORDER BY doc.vendor_name_raw) as vendor_name_raw,
doc.vendor_email_norm,
MODE() WITHIN GROUP (ORDER BY doc.vendor_email_raw) as vendor_email_raw,
COUNT(doc.id) as document_count,
CASE
WHEN doc.vendor_name_norm IS NOT NULL AND doc.vendor_name_norm != '' THEN 'name'
WHEN doc.vendor_email_norm IS NOT NULL AND doc.vendor_email_norm != '' THEN 'email'
ELSE 'unknown'
END as grouping_type,
jsonb_agg(
jsonb_build_object(
'id', doc.id,
'document_id', doc.document_id,
'vendor_email_raw', doc.vendor_email_raw,
'vendor_name_raw', doc.vendor_name_raw,
'document_data', doc.document_data
)
ORDER BY doc.created_at DESC
) FILTER (WHERE doc.id IS NOT NULL) as example_documents
FROM imported_documents doc
WHERE doc.batch_id = p_batch_id
AND doc.is_unmatched = true
GROUP BY doc.vendor_key, doc.vendor_name_norm, doc.vendor_email_norm
ORDER BY document_count DESC;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_unmatched_vendor_groups_by_name(p_batch_id uuid)
 RETURNS TABLE(vendor_name_norm text, vendor_name_raw text, document_count bigint, emails_detected text[], example_documents jsonb)
 LANGUAGE plpgsql
 STABLE
AS $function$
BEGIN
RETURN QUERY
SELECT
doc.vendor_name_norm,
-- Tomar el vendor_name_raw más común del grupo
MODE() WITHIN GROUP (ORDER BY doc.vendor_name_raw) as vendor_name_raw,
COUNT(doc.id) as document_count,
-- Recopilar emails únicos detectados en el grupo
ARRAY_AGG(DISTINCT doc.vendor_email_raw) FILTER (WHERE doc.vendor_email_raw IS NOT NULL AND doc.vendor_email_raw != '') as emails_detected,
-- Ejemplos de documentos (máximo 10)
jsonb_agg(
jsonb_build_object(
'id', doc.id,
'document_id', doc.document_id,
'vendor_email_raw', doc.vendor_email_raw,
'document_data', doc.document_data
)
ORDER BY doc.created_at DESC
) FILTER (WHERE doc.id IS NOT NULL) as example_documents
FROM imported_documents doc
WHERE doc.batch_id = p_batch_id
AND doc.is_unmatched = true
AND doc.vendor_name_norm IS NOT NULL
AND doc.vendor_name_norm != ''
GROUP BY doc.vendor_name_norm
ORDER BY document_count DESC;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_unmatched_vendors_by_batch(batch_id_param uuid)
 RETURNS TABLE(vendor_key text, vendor_type text, vendor_email text, vendor_name text, polizas_count bigint, total_commission numeric, example_polizas jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
RETURN QUERY
SELECT 
cd.vendor_key,
CASE 
WHEN cd.vendor_key LIKE 'email:%' THEN 'email'
WHEN cd.vendor_key LIKE 'name:%' THEN 'name'
ELSE 'unknown'
END::TEXT as vendor_type,
COALESCE(cd.vendor_email_raw, '')::TEXT as vendor_email,
COALESCE(cd.vendor_name_raw, '')::TEXT as vendor_name,
COUNT(cd.id)::BIGINT as polizas_count,
SUM(cd.commission_neta)::NUMERIC as total_commission,
JSONB_AGG(
JSONB_BUILD_OBJECT(
'id', cd.id,
'poliza', cd.poliza,
'ramo', cd.ramo,
'aseguradora', cd.aseguradora,
'prima_neta', cd.prima_neta,
'commission_neta', cd.commission_neta
) 
ORDER BY cd.created_at DESC
) FILTER (WHERE cd.id IS NOT NULL) AS example_polizas
FROM commission_details cd
WHERE cd.batch_id = batch_id_param
AND cd.is_unmatched = true
AND cd.vendor_key IS NOT NULL
GROUP BY cd.vendor_key, cd.vendor_email_raw, cd.vendor_name_raw
ORDER BY polizas_count DESC;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_unmatched_vendors_by_name(p_batch_id uuid)
 RETURNS TABLE(vendor_name_norm text, vendor_display_name text, document_count bigint, emails_detected text[], unique_email_count integer, example_documents jsonb)
 LANGUAGE plpgsql
 STABLE
AS $function$
BEGIN
RETURN QUERY
-- Vendedores con nombre
SELECT
doc.vendor_name_norm as vendor_name_norm,
MODE() WITHIN GROUP (ORDER BY doc.vendor_name_raw) as vendor_display_name,
COUNT(doc.id) as document_count,
ARRAY(
SELECT DISTINCT unnest(ARRAY_AGG(doc2.vendor_email_raw))
FROM imported_documents doc2
WHERE doc2.batch_id = p_batch_id
AND doc2.is_unmatched = true
AND doc2.vendor_name_norm = doc.vendor_name_norm
AND doc2.vendor_email_raw IS NOT NULL
AND doc2.vendor_email_raw != ''
) as emails_detected,
(
SELECT COUNT(DISTINCT doc3.vendor_email_raw)
FROM imported_documents doc3
WHERE doc3.batch_id = p_batch_id
AND doc3.is_unmatched = true
AND doc3.vendor_name_norm = doc.vendor_name_norm
AND doc3.vendor_email_raw IS NOT NULL
AND doc3.vendor_email_raw != ''
)::INTEGER as unique_email_count,
(
SELECT jsonb_agg(doc_sample)
FROM (
SELECT jsonb_build_object(
'id', doc4.id,
'document_id', doc4.document_id,
'vendor_email_raw', doc4.vendor_email_raw,
'vendor_name_raw', doc4.vendor_name_raw,
'document_data', doc4.document_data
) as doc_sample
FROM imported_documents doc4
WHERE doc4.batch_id = p_batch_id
AND doc4.is_unmatched = true
AND doc4.vendor_name_norm = doc.vendor_name_norm
ORDER BY doc4.created_at DESC
LIMIT 10
) sample_docs
) as example_documents
FROM imported_documents doc
WHERE doc.batch_id = p_batch_id
AND doc.is_unmatched = true
AND doc.vendor_name_norm IS NOT NULL
AND doc.vendor_name_norm != ''
GROUP BY doc.vendor_name_norm

UNION ALL

-- Vendedores sin nombre (solo email)
SELECT
COALESCE(doc.vendor_email_norm, 'unknown') as vendor_name_norm,
COALESCE(MODE() WITHIN GROUP (ORDER BY doc.vendor_email_raw), 'Solo email') as vendor_display_name,
COUNT(doc.id) as document_count,
ARRAY_AGG(DISTINCT doc.vendor_email_raw) FILTER (WHERE doc.vendor_email_raw IS NOT NULL AND doc.vendor_email_raw != '') as emails_detected,
COUNT(DISTINCT doc.vendor_email_raw) FILTER (WHERE doc.vendor_email_raw IS NOT NULL AND doc.vendor_email_raw != '')::INTEGER as unique_email_count,
(
SELECT jsonb_agg(doc_sample)
FROM (
SELECT jsonb_build_object(
'id', doc5.id,
'document_id', doc5.document_id,
'vendor_email_raw', doc5.vendor_email_raw,
'vendor_name_raw', doc5.vendor_name_raw,
'document_data', doc5.document_data
) as doc_sample
FROM imported_documents doc5
WHERE doc5.batch_id = p_batch_id
AND doc5.is_unmatched = true
AND (doc5.vendor_name_norm IS NULL OR doc5.vendor_name_norm = '')
AND doc5.vendor_email_norm = doc.vendor_email_norm
ORDER BY doc5.created_at DESC
LIMIT 10
) sample_docs
) as example_documents
FROM imported_documents doc
WHERE doc.batch_id = p_batch_id
AND doc.is_unmatched = true
AND (doc.vendor_name_norm IS NULL OR doc.vendor_name_norm = '')
AND doc.vendor_email_norm IS NOT NULL
AND doc.vendor_email_norm != ''
GROUP BY doc.vendor_email_norm

UNION ALL

-- Documentos sin vendedor (ni nombre ni email)
SELECT
'unknown' as vendor_name_norm,
'Sin información de vendedor' as vendor_display_name,
COUNT(doc.id) as document_count,
ARRAY[]::TEXT[] as emails_detected,
0 as unique_email_count,
(
SELECT jsonb_agg(doc_sample)
FROM (
SELECT jsonb_build_object(
'id', doc6.id,
'document_id', doc6.document_id,
'vendor_email_raw', doc6.vendor_email_raw,
'vendor_name_raw', doc6.vendor_name_raw,
'document_data', doc6.document_data
) as doc_sample
FROM imported_documents doc6
WHERE doc6.batch_id = p_batch_id
AND doc6.is_unmatched = true
AND (doc6.vendor_name_norm IS NULL OR doc6.vendor_name_norm = '')
AND (doc6.vendor_email_norm IS NULL OR doc6.vendor_email_norm = '')
ORDER BY doc6.created_at DESC
LIMIT 10
) sample_docs
) as example_documents
FROM imported_documents doc
WHERE doc.batch_id = p_batch_id
AND doc.is_unmatched = true
AND (doc.vendor_name_norm IS NULL OR doc.vendor_name_norm = '')
AND (doc.vendor_email_norm IS NULL OR doc.vendor_email_norm = '')
HAVING COUNT(doc.id) > 0

ORDER BY document_count DESC;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_unread_events_count(p_usuario_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_count integer;
BEGIN
SELECT COUNT(*)
INTO v_count
FROM assistant_events
WHERE usuario_id = p_usuario_id
AND leido = false;

RETURN v_count;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_unrecognized_vendors_for_batch(p_batch_id uuid)
 RETURNS TABLE(vendor_key text, vendor_name_raw text, vendor_email_raw text, items_count bigint, total_commission double precision, has_existing_mapping boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
RETURN QUERY
SELECT
cd.vendor_key,
MAX(cd.vendor_name_raw) as vendor_name_raw,
MAX(cd.vendor_email_raw) as vendor_email_raw,
COUNT(*) as items_count,
SUM(COALESCE(cd.commission_calculada, cd.commission_bruta, 0)) as total_commission,
EXISTS (
SELECT 1 FROM vendor_mappings vm
WHERE (
(cd.vendor_key LIKE 'email:%' AND vm.source_type = 'email' AND vm.source_value = SUBSTRING(cd.vendor_key FROM 7))
OR
(cd.vendor_key LIKE 'name:%' AND vm.source_type = 'name' AND vm.source_value = SUBSTRING(cd.vendor_key FROM 6))
)
AND vm.status = 'active'
) as has_existing_mapping
FROM commission_details cd
WHERE
cd.batch_id = p_batch_id
AND cd.pending_assignment = true
AND cd.vendor_key IS NOT NULL
GROUP BY cd.vendor_key
ORDER BY items_count DESC, total_commission DESC;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_user_commissions_summary(p_usuario_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_result jsonb;
BEGIN
SELECT jsonb_build_object(
'pendientes', jsonb_build_object(
'total', COALESCE(SUM(comision), 0),
'count', COUNT(*),
'polizas', COUNT(DISTINCT no_poliza)
),
'pagadas', jsonb_build_object(
'total', COALESCE(
(SELECT SUM(comision) FROM sicas_comisiones_pagadas WHERE usuario_id = p_usuario_id),
0
),
'count', (SELECT COUNT(*) FROM sicas_comisiones_pagadas WHERE usuario_id = p_usuario_id),
'polizas', (SELECT COUNT(DISTINCT no_poliza) FROM sicas_comisiones_pagadas WHERE usuario_id = p_usuario_id)
)
) INTO v_result
FROM sicas_comisiones_pendientes
WHERE usuario_id = p_usuario_id;

RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_user_full_context(p_usuario_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_result jsonb;
BEGIN
SELECT jsonb_build_object(
'usuario_id', p_usuario_id,

-- Chat conversaciones
'chat_conversaciones', (
SELECT COALESCE(jsonb_agg(chat_data), '[]'::jsonb)
FROM (
SELECT jsonb_build_object(
'chat_id', c.id,
'tipo', c.tipo,
'nombre', c.nombre,
'ultimo_mensaje_at', c.ultimo_mensaje_at,
'ultimos_mensajes', (
SELECT COALESCE(jsonb_agg(msg_data), '[]'::jsonb)
FROM (
SELECT jsonb_build_object(
'remitente', u2.nombre_completo,
'mensaje', cm.mensaje,
'created_at', cm.created_at
) as msg_data
FROM chat_mensajes cm
LEFT JOIN usuarios u2 ON u2.id = cm.remitente_id
WHERE cm.chat_id = c.id
AND cm.eliminado = false
ORDER BY cm.created_at DESC
LIMIT 5
) msgs
)
) as chat_data
FROM chats c
INNER JOIN chat_miembros cmem ON cmem.chat_id = c.id
WHERE cmem.usuario_id = p_usuario_id
ORDER BY c.ultimo_mensaje_at DESC NULLS LAST
LIMIT 20
) chats
),

-- Comisiones
'comisiones_count', (
SELECT COUNT(*)
FROM commission_details
WHERE movi_user_id = p_usuario_id
),

-- Tareas CRM
'tareas_pendientes', (
SELECT COUNT(*)
FROM crm_tareas
WHERE creado_por = p_usuario_id
AND completada = false
),

-- Tickets
'tickets_activos', (
SELECT COUNT(*)
FROM tickets
WHERE creado_por = p_usuario_id
AND cerrado_en IS NULL
),

-- DIRECTORIO COMPLETO
'directorio_empleados', (
SELECT COALESCE(jsonb_agg(emp_data ORDER BY nombre, apellidos), '[]'::jsonb)
FROM (
SELECT jsonb_build_object(
'id', u.id,
'nombre_completo', u.nombre || ' ' || u.apellidos,
'nombre', u.nombre,
'apellidos', u.apellidos,
'rol', u.rol,
'puesto', u.puesto,
'oficina', o.nombre,
'celular_laboral', u.celular_laboral,
'extension_telefonica', u.extension_telefonica,
'email_laboral', u.email_laboral,
'celular_personal', u.celular_personal,
'email_personal', u.email_personal
) as emp_data,
u.nombre,
u.apellidos
FROM usuarios u
LEFT JOIN oficinas o ON u.oficina_id = o.id
WHERE u.activo = true
) empleados
),

-- OFICINAS COMPLETO
'directorio_oficinas', (
SELECT COALESCE(jsonb_agg(ofi_data ORDER BY nombre), '[]'::jsonb)
FROM (
SELECT jsonb_build_object(
'id', o.id,
'nombre', o.nombre,
'telefono', o.telefono,
'domicilio', o.domicilio,
'email', o.email,
'facebook', o.facebook,
'instagram', o.instagram,
'gerente', (
SELECT u.nombre || ' ' || u.apellidos
FROM usuarios u
WHERE u.oficina_id = o.id
AND u.rol = 'Gerente'
AND u.activo = true
LIMIT 1
)
) as ofi_data,
o.nombre
FROM oficinas o
WHERE o.activa = true
) oficinas
)
)
INTO v_result;

RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_user_grupos(p_usuario_id uuid)
 RETURNS TABLE(grupo_id uuid, grupo_nombre text, grupo_color text)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
RETURN QUERY
SELECT
g.id,
g.nombre,
g.color
FROM tramites_grupos_visualizacion g
INNER JOIN tramites_grupos_miembros m ON m.grupo_id = g.id
WHERE m.usuario_id = p_usuario_id
AND g.activo = true
ORDER BY g.nombre;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_user_nombre_sicas(p_user_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE
v_nombre_sicas TEXT;
BEGIN
-- Primero intentar desde usuarios (fuente de verdad)
SELECT nombre_sicas INTO v_nombre_sicas
FROM usuarios
WHERE id = p_user_id;

IF v_nombre_sicas IS NOT NULL THEN
RETURN v_nombre_sicas;
END IF;

-- Si no existe, buscar en sicas_mapeo_vendedor_usuario
SELECT sv.nombre INTO v_nombre_sicas
FROM sicas_mapeo_vendedor_usuario smu
JOIN sicas_vendedores sv ON sv.id_sicas = smu.id_sicas_vendedor
WHERE smu.movi_user_id = p_user_id;

RETURN v_nombre_sicas;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_user_office_for_quotes(user_uuid uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
SELECT oficina_id FROM usuarios WHERE id = user_uuid AND activo = true LIMIT 1;
$function$
;

CREATE OR REPLACE FUNCTION public.get_user_oficina_for_rls(p_user_id uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
SELECT oficina_id FROM usuarios WHERE id = p_user_id AND deleted_at IS NULL;
$function$
;

CREATE OR REPLACE FUNCTION public.get_user_recent_activity(p_usuario_id uuid, p_dias integer DEFAULT 7)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_result jsonb;
v_fecha_inicio timestamp;
BEGIN
v_fecha_inicio := now() - (p_dias || ' days')::interval;

v_result := jsonb_build_object(
'comisiones_nuevas', (
SELECT COUNT(*)
FROM commission_details
WHERE movi_user_id = p_usuario_id
AND created_at >= v_fecha_inicio
),
'tareas_completadas', (
SELECT COUNT(*)
FROM crm_tareas
WHERE creado_por = p_usuario_id
AND completada = true
AND updated_at >= v_fecha_inicio
),
'mensajes_enviados', (
SELECT COUNT(*)
FROM chat_mensajes cm
WHERE cm.remitente_id = p_usuario_id
AND cm.created_at >= v_fecha_inicio
AND cm.eliminado = false
),
'tickets_creados', (
SELECT COUNT(*)
FROM tickets
WHERE creado_por = p_usuario_id
AND created_at >= v_fecha_inicio
),
'comunicados_leidos', (
SELECT COUNT(*)
FROM comunicados_leidos
WHERE usuario_id = p_usuario_id
AND fecha_lectura >= v_fecha_inicio
)
);

RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_user_role(user_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE
user_role text;
BEGIN
SELECT rol INTO user_role
FROM usuarios
WHERE id = user_id;

RETURN user_role;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_user_role_for_quotes(user_uuid uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
SELECT
CASE LOWER(rol)
WHEN 'administrador' THEN 'admin'
WHEN 'gerente' THEN 'gerente'
WHEN 'agente' THEN 'agente'
WHEN 'empleado' THEN 'empleado'
WHEN 'ejecutivo' THEN 'ejecutivo'
ELSE LOWER(rol)
END
FROM usuarios
WHERE id = user_uuid AND activo = true
LIMIT 1;
$function$
;

