CREATE OR REPLACE FUNCTION public.get_user_sicas_mapping(p_usuario_id uuid)
 RETURNS TABLE(sicas_id_vendedor text, sicas_id_oficina text, sicas_id_gerencia text, sicas_nombre_vendedor text, sicas_nombre_oficina text, rol text, oficina_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
RETURN QUERY
SELECT 
sum.sicas_id_vendedor,
sum.sicas_id_oficina,
sum.sicas_id_gerencia,
sum.sicas_nombre_vendedor,
sum.sicas_nombre_oficina,
u.rol::text,
u.oficina_id
FROM usuarios u
LEFT JOIN sicas_user_mapping sum ON sum.usuario_id = u.id AND sum.es_mapeo_principal = true
WHERE u.id = p_usuario_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_user_sicas_permissions(p_usuario_id uuid)
 RETURNS TABLE(rol text, oficina_id uuid, nombre_sicas text, puede_ver_todas boolean, puede_ver_oficina boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN QUERY
SELECT
u.rol,
u.oficina_id,
u.nombre_sicas,
(u.rol = 'admin') as puede_ver_todas,
(u.rol IN ('gerente', 'empleado')) as puede_ver_oficina
FROM usuarios u
WHERE u.id = p_usuario_id
LIMIT 1;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_user_tramite_area(p_user_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
SELECT g.area_categoria
FROM tramites_grupos_miembros m
INNER JOIN tramites_grupos_visualizacion g ON g.id = m.grupo_id
WHERE m.usuario_id = p_user_id
AND g.activo = true
AND g.area_categoria IS NOT NULL
