CREATE OR REPLACE FUNCTION public.get_users_who_can_attend()
 RETURNS TABLE(id uuid, nombre_completo text, rol text, oficina_nombre text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_oficina_id uuid;
BEGIN
-- Obtener oficina del usuario actual
SELECT usuarios.oficina_id INTO v_oficina_id
FROM usuarios
WHERE usuarios.id = auth.uid();

-- Si no tiene oficina, retornar vacío
IF v_oficina_id IS NULL THEN
RETURN;
END IF;

-- Retornar usuarios de la misma oficina con roles permitidos
RETURN QUERY
SELECT 
u.id,
u.nombre_completo,
u.rol,
o.nombre as oficina_nombre
FROM usuarios u
LEFT JOIN oficinas o ON u.oficina_id = o.id
WHERE u.oficina_id = v_oficina_id
AND u.rol IN ('Empleado', 'Gerente', 'Administrador')
AND u.estado = 'activo'
AND u.deleted_at IS NULL
ORDER BY 
CASE u.rol
WHEN 'Administrador' THEN 1
WHEN 'Gerente' THEN 2
WHEN 'Empleado' THEN 3
ELSE 4
END,
u.nombre_completo;
END;
$function$
;

