CREATE OR REPLACE FUNCTION public.get_validation_error_details(batch_id_param uuid, error_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
result jsonb;
BEGIN
IF error_type = 'MISSING_DATE' THEN
SELECT jsonb_agg(
jsonb_build_object(
'row_index', source_row_index,
'poliza', COALESCE((document_data->>'poliza'), (document_data->>'policy'), document_id),
'vendor_name', COALESCE(vendor_name_raw, 'Sin vendedor'),
'vendor_email', COALESCE(vendor_email_raw, 'Sin email'),
'document_id', document_id
)
) INTO result
FROM imported_documents
WHERE batch_id = batch_id_param
AND (
document_data->>'fecha_fpago' IS NULL
OR document_data->>'fecha_fpago' = ''
OR document_data->>'fecha' IS NULL
OR document_data->>'fecha' = ''
)
LIMIT 100;

ELSIF error_type = 'UNASSIGNED_USER' THEN
SELECT jsonb_agg(
jsonb_build_object(
'row_index', source_row_index,
'poliza', COALESCE((document_data->>'poliza'), (document_data->>'policy'), document_id),
'vendor_name', COALESCE(vendor_name_raw, 'Sin vendedor'),
'vendor_email', COALESCE(vendor_email_raw, 'Sin email'),
'document_id', document_id
)
) INTO result
FROM imported_documents
WHERE batch_id = batch_id_param
AND (movi_user_id IS NULL OR is_unmatched = true)
LIMIT 100;

ELSIF error_type = 'EMPTY_VENDOR' THEN
SELECT jsonb_agg(
jsonb_build_object(
'row_index', source_row_index,
'poliza', COALESCE((document_data->>'poliza'), (document_data->>'policy'), document_id),
'document_id', document_id
)
) INTO result
FROM imported_documents
WHERE batch_id = batch_id_param
AND (vendor_name_raw IS NULL OR vendor_name_raw = '')
AND (vendor_email_raw IS NULL OR vendor_email_raw = '')
LIMIT 100;
END IF;

RETURN COALESCE(result, '[]'::jsonb);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.handle_new_auth_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
BEGIN
-- Insert into usuarios table with same UUID as auth.users
INSERT INTO public.usuarios (
id,
email_laboral,
rol,
estado,
created_at,
updated_at
)
VALUES (
NEW.id,
NEW.email,
'agente', -- default role
'activo',
NOW(),
NOW()
)
ON CONFLICT (id) DO UPDATE
SET email_laboral = EXCLUDED.email_laboral,
updated_at = NOW();

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.handle_new_user_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_pagina_web text;
v_oficina_nombre text := 'No asignada';
BEGIN
IF NEW.estado = 'activo' AND OLD IS NULL THEN
IF NEW.web_slug IS NOT NULL AND NEW.web_slug != '' THEN
v_pagina_web := 'https://agentedeseguros.website/' || NEW.web_slug;
ELSE
v_pagina_web := 'No configurada';
END IF;

IF NEW.oficina_id IS NOT NULL THEN
SELECT nombre INTO v_oficina_nombre
FROM oficinas
WHERE id = NEW.oficina_id;
END IF;

PERFORM enviar_notificacion_completa(
p_tipo_codigo := 'cuenta_activada',
p_user_id := NEW.id,
p_titulo := '¡Bienvenido a MOVI Digital!',
p_mensaje := 'Tu cuenta ha sido activada exitosamente.',
p_modulo := 'usuarios',
p_datos_adicionales := jsonb_build_object(
'email_laboral', NEW.email_laboral,
'rol', NEW.rol,
'oficina', v_oficina_nombre,
'pagina_web', v_pagina_web,
'puesto', COALESCE(NEW.puesto, '')
),
p_accion_url := 'https://app.movi.digital/dashboard'
);
END IF;

RETURN NEW;
END;
$function$
;

