CREATE OR REPLACE FUNCTION public.ia_cred_get(p_cuenta_id uuid, p_key text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result text;
BEGIN
  SELECT extensions.pgp_sym_decrypt(password_cifrada, p_key) INTO v_result
  FROM public.ia_credenciales_correo WHERE cuenta_id = p_cuenta_id;
  RETURN v_result;
EXCEPTION WHEN OTHERS THEN
  RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.ia_cred_set(p_cuenta_id uuid, p_password text, p_key text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO public.ia_credenciales_correo (cuenta_id, password_cifrada, updated_at)
  VALUES (p_cuenta_id, extensions.pgp_sym_encrypt(p_password, p_key), now())
  ON CONFLICT (cuenta_id) DO UPDATE
    SET password_cifrada = excluded.password_cifrada, updated_at = now();
END;
$function$
;

