 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
result jsonb;
BEGIN
INSERT INTO sicas_sync_runs (
module,
keycode,
report_name,
status,
error_message,
started_at
) VALUES (
'cron',
function_name,
'Scheduled sync job',
'failed',
'Use Supabase scheduled edge functions or external cron service',
