CREATE OR REPLACE FUNCTION public.is_production_cache_valid(p_cache_key text DEFAULT 'production_vendors_main'::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_last_fetched timestamptz;
v_ttl_minutes INTEGER;
v_is_valid BOOLEAN;
BEGIN
SELECT last_fetched_at, ttl_minutes
INTO v_last_fetched, v_ttl_minutes
FROM production_cache_metadata
WHERE cache_key = p_cache_key;

IF v_last_fetched IS NULL THEN
RETURN FALSE;
END IF;

v_is_valid := (v_last_fetched + (v_ttl_minutes * INTERVAL '1 minute')) > NOW();

RETURN v_is_valid;
END;
$function$
;

