CREATE OR REPLACE FUNCTION public.liberar_correo_ocupado(p_email text, p_forzar boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_admin record;
  v_due record;
  v_nuevo text;
BEGIN
  SELECT rol, is_deleted INTO v_admin FROM usuarios WHERE id = auth.uid();
  IF NOT FOUND OR v_admin.rol <> 'Administrador' OR v_admin.is_deleted THEN
    RETURN jsonb_build_object('success', false, 'error', 'Solo un Administrador puede liberar un correo', 'error_code', 'NO_AUTORIZADO');
  END IF;

  SELECT * INTO v_due FROM quien_ocupa_correo(p_email);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', true, 'error_code', 'LIBRE', 'message', 'Ese correo no lo tiene nadie');
  END IF;

  -- Quitarle el correo a alguien que sigue trabajando lo deja sin poder entrar.
  -- No se hace por accidente: hay que pedirlo expresamente.
  IF v_due.visible AND NOT p_forzar THEN
    RETURN jsonb_build_object(
      'success', false, 'error_code', 'EN_USO',
      'error', 'Ese correo lo usa un usuario activo de MOVI',
      'ocupado_por', jsonb_build_object('id', v_due.user_id, 'nombre', concat_ws(' ', v_due.nombre, v_due.apellidos), 'rol', v_due.rol)
    );
  END IF;

  v_nuevo := public.correo_liberado(v_due.user_id);

  UPDATE auth.users
  SET email = v_nuevo, email_confirmed_at = NULL, updated_at = now()
  WHERE id = v_due.user_id;

  UPDATE usuarios
  SET email_laboral = v_nuevo,
      email_personal = CASE WHEN lower(coalesce(email_personal, '')) = lower(trim(p_email)) THEN NULL ELSE email_personal END
  WHERE id = v_due.user_id;

  INSERT INTO audit_logs (action, performed_by, target_user_id, target_resource_type, target_resource_id, details)
  VALUES ('EMAIL_RELEASE', auth.uid(), v_due.user_id, 'usuario', v_due.user_id,
          jsonb_build_object('correo_liberado', trim(p_email), 'correo_nuevo', v_nuevo,
                             'era_visible', v_due.visible, 'motivo', v_due.motivo, 'forzado', p_forzar));

  RETURN jsonb_build_object('success', true, 'liberado_de', v_due.user_id,
                            'nombre', concat_ws(' ', v_due.nombre, v_due.apellidos), 'era_visible', v_due.visible);
END $function$
;

CREATE OR REPLACE FUNCTION public.link_seguwallet_to_crm_contact(p_customer_id uuid, p_crm_contact_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_sw seguwallet_customers%ROWTYPE;
v_contact_id uuid;
v_existing_contact_id uuid;
BEGIN
SELECT * INTO v_sw FROM seguwallet_customers WHERE id = p_customer_id;
IF NOT FOUND THEN
RAISE EXCEPTION 'Seguwallet customer not found';
END IF;

IF p_crm_contact_id IS NOT NULL THEN
UPDATE seguwallet_customers SET crm_contact_id = p_crm_contact_id WHERE id = p_customer_id;
RETURN p_crm_contact_id;
END IF;

IF v_sw.email IS NOT NULL AND v_sw.email != '' THEN
SELECT id INTO v_existing_contact_id
FROM crm_contactos
WHERE email = v_sw.email
LIMIT 1;
END IF;

IF v_existing_contact_id IS NULL AND v_sw.phone IS NOT NULL AND v_sw.phone != '' THEN
SELECT id INTO v_existing_contact_id
FROM crm_contactos
WHERE celular = v_sw.phone
LIMIT 1;
END IF;

IF v_existing_contact_id IS NOT NULL THEN
UPDATE seguwallet_customers SET crm_contact_id = v_existing_contact_id WHERE id = p_customer_id;
RETURN v_existing_contact_id;
ELSE
INSERT INTO crm_contactos (
tipo_contacto, nombre_completo, celular, email, whatsapp,
estatus, fuente_origen, creado_por, fecha_creacion
) VALUES (
'Persona',
v_sw.full_name,
COALESCE(v_sw.phone, ''),
v_sw.email,
v_sw.whatsapp,
'Cliente',
'Seguwallet',
v_sw.agent_user_id,
v_sw.created_at
)
RETURNING id INTO v_contact_id;

UPDATE seguwallet_customers SET crm_contact_id = v_contact_id WHERE id = p_customer_id;
RETURN v_contact_id;
END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.link_vendor_to_user(p_vendor_id uuid, p_movi_user_id uuid, p_linked_by uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_vend_id TEXT;
  v_vend_nombre TEXT;
  v_normalized_name TEXT;
  v_normalized_id TEXT;
BEGIN
  SELECT vend_id, vend_nombre INTO v_vend_id, v_vend_nombre
  FROM sicas_vendor_user_mappings
  WHERE id = p_vendor_id;

  IF v_vend_nombre IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Vendedor SICAS no encontrado');
  END IF;

  UPDATE sicas_vendor_user_mappings
  SET movi_user_id = p_movi_user_id,
      match_type = 'manual',
      confidence_score = 100,
      status = 'active',
      mapped_by = p_linked_by,
      mapped_at = NOW(),
      match_details = jsonb_build_object(
        'method', 'manual_link',
        'linked_at', NOW(),
        'linked_by', p_linked_by
      ),
      updated_at = NOW()
  WHERE id = p_vendor_id;

  UPDATE usuarios
  SET id_sicas = v_vend_id,
      nombre_sicas = v_vend_nombre,
      updated_at = NOW()
  WHERE id = p_movi_user_id;

  v_normalized_name := LOWER(TRIM(
    REGEXP_REPLACE(
      TRANSLATE(v_vend_nombre, 'ÁÉÍÓÚÜÑáéíóúüñ', 'AEIOUUNaeiouun'),
      '\s+', ' ', 'g'
    )
  ));

  INSERT INTO vendor_mappings (source_type, source_value, movi_user_id, status, created_by, notes)
  VALUES ('name', v_normalized_name, p_movi_user_id, 'active', p_linked_by, 'Vinculado manual desde panel unificado (nombre)')
  ON CONFLICT (source_type, source_value) WHERE status = 'active'
  DO UPDATE SET
    movi_user_id = EXCLUDED.movi_user_id,
    updated_by = EXCLUDED.created_by,
    updated_at = NOW(),
    notes = 'Vinculado manual desde panel unificado (nombre actualizado)';

  IF v_vend_id IS NOT NULL AND TRIM(v_vend_id) != '' THEN
    v_normalized_id := LOWER(TRIM(v_vend_id));
    INSERT INTO vendor_mappings (source_type, source_value, movi_user_id, status, created_by, notes)
    VALUES ('id', v_normalized_id, p_movi_user_id, 'active', p_linked_by, 'Vinculado manual desde panel unificado (ID SICAS)')
    ON CONFLICT (source_type, source_value) WHERE status = 'active'
    DO UPDATE SET
      movi_user_id = EXCLUDED.movi_user_id,
      updated_by = EXCLUDED.created_by,
      updated_at = NOW(),
      notes = 'Vinculado manual desde panel unificado (ID SICAS actualizado)';
  END IF;

  BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'sicas_mapeo_vendedor_usuario') THEN
      INSERT INTO sicas_mapeo_vendedor_usuario (id_sicas_vendedor, movi_user_id, mapped_by, mapped_at)
      VALUES (v_vend_id, p_movi_user_id, p_linked_by, NOW())
      ON CONFLICT (id_sicas_vendedor)
      DO UPDATE SET
        movi_user_id = EXCLUDED.movi_user_id,
        mapped_by = EXCLUDED.mapped_by,
        mapped_at = NOW(),
        updated_at = NOW();
    END IF;
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN jsonb_build_object(
    'success', true,
    'vendor_id', v_vend_id,
    'vendor_name', v_vend_nombre,
    'user_id', p_movi_user_id
  );
END;
$function$
;

