CREATE OR REPLACE FUNCTION public.log_ticket_archivo()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
usuario_nombre text;
tamano_mb numeric;
accion_texto text;
BEGIN
SELECT nombre_completo INTO usuario_nombre
FROM usuarios
WHERE id = NEW.usuario_id;

tamano_mb := CASE
WHEN NEW.tamano IS NOT NULL THEN round((NEW.tamano::numeric / 1024 / 1024), 2)
ELSE 0
END;

-- Determinar si es carga
IF TG_OP = 'INSERT' THEN
accion_texto := 'Archivo adjuntado';
END IF;

INSERT INTO ticket_historial (ticket_id, usuario_id, accion, detalle, tipo_accion)
VALUES (
NEW.ticket_id,
NEW.usuario_id,
accion_texto,
jsonb_build_object(
'usuario', usuario_nombre,
'nombre_archivo', NEW.nombre,
'tipo', COALESCE(NEW.tipo, 'desconocido'),
'tamano_mb', tamano_mb
),
'archivo'
);

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.log_ticket_archivo_eliminado()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
usuario_id_actual uuid;
usuario_nombre text;
tamano_mb numeric;
BEGIN
-- Obtener el usuario actual de la sesión
BEGIN
usuario_id_actual := auth.uid();
EXCEPTION WHEN OTHERS THEN
usuario_id_actual := NULL;
END;

IF usuario_id_actual IS NOT NULL THEN
SELECT nombre_completo INTO usuario_nombre
FROM usuarios
WHERE id = usuario_id_actual;

tamano_mb := CASE
WHEN OLD.tamano IS NOT NULL THEN round((OLD.tamano::numeric / 1024 / 1024), 2)
ELSE 0
END;

INSERT INTO ticket_historial (ticket_id, usuario_id, accion, detalle, tipo_accion)
VALUES (
OLD.ticket_id,
usuario_id_actual,
'Archivo eliminado',
jsonb_build_object(
'usuario', usuario_nombre,
'nombre_archivo', OLD.nombre,
'tipo', COALESCE(OLD.tipo, 'desconocido'),
'tamano_mb', tamano_mb
),
'archivo'
);
END IF;

RETURN OLD;
END;
$function$
;

