CREATE OR REPLACE FUNCTION public.log_ticket_cambio()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
accion_texto text;
tipo_accion_valor text;
detalle_json jsonb;
estatus_anterior_nombre text;
estatus_nuevo_nombre text;
agente_nombre text;
cerrado_por_nombre text;
tipo_seguro_nombre text;
tipo_seguro_anterior_nombre text;
tipo_seguro_nuevo_nombre text;
cambios_detectados boolean := false;
BEGIN
IF TG_OP = 'INSERT' THEN
accion_texto := 'Ticket creado';
tipo_accion_valor := 'creacion';
cambios_detectados := true;

-- Obtener nombre del agente si existe
IF NEW.agente_id IS NOT NULL THEN
SELECT nombre_completo INTO agente_nombre
FROM usuarios
WHERE id = NEW.agente_id;
END IF;

-- Obtener nombre del estatus
SELECT nombre INTO estatus_nuevo_nombre
FROM ticket_estatus
WHERE id = NEW.estatus_id;

-- Obtener nombre del tipo de seguro si existe
IF NEW.tipo_seguro_id IS NOT NULL THEN
SELECT nombre INTO tipo_seguro_nombre
FROM tramite_insurance_types
WHERE id = NEW.tipo_seguro_id;
END IF;

detalle_json := jsonb_build_object(
'folio', NEW.folio,
'agente', COALESCE(agente_nombre, 'Sin asignar'),
'estatus', estatus_nuevo_nombre,
'prioridad', NEW.prioridad,
'poliza', COALESCE(NEW.poliza, 'Sin póliza'),
'tipo_seguro', COALESCE(tipo_seguro_nombre, 'No especificado'),
'descripcion_preview', CASE
WHEN NEW.instrucciones IS NOT NULL AND length(NEW.instrucciones) > 100 
THEN substring(NEW.instrucciones from 1 for 100) || '...'
ELSE COALESCE(NEW.instrucciones, '')
END
);

INSERT INTO ticket_historial (ticket_id, usuario_id, accion, detalle, tipo_accion)
VALUES (NEW.id, NEW.creado_por, accion_texto, detalle_json, tipo_accion_valor);

ELSIF TG_OP = 'UPDATE' THEN
detalle_json := '{}'::jsonb;

-- Cambio de estatus (prioridad más alta)
IF OLD.estatus_id != NEW.estatus_id THEN
SELECT nombre INTO estatus_anterior_nombre
FROM ticket_estatus
WHERE id = OLD.estatus_id;

SELECT nombre INTO estatus_nuevo_nombre
FROM ticket_estatus
WHERE id = NEW.estatus_id;

accion_texto := 'Estatus actualizado';
tipo_accion_valor := 'estatus';
detalle_json := jsonb_build_object(
'estatus_anterior', estatus_anterior_nombre,
'estatus_nuevo', estatus_nuevo_nombre
);
cambios_detectados := true;

-- Cambio de prioridad
ELSIF OLD.prioridad != NEW.prioridad THEN
accion_texto := 'Prioridad actualizada';
tipo_accion_valor := 'modificacion';
detalle_json := jsonb_build_object(
'prioridad_anterior', OLD.prioridad,
'prioridad_nueva', NEW.prioridad
);
cambios_detectados := true;

-- Cambio de agente
ELSIF OLD.agente_id IS DISTINCT FROM NEW.agente_id THEN
accion_texto := 'Agente reasignado';
tipo_accion_valor := 'asignacion';

IF OLD.agente_id IS NOT NULL THEN
SELECT nombre_completo INTO agente_nombre
FROM usuarios
WHERE id = OLD.agente_id;
END IF;

detalle_json := jsonb_build_object(
'agente_anterior', COALESCE(agente_nombre, 'Sin asignar')
);

agente_nombre := NULL;
IF NEW.agente_id IS NOT NULL THEN
SELECT nombre_completo INTO agente_nombre
FROM usuarios
WHERE id = NEW.agente_id;
END IF;

detalle_json := detalle_json || jsonb_build_object(
'agente_nuevo', COALESCE(agente_nombre, 'Sin asignar')
);
cambios_detectados := true;

-- Ticket cerrado
ELSIF OLD.cerrado_en IS NULL AND NEW.cerrado_en IS NOT NULL THEN
IF NEW.cerrado_por IS NOT NULL THEN
SELECT nombre_completo INTO cerrado_por_nombre
FROM usuarios
WHERE id = NEW.cerrado_por;
END IF;

accion_texto := 'Ticket cerrado';
tipo_accion_valor := 'cierre';
detalle_json := jsonb_build_object(
'cerrado_por', COALESCE(cerrado_por_nombre, 'Desconocido'),
'fecha_cierre', NEW.cerrado_en
);
cambios_detectados := true;

-- Ticket reabierto
ELSIF OLD.cerrado_en IS NOT NULL AND NEW.cerrado_en IS NULL THEN
accion_texto := 'Ticket reabierto';
tipo_accion_valor := 'reapertura';
detalle_json := jsonb_build_object(
'fecha_reapertura', now()
);
cambios_detectados := true;

-- Cambio de póliza
ELSIF OLD.poliza IS DISTINCT FROM NEW.poliza THEN
accion_texto := 'Póliza actualizada';
tipo_accion_valor := 'modificacion';
detalle_json := jsonb_build_object(
'poliza_anterior', COALESCE(OLD.poliza, 'Sin póliza'),
'poliza_nueva', COALESCE(NEW.poliza, 'Sin póliza')
);
cambios_detectados := true;

-- Cambio de instrucciones
ELSIF OLD.instrucciones IS DISTINCT FROM NEW.instrucciones THEN
accion_texto := 'Instrucciones actualizadas';
tipo_accion_valor := 'modificacion';
detalle_json := jsonb_build_object(
'instrucciones_anterior_preview', CASE
WHEN OLD.instrucciones IS NOT NULL AND length(OLD.instrucciones) > 100 
THEN substring(OLD.instrucciones from 1 for 100) || '...'
ELSE COALESCE(OLD.instrucciones, '')
END,
'instrucciones_nueva_preview', CASE
WHEN NEW.instrucciones IS NOT NULL AND length(NEW.instrucciones) > 100 
THEN substring(NEW.instrucciones from 1 for 100) || '...'
ELSE COALESCE(NEW.instrucciones, '')
END
);
cambios_detectados := true;

-- Cambio de tipo de seguro
ELSIF OLD.tipo_seguro_id IS DISTINCT FROM NEW.tipo_seguro_id THEN
IF OLD.tipo_seguro_id IS NOT NULL THEN
SELECT nombre INTO tipo_seguro_anterior_nombre
FROM tramite_insurance_types
WHERE id = OLD.tipo_seguro_id;
END IF;

IF NEW.tipo_seguro_id IS NOT NULL THEN
SELECT nombre INTO tipo_seguro_nuevo_nombre
FROM tramite_insurance_types
WHERE id = NEW.tipo_seguro_id;
END IF;

accion_texto := 'Tipo de seguro actualizado';
tipo_accion_valor := 'modificacion';
detalle_json := jsonb_build_object(
'tipo_seguro_anterior', COALESCE(tipo_seguro_anterior_nombre, 'No especificado'),
'tipo_seguro_nuevo', COALESCE(tipo_seguro_nuevo_nombre, 'No especificado')
);
cambios_detectados := true;

-- Cambio de resultado
ELSIF OLD.resultado IS DISTINCT FROM NEW.resultado THEN
accion_texto := 'Resultado actualizado';
tipo_accion_valor := 'modificacion';
detalle_json := jsonb_build_object(
'resultado_anterior', COALESCE(OLD.resultado, 'Sin resultado'),
'resultado_nuevo', COALESCE(NEW.resultado, 'Sin resultado')
);
cambios_detectados := true;

-- Otros cambios genéricos
ELSE
accion_texto := 'Datos actualizados';
tipo_accion_valor := 'modificacion';
cambios_detectados := true;
END IF;

-- Solo insertar si hubo cambios detectados
IF cambios_detectados THEN
INSERT INTO ticket_historial (ticket_id, usuario_id, accion, detalle, tipo_accion)
VALUES (NEW.id, NEW.modificado_por, accion_texto, detalle_json, tipo_accion_valor);
END IF;
END IF;

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.log_ticket_comentario()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
usuario_nombre text;
BEGIN
SELECT nombre_completo INTO usuario_nombre
FROM usuarios
WHERE id = NEW.usuario_id;

INSERT INTO ticket_historial (ticket_id, usuario_id, accion, detalle, tipo_accion)
VALUES (
NEW.ticket_id,
NEW.usuario_id,
'Comentario agregado',
jsonb_build_object(
'usuario', usuario_nombre,
'mensaje_preview', CASE
WHEN length(NEW.mensaje) > 100 THEN substring(NEW.mensaje from 1 for 100) || '...'
ELSE NEW.mensaje
END
),
'comentario'
);

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.log_user_activity(p_user_id uuid, p_module text, p_event_type text, p_action text, p_summary text, p_entity_type text DEFAULT NULL::text, p_entity_id text DEFAULT NULL::text, p_details jsonb DEFAULT '{}'::jsonb, p_metadata jsonb DEFAULT '{}'::jsonb, p_status text DEFAULT 'success'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_user_name text;
v_email text;
v_office_id uuid;
v_office_name text;
v_role text;
v_log_id uuid;
BEGIN
-- Get user snapshot data
SELECT 
COALESCE(u.nombre_completo, u.nombre || ' ' || u.apellidos),
u.email_laboral,
u.oficina_id,
u.rol
INTO v_user_name, v_email, v_office_id, v_role
FROM usuarios u WHERE u.id = p_user_id;

-- Get office name
IF v_office_id IS NOT NULL THEN
SELECT nombre INTO v_office_name FROM oficinas WHERE id = v_office_id;
END IF;

INSERT INTO user_activity_logs (
user_id, user_name_snapshot, email_snapshot, office_id, office_name_snapshot,
role_snapshot, module, event_type, action, entity_type, entity_id,
summary, details, metadata, status
) VALUES (
p_user_id, COALESCE(v_user_name, ''), COALESCE(v_email, ''),
v_office_id, COALESCE(v_office_name, ''), COALESCE(v_role, ''),
p_module, p_event_type, p_action, p_entity_type, p_entity_id,
p_summary, p_details, p_metadata, p_status
)
RETURNING id INTO v_log_id;

RETURN v_log_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.mark_contact_messages_read(p_agent_user_id uuid, p_user_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_count int;
  v_caller uuid := auth.uid();
BEGIN
  IF v_caller IS NULL OR p_agent_user_id IS DISTINCT FROM v_caller OR p_user_id IS DISTINCT FROM v_caller THEN
    RAISE EXCEPTION 'Not authorized to mark this conversation as read' USING ERRCODE = '42501';
  END IF;
  UPDATE contact_center_messages
  SET read_at = now(), read_by_user_id = v_caller
  WHERE agent_user_id = v_caller AND direction = 'inbound' AND read_at IS NULL;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.mark_events_as_read(p_usuario_id uuid, p_event_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
UPDATE assistant_events
SET leido = true
WHERE usuario_id = p_usuario_id
AND id = ANY(p_event_ids);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.mark_report_failed(p_report_code text, p_error_message text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_next_code TEXT;
BEGIN
-- Registrar el fallo
UPDATE sicas_config
SET
report_test_history = report_test_history || jsonb_build_object(
'report_code', p_report_code,
'status', 'failed',
'error_message', p_error_message,
'tested_at', now()
)
WHERE id = (SELECT id FROM sicas_config LIMIT 1);

-- Obtener siguiente código
v_next_code := get_next_alternate_report();

-- Actualizar código actual
UPDATE sicas_config
SET current_report_code = v_next_code
WHERE id = (SELECT id FROM sicas_config LIMIT 1);

RETURN v_next_code;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.mark_report_successful(p_report_code text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
UPDATE sicas_config
SET
last_successful_report = p_report_code,
current_report_code = p_report_code,
report_test_history = report_test_history || jsonb_build_object(
'report_code', p_report_code,
'status', 'success',
'tested_at', now()
)
WHERE id = (SELECT id FROM sicas_config LIMIT 1);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.migrate_all_seguwallet_to_crm()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_count int := 0;
v_customer seguwallet_customers%ROWTYPE;
BEGIN
FOR v_customer IN
SELECT * FROM seguwallet_customers
WHERE crm_contact_id IS NULL AND deleted_at IS NULL
LOOP
PERFORM link_seguwallet_to_crm_contact(v_customer.id);
v_count := v_count + 1;
END LOOP;
RETURN v_count;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.mkt_premium_monto_periodo(p_plan text)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE p_plan
           WHEN 'anual'   THEN 2000::numeric
           WHEN 'mensual' THEN 200::numeric * 12
           ELSE 0::numeric
         END;
$function$
;

CREATE OR REPLACE FUNCTION public.mkt_premium_pagos_bitacora()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO mkt_premium_pagos_log (pago_id, usuario_id, accion, datos_despues, hecho_por)
    VALUES (NEW.id, NEW.usuario_id, 'alta', to_jsonb(NEW), auth.uid());
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    INSERT INTO mkt_premium_pagos_log (pago_id, usuario_id, accion, datos_antes, datos_despues, hecho_por)
    VALUES (NEW.id, NEW.usuario_id, 'edicion', to_jsonb(OLD), to_jsonb(NEW), auth.uid());
    RETURN NEW;
  ELSE
    INSERT INTO mkt_premium_pagos_log (pago_id, usuario_id, accion, datos_antes, hecho_por)
    VALUES (OLD.id, OLD.usuario_id, 'baja', to_jsonb(OLD), auth.uid());
    RETURN OLD;
  END IF;
END $function$
;

CREATE OR REPLACE FUNCTION public.mkt_premium_pagos_log_inmutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  RAISE EXCEPTION 'La bitácora de pagos Premium es de solo lectura: no se puede % una entrada.', lower(TG_OP);
END $function$
;

CREATE OR REPLACE FUNCTION public.mkt_puede_administrar()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (SELECT 1 FROM usuarios WHERE id = auth.uid() AND rol = 'Administrador')
      OR EXISTS (
        SELECT 1 FROM tramites_grupos_miembros m
        JOIN mkt_equipos_acceso a ON a.grupo_id = m.grupo_id
        WHERE m.usuario_id = auth.uid()
      );
$function$
;

CREATE OR REPLACE FUNCTION public.name_similarity(name1 text, name2 text)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
norm1 text;
norm2 text;
tokens1 text[];
tokens2 text[];
common_tokens int := 0;
total_tokens int;
score float;
i int;
BEGIN
-- Normalizar ambos nombres
norm1 := normalize_person_name(name1);
norm2 := normalize_person_name(name2);

-- Si son iguales después de normalizar, retornar 100
IF norm1 = norm2 THEN
RETURN 100;
END IF;

-- Si alguno está vacío, retornar 0
IF norm1 = '' OR norm2 = '' THEN
RETURN 0;
END IF;

-- Dividir en tokens (palabras)
tokens1 := string_to_array(norm1, ' ');
tokens2 := string_to_array(norm2, ' ');

-- Contar tokens en común
FOR i IN 1..array_length(tokens1, 1) LOOP
IF tokens1[i] = ANY(tokens2) THEN
common_tokens := common_tokens + 1;
END IF;
END LOOP;

-- Calcular total de tokens únicos
total_tokens := greatest(array_length(tokens1, 1), array_length(tokens2, 1));

IF total_tokens = 0 THEN
RETURN 0;
END IF;

-- Calcular score como porcentaje
score := (common_tokens::float / total_tokens::float) * 100;

RETURN floor(score)::int;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.net_http_post_wrapper(target_url text, headers_json text DEFAULT '{}'::text, body_json text DEFAULT '{}'::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'net'
AS $function$
DECLARE
request_id bigint;
BEGIN
SELECT net.http_post(
url := target_url,
headers := headers_json::jsonb,
body := body_json::jsonb
) INTO request_id;

RETURN request_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.nombre_comparable(p_texto text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT nullif(trim(regexp_replace(public.folio_normaliza(p_texto), '\s+', ' ', 'g')), '');
$function$
;

CREATE OR REPLACE FUNCTION public.normalizar_telefono_mx(telefono text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
BEGIN
-- Remover espacios, guiones y paréntesis
telefono := regexp_replace(telefono, '[^0-9]', '', 'g');

-- Si empieza con +52, remover el +
IF telefono LIKE '+52%' THEN
telefono := substring(telefono from 4);
END IF;

-- Si no empieza con 52 y tiene 10 dígitos, agregar 52
IF length(telefono) = 10 THEN
telefono := '52' || telefono;
END IF;

-- Si empieza con 1 después de 52, removerlo (formato antiguo)
IF telefono LIKE '521%' AND length(telefono) = 13 THEN
telefono := '52' || substring(telefono from 4);
END IF;

RETURN telefono;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.normalize_email(email text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
BEGIN
IF email IS NULL OR trim(email) = '' THEN
RETURN NULL;
END IF;
RETURN lower(trim(email));
END;
$function$
;

CREATE OR REPLACE FUNCTION public.normalize_name(name text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
normalized text;
BEGIN
IF name IS NULL OR trim(name) = '' THEN
RETURN NULL;
END IF;

-- Convertir a minúsculas y quitar espacios extras
normalized := lower(trim(regexp_replace(name, '\s+', ' ', 'g')));

-- Quitar acentos (transliterar)
normalized := unaccent(normalized);

RETURN normalized;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.normalize_name_for_sicas(input_name text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE result text;
BEGIN
IF input_name IS NULL THEN RETURN NULL; END IF;
result := upper(trim(input_name));
result := translate(result, 'ÁÉÍÓÚÀÈÌÒÙÄËÏÖÜÑáéíóúàèìòùäëïöüñ', 'AEIOUAEIOUAEIOUNaeiouaeiouaeioun');
result := regexp_replace(result, '\s+', ' ', 'g');
result := regexp_replace(result, '-\s*\d+\s*$', '', 'g');
result := regexp_replace(result, '-\s*(QRO|QUERETARO|TOLUCA|CDMX|MTY|GDL)\s*$', '', 'gi');
result := trim(result);
RETURN result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.normalize_name_for_usuarios()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
cleaned TEXT;
tokens TEXT[];
full_name TEXT;
BEGIN
full_name := (NEW.nombre || ' ' || NEW.apellidos);

IF full_name IS NULL OR trim(full_name) = '' THEN
NEW.name_norm := '';
NEW.name_tokens := ARRAY[]::TEXT[];
NEW.name_signature := '';
RETURN NEW;
END IF;

cleaned := lower(trim(full_name));
cleaned := regexp_replace(cleaned, '[^a-z0-9\s]', ' ', 'g');
cleaned := regexp_replace(cleaned, '\s+', ' ', 'g');

NEW.name_norm := cleaned;

tokens := string_to_array(cleaned, ' ');
tokens := array_remove(tokens, '');
NEW.name_tokens := tokens;

NEW.name_signature := array_to_string(
(SELECT array_agg(token ORDER BY token)
FROM unnest(tokens) AS token
WHERE token NOT IN ('de', 'del', 'la', 'las', 'el', 'los', 'y', 'e')),
'_'
);

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.normalize_person_name(name_input text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
normalized text;
BEGIN
IF name_input IS NULL OR trim(name_input) = '' THEN
RETURN '';
END IF;

-- Convertir a minúsculas y quitar espacios al inicio/final
normalized := lower(trim(name_input));

-- Remover acentos y diacríticos
normalized := translate(normalized,
'áéíóúàèìòùâêîôûäëïöüñç',
'aeiouaeiouaeiouaeiounç');

-- Remover títulos profesionales comunes
normalized := regexp_replace(normalized, '\b(lic|ing|dr|dra|mtro|mtra|c\.?p\.?|arq|prof)\b\.?', '', 'gi');

-- Remover símbolos y caracteres especiales (mantener solo letras, números y espacios)
normalized := regexp_replace(normalized, '[^a-z0-9\s]', '', 'g');

-- Normalizar espacios múltiples a uno solo
normalized := regexp_replace(normalized, '\s+', ' ', 'g');
normalized := trim(normalized);

RETURN normalized;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.normalize_phone_mx(p_phone text, p_log boolean DEFAULT false)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
v_clean text;
v_result text;
BEGIN
IF p_phone IS NULL OR trim(p_phone) = '' THEN
IF p_log THEN
INSERT INTO notification_phone_normalization_log (original_phone, success, error_reason)
VALUES (p_phone, false, 'Empty or null phone');
END IF;
RETURN NULL;
END IF;

-- Remover espacios, guiones, paréntesis, puntos
v_clean := regexp_replace(p_phone, '[^0-9+]', '', 'g');

-- Si empieza con +521, remover para procesar
IF v_clean LIKE '+521%' THEN
v_clean := substring(v_clean from 5);
-- Si empieza con +52, remover para procesar
ELSIF v_clean LIKE '+52%' THEN
v_clean := substring(v_clean from 4);
END IF;

-- Si empieza con 521 y tiene 13 dígitos total, remover prefijo
IF v_clean LIKE '521%' AND length(v_clean) = 13 THEN
v_clean := substring(v_clean from 4);
-- Si empieza con 52 y tiene 12 dígitos total, remover prefijo
ELSIF v_clean LIKE '52%' AND length(v_clean) = 12 THEN
v_clean := substring(v_clean from 3);
END IF;

-- Validar que tenga exactamente 10 dígitos
IF length(v_clean) != 10 OR NOT (v_clean ~ '^[0-9]{10}$') THEN
IF p_log THEN
INSERT INTO notification_phone_normalization_log (original_phone, success, error_reason)
VALUES (p_phone, false, 'Invalid format - must be 10 digits, got ' || length(v_clean) || ' digits');
END IF;
RETURN NULL;
END IF;

-- Retornar en formato para Wazzup24: 521 + 10 dígitos (SIN el símbolo +)
v_result := '521' || v_clean;

IF p_log THEN
INSERT INTO notification_phone_normalization_log (original_phone, normalized_phone, success)
VALUES (p_phone, v_result, true);
END IF;

RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.normalize_vendor_name(name_input text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
normalized text;
BEGIN
IF name_input IS NULL OR trim(name_input) = '' THEN
RETURN NULL;
END IF;

normalized := lower(trim(name_input));

-- Remover acentos
normalized := translate(normalized,
'áéíóúüñàèìòùäëïöü',
'aeiouunaeiouaeiou');

-- Normalizar espacios
normalized := regexp_replace(normalized, '\s+', ' ', 'g');

RETURN normalized;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notificar_actualizacion_tramite()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_modificador RECORD;
v_estatus_nombre TEXT;
v_campos_modificados TEXT[];
v_variables jsonb;
BEGIN
v_campos_modificados := ARRAY[]::TEXT[];

IF OLD.tipo_tramite IS DISTINCT FROM NEW.tipo_tramite THEN
v_campos_modificados := array_append(v_campos_modificados, 'Tipo de trámite');
END IF;

IF OLD.prioridad IS DISTINCT FROM NEW.prioridad THEN
v_campos_modificados := array_append(v_campos_modificados, 'Prioridad');
END IF;

IF OLD.poliza IS DISTINCT FROM NEW.poliza THEN
v_campos_modificados := array_append(v_campos_modificados, 'Póliza');
END IF;

IF OLD.instrucciones IS DISTINCT FROM NEW.instrucciones THEN
v_campos_modificados := array_append(v_campos_modificados, 'Instrucciones');
END IF;

IF OLD.assigned_to_user_id IS DISTINCT FROM NEW.assigned_to_user_id THEN
v_campos_modificados := array_append(v_campos_modificados, 'Responsable');
END IF;

IF array_length(v_campos_modificados, 1) IS NULL THEN
RETURN NEW;
END IF;

SELECT nombre_completo, rol INTO v_modificador
FROM usuarios WHERE id = NEW.modificado_por;

SELECT nombre INTO v_estatus_nombre
FROM ticket_estatus WHERE id = NEW.estatus_id;

v_variables := jsonb_build_object(
'folio',              NEW.folio,
'agente_nombre',      '',
'modificado_por',     COALESCE(v_modificador.nombre_completo, 'Sistema'),
'rol_modificador',    COALESCE(v_modificador.rol, ''),
'campos_modificados', array_to_string(v_campos_modificados, ', '),
'tipo_tramite',       COALESCE(NEW.tipo_tramite, ''),
'estatus',            COALESCE(v_estatus_nombre, 'Sin estatus'),
'instrucciones',      COALESCE(NEW.instrucciones, ''),
'url',                'https://app.movi.digital/tramites/' || NEW.id
);

PERFORM notify_tramite_recipients(
p_ticket_id       := NEW.id,
p_codigo_tipo     := 'tramite_actualizado',
p_variables       := v_variables,
p_excluir_user_id := NEW.modificado_por
);

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notificar_admin_digital_periodo_actualizado()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_destinatario_id uuid := '5c22eb53-5090-49f7-9e36-7748baee5f2c';
v_variables jsonb;
BEGIN
-- Only fire when transaction_count or total_amount_mxn changes (i.e., new data was imported)
IF (OLD.transaction_count IS NOT DISTINCT FROM NEW.transaction_count)
AND (OLD.total_amount_mxn IS NOT DISTINCT FROM NEW.total_amount_mxn) THEN
RETURN NEW;
END IF;

v_variables := jsonb_build_object(
'periodo', COALESCE(NEW.label, NEW.period_key, 'Sin periodo'),
'total_transacciones', COALESCE(NEW.transaction_count, 0)::text,
'monto_total', '$' || to_char(COALESCE(NEW.total_amount_mxn, 0), 'FM999,999,999.00') || ' MXN',
'archivo', COALESCE(NEW.file_name, 'No especificado'),
'fecha_procesamiento', to_char(now(), 'DD/MM/YYYY HH24:MI'),
'url', '/admin-digital'
);

PERFORM enviar_notificacion_transaccional(
p_codigo_tipo := 'admin_digital_batch_guardado',
p_destinatario_id := v_destinatario_id,
p_variables := v_variables
);

RETURN NEW;
END;
$function$
;

