CREATE OR REPLACE FUNCTION public.notificar_comentario_tramite()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_tramite RECORD;
v_autor RECORD;
v_variables jsonb;
BEGIN
SELECT t.id, t.folio, t.tipo_tramite, t.estatus_id, t.instrucciones,
te.nombre AS estatus_nombre
INTO v_tramite
FROM tickets t
LEFT JOIN ticket_estatus te ON te.id = t.estatus_id
WHERE t.id = NEW.ticket_id;

IF NOT FOUND THEN
RETURN NEW;
END IF;

SELECT nombre_completo, rol INTO v_autor
FROM usuarios WHERE id = NEW.usuario_id;

v_variables := jsonb_build_object(
'folio',         v_tramite.folio,
'agente_nombre', '',
'comentario',    NEW.mensaje,
'autor_nombre',  COALESCE(v_autor.nombre_completo, 'Usuario'),
'autor_rol',     COALESCE(v_autor.rol, ''),
'tipo_tramite',  COALESCE(v_tramite.tipo_tramite, ''),
'estatus',       COALESCE(v_tramite.estatus_nombre, 'Sin estatus'),
'instrucciones', COALESCE(v_tramite.instrucciones, ''),
'url',           'https://app.movi.digital/tramites/' || v_tramite.id
);

PERFORM notify_tramite_recipients(
p_ticket_id       := NEW.ticket_id,
p_codigo_tipo     := 'tramite_comentario_nuevo',
p_variables       := v_variables,
p_excluir_user_id := NEW.usuario_id
);

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notificar_documento_tramite()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_tramite         RECORD;
v_agente          RECORD;
v_subidor_nombre  TEXT;
v_subidor_rol     TEXT;
v_tamano_texto    TEXT;
v_url             TEXT;
v_recent_job      BOOLEAN;
BEGIN
-- Obtener info del trámite
SELECT t.id, t.folio, t.tipo_tramite, t.agente_id
INTO v_tramite
FROM tickets t
WHERE t.id = NEW.ticket_id;

IF NOT FOUND THEN
RETURN NEW;
END IF;

-- Solo notificar si hay un agente asignado
IF v_tramite.agente_id IS NULL THEN
RETURN NEW;
END IF;

-- Obtener info del agente
SELECT id, nombre_completo, email_laboral, celular_laboral
INTO v_agente
FROM usuarios
WHERE id = v_tramite.agente_id
AND estado = 'activo';

IF NOT FOUND THEN
RETURN NEW;
END IF;

-- No notificar si el agente es quien subió el documento
IF v_agente.id = NEW.usuario_id THEN
RETURN NEW;
END IF;

-- Guard de idempotencia: evitar spam si se suben varios docs en poco tiempo
-- Solo aplica para el mismo ticket, no para documentos diferentes
SELECT EXISTS(
SELECT 1 FROM notification_jobs
WHERE user_id = v_agente.id
AND event_code = 'tramite_documento_cargado'
AND (payload->>'ticket_id') = v_tramite.id::text
AND status IN ('pending', 'processing', 'sent')
AND created_at > NOW() - INTERVAL '2 minutes'
LIMIT 1
) INTO v_recent_job;

IF v_recent_job THEN
RAISE NOTICE '[DOC TRIGGER] Job reciente para ticket %, omitiendo duplicado', v_tramite.id;
RETURN NEW;
END IF;

-- Obtener info de quien sube el documento
SELECT
COALESCE(nombre_completo, nombre || ' ' || COALESCE(apellidos, ''), 'Usuario'),
COALESCE(rol, 'Usuario')
INTO v_subidor_nombre, v_subidor_rol
FROM usuarios
WHERE id = NEW.usuario_id;

v_subidor_nombre := COALESCE(v_subidor_nombre, 'Usuario del sistema');
v_subidor_rol    := COALESCE(v_subidor_rol, 'Usuario');

-- Formatear tamaño de archivo
IF NEW.tamano IS NOT NULL THEN
IF NEW.tamano < 1024 THEN
v_tamano_texto := NEW.tamano || ' bytes';
ELSIF NEW.tamano < 1048576 THEN
v_tamano_texto := ROUND(NEW.tamano / 1024.0, 1) || ' KB';
ELSE
v_tamano_texto := ROUND(NEW.tamano / 1048576.0, 2) || ' MB';
END IF;
ELSE
v_tamano_texto := 'Desconocido';
END IF;

v_url := '/tramites/' || v_tramite.id::text;

-- Enviar notificación (sin adjuntos durante INSERT para evitar GROUP BY issues)
BEGIN
PERFORM enviar_notificacion_transaccional(
p_codigo_tipo  := 'tramite_documento_cargado',
p_destinatario_id := v_agente.id,
p_variables    := jsonb_build_object(
'folio',          COALESCE(v_tramite.folio, 'Sin folio'),
'agente_nombre',  v_agente.nombre_completo,
'nombre_archivo', COALESCE(NEW.nombre, 'Documento'),
'subido_por',     v_subidor_nombre,
'rol_subidor',    v_subidor_rol,
'tamano_archivo', v_tamano_texto,
'tipo_tramite',   COALESCE(v_tramite.tipo_tramite, 'tramite'),
'url',            v_url,
'ticket_id',      v_tramite.id::text
),
p_adjuntos     := NULL
);

RAISE NOTICE '[DOC TRIGGER] Notificación tramite_documento_cargado enviada para agente % (ticket %)',
v_agente.id, v_tramite.id;
EXCEPTION WHEN OTHERS THEN
RAISE WARNING '[DOC TRIGGER] Error al enviar notificación para ticket %: %', v_tramite.id, SQLERRM;
END;

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notificar_equipos_nuevo_usuario()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_destinatarios uuid[];
v_destinatario uuid;
v_oficina_nombre text;
v_creador_nombre text;
v_link_usuario text;
v_datos jsonb;
v_current_user_id text;
BEGIN
IF TG_OP != 'INSERT' THEN
RETURN NEW;
END IF;

SELECT nombre INTO v_oficina_nombre
FROM oficinas
WHERE id = NEW.oficina_id;

IF v_oficina_nombre IS NULL THEN
v_oficina_nombre := 'Sin oficina asignada';
END IF;

v_creador_nombre := 'Sistema';
v_current_user_id := current_setting('app.current_user_id', true);
IF v_current_user_id IS NOT NULL AND v_current_user_id <> '' THEN
SELECT nombre_completo INTO v_creador_nombre
FROM usuarios
WHERE id = v_current_user_id::uuid;

IF v_creador_nombre IS NULL THEN
v_creador_nombre := 'Administrador';
END IF;
END IF;

v_link_usuario := 'https://app.movi.digital/usuario/' || NEW.id::text;

v_datos := jsonb_build_object(
'usuario_nombre', NEW.nombre,
'usuario_apellidos', NEW.apellidos,
'usuario_email_laboral', NEW.email_laboral,
'usuario_rol', NEW.rol,
'usuario_oficina', v_oficina_nombre,
'usuario_fecha_alta', to_char(NEW.created_at, 'DD/MM/YYYY HH24:MI'),
'creado_por', v_creador_nombre,
'link_usuario', v_link_usuario
);

SELECT ARRAY_AGG(DISTINCT usuario_id)
INTO v_destinatarios
FROM correo_destinatarios_notificacion cdn
INNER JOIN correo_tipos_notificacion ctn ON ctn.id = cdn.tipo_notificacion_id
INNER JOIN usuarios u ON u.id = cdn.usuario_id
WHERE ctn.codigo = 'nuevo_usuario_creado'
AND ctn.activo = true
AND u.estado = 'activo'
AND u.rol IN ('Empleado', 'Gerente', 'Administrador');

IF v_destinatarios IS NULL OR array_length(v_destinatarios, 1) = 0 THEN
RAISE LOG '[nuevo_usuario] No hay destinatarios configurados para nuevo_usuario_creado';
RETURN NEW;
END IF;

RAISE LOG '[nuevo_usuario] Notificando a % destinatarios sobre nuevo usuario: %', 
array_length(v_destinatarios, 1), NEW.email_laboral;

FOREACH v_destinatario IN ARRAY v_destinatarios
LOOP
BEGIN
PERFORM enviar_notificacion_completa(
p_tipo_codigo := 'nuevo_usuario_creado',
p_user_id := v_destinatario,
p_titulo := 'Nuevo usuario registrado',
p_mensaje := NEW.nombre || ' ' || NEW.apellidos || ' (' || NEW.rol || ') se ha registrado en ' || v_oficina_nombre,
p_modulo := 'usuarios',
p_datos_adicionales := v_datos,
p_accion_url := '/usuario/' || NEW.id::text
);
EXCEPTION WHEN OTHERS THEN
RAISE LOG '[nuevo_usuario] Error notificando a destinatario %: %', v_destinatario, SQLERRM;
END;
END LOOP;

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notificar_nuevo_evento()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
usuario_record RECORD;
evento_titulo text;
BEGIN
evento_titulo := NEW.titulo;

-- Obtener usuarios autorizados y enviar notificaciones
FOR usuario_record IN
SELECT usuario_id FROM obtener_usuarios_autorizados_evento(NEW.id)
LOOP
INSERT INTO notificaciones_internas (
usuario_id,
tipo,
titulo,
mensaje,
link,
leida,
creada_en
) VALUES (
usuario_record.usuario_id,
'evento',
'Nuevo evento en Aula Digital',
'Se ha programado un nuevo evento: ' || evento_titulo,
'/seguros-education/aula-digital?evento=' || NEW.id,
false,
now()
);
END LOOP;

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notify(p_event_code text, p_user_ids uuid[], p_payload jsonb DEFAULT '{}'::jsonb, p_entity_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_event record;
v_user_id uuid;
v_user record;
v_idempotency_key text;
v_job_id uuid;
v_jobs_created integer := 0;
v_jobs_skipped integer := 0;
v_users_processed integer := 0;
v_email text;
v_phone text;
v_result jsonb;
BEGIN
-- Validar que hay usuarios
IF p_user_ids IS NULL OR array_length(p_user_ids, 1) IS NULL THEN
RETURN jsonb_build_object(
'success', false,
'error', 'No users provided',
'jobs_created', 0
);
END IF;

-- Obtener configuración del evento
SELECT * INTO v_event
FROM notification_events_catalog
WHERE event_code = p_event_code AND active = true;

IF NOT FOUND THEN
RAISE WARNING 'Evento no encontrado o inactivo: %', p_event_code;
RETURN jsonb_build_object(
'success', false,
'error', 'Event not found or inactive: ' || p_event_code,
'jobs_created', 0
);
END IF;

-- Procesar cada usuario
FOREACH v_user_id IN ARRAY p_user_ids
LOOP
-- Obtener datos del usuario con nombres correctos de columnas
SELECT
id, nombre, apellidos, nombre_completo,
email_laboral, email_personal,
celular_laboral, celular_personal,
estado
INTO v_user
FROM usuarios
WHERE id = v_user_id;

IF NOT FOUND THEN
CONTINUE;
END IF;

IF v_user.estado != 'activo' THEN
CONTINUE;
END IF;

v_users_processed := v_users_processed + 1;

-- ==========================================
-- Canal: In-App (Campanita)
-- ==========================================
IF v_event.enable_in_app THEN
v_idempotency_key := p_event_code || '_' || v_user_id::text || '_in_app';

IF p_entity_id IS NOT NULL THEN
v_idempotency_key := v_idempotency_key || '_' || p_entity_id;
ELSE
v_idempotency_key := v_idempotency_key || '_' || md5(p_payload::text);
END IF;

BEGIN
INSERT INTO notification_jobs (
event_code, user_id, channel, status, payload, idempotency_key
)
VALUES (
p_event_code, v_user_id, 'in_app', 'pending', p_payload, v_idempotency_key
);

v_jobs_created := v_jobs_created + 1;
EXCEPTION WHEN unique_violation THEN
v_jobs_skipped := v_jobs_skipped + 1;
END;
END IF;

-- ==========================================
-- Canal: Email
-- ==========================================
IF v_event.enable_email THEN
v_email := COALESCE(
NULLIF(trim(v_user.email_laboral), ''),
NULLIF(trim(v_user.email_personal), '')
);

IF v_email IS NOT NULL AND v_email ~ '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$' THEN
v_idempotency_key := p_event_code || '_' || v_user_id::text || '_email';

IF p_entity_id IS NOT NULL THEN
v_idempotency_key := v_idempotency_key || '_' || p_entity_id;
ELSE
v_idempotency_key := v_idempotency_key || '_' || md5(p_payload::text);
END IF;

BEGIN
INSERT INTO notification_jobs (
event_code, user_id, channel, status, payload, idempotency_key
)
VALUES (
p_event_code, v_user_id, 'email', 'pending', p_payload, v_idempotency_key
);

v_jobs_created := v_jobs_created + 1;
EXCEPTION WHEN unique_violation THEN
v_jobs_skipped := v_jobs_skipped + 1;
END;
END IF;
END IF;

-- ==========================================
-- Canal: WhatsApp
-- ==========================================
IF v_event.enable_whatsapp THEN
v_phone := COALESCE(
normalize_phone_mx(v_user.celular_laboral),
normalize_phone_mx(v_user.celular_personal)
);

IF v_phone IS NOT NULL THEN
v_idempotency_key := p_event_code || '_' || v_user_id::text || '_whatsapp';

IF p_entity_id IS NOT NULL THEN
v_idempotency_key := v_idempotency_key || '_' || p_entity_id;
ELSE
v_idempotency_key := v_idempotency_key || '_' || md5(p_payload::text);
END IF;

BEGIN
INSERT INTO notification_jobs (
event_code, user_id, channel, status, payload, idempotency_key
)
VALUES (
p_event_code, v_user_id, 'whatsapp', 'pending', p_payload, v_idempotency_key
);

v_jobs_created := v_jobs_created + 1;
EXCEPTION WHEN unique_violation THEN
v_jobs_skipped := v_jobs_skipped + 1;
END;
END IF;
END IF;
END LOOP;

-- Retornar estadísticas
v_result := jsonb_build_object(
'success', true,
'event_code', p_event_code,
'users_provided', array_length(p_user_ids, 1),
'users_processed', v_users_processed,
'jobs_created', v_jobs_created,
'jobs_skipped', v_jobs_skipped
);

RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_admins_new_user_pending()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
admin_id uuid;
creator_name text;
new_user_name text;
notification_message text;
BEGIN
IF NEW.estado <> 'pendiente' THEN
RETURN NEW;
END IF;

new_user_name := COALESCE(NEW.nombre_completo, NEW.nombre || ' ' || NEW.apellidos);

SELECT nombre_completo INTO creator_name
FROM usuarios
WHERE id = auth.uid()
LIMIT 1;

IF creator_name IS NULL THEN
creator_name := 'Un gerente';
END IF;

notification_message := creator_name || ' ha creado un nuevo usuario que requiere activación: ' || new_user_name;

FOR admin_id IN
SELECT id
FROM usuarios
WHERE rol = 'Administrador'
AND estado = 'activo'
AND (deleted_at IS NULL OR is_deleted = false)
LOOP
INSERT INTO notificaciones (
usuario_id,
titulo,
mensaje,
modulo,
accion_url,
leida
) VALUES (
admin_id,
'Nuevo Usuario Pendiente de Activación',
notification_message,
'usuarios',
'/configuracion?tab=usuarios&highlight=' || NEW.id::text,
false
);
END LOOP;

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_agent_on_external_policy()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_customer_name  text;
v_agent_id       uuid;
v_agent_name     text;
v_insurer        text;
v_ramo           text;
v_policy_number  text;
v_payload        jsonb;
BEGIN
-- Only fire on INSERT (not updates/deletes)
IF TG_OP <> 'INSERT' THEN RETURN NEW; END IF;
-- Skip soft-deleted
IF NEW.deleted_at IS NOT NULL THEN RETURN NEW; END IF;

-- Resolve customer name and agent
SELECT sc.full_name, sc.agent_user_id
INTO v_customer_name, v_agent_id
FROM seguwallet_customers sc
WHERE sc.id = NEW.seguwallet_customer_id
LIMIT 1;

IF v_agent_id IS NULL THEN RETURN NEW; END IF;

-- Resolve agent name
SELECT COALESCE(u.nombre_completo, u.nombre, 'Agente')
INTO v_agent_name
FROM usuarios u
WHERE u.id = v_agent_id
LIMIT 1;

v_insurer       := COALESCE(NULLIF(trim(NEW.insurer_name), ''), 'Aseguradora no especificada');
v_ramo          := COALESCE(NULLIF(trim(NEW.ramo), ''), 'No especificado');
v_policy_number := COALESCE(NULLIF(trim(NEW.policy_number), ''), 'N/A');

v_payload := jsonb_build_object(
'agente_nombre',  v_agent_name,
'cliente_nombre', COALESCE(v_customer_name, 'Cliente'),
'aseguradora',    v_insurer,
'ramo',           v_ramo,
'numero_poliza',  v_policy_number,
'fecha_carga',    to_char(now() AT TIME ZONE 'America/Mexico_City', 'DD/MM/YYYY HH24:MI')
);

-- Fire notify() — creates in-app bell + WhatsApp job via notification dispatcher
PERFORM notify(
p_event_code := 'seguwallet_poliza_externa_cargada',
p_user_ids   := ARRAY[v_agent_id],
p_payload    := v_payload,
p_entity_id  := NEW.id::text
);

RETURN NEW;
EXCEPTION WHEN OTHERS THEN
-- Never block policy save
RAISE WARNING 'notify_agent_on_external_policy error: %', SQLERRM;
RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_manager_new_space_reservation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_manager_id uuid;
v_manager_name text;
v_user_name text;
v_area_name text;
v_office_name text;
v_fecha_formatted text;
BEGIN
-- Solo proceder si la reserva se crea en estado pendiente
IF NEW.estado = 'pendiente' THEN
-- Obtener el gerente de la oficina
SELECT u.id, COALESCE(u.nombre_completo, u.nombre || ' ' || u.apellidos)
INTO v_manager_id, v_manager_name
FROM usuarios u
WHERE u.oficina_id = NEW.oficina_id
AND u.rol = 'Gerente'
AND u.activo = true
AND u.is_deleted = false
LIMIT 1;

-- Si no hay gerente, no enviar notificación
IF v_manager_id IS NULL THEN
RAISE LOG '[space_reservation] No se encontró gerente activo para la oficina %', NEW.oficina_id;
RETURN NEW;
END IF;

-- Obtener datos adicionales
SELECT COALESCE(u.nombre_completo, u.nombre || ' ' || u.apellidos)
INTO v_user_name
FROM usuarios u
WHERE u.id = NEW.usuario_id;

SELECT a.nombre
INTO v_area_name
FROM areas a
WHERE a.id = NEW.area_id;

SELECT o.nombre
INTO v_office_name
FROM oficinas o
WHERE o.id = NEW.oficina_id;

-- Formatear fecha
v_fecha_formatted := to_char(NEW.fecha, 'DD/MM/YYYY');

-- Enviar notificación al gerente
PERFORM send_transactional_notification(
'space_reservation_created',
v_manager_id,
jsonb_build_object(
'manager_name', v_manager_name,
'user_name', v_user_name,
'area_name', v_area_name,
'office_name', v_office_name,
'fecha', v_fecha_formatted,
'hora_inicio', to_char(NEW.hora_inicio, 'HH24:MI'),
'hora_fin', to_char(NEW.hora_fin, 'HH24:MI'),
'notas', COALESCE(NEW.notas, 'Sin notas adicionales'),
'link_url', '/espacio-jiro'
),
'/espacio-jiro'
);

RAISE LOG '[space_reservation] Notificación enviada al gerente % para reserva %', v_manager_id, NEW.id;
END IF;

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_ticket_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_notification_title text;
v_notification_body text;
v_notification_url text;
v_target_user_id uuid;
v_changed_by_name text;
v_status_changed boolean := false;
v_reassigned boolean := false;
BEGIN
SELECT nombre_completo INTO v_changed_by_name
FROM usuarios
WHERE id = NEW.modificado_por;

v_changed_by_name := COALESCE(v_changed_by_name, 'Sistema');

v_notification_url := 'https://app.movi.digital/tramites/' || NEW.id;

IF TG_OP = 'UPDATE' THEN
IF OLD.estatus_id IS DISTINCT FROM NEW.estatus_id THEN
v_status_changed := true;
v_notification_title := 'Actualización de trámite';

DECLARE
v_new_status_name text;
BEGIN
SELECT nombre INTO v_new_status_name
FROM ticket_estatus
WHERE id = NEW.estatus_id;

v_notification_body := format('Tu trámite %s cambió a estatus: %s', NEW.folio, v_new_status_name);
END;
END IF;

IF OLD.assigned_to_user_id IS DISTINCT FROM NEW.assigned_to_user_id THEN
v_reassigned := true;
v_notification_title := 'Trámite asignado';
v_notification_body := format('Se te asignó el trámite %s', NEW.folio);

IF NEW.assigned_to_user_id IS NOT NULL AND NEW.assigned_to_user_id != NEW.modificado_por THEN
INSERT INTO notifications (
user_id,
title,
body,
link_url,
is_read
) VALUES (
NEW.assigned_to_user_id,
v_notification_title,
v_notification_body,
v_notification_url,
false
);
END IF;

IF OLD.assigned_to_user_id IS NOT NULL AND OLD.assigned_to_user_id != NEW.modificado_por THEN
INSERT INTO notifications (
user_id,
title,
body,
link_url,
is_read
) VALUES (
OLD.assigned_to_user_id,
'Trámite reasignado',
format('El trámite %s fue reasignado a otro usuario', NEW.folio),
v_notification_url,
false
);
END IF;
END IF;

IF NOT v_status_changed AND NOT v_reassigned THEN
v_notification_title := 'Tu trámite fue actualizado';
v_notification_body := format('Tu trámite %s fue actualizado por %s', NEW.folio, v_changed_by_name);
END IF;

v_target_user_id := NEW.assigned_to_user_id;

IF v_target_user_id IS NOT NULL AND v_target_user_id != NEW.modificado_por AND (v_status_changed OR (NOT v_reassigned)) THEN
INSERT INTO notifications (
user_id,
title,
body,
link_url,
is_read
) VALUES (
v_target_user_id,
v_notification_title,
v_notification_body,
v_notification_url,
false
);
END IF;
END IF;

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_ticket_created_unassigned()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tipo_label      text;
  v_agente_nombre   text;
  v_folio           text;
BEGIN
  IF TG_OP != 'INSERT' THEN RETURN NEW; END IF;

  SELECT label INTO v_tipo_label
  FROM ticket_tipos WHERE value = NEW.tipo_tramite;

  v_folio := COALESCE(NEW.folio, 'Sin folio');

  SELECT nombre_completo INTO v_agente_nombre
  FROM usuarios WHERE id = NEW.agente_id;

  -- Notificar al agente siempre que no sea quien creó el ticket
  IF NEW.agente_id IS NOT NULL AND NEW.agente_id IS DISTINCT FROM NEW.creado_por THEN
    INSERT INTO notifications (user_id, title, body, link_url, is_read)
    VALUES (
      NEW.agente_id,
      'Trámite Registrado',
      'Se registró el trámite ' || v_folio ||
        CASE WHEN v_tipo_label IS NOT NULL THEN ' — ' || v_tipo_label ELSE '' END || '.',
      '/tramites/' || NEW.id,
      false
    );
  END IF;

  -- Notificar al responsable si es distinto del creador y del agente
  IF NEW.assigned_to_user_id IS NOT NULL
     AND NEW.assigned_to_user_id IS DISTINCT FROM NEW.creado_por
     AND NEW.assigned_to_user_id IS DISTINCT FROM NEW.agente_id THEN
    INSERT INTO notifications (user_id, title, body, link_url, is_read)
    VALUES (
      NEW.assigned_to_user_id,
      'Trámite Asignado',
      'Se te asignó el trámite ' || v_folio ||
        CASE WHEN v_tipo_label IS NOT NULL THEN ' — ' || v_tipo_label ELSE '' END || '.',
      '/tramites/' || NEW.id,
      false
    );
  END IF;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_tramite_recipients(p_ticket_id uuid, p_codigo_tipo text, p_variables jsonb, p_excluir_user_id uuid DEFAULT NULL::uuid, p_adjuntos jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_t               RECORD;
  v_recipient_ids   uuid[];
  v_uid             uuid;
  v_recipient_name  text;
  v_personalized    jsonb;
BEGIN
  SELECT agente_id, assigned_to_user_id
  INTO v_t
  FROM tickets
  WHERE id = p_ticket_id;

  IF NOT FOUND THEN RETURN; END IF;

  v_recipient_ids := ARRAY[]::uuid[];

  IF v_t.agente_id IS NOT NULL THEN
    v_recipient_ids := array_append(v_recipient_ids, v_t.agente_id);
  END IF;

  IF v_t.assigned_to_user_id IS NOT NULL
     AND NOT (v_t.assigned_to_user_id = ANY(v_recipient_ids)) THEN
    v_recipient_ids := array_append(v_recipient_ids, v_t.assigned_to_user_id);
  END IF;

  FOREACH v_uid IN ARRAY v_recipient_ids LOOP
    IF p_excluir_user_id IS NOT NULL AND v_uid = p_excluir_user_id THEN
      CONTINUE;
    END IF;

    SELECT nombre_completo INTO v_recipient_name
    FROM usuarios WHERE id = v_uid;

    v_personalized := p_variables || jsonb_build_object(
      'agente_nombre', COALESCE(v_recipient_name, '')
    );

    PERFORM enviar_notificacion_transaccional(
      p_codigo_tipo     := p_codigo_tipo,
      p_destinatario_id := v_uid,
      p_variables       := v_personalized,
      p_adjuntos        := p_adjuntos
    );
  END LOOP;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_user_space_reservation_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_event_key text;
v_user_name text;
v_area_name text;
v_office_name text;
v_manager_name text;
v_fecha_formatted text;
BEGIN
-- Solo proceder si cambió el estado y es aprobada o rechazada
IF OLD.estado != NEW.estado AND NEW.estado IN ('aprobada', 'rechazada') THEN

-- Determinar el evento según el nuevo estado
IF NEW.estado = 'aprobada' THEN
v_event_key := 'space_reservation_approved';
ELSIF NEW.estado = 'rechazada' THEN
v_event_key := 'space_reservation_rejected';
END IF;

-- Obtener datos del usuario que hizo la reserva
SELECT COALESCE(u.nombre_completo, u.nombre || ' ' || u.apellidos)
INTO v_user_name
FROM usuarios u
WHERE u.id = NEW.usuario_id;

-- Obtener nombre del área
SELECT a.nombre
INTO v_area_name
FROM areas a
WHERE a.id = NEW.area_id;

-- Obtener nombre de la oficina
SELECT o.nombre
INTO v_office_name
FROM oficinas o
WHERE o.id = NEW.oficina_id;

-- Obtener nombre del gerente (asumimos que auth.uid() es el gerente que aprueba/rechaza)
SELECT COALESCE(u.nombre_completo, u.nombre || ' ' || u.apellidos)
INTO v_manager_name
FROM usuarios u
WHERE u.id = auth.uid();

-- Si no se pudo obtener el gerente del contexto, usar el gerente de la oficina
IF v_manager_name IS NULL THEN
SELECT COALESCE(u.nombre_completo, u.nombre || ' ' || u.apellidos)
INTO v_manager_name
FROM usuarios u
WHERE u.oficina_id = NEW.oficina_id
AND u.rol = 'Gerente'
AND u.activo = true
AND u.is_deleted = false
LIMIT 1;
END IF;

-- Formatear fecha
v_fecha_formatted := to_char(NEW.fecha, 'DD/MM/YYYY');

-- Enviar notificación al usuario
PERFORM send_transactional_notification(
v_event_key,
NEW.usuario_id,
jsonb_build_object(
'user_name', v_user_name,
'area_name', v_area_name,
'office_name', v_office_name,
'fecha', v_fecha_formatted,
'hora_inicio', to_char(NEW.hora_inicio, 'HH24:MI'),
'hora_fin', to_char(NEW.hora_fin, 'HH24:MI'),
'manager_name', COALESCE(v_manager_name, 'Gerencia'),
'comentarios_gerente', COALESCE(NEW.comentarios_gerente, ''),
'link_url', '/espacio-jiro'
),
'/espacio-jiro'
);

RAISE LOG '[space_reservation] Notificación % enviada al usuario % para reserva %', v_event_key, NEW.usuario_id, NEW.id;
END IF;

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_web_monitor_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_target_user_id uuid;
BEGIN
-- Only notify on SSL changes, ignore status/speed changes
IF NEW.change_type <> 'ssl' THEN
RETURN NEW;
END IF;

SELECT id INTO v_target_user_id
FROM usuarios
WHERE email_laboral = 'ccjimenez@jiro.com.mx'
AND deleted_at IS NULL
LIMIT 1;

IF v_target_user_id IS NULL THEN
RETURN NEW;
END IF;

PERFORM enviar_notificacion_transaccional(
'web_monitor_status_change',
v_target_user_id,
jsonb_build_object(
'url', NEW.url,
'change_type', NEW.change_type,
'old_status', COALESCE(NEW.old_value, 'N/A'),
'new_status', COALESCE(NEW.new_value, 'N/A')
)
);

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.obtener_estadisticas_envios(p_fecha_inicio timestamp with time zone DEFAULT NULL::timestamp with time zone, p_fecha_fin timestamp with time zone DEFAULT NULL::timestamp with time zone, p_tipo_notificacion_codigo text DEFAULT NULL::text, p_canal_envio text DEFAULT NULL::text)
 RETURNS TABLE(total_enviados bigint, total_fallidos bigint, total_pendientes bigint, por_canal jsonb, por_tipo jsonb, tasa_exito numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN QUERY
SELECT
COUNT(*) FILTER (WHERE estado = 'enviado') as total_enviados,
COUNT(*) FILTER (WHERE estado = 'fallido') as total_fallidos,
COUNT(*) FILTER (WHERE estado = 'pendiente') as total_pendientes,

-- Agrupación por canal
jsonb_object_agg(
COALESCE(canal_envio, 'sin_canal'),
COUNT(*) FILTER (WHERE canal_envio IS NOT NULL)
) FILTER (WHERE canal_envio IS NOT NULL) as por_canal,

-- Agrupación por tipo
jsonb_object_agg(
tipo_notificacion_codigo,
COUNT(*)
) as por_tipo,

-- Tasa de éxito
CASE 
WHEN COUNT(*) > 0 THEN
ROUND((COUNT(*) FILTER (WHERE estado = 'enviado')::numeric / COUNT(*)::numeric) * 100, 2)
ELSE 0
END as tasa_exito

FROM correo_historial_envios
WHERE 
(p_fecha_inicio IS NULL OR fecha_envio >= p_fecha_inicio)
AND (p_fecha_fin IS NULL OR fecha_envio <= p_fecha_fin)
AND (p_tipo_notificacion_codigo IS NULL OR tipo_notificacion_codigo = p_tipo_notificacion_codigo)
AND (p_canal_envio IS NULL OR canal_envio = p_canal_envio);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.obtener_rol_desde_jwt()
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
SELECT COALESCE(
(auth.jwt()->>'rol')::text,
(auth.jwt()->'app_metadata'->>'rol')::text,
'Agente'
);
$function$
;

CREATE OR REPLACE FUNCTION public.obtener_usuarios_autorizados_evento(evento_uuid uuid)
 RETURNS TABLE(usuario_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
RETURN QUERY
SELECT DISTINCT u.id
FROM usuarios u
WHERE EXISTS (
SELECT 1 FROM aula_eventos_permisos p
WHERE p.evento_id = evento_uuid
AND (
p.todos = true OR
p.usuario_id = u.id OR
p.rol = u.rol OR
p.oficina_id = u.oficina_id
)
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.obtener_usuarios_con_permiso_evento(evento_uuid uuid)
 RETURNS TABLE(usuario_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
-- Si el evento es visible para todos, retornar todos los usuarios
IF EXISTS (
SELECT 1 FROM aula_eventos
WHERE id = evento_uuid AND visible_para_todos = true
) THEN
RETURN QUERY
SELECT u.id
FROM usuarios u;
ELSE
-- Retornar usuarios con permisos específicos
RETURN QUERY
SELECT DISTINCT u.id
FROM usuarios u
WHERE EXISTS (
SELECT 1
FROM aula_eventos_permisos aep
WHERE aep.evento_id = evento_uuid
AND (
aep.usuario_id = u.id OR
aep.rol = u.rol OR
aep.oficina_id = u.oficina_id
)
);
END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.ocultar_chat(p_chat_id uuid, p_usuario_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
-- Verificar que el usuario sea miembro del chat
IF NOT EXISTS (
SELECT 1 FROM chat_miembros
WHERE chat_id = p_chat_id
AND usuario_id = p_usuario_id
) THEN
RAISE EXCEPTION 'Usuario no es miembro de este chat';
END IF;

-- Ocultar el chat
UPDATE chat_miembros
SET oculto = true,
oculto_at = now()
WHERE chat_id = p_chat_id
AND usuario_id = p_usuario_id;

RETURN true;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.prevent_batch_close_with_pending()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
pending_count int;
BEGIN
IF NEW.status = 'closed' AND OLD.status != 'closed' THEN
SELECT COUNT(*) INTO pending_count
FROM commission_details
WHERE batch_id = NEW.id
AND pending_assignment = true;

IF pending_count > 0 THEN
RAISE EXCEPTION 'No puedes cerrar el lote: existen % documentos sin usuario asignado. Asigna los pendientes para continuar.', pending_count;
END IF;
END IF;

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.prevent_crm_contacto_creator_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.creado_por IS DISTINCT FROM OLD.creado_por THEN
    RAISE EXCEPTION 'El creador original del contacto no puede modificarse';
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.procesar_registro_no_usuario(p_nombre text, p_apellidos text, p_email text, p_whatsapp text, p_es_agente_jiro boolean, p_oficina_id uuid, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_registro_id uuid;
v_tarea_id uuid;
v_destinatario record;
v_oficina_nombre text := 'N/A';
v_nombre_completo text;
v_es_agente_texto text;
v_descripcion_tarea text;
v_url_base text := 'https://app.movi.digital';
v_estatus_nuevo_id uuid;
BEGIN
SELECT id INTO v_estatus_nuevo_id
FROM ticket_estatus
WHERE nombre = 'Nuevo'
LIMIT 1;

IF v_estatus_nuevo_id IS NULL THEN
RAISE EXCEPTION 'No se encontró el estatus "Nuevo"';
END IF;

INSERT INTO registros_no_usuarios (
nombre,
apellidos,
email,
whatsapp,
es_agente_jiro,
oficina_id,
metadata
) VALUES (
p_nombre,
p_apellidos,
p_email,
p_whatsapp,
p_es_agente_jiro,
p_oficina_id,
p_metadata
)
RETURNING id INTO v_registro_id;

v_nombre_completo := p_nombre || ' ' || p_apellidos;
v_es_agente_texto := CASE WHEN p_es_agente_jiro THEN 'Sí' ELSE 'No' END;

IF p_oficina_id IS NOT NULL THEN
SELECT nombre INTO v_oficina_nombre
FROM oficinas
WHERE id = p_oficina_id;
END IF;

v_descripcion_tarea := format(
E'NUEVO REGISTRO DE USUARIO\n\n' ||
'Nombre: %s\n' ||
'Email: %s\n' ||
'WhatsApp: %s\n' ||
'¿Es agente de Jiro?: %s\n' ||
'Oficina: %s\n\n' ||
'Ver registro completo: %s/administrador/usuarios-pendientes',
v_nombre_completo,
p_email,
p_whatsapp,
v_es_agente_texto,
v_oficina_nombre,
v_url_base
);

IF p_es_agente_jiro AND p_oficina_id IS NOT NULL THEN
FOR v_destinatario IN (
SELECT id, nombre_completo
FROM usuarios
WHERE rol = 'Gerente'
AND oficina_id = p_oficina_id
AND estado IN ('Activo', 'Pendiente')
) LOOP
INSERT INTO tickets (
tipo_tramite,
instrucciones,
prioridad,
estatus_id,
assigned_to_user_id,
agente_id,
creado_por,
metadata
) VALUES (
'Lead – Registro MOVI',
v_descripcion_tarea,
'Alta',
v_estatus_nuevo_id,
v_destinatario.id,
v_destinatario.id,
v_destinatario.id,
jsonb_build_object(
'registro_id', v_registro_id,
'tipo', 'registro_no_usuario',
'email', p_email
)
)
RETURNING id INTO v_tarea_id;

PERFORM enviar_notificacion_completa(
'nuevo_usuario_creado',
v_destinatario.id,
jsonb_build_object(
'usuario_nombre', v_nombre_completo,
'usuario_email', p_email
)
);
END LOOP;
END IF;

FOR v_destinatario IN (
SELECT id, nombre_completo
FROM usuarios
WHERE rol = 'Administrador'
AND estado IN ('Activo', 'Pendiente')
) LOOP
INSERT INTO tickets (
tipo_tramite,
instrucciones,
prioridad,
estatus_id,
assigned_to_user_id,
agente_id,
creado_por,
metadata
) VALUES (
'Lead – Registro MOVI',
v_descripcion_tarea,
'Alta',
v_estatus_nuevo_id,
v_destinatario.id,
v_destinatario.id,
v_destinatario.id,
jsonb_build_object(
'registro_id', v_registro_id,
'tipo', 'registro_no_usuario',
'email', p_email
)
)
RETURNING id INTO v_tarea_id;

PERFORM enviar_notificacion_completa(
'nuevo_usuario_creado',
v_destinatario.id,
jsonb_build_object(
'usuario_nombre', v_nombre_completo,
'usuario_email', p_email
)
);
END LOOP;

RETURN jsonb_build_object(
'success', true,
'registro_id', v_registro_id,
'mensaje', 'Registro procesado exitosamente'
);
EXCEPTION
WHEN OTHERS THEN
RAISE EXCEPTION 'Error al procesar registro: %', SQLERRM;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.process_due_agenda_reminders()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_reminder record; v_payload jsonb; v_channel text; v_enabled boolean; v_created integer:=0; v_failed integer:=0;
BEGIN
 FOR v_reminder IN SELECT r.*,b.guest_name,b.guest_email,b.guest_phone,b.location_type,b.meeting_url,b.start_at,b.end_at,et.name AS event_name,c.user_id AS owner_id,c.timezone,COALESCE(u.nombre_publico,u.nombre_completo,u.nombre,'Asesor') AS owner_name FROM agenda_booking_reminders r JOIN agenda_bookings b ON b.id=r.booking_id AND b.status='confirmed' JOIN agenda_event_types et ON et.id=b.event_type_id JOIN agenda_calendars c ON c.id=et.calendar_id JOIN usuarios u ON u.id=c.user_id WHERE r.status='pending' AND r.scheduled_for<=now() AND b.start_at>now() ORDER BY r.scheduled_for LIMIT 100 FOR UPDATE OF r SKIP LOCKED LOOP
  BEGIN
   UPDATE agenda_booking_reminders SET status='processing',updated_at=now() WHERE id=v_reminder.id;
   v_payload:=jsonb_build_object('organizador_nombre',v_reminder.owner_name,'invitado_nombre',v_reminder.guest_name,'tipo_cita',v_reminder.event_name,'fecha',to_char(v_reminder.start_at AT TIME ZONE v_reminder.timezone,'DD/MM/YYYY'),'hora',to_char(v_reminder.start_at AT TIME ZONE v_reminder.timezone,'HH12:MI AM'),'cuando',CASE WHEN v_reminder.offset_minutes>=1440 THEN 'mañana' WHEN v_reminder.offset_minutes>=60 THEN 'en '||(v_reminder.offset_minutes/60)::text||' hora(s)' ELSE 'en '||v_reminder.offset_minutes::text||' minutos' END,'modalidad',CASE v_reminder.location_type WHEN 'jitsi' THEN 'Videollamada' WHEN 'google_meet' THEN 'Google Meet' WHEN 'phone' THEN 'Llamada telefónica' ELSE 'Presencial' END,'meeting_url',COALESCE(v_reminder.meeting_url,'https://app.movi.digital/agenda'),'url','/agenda','email',CASE WHEN v_reminder.recipient_type='guest' THEN v_reminder.guest_email ELSE NULL END,'phone',CASE WHEN v_reminder.recipient_type='guest' THEN v_reminder.guest_phone ELSE NULL END,'nombre_usuario',CASE WHEN v_reminder.recipient_type='guest' THEN v_reminder.guest_name ELSE v_reminder.owner_name END);
   FOR v_channel IN SELECT unnest(ARRAY['in_app','email','whatsapp']) LOOP
    SELECT CASE v_channel WHEN 'in_app' THEN enable_in_app WHEN 'email' THEN enable_email ELSE enable_whatsapp END INTO v_enabled FROM notification_events_catalog WHERE event_code=v_reminder.event_code AND active;
    IF COALESCE(v_enabled,false) AND NOT(v_reminder.recipient_type='guest' AND v_channel='in_app') AND NOT(v_reminder.recipient_type='guest' AND v_channel='email' AND COALESCE(v_reminder.guest_email,'')='') AND NOT(v_reminder.recipient_type='guest' AND v_channel='whatsapp' AND COALESCE(v_reminder.guest_phone,'')='') THEN
     INSERT INTO notification_jobs(event_code,user_id,channel,status,payload,idempotency_key,attempt_count,max_attempts) VALUES(v_reminder.event_code,v_reminder.owner_id,v_channel,'pending',v_payload,'agenda_'||v_reminder.booking_id::text||'_'||v_reminder.recipient_type||'_'||v_reminder.offset_minutes::text||'_'||v_channel,0,3) ON CONFLICT(idempotency_key) DO NOTHING;
     v_created:=v_created+1;
    END IF;
   END LOOP;
   UPDATE agenda_booking_reminders SET status='queued',processed_at=now(),updated_at=now() WHERE id=v_reminder.id;
  EXCEPTION WHEN OTHERS THEN UPDATE agenda_booking_reminders SET status='failed',last_error=SQLERRM,updated_at=now() WHERE id=v_reminder.id; v_failed:=v_failed+1; END;
 END LOOP;
 RETURN jsonb_build_object('success',true,'jobs_created',v_created,'failed',v_failed);
END;$function$
;

CREATE OR REPLACE FUNCTION public.process_in_app_notifications()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_job record;
v_event record;
v_tipo record;
v_template jsonb;
v_titulo text;
v_mensaje text;
v_url text;
v_key text;
v_value text;
v_processed integer := 0;
v_failed integer := 0;
BEGIN
FOR v_job IN
SELECT *
FROM notification_jobs
WHERE status = 'pending'
AND channel = 'in_app'
ORDER BY created_at ASC
LIMIT 50
LOOP
BEGIN
UPDATE notification_jobs
SET status = 'processing', updated_at = NOW()
WHERE id = v_job.id;

SELECT * INTO v_event
FROM notification_events_catalog
WHERE event_code = v_job.event_code
AND active = true;

IF FOUND THEN
v_template := v_event.template_in_app;

v_titulo := COALESCE(
v_template->>'titulo',
v_template->>'title',
'Notificacion'
);

v_mensaje := COALESCE(
v_template->>'mensaje',
v_template->>'message',
''
);

v_url := COALESCE(
v_template->>'accion_url',
v_job.payload->>'url',
'/dashboard'
);
ELSE
-- Fallback: catalogo editable desde Admin > Notificaciones Transaccionales
SELECT ctn.id, cp.notificacion_titulo, cp.notificacion_cuerpo
INTO v_tipo
FROM correo_tipos_notificacion ctn
LEFT JOIN correo_plantillas cp
ON cp.tipo_notificacion_id = ctn.id AND cp.es_plantilla_default = true
WHERE ctn.codigo = v_job.event_code
AND ctn.activo = true
AND COALESCE(ctn.enviar_notificacion, true) = true;

IF NOT FOUND OR (v_tipo.notificacion_titulo IS NULL AND v_tipo.notificacion_cuerpo IS NULL) THEN
RAISE EXCEPTION 'Evento no encontrado o inactivo: %', v_job.event_code;
END IF;

v_titulo := COALESCE(v_tipo.notificacion_titulo, 'Notificacion');
v_mensaje := COALESCE(v_tipo.notificacion_cuerpo, '');
v_url := COALESCE(v_job.payload->>'url', '/dashboard');
END IF;

FOR v_key, v_value IN
SELECT key, value #>> '{}'
FROM jsonb_each(v_job.payload)
LOOP
v_titulo  := replace(v_titulo,  '{{' || v_key || '}}', COALESCE(v_value, ''));
v_mensaje := replace(v_mensaje, '{{' || v_key || '}}', COALESCE(v_value, ''));
v_url     := replace(v_url,     '{{' || v_key || '}}', COALESCE(v_value, ''));
END LOOP;

-- Safety net: ensure URL is absolute
v_url := ensure_absolute_url(v_url);

INSERT INTO notificaciones (
usuario_id,
tipo,
titulo,
mensaje,
url,
accion_url,
leida,
tipo_codigo
) VALUES (
v_job.user_id,
v_job.event_code,
v_titulo,
v_mensaje,
v_url,
v_url,
false,
v_job.event_code
);

UPDATE notification_jobs
SET
status = 'sent',
sent_at = NOW(),
updated_at = NOW()
WHERE id = v_job.id;

v_processed := v_processed + 1;

EXCEPTION WHEN OTHERS THEN
UPDATE notification_jobs
SET
status = 'failed',
last_error = SQLERRM,
attempt_count = attempt_count + 1,
updated_at = NOW()
WHERE id = v_job.id;

v_failed := v_failed + 1;

RAISE WARNING 'Error procesando job %: %', v_job.id, SQLERRM;
END;
END LOOP;

RETURN jsonb_build_object(
'success', true,
'processed', v_processed,
'failed', v_failed
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.promote_crm_contact_to_cliente(p_crm_contact_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
IF p_crm_contact_id IS NULL THEN RETURN; END IF;
UPDATE crm_contactos
SET estatus = 'Cliente',
actualizado_en = now(),
fecha_conversion_cliente = COALESCE(fecha_conversion_cliente, now())
WHERE id = p_crm_contact_id
AND estatus = 'Prospecto';
END;
$function$
;

CREATE OR REPLACE FUNCTION public.provision_all_shared_links()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_user_id uuid;
v_total integer := 0;
v_user_count integer;
BEGIN
FOR v_user_id IN
SELECT id FROM usuarios
WHERE activo = true
AND deleted_at IS NULL
AND web_slug IS NOT NULL
AND web_slug != ''
LOOP
SELECT provision_shared_links_for_user(v_user_id) INTO v_user_count;
v_total := v_total + v_user_count;
END LOOP;

RETURN v_total;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.provision_insurer_folders()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_folder_id uuid;
v_created   integer := 0;
v_skipped   integer := 0;

-- Top-level insurer folders: (nombre, descripcion)
v_insurers text[][] := ARRAY[
ARRAY['ANA Seguros',       'Documentos de ANA Seguros'],
ARRAY['GNP Seguros',       'Documentos de GNP Seguros'],
ARRAY['AXA Seguros',       'Documentos de AXA Seguros'],
ARRAY['HDI Seguros',       'Documentos de HDI Seguros'],
ARRAY['Quálitas',          'Documentos de Quálitas'],
ARRAY['Mapfre',            'Documentos de Mapfre Seguros'],
ARRAY['MetLife',           'Documentos de MetLife'],
ARRAY['Chubb',             'Documentos de Chubb'],
ARRAY['Banorte Seguros',   'Documentos de Banorte Seguros'],
ARRAY['SURA',              'Documentos de SURA Seguros'],
ARRAY['Zurich',            'Documentos de Zurich Seguros'],
ARRAY['Afirme',            'Documentos de Afirme Seguros'],
ARRAY['Inbursa',           'Documentos de Inbursa Seguros'],
ARRAY['Allianz',           'Documentos de Allianz Seguros'],
ARRAY['Atlas',             'Documentos de Seguros Atlas'],
ARRAY['BUPA',              'Documentos de BUPA'],
ARRAY['BX+',               'Documentos de BX+']
];

-- Sub-folders per insurer: ramo names
v_ramos text[] := ARRAY[
'Autos', 'GMM', 'Vida', 'Daños', 'Camiones', 'Empresarial',
'Condiciones Generales', 'Formatos', 'Guías', 'Fianzas'
];

-- Regulatory folders
v_reg_ramos text[] := ARRAY['Leyes', 'CNSF', 'CONDUSEF', 'CUSF'];

v_insurer text[];
v_ramo    text;
v_reg     text;
BEGIN
-- Create insurer top-level folders + sub-ramo folders
FOREACH v_insurer SLICE 1 IN ARRAY v_insurers LOOP
-- Top-level insurer folder
SELECT id INTO v_folder_id
FROM centro_digital_carpetas
WHERE nombre = v_insurer[1] AND activa = true
LIMIT 1;

IF v_folder_id IS NULL THEN
INSERT INTO centro_digital_carpetas (
nombre, descripcion, todas_oficinas, todos_roles,
enable_chava_ai, external_chava_access, auto_index, knowledge_priority,
activa
) VALUES (
v_insurer[1], v_insurer[2], true, true,
true, true, true, 2,
true
) RETURNING id INTO v_folder_id;
v_created := v_created + 1;
ELSE
v_skipped := v_skipped + 1;
END IF;
END LOOP;

-- Create Regulación folder + sub-folders
SELECT id INTO v_folder_id
FROM centro_digital_carpetas
WHERE nombre = 'Regulación' AND activa = true
LIMIT 1;

IF v_folder_id IS NULL THEN
INSERT INTO centro_digital_carpetas (
nombre, descripcion, todas_oficinas, todos_roles,
enable_chava_ai, external_chava_access, auto_index, knowledge_priority,
activa
) VALUES (
'Regulación', 'Marco legal y normativo del sector asegurador',
true, true, true, true, true, 3, true
) RETURNING id INTO v_folder_id;
v_created := v_created + 1;
ELSE
v_skipped := v_skipped + 1;
END IF;

-- Recursos para Agentes
IF NOT EXISTS (
SELECT 1 FROM centro_digital_carpetas WHERE nombre = 'Recursos para Agentes' AND activa = true
) THEN
INSERT INTO centro_digital_carpetas (
nombre, descripcion, todas_oficinas, todos_roles,
enable_chava_ai, external_chava_access, auto_index, knowledge_priority,
activa
) VALUES (
'Recursos para Agentes',
'Materiales de apoyo, guías y recursos para agentes de seguros',
true, true, true, true, true, 2, true
);
v_created := v_created + 1;
ELSE
v_skipped := v_skipped + 1;
END IF;

RETURN jsonb_build_object(
'success', true,
'carpetas_creadas', v_created,
'carpetas_existentes', v_skipped
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.provision_shared_links_for_user(p_user_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_agent_slug text;
v_office_id uuid;
v_template record;
v_form_slug text;
v_code text;
v_full_slug text;
v_count integer := 0;
v_attempts integer;
BEGIN
-- Get user info
SELECT web_slug, oficina_id INTO v_agent_slug, v_office_id
FROM usuarios
WHERE id = p_user_id AND activo = true AND deleted_at IS NULL;

IF v_agent_slug IS NULL OR v_agent_slug = '' THEN
v_agent_slug := derive_agent_slug(p_user_id);
END IF;

-- Loop through all active templates that this user doesn't have a link for
FOR v_template IN
SELECT qft.id, qft.form_type, qft.title
FROM quote_form_templates qft
WHERE qft.is_active = true
AND NOT EXISTS (
SELECT 1 FROM shared_quote_form_links sqfl
WHERE sqfl.agent_id = p_user_id
AND sqfl.quote_form_template_id = qft.id
AND sqfl.status = 'active'
)
LOOP
v_form_slug := form_type_to_slug(v_template.form_type);

-- Generate unique slug (retry up to 5 times)
v_attempts := 0;
LOOP
v_code := generate_link_code(7);
v_full_slug := v_agent_slug || '-' || v_form_slug || '-' || v_code;

-- Check uniqueness
IF NOT EXISTS (SELECT 1 FROM shared_quote_form_links WHERE slug = v_full_slug) THEN
EXIT;
END IF;

v_attempts := v_attempts + 1;
IF v_attempts >= 5 THEN
-- Use longer code as fallback
v_code := generate_link_code(10);
v_full_slug := v_agent_slug || '-' || v_form_slug || '-' || v_code;
EXIT;
END IF;
END LOOP;

-- Insert the shared link
INSERT INTO shared_quote_form_links (
created_by, agent_id, agent_slug, office_id,
quote_form_template_id, form_type, form_slug,
form_title, unique_code, slug, public_url, status
) VALUES (
p_user_id, p_user_id, v_agent_slug, v_office_id,
v_template.id, v_template.form_type, v_form_slug,
v_template.title, v_code, v_full_slug,
'https://agentedeseguros.website/cotizar/' || v_full_slug,
'active'
)
ON CONFLICT (slug) DO NOTHING;

v_count := v_count + 1;
END LOOP;

RETURN v_count;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.puede_acceder_tipo_tramite(p_tipo_id uuid, p_user_id uuid, p_accion text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE
  v_rol         text;
  v_override    boolean;
  v_equipo_val  boolean;
  v_rol_config  boolean;
BEGIN
  -- Obtener rol global
  SELECT rol INTO v_rol FROM public.usuarios WHERE id = p_user_id LIMIT 1;

  -- 1. Admin y Gerente siempre pueden
  IF v_rol IN ('Administrador', 'Gerente') THEN
    RETURN true;
  END IF;

  -- 2. Override por usuario
  IF p_accion = 'ver' THEN
    SELECT puede_ver   INTO v_override FROM public.tramite_tipo_usuario_override
    WHERE tramite_tipo_id = p_tipo_id AND user_id = p_user_id LIMIT 1;
  ELSIF p_accion = 'crear' THEN
    SELECT puede_crear INTO v_override FROM public.tramite_tipo_usuario_override
    WHERE tramite_tipo_id = p_tipo_id AND user_id = p_user_id LIMIT 1;
  ELSE
    SELECT puede_editar INTO v_override FROM public.tramite_tipo_usuario_override
    WHERE tramite_tipo_id = p_tipo_id AND user_id = p_user_id LIMIT 1;
  END IF;
  IF v_override IS NOT NULL THEN RETURN v_override; END IF;

  -- 3. Override por equipo (toma el equipo con mayor permiso entre los del usuario)
  IF p_accion = 'ver' THEN
    SELECT bool_or(tp.puede_ver) INTO v_equipo_val
    FROM   public.tramites_grupos_miembros gm
    JOIN   public.tramite_equipo_tipo_permisos tp
           ON tp.equipo_id = gm.grupo_id AND tp.tramite_tipo_id = p_tipo_id
    WHERE  gm.usuario_id = p_user_id
      AND  tp.puede_ver IS NOT NULL;
  ELSIF p_accion = 'crear' THEN
    SELECT bool_or(tp.puede_crear) INTO v_equipo_val
    FROM   public.tramites_grupos_miembros gm
    JOIN   public.tramite_equipo_tipo_permisos tp
           ON tp.equipo_id = gm.grupo_id AND tp.tramite_tipo_id = p_tipo_id
    WHERE  gm.usuario_id = p_user_id
      AND  tp.puede_crear IS NOT NULL;
  ELSE
    SELECT bool_or(tp.puede_editar) INTO v_equipo_val
    FROM   public.tramites_grupos_miembros gm
    JOIN   public.tramite_equipo_tipo_permisos tp
           ON tp.equipo_id = gm.grupo_id AND tp.tramite_tipo_id = p_tipo_id
    WHERE  gm.usuario_id = p_user_id
      AND  tp.puede_editar IS NOT NULL;
  END IF;
  IF v_equipo_val IS NOT NULL THEN RETURN v_equipo_val; END IF;

  -- 4. Config por rol
  IF p_accion = 'ver' THEN
    SELECT puede_ver    INTO v_rol_config FROM public.tramite_tipo_rol_permisos
    WHERE tramite_tipo_id = p_tipo_id AND rol = v_rol LIMIT 1;
  ELSIF p_accion = 'crear' THEN
    SELECT puede_crear  INTO v_rol_config FROM public.tramite_tipo_rol_permisos
    WHERE tramite_tipo_id = p_tipo_id AND rol = v_rol LIMIT 1;
  ELSE
    SELECT puede_editar INTO v_rol_config FROM public.tramite_tipo_rol_permisos
    WHERE tramite_tipo_id = p_tipo_id AND rol = v_rol LIMIT 1;
  END IF;

  -- 5. Default true
  RETURN COALESCE(v_rol_config, true);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.puede_ver_comunicado(p_comunicado_id uuid, p_usuario_id uuid DEFAULT auth.uid())
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_usuario_rol TEXT;
v_usuario_oficina UUID;
v_comunicado_oficina_origen UUID;
v_publicado BOOLEAN;
v_fecha_publicacion TIMESTAMPTZ;
BEGIN
-- Obtener datos del usuario
SELECT rol, oficina_id INTO v_usuario_rol, v_usuario_oficina
FROM usuarios
WHERE id = p_usuario_id;

-- Obtener datos del comunicado
SELECT oficina_origen_id, publicado, fecha_publicacion
INTO v_comunicado_oficina_origen, v_publicado, v_fecha_publicacion
FROM comunicados_publicaciones
WHERE id = p_comunicado_id;

-- Verificar que el comunicado está publicado
IF NOT v_publicado OR v_fecha_publicacion > now() THEN
-- Solo administradores pueden ver comunicados no publicados
IF v_usuario_rol = 'Administrador' THEN
RETURN TRUE;
END IF;
RETURN FALSE;
END IF;

-- Administradores siempre pueden ver todos
IF v_usuario_rol = 'Administrador' THEN
RETURN TRUE;
END IF;

-- Comunicados de administradores (sin oficina_origen)
IF v_comunicado_oficina_origen IS NULL THEN
-- Verificar visibilidad configurada
RETURN EXISTS (
SELECT 1 FROM comunicados_visibilidad cv
WHERE cv.comunicado_id = p_comunicado_id
AND (
cv.para_todos = true
OR cv.usuario_id = p_usuario_id
OR cv.rol = v_usuario_rol
OR cv.oficina_id = v_usuario_oficina
)
);
END IF;

-- Comunicados de gerentes (con oficina_origen)
-- Solo visible para usuarios de esa oficina según roles configurados
IF v_usuario_oficina = v_comunicado_oficina_origen THEN
RETURN EXISTS (
SELECT 1 FROM comunicados_visibilidad cv
WHERE cv.comunicado_id = p_comunicado_id
AND cv.oficina_id = v_comunicado_oficina_origen
AND (
cv.rol = v_usuario_rol
OR cv.usuario_id = p_usuario_id
)
);
END IF;

RETURN FALSE;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.purgar_huerfanos_auth(p_minutos_minimos integer DEFAULT 60)
 RETURNS TABLE(id uuid, correo text, creada timestamp with time zone, resultado text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  c record;
  v_refs bigint;
BEGIN
  FOR c IN
    SELECT au.id, au.email, au.created_at
    FROM auth.users au
    LEFT JOIN public.usuarios u ON u.id = au.id
    WHERE u.id IS NULL
      AND au.created_at < now() - make_interval(mins => greatest(p_minutos_minimos, 1))
  LOOP
    SELECT count(*) INTO v_refs FROM public.referencias_de_cuenta(c.id);

    id := c.id; correo := c.email; creada := c.created_at;

    IF v_refs > 0 THEN
      -- Es de alguien: un cliente de SeguWallet, un usuario de Chava, o tiene
      -- pedidos/eventos colgando que se irían en cascada.
      resultado := 'conservada (' || v_refs || ' referencia(s))';
    ELSE
      DELETE FROM auth.users WHERE auth.users.id = c.id;
      resultado := 'borrada';
    END IF;

    RETURN NEXT;
  END LOOP;
END $function$
;

CREATE OR REPLACE FUNCTION public.qualitas_catalog_is_loaded()
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.multi_autos_catalogo_vehiculos
    WHERE catalog_source = 'qualitas_official' AND active = true
  );
$function$
;

CREATE OR REPLACE FUNCTION public.quien_ocupa_correo(p_email text)
 RETURNS TABLE(user_id uuid, nombre text, apellidos text, rol text, visible boolean, motivo text, eliminado_en timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    au.id,
    u.nombre,
    u.apellidos,
    u.rol,
    coalesce(u.is_deleted = false AND u.estado <> 'eliminado', false) AS visible,
    CASE
      WHEN u.id IS NULL           THEN 'huerfano_auth'
      WHEN u.is_deleted           THEN 'eliminado'
      WHEN u.estado = 'eliminado' THEN 'eliminado'
      ELSE 'activo'
    END,
    u.deleted_at
  FROM auth.users au
  LEFT JOIN public.usuarios u ON u.id = au.id
  WHERE lower(au.email) = lower(trim(p_email))
  LIMIT 1;
$function$
;

CREATE OR REPLACE FUNCTION public.reasignar_y_eliminar_rol(p_origen uuid, p_destino uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_origen  roles%ROWTYPE;
  v_destino roles%ROWTYPE;
  v_usuarios_origen int;
  v_admins_restantes int;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM usuarios u WHERE u.id = auth.uid() AND u.rol = 'Administrador') THEN
    RAISE EXCEPTION 'Solo un Administrador puede eliminar o fusionar roles.';
  END IF;

  SELECT * INTO v_origen FROM roles WHERE id = p_origen;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'El rol a eliminar no existe.';
  END IF;

  IF p_destino IS NOT NULL THEN
    IF p_destino = p_origen THEN
      RAISE EXCEPTION 'El rol destino no puede ser el mismo que el origen.';
    END IF;
    SELECT * INTO v_destino FROM roles WHERE id = p_destino;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'El rol destino no existe.';
    END IF;
  END IF;

  SELECT count(*) INTO v_usuarios_origen FROM usuarios WHERE rol_id = p_origen;

  IF v_usuarios_origen > 0 AND p_destino IS NULL THEN
    RAISE EXCEPTION 'El rol tiene % usuario(s). Debes indicar a qué rol reasignarlos.', v_usuarios_origen;
  END IF;

  -- Admins que quedarían tras la operación (base Administrador).
  SELECT count(*) INTO v_admins_restantes
    FROM usuarios u
   WHERE (
     (u.rol_id IS DISTINCT FROM p_origen AND u.rol = 'Administrador')
     OR (u.rol_id = p_origen AND p_destino IS NOT NULL AND v_destino.rol_base = 'Administrador')
   );

  IF v_admins_restantes = 0 THEN
    RAISE EXCEPTION 'La operación dejaría la plataforma sin administradores. Reasigna a un rol de base Administrador o cancela.';
  END IF;

  IF p_destino IS NOT NULL THEN
    UPDATE usuarios
       SET rol = v_destino.rol_base, rol_id = p_destino
     WHERE rol_id = p_origen;
  END IF;

  DELETE FROM module_visibility WHERE target_type = 'rol_id' AND target_value = p_origen::text;

  DELETE FROM roles WHERE id = p_origen;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.reassign_user_documents(p_batch_id uuid, p_old_user_id uuid, p_new_user_id uuid, p_save_mapping boolean DEFAULT true)
 RETURNS TABLE(updated_count integer, mapping_saved boolean, error text)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_updated_count INTEGER := 0;
v_mapping_saved BOOLEAN := false;
v_vendor_names TEXT[];
v_vendor_emails TEXT[];
BEGIN
-- Validar que existan documentos
IF NOT EXISTS (
SELECT 1 FROM imported_documents
WHERE batch_id = p_batch_id
AND movi_user_id = p_old_user_id
AND is_unmatched = false
) THEN
RETURN QUERY SELECT 0, false, 'No se encontraron documentos para este usuario'::TEXT;
RETURN;
END IF;

-- Obtener todos los nombres y emails únicos
SELECT
ARRAY_AGG(DISTINCT vendor_name_raw),
ARRAY_AGG(DISTINCT vendor_email_raw)
INTO v_vendor_names, v_vendor_emails
FROM imported_documents
WHERE batch_id = p_batch_id
AND movi_user_id = p_old_user_id
AND is_unmatched = false
AND (vendor_name_raw IS NOT NULL OR vendor_email_raw IS NOT NULL);

-- Actualizar todos los documentos del usuario
UPDATE imported_documents
SET
movi_user_id = p_new_user_id,
match_method = 'manual',
updated_at = now()
WHERE batch_id = p_batch_id
AND movi_user_id = p_old_user_id
AND is_unmatched = false;

GET DIAGNOSTICS v_updated_count = ROW_COUNT;

-- Guardar mapeos si se solicita
IF p_save_mapping THEN
-- Mapeos por nombre
IF v_vendor_names IS NOT NULL THEN
DECLARE
v_name TEXT;
v_name_norm TEXT;
BEGIN
FOREACH v_name IN ARRAY v_vendor_names
LOOP
IF v_name IS NOT NULL AND v_name != '' THEN
-- Normalizar nombre (mismo proceso que en la importación)
v_name_norm := LOWER(TRIM(REGEXP_REPLACE(v_name, '\s+', ' ', 'g')));

INSERT INTO vendor_mappings (
source_type,
source_value,
movi_user_id,
status,
created_by,
updated_by,
source_raw_examples
)
VALUES (
'name',
v_name_norm,
p_new_user_id,
'active',
auth.uid(),
auth.uid(),
jsonb_build_array(jsonb_build_object('name', v_name))
)
ON CONFLICT (source_type, source_value)
DO UPDATE SET
movi_user_id = p_new_user_id,
updated_by = auth.uid(),
updated_at = now(),
status = 'active';

v_mapping_saved := true;
END IF;
END LOOP;
END;
END IF;

-- Mapeos por email
IF v_vendor_emails IS NOT NULL THEN
DECLARE
v_email TEXT;
BEGIN
FOREACH v_email IN ARRAY v_vendor_emails
LOOP
IF v_email IS NOT NULL AND v_email != '' THEN
INSERT INTO vendor_mappings (
source_type,
source_value,
movi_user_id,
status,
created_by,
updated_by,
source_raw_examples
)
VALUES (
'email',
LOWER(TRIM(v_email)),
p_new_user_id,
'active',
auth.uid(),
auth.uid(),
jsonb_build_array(jsonb_build_object('email', v_email))
)
ON CONFLICT (source_type, source_value)
DO UPDATE SET
movi_user_id = p_new_user_id,
updated_by = auth.uid(),
updated_at = now(),
status = 'active';

v_mapping_saved := true;
END IF;
END LOOP;
END;
END IF;
END IF;

-- Actualizar contadores del batch
PERFORM update_batch_counters(p_batch_id);

RETURN QUERY SELECT v_updated_count, v_mapping_saved, NULL::TEXT;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.recalculate_all_commission_batches()
 RETURNS TABLE(batch_id uuid, usuario_id uuid, usuario_nombre text, regimen_fiscal_anterior text, regimen_fiscal_nuevo text, total_neto_anterior numeric, total_neto_nuevo numeric, success boolean, error_message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_batch record;
v_result jsonb;
v_old_regime text;
v_old_total numeric;
BEGIN
FOR v_batch IN
SELECT 
cb.id,
cb.usuario_id,
u.nombre || ' ' || u.apellidos as nombre_completo,
cb.regimen_fiscal as old_regime,
cb.total_neto as old_total
FROM commission_batches cb
JOIN usuarios u ON u.id = cb.usuario_id
WHERE cb.created_at > NOW() - INTERVAL '30 days'
ORDER BY cb.created_at DESC
LOOP
v_old_regime := v_batch.old_regime;
v_old_total := v_batch.old_total;

BEGIN
-- Ejecutar recálculo
SELECT calculate_batch_fiscal_aggregates(v_batch.id) INTO v_result;

-- Si fue exitoso, retornar el resultado
IF (v_result->>'success')::boolean THEN
batch_id := v_batch.id;
usuario_id := v_batch.usuario_id;
usuario_nombre := v_batch.nombre_completo;
regimen_fiscal_anterior := v_old_regime;
regimen_fiscal_nuevo := v_result->>'regimen_fiscal';
total_neto_anterior := v_old_total;
total_neto_nuevo := (v_result->>'total_neto')::numeric;
success := true;
error_message := NULL;
RETURN NEXT;
ELSE
batch_id := v_batch.id;
usuario_id := v_batch.usuario_id;
usuario_nombre := v_batch.nombre_completo;
regimen_fiscal_anterior := v_old_regime;
regimen_fiscal_nuevo := NULL;
total_neto_anterior := v_old_total;
total_neto_nuevo := NULL;
success := false;
error_message := v_result->>'error';
RETURN NEXT;
END IF;

EXCEPTION WHEN OTHERS THEN
batch_id := v_batch.id;
usuario_id := v_batch.usuario_id;
usuario_nombre := v_batch.nombre_completo;
regimen_fiscal_anterior := v_old_regime;
regimen_fiscal_nuevo := NULL;
total_neto_anterior := v_old_total;
total_neto_nuevo := NULL;
success := false;
error_message := SQLERRM;
RETURN NEXT;
END;
END LOOP;

RETURN;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.recalculate_batch_fiscal_values(p_batch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_usuario_id UUID;
v_regimen_fiscal TEXT;
v_commission_vida NUMERIC;
v_commission_sinvida NUMERIC;
v_commission_total NUMERIC;
v_iva NUMERIC := 0;
v_ret_isr NUMERIC := 0;
v_ret_iva NUMERIC := 0;
v_retencion_contable NUMERIC := 0;
v_costo_dispersion NUMERIC := 0;
v_total_neto NUMERIC := 0;
v_isr_vida NUMERIC := 0;
v_isr_danios NUMERIC := 0;
v_fiscal_regime RECORD;
BEGIN
-- Obtener el usuario del lote (debe ser único)
SELECT DISTINCT cd.usuario_id INTO v_usuario_id
FROM commission_details cd
WHERE cd.batch_id = p_batch_id
LIMIT 1;

IF v_usuario_id IS NULL THEN
RAISE EXCEPTION 'No se encontró usuario para el lote %', p_batch_id;
END IF;

-- Verificar que todos los details tengan el mismo usuario
IF EXISTS (
SELECT 1 FROM commission_details
WHERE batch_id = p_batch_id
AND usuario_id != v_usuario_id
) THEN
RAISE EXCEPTION 'El lote % tiene múltiples usuarios. Debe separarse primero.', p_batch_id;
END IF;

-- Obtener régimen fiscal del usuario (normalizado a mayúsculas)
SELECT 
UPPER(COALESCE(cfr.name, 'HONORARIOS')) as regime_name,
cfr.iva_trasladado,
cfr.iva_retenido,
cfr.isr
INTO v_fiscal_regime
FROM usuarios u
LEFT JOIN commission_fiscal_regimes cfr ON cfr.id = u.regimen_fiscal_id
WHERE u.id = v_usuario_id;

v_regimen_fiscal := v_fiscal_regime.regime_name;

-- Calcular totales por tipo de ramo
SELECT 
COALESCE(SUM(CASE WHEN tipo_ramo = 'VIDA' THEN commission_neta ELSE 0 END), 0),
COALESCE(SUM(CASE WHEN tipo_ramo != 'VIDA' THEN commission_neta ELSE 0 END), 0),
COALESCE(SUM(commission_neta), 0)
INTO v_commission_vida, v_commission_sinvida, v_commission_total
FROM commission_details
WHERE batch_id = p_batch_id;

-- Calcular según régimen fiscal
IF v_regimen_fiscal = 'ASIMILADOS' THEN
-- Asimilados: tiene retención contable y costo de dispersión
v_retencion_contable := v_commission_vida * 0.01;
v_costo_dispersion := (v_commission_vida - v_retencion_contable) * 0.09;
v_isr_vida := ((v_commission_vida - v_retencion_contable - v_costo_dispersion) * v_fiscal_regime.isr) / 1.09;
v_isr_danios := (v_commission_sinvida * v_fiscal_regime.isr) / 1.09;
v_ret_isr := v_isr_vida + v_isr_danios;
v_total_neto := v_commission_total - v_retencion_contable - v_costo_dispersion - v_ret_isr;

ELSIF v_regimen_fiscal = 'RESICO' THEN
-- RESICO
v_iva := v_commission_total * v_fiscal_regime.iva_trasladado;
v_ret_isr := (v_commission_total + v_iva) * v_fiscal_regime.isr;
v_ret_iva := v_iva * v_fiscal_regime.iva_retenido;
v_total_neto := v_commission_total + v_iva - v_ret_isr - v_ret_iva;

ELSE -- HONORARIOS
v_iva := v_commission_total * v_fiscal_regime.iva_trasladado;
v_ret_isr := (v_commission_total + v_iva) * v_fiscal_regime.isr;
v_ret_iva := v_iva * v_fiscal_regime.iva_retenido;
v_total_neto := v_commission_total + v_iva - v_ret_isr - v_ret_iva;
END IF;

-- Actualizar el batch
UPDATE commission_batches
SET 
regimen_fiscal = v_regimen_fiscal,
commission_vida = v_commission_vida,
commission_sinvida = v_commission_sinvida,
commission_total = v_commission_total,
retencion_contable = v_retencion_contable,
costo_dispersion = v_costo_dispersion,
iva = v_iva,
ret_isr = v_ret_isr,
ret_iva = v_ret_iva,
total_neto = v_total_neto,
calculated_at = NOW(),
tax_version = '2026-v1',
updated_at = NOW()
WHERE id = p_batch_id;

RETURN jsonb_build_object(
'success', true,
'batch_id', p_batch_id,
'usuario_id', v_usuario_id,
'regimen_fiscal', v_regimen_fiscal,
'total_neto', v_total_neto
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.recalculate_commission_batch_fiscal(p_batch_id uuid)
 RETURNS TABLE(success boolean, message text, total_records_updated integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_record RECORD;
v_updated_count INTEGER := 0;
v_regimen_fiscal TEXT;
BEGIN
FOR v_record IN 
SELECT 
cd.id,
cd.usuario_id,
cd.commission_bruta,
cd.commission_neta,
COALESCE(cfr.name, 'HONORARIOS') as regimen_fiscal
FROM commission_details cd
INNER JOIN usuarios u ON u.id = cd.usuario_id
LEFT JOIN commission_fiscal_regimes cfr ON cfr.id = u.regimen_fiscal_id
WHERE cd.batch_id = p_batch_id
LOOP
v_regimen_fiscal := v_record.regimen_fiscal;

IF v_regimen_fiscal = 'ASIMILADOS' THEN
UPDATE commission_details
SET
isr = ROUND((commission_neta / 1.09) * 0.10, 2),
iva_retenido = 0,
costo_dispersion = ROUND((commission_neta / 1.09) * 0.09, 2),
importe_pago = commission_neta - ROUND((commission_neta / 1.09) * 0.10, 2) - ROUND((commission_neta / 1.09) * 0.09, 2)
WHERE id = v_record.id;

ELSIF v_regimen_fiscal = 'RESICO' THEN
UPDATE commission_details
SET
iva_trasladado = ROUND(commission_bruta * 0.16, 2),
iva_retenido = ROUND((commission_bruta + ROUND(commission_bruta * 0.16, 2)) * 0.0533, 2),
isr = ROUND((commission_bruta + ROUND(commission_bruta * 0.16, 2)) * 0.0125, 2),
costo_dispersion = 0,
importe_pago = (commission_bruta + ROUND(commission_bruta * 0.16, 2)) - ROUND((commission_bruta + ROUND(commission_bruta * 0.16, 2)) * 0.0533, 2) - ROUND((commission_bruta + ROUND(commission_bruta * 0.16, 2)) * 0.0125, 2)
WHERE id = v_record.id;

ELSE -- HONORARIOS
UPDATE commission_details
SET
iva_trasladado = ROUND(commission_bruta * 0.16, 2),
iva_retenido = ROUND((commission_bruta + ROUND(commission_bruta * 0.16, 2)) * 0.0533, 2),
isr = ROUND((commission_bruta + ROUND(commission_bruta * 0.16, 2)) * 0.10, 2),
costo_dispersion = 0,
importe_pago = (commission_bruta + ROUND(commission_bruta * 0.16, 2)) - ROUND((commission_bruta + ROUND(commission_bruta * 0.16, 2)) * 0.0533, 2) - ROUND((commission_bruta + ROUND(commission_bruta * 0.16, 2)) * 0.10, 2)
WHERE id = v_record.id;
END IF;

v_updated_count := v_updated_count + 1;
END LOOP;

RETURN QUERY SELECT TRUE, 'Recalculo completado exitosamente'::TEXT, v_updated_count;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.recalculate_staging_session_counters(session_id uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
BEGIN
UPDATE commission_staging_sessions
SET
total_items = (
SELECT COUNT(*) 
FROM commission_items_staging 
WHERE staging_session_id = session_id
),
recognized_count = (
SELECT COUNT(*) 
FROM commission_items_staging 
WHERE staging_session_id = session_id 
AND movi_user_id IS NOT NULL
),
pending_assignment_count = (
SELECT COUNT(*) 
FROM commission_items_staging 
WHERE staging_session_id = session_id 
AND pending_assignment = true
),
updated_at = now()
WHERE id = session_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.record_assistant_feedback(p_routing_log_id uuid, p_feedback text, p_response_time_ms integer DEFAULT NULL::integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_log record;
BEGIN
-- Update routing log with feedback
UPDATE assistant_routing_logs
SET 
user_feedback = p_feedback,
response_time_ms = COALESCE(p_response_time_ms, response_time_ms)
WHERE id = p_routing_log_id
RETURNING * INTO v_log;

-- Update analytics
IF p_feedback = 'positive' THEN
UPDATE assistant_mode_analytics
SET 
successful_queries = successful_queries + 1,
positive_feedback = positive_feedback + 1,
updated_at = now()
WHERE user_id = v_log.user_id 
AND mode = v_log.selected_mode
AND period_start = date_trunc('week', v_log.created_at);
ELSIF p_feedback = 'negative' THEN
UPDATE assistant_mode_analytics
SET 
negative_feedback = negative_feedback + 1,
updated_at = now()
WHERE user_id = v_log.user_id 
AND mode = v_log.selected_mode
AND period_start = date_trunc('week', v_log.created_at);
END IF;

-- Update average response time if provided
IF p_response_time_ms IS NOT NULL THEN
UPDATE assistant_mode_analytics
SET 
average_response_time_ms = (
COALESCE(average_response_time_ms, 0) * (total_queries - 1) + p_response_time_ms
) / total_queries,
updated_at = now()
WHERE user_id = v_log.user_id 
AND mode = v_log.selected_mode
AND period_start = date_trunc('week', v_log.created_at);
END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.record_sicas_error(p_is_timeout boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_state record;
v_error_threshold integer;
v_timeout_threshold integer;
v_pause_minutes integer;
BEGIN
SELECT * INTO v_state FROM sicas_circuit_breaker LIMIT 1;

IF v_state IS NULL THEN
INSERT INTO sicas_circuit_breaker (is_open, error_count_5min, timeout_count_5min)
VALUES (false, 0, 0)
RETURNING * INTO v_state;
END IF;

-- Get thresholds from config
v_error_threshold := COALESCE((SELECT config_value::integer FROM sicas_rate_config WHERE config_key = 'CIRCUIT_BREAKER_ERROR_THRESHOLD'), 5);
v_timeout_threshold := COALESCE((SELECT config_value::integer FROM sicas_rate_config WHERE config_key = 'CIRCUIT_BREAKER_TIMEOUT_THRESHOLD'), 3);
v_pause_minutes := COALESCE((SELECT config_value::integer FROM sicas_rate_config WHERE config_key = 'CIRCUIT_BREAKER_PAUSE_MINUTES'), 15);

-- Update counters
IF p_is_timeout THEN
UPDATE sicas_circuit_breaker
SET timeout_count_5min = timeout_count_5min + 1,
last_error_at = now(),
updated_at = now()
WHERE id = v_state.id;
ELSE
UPDATE sicas_circuit_breaker
SET error_count_5min = error_count_5min + 1,
last_error_at = now(),
updated_at = now()
WHERE id = v_state.id;
END IF;

-- Check if should trip
SELECT * INTO v_state FROM sicas_circuit_breaker LIMIT 1;

IF NOT v_state.is_open AND (
v_state.error_count_5min >= v_error_threshold OR
v_state.timeout_count_5min >= v_timeout_threshold
) THEN
UPDATE sicas_circuit_breaker
SET is_open = true,
opened_at = now(),
closes_at = now() + (v_pause_minutes || ' minutes')::interval,
reason = CASE
WHEN v_state.error_count_5min >= v_error_threshold THEN 'Demasiados errores 500 en 5 minutos'
ELSE 'Demasiados timeouts en 5 minutos'
END,
updated_at = now()
WHERE id = v_state.id;

RETURN jsonb_build_object('tripped', true, 'closes_at', now() + (v_pause_minutes || ' minutes')::interval);
END IF;

RETURN jsonb_build_object('tripped', false);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.record_sicas_success()
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
UPDATE sicas_circuit_breaker
SET error_count_5min = GREATEST(error_count_5min - 1, 0),
timeout_count_5min = GREATEST(timeout_count_5min - 1, 0),
last_success_at = now(),
updated_at = now();
$function$
;

CREATE OR REPLACE FUNCTION public.reemplazar_maestro_catalogo(p_pestana text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  -- Solo administradores pueden ejecutar esto
  IF (SELECT get_my_rol()) != 'Administrador' THEN
    RAISE EXCEPTION 'Acceso denegado: se requiere rol Administrador';
  END IF;

  IF p_pestana = 'catalogo' THEN
    DELETE FROM public.maestro_combinaciones;
    DELETE FROM public.maestro_subramos;
    DELETE FROM public.maestro_companias;
    DELETE FROM public.maestro_ramos;

  ELSIF p_pestana = 'vendedores' THEN
    -- Los mapeos apuntan a agentes; si borramos agentes se rompe la FK.
    -- Borramos mapeos también para que el admin los reimporte con la nueva data.
    DELETE FROM public.maestro_usuario_agente;
    DELETE FROM public.maestro_agentes;
    DELETE FROM public.maestro_gerencias;
    DELETE FROM public.maestro_despachos;

  ELSIF p_pestana = 'mapeo' THEN
    DELETE FROM public.maestro_usuario_agente;

  ELSE
    RAISE EXCEPTION 'Pestaña inválida: %. Valores válidos: catalogo | vendedores | mapeo', p_pestana;
  END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.referencias_de_cuenta(p_user_id uuid)
 RETURNS TABLE(tabla text, columna text, filas bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r record;
  n bigint;
BEGIN
  FOR r IN
    SELECT c.conrelid::regclass::text AS tabla, a.attname::text AS columna
    FROM pg_constraint c
    JOIN unnest(c.conkey) WITH ORDINALITY k(attnum, ord) ON true
    JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = k.attnum
    JOIN pg_class t ON t.oid = c.conrelid
    JOIN pg_namespace ns ON ns.oid = t.relnamespace
    WHERE c.contype = 'f'
      AND c.confrelid = 'auth.users'::regclass
      AND ns.nspname = 'public'
  LOOP
    EXECUTE format('SELECT count(*) FROM %s WHERE %I = $1', r.tabla, r.columna)
      INTO n USING p_user_id;
    IF n > 0 THEN
      tabla := r.tabla; columna := r.columna; filas := n;
      RETURN NEXT;
    END IF;
  END LOOP;

  -- Sin llave foránea, pero igual de dueñas de la cuenta.
  FOR r IN
    SELECT * FROM (VALUES
      ('seguwallet_customers', 'auth_user_id'),
      ('chava_agente_users',   'auth_user_id')
    ) v(tabla, columna)
  LOOP
    IF EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = r.tabla AND column_name = r.columna
    ) THEN
      EXECUTE format('SELECT count(*) FROM public.%I WHERE %I = $1', r.tabla, r.columna)
        INTO n USING p_user_id;
      IF n > 0 THEN
        tabla := 'public.' || r.tabla; columna := r.columna; filas := n;
        RETURN NEXT;
      END IF;
    END IF;
  END LOOP;
END $function$
;

CREATE OR REPLACE FUNCTION public.refresh_sicas_customer_profiles(p_usuario_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_vendor_id text;
v_oficina_id uuid;
v_count integer := 0;
BEGIN
-- Get user's vendor mapping using the same helper as dashboard
v_vendor_id := get_sicas_user_vend_id(p_usuario_id);

IF v_vendor_id IS NULL THEN
RETURN jsonb_build_object('success', false, 'error', 'No vendor mapping found');
END IF;

-- Get office
SELECT oficina_id INTO v_oficina_id FROM usuarios WHERE id = p_usuario_id;

-- Upsert customer profiles from documents (using vend_id, not usuario_id)
INSERT INTO sicas_customer_profiles (
usuario_id, sicas_vendor_id, oficina_id, client_name, normalized_name, 
total_policies_active, total_premium_active, ramos_activos, aseguradoras_activas,
next_renewal_date, last_emission_date, last_activity_at, portfolio_status
)
SELECT
p_usuario_id,
v_vendor_id,
v_oficina_id,
d.cliente,
upper(trim(regexp_replace(d.cliente, '\s+', ' ', 'g'))),
count(*) FILTER (WHERE d.is_vigente = true),
coalesce(sum(d.prima_neta) FILTER (WHERE d.is_vigente = true), 0),
array_agg(DISTINCT d.ramo) FILTER (WHERE d.ramo IS NOT NULL AND d.is_vigente = true),
array_agg(DISTINCT d.compania) FILTER (WHERE d.compania IS NOT NULL AND d.is_vigente = true),
min(d.vigencia_hasta) FILTER (WHERE d.is_vigente = true AND d.vigencia_hasta > now()),
max(d.fecha_captura),
max(d.synced_at),
CASE
WHEN count(*) FILTER (WHERE d.is_vigente = true AND d.vigencia_hasta BETWEEN now() AND now() + interval '30 days') > 0 THEN 'renewing'
WHEN count(*) FILTER (WHERE d.is_vigente = true) > 0 THEN 'active'
WHEN count(*) FILTER (WHERE d.is_vigente = false AND d.vigencia_hasta > now() - interval '90 days') > 0 THEN 'expired'
ELSE 'lost'
END
FROM sicas_documents d
WHERE d.vend_id = v_vendor_id
AND d.cliente IS NOT NULL
AND trim(d.cliente) != ''
GROUP BY d.cliente
ON CONFLICT (usuario_id, normalized_name) WHERE rfc IS NULL
DO UPDATE SET
total_policies_active = EXCLUDED.total_policies_active,
total_premium_active = EXCLUDED.total_premium_active,
ramos_activos = EXCLUDED.ramos_activos,
aseguradoras_activas = EXCLUDED.aseguradoras_activas,
next_renewal_date = EXCLUDED.next_renewal_date,
last_emission_date = EXCLUDED.last_emission_date,
last_activity_at = EXCLUDED.last_activity_at,
portfolio_status = EXCLUDED.portfolio_status,
updated_at = now();

GET DIAGNOSTICS v_count = ROW_COUNT;

-- Mark high-value clients (top 20% by premium)
WITH ranked AS (
SELECT id, total_premium_active,
ntile(5) OVER (ORDER BY total_premium_active DESC) as quintile
FROM sicas_customer_profiles
WHERE usuario_id = p_usuario_id AND total_policies_active > 0
)
UPDATE sicas_customer_profiles cp
SET is_high_value = (r.quintile = 1)
FROM ranked r
WHERE cp.id = r.id;

RETURN jsonb_build_object('success', true, 'profiles_updated', v_count);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.refresh_sicas_document_renewal_flags()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
UPDATE sicas_documents
SET
renewal_days_remaining = CASE
WHEN vigencia_hasta IS NOT NULL THEN
EXTRACT(DAY FROM (vigencia_hasta - CURRENT_DATE))::integer
ELSE NULL
END,
is_renewable = CASE
WHEN is_vigente = true
AND vigencia_hasta IS NOT NULL
AND vigencia_hasta >= CURRENT_DATE
AND vigencia_hasta <= (CURRENT_DATE + interval '30 days')
THEN true
ELSE false
END,
updated_at = now()
WHERE is_vigente = true OR is_renewable = true;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.refresh_vendor_mapping_cache(p_vendor_nombre text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_normalized text;
v_mapping_id uuid;
v_user_id uuid;
v_user_name text;
v_oficina_nombre text;
v_match_method text;
v_mapping_source text;
BEGIN
-- Normalizar nombre
v_normalized := normalize_vendor_name(p_vendor_nombre);

IF v_normalized IS NULL THEN
RETURN;
END IF;

-- Buscar en vendor_mappings
SELECT vm.movi_user_id, u.nombre_completo, o.nombre
INTO v_user_id, v_user_name, v_oficina_nombre
FROM vendor_mappings vm
LEFT JOIN usuarios u ON u.id = vm.movi_user_id
LEFT JOIN oficinas o ON o.id = u.oficina_id
WHERE vm.source_type = 'name'
AND vm.source_value = v_normalized
AND vm.status = 'active'
LIMIT 1;

IF FOUND THEN
v_match_method := 'mapping_name';
v_mapping_source := 'manual';
ELSE
-- Buscar coincidencia directa en usuarios
SELECT u.id, u.nombre_completo, o.nombre
INTO v_user_id, v_user_name, v_oficina_nombre
FROM usuarios u
LEFT JOIN oficinas o ON o.id = u.oficina_id
WHERE normalize_vendor_name(u.nombre_completo) = v_normalized
AND u.estado != 'eliminado'
LIMIT 1;

IF FOUND THEN
v_match_method := 'direct_name';
v_mapping_source := 'auto';
ELSE
v_user_id := NULL;
v_user_name := NULL;
v_oficina_nombre := NULL;
v_match_method := 'none';
v_mapping_source := 'none';
END IF;
END IF;

-- Actualizar o insertar en cache
INSERT INTO production_vendors_cache (
vendor_nombre,
vendor_nombre_normalized,
movi_user_id,
movi_user_name,
oficina_nombre,
mapping_source,
match_method,
mapping_updated_at
) VALUES (
p_vendor_nombre,
v_normalized,
v_user_id,
v_user_name,
v_oficina_nombre,
v_mapping_source,
v_match_method,
now()
)
ON CONFLICT (vendor_nombre)
DO UPDATE SET
vendor_nombre_normalized = EXCLUDED.vendor_nombre_normalized,
movi_user_id = EXCLUDED.movi_user_id,
movi_user_name = EXCLUDED.movi_user_name,
oficina_nombre = EXCLUDED.oficina_nombre,
mapping_source = EXCLUDED.mapping_source,
match_method = EXCLUDED.match_method,
mapping_updated_at = EXCLUDED.mapping_updated_at,
updated_at = now();
END;
$function$
;

CREATE OR REPLACE FUNCTION public.registrar_auditoria_centro_digital()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
v_accion text;
v_detalles jsonb;
BEGIN
-- Determinar acción
IF TG_TABLE_NAME = 'centro_digital_archivos' THEN
IF TG_OP = 'INSERT' THEN
v_accion := 'archivo_subido';
v_detalles := jsonb_build_object(
'nombre', NEW.nombre,
'tamano_bytes', NEW.tamano_bytes,
'tipo_mime', NEW.tipo_mime
);

INSERT INTO centro_digital_auditoria (accion, carpeta_id, archivo_id, usuario_id, detalles)
VALUES (v_accion, NEW.carpeta_id, NEW.id, NEW.cargado_por, v_detalles);

ELSIF TG_OP = 'UPDATE' THEN
IF OLD.estado = 'activo' AND NEW.estado = 'papelera' THEN
v_accion := 'archivo_eliminado';
v_detalles := jsonb_build_object(
'nombre', NEW.nombre,
'eliminado_por', NEW.eliminado_por
);

INSERT INTO centro_digital_auditoria (accion, carpeta_id, archivo_id, usuario_id, detalles)
VALUES (v_accion, NEW.carpeta_id, NEW.id, NEW.eliminado_por, v_detalles);

ELSIF OLD.estado = 'papelera' AND NEW.estado = 'activo' THEN
v_accion := 'archivo_restaurado';
v_detalles := jsonb_build_object('nombre', NEW.nombre);

INSERT INTO centro_digital_auditoria (accion, carpeta_id, archivo_id, usuario_id, detalles)
VALUES (v_accion, NEW.carpeta_id, NEW.id, (SELECT auth.uid()), v_detalles);
END IF;
END IF;
END IF;

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.registrar_cambio_canales()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
-- Solo registrar si realmente cambió algo
IF (OLD.enviar_correo IS DISTINCT FROM NEW.enviar_correo OR
OLD.enviar_whatsapp IS DISTINCT FROM NEW.enviar_whatsapp OR
OLD.enviar_notificacion IS DISTINCT FROM NEW.enviar_notificacion) THEN

INSERT INTO correo_canales_historial (
tipo_notificacion_id,
enviar_correo_anterior,
enviar_whatsapp_anterior,
enviar_notificacion_anterior,
enviar_correo_nuevo,
enviar_whatsapp_nuevo,
enviar_notificacion_nuevo,
cambiado_por
) VALUES (
NEW.id,
OLD.enviar_correo,
OLD.enviar_whatsapp,
OLD.enviar_notificacion,
NEW.enviar_correo,
NEW.enviar_whatsapp,
NEW.enviar_notificacion,
auth.uid()
);
END IF;

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.registrar_cambio_ticket()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
descripcion_cambio TEXT := '';
tiene_cambios BOOLEAN := FALSE;
BEGIN
-- Detectar cambios en estatus
IF OLD.estatus_id IS DISTINCT FROM NEW.estatus_id THEN
SELECT INTO descripcion_cambio descripcion_cambio || 
'Estatus cambiado a: ' || (SELECT nombre FROM ticket_estatus WHERE id = NEW.estatus_id) || '. ';
tiene_cambios := TRUE;
END IF;

-- Detectar cambios en prioridad
IF OLD.prioridad IS DISTINCT FROM NEW.prioridad THEN
descripcion_cambio := descripcion_cambio || 'Prioridad cambiada a: ' || NEW.prioridad || '. ';
tiene_cambios := TRUE;
END IF;

-- Detectar cierre de ticket
IF OLD.cerrado_en IS NULL AND NEW.cerrado_en IS NOT NULL THEN
descripcion_cambio := descripcion_cambio || 'Ticket cerrado. ';
tiene_cambios := TRUE;
END IF;

-- Detectar reapertura de ticket
IF OLD.cerrado_en IS NOT NULL AND NEW.cerrado_en IS NULL THEN
descripcion_cambio := descripcion_cambio || 'Ticket reabierto. ';
tiene_cambios := TRUE;
END IF;

-- Registrar en historial si hay cambios
IF tiene_cambios AND NEW.modificado_por IS NOT NULL THEN
INSERT INTO ticket_historial (ticket_id, usuario_id, accion, descripcion)
VALUES (NEW.id, NEW.modificado_por, 'Actualización', descripcion_cambio);
END IF;

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.registrar_envio_notificacion(p_tipo_notificacion_codigo text, p_canal_envio text, p_usuario_id uuid DEFAULT NULL::uuid, p_destinatario_email text DEFAULT NULL::text, p_destinatario_nombre text DEFAULT NULL::text, p_numero_destino text DEFAULT NULL::text, p_asunto text DEFAULT 'Notificación'::text, p_cuerpo_html text DEFAULT NULL::text, p_estado text DEFAULT 'enviado'::text, p_error_mensaje text DEFAULT NULL::text, p_enviado_por uuid DEFAULT NULL::uuid, p_evento_id uuid DEFAULT NULL::uuid, p_provider_response jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_historial_id uuid;
v_tipo_id uuid;
BEGIN
-- Validar canal
IF p_canal_envio NOT IN ('correo', 'whatsapp', 'notificacion') THEN
RAISE EXCEPTION 'Canal de envío inválido: %. Debe ser correo, whatsapp o notificacion', p_canal_envio;
END IF;

-- Validar estado
IF p_estado NOT IN ('pendiente', 'enviado', 'fallido') THEN
RAISE EXCEPTION 'Estado inválido: %. Debe ser pendiente, enviado o fallido', p_estado;
END IF;

-- Obtener ID del tipo de notificación si existe
SELECT id INTO v_tipo_id
FROM correo_tipos_notificacion
WHERE codigo = p_tipo_notificacion_codigo
LIMIT 1;

-- Insertar registro en historial
INSERT INTO correo_historial_envios (
tipo_notificacion_id,
tipo_notificacion_codigo,
canal_envio,
usuario_id,
destinatario_email,
destinatario_nombre,
numero_destino,
asunto,
cuerpo_html,
estado,
error_mensaje,
enviado_por,
evento_id,
whatsapp_respuesta,
fecha_envio,
created_at
)
VALUES (
v_tipo_id,
p_tipo_notificacion_codigo,
p_canal_envio,
p_usuario_id,
COALESCE(p_destinatario_email, 'sin-email@sistema.local'),
p_destinatario_nombre,
p_numero_destino,
p_asunto,
p_cuerpo_html,
p_estado,
p_error_mensaje,
COALESCE(p_enviado_por, auth.uid()),
p_evento_id,
p_provider_response,
now(),
now()
)
RETURNING id INTO v_historial_id;

RETURN v_historial_id;
EXCEPTION
WHEN OTHERS THEN
-- Log error pero no fallar
RAISE WARNING 'Error al registrar envío de notificación: %, SQL State: %', SQLERRM, SQLSTATE;
RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.registrar_envio_notificacion_batch(p_tipo_notificacion_codigo text, p_canal_envio text, p_destinatarios jsonb, p_asunto text DEFAULT 'Notificación'::text, p_cuerpo_html text DEFAULT NULL::text, p_estado text DEFAULT 'enviado'::text, p_enviado_por uuid DEFAULT NULL::uuid, p_evento_id uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_destinatario jsonb;
v_count integer := 0;
v_historial_id uuid;
BEGIN
-- Validar que p_destinatarios sea un array
IF jsonb_typeof(p_destinatarios) != 'array' THEN
RAISE EXCEPTION 'p_destinatarios debe ser un array JSON';
END IF;

-- Iterar sobre cada destinatario
FOR v_destinatario IN SELECT * FROM jsonb_array_elements(p_destinatarios)
LOOP
v_historial_id := registrar_envio_notificacion(
p_tipo_notificacion_codigo := p_tipo_notificacion_codigo,
p_canal_envio := p_canal_envio,
p_usuario_id := (v_destinatario->>'usuario_id')::uuid,
p_destinatario_email := v_destinatario->>'email',
p_destinatario_nombre := v_destinatario->>'nombre',
p_numero_destino := v_destinatario->>'telefono',
p_asunto := p_asunto,
p_cuerpo_html := p_cuerpo_html,
p_estado := p_estado,
p_error_mensaje := v_destinatario->>'error',
p_enviado_por := p_enviado_por,
p_evento_id := p_evento_id,
p_provider_response := (v_destinatario->'provider_response')::jsonb
);

IF v_historial_id IS NOT NULL THEN
v_count := v_count + 1;
END IF;
END LOOP;

RETURN v_count;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.registrar_evento_educacion(p_user_id uuid, p_lesson_id uuid DEFAULT NULL::uuid, p_class_id uuid DEFAULT NULL::uuid, p_session_id text DEFAULT NULL::text, p_event_type text DEFAULT 'lesson_view_start'::text, p_progress_seconds integer DEFAULT 0, p_progress_percent numeric DEFAULT 0, p_duration_seconds integer DEFAULT NULL::integer, p_device text DEFAULT 'web'::text, p_browser text DEFAULT NULL::text, p_source text DEFAULT 'dashboard'::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid(); v_event_id uuid; v_oficina_id uuid; v_rol text; v_session text;
  v_valida boolean := (COALESCE(p_progress_seconds, 0) >= 10 OR COALESCE(p_progress_percent, 0) >= 5);
  v_completo boolean := (COALESCE(p_progress_percent, 0) >= 90);
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'No autenticado' USING ERRCODE = '42501'; END IF;
  SELECT oficina_id, rol INTO v_oficina_id, v_rol FROM usuarios WHERE id = v_user;
  v_session := COALESCE(p_session_id, gen_random_uuid()::text) || ':' || COALESCE(p_lesson_id::text, p_class_id::text, 'general');
  INSERT INTO seguros_education_eventos (user_id, lesson_id, class_id, session_id, event_type, oficina_id, rol,
    progress_seconds, progress_percent, duration_seconds, device, browser, source, metadata)
  VALUES (v_user, p_lesson_id, p_class_id, v_session, p_event_type, v_oficina_id, v_rol,
    p_progress_seconds, p_progress_percent, p_duration_seconds, p_device, p_browser, p_source, p_metadata)
  RETURNING id INTO v_event_id;
  INSERT INTO seguros_education_sesiones (session_id, user_id, lesson_id, class_id, oficina_id, rol, inicio,
    duracion_total_segundos, max_progress_percent, device, browser, es_reproduccion_valida, completo)
  VALUES (v_session, v_user, p_lesson_id, p_class_id, v_oficina_id, v_rol, now(),
    p_progress_seconds, p_progress_percent, p_device, p_browser, v_valida, v_completo)
  ON CONFLICT (session_id) DO UPDATE SET
    duracion_total_segundos = GREATEST(seguros_education_sesiones.duracion_total_segundos, EXCLUDED.duracion_total_segundos),
    max_progress_percent = GREATEST(seguros_education_sesiones.max_progress_percent, EXCLUDED.max_progress_percent),
    es_reproduccion_valida = seguros_education_sesiones.es_reproduccion_valida OR EXCLUDED.es_reproduccion_valida,
    completo = seguros_education_sesiones.completo OR EXCLUDED.completo,
    fin = now(), updated_at = now();
  RETURN v_event_id;
END; $function$
;

CREATE OR REPLACE FUNCTION public.release_sicas_lock(p_lock_id uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
UPDATE sicas_process_locks
SET is_active = false
WHERE id = p_lock_id;
$function$
;

CREATE OR REPLACE FUNCTION public.reorganize_batch_by_user(p_batch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_batch_info RECORD;
v_usuario_record RECORD;
v_new_batch_id UUID;
v_new_batch_name TEXT;
v_moved_count INTEGER := 0;
v_created_batches JSONB := '[]'::JSONB;
v_first_usuario_id UUID;
v_is_first BOOLEAN := TRUE;
v_batch_ids_to_recalc UUID[];
BEGIN
-- Obtener info del batch original
SELECT * INTO v_batch_info
FROM commission_batches
WHERE id = p_batch_id;

IF v_batch_info IS NULL THEN
RAISE EXCEPTION 'Lote % no encontrado', p_batch_id;
END IF;

v_batch_ids_to_recalc := ARRAY[]::UUID[];

-- PASO 1: Mover todos los details a sus respectivos batches
FOR v_usuario_record IN
SELECT 
usuario_id,
u.nombre_completo,
COUNT(*) as detail_count
FROM commission_details cd
JOIN usuarios u ON u.id = cd.usuario_id
WHERE cd.batch_id = p_batch_id
GROUP BY usuario_id, u.nombre_completo
HAVING COUNT(*) > 0
ORDER BY COUNT(*) DESC, usuario_id -- El que tiene más items se queda en el original
LOOP
-- Si es el primer usuario, usar el batch original
IF v_is_first THEN
v_new_batch_id := p_batch_id;
v_new_batch_name := v_batch_info.name || ' - ' || v_usuario_record.nombre_completo;
v_first_usuario_id := v_usuario_record.usuario_id;

-- Actualizar nombre del batch original
UPDATE commission_batches
SET 
name = v_new_batch_name,
display_name = v_new_batch_name,
updated_at = NOW()
WHERE id = p_batch_id;

v_is_first := FALSE;
ELSE
-- Crear nuevo batch para los demás usuarios
v_new_batch_name := v_batch_info.name || ' - ' || v_usuario_record.nombre_completo;

INSERT INTO commission_batches (
name,
display_name,
date_from,
date_to,
period_start,
period_end,
week_number,
uploaded_by,
status,
source_type,
created_at
) VALUES (
v_new_batch_name,
v_new_batch_name,
v_batch_info.date_from,
v_batch_info.date_to,
v_batch_info.period_start,
v_batch_info.period_end,
v_batch_info.week_number,
v_batch_info.uploaded_by,
'draft',
'reorganized',
NOW()
)
RETURNING id INTO v_new_batch_id;

-- Mover los details de este usuario al nuevo batch
UPDATE commission_details
SET batch_id = v_new_batch_id
WHERE batch_id = p_batch_id
AND usuario_id = v_usuario_record.usuario_id;
END IF;

-- Guardar el batch_id para recalcular después
v_batch_ids_to_recalc := array_append(v_batch_ids_to_recalc, v_new_batch_id);

v_created_batches := v_created_batches || jsonb_build_object(
'batch_id', v_new_batch_id,
'batch_name', v_new_batch_name,
'usuario_id', v_usuario_record.usuario_id,
'usuario_nombre', v_usuario_record.nombre_completo,
'detail_count', v_usuario_record.detail_count
);

v_moved_count := v_moved_count + 1;
END LOOP;

-- PASO 2: Ahora que todos los details están en sus batches correctos, recalcular cada uno
FOR v_new_batch_id IN SELECT unnest(v_batch_ids_to_recalc)
LOOP
PERFORM recalculate_batch_fiscal_values(v_new_batch_id);
END LOOP;

RETURN jsonb_build_object(
'success', true,
'original_batch_id', p_batch_id,
'batches_created', v_moved_count,
'batches', v_created_batches
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.repair_deleted_users_emails()
 RETURNS TABLE(usuario_id uuid, nombre text, email_laboral_original text, auth_email_anterior text, auth_email_nuevo text, reparado boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_record record;
v_deleted_email text;
v_count integer := 0;
BEGIN
-- Buscar usuarios eliminados que todavía tienen su email original en auth.users
FOR v_record IN
SELECT 
u.id,
u.nombre_completo,
u.email_laboral,
au.email::text as auth_email
FROM usuarios u
JOIN auth.users au ON au.id = u.id
WHERE u.is_deleted = true
AND u.email_laboral IS NOT NULL
AND u.email_laboral != ''
-- Si auth.email no tiene formato de "deleted-*", necesita repararse
AND au.email NOT LIKE 'deleted-%@deleted.local'
LOOP
BEGIN
-- Generar email dummy único
v_deleted_email := 'deleted-' || LEFT(v_record.id::text, 8) || '@deleted.local';

-- Actualizar auth.users
UPDATE auth.users
SET 
email = v_deleted_email,
email_confirmed_at = NULL,
updated_at = NOW()
WHERE id = v_record.id;

v_count := v_count + 1;

RETURN QUERY SELECT 
v_record.id,
v_record.nombre_completo,
v_record.email_laboral,
v_record.auth_email,
v_deleted_email,
true;

RAISE LOG '[repair] Usuario % : % -> %', 
v_record.id, v_record.auth_email, v_deleted_email;

EXCEPTION WHEN OTHERS THEN
RAISE WARNING '[repair] Error reparando usuario %: %', v_record.id, SQLERRM;

RETURN QUERY SELECT 
v_record.id,
v_record.nombre_completo,
v_record.email_laboral,
v_record.auth_email,
v_record.auth_email::text,
false;
END;
END LOOP;

RAISE NOTICE 'Reparación completada: % usuarios procesados', v_count;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.reschedule_agenda_reminders_on_config_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ DECLARE v_recipient_type text; BEGIN IF NEW.codigo NOT IN ('agenda_recordatorio_asesor','agenda_recordatorio_invitado') THEN RETURN NEW; END IF; v_recipient_type:=CASE WHEN NEW.codigo='agenda_recordatorio_asesor' THEN 'organizer' ELSE 'guest' END; DELETE FROM agenda_booking_reminders r USING agenda_bookings b WHERE r.booking_id=b.id AND r.event_code=NEW.codigo AND r.status IN ('pending','failed','cancelled') AND b.status='confirmed' AND b.start_at>now(); IF NEW.activo THEN INSERT INTO agenda_booking_reminders(booking_id,recipient_type,event_code,offset_minutes,scheduled_for) SELECT b.id,v_recipient_type,NEW.codigo,offsets.offset_minutes,GREATEST(now(),b.start_at-make_interval(mins=>offsets.offset_minutes)) FROM agenda_bookings b CROSS JOIN LATERAL unnest(NEW.reminder_offsets_minutes) offsets(offset_minutes) WHERE b.status='confirmed' AND b.start_at>now() ON CONFLICT(booking_id,recipient_type,offset_minutes) DO NOTHING; END IF; RETURN NEW; END; $function$
;

CREATE OR REPLACE FUNCTION public.resolve_notification_template(p_platform text, p_event_type text, p_channel text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, event_key text, name text, platform text, channel text, event_type text, email_subject_template text, email_body_template text, whatsapp_body_template text, inapp_title_template text, inapp_body_template text)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
-- Step 1: Exact match (platform + event_type + channel)
IF p_channel IS NOT NULL THEN
RETURN QUERY
SELECT t.id, t.event_key, t.name, t.platform, t.channel, t.event_type,
t.email_subject_template, t.email_body_template, t.whatsapp_body_template,
t.inapp_title_template, t.inapp_body_template
FROM transactional_notification_templates t
WHERE t.platform = p_platform
AND t.event_type = p_event_type
AND t.channel = p_channel
AND t.is_active = true
LIMIT 1;

IF FOUND THEN RETURN; END IF;
END IF;

-- Step 2: Platform match without channel (legacy multi-channel row)
RETURN QUERY
SELECT t.id, t.event_key, t.name, t.platform, t.channel, t.event_type,
t.email_subject_template, t.email_body_template, t.whatsapp_body_template,
t.inapp_title_template, t.inapp_body_template
FROM transactional_notification_templates t
WHERE t.platform = p_platform
AND t.event_type = p_event_type
AND t.channel IS NULL
AND t.is_active = true
LIMIT 1;

IF FOUND THEN RETURN; END IF;

-- Step 3: MOVI fallback with channel (only if original platform was not movi)
IF p_platform <> 'movi' AND p_channel IS NOT NULL THEN
RETURN QUERY
SELECT t.id, t.event_key, t.name, t.platform, t.channel, t.event_type,
t.email_subject_template, t.email_body_template, t.whatsapp_body_template,
t.inapp_title_template, t.inapp_body_template
FROM transactional_notification_templates t
WHERE t.platform = 'movi'
AND t.event_type = p_event_type
AND t.channel = p_channel
AND t.is_active = true
LIMIT 1;

IF FOUND THEN RETURN; END IF;
END IF;

-- Step 4: MOVI legacy fallback (no channel, multi-channel row)
IF p_platform <> 'movi' THEN
RETURN QUERY
SELECT t.id, t.event_key, t.name, t.platform, t.channel, t.event_type,
t.email_subject_template, t.email_body_template, t.whatsapp_body_template,
t.inapp_title_template, t.inapp_body_template
FROM transactional_notification_templates t
WHERE t.platform = 'movi'
AND t.event_type = p_event_type
AND t.channel IS NULL
AND t.is_active = true
LIMIT 1;
END IF;

-- If still nothing found, function returns empty set
RETURN;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.restaurar_chat(p_chat_id uuid, p_usuario_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
-- Verificar que el usuario sea miembro del chat
IF NOT EXISTS (
SELECT 1 FROM chat_miembros
WHERE chat_id = p_chat_id
AND usuario_id = p_usuario_id
) THEN
RAISE EXCEPTION 'Usuario no es miembro de este chat';
END IF;

-- Restaurar el chat (solo si no está eliminado permanentemente)
UPDATE chat_miembros
SET oculto = false,
oculto_at = NULL
WHERE chat_id = p_chat_id
AND usuario_id = p_usuario_id
AND eliminado = false;

RETURN true;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.reverse_gamification_event(p_event_id uuid, p_created_by uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_original_event agent_gamification_events;
v_reversal_id UUID;
BEGIN
-- Obtener evento original
SELECT * INTO v_original_event
FROM agent_gamification_events
WHERE id = p_event_id
AND reversible = true
AND reversed_by_event_id IS NULL
FOR UPDATE;

IF NOT FOUND THEN
RAISE EXCEPTION 'Evento no encontrado o no reversible';
END IF;

-- Crear evento de reversa (deltas negativos)
v_reversal_id := add_gamification_event(
p_user_id := v_original_event.user_id,
p_tipo_evento := 'cancelacion',
p_referencia_tipo := v_original_event.referencia_tipo,
p_referencia_id := v_original_event.referencia_id,
p_xp_delta := -v_original_event.xp_delta,
p_jc_delta := -v_original_event.jc_delta,
p_reversible := false,
p_jc_expiration_months := 0,
p_metadata := jsonb_build_object(
'original_event_id', p_event_id,
'motivo', 'cancelacion'
),
p_created_by := p_created_by
);

-- Marcar evento original como revertido
UPDATE agent_gamification_events
SET 
reversed_by_event_id = v_reversal_id,
is_reversal = true
WHERE id = p_event_id;

RETURN v_reversal_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.roles_propagar_base()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.rol_base IS DISTINCT FROM OLD.rol_base THEN
    UPDATE usuarios SET rol = NEW.rol_base WHERE rol_id = NEW.id AND rol IS DISTINCT FROM NEW.rol_base;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.run_fuzzy_vendor_match(p_threshold numeric DEFAULT 0.75, p_auto_confirm_threshold numeric DEFAULT 0.92)
 RETURNS TABLE(vendor_id uuid, vend_nombre text, matched_user_id uuid, matched_user_name text, similarity_score numeric, auto_confirmed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
RETURN QUERY
WITH candidates AS (
SELECT DISTINCT ON (vm.id)
vm.id AS vendor_id,
vm.vend_nombre,
u.id AS usuario_id,
(u.nombre || ' ' || u.apellidos) AS usuario_nombre,
similarity(
UPPER(vm.vend_nombre),
UPPER(u.nombre || ' ' || u.apellidos)
)::NUMERIC AS sim_score
FROM sicas_vendor_user_mappings vm
CROSS JOIN LATERAL (
SELECT u2.id, u2.nombre, u2.apellidos
FROM usuarios u2
WHERE u2.estado = 'activo'
AND similarity(UPPER(vm.vend_nombre), UPPER(u2.nombre || ' ' || u2.apellidos)) >= p_threshold
ORDER BY similarity(UPPER(vm.vend_nombre), UPPER(u2.nombre || ' ' || u2.apellidos)) DESC
LIMIT 1
) u
WHERE vm.status = 'pending_review'
AND vm.movi_user_id IS NULL
ORDER BY vm.id, sim_score DESC
)
SELECT 
c.vendor_id,
c.vend_nombre,
c.usuario_id AS matched_user_id,
c.usuario_nombre AS matched_user_name,
c.sim_score AS similarity_score,
(c.sim_score >= p_auto_confirm_threshold) AS auto_confirmed
FROM candidates c
ORDER BY c.sim_score DESC;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.run_post_sync_mapping(p_job_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_mapped integer := 0;
v_new_vendors integer := 0;
BEGIN
-- Step 1: Apply active vendor mappings to unmapped documents
WITH mapping_update AS (
UPDATE sicas_documents d
SET 
usuario_id = m.movi_user_id,
updated_at = now()
FROM sicas_vendor_user_mappings m
WHERE m.vend_id = d.vend_id
AND m.status = 'active'
AND m.movi_user_id IS NOT NULL
AND d.usuario_id IS NULL
RETURNING d.id
)
SELECT COUNT(*) INTO v_mapped FROM mapping_update;

-- Step 2: Upsert new vendors discovered from documents into mapping table
WITH new_vendors AS (
INSERT INTO sicas_vendor_user_mappings (vend_id, vend_nombre, desp_nombre, total_docs, total_prima_neta, last_doc_date, status, match_type)
SELECT 
d.vend_id,
MAX(d.vend_nombre),
MAX(d.desp_nombre),
COUNT(*),
COALESCE(SUM(d.prima_neta), 0),
MAX(d.synced_at),
'pending_review',
'no_match'
FROM sicas_documents d
WHERE d.vend_id IS NOT NULL
GROUP BY d.vend_id
ON CONFLICT (vend_id) DO UPDATE SET
total_docs = EXCLUDED.total_docs,
total_prima_neta = EXCLUDED.total_prima_neta,
last_doc_date = EXCLUDED.last_doc_date,
vend_nombre = COALESCE(sicas_vendor_user_mappings.vend_nombre, EXCLUDED.vend_nombre),
updated_at = now()
RETURNING vend_id
)
SELECT COUNT(*) INTO v_new_vendors FROM new_vendors;

-- Step 3: Update job record if provided
IF p_job_id IS NOT NULL THEN
UPDATE sicas_sync_jobs
SET 
post_sync_done = true,
post_sync_at = now(),
docs_mapped_in_post_sync = v_mapped,
updated_at = now()
WHERE id = p_job_id;
END IF;

RETURN jsonb_build_object(
'docs_mapped', v_mapped,
'vendors_updated', v_new_vendors,
'ran_at', now()
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.safe_delete_user(user_id_to_delete uuid, deleted_by_admin_id uuid, deletion_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
target_user RECORD;
admin_user RECORD;
active_admin_count integer;
deleted_email text;
result jsonb;
BEGIN
-- Get target user info
SELECT * INTO target_user
FROM usuarios
WHERE id = user_id_to_delete;

-- Verify user exists
IF NOT FOUND THEN
RETURN jsonb_build_object(
'success', false,
'error', 'Usuario no encontrado',
'error_code', 'USER_NOT_FOUND'
);
END IF;

-- Verify user is not already deleted
IF target_user.is_deleted = true THEN
RETURN jsonb_build_object(
'success', false,
'error', 'Usuario ya está eliminado',
'error_code', 'USER_ALREADY_DELETED'
);
END IF;

-- Verify admin exists and is active
SELECT * INTO admin_user
FROM usuarios
WHERE id = deleted_by_admin_id;

IF NOT FOUND OR admin_user.rol != 'Administrador' OR admin_user.is_deleted = true THEN
RETURN jsonb_build_object(
'success', false,
'error', 'Administrador inválido o no autorizado',
'error_code', 'INVALID_ADMIN'
);
END IF;

-- Prevent self-deletion
IF user_id_to_delete = deleted_by_admin_id THEN
RETURN jsonb_build_object(
'success', false,
'error', 'No puedes eliminarte a ti mismo',
'error_code', 'CANNOT_DELETE_SELF'
);
END IF;

-- If deleting an admin, check if it's the last active admin
IF target_user.rol = 'Administrador' THEN
SELECT COUNT(*) INTO active_admin_count
FROM usuarios
WHERE rol = 'Administrador'
AND is_deleted = false
AND activo = true
AND id != user_id_to_delete;

IF active_admin_count = 0 THEN
RETURN jsonb_build_object(
'success', false,
'error', 'No se puede eliminar el último administrador activo',
'error_code', 'LAST_ADMIN'
);
END IF;
END IF;

-- ✅ NUEVO: Generar email dummy único para liberar el email_laboral
deleted_email := 'deleted-' || LEFT(user_id_to_delete::text, 8) || '@deleted.local';

-- ✅ NUEVO: Modificar email en auth.users para liberar el email_laboral
BEGIN
UPDATE auth.users
SET 
email = deleted_email,
email_confirmed_at = NULL,
updated_at = now()
WHERE id = user_id_to_delete;

RAISE LOG '[safe_delete] Email liberado: % -> %', target_user.email_laboral, deleted_email;
EXCEPTION WHEN OTHERS THEN
RAISE WARNING '[safe_delete] Error al modificar auth.email: %', SQLERRM;
-- Continuar con soft delete aunque falle auth.users
END;

-- Perform soft delete en tabla usuarios
UPDATE usuarios
SET 
is_deleted = true,
deleted_at = now(),
deleted_by_user_id = deleted_by_admin_id,
estado = 'eliminado',
activo = false
WHERE id = user_id_to_delete;

-- Create audit log entry
INSERT INTO audit_logs (
action,
performed_by,
target_user_id,
target_resource_type,
target_resource_id,
details
) VALUES (
'USER_DELETE',
deleted_by_admin_id,
user_id_to_delete,
'usuario',
user_id_to_delete,
jsonb_build_object(
'user_name', target_user.nombre,
'user_rol', target_user.rol,
'user_email_laboral', target_user.email_laboral,
'auth_email_replaced', deleted_email,
'deletion_reason', deletion_reason,
'deletion_type', 'soft_delete_with_email_release'
)
);

-- Build success response
result := jsonb_build_object(
'success', true,
'message', 'Usuario eliminado correctamente. Email liberado para reutilización.',
'deletion_type', 'soft_delete',
'email_released', true,
'user', jsonb_build_object(
'id', target_user.id,
'nombre', target_user.nombre,
'rol', target_user.rol,
'email_laboral_original', target_user.email_laboral
),
'deleted_at', now(),
'deleted_by', jsonb_build_object(
'id', admin_user.id,
'nombre', admin_user.nombre
)
);

RETURN result;

EXCEPTION
WHEN OTHERS THEN
RETURN jsonb_build_object(
'success', false,
'error', 'Error inesperado durante la eliminación',
'error_code', 'UNEXPECTED_ERROR',
'sqlstate', SQLSTATE,
'message', SQLERRM
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.se_es_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (SELECT 1 FROM usuarios WHERE id = auth.uid() AND rol IN ('Administrador', 'administrador', 'admin'));
$function$
;

CREATE OR REPLACE FUNCTION public.search_directory(search_term text)
 RETURNS TABLE(id uuid, nombre_completo text, rol text, puesto text, oficina_nombre text, celular_laboral text, extension_telefonica text, email_laboral text, celular_personal text, email_personal text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
search_words text[];
BEGIN
-- Dividir el search_term en palabras (separadas por espacios)
search_words := string_to_array(LOWER(TRIM(search_term)), ' ');

-- Si solo hay una palabra, hacer búsqueda simple
IF array_length(search_words, 1) = 1 THEN
RETURN QUERY
SELECT 
u.id,
u.nombre || ' ' || u.apellidos AS nombre_completo,
u.rol::text,
u.puesto,
o.nombre AS oficina_nombre,
u.celular_laboral,
u.extension_telefonica,
u.email_laboral,
u.celular_personal,
u.email_personal
FROM usuarios u
LEFT JOIN oficinas o ON u.oficina_id = o.id
WHERE 
u.activo = true
AND (
LOWER(u.nombre) LIKE LOWER('%' || search_term || '%')
OR LOWER(u.apellidos) LIKE LOWER('%' || search_term || '%')
OR LOWER(u.nombre || ' ' || u.apellidos) LIKE LOWER('%' || search_term || '%')
OR LOWER(u.email_laboral) LIKE LOWER('%' || search_term || '%')
OR LOWER(u.email_personal) LIKE LOWER('%' || search_term || '%')
OR REPLACE(REPLACE(u.celular_laboral, '-', ''), ' ', '') LIKE '%' || REPLACE(REPLACE(search_term, '-', ''), ' ', '') || '%'
OR REPLACE(REPLACE(u.celular_personal, '-', ''), ' ', '') LIKE '%' || REPLACE(REPLACE(search_term, '-', ''), ' ', '') || '%'
)
ORDER BY 
CASE 
WHEN LOWER(u.nombre) = LOWER(search_term) THEN 1
WHEN LOWER(u.apellidos) = LOWER(search_term) THEN 2
WHEN LOWER(u.nombre || ' ' || u.apellidos) = LOWER(search_term) THEN 3
WHEN LOWER(u.nombre) LIKE LOWER(search_term || '%') THEN 4
ELSE 5
END,
u.nombre, u.apellidos
LIMIT 10;
ELSE
-- Si hay múltiples palabras, buscar que TODAS las palabras estén presentes
RETURN QUERY
SELECT 
u.id,
u.nombre || ' ' || u.apellidos AS nombre_completo,
u.rol::text,
u.puesto,
o.nombre AS oficina_nombre,
u.celular_laboral,
u.extension_telefonica,
u.email_laboral,
u.celular_personal,
u.email_personal
FROM usuarios u
LEFT JOIN oficinas o ON u.oficina_id = o.id
WHERE 
u.activo = true
-- Verificar que TODAS las palabras estén en nombre O apellidos
AND (
-- Todas las palabras en nombre completo
(SELECT bool_and(
LOWER(u.nombre || ' ' || u.apellidos) LIKE LOWER('%' || w || '%')
) FROM unnest(search_words) AS w)
-- O todas en email
OR (SELECT bool_and(
LOWER(u.email_laboral) LIKE LOWER('%' || w || '%')
) FROM unnest(search_words) AS w)
)
ORDER BY 
-- Priorizar matches donde las palabras aparecen en orden
CASE 
WHEN LOWER(u.nombre || ' ' || u.apellidos) LIKE LOWER(array_to_string(search_words, '%') || '%') THEN 1
ELSE 2
END,
u.nombre, u.apellidos
LIMIT 10;
END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.search_offices(search_term text)
 RETURNS TABLE(id uuid, nombre text, telefono text, email text, domicilio text, gerente_nombre text, director_nombre text, facebook text, instagram text, activa boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN QUERY
SELECT 
o.id,
o.nombre,
o.telefono,
o.email,
o.domicilio,
o.gerente AS gerente_nombre,
o.director AS director_nombre,
o.facebook,
o.instagram,
o.activa
FROM oficinas o
WHERE 
o.activa = true
AND o.es_espacio_jiro = false
AND (
-- Búsqueda por nombre de oficina
LOWER(o.nombre) LIKE LOWER('%' || search_term || '%')
-- Búsqueda por domicilio/ciudad
OR LOWER(o.domicilio) LIKE LOWER('%' || search_term || '%')
-- Búsqueda por gerente
OR LOWER(o.gerente) LIKE LOWER('%' || search_term || '%')
-- Búsqueda por director
OR LOWER(o.director) LIKE LOWER('%' || search_term || '%')
)
ORDER BY 
-- Priorizar matches exactos en nombre
CASE 
WHEN LOWER(o.nombre) = LOWER(search_term) THEN 1
WHEN LOWER(o.nombre) LIKE LOWER(search_term || '%') THEN 2
ELSE 3
END,
o.nombre
LIMIT 10;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.search_sicas_clients_admin(p_query text DEFAULT ''::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS TABLE(sicas_client_id text, client_name text, vend_id text, poliza_count bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN QUERY
SELECT
d.cliente   AS sicas_client_id,
d.cliente   AS client_name,
d.vend_id   AS vend_id,
COUNT(*)    AS poliza_count
FROM sicas_documents d
WHERE d.cliente IS NOT NULL
AND d.cliente <> ''
AND (
p_query = ''
OR d.cliente ILIKE '%' || p_query || '%'
)
GROUP BY d.cliente, d.vend_id
ORDER BY d.cliente
LIMIT p_limit
OFFSET p_offset;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.search_sicas_clients_for_agent(p_agent_user_id uuid, p_query text DEFAULT ''::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS TABLE(sicas_client_id text, client_name text, vend_id text, poliza_count bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_vend_ids text[];
BEGIN
-- Get the agent's mapped SICAS vendor IDs
SELECT array_agg(id_sicas_vendedor)
INTO v_vend_ids
FROM sicas_mapeo_vendedor_usuario
WHERE movi_user_id = p_agent_user_id;

-- If agent has no mappings, return empty (not admin path)
IF v_vend_ids IS NULL OR array_length(v_vend_ids, 1) = 0 THEN
RETURN;
END IF;

RETURN QUERY
SELECT
d.cliente                        AS sicas_client_id,
d.cliente                        AS client_name,
d.vend_id                        AS vend_id,
COUNT(*)                         AS poliza_count
FROM sicas_documents d
WHERE d.vend_id = ANY(v_vend_ids)
AND d.cliente IS NOT NULL
AND d.cliente <> ''
AND (
p_query = ''
OR d.cliente ILIKE '%' || p_query || '%'
)
GROUP BY d.cliente, d.vend_id
ORDER BY d.cliente
LIMIT p_limit
OFFSET p_offset;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.search_user_conversations(p_usuario_id uuid, p_query text, p_limit integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_result jsonb;
BEGIN
SELECT COALESCE(jsonb_agg(resultado), '[]'::jsonb)
INTO v_result
FROM (
SELECT jsonb_build_object(
'mensaje_id', cm.id,
'chat_id', c.id,
'chat_nombre', CASE 
WHEN c.tipo = 'group' THEN c.nombre
ELSE (
SELECT string_agg(u2.nombre_completo, ', ')
FROM usuarios u2
WHERE u2.id = ANY(c.participantes_directos)
AND u2.id != p_usuario_id
)
END,
'remitente', u.nombre_completo,
'mensaje', cm.mensaje,
'created_at', cm.created_at
) as resultado
FROM chat_mensajes cm
INNER JOIN chats c ON c.id = cm.chat_id
INNER JOIN chat_miembros cmb ON cmb.chat_id = c.id
INNER JOIN usuarios u ON u.id = cm.remitente_id
WHERE cmb.usuario_id = p_usuario_id
AND cm.eliminado = false
AND cm.mensaje ILIKE '%' || p_query || '%'
ORDER BY cm.created_at DESC
LIMIT p_limit
) sub;

RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.send_email_with_attachments(p_to_email text, p_subject text, p_html_body text, p_attachments jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_response jsonb;
v_request_payload jsonb;
BEGIN
-- Construir payload
v_request_payload := jsonb_build_object(
'to_email', p_to_email,
'subject', p_subject,
'html_body', p_html_body
);

-- Agregar adjuntos si existen
IF p_attachments IS NOT NULL AND jsonb_array_length(p_attachments) > 0 THEN
v_request_payload := v_request_payload || jsonb_build_object('attachments', p_attachments);
END IF;

-- Llamar a la edge function
SELECT content::jsonb INTO v_response
FROM http((
'POST',
current_setting('app.settings.supabase_url') || '/functions/v1/enviar-correo-transaccional',
ARRAY[
http_header('Content-Type', 'application/json'),
http_header('Authorization', 'Bearer ' || current_setting('app.settings.supabase_anon_key'))
],
'application/json',
v_request_payload::text
)::http_request);

RETURN v_response;
EXCEPTION
WHEN OTHERS THEN
RAISE WARNING 'Error enviando correo con adjuntos: %', SQLERRM;
RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.send_transactional_notification(p_event_key text, p_user_id uuid, p_variables jsonb DEFAULT '{}'::jsonb, p_link_url text DEFAULT NULL::text, p_attachments jsonb DEFAULT '[]'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_template record;
v_user record;
v_notif_id uuid;
v_email_subject text;
v_email_body text;
v_whatsapp_body text;
v_inapp_title text;
v_inapp_body text;
v_variable_key text;
v_variable_value text;
v_supabase_url text;
v_anon_key text;
v_request_id bigint;
BEGIN
-- Obtener la plantilla
SELECT * INTO v_template
FROM transactional_notification_templates
WHERE event_key = p_event_key
AND is_active = true;

IF NOT FOUND THEN
RAISE WARNING 'Template not found or inactive: %', p_event_key;
RETURN NULL;
END IF;

-- Obtener datos del usuario
SELECT
id,
nombre_completo,
email_laboral,
celular_laboral
INTO v_user
FROM usuarios
WHERE id = p_user_id;

IF NOT FOUND THEN
RAISE WARNING 'User not found: %', p_user_id;
RETURN NULL;
END IF;

-- Inicializar las plantillas
v_email_subject := v_template.email_subject_template;
v_email_body := v_template.email_body_template;
v_whatsapp_body := v_template.whatsapp_body_template;
v_inapp_title := v_template.inapp_title_template;
v_inapp_body := v_template.inapp_body_template;

-- Reemplazar variables en las plantillas
FOR v_variable_key, v_variable_value IN SELECT * FROM jsonb_each_text(p_variables)
LOOP
v_email_subject := replace(v_email_subject, '{{' || v_variable_key || '}}', v_variable_value);
v_email_body := replace(v_email_body, '{{' || v_variable_key || '}}', v_variable_value);
v_whatsapp_body := replace(v_whatsapp_body, '{{' || v_variable_key || '}}', v_variable_value);
v_inapp_title := replace(v_inapp_title, '{{' || v_variable_key || '}}', v_variable_value);
v_inapp_body := replace(v_inapp_body, '{{' || v_variable_key || '}}', v_variable_value);
END LOOP;

-- 1. Crear notificación interna (campanita)
IF v_inapp_title IS NOT NULL AND v_inapp_body IS NOT NULL THEN
INSERT INTO notifications (user_id, title, body, link_url)
VALUES (p_user_id, v_inapp_title, v_inapp_body, p_link_url)
RETURNING id INTO v_notif_id;

RAISE NOTICE 'Created in-app notification: %', v_notif_id;
END IF;

-- Obtener configuración de Supabase
v_supabase_url := COALESCE(
current_setting('app.settings.supabase_url', true),
'https://qhwvuuyjhcennqccgvse.supabase.co'
);

v_anon_key := COALESCE(
current_setting('app.settings.supabase_anon_key', true),
'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InFod3Z1dXlqaGNlbm5xY2NndnNlIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NjE3MjA5OTAsImV4cCI6MjA3NzI5Njk5MH0.bIlGsgeAC6oxGUalODg0C5-l6KaJip0wWa9IbQ7MjTQ'
);

-- 2. Enviar email si está configurado (con adjuntos)
IF v_email_subject IS NOT NULL AND v_email_body IS NOT NULL AND v_user.email_laboral IS NOT NULL THEN
BEGIN
SELECT net.http_post(
url := v_supabase_url || '/functions/v1/enviar-correo-transaccional',
headers := jsonb_build_object(
'Content-Type', 'application/json',
'Authorization', 'Bearer ' || v_anon_key
),
body := jsonb_build_object(
'to_email', v_user.email_laboral,
'to_name', v_user.nombre_completo,
'subject', v_email_subject,
'html_body', v_email_body,
'attachments', p_attachments
)
) INTO v_request_id;

RAISE NOTICE 'Email notification queued: % to % with % attachments', v_request_id, v_user.email_laboral, jsonb_array_length(p_attachments);
EXCEPTION WHEN OTHERS THEN
RAISE WARNING 'Failed to queue email notification: %', SQLERRM;
END;
END IF;

-- 3. Enviar WhatsApp si está configurado
IF v_whatsapp_body IS NOT NULL AND v_user.celular_laboral IS NOT NULL THEN
BEGIN
SELECT net.http_post(
url := v_supabase_url || '/functions/v1/enviar-whatsapp',
headers := jsonb_build_object(
'Content-Type', 'application/json',
'Authorization', 'Bearer ' || v_anon_key
),
body := jsonb_build_object(
'phone', v_user.celular_laboral,
'message', v_whatsapp_body
)
) INTO v_request_id;

RAISE NOTICE 'WhatsApp notification queued: % to %', v_request_id, v_user.celular_laboral;
EXCEPTION WHEN OTHERS THEN
RAISE WARNING 'Failed to queue WhatsApp notification: %', SQLERRM;
END;
END IF;

RETURN v_notif_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.send_welcome_notification_manual(p_user_id uuid, p_tipo_notificacion text DEFAULT 'cuenta_activada'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_user record;
v_pagina_web text;
v_oficina_nombre text;
v_result jsonb;
BEGIN
SELECT * INTO v_user
FROM usuarios
WHERE id = p_user_id;

IF NOT FOUND THEN
RETURN jsonb_build_object('success', false, 'error', 'Usuario no encontrado');
END IF;

IF v_user.web_slug IS NOT NULL AND v_user.web_slug != '' THEN
v_pagina_web := 'https://agentedeseguros.website/' || v_user.web_slug;
ELSE
v_pagina_web := 'No configurada aún';
END IF;

IF v_user.oficina_id IS NOT NULL THEN
SELECT nombre INTO v_oficina_nombre
FROM oficinas
WHERE id = v_user.oficina_id;
END IF;

IF v_oficina_nombre IS NULL THEN
v_oficina_nombre := 'No asignada';
END IF;

SELECT notify(
p_tipo_notificacion,
ARRAY[p_user_id],
jsonb_build_object(
'nombre', COALESCE(v_user.nombre, ''),
'apellidos', COALESCE(v_user.apellidos, ''),
'nombre_completo', COALESCE(v_user.nombre_completo, ''),
'email_laboral', v_user.email_laboral,
'email_personal', COALESCE(v_user.email_personal, ''),
'celular_laboral', COALESCE(v_user.celular_laboral, ''),
'celular_personal', COALESCE(v_user.celular_personal, ''),
'password', 'La que configuraste al registrarte',
'rol', v_user.rol,
'oficina', v_oficina_nombre,
'puesto', COALESCE(v_user.puesto, ''),
'pagina_web', v_pagina_web
),
'manual_call'
) INTO v_result;

RETURN jsonb_build_object(
'success', true,
'user_id', p_user_id,
'notification_type', p_tipo_notificacion,
'jobs_created', v_result
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.send_welcome_notifications_on_activation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_pagina_web text;
v_oficina_nombre text;
v_password_temp text;
BEGIN
IF NEW.estado = 'activo' AND (OLD.estado IS NULL OR OLD.estado != 'activo') THEN
RAISE LOG '[activation] Usuario activado: % - %', NEW.id, NEW.email_laboral;

IF NEW.web_slug IS NOT NULL AND NEW.web_slug != '' THEN
v_pagina_web := 'https://agentedeseguros.website/' || NEW.web_slug;
ELSE
v_pagina_web := 'No configurada aún';
END IF;

IF NEW.oficina_id IS NOT NULL THEN
SELECT nombre INTO v_oficina_nombre
FROM oficinas
WHERE id = NEW.oficina_id;
END IF;

IF v_oficina_nombre IS NULL THEN
v_oficina_nombre := 'No asignada';
END IF;

v_password_temp := 'La que te proporcionó tu administrador';

BEGIN
PERFORM enviar_notificacion_completa(
p_tipo_codigo := 'cuenta_activada',
p_user_id := NEW.id,
p_titulo := '¡Bienvenido a MOVI Digital!',
p_mensaje := 'Tu cuenta ha sido activada exitosamente. Ya puedes acceder a la plataforma.',
p_modulo := 'usuarios',
p_datos_adicionales := jsonb_build_object(
'nombre', COALESCE(NEW.nombre_completo, NEW.nombre || ' ' || NEW.apellidos),
'email_laboral', NEW.email_laboral,
'password', v_password_temp,
'pagina_web', v_pagina_web,
'oficina', v_oficina_nombre,
'rol', NEW.rol
),
p_accion_url := 'https://app.movi.digital/dashboard'
);
RAISE LOG '[activation] Notificación de cuenta_activada enviada correctamente';
EXCEPTION WHEN OTHERS THEN
RAISE LOG '[activation] Error al enviar notificación: %', SQLERRM;
END;
END IF;

RETURN NEW;
END;
$function$
;

