CREATE OR REPLACE FUNCTION public.set_chat_miembros_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- Solo setear defaults si son NULL
  IF NEW.rol IS NULL THEN
    NEW.rol := 'miembro';
  END IF;
  
  IF NEW.unido_at IS NULL THEN
    NEW.unido_at := now();
  END IF;
  
  IF NEW.joined_at IS NULL THEN
    NEW.joined_at := now();
  END IF;
  
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.set_crm_contacto_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_agent_id uuid;
  v_oficina_id uuid;
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- Manual creation always belongs to its creator. Lead/Seguwallet
    -- assignment is applied afterwards by their synchronization triggers.
    v_agent_id := COALESCE(NEW.creado_por, auth.uid());
  ELSE
    v_agent_id := COALESCE(NEW.agente_id, NEW.creado_por, auth.uid());
  END IF;

  IF v_agent_id IS NULL THEN
    RAISE EXCEPTION 'Todo contacto debe tener un agente relacionado';
  END IF;

  SELECT u.oficina_id
    INTO v_oficina_id
    FROM public.usuarios u
   WHERE u.id = v_agent_id
   LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'El agente relacionado no existe: %', v_agent_id;
  END IF;

  IF v_oficina_id IS NULL THEN
    RAISE EXCEPTION 'El agente % no tiene una oficina relacionada', v_agent_id;
  END IF;

  NEW.agente_id := v_agent_id;
  NEW.oficina_id := v_oficina_id;
  RETURN NEW;
END;
$function$
;

