CREATE OR REPLACE FUNCTION public.sicas_auto_map_vendors(p_dry_run boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_mapped_count integer := 0;
v_id_exact_count integer := 0;
v_nombre_sicas_count integer := 0;
v_nombre_norm_count integer := 0;
v_nombre_inv_count integer := 0;
v_total_vendors integer := 0;
v_already_mapped integer := 0;
v_rec record;
v_user_id uuid;
v_confidence numeric;
v_match_type text;
v_match_details jsonb;
v_words text[];
v_inverted text;
BEGIN
SELECT COUNT(DISTINCT vend_id) INTO v_total_vendors FROM sicas_documents;
SELECT COUNT(*) INTO v_already_mapped FROM sicas_vendor_user_mappings WHERE status IN ('active', 'pending_review');

FOR v_rec IN
SELECT DISTINCT ON (d.vend_id)
d.vend_id,
d.vend_nombre,
d.desp_nombre,
COUNT(*) OVER (PARTITION BY d.vend_id) as total_docs,
SUM(d.prima_neta) OVER (PARTITION BY d.vend_id) as total_prima,
MAX(d.fecha_captura) OVER (PARTITION BY d.vend_id) as last_doc
FROM sicas_documents d
WHERE d.vend_id IS NOT NULL
AND NOT EXISTS (
SELECT 1 FROM sicas_vendor_user_mappings m
WHERE m.vend_id = d.vend_id
)
ORDER BY d.vend_id, d.fecha_captura DESC
LOOP
v_user_id := NULL; v_confidence := 0; v_match_type := NULL; v_match_details := '{}';

-- Método 1: id_sicas exacto
SELECT u.id INTO v_user_id FROM usuarios u
WHERE u.id_sicas = v_rec.vend_id AND u.activo = true AND u.is_deleted = false LIMIT 1;
IF v_user_id IS NOT NULL THEN
v_confidence := 99; v_match_type := 'id_sicas_exact';
v_match_details := jsonb_build_object('method','id_sicas','vend_id',v_rec.vend_id);
v_id_exact_count := v_id_exact_count + 1;
END IF;

-- Método 2: nombre_sicas exacto
IF v_user_id IS NULL THEN
SELECT u.id INTO v_user_id FROM usuarios u
WHERE upper(trim(COALESCE(u.nombre_sicas,''))) = upper(trim(v_rec.vend_nombre))
AND u.activo = true AND u.is_deleted = false LIMIT 1;
IF v_user_id IS NOT NULL THEN
v_confidence := 95; v_match_type := 'nombre_sicas_exact';
v_match_details := jsonb_build_object('method','nombre_sicas','vend_nombre',v_rec.vend_nombre);
v_nombre_sicas_count := v_nombre_sicas_count + 1;
END IF;
END IF;

-- Método 3: nombre normalizado directo
IF v_user_id IS NULL THEN
SELECT u.id INTO v_user_id FROM usuarios u
WHERE normalize_name_for_sicas(u.nombre_completo) = normalize_name_for_sicas(v_rec.vend_nombre)
AND u.activo = true AND u.is_deleted = false
AND u.rol IN ('Agente','Gerente','Ejecutivo') LIMIT 1;
IF v_user_id IS NOT NULL THEN
v_confidence := 82; v_match_type := 'nombre_normalizado';
v_match_details := jsonb_build_object('method','nombre_norm','norm',normalize_name_for_sicas(v_rec.vend_nombre));
v_nombre_norm_count := v_nombre_norm_count + 1;
END IF;
END IF;

-- Método 4: nombre invertido (APELLIDO NOMBRE -> NOMBRE APELLIDO)
IF v_user_id IS NULL AND length(v_rec.vend_nombre) > 5 THEN
v_words := string_to_array(normalize_name_for_sicas(v_rec.vend_nombre), ' ');
IF array_length(v_words, 1) >= 2 THEN
v_inverted := array_to_string(v_words[2:array_length(v_words,1)], ' ') || ' ' || v_words[1];
SELECT u.id INTO v_user_id FROM usuarios u
WHERE normalize_name_for_sicas(u.nombre_completo) = v_inverted
AND u.activo = true AND u.is_deleted = false
AND u.rol IN ('Agente','Gerente','Ejecutivo') LIMIT 1;
IF v_user_id IS NOT NULL THEN
v_confidence := 72; v_match_type := 'nombre_invertido';
v_match_details := jsonb_build_object('method','nombre_inv','original',v_rec.vend_nombre,'inverted',v_inverted);
v_nombre_inv_count := v_nombre_inv_count + 1;
END IF;
END IF;
END IF;

-- Insertar si hay match
IF v_user_id IS NOT NULL THEN
v_mapped_count := v_mapped_count + 1;
IF NOT p_dry_run THEN
INSERT INTO sicas_vendor_user_mappings (
vend_id, vend_nombre, desp_nombre,
movi_user_id, match_type, confidence_score, match_details,
status, total_docs, total_prima_neta, last_doc_date, mapped_at
) VALUES (
v_rec.vend_id, v_rec.vend_nombre, v_rec.desp_nombre,
v_user_id, v_match_type, v_confidence, v_match_details,
CASE WHEN v_confidence >= 80 THEN 'active' ELSE 'pending_review' END,
COALESCE(v_rec.total_docs,0), COALESCE(v_rec.total_prima,0), v_rec.last_doc, now()
) ON CONFLICT (vend_id) DO UPDATE SET
movi_user_id = EXCLUDED.movi_user_id,
match_type = EXCLUDED.match_type,
confidence_score = EXCLUDED.confidence_score,
status = EXCLUDED.status,
updated_at = now();

-- Actualizar usuario_id en documentos si confianza alta
IF v_confidence >= 80 THEN
UPDATE sicas_documents SET usuario_id = v_user_id
WHERE vend_id = v_rec.vend_id AND usuario_id IS NULL;
END IF;
END IF;
ELSE
-- Crear registro de pending sin usuario para revisión manual
IF NOT p_dry_run THEN
INSERT INTO sicas_vendor_user_mappings (
vend_id, vend_nombre, desp_nombre,
movi_user_id, match_type, confidence_score,
status, total_docs, total_prima_neta, last_doc_date, mapped_at
) VALUES (
v_rec.vend_id, v_rec.vend_nombre, v_rec.desp_nombre,
NULL, 'no_match', 0,
'pending_review', COALESCE(v_rec.total_docs,0), COALESCE(v_rec.total_prima,0), v_rec.last_doc, now()
) ON CONFLICT (vend_id) DO NOTHING;
END IF;
END IF;
END LOOP;

-- Actualizar ya_mapeados
SELECT COUNT(*) INTO v_already_mapped FROM sicas_vendor_user_mappings WHERE status = 'active';

RETURN jsonb_build_object(
'dry_run', p_dry_run,
'total_vendors_in_docs', v_total_vendors,
'newly_mapped', v_mapped_count,
'active_mappings_after', v_already_mapped,
'by_method', jsonb_build_object(
'id_sicas_exact', v_id_exact_count,
'nombre_sicas', v_nombre_sicas_count,
'nombre_normalizado', v_nombre_norm_count,
'nombre_invertido', v_nombre_inv_count
),
'run_at', now()
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.sicas_build_derived_aseguradoras()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_cnt integer;
BEGIN
INSERT INTO sicas_derived_aseguradoras (
nombre, nombre_normalizado, total_docs, total_vigentes, total_prima_neta, source_type, last_seen_in_docs
)
SELECT compania,
normalize_name_for_sicas(compania),
COUNT(*), COUNT(*) FILTER (WHERE is_vigente), COALESCE(SUM(prima_neta),0),
'derived', MAX(fecha_captura)
FROM sicas_documents
WHERE compania IS NOT NULL AND compania != ''
GROUP BY compania
ON CONFLICT (nombre) DO UPDATE SET
nombre_normalizado = EXCLUDED.nombre_normalizado,
total_docs = EXCLUDED.total_docs,
total_vigentes = EXCLUDED.total_vigentes,
total_prima_neta = EXCLUDED.total_prima_neta,
last_seen_in_docs = EXCLUDED.last_seen_in_docs,
updated_at = now();
GET DIAGNOSTICS v_cnt = ROW_COUNT;
RETURN jsonb_build_object('upserted', v_cnt, 'run_at', now());
END;
$function$
;

CREATE OR REPLACE FUNCTION public.sicas_fix_expired_vigentes(p_apply boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_count integer; v_anomalous integer;
BEGIN
SELECT COUNT(*) INTO v_count FROM sicas_documents
WHERE is_vigente = true AND vigencia_hasta < NOW()
AND vigencia_hasta > '1950-01-01' AND vigencia_hasta < '2100-01-01';

SELECT COUNT(*) INTO v_anomalous FROM sicas_documents
WHERE vigencia_hasta < '1950-01-01' OR vigencia_hasta > '2100-01-01'
OR vigencia_desde < '1950-01-01';

IF p_apply THEN
UPDATE sicas_documents SET is_vigente = false, updated_at = now()
WHERE is_vigente = true AND vigencia_hasta < NOW()
AND vigencia_hasta > '1950-01-01' AND vigencia_hasta < '2100-01-01';

INSERT INTO sicas_data_quality_log (check_type, records_checked, records_affected, records_fixed, fix_applied, details)
SELECT 'expired_vigentes', COUNT(*), v_count, v_count, true,
jsonb_build_object('fixed', v_count, 'anomalous', v_anomalous, 'ts', now())
FROM sicas_documents;
END IF;

RETURN jsonb_build_object(
'expired_vigentes_found', v_count, 'anomalous_dates', v_anomalous,
'fix_applied', p_apply, 'run_at', now()
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.sicas_get_health_report()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_cfg record; v_docs record; v_map record;
v_sync record; v_qual record; v_ren record;
BEGIN
SELECT * INTO v_cfg FROM sicas_config LIMIT 1;

SELECT COUNT(*) as total,
COUNT(*) FILTER (WHERE is_vigente) as vigentes,
COUNT(*) FILTER (WHERE is_renewable) as renovables,
COUNT(*) FILTER (WHERE usuario_id IS NOT NULL) as con_usuario,
COUNT(DISTINCT vend_id) as total_vendors,
MAX(synced_at) as last_sync
INTO v_docs FROM sicas_documents;

SELECT COUNT(*) as total,
COUNT(*) FILTER (WHERE status='active') as active_m,
COUNT(*) FILTER (WHERE status='pending_review') as pending_m,
COUNT(*) FILTER (WHERE movi_user_id IS NOT NULL) as with_user
INTO v_map FROM sicas_vendor_user_mappings;

SELECT
COUNT(*) FILTER (WHERE status='completed') as completed,
COUNT(*) FILTER (WHERE status='failed') as failed,
COUNT(*) FILTER (WHERE status='running' AND started_at < NOW()-INTERVAL'2h') as stuck,
MAX(finished_at) FILTER (WHERE status='completed') as last_ok,
MAX(finished_at) FILTER (WHERE status='failed') as last_fail
INTO v_sync FROM sicas_sync_jobs;

SELECT
COUNT(*) FILTER (WHERE is_vigente AND vigencia_hasta < NOW() AND vigencia_hasta > '1950-01-01' AND vigencia_hasta < '2100-01-01') as expired_v,
COUNT(*) FILTER (WHERE prima_neta IS NULL OR prima_neta=0) as sin_prima,
COUNT(*) FILTER (WHERE vigencia_hasta>'2100-01-01' OR vigencia_hasta<'1950-01-01') as anomalous,
COUNT(*) FILTER (WHERE cliente IS NULL OR cliente='') as sin_cliente
INTO v_qual FROM sicas_documents;

SELECT
COUNT(*) FILTER (WHERE vigencia_hasta BETWEEN NOW() AND NOW()+INTERVAL'30d' AND is_vigente AND vigencia_hasta>'1950-01-01' AND vigencia_hasta<'2100-01-01') as d30,
COUNT(*) FILTER (WHERE vigencia_hasta BETWEEN NOW() AND NOW()+INTERVAL'60d' AND is_vigente AND vigencia_hasta>'1950-01-01' AND vigencia_hasta<'2100-01-01') as d60,
COUNT(*) FILTER (WHERE vigencia_hasta BETWEEN NOW() AND NOW()+INTERVAL'90d' AND is_vigente AND vigencia_hasta>'1950-01-01' AND vigencia_hasta<'2100-01-01') as d90
INTO v_ren FROM sicas_documents;

RETURN jsonb_build_object(
'config', jsonb_build_object(
'endpoint', v_cfg.endpoint, 'use_rest', v_cfg.use_rest,
'keycode', v_cfg.current_report_code, 'auto_sync', v_cfg.auto_sync_enabled,
'local_first', v_cfg.local_first_mode,
'last_test_at', v_cfg.last_test_at, 'last_test_ok', v_cfg.last_test_success
),
'documents', jsonb_build_object(
'total', v_docs.total, 'vigentes', v_docs.vigentes, 'renovables', v_docs.renovables,
'con_usuario', v_docs.con_usuario, 'sin_usuario', v_docs.total - v_docs.con_usuario,
'total_vendors', v_docs.total_vendors,
'pct_mapeados', ROUND((v_docs.con_usuario::numeric / NULLIF(v_docs.total,0) * 100)::numeric, 2),
'last_sync', v_docs.last_sync
),
'vendor_mapping', jsonb_build_object(
'total_mappings', v_map.total, 'active', v_map.active_m,
'pending_review', v_map.pending_m, 'with_user', v_map.with_user,
'pct_vendors_mapped', ROUND((v_map.active_m::numeric / NULLIF(v_docs.total_vendors,0) * 100)::numeric, 2)
),
'sync_jobs', jsonb_build_object(
'completed', v_sync.completed, 'failed', v_sync.failed, 'stuck', v_sync.stuck,
'last_success', v_sync.last_ok, 'last_failure', v_sync.last_fail,
'hours_since_success', ROUND(EXTRACT(EPOCH FROM (NOW() - v_sync.last_ok)) / 3600)
),
'data_quality', jsonb_build_object(
'expired_vigentes', v_qual.expired_v, 'sin_prima', v_qual.sin_prima,
'anomalous_dates', v_qual.anomalous, 'sin_cliente', v_qual.sin_cliente
),
'renewals', jsonb_build_object('next_30d', v_ren.d30, 'next_60d', v_ren.d60, 'next_90d', v_ren.d90),
'generated_at', now()
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.sicas_sync_mapping_stats()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
UPDATE sicas_vendor_user_mappings m SET
total_docs = s.cnt, total_prima_neta = COALESCE(s.prima,0),
last_doc_date = s.last_doc, updated_at = now()
FROM (
SELECT vend_id, COUNT(*) as cnt, SUM(prima_neta) as prima, MAX(fecha_captura) as last_doc
FROM sicas_documents GROUP BY vend_id
) s WHERE m.vend_id = s.vend_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.soft_delete_gmm_quotation(p_quotation_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_user_id uuid;
v_owner_id uuid;
v_result json;
BEGIN
-- Get current authenticated user
v_user_id := auth.uid();

IF v_user_id IS NULL THEN
RETURN json_build_object(
'success', false,
'error', 'No authenticated user'
);
END IF;

-- Get the owner of the quotation
SELECT usuario_id INTO v_owner_id
FROM gmm_quotations
WHERE id = p_quotation_id;

IF v_owner_id IS NULL THEN
RETURN json_build_object(
'success', false,
'error', 'Quotation not found'
);
END IF;

-- Check ownership
IF v_owner_id != v_user_id THEN
RETURN json_build_object(
'success', false,
'error', 'You do not own this quotation'
);
END IF;

-- Perform soft delete
UPDATE gmm_quotations
SET deleted_at = now()
WHERE id = p_quotation_id;

RETURN json_build_object(
'success', true,
'message', 'Quotation soft deleted successfully'
);

EXCEPTION
WHEN OTHERS THEN
RETURN json_build_object(
'success', false,
'error', SQLERRM
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_agenda_booking_to_crm_and_reminders()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_owner_id uuid; v_event_name text; v_color text; v_offset integer; v_event_code text; v_recipient text;
BEGIN
 SELECT c.user_id,et.name,et.color INTO v_owner_id,v_event_name,v_color FROM agenda_event_types et JOIN agenda_calendars c ON c.id=et.calendar_id WHERE et.id=NEW.event_type_id;
 IF NEW.status='confirmed' THEN
  INSERT INTO dashboard_calendar_events(usuario_id,titulo,descripcion,fecha_inicio,fecha_fin,todo_el_dia,tipo_evento,color,entidad_tipo,entidad_id,metadata)
  VALUES(v_owner_id,v_event_name||' · '||NEW.guest_name,'Cita reservada desde Agenda',NEW.start_at,NEW.end_at,false,'reserva',COALESCE(v_color,'#2563eb'),'agenda_booking',NEW.id,jsonb_build_object('guest_name',NEW.guest_name,'guest_email',NEW.guest_email,'guest_phone',NEW.guest_phone,'location_type',NEW.location_type,'meeting_url',NEW.meeting_url,'agenda_event_type_id',NEW.event_type_id))
  ON CONFLICT(usuario_id,entidad_tipo,entidad_id) WHERE entidad_tipo='agenda_booking' DO UPDATE SET titulo=EXCLUDED.titulo,fecha_inicio=EXCLUDED.fecha_inicio,fecha_fin=EXCLUDED.fecha_fin,metadata=EXCLUDED.metadata,actualizado_en=now();
  FOR v_recipient,v_event_code IN SELECT * FROM (VALUES ('organizer'::text,'agenda_recordatorio_asesor'::text),('guest'::text,'agenda_recordatorio_invitado'::text)) AS recipients(recipient_type,event_code) LOOP
   FOR v_offset IN SELECT unnest(COALESCE((SELECT reminder_offsets_minutes FROM correo_tipos_notificacion WHERE codigo=v_event_code AND activo),'{}'::integer[])) LOOP
    INSERT INTO agenda_booking_reminders(booking_id,recipient_type,event_code,offset_minutes,scheduled_for) VALUES(NEW.id,v_recipient,v_event_code,v_offset,GREATEST(now(),NEW.start_at-make_interval(mins=>v_offset)))
    ON CONFLICT(booking_id,recipient_type,offset_minutes) DO UPDATE SET event_code=EXCLUDED.event_code,scheduled_for=EXCLUDED.scheduled_for,status=CASE WHEN agenda_booking_reminders.status='queued' THEN 'queued' ELSE 'pending' END,updated_at=now();
   END LOOP;
  END LOOP;
 ELSE
  UPDATE agenda_booking_reminders SET status='cancelled',updated_at=now() WHERE booking_id=NEW.id AND status IN ('pending','processing');
  DELETE FROM dashboard_calendar_events WHERE entidad_tipo='agenda_booking' AND entidad_id=NEW.id;
 END IF;
 RETURN NEW;
END;$function$
;

CREATE OR REPLACE FUNCTION public.sync_agent_tramite_team_assignments(p_user_id uuid, p_group_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor_id uuid := (select auth.uid());
  v_group record;
  v_existing_rule_id uuid;
begin
  if v_actor_id is null or not exists (
    select 1
    from public.usuarios actor
    where actor.id = v_actor_id
      and actor.rol = 'Administrador'
      and actor.activo = true
      and (actor.estado is null or lower(actor.estado) = 'activo')
  ) then
    raise exception 'Solo los administradores pueden asignar equipos responsables';
  end if;

  if not exists (
    select 1
    from public.usuarios target_user
    where target_user.id = p_user_id
      and target_user.rol = 'Agente'
  ) then
    raise exception 'Las asignaciones de atención solo aplican a usuarios con rol Agente';
  end if;

  if coalesce(cardinality(p_group_ids), 0) <> (
    select count(distinct selected_id)
    from unnest(coalesce(p_group_ids, array[]::uuid[])) selected_id
  ) then
    raise exception 'La selección contiene equipos duplicados';
  end if;

  if exists (
    select 1
    from unnest(coalesce(p_group_ids, array[]::uuid[])) selected_id
    left join public.tramites_grupos_visualizacion g
      on g.id = selected_id
     and g.activo = true
    where g.id is null
  ) then
    raise exception 'Uno o más equipos seleccionados no existen o están inactivos';
  end if;

  if exists (
    select 1
    from public.tramites_grupos_visualizacion g
    where g.id = any(coalesce(p_group_ids, array[]::uuid[]))
    group by lower(coalesce(g.area_categoria, ''))
    having count(*) > 1
  ) then
    raise exception 'Selecciona solo un equipo responsable por categoría';
  end if;

  if exists (
    select 1
    from (
      select distinct lower(coalesce(g.area_categoria, '')) as category_key
      from public.tramites_grupos_visualizacion g
      where g.activo = true
    ) active_category
    where not exists (
      select 1
      from public.tramites_grupos_visualizacion selected_group
      where selected_group.id = any(coalesce(p_group_ids, array[]::uuid[]))
        and lower(coalesce(selected_group.area_categoria, '')) = active_category.category_key
    )
  ) then
    raise exception 'El agente debe tener un equipo responsable en cada categoría activa';
  end if;

  for v_group in
    select g.id, g.area_categoria
    from public.tramites_grupos_visualizacion g
    where g.id = any(coalesce(p_group_ids, array[]::uuid[]))
  loop
    select r.id
      into v_existing_rule_id
    from public.tramites_grupos_reglas r
    where r.usuario_id = p_user_id
      and lower(coalesce(r.area, '')) = lower(coalesce(v_group.area_categoria, ''))
    order by r.activo desc, r.created_at desc
    limit 1;

    if v_existing_rule_id is null then
      insert into public.tramites_grupos_reglas (
        grupo_id, usuario_id, ejecutivo_id, area, activo, created_by
      ) values (
        v_group.id, p_user_id, null, v_group.area_categoria, true, v_actor_id
      );
    else
      update public.tramites_grupos_reglas
      set grupo_id = v_group.id,
          ejecutivo_id = case when grupo_id = v_group.id then ejecutivo_id else null end,
          area = v_group.area_categoria,
          activo = true
      where id = v_existing_rule_id;

      update public.tramites_grupos_reglas
      set activo = false
      where usuario_id = p_user_id
        and id <> v_existing_rule_id
        and activo = true
        and lower(coalesce(area, '')) = lower(coalesce(v_group.area_categoria, ''));
    end if;
  end loop;

  update public.tramites_grupos_reglas r
  set activo = false
  where r.usuario_id = p_user_id
    and r.activo = true
    and r.area is not null
    and not exists (
      select 1
      from public.tramites_grupos_visualizacion selected_group
      where selected_group.id = any(coalesce(p_group_ids, array[]::uuid[]))
        and lower(coalesce(selected_group.area_categoria, '')) = lower(r.area)
    );

  -- Defensa adicional: aunque existieran datos heredados, un Agente nunca
  -- permanece como miembro de un equipo.
  delete from public.tramites_grupos_miembros
  where usuario_id = p_user_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_all_channels_for_user(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_wazzup   jsonb;
v_personal jsonb;
v_chat     jsonb;
BEGIN
v_wazzup   := sync_wazzup_to_cc(p_user_id);
v_personal := sync_wa_personal_to_cc(p_user_id);
v_chat     := sync_chat_to_cc(p_user_id);
RETURN jsonb_build_object(
'wa_movi',     v_wazzup,
'wa_personal', v_personal,
'chat',        v_chat
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_all_production_mappings()
 RETURNS TABLE(total_mappings_applied integer, total_records_updated integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_mapping RECORD;
v_total_mappings integer := 0;
v_total_records integer := 0;
v_records_updated integer;
BEGIN
-- Iterar sobre todos los mapeos activos
FOR v_mapping IN
SELECT
'name:' || source_value as vendor_key,
movi_user_id
FROM vendor_mappings
WHERE source_type = 'name'
AND status = 'active'
LOOP
-- Aplicar mapeo
SELECT * INTO v_records_updated
FROM apply_vendor_mapping_to_production(
v_mapping.vendor_key,
v_mapping.movi_user_id
);

IF v_records_updated > 0 THEN
v_total_mappings := v_total_mappings + 1;
v_total_records := v_total_records + v_records_updated;
END IF;
END LOOP;

RETURN QUERY SELECT v_total_mappings, v_total_records;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_auth_email_from_email_laboral()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_auth_email text;
BEGIN
IF NEW.email_laboral IS NOT NULL 
AND NEW.email_laboral != '' 
AND (OLD IS NULL OR OLD.email_laboral IS NULL OR OLD.email_laboral != NEW.email_laboral) THEN

SELECT email::text INTO v_auth_email
FROM auth.users
WHERE id = NEW.id;

IF v_auth_email IS NOT NULL AND v_auth_email != NEW.email_laboral THEN
RAISE LOG '[sync_email] % -> %', v_auth_email, NEW.email_laboral;

UPDATE auth.users
SET 
email = NEW.email_laboral,
email_confirmed_at = CASE 
WHEN email_confirmed_at IS NULL THEN NULL 
ELSE NOW() 
END,
updated_at = NOW()
WHERE id = NEW.id;
END IF;
END IF;

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_borrado_mapeo_agente()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_vend_id text;
BEGIN
  SELECT vend_id INTO v_vend_id FROM maestro_agentes WHERE id = OLD.agente_id;
  IF v_vend_id IS NULL THEN RETURN OLD; END IF;

  UPDATE sicas_vendor_user_mappings
  SET movi_user_id = NULL, updated_at = now()
  WHERE vend_id = v_vend_id AND movi_user_id = OLD.user_id;

  UPDATE usuarios SET id_sicas = NULL, nombre_sicas = NULL
  WHERE id = OLD.user_id AND id_sicas = v_vend_id;

  RETURN OLD;
END $function$
;

CREATE OR REPLACE FUNCTION public.sync_chat_to_cc(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_chat         RECORD;
v_msg          RECORD;
v_cc_conv_id   uuid;
v_office_id    uuid;
v_peer_name    text;
v_upserted     integer := 0;
v_skipped      integer := 0;
BEGIN
SELECT oficina_id INTO v_office_id FROM usuarios WHERE id = p_user_id;

FOR v_chat IN
SELECT c.id, c.nombre, c.tipo, c.ultimo_mensaje_at,
cm.unido_at
FROM chats c
JOIN chat_miembros cm ON cm.chat_id = c.id AND cm.usuario_id = p_user_id
WHERE c.eliminado IS NOT TRUE
LOOP
-- Get peer name for direct chats
IF v_chat.tipo = 'direct' THEN
SELECT CONCAT(u.nombre, ' ', u.apellidos)
INTO v_peer_name
FROM chat_miembros cm
JOIN usuarios u ON u.id = cm.usuario_id
WHERE cm.chat_id = v_chat.id AND cm.usuario_id <> p_user_id
LIMIT 1;
ELSE
v_peer_name := v_chat.nombre;
END IF;

INSERT INTO cc_conversations (
owner_user_id, office_id, channel, external_conversation_id,
contact_name, last_message_at, is_group, group_name, status
) VALUES (
p_user_id, v_office_id, 'chat', v_chat.id::text,
v_peer_name, v_chat.ultimo_mensaje_at,
v_chat.tipo = 'group', v_chat.nombre,
'open'
)
ON CONFLICT (owner_user_id, channel, external_conversation_id)
DO UPDATE SET
contact_name    = COALESCE(EXCLUDED.contact_name, cc_conversations.contact_name),
last_message_at = GREATEST(cc_conversations.last_message_at, EXCLUDED.last_message_at),
updated_at      = now()
RETURNING id INTO v_cc_conv_id;

IF v_cc_conv_id IS NULL THEN
SELECT id INTO v_cc_conv_id FROM cc_conversations
WHERE owner_user_id = p_user_id AND channel = 'chat'
AND external_conversation_id = v_chat.id::text;
END IF;

FOR v_msg IN
SELECT m.id, m.remitente_id, m.mensaje, m.created_at, m.eliminado
FROM chat_mensajes m
WHERE m.chat_id = v_chat.id
AND (m.eliminado IS NOT TRUE)
ORDER BY m.created_at ASC
LOOP
INSERT INTO cc_messages (
conversation_id, channel, external_message_id, direction,
message_type, body, sender_user_id,
sent_at, status, raw_payload
) VALUES (
v_cc_conv_id, 'chat', v_msg.id::text,
CASE WHEN v_msg.remitente_id = p_user_id THEN 'outbound' ELSE 'inbound' END,
'text', v_msg.mensaje, v_msg.remitente_id,
v_msg.created_at, 'sent',
jsonb_build_object('original_id', v_msg.id)
)
ON CONFLICT (conversation_id, external_message_id) DO NOTHING;

IF FOUND THEN v_upserted := v_upserted + 1;
ELSE v_skipped := v_skipped + 1;
END IF;
END LOOP;

-- Update last_message text from latest message
UPDATE cc_conversations
SET last_message = (
SELECT body FROM cc_messages
WHERE conversation_id = v_cc_conv_id
ORDER BY sent_at DESC LIMIT 1
)
WHERE id = v_cc_conv_id;
END LOOP;

RETURN jsonb_build_object('channel','chat','upserted',v_upserted,'skipped',v_skipped);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_correo_template_to_transactional()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_codigo text; v_nombre text;
BEGIN
  SELECT codigo, nombre INTO v_codigo, v_nombre FROM correo_tipos_notificacion WHERE id = NEW.tipo_notificacion_id;
  IF v_codigo IS NOT NULL AND EXISTS (SELECT 1 FROM transactional_notification_templates WHERE event_key = v_codigo) THEN
    UPDATE transactional_notification_templates
    SET name = v_nombre,
        email_subject_template = NEW.asunto,
        email_body_template = NEW.html_cuerpo,
        whatsapp_body_template = COALESCE(NEW.whatsapp_plantilla, ''),
        inapp_title_template = COALESCE(NEW.notificacion_titulo, ''),
        inapp_body_template = COALESCE(NEW.notificacion_cuerpo, ''),
        is_active = true,
        updated_at = now()
    WHERE event_key = v_codigo;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_desenlace_sicas()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.movi_user_id IS NULL OR NEW.movi_user_id IS NOT DISTINCT FROM OLD.movi_user_id THEN
    RETURN NEW;
  END IF;

  DELETE FROM maestro_usuario_agente m
  USING maestro_agentes a
  WHERE m.agente_id = a.id
    AND m.user_id = OLD.movi_user_id
    AND a.vend_id = OLD.vend_id;

  RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.sync_express_lead_contact_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.crm_contacto_id IS NOT NULL AND NEW.agente_asignado_id IS NOT NULL THEN
    UPDATE public.crm_contactos
       SET agente_id = NEW.agente_asignado_id,
           actualizado_en = now()
     WHERE id = NEW.crm_contacto_id
       AND agente_id IS DISTINCT FROM NEW.agente_asignado_id;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_mapeo_agente_a_sicas()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  a record;
BEGIN
  IF NOT NEW.activo THEN RETURN NEW; END IF;

  SELECT nombre, vend_id INTO a FROM maestro_agentes WHERE id = NEW.agente_id;
  -- Un agente creado a mano para un usuario MOVI no tiene contraparte en SICAS.
  IF a.vend_id IS NULL THEN RETURN NEW; END IF;

  -- Los `IS DISTINCT FROM` no son adorno: cortan el ida y vuelta entre este
  -- trigger, el de abajo y el que ya existía sobre `usuarios.id_sicas`.
  UPDATE usuarios
  SET id_sicas = a.vend_id,
      nombre_sicas = coalesce(nombre_sicas, a.nombre)
  WHERE id = NEW.user_id AND id_sicas IS DISTINCT FROM a.vend_id;

  UPDATE sicas_vendor_user_mappings
  SET movi_user_id = NEW.user_id, updated_at = now()
  WHERE vend_id = a.vend_id AND movi_user_id IS DISTINCT FROM NEW.user_id;

  RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.sync_nombre_sicas_on_mapping()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
-- Cuando se crea o actualiza un mapeo, sincronizar nombre_sicas en usuarios
IF TG_TABLE_NAME = 'sicas_mapeo_vendedor_usuario' THEN
UPDATE usuarios
SET nombre_sicas = (
SELECT nombre 
FROM sicas_vendedores 
WHERE id_sicas = NEW.id_sicas_vendedor
)
WHERE id = NEW.movi_user_id;
END IF;

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_nombre_sicas_to_vendor_mapping()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_normalized_name TEXT;
  v_normalized_id TEXT;
  v_sicas_mapping_id UUID;
BEGIN
  IF OLD.nombre_sicas IS NOT DISTINCT FROM NEW.nombre_sicas AND OLD.id_sicas IS NOT DISTINCT FROM NEW.id_sicas THEN
    RETURN NEW;
  END IF;

  IF (NEW.nombre_sicas IS NULL OR TRIM(NEW.nombre_sicas) = '') AND (NEW.id_sicas IS NULL OR TRIM(NEW.id_sicas) = '') THEN
    UPDATE vendor_mappings
    SET status = 'inactive', updated_at = NOW()
    WHERE movi_user_id = NEW.id
      AND status = 'active';

    UPDATE sicas_vendor_user_mappings
    SET movi_user_id = NULL,
        status = 'pending_review',
        updated_at = NOW()
    WHERE movi_user_id = NEW.id;

    BEGIN
      IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'sicas_mapeo_vendedor_usuario') THEN
        DELETE FROM sicas_mapeo_vendedor_usuario WHERE movi_user_id = NEW.id;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;

    RETURN NEW;
  END IF;

  IF NEW.id_sicas IS NOT NULL AND TRIM(NEW.id_sicas) != '' THEN
    SELECT id INTO v_sicas_mapping_id
    FROM sicas_vendor_user_mappings
    WHERE vend_id = TRIM(NEW.id_sicas)
    LIMIT 1;

    IF v_sicas_mapping_id IS NOT NULL THEN
      UPDATE sicas_vendor_user_mappings
      SET movi_user_id = NEW.id,
          status = 'active',
          match_type = 'user_sync',
          confidence_score = 100,
          updated_at = NOW()
      WHERE id = v_sicas_mapping_id;
    END IF;

    v_normalized_id := LOWER(TRIM(NEW.id_sicas));
    INSERT INTO vendor_mappings (source_type, source_value, movi_user_id, status, notes)
    VALUES ('id', v_normalized_id, NEW.id, 'active', 'auto-sync id_sicas')
    ON CONFLICT (source_type, source_value) WHERE status = 'active'
    DO UPDATE SET
      movi_user_id = EXCLUDED.movi_user_id,
      updated_at = NOW(),
      notes = 'auto-sync id_sicas';

    BEGIN
      IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'sicas_mapeo_vendedor_usuario') THEN
        INSERT INTO sicas_mapeo_vendedor_usuario (id_sicas_vendedor, movi_user_id, mapped_at)
        VALUES (TRIM(NEW.id_sicas), NEW.id, NOW())
        ON CONFLICT (id_sicas_vendedor)
        DO UPDATE SET
          movi_user_id = EXCLUDED.movi_user_id,
          mapped_at = NOW(),
          updated_at = NOW();
      END IF;
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;

  IF NEW.nombre_sicas IS NOT NULL AND TRIM(NEW.nombre_sicas) != '' THEN
    v_normalized_name := LOWER(TRIM(
      REGEXP_REPLACE(
        TRANSLATE(NEW.nombre_sicas, 'ÁÉÍÓÚÜÑáéíóúüñ', 'AEIOUUNaeiouun'),
        '\s+', ' ', 'g'
      )
    ));

    INSERT INTO vendor_mappings (source_type, source_value, movi_user_id, status, notes)
    VALUES ('name', v_normalized_name, NEW.id, 'active', 'auto-sync nombre_sicas')
    ON CONFLICT (source_type, source_value) WHERE status = 'active'
    DO UPDATE SET
      movi_user_id = EXCLUDED.movi_user_id,
      updated_at = NOW(),
      notes = 'auto-sync nombre_sicas';

    IF v_sicas_mapping_id IS NULL THEN
      UPDATE sicas_vendor_user_mappings
      SET movi_user_id = NEW.id,
          match_type = 'nombre_sicas_sync',
          confidence_score = 95,
          status = 'active',
          match_details = jsonb_build_object('method', 'nombre_sicas_sync', 'synced_at', NOW()),
          updated_at = NOW()
      WHERE (status = 'pending_review' OR movi_user_id IS NULL)
        AND similarity(UPPER(vend_nombre), UPPER(NEW.nombre_sicas)) >= 0.75;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_notification_type_to_delivery_catalog()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF EXISTS (SELECT 1 FROM notification_events_catalog WHERE event_code = NEW.codigo) THEN
    UPDATE notification_events_catalog
    SET event_name = NEW.nombre,
        module = lower(COALESCE(NEW.modulo, 'sistema')),
        description = NEW.descripcion,
        enable_in_app = COALESCE(NEW.enviar_notificacion, false),
        enable_email = COALESCE(NEW.enviar_correo, false),
        enable_whatsapp = COALESCE(NEW.enviar_whatsapp, false),
        active = COALESCE(NEW.activo, true),
        updated_at = now()
    WHERE event_code = NEW.codigo;
  END IF;
  RETURN NEW;
END;
$function$
;

