 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
-- Insert or update commission office
INSERT INTO commission_offices (
oficina_id,
name,
created_at
) VALUES (
NEW.id,
NEW.nombre,
NOW()
)
ON CONFLICT (oficina_id) 
DO UPDATE SET
name = EXCLUDED.name;

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_reserva_fechas()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
-- Si se insertan/actualizan fecha y hora separadas, construir fecha_inicio/fecha_fin
IF NEW.fecha IS NOT NULL AND NEW.hora_inicio IS NOT NULL THEN
NEW.fecha_inicio := (NEW.fecha || ' ' || NEW.hora_inicio)::timestamptz;
END IF;

IF NEW.fecha IS NOT NULL AND NEW.hora_fin IS NOT NULL THEN
NEW.fecha_fin := (NEW.fecha || ' ' || NEW.hora_fin)::timestamptz;
END IF;

-- Sincronizar notas con motivo
IF NEW.notas IS NOT NULL THEN
NEW.motivo := NEW.notas;
END IF;

RETURN NEW;
END;
$function$
;

