$function$
;

CREATE OR REPLACE FUNCTION public.sync_seguwallet_template_to_transactional()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_codigo text;
BEGIN
-- Get the notification type code
SELECT codigo INTO v_codigo
FROM correo_tipos_notificacion
WHERE id = NEW.tipo_notificacion_id;

-- Only sync seguwallet templates that exist in transactional_notification_templates
IF v_codigo IS NOT NULL AND EXISTS (
SELECT 1 FROM transactional_notification_templates WHERE event_key = v_codigo
) THEN
UPDATE transactional_notification_templates
SET
whatsapp_body_template = COALESCE(NEW.whatsapp_plantilla, whatsapp_body_template),
inapp_title_template   = COALESCE(NEW.notificacion_titulo, inapp_title_template),
inapp_body_template    = COALESCE(NEW.notificacion_cuerpo, inapp_body_template),
updated_at             = now()
WHERE event_key = v_codigo;
END IF;

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_sicas_a_mapeo_agente()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_agente uuid;
BEGIN
  IF NEW.movi_user_id IS NULL OR NEW.vend_id IS NULL THEN RETURN NEW; END IF;

  SELECT id INTO v_agente FROM maestro_agentes WHERE vend_id = NEW.vend_id;

  -- ¿Ya estaba en el catálogo del Excel, sin su ID de SICAS? Se le pone.
  IF v_agente IS NULL THEN
    SELECT id INTO v_agente FROM maestro_agentes
     WHERE vend_id IS NULL
       AND nombre_comparable(nombre) = nombre_comparable(NEW.vend_nombre)
     ORDER BY es_primario DESC NULLS LAST
     LIMIT 1;
    IF v_agente IS NOT NULL THEN
      UPDATE maestro_agentes SET vend_id = NEW.vend_id WHERE id = v_agente;
    END IF;
  END IF;

  -- Y si no estaba, entra. Un vendedor que alguien enlazó a mano tiene que
  -- existir en el catálogo que leen los trámites, o el enlace no sirve de nada.
  IF v_agente IS NULL THEN
    BEGIN
      INSERT INTO maestro_agentes (nombre, vend_id, origen, activo, despacho_id)
      VALUES (
        NEW.vend_nombre, NEW.vend_id, 'sicas', true,
        (SELECT id FROM maestro_despachos
          WHERE nombre_comparable(nombre) = nombre_comparable(NEW.desp_nombre) LIMIT 1)
      )
      RETURNING id INTO v_agente;
    EXCEPTION WHEN unique_violation THEN
      -- Choca con UNIQUE (nombre, despacho_id): es el mismo, se reutiliza.
      SELECT id INTO v_agente FROM maestro_agentes
       WHERE nombre_comparable(nombre) = nombre_comparable(NEW.vend_nombre) LIMIT 1;
    END;
  END IF;

  IF v_agente IS NULL THEN RETURN NEW; END IF;

  INSERT INTO maestro_usuario_agente (user_id, agente_id, activo)
  VALUES (NEW.movi_user_id, v_agente, true)
  ON CONFLICT (user_id) DO UPDATE
    SET agente_id = EXCLUDED.agente_id, activo = true, updated_at = now()
    WHERE maestro_usuario_agente.agente_id IS DISTINCT FROM EXCLUDED.agente_id
       OR maestro_usuario_agente.activo IS DISTINCT FROM true;

  RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.sync_sicas_despachos()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
IF NEW.catalog_type_id = 11 THEN
INSERT INTO sicas_despachos (id_sicas, nombre, raw, created_at, updated_at)
VALUES (NEW.id_sicas, NEW.nombre, NEW.raw, NEW.created_at, NEW.updated_at)
ON CONFLICT (id_sicas) DO UPDATE SET
nombre = EXCLUDED.nombre,
raw = EXCLUDED.raw,
updated_at = EXCLUDED.updated_at;
END IF;
RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_sicas_mapping_to_vendor_mappings()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
vendor_nombre TEXT;
normalized_nombre TEXT;
BEGIN
-- Obtener el nombre del vendedor desde sicas_catalogos
SELECT nombre INTO vendor_nombre
FROM sicas_catalogos
WHERE catalog_type_id = NEW.catalog_type_id
AND id_sicas = NEW.id_sicas_vendedor
LIMIT 1;

IF vendor_nombre IS NULL THEN
-- Si no se encuentra en catálogos, no hacer nada
RETURN NEW;
END IF;

-- Normalizar el nombre
normalized_nombre := normalize_name(vendor_nombre);

IF normalized_nombre IS NULL OR normalized_nombre = '' THEN
RETURN NEW;
END IF;

-- Verificar si ya existe un mapeo activo para este nombre
IF EXISTS (
SELECT 1 FROM vendor_mappings
WHERE source_type = 'name'
AND source_value = normalized_nombre
AND status = 'active'
) THEN
-- Actualizar el mapeo existente
UPDATE vendor_mappings
SET 
movi_user_id = NEW.movi_user_id,
updated_by = NEW.mapped_by,
updated_at = NOW(),
notes = COALESCE(notes, '') || ' | Sincronizado desde SICAS mapeo vendedor ID: ' || NEW.id_sicas_vendedor
WHERE source_type = 'name'
AND source_value = normalized_nombre
AND status = 'active';
ELSE
-- Crear nuevo mapeo
INSERT INTO vendor_mappings (
source_type,
source_value,
movi_user_id,
status,
created_by,
notes
) VALUES (
'name',
normalized_nombre,
NEW.movi_user_id,
'active',
NEW.mapped_by,
'Sincronizado desde SICAS mapeo vendedor ID: ' || NEW.id_sicas_vendedor
);
END IF;

-- Actualizar el flag is_mapped en sicas_catalogos
UPDATE sicas_catalogos
SET is_mapped = true
WHERE catalog_type_id = NEW.catalog_type_id
AND id_sicas = NEW.id_sicas_vendedor;

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_tarea_completada()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
IF NEW.estatus = 'Completada' AND (OLD.estatus IS NULL OR OLD.estatus != 'Completada') THEN
NEW.completada := true;
NEW.fecha_completado := now();
END IF;

IF NEW.estatus != 'Completada' AND OLD.estatus = 'Completada' THEN
NEW.completada := false;
NEW.fecha_completado := NULL;
END IF;

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_usuario_contactos_oficina()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.oficina_id IS NULL THEN
    RAISE EXCEPTION 'Un usuario propietario de contactos debe tener oficina';
  END IF;

  UPDATE public.crm_contactos
     SET oficina_id = NEW.oficina_id,
         actualizado_en = now()
   WHERE agente_id = NEW.id
     AND oficina_id IS DISTINCT FROM NEW.oficina_id;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_usuario_metadata()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
-- Calcular nombre_completo en lugar de leerlo
UPDATE auth.users
SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || 
jsonb_build_object(
'rol', NEW.rol,
'oficina_id', NEW.oficina_id,
'nombre_completo', (NEW.nombre || ' ' || NEW.apellidos)
)
WHERE id = NEW.id;

RETURN NEW;
EXCEPTION
WHEN OTHERS THEN
-- Si falla, continuar sin error para no bloquear el INSERT
RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_usuario_nombre_norm()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
NEW.nombre_completo_norm := normalize_person_name(NEW.nombre_completo);
RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_usuario_sicas_data()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
IF TG_TABLE_NAME = 'sicas_mapeo_vendedor_usuario' THEN
UPDATE usuarios
SET 
nombre_sicas = (SELECT nombre FROM sicas_vendedores WHERE id_sicas = NEW.id_sicas_vendedor),
id_sicas = NEW.id_sicas_vendedor
WHERE id = NEW.movi_user_id;
END IF;

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_wa_personal_to_cc(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_conv         RECORD;
v_msg          RECORD;
v_cc_conv_id   uuid;
v_office_id    uuid;
v_upserted     integer := 0;
v_skipped      integer := 0;
BEGIN
SELECT oficina_id INTO v_office_id FROM usuarios WHERE id = p_user_id;

FOR v_conv IN
SELECT c.id, c.remote_phone, c.remote_name, c.remote_avatar_url,
c.last_message_text, c.last_message_at, c.unread_count, c.is_group, c.group_name
FROM whatsapp_conversations c
JOIN whatsapp_sessions s ON s.id = c.session_id
WHERE s.user_id = p_user_id
LOOP
INSERT INTO cc_conversations (
owner_user_id, office_id, channel, external_conversation_id,
contact_name, contact_phone, avatar_url,
last_message, last_message_at, unread_count,
is_group, group_name, status
) VALUES (
p_user_id, v_office_id, 'wa_personal', v_conv.id::text,
COALESCE(v_conv.group_name, v_conv.remote_name), v_conv.remote_phone,
v_conv.remote_avatar_url,
v_conv.last_message_text, v_conv.last_message_at, v_conv.unread_count,
v_conv.is_group, v_conv.group_name, 'open'
)
ON CONFLICT (owner_user_id, channel, external_conversation_id)
DO UPDATE SET
contact_name    = COALESCE(EXCLUDED.contact_name, cc_conversations.contact_name),
avatar_url      = COALESCE(EXCLUDED.avatar_url, cc_conversations.avatar_url),
last_message    = CASE WHEN EXCLUDED.last_message_at >= cc_conversations.last_message_at
THEN EXCLUDED.last_message ELSE cc_conversations.last_message END,
last_message_at = GREATEST(cc_conversations.last_message_at, EXCLUDED.last_message_at),
unread_count    = EXCLUDED.unread_count,
updated_at      = now()
RETURNING id INTO v_cc_conv_id;

IF v_cc_conv_id IS NULL THEN
SELECT id INTO v_cc_conv_id FROM cc_conversations
WHERE owner_user_id = p_user_id AND channel = 'wa_personal'
AND external_conversation_id = v_conv.id::text;
END IF;

FOR v_msg IN
SELECT m.id, m.direction, m.message_type, m.content, m.media_url,
m.media_mime_type, m.media_filename, m.media_thumbnail_url,
m.status, m.created_at, m.message_timestamp
FROM whatsapp_messages m
WHERE m.conversation_id = v_conv.id
ORDER BY m.created_at ASC
LOOP
INSERT INTO cc_messages (
conversation_id, channel, external_message_id, direction,
message_type, body, media_url, media_mime_type, media_filename,
media_thumbnail_url,
sender_user_id, sent_at, status,
raw_payload
) VALUES (
v_cc_conv_id, 'wa_personal', v_msg.id::text, v_msg.direction,
COALESCE(v_msg.message_type, 'text'),
v_msg.content, v_msg.media_url, v_msg.media_mime_type, v_msg.media_filename,
v_msg.media_thumbnail_url,
CASE WHEN v_msg.direction = 'outbound' THEN p_user_id ELSE NULL END,
COALESCE(v_msg.message_timestamp, v_msg.created_at),
COALESCE(v_msg.status, 'sent'),
jsonb_build_object('original_id', v_msg.id)
)
ON CONFLICT (conversation_id, external_message_id) DO NOTHING;

IF FOUND THEN v_upserted := v_upserted + 1;
ELSE v_skipped := v_skipped + 1;
END IF;
END LOOP;
END LOOP;

RETURN jsonb_build_object('channel','wa_personal','upserted',v_upserted,'skipped',v_skipped);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_wazzup_to_cc(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_msg          RECORD;
v_conv_id      uuid;
v_office_id    uuid;
v_conv_phone   text;
v_upserted     integer := 0;
v_skipped      integer := 0;
BEGIN
SELECT oficina_id INTO v_office_id FROM usuarios WHERE id = p_user_id;

FOR v_msg IN
SELECT
m.id,
m.agent_user_id,
m.direction,
m.body,
m.created_at,
m.status,
m.provider_message_id,
m.contact_phone,
m.contact_name,
m.metadata,
m.attachment_urls,
m.read_at
FROM contact_center_messages m
WHERE m.agent_user_id = p_user_id
AND m.channel = 'whatsapp'
AND m.provider = 'wazzup'
ORDER BY m.created_at ASC
LOOP
v_conv_phone := COALESCE(v_msg.contact_phone, (v_msg.metadata->>'chat_id')::text, 'unknown');

-- Upsert conversation
INSERT INTO cc_conversations (
owner_user_id, office_id, channel, external_conversation_id,
contact_name, contact_phone,
last_message, last_message_at, status
) VALUES (
p_user_id, v_office_id, 'wa_movi', v_conv_phone,
v_msg.contact_name, v_conv_phone,
v_msg.body, v_msg.created_at, 'open'
)
ON CONFLICT (owner_user_id, channel, external_conversation_id)
DO UPDATE SET
last_message    = CASE WHEN EXCLUDED.last_message_at >= cc_conversations.last_message_at THEN EXCLUDED.last_message ELSE cc_conversations.last_message END,
last_message_at = GREATEST(cc_conversations.last_message_at, EXCLUDED.last_message_at),
contact_name    = COALESCE(EXCLUDED.contact_name, cc_conversations.contact_name),
updated_at      = now()
RETURNING id INTO v_conv_id;

IF v_conv_id IS NULL THEN
SELECT id INTO v_conv_id FROM cc_conversations
WHERE owner_user_id = p_user_id AND channel = 'wa_movi' AND external_conversation_id = v_conv_phone;
END IF;

-- Insert message (ignore duplicates)
INSERT INTO cc_messages (
conversation_id, channel, external_message_id, direction,
message_type, body, sender_name, sender_user_id,
sent_at, status, raw_payload
) VALUES (
v_conv_id, 'wa_movi',
COALESCE(v_msg.provider_message_id, v_msg.id::text),
v_msg.direction,
'text', v_msg.body,
CASE WHEN v_msg.direction = 'inbound' THEN v_msg.contact_name ELSE NULL END,
CASE WHEN v_msg.direction = 'outbound' THEN p_user_id ELSE NULL END,
v_msg.created_at, v_msg.status,
jsonb_build_object('original_id', v_msg.id)
)
ON CONFLICT (conversation_id, external_message_id) DO NOTHING;

IF FOUND THEN v_upserted := v_upserted + 1;
ELSE v_skipped := v_skipped + 1;
END IF;
END LOOP;

RETURN jsonb_build_object('channel','wa_movi','upserted',v_upserted,'skipped',v_skipped);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.test_asimilados_con_caso_real(p_vida numeric, p_sin_vida numeric, p_ret_contable_esperado numeric, p_dispersion_esperada numeric, p_isr_total_esperado numeric, p_total_esperado numeric)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
v_ret_contable NUMERIC;
v_dispersion NUMERIC;
v_isr_vida NUMERIC;
v_isr_danios NUMERIC;
v_isr_total NUMERIC;
v_total NUMERIC;
v_total_comision NUMERIC;
v_tolerance NUMERIC := 0.10; -- Tolerancia de 10 centavos
v_resultado TEXT := '';
BEGIN
v_total_comision := p_vida + p_sin_vida;

v_resultado := v_resultado || E'\n========================================\n';
v_resultado := v_resultado || 'TEST DE CASO REAL ASIMILADOS\n';
v_resultado := v_resultado || E'========================================\n';
v_resultado := v_resultado || 'ENTRADA:\n';
v_resultado := v_resultado || '  Vida: ' || p_vida || E'\n';
v_resultado := v_resultado || '  Sin Vida: ' || p_sin_vida || E'\n';
v_resultado := v_resultado || '  Total Comisión: ' || v_total_comision || E'\n';

-- Calcular con fórmulas actuales
v_ret_contable := ROUND((p_vida * 0.16)::numeric, 2);
v_dispersion := ROUND((p_sin_vida * 0.09)::numeric, 2);
v_isr_vida := ROUND(((p_vida - v_ret_contable) * 0.10)::numeric, 2);
v_isr_danios := ROUND(((p_sin_vida - v_dispersion) * 0.10)::numeric, 2);
v_isr_total := ROUND((v_isr_vida + v_isr_danios)::numeric, 2);
v_total := ROUND((v_total_comision - v_ret_contable - v_dispersion - v_isr_total)::numeric, 2);

v_resultado := v_resultado || E'\nCALCULADO:\n';
v_resultado := v_resultado || '  Ret. Contable: ' || v_ret_contable || E'\n';
v_resultado := v_resultado || '  Dispersión: ' || v_dispersion || E'\n';
v_resultado := v_resultado || '  ISR Vida: ' || v_isr_vida || E'\n';
v_resultado := v_resultado || '  ISR Daños: ' || v_isr_danios || E'\n';
v_resultado := v_resultado || '  ISR Total: ' || v_isr_total || E'\n';
v_resultado := v_resultado || '  Total a Pagar: ' || v_total || E'\n';

v_resultado := v_resultado || E'\nESPERADO:\n';
v_resultado := v_resultado || '  Ret. Contable: ' || p_ret_contable_esperado || E'\n';
v_resultado := v_resultado || '  Dispersión: ' || p_dispersion_esperada || E'\n';
v_resultado := v_resultado || '  ISR Total: ' || p_isr_total_esperado || E'\n';
v_resultado := v_resultado || '  Total a Pagar: ' || p_total_esperado || E'\n';

v_resultado := v_resultado || E'\nDIFERENCIAS:\n';
v_resultado := v_resultado || '  Ret. Contable: ' || ABS(v_ret_contable - p_ret_contable_esperado) || E'\n';
v_resultado := v_resultado || '  Dispersión: ' || ABS(v_dispersion - p_dispersion_esperada) || E'\n';
v_resultado := v_resultado || '  ISR Total: ' || ABS(v_isr_total - p_isr_total_esperado) || E'\n';
v_resultado := v_resultado || '  Total: ' || ABS(v_total - p_total_esperado) || E'\n';

v_resultado := v_resultado || E'\nRESULTADO: ';

IF ABS(v_isr_total - p_isr_total_esperado) > v_tolerance THEN
v_resultado := v_resultado || '❌ FALLIDO - ISR Total no coincide (diff: ' || 
ABS(v_isr_total - p_isr_total_esperado) || ')' || E'\n';
ELSIF ABS(v_total - p_total_esperado) > v_tolerance THEN
v_resultado := v_resultado || '❌ FALLIDO - Total no coincide (diff: ' || 
ABS(v_total - p_total_esperado) || ')' || E'\n';
ELSE
v_resultado := v_resultado || '✅ PASADO' || E'\n';
END IF;

v_resultado := v_resultado || E'========================================\n';

RETURN v_resultado;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.test_fiscal_calculation(p_regimen_fiscal text, p_commission_vida numeric, p_commission_sinvida numeric)
 RETURNS TABLE(concepto text, valor numeric, formula text)
 LANGUAGE plpgsql
AS $function$
DECLARE
v_commission_total NUMERIC;
v_iva NUMERIC;
v_subtotal_con_iva NUMERIC;
v_ret_isr NUMERIC;
v_ret_iva NUMERIC;
v_total_neto NUMERIC;
v_regimen TEXT;
BEGIN
v_regimen := UPPER(p_regimen_fiscal);
v_commission_total := p_commission_vida + p_commission_sinvida;

IF v_regimen = 'HONORARIOS' THEN
-- HONORARIOS
v_iva := p_commission_sinvida * 0.16;
v_subtotal_con_iva := v_commission_total + v_iva;
v_ret_isr := v_subtotal_con_iva * 0.10;
v_ret_iva := v_iva * (2.0 / 3.0);
v_total_neto := v_subtotal_con_iva - v_ret_isr - v_ret_iva;

RETURN QUERY
SELECT 'Commission Vida'::TEXT, ROUND(p_commission_vida, 2), ''::TEXT
UNION ALL
SELECT 'Commission Sin Vida'::TEXT, ROUND(p_commission_sinvida, 2), ''::TEXT
UNION ALL
SELECT 'Commission Total'::TEXT, ROUND(v_commission_total, 2), 'Vida + Sin Vida'::TEXT
UNION ALL
SELECT 'IVA (16%)'::TEXT, ROUND(v_iva, 2), 'Sin Vida × 0.16'::TEXT
UNION ALL
SELECT 'Subtotal con IVA'::TEXT, ROUND(v_subtotal_con_iva, 2), 'Total + IVA'::TEXT
UNION ALL
SELECT 'Ret ISR (10%)'::TEXT, ROUND(v_ret_isr, 2), '(Total + IVA) × 0.10'::TEXT
UNION ALL
SELECT 'Ret IVA (2/3)'::TEXT, ROUND(v_ret_iva, 2), 'IVA × (2/3)'::TEXT
UNION ALL
SELECT '=== TOTAL NETO ==='::TEXT, ROUND(v_total_neto, 2), 'Subtotal - Ret ISR - Ret IVA'::TEXT;

ELSIF v_regimen = 'RESICO' THEN
-- RESICO
v_iva := p_commission_sinvida * 0.16;
v_subtotal_con_iva := v_commission_total + v_iva;
v_ret_isr := v_subtotal_con_iva * 0.0125;
v_ret_iva := v_iva * (2.0 / 3.0);
v_total_neto := v_subtotal_con_iva - v_ret_isr - v_ret_iva;

RETURN QUERY
SELECT 'Commission Vida'::TEXT, ROUND(p_commission_vida, 2), ''::TEXT
UNION ALL
SELECT 'Commission Sin Vida'::TEXT, ROUND(p_commission_sinvida, 2), ''::TEXT
UNION ALL
SELECT 'Commission Total'::TEXT, ROUND(v_commission_total, 2), 'Vida + Sin Vida'::TEXT
UNION ALL
SELECT 'IVA (16%)'::TEXT, ROUND(v_iva, 2), 'Sin Vida × 0.16'::TEXT
UNION ALL
SELECT 'Subtotal con IVA'::TEXT, ROUND(v_subtotal_con_iva, 2), 'Total + IVA'::TEXT
UNION ALL
SELECT 'Ret ISR (1.25%)'::TEXT, ROUND(v_ret_isr, 2), '(Total + IVA) × 0.0125'::TEXT
UNION ALL
SELECT 'Ret IVA (2/3)'::TEXT, ROUND(v_ret_iva, 2), 'IVA × (2/3)'::TEXT
UNION ALL
SELECT '=== TOTAL NETO ==='::TEXT, ROUND(v_total_neto, 2), 'Subtotal - Ret ISR - Ret IVA'::TEXT;

ELSE
RETURN QUERY
SELECT 'ERROR'::TEXT, 0::NUMERIC, 'Régimen no reconocido'::TEXT;
END IF;

END;
$function$
;

CREATE OR REPLACE FUNCTION public.test_gmm_quotation_update(p_quotation_id uuid, p_user_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result text;
BEGIN
  -- Simular contexto de usuario autenticado
  PERFORM set_config('request.jwt.claims', json_build_object('sub', p_user_id)::text, true);
  
  -- Intentar UPDATE
  UPDATE gmm_quotations
  SET deleted_at = now()
  WHERE id = p_quotation_id;
  
  v_result := 'SUCCESS: Update completed';
  RETURN v_result;
EXCEPTION
  WHEN OTHERS THEN
    v_result := 'ERROR: ' || SQLERRM;
    RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.tetp_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN NEW.updated_at = now(); RETURN NEW; END;
$function$
;

CREATE OR REPLACE FUNCTION public.ticket_in_office(p_ticket_creado_por uuid, p_ticket_agente_id uuid, p_ticket_agente_usuario_id uuid, p_ticket_attending_user_id uuid, p_ticket_assigned_to_user_id uuid, p_oficina_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
SELECT EXISTS (
SELECT 1 FROM usuarios
WHERE oficina_id = p_oficina_id
AND id IN (
p_ticket_creado_por,
p_ticket_agente_id,
p_ticket_agente_usuario_id,
p_ticket_attending_user_id,
p_ticket_assigned_to_user_id
)
);
$function$
;

CREATE OR REPLACE FUNCTION public.tiene_permiso_admin_en_modulo(p_usuario_id uuid, p_modulo_codigo text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE
v_rol text;
v_tiene_permiso boolean;
BEGIN
-- Obtener rol del usuario
SELECT rol INTO v_rol
FROM usuarios
WHERE id = p_usuario_id AND estado = 'activo';

-- Si no existe el usuario o está inactivo, no tiene permiso
IF v_rol IS NULL THEN
RETURN false;
END IF;

-- Si es Administrador, siempre tiene permiso
IF v_rol = 'Administrador' THEN
RETURN true;
END IF;

-- Si NO es Gerente, no tiene permisos adicionales
IF v_rol != 'Gerente' THEN
RETURN false;
END IF;

-- Si es Gerente, verificar si tiene permiso adicional en ese módulo
SELECT EXISTS (
SELECT 1
FROM permisos_adicionales_gerente pag
JOIN modulos_sistema ms ON ms.id = pag.modulo_id
WHERE pag.usuario_id = p_usuario_id
AND ms.codigo = p_modulo_codigo
AND ms.activo = true
) INTO v_tiene_permiso;

RETURN COALESCE(v_tiene_permiso, false);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.toggle_aula_screen_sharing(p_participant_id uuid, p_is_sharing boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_puede_compartir boolean;
v_rol_participante text;
BEGIN
-- Get participant info
SELECT puede_compartir_pantalla, rol_participante
INTO v_puede_compartir, v_rol_participante
FROM aula_virtual_participantes
WHERE id = p_participant_id;

-- Check if participant can share screen (must be instructor or have permission)
IF NOT v_puede_compartir THEN
RAISE EXCEPTION 'Solo los instructores pueden compartir pantalla';
END IF;

-- Update screen sharing status
UPDATE aula_virtual_participantes
SET is_screen_sharing = p_is_sharing
WHERE id = p_participant_id;

RETURN true;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.toggle_cohost_status(p_meeting_id uuid, p_participant_id uuid, p_is_cohost boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_meeting_creator_id uuid;
BEGIN
-- Get meeting creator
SELECT creator_id INTO v_meeting_creator_id
FROM meetings
WHERE id = p_meeting_id;

-- Check if current user is the meeting creator
IF v_meeting_creator_id != auth.uid() THEN
RAISE EXCEPTION 'Solo el anfitrión puede asignar co-anfitriones';
END IF;

-- Update participant co-host status
UPDATE meeting_participants
SET is_cohost = p_is_cohost
WHERE id = p_participant_id AND meeting_id = p_meeting_id;

RETURN true;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.toggle_screen_sharing(p_participant_id uuid, p_is_sharing boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_participant_role text;
v_is_cohost boolean;
v_meeting_creator_id uuid;
v_meeting_id uuid;
v_user_id uuid;
BEGIN
-- Get participant info
SELECT role, is_cohost, meeting_id, user_id 
INTO v_participant_role, v_is_cohost, v_meeting_id, v_user_id
FROM meeting_participants
WHERE id = p_participant_id;

-- Get meeting creator
SELECT creator_id INTO v_meeting_creator_id
FROM meetings
WHERE id = v_meeting_id;

-- Check if user can share screen (must be host or co-host)
IF v_meeting_creator_id != auth.uid() AND NOT v_is_cohost THEN
RAISE EXCEPTION 'Solo el anfitrión y co-anfitriones pueden compartir pantalla';
END IF;

-- Update screen sharing status
UPDATE meeting_participants
SET is_screen_sharing = p_is_sharing
WHERE id = p_participant_id;

RETURN true;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.toggle_user_active_status(p_user_id uuid, p_activo boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_caller_id uuid;
v_caller_rol text;
v_caller_estado text;
v_target_email text;
v_target_nombre text;
v_old_activo boolean;
v_old_estado text;
v_target_deleted_at timestamptz;
v_new_estado text;
BEGIN
-- Get caller's ID
v_caller_id := auth.uid();

IF v_caller_id IS NULL THEN
RETURN jsonb_build_object(
'success', false,
'error', 'No autenticado'
);
END IF;

-- Validate caller is an active Administrator
SELECT rol, estado INTO v_caller_rol, v_caller_estado
FROM usuarios
WHERE id = v_caller_id AND deleted_at IS NULL;

IF v_caller_rol IS NULL THEN
RETURN jsonb_build_object(
'success', false,
'error', 'Usuario no encontrado'
);
END IF;

IF v_caller_rol != 'Administrador' THEN
RETURN jsonb_build_object(
'success', false,
'error', 'No autorizado. Solo administradores pueden realizar esta acción.'
);
END IF;

IF v_caller_estado != 'activo' THEN
RETURN jsonb_build_object(
'success', false,
'error', 'Tu cuenta no está activa'
);
END IF;

-- Prevent self-deactivation
IF v_caller_id = p_user_id AND p_activo = false THEN
RETURN jsonb_build_object(
'success', false,
'error', 'No puedes desactivar tu propia cuenta'
);
END IF;

-- Get target user info
SELECT email_laboral, nombre_completo, activo, estado, deleted_at
INTO v_target_email, v_target_nombre, v_old_activo, v_old_estado, v_target_deleted_at
FROM usuarios
WHERE id = p_user_id;

IF v_target_email IS NULL THEN
RETURN jsonb_build_object(
'success', false,
'error', 'Usuario objetivo no encontrado'
);
END IF;

IF v_target_deleted_at IS NOT NULL THEN
RETURN jsonb_build_object(
'success', false,
'error', 'No se puede modificar un usuario eliminado'
);
END IF;

-- Check if already in desired state
IF v_old_activo = p_activo THEN
RETURN jsonb_build_object(
'success', true,
'message', 'El usuario ya tiene el estado deseado',
'changed', false
);
END IF;

-- Determine new estado value
v_new_estado := CASE WHEN p_activo THEN 'activo' ELSE 'inactivo' END;

-- Update the user (both activo and estado fields)
UPDATE usuarios
SET 
activo = p_activo,
estado = v_new_estado,
updated_at = now()
WHERE id = p_user_id;

-- Log the change with correct column names
INSERT INTO audit_logs (
performed_by,
action,
target_user_id,
target_resource_type,
target_resource_id,
details
) VALUES (
v_caller_id,
CASE 
WHEN p_activo THEN 'activate_user'
ELSE 'deactivate_user'
END,
p_user_id,
'usuarios',
p_user_id,
jsonb_build_object(
'target_email', v_target_email,
'target_nombre', v_target_nombre,
'old_activo', v_old_activo,
'new_activo', p_activo,
'old_estado', v_old_estado,
'new_estado', v_new_estado
)
);

-- Return success
RETURN jsonb_build_object(
'success', true,
'message', CASE 
WHEN p_activo THEN 'Usuario activado exitosamente'
ELSE 'Usuario desactivado exitosamente'
END,
'changed', true,
'user', jsonb_build_object(
'id', p_user_id,
'email_laboral', v_target_email,
'nombre', v_target_nombre,
'activo', p_activo,
'estado', v_new_estado
)
);

EXCEPTION
WHEN OTHERS THEN
RETURN jsonb_build_object(
'success', false,
'error', 'Error al actualizar usuario: ' || SQLERRM
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.tramites_usuarios_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN NEW.updated_at = now(); RETURN NEW; END; $function$
;

CREATE OR REPLACE FUNCTION public.trg_actualizar_antiguedad()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
UPDATE agent_gamification_profile
SET
anios_antiguedad = EXTRACT(YEAR FROM AGE(CURRENT_DATE, fecha_ingreso_empresa)) +
EXTRACT(MONTH FROM AGE(CURRENT_DATE, fecha_ingreso_empresa)) / 12.0,
multiplicador_veterano = fn_calcular_multiplicador_veterano(
EXTRACT(YEAR FROM AGE(CURRENT_DATE, fecha_ingreso_empresa)) +
EXTRACT(MONTH FROM AGE(CURRENT_DATE, fecha_ingreso_empresa)) / 12.0
),
ultima_actualizacion_antiguedad = CURRENT_DATE,
updated_at = now()
WHERE fecha_ingreso_empresa IS NOT NULL
AND (ultima_actualizacion_antiguedad IS NULL 
OR ultima_actualizacion_antiguedad < CURRENT_DATE - INTERVAL '30 days');
END;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_actualizar_contadores_perfil()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
UPDATE agent_gamification_profile
SET
total_polizas_emitidas = total_polizas_emitidas + CASE WHEN NEW.tipo_evento = 'poliza_emitida' THEN 1 ELSE 0 END,
total_prospectos = total_prospectos + CASE WHEN NEW.tipo_evento = 'prospecto' THEN 1 ELSE 0 END,
total_cursos_completados = total_cursos_completados + CASE WHEN NEW.tipo_evento = 'curso_completado' THEN 1 ELSE 0 END,
total_certificaciones = total_certificaciones + CASE WHEN NEW.tipo_evento = 'certificacion' THEN 1 ELSE 0 END,
total_renovaciones = total_renovaciones + CASE WHEN NEW.tipo_evento = 'renovacion' THEN 1 ELSE 0 END,
updated_at = now()
WHERE user_id = NEW.user_id;

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_crear_perfil_gamificacion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
IF NEW.rol = 'Agente' THEN
INSERT INTO agent_gamification_profile (
user_id,
fecha_ingreso_empresa,
anios_antiguedad,
multiplicador_veterano
)
VALUES (
NEW.id,
COALESCE(NEW.fecha_ingreso, CURRENT_DATE),
0,
1.0
)
ON CONFLICT (user_id) DO NOTHING;
END IF;

RETURN NEW;
END;
$function$
;

