CREATE OR REPLACE FUNCTION public.trigger_notification_dispatcher()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_pending_count integer;
v_supabase_url text;
v_service_role_key text;
BEGIN
-- Count pending email/whatsapp jobs
SELECT COUNT(*) INTO v_pending_count
FROM notification_jobs
WHERE status = 'pending'
AND channel IN ('email', 'whatsapp');

IF v_pending_count = 0 THEN
RETURN;
END IF;

v_supabase_url := 'https://qhwvuuyjhcennqccgvse.supabase.co';
v_service_role_key := 'SERVICE_ROLE_KEY_REDACTADA';

-- Call the edge function with correct body
PERFORM net.http_post(
url := v_supabase_url || '/functions/v1/notification-dispatcher',
headers := jsonb_build_object(
'Authorization', 'Bearer ' || v_service_role_key,
'Content-Type', 'application/json'
),
body := '{"process_pending_jobs": true}'::jsonb,
timeout_milliseconds := 30000
);

EXCEPTION WHEN OTHERS THEN
RAISE WARNING 'Error al invocar notification-dispatcher: %', SQLERRM;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.trigger_refresh_vendor_cache()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_rec RECORD;
BEGIN
-- Cuando se crea o actualiza un mapping de tipo 'name', refrescar todos los vendedores que coincidan
IF (TG_OP = 'INSERT' OR TG_OP = 'UPDATE') AND NEW.source_type = 'name' THEN
FOR v_rec IN
SELECT DISTINCT vendor_nombre
FROM production_vendors_cache
WHERE vendor_nombre_normalized = NEW.source_value
LOOP
PERFORM refresh_vendor_mapping_cache(v_rec.vendor_nombre);
END LOOP;
END IF;

-- Cuando se elimina un mapping, refrescar los vendedores afectados
IF TG_OP = 'DELETE' AND OLD.source_type = 'name' THEN
FOR v_rec IN
SELECT DISTINCT vendor_nombre
FROM production_vendors_cache
WHERE vendor_nombre_normalized = OLD.source_value
LOOP
PERFORM refresh_vendor_mapping_cache(v_rec.vendor_nombre);
END LOOP;
END IF;

RETURN COALESCE(NEW, OLD);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.trigger_seguwallet_welcome_email()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_supabase_url text;
v_service_key  text;
BEGIN
IF NEW.email IS NULL OR trim(NEW.email) = '' THEN
RETURN NEW;
END IF;

IF NEW.status IS DISTINCT FROM 'active' THEN
RETURN NEW;
END IF;

v_supabase_url := current_setting('app.settings.supabase_url', true);
v_service_key  := current_setting('app.settings.service_role_key', true);

IF v_supabase_url IS NULL OR v_service_key IS NULL THEN
v_supabase_url := 'https://qhwvuuyjhcennqccgvse.supabase.co';
BEGIN
v_service_key := (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'service_role_key' LIMIT 1);
EXCEPTION WHEN OTHERS THEN
v_service_key := NULL;
END;
END IF;

IF v_service_key IS NULL THEN
RAISE WARNING '[SEGUWALLET WELCOME] No service_role_key available; skipping welcome email for customer %', NEW.id;
RETURN NEW;
END IF;

BEGIN
PERFORM net.http_post(
url     := v_supabase_url || '/functions/v1/seguwallet-send-welcome',
headers := jsonb_build_object(
'Content-Type',  'application/json',
'Authorization', 'Bearer ' || v_service_key
),
body    := jsonb_build_object('customer_id', NEW.id)
);
EXCEPTION WHEN OTHERS THEN
RAISE WARNING '[SEGUWALLET WELCOME] Failed to enqueue email for customer %: %', NEW.id, SQLERRM;
END;

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.trigger_send_welcome_on_activation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_oficina_nombre text;
v_pagina_web text;
v_already_queued boolean;
BEGIN
-- Solo actuar cuando estado cambia a 'activo' desde un estado diferente
IF NOT (NEW.estado = 'activo' AND (OLD.estado IS NULL OR OLD.estado != 'activo')) THEN
RETURN NEW;
END IF;

RAISE NOTICE '[ACTIVATION TRIGGER] Ejecutado para usuario % (% -> %)',
NEW.id, OLD.estado, NEW.estado;

-- Guard fuerte: checar notification_jobs directamente.
-- Se checa ANTES del envío (no historial que solo existe post-envío).
-- Ventana de 24 horas para activación — un usuario no debe recibir 
-- bienvenida dos veces en el mismo día.
SELECT EXISTS(
SELECT 1 FROM notification_jobs
WHERE user_id = NEW.id
AND event_code = 'cuenta_activada'
AND status IN ('pending', 'processing', 'sent')
AND created_at > NOW() - INTERVAL '24 hours'
LIMIT 1
) INTO v_already_queued;

IF v_already_queued THEN
RAISE NOTICE '[ACTIVATION TRIGGER] Job reciente detectado para %, omitiendo duplicado', NEW.id;
RETURN NEW;
END IF;

-- Obtener nombre de oficina
IF NEW.oficina_id IS NOT NULL THEN
SELECT nombre INTO v_oficina_nombre
FROM oficinas
WHERE id = NEW.oficina_id;
END IF;
v_oficina_nombre := COALESCE(v_oficina_nombre, 'No asignada');

-- Construir URL de página web
IF NEW.web_slug IS NOT NULL AND NEW.web_slug != '' THEN
v_pagina_web := 'https://agentedeseguros.online/' || NEW.web_slug;
ELSE
v_pagina_web := 'No configurada aún';
END IF;

-- Enviar notificación
BEGIN
PERFORM notify(
'cuenta_activada',
ARRAY[NEW.id],
jsonb_build_object(
'nombre',          COALESCE(NEW.nombre, ''),
'apellidos',       COALESCE(NEW.apellidos, ''),
'nombre_completo', COALESCE(NEW.nombre_completo, TRIM(COALESCE(NEW.nombre, '') || ' ' || COALESCE(NEW.apellidos, ''))),
'email_laboral',   COALESCE(NEW.email_laboral, ''),
'email_personal',  COALESCE(NEW.email_personal, ''),
'celular_laboral', COALESCE(NEW.celular_laboral, ''),
'celular_personal',COALESCE(NEW.celular_personal, ''),
'password',        'La contraseña que configuraste',
'rol',             COALESCE(NEW.rol, ''),
'oficina',         v_oficina_nombre,
'puesto',          COALESCE(NEW.puesto, 'Sin asignar'),
'pagina_web',      v_pagina_web,
'url',             '/dashboard'
),
NEW.id::text
);
RAISE NOTICE '[ACTIVATION TRIGGER] Notificación cuenta_activada encolada para %', NEW.id;
EXCEPTION WHEN OTHERS THEN
RAISE WARNING '[ACTIVATION TRIGGER] Error al encolar notificación para %: %', NEW.id, SQLERRM;
END;

RETURN NEW;
END;
$function$
;

