CREATE OR REPLACE FUNCTION public.truncate_whatsapp_message(p_message text, p_max_length integer DEFAULT 550)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
BEGIN
IF LENGTH(p_message) <= p_max_length THEN
RETURN p_message;
END IF;

-- Truncar y agregar indicador
RETURN SUBSTRING(p_message FROM 1 FOR p_max_length - 20) || '... [Continúa]';
END;
$function$
;

CREATE OR REPLACE FUNCTION public.unlink_vendor_from_user(p_vendor_id uuid DEFAULT NULL::uuid, p_movi_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_vend_id TEXT;
  v_vend_nombre TEXT;
  v_user_id UUID;
BEGIN
  IF p_vendor_id IS NOT NULL THEN
    SELECT vend_id, vend_nombre, movi_user_id 
    INTO v_vend_id, v_vend_nombre, v_user_id
    FROM sicas_vendor_user_mappings
    WHERE id = p_vendor_id;
  ELSIF p_movi_user_id IS NOT NULL THEN
    v_user_id := p_movi_user_id;
    SELECT vend_id, vend_nombre, id
    INTO v_vend_id, v_vend_nombre, p_vendor_id
    FROM sicas_vendor_user_mappings
    WHERE movi_user_id = p_movi_user_id
    LIMIT 1;
  END IF;

  IF p_vendor_id IS NOT NULL THEN
    UPDATE sicas_vendor_user_mappings
    SET movi_user_id = NULL,
        status = 'pending_review',
        match_type = 'unlinked',
        confidence_score = 0,
        match_details = jsonb_build_object('unlinked_at', NOW()),
        updated_at = NOW()
    WHERE id = p_vendor_id;
  ELSIF v_user_id IS NOT NULL THEN
    UPDATE sicas_vendor_user_mappings
    SET movi_user_id = NULL,
        status = 'pending_review',
        match_type = 'unlinked',
        confidence_score = 0,
        match_details = jsonb_build_object('unlinked_at', NOW()),
        updated_at = NOW()
    WHERE movi_user_id = v_user_id;
  END IF;

  IF v_user_id IS NOT NULL THEN
    UPDATE usuarios
    SET id_sicas = NULL,
        nombre_sicas = NULL,
        updated_at = NOW()
    WHERE id = v_user_id;

    UPDATE vendor_mappings
    SET status = 'inactive',
        updated_at = NOW()
    WHERE movi_user_id = v_user_id
      AND status = 'active';

    BEGIN
      IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'sicas_mapeo_vendedor_usuario') THEN
        DELETE FROM sicas_mapeo_vendedor_usuario
        WHERE movi_user_id = v_user_id;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;

  RETURN jsonb_build_object('success', true, 'unlinked_user_id', v_user_id, 'unlinked_vendor_id', v_vend_id);
END;
$function$
;

