CREATE OR REPLACE FUNCTION public.update_agent_seniority()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
UPDATE agent_gamification_profile
SET 
anios_antiguedad = EXTRACT(YEAR FROM age(CURRENT_DATE, fecha_ingreso_empresa)) +
(EXTRACT(MONTH FROM age(CURRENT_DATE, fecha_ingreso_empresa)) / 12.0),
multiplicador_veterano = calculate_veteran_multiplier(
EXTRACT(YEAR FROM age(CURRENT_DATE, fecha_ingreso_empresa)) +
(EXTRACT(MONTH FROM age(CURRENT_DATE, fecha_ingreso_empresa)) / 12.0)
),
ultima_actualizacion_antiguedad = CURRENT_DATE,
updated_at = now()
WHERE fecha_ingreso_empresa IS NOT NULL
AND (ultima_actualizacion_antiguedad IS NULL 
OR ultima_actualizacion_antiguedad < CURRENT_DATE);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.update_assistant_analytics()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_period_start timestamptz;
v_period_end timestamptz;
BEGIN
-- Calculate weekly period
v_period_start := date_trunc('week', NEW.created_at);
v_period_end := v_period_start + interval '7 days';

-- Upsert analytics record
INSERT INTO assistant_mode_analytics (
user_id,
mode,
total_queries,
period_start,
period_end,
updated_at
)
VALUES (
NEW.user_id,
NEW.selected_mode,
1,
v_period_start,
v_period_end,
now()
)
ON CONFLICT (user_id, mode, period_start)
DO UPDATE SET
total_queries = assistant_mode_analytics.total_queries + 1,
updated_at = now();

RETURN NEW;
END;
$function$
;

