CREATE OR REPLACE FUNCTION public.update_batch_counters(p_batch_id uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
BEGIN
UPDATE document_import_batches
SET
records_total = (
SELECT COUNT(*)
FROM imported_documents
WHERE batch_id = p_batch_id
),
records_matched = (
SELECT COUNT(*)
FROM imported_documents
WHERE batch_id = p_batch_id AND is_unmatched = false
),
records_unmatched = (
SELECT COUNT(*)
FROM imported_documents
WHERE batch_id = p_batch_id AND is_unmatched = true
),
updated_at = now()
WHERE id = p_batch_id;
END;
$function$
;

