CREATE OR REPLACE FUNCTION public.update_vendedor_mapped_status()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
IF TG_OP = 'INSERT' THEN
UPDATE sicas_vendedores
SET is_mapped = true
WHERE id_sicas = NEW.id_sicas_vendedor;
RETURN NEW;
ELSIF TG_OP = 'DELETE' THEN
UPDATE sicas_vendedores
SET is_mapped = false
WHERE id_sicas = OLD.id_sicas_vendedor;
RETURN OLD;
END IF;
RETURN NULL;
END;
$function$
;

