CREATE OR REPLACE FUNCTION public.uppercase_nombres_apellidos()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
-- Convertir nombre a MAYÚSCULAS si no es NULL
IF NEW.nombre IS NOT NULL THEN
NEW.nombre = UPPER(TRIM(NEW.nombre));
END IF;

-- Convertir apellidos a MAYÚSCULAS si no es NULL
IF NEW.apellidos IS NOT NULL THEN
NEW.apellidos = UPPER(TRIM(NEW.apellidos));
END IF;

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.upsert_chava_memory(p_scope text, p_scope_id text, p_usuario_id uuid, p_clave text, p_valor jsonb, p_fuente text DEFAULT NULL::text, p_confianza numeric DEFAULT 1.0, p_ttl_hours integer DEFAULT NULL::integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
INSERT INTO chava_memory (scope, scope_id, usuario_id, clave, valor, fuente, confianza, expires_at)
VALUES (
p_scope, p_scope_id, p_usuario_id, p_clave, p_valor, p_fuente, p_confianza,
CASE WHEN p_ttl_hours IS NOT NULL THEN now() + (p_ttl_hours || ' hours')::interval ELSE NULL END
)
ON CONFLICT (scope, scope_id, clave)
DO UPDATE SET
valor = EXCLUDED.valor,
fuente = COALESCE(EXCLUDED.fuente, chava_memory.fuente),
confianza = EXCLUDED.confianza,
expires_at = EXCLUDED.expires_at,
updated_at = now();
END;
$function$
;

CREATE OR REPLACE FUNCTION public.upsert_chava_proactive_cache(p_usuario_id uuid, p_tipo text, p_titulo text, p_cuerpo text, p_datos_json jsonb DEFAULT '{}'::jsonb, p_prioridad integer DEFAULT 50, p_ttl_hours integer DEFAULT 4)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_id uuid;
BEGIN
-- Delete expired or same-type entries for this user to avoid duplicates
DELETE FROM chava_proactive_cache
WHERE usuario_id = p_usuario_id
AND tipo = p_tipo
AND titulo = p_titulo;

INSERT INTO chava_proactive_cache (usuario_id, tipo, titulo, cuerpo, datos_json, prioridad, expires_at)
VALUES (
p_usuario_id, p_tipo, p_titulo, p_cuerpo, p_dados_json,
p_prioridad,
now() + (p_ttl_hours || ' hours')::interval
)
RETURNING id INTO v_id;

RETURN v_id;
EXCEPTION WHEN OTHERS THEN
-- Fallback: try INSERT ignoring the title uniqueness issue
INSERT INTO chava_proactive_cache (usuario_id, tipo, titulo, cuerpo, dados_json, prioridad, expires_at)
VALUES (p_usuario_id, p_tipo, p_titulo, p_cuerpo, p_dados_json, p_prioridad, now() + (p_ttl_hours || ' hours')::interval)
RETURNING id INTO v_id;
RETURN v_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.upsert_chava_topic_trend(p_fecha date, p_periodo text, p_intent_codigo text, p_plataforma text, p_incremento integer DEFAULT 1)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
INSERT INTO chava_topic_trends (
fecha,
periodo,
intent_codigo,
plataforma,
conteo,
updated_at
)
VALUES (
p_fecha,
p_periodo,
p_intent_codigo,
p_plataforma,
p_incremento,
now()
)
ON CONFLICT (fecha, periodo, intent_codigo, plataforma)
DO UPDATE SET
conteo = chava_topic_trends.conteo + p_incremento,
updated_at = now();
END;
$function$
;

