CREATE OR REPLACE FUNCTION public.usuario_puede_editar_tarea(tarea_uuid uuid, usuario_uuid uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_board_id UUID;
v_creado_por UUID;
v_puede_editar BOOLEAN;
v_member_role TEXT;
BEGIN
-- Obtener información de la tarea
SELECT board_id, creado_por INTO v_board_id, v_creado_por
FROM crm_tareas
WHERE id = tarea_uuid;

-- Si no existe la tarea, no puede editar
IF NOT FOUND THEN
RETURN FALSE;
END IF;

-- Si no tiene tablero, verificar si es el creador
IF v_board_id IS NULL THEN
RETURN v_creado_por = usuario_uuid;
END IF;

-- Verificar si es el propietario del tablero
SELECT EXISTS (
SELECT 1 FROM crm_boards
WHERE id = v_board_id
AND owner_user_id = usuario_uuid
) INTO v_puede_editar;

IF v_puede_editar THEN
RETURN TRUE;
END IF;

-- Verificar si es miembro con permisos de edición
SELECT member_role INTO v_member_role
FROM crm_board_members
WHERE board_id = v_board_id
AND user_id = usuario_uuid;

IF FOUND AND v_member_role IN ('owner', 'admin', 'editor') THEN
RETURN TRUE;
END IF;

RETURN FALSE;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.usuario_puede_gestionar_archivo(p_archivo_id uuid, p_usuario_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
v_usuario_id UUID;
v_usuario_rol TEXT;
v_usuario_oficina_id UUID;
v_archivo RECORD;
BEGIN
v_usuario_id := COALESCE(p_usuario_id, auth.uid());

IF v_usuario_id IS NULL THEN
RETURN false;
END IF;

SELECT rol, oficina_id INTO v_usuario_rol, v_usuario_oficina_id
FROM usuarios
WHERE id = v_usuario_id;

IF v_usuario_rol = 'Administrador' THEN
RETURN true;
END IF;

SELECT * INTO v_archivo
FROM centro_digital_archivos
WHERE id = p_archivo_id;

IF NOT FOUND THEN
RETURN false;
END IF;

IF v_archivo.cargado_por = v_usuario_id THEN
RETURN true;
END IF;

IF v_usuario_rol = 'Gerente' THEN
IF v_archivo.visible_para_oficina = v_usuario_oficina_id THEN
RETURN true;
END IF;

IF usuario_puede_gestionar_carpeta(v_archivo.carpeta_id, v_usuario_id) THEN
RETURN true;
END IF;
END IF;

RETURN false;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.usuario_puede_gestionar_carpeta(p_carpeta_id uuid, p_usuario_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
v_usuario_id uuid;
v_usuario_rol text;
v_usuario_oficina_id uuid;
v_carpeta_oficina_id uuid;
BEGIN
v_usuario_id := COALESCE(p_usuario_id, auth.uid());

IF v_usuario_id IS NULL THEN
RETURN false;
END IF;

SELECT rol, oficina_id INTO v_usuario_rol, v_usuario_oficina_id
FROM usuarios
WHERE id = v_usuario_id;

-- Admin puede gestionar todo
IF v_usuario_rol = 'Administrador' THEN
RETURN true;
END IF;

-- Gerente puede gestionar carpetas de su oficina o globales
IF v_usuario_rol = 'Gerente' THEN
SELECT oficina_id INTO v_carpeta_oficina_id
FROM centro_digital_carpetas
WHERE id = p_carpeta_id;

IF v_carpeta_oficina_id IS NULL OR v_carpeta_oficina_id = v_usuario_oficina_id THEN
RETURN true;
END IF;
END IF;

RETURN false;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.usuario_puede_ver_archivo(p_archivo_id uuid, p_usuario_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
v_usuario_id UUID;
v_usuario_rol TEXT;
v_usuario_oficina_id UUID;
v_archivo RECORD;
BEGIN
v_usuario_id := COALESCE(p_usuario_id, auth.uid());

IF v_usuario_id IS NULL THEN
RETURN false;
END IF;

SELECT rol, oficina_id INTO v_usuario_rol, v_usuario_oficina_id
FROM usuarios
WHERE id = v_usuario_id;

IF v_usuario_rol = 'Administrador' THEN
RETURN true;
END IF;

SELECT * INTO v_archivo
FROM centro_digital_archivos
WHERE id = p_archivo_id AND estado = 'activo';

IF NOT FOUND THEN
RETURN false;
END IF;

-- Creador siempre puede ver
IF v_archivo.cargado_por = v_usuario_id THEN
RETURN true;
END IF;

-- Visible para todos
IF v_archivo.visible_para_todos = true THEN
RETURN true;
END IF;

-- Visible para oficina específica
IF v_archivo.visible_para_oficina IS NOT NULL 
AND v_archivo.visible_para_oficina = v_usuario_oficina_id THEN
RETURN true;
END IF;

-- Permiso individual
IF EXISTS (
SELECT 1 FROM centro_digital_archivos_usuarios
WHERE archivo_id = p_archivo_id 
AND usuario_id = v_usuario_id
) THEN
RETURN true;
END IF;

-- Hereda visibilidad de carpeta
IF usuario_puede_ver_carpeta(v_archivo.carpeta_id, v_usuario_id) THEN
RETURN true;
END IF;

RETURN false;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.usuario_puede_ver_carpeta(p_carpeta_id uuid, p_usuario_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
v_usuario_id uuid;
v_usuario_rol text;
v_usuario_oficina_id uuid;
v_carpeta record;
BEGIN
-- Determinar usuario
v_usuario_id := COALESCE(p_usuario_id, auth.uid());

IF v_usuario_id IS NULL THEN
RETURN false;
END IF;

-- Obtener datos del usuario
SELECT rol, oficina_id INTO v_usuario_rol, v_usuario_oficina_id
FROM usuarios
WHERE id = v_usuario_id;

-- Admin ve todo
IF v_usuario_rol = 'Administrador' THEN
RETURN true;
END IF;

-- Obtener datos de la carpeta
SELECT * INTO v_carpeta
FROM centro_digital_carpetas
WHERE id = p_carpeta_id AND activa = true;

IF NOT FOUND THEN
RETURN false;
END IF;

-- Verificar visibilidad por rol
IF NOT v_carpeta.todos_roles THEN
IF NOT EXISTS (
SELECT 1 FROM centro_digital_carpetas_roles
WHERE carpeta_id = p_carpeta_id AND rol = v_usuario_rol
) THEN
RETURN false;
END IF;
END IF;

-- Verificar visibilidad por oficina
IF NOT v_carpeta.todas_oficinas THEN
IF NOT EXISTS (
SELECT 1 FROM centro_digital_carpetas_oficinas
WHERE carpeta_id = p_carpeta_id AND oficina_id = v_usuario_oficina_id
) THEN
RETURN false;
END IF;
END IF;

RETURN true;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.usuario_puede_ver_comunicado(p_comunicado_id uuid, p_usuario_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_tiene_restricciones BOOLEAN;
v_tiene_para_todos BOOLEAN;
v_usuario_rol TEXT;
v_usuario_oficina UUID;
v_puede_ver BOOLEAN;
BEGIN
-- Verificar si el comunicado tiene restricciones de visibilidad
SELECT EXISTS(
SELECT 1 FROM comunicados_visibilidad
WHERE comunicado_id = p_comunicado_id
) INTO v_tiene_restricciones;

-- Si no tiene restricciones, todos pueden verlo
IF NOT v_tiene_restricciones THEN
RETURN true;
END IF;

-- Verificar si tiene la regla "para_todos"
SELECT EXISTS(
SELECT 1 FROM comunicados_visibilidad
WHERE comunicado_id = p_comunicado_id
AND para_todos = true
) INTO v_tiene_para_todos;

-- Si tiene para_todos=true, todos pueden verlo
IF v_tiene_para_todos THEN
RETURN true;
END IF;

-- Obtener datos del usuario
SELECT rol, oficina_id INTO v_usuario_rol, v_usuario_oficina
FROM usuarios
WHERE id = p_usuario_id;

-- Verificar si el usuario cumple alguna regla de visibilidad específica
SELECT EXISTS(
SELECT 1 FROM comunicados_visibilidad
WHERE comunicado_id = p_comunicado_id
AND (
rol = v_usuario_rol OR
oficina_id = v_usuario_oficina OR
usuario_id = p_usuario_id
)
) INTO v_puede_ver;

RETURN v_puede_ver;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.usuario_puede_ver_tarea(tarea_uuid uuid, usuario_uuid uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_board_id UUID;
v_creado_por UUID;
v_tiene_acceso BOOLEAN;
BEGIN
-- Obtener información de la tarea
SELECT board_id, creado_por INTO v_board_id, v_creado_por
FROM crm_tareas
WHERE id = tarea_uuid;

-- Si no existe la tarea, no tiene acceso
IF NOT FOUND THEN
RETURN FALSE;
END IF;

-- Si no tiene tablero, verificar si es el creador
IF v_board_id IS NULL THEN
RETURN v_creado_por = usuario_uuid;
END IF;

-- Verificar si es el propietario del tablero
SELECT EXISTS (
SELECT 1 FROM crm_boards
WHERE id = v_board_id
AND owner_user_id = usuario_uuid
) INTO v_tiene_acceso;

IF v_tiene_acceso THEN
RETURN TRUE;
END IF;

-- Verificar si es miembro del tablero (sin verificar RLS)
SELECT EXISTS (
SELECT 1 FROM crm_board_members
WHERE board_id = v_board_id
AND user_id = usuario_uuid
) INTO v_tiene_acceso;

RETURN v_tiene_acceso;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.usuario_tiene_acceso_ticket(ticket_id uuid, usuario_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
tiene_acceso BOOLEAN;
user_rol TEXT;
BEGIN
-- Obtener rol del usuario
SELECT rol INTO user_rol FROM usuarios WHERE id = usuario_id;

-- Admin y Gerente tienen acceso a todo
IF user_rol IN ('Administrador', 'Gerente') THEN
RETURN true;
END IF;

-- Verificar si es creador, agente, o asignado
SELECT EXISTS (
SELECT 1 FROM tickets t
WHERE t.id = ticket_id
AND (
t.creado_por = usuario_id
OR t.agente_id = usuario_id
OR EXISTS (
SELECT 1 FROM ticket_asignaciones ta
WHERE ta.ticket_id = t.id
AND ta.ejecutivo_id = usuario_id
)
)
) INTO tiene_acceso;

RETURN tiene_acceso;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.usuario_tiene_permiso_evento(evento_uuid uuid, user_uuid uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
evento_visible_todos boolean;
user_rol text;
user_oficina uuid;
tiene_permiso boolean;
BEGIN
-- Obtener si el evento es visible para todos
SELECT visible_para_todos INTO evento_visible_todos
FROM aula_eventos
WHERE id = evento_uuid;

-- Si es visible para todos, retornar true
IF evento_visible_todos THEN
RETURN true;
END IF;

-- Obtener rol y oficina del usuario
SELECT rol, oficina_id INTO user_rol, user_oficina
FROM usuarios
WHERE id = user_uuid;

-- Verificar si tiene permiso directo, por rol o por oficina
SELECT EXISTS (
SELECT 1
FROM aula_eventos_permisos
WHERE evento_id = evento_uuid
AND (
usuario_id = user_uuid OR
rol = user_rol OR
oficina_id = user_oficina
)
) INTO tiene_permiso;

RETURN tiene_permiso;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.usuario_tiene_rol(p_roles text[])
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.usuarios u
    WHERE u.id = auth.uid()
      AND lower(u.rol) = ANY (SELECT lower(r) FROM unnest(p_roles) AS r)
  );
$function$
;

CREATE OR REPLACE FUNCTION public.usuarios_set_default_rol_id()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.rol_id IS NULL AND NEW.rol IS NOT NULL THEN
    SELECT id INTO NEW.rol_id FROM roles WHERE nombre = NEW.rol LIMIT 1;
    IF NEW.rol_id IS NULL THEN
      SELECT id INTO NEW.rol_id FROM roles WHERE rol_base = NEW.rol ORDER BY es_sistema DESC, orden LIMIT 1;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.validar_desglose_fiscal_asimilados(p_batch_id uuid, p_agent_id uuid)
 RETURNS TABLE(campo text, esperado numeric, calculado numeric, diferencia numeric, valido boolean)
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
v_desglose JSON;
BEGIN
-- Obtener desglose calculado
v_desglose := calcular_desglose_fiscal_asimilados(p_batch_id, p_agent_id);

-- Validar totales
RETURN QUERY
SELECT 
'Total Comisión'::TEXT,
(v_desglose->>'vida')::numeric + (v_desglose->>'sin_vida')::numeric,
(v_desglose->>'total_comision')::numeric,
ABS((v_desglose->>'vida')::numeric + (v_desglose->>'sin_vida')::numeric - (v_desglose->>'total_comision')::numeric),
ABS((v_desglose->>'vida')::numeric + (v_desglose->>'sin_vida')::numeric - (v_desglose->>'total_comision')::numeric) < 0.01

UNION ALL

SELECT 
'Total a Pagar'::TEXT,
(v_desglose->>'total_comision')::numeric - (v_desglose->>'ret_contable')::numeric - (v_desglose->>'dispersion')::numeric - (v_desglose->>'isr_total')::numeric,
(v_desglose->>'total_pagar')::numeric,
ABS((v_desglose->>'total_comision')::numeric - (v_desglose->>'ret_contable')::numeric - (v_desglose->>'dispersion')::numeric - (v_desglose->>'isr_total')::numeric - (v_desglose->>'total_pagar')::numeric),
ABS((v_desglose->>'total_comision')::numeric - (v_desglose->>'ret_contable')::numeric - (v_desglose->>'dispersion')::numeric - (v_desglose->>'isr_total')::numeric - (v_desglose->>'total_pagar')::numeric) < 0.01;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.validar_desglose_fiscal_o_abortar(p_batch_id uuid, p_agent_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
DECLARE
v_desglose JSON;
v_total_comision NUMERIC;
v_vida NUMERIC;
v_sin_vida NUMERIC;
v_ret_contable NUMERIC;
v_dispersion NUMERIC;
v_isr_total NUMERIC;
v_total_pagar NUMERIC;
v_total_calculado NUMERIC;
v_tolerance NUMERIC := 0.02;
BEGIN
-- Obtener desglose calculado
v_desglose := calcular_desglose_fiscal_asimilados(p_batch_id, p_agent_id);

-- Si no es ASIMILADOS, no validar
IF NOT (v_desglose->>'es_asimilados')::boolean THEN
RETURN TRUE;
END IF;

-- Extraer valores
v_total_comision := (v_desglose->>'total_comision')::numeric;
v_vida := (v_desglose->>'vida')::numeric;
v_sin_vida := (v_desglose->>'sin_vida')::numeric;
v_ret_contable := (v_desglose->>'ret_contable')::numeric;
v_dispersion := (v_desglose->>'dispersion')::numeric;
v_isr_total := (v_desglose->>'isr_total')::numeric;
v_total_pagar := (v_desglose->>'total_pagar')::numeric;

-- VALIDACIÓN 1: Vida + Sin Vida = Total Comisión
IF ABS((v_vida + v_sin_vida) - v_total_comision) > v_tolerance THEN
RAISE EXCEPTION 'VALIDACIÓN FALLIDA [Lote %, Agente %]: Vida (%) + Sin Vida (%) != Total Comisión (%). Diferencia: %',
p_batch_id, p_agent_id, v_vida, v_sin_vida, v_total_comision, 
ABS((v_vida + v_sin_vida) - v_total_comision);
END IF;

-- VALIDACIÓN 2: Total a Pagar = Total - Ret - Dispersión - ISR
v_total_calculado := v_total_comision - v_ret_contable - v_dispersion - v_isr_total;
IF ABS(v_total_calculado - v_total_pagar) > v_tolerance THEN
RAISE EXCEPTION 'VALIDACIÓN FALLIDA [Lote %, Agente %]: Total calculado (%) != Total a Pagar (%). Diferencia: %',
p_batch_id, p_agent_id, v_total_calculado, v_total_pagar, 
ABS(v_total_calculado - v_total_pagar);
END IF;

-- VALIDACIÓN 3: Ret. Contable debe ser Vida * 0.16
IF v_vida > 0 THEN
IF ABS(v_ret_contable - ROUND((v_vida * 0.16)::numeric, 2)) > v_tolerance THEN
RAISE EXCEPTION 'VALIDACIÓN FALLIDA [Lote %, Agente %]: Ret. Contable (%) debe ser Vida (%) * 0.16 = %. Diferencia: %',
p_batch_id, p_agent_id, v_ret_contable, v_vida, ROUND((v_vida * 0.16)::numeric, 2), 
ABS(v_ret_contable - ROUND((v_vida * 0.16)::numeric, 2));
END IF;
END IF;

-- VALIDACIÓN 4: Dispersión debe ser Sin Vida * 0.09
IF v_sin_vida > 0 THEN
IF ABS(v_dispersion - ROUND((v_sin_vida * 0.09)::numeric, 2)) > v_tolerance THEN
RAISE EXCEPTION 'VALIDACIÓN FALLIDA [Lote %, Agente %]: Dispersión (%) debe ser Sin Vida (%) * 0.09 = %. Diferencia: %',
p_batch_id, p_agent_id, v_dispersion, v_sin_vida, ROUND((v_sin_vida * 0.09)::numeric, 2), 
ABS(v_dispersion - ROUND((v_sin_vida * 0.09)::numeric, 2));
END IF;
END IF;

-- VALIDACIÓN 5: ISR Total debe ser positivo
IF v_isr_total < 0 THEN
RAISE EXCEPTION 'VALIDACIÓN FALLIDA [Lote %, Agente %]: ISR Total (%) no puede ser negativo',
p_batch_id, p_agent_id, v_isr_total;
END IF;

-- VALIDACIÓN 6: Total a Pagar debe ser menor que Total Comisión
IF v_total_pagar > v_total_comision THEN
RAISE EXCEPTION 'VALIDACIÓN FALLIDA [Lote %, Agente %]: Total a Pagar (%) no puede ser mayor que Total Comisión (%)',
p_batch_id, p_agent_id, v_total_pagar, v_total_comision;
END IF;

-- Todas las validaciones pasaron
RETURN TRUE;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.validar_destinatarios_notificacion(p_tipo_notificacion_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_permite_destinatarios boolean;
v_tiene_destinatarios boolean;
BEGIN
-- Obtener si el tipo permite destinatarios custom
SELECT permite_destinatarios_custom INTO v_permite_destinatarios
FROM correo_tipos_notificacion
WHERE id = p_tipo_notificacion_id;

-- Si no permite destinatarios, está OK (puede enviar a todos o a quien corresponda)
IF NOT v_permite_destinatarios THEN
RETURN true;
END IF;

-- Si permite destinatarios custom, verificar que tenga al menos uno
SELECT EXISTS(
SELECT 1
FROM correo_destinatarios_notificacion
WHERE tipo_notificacion_id = p_tipo_notificacion_id
) INTO v_tiene_destinatarios;

RETURN v_tiene_destinatarios;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.validar_limite_adjuntos_tarea()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
IF (SELECT COUNT(*) FROM crm_tareas_adjuntos WHERE tarea_id = NEW.tarea_id) >= 5 THEN
RAISE EXCEPTION 'No se pueden agregar más de 5 adjuntos por tarea';
END IF;
RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_batch_for_conversion(batch_id_param uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
result jsonb;
total_docs int;
unmatched_docs int;
missing_dates int;
weeks_info jsonb;
BEGIN
-- Inicializar resultado
result := jsonb_build_object(
'can_convert', false,
'errors', '[]'::jsonb,
'warnings', '[]'::jsonb,
'summary', '{}'::jsonb
);

-- Verificar si ya fue convertido
IF EXISTS (
SELECT 1 FROM document_import_batches 
WHERE id = batch_id_param AND status = 'converted'
) THEN
result := jsonb_set(
result, 
'{errors}', 
result->'errors' || '["El batch ya fue convertido anteriormente"]'::jsonb
);
RETURN result;
END IF;

-- Contar documentos
SELECT COUNT(*) INTO total_docs
FROM imported_documents
WHERE batch_id = batch_id_param;

IF total_docs = 0 THEN
result := jsonb_set(
result, 
'{errors}', 
result->'errors' || '["No hay documentos en este batch"]'::jsonb
);
RETURN result;
END IF;

-- Verificar documentos sin asignar (AHORA ES ADVERTENCIA, NO ERROR)
SELECT COUNT(*) INTO unmatched_docs
FROM imported_documents
WHERE batch_id = batch_id_param 
AND (movi_user_id IS NULL OR is_unmatched = true);

IF unmatched_docs > 0 THEN
result := jsonb_set(
result, 
'{warnings}', 
result->'warnings' || jsonb_build_array(
'Hay ' || unmatched_docs || ' documentos sin usuario asignado. Podrás asignarlos dentro del lote después de convertir.'
)
);
END IF;

-- Verificar documentos sin fecha (ESTO SÍ ES ERROR)
SELECT COUNT(*) INTO missing_dates
FROM imported_documents
WHERE batch_id = batch_id_param 
AND (document_data->>'fecha_pago' IS NULL OR document_data->>'fecha_pago' = '');

IF missing_dates > 0 THEN
result := jsonb_set(
result, 
'{errors}', 
result->'errors' || jsonb_build_array(
'Falta fecha en ' || missing_dates || ' documentos. No es posible agrupar por semana.'
)
);
END IF;

-- Si no hay errores (solo fechas bloquean), obtener información de semanas
IF jsonb_array_length(result->'errors') = 0 THEN
result := jsonb_set(result, '{can_convert}', 'true'::jsonb);

-- Obtener resumen de semanas (INCLUIR TODOS LOS DOCS, con y sin usuario)
SELECT jsonb_agg(week_data)
INTO weeks_info
FROM (
SELECT 
EXTRACT(WEEK FROM (document_data->>'fecha_pago')::date) as week_number,
DATE_TRUNC('week', (document_data->>'fecha_pago')::date)::date as week_start,
(DATE_TRUNC('week', (document_data->>'fecha_pago')::date) + INTERVAL '6 days')::date as week_end,
COUNT(*) as document_count,
COUNT(DISTINCT movi_user_id) FILTER (WHERE movi_user_id IS NOT NULL) as agent_count,
COUNT(*) FILTER (WHERE movi_user_id IS NULL OR is_unmatched = true) as unassigned_count
FROM imported_documents
WHERE batch_id = batch_id_param
GROUP BY week_number, week_start, week_end
ORDER BY week_start
) as week_data;

result := jsonb_set(
result, 
'{summary}', 
jsonb_build_object(
'total_documents', total_docs,
'unmatched_documents', unmatched_docs,
'assigned_documents', total_docs - unmatched_docs,
'total_agents', (
SELECT COUNT(DISTINCT movi_user_id) 
FROM imported_documents 
WHERE batch_id = batch_id_param
AND movi_user_id IS NOT NULL
),
'weeks', COALESCE(weeks_info, '[]'::jsonb)
)
);
END IF;

RETURN result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_batch_for_conversion_detailed(batch_id_param uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
result jsonb;
total_docs int;
matched_docs int;
unmatched_docs int;
missing_dates int;
empty_vendor int;
weeks_info jsonb;
error_list jsonb := '[]'::jsonb;
warning_list jsonb := '[]'::jsonb;
can_convert boolean := true;
BEGIN
-- Verificar si ya fue convertido
IF EXISTS (
SELECT 1 FROM document_import_batches
WHERE id = batch_id_param AND converted_to_commissions = true
) THEN
RETURN jsonb_build_object(
'canConvert', false,
'blockingErrorsCount', 1,
'warningsCount', 0,
'errors', jsonb_build_array(
jsonb_build_object(
'severity', 'blocking',
'code', 'ALREADY_CONVERTED',
'message', 'El batch ya fue convertido anteriormente',
'count', 1,
'affectedRows', '[]'::jsonb,
'examples', '[]'::jsonb
)
)
);
END IF;

-- Contar totales
SELECT COUNT(*) INTO total_docs
FROM imported_documents
WHERE batch_id = batch_id_param;

IF total_docs = 0 THEN
RETURN jsonb_build_object(
'canConvert', false,
'blockingErrorsCount', 1,
'warningsCount', 0,
'errors', jsonb_build_array(
jsonb_build_object(
'severity', 'blocking',
'code', 'NO_DOCUMENTS',
'message', 'No hay documentos en este batch',
'count', 0,
'affectedRows', '[]'::jsonb,
'examples', '[]'::jsonb
)
)
);
END IF;

-- Contar matched vs unmatched
SELECT
COUNT(*) FILTER (WHERE movi_user_id IS NOT NULL AND is_unmatched = false),
COUNT(*) FILTER (WHERE movi_user_id IS NULL OR is_unmatched = true)
INTO matched_docs, unmatched_docs
FROM imported_documents
WHERE batch_id = batch_id_param;

-- Contar documentos sin FPago válido (SOLO FPago es la fecha oficial)
SELECT COUNT(*) INTO missing_dates
FROM imported_documents
WHERE batch_id = batch_id_param
AND (
document_data->>'FPago' IS NULL
OR document_data->>'FPago' = ''
);

-- Contar vendedores vacíos
SELECT COUNT(*) INTO empty_vendor
FROM imported_documents
WHERE batch_id = batch_id_param
AND (vendor_name_raw IS NULL OR vendor_name_raw = '')
AND (vendor_email_raw IS NULL OR vendor_email_raw = '');

-- FPago faltante: SIEMPRE es WARNING, NUNCA bloqueante
IF missing_dates = total_docs THEN
-- Todos los documentos sin FPago
warning_list := warning_list || jsonb_build_array(
jsonb_build_object(
'severity', 'warning',
'code', 'ALL_MISSING_FPAGO',
'message', format('FPago no está definido en ningún documento (%s total). Se creará un lote "Sin fecha" para gestionar después.', total_docs),
'count', missing_dates,
'affectedRows', (
SELECT jsonb_agg(source_row_index)
FROM imported_documents
WHERE batch_id = batch_id_param
LIMIT 20
),
'examples', get_validation_error_details(batch_id_param, 'MISSING_DATE')
)
);
ELSIF missing_dates > 0 THEN
-- Algunos documentos sin FPago
warning_list := warning_list || jsonb_build_array(
jsonb_build_object(
'severity', 'warning',
'code', 'PARTIAL_MISSING_FPAGO',
'message', format('Hay %s documentos sin FPago. Se incluirán en un lote especial "Sin fecha".', missing_dates),
'count', missing_dates,
'affectedRows', (
SELECT jsonb_agg(source_row_index)
FROM imported_documents
WHERE batch_id = batch_id_param
AND (document_data->>'FPago' IS NULL OR document_data->>'FPago' = '')
LIMIT 20
),
'examples', get_validation_error_details(batch_id_param, 'MISSING_DATE')
)
);
END IF;

-- Advertencia: documentos sin asignar (NO bloqueante)
IF unmatched_docs > 0 THEN
warning_list := warning_list || jsonb_build_array(
jsonb_build_object(
'severity', 'warning',
'code', 'UNASSIGNED_USERS',
'message', format('Hay %s documentos sin asignación de usuario. Se incluirán en los lotes con pending_assignment=true.', unmatched_docs),
'count', unmatched_docs,
'affectedRows', (
SELECT jsonb_agg(source_row_index)
FROM imported_documents
WHERE batch_id = batch_id_param
AND (movi_user_id IS NULL OR is_unmatched = true)
LIMIT 20
),
'examples', get_validation_error_details(batch_id_param, 'UNASSIGNED_USER')
)
);
END IF;

-- Advertencia: vendedores vacíos (NO bloqueante)
IF empty_vendor > 0 THEN
warning_list := warning_list || jsonb_build_array(
jsonb_build_object(
'severity', 'warning',
'code', 'EMPTY_VENDOR',
'message', format('Hay %s documentos sin información de vendedor. Se marcarán con vendor_key="unknown".', empty_vendor),
'count', empty_vendor,
'affectedRows', (
SELECT jsonb_agg(source_row_index)
FROM imported_documents
WHERE batch_id = batch_id_param
AND (vendor_name_raw IS NULL OR vendor_name_raw = '')
AND (vendor_email_raw IS NULL OR vendor_email_raw = '')
LIMIT 20
),
'examples', get_validation_error_details(batch_id_param, 'EMPTY_VENDOR')
)
);
END IF;

-- Calcular información de semanas (excluyendo sin FPago)
SELECT jsonb_agg(
jsonb_build_object(
'week_number', week_number,
'week_start', week_start,
'week_end', week_end,
'document_count', document_count,
'agent_count', agent_count
)
) INTO weeks_info
FROM (
SELECT
EXTRACT(WEEK FROM (document_data->>'FPago')::date) as week_number,
date_trunc('week', (document_data->>'FPago')::date)::date as week_start,
(date_trunc('week', (document_data->>'FPago')::date) + interval '6 days')::date as week_end,
COUNT(*) as document_count,
COUNT(DISTINCT movi_user_id) as agent_count
FROM imported_documents
WHERE batch_id = batch_id_param
AND document_data->>'FPago' IS NOT NULL
AND document_data->>'FPago' != ''
GROUP BY week_number, week_start, week_end
ORDER BY week_start
) as week_data;

-- Construir resultado (SIEMPRE can_convert = true excepto si ya convertido o sin docs)
RETURN jsonb_build_object(
'canConvert', true,
'blockingErrorsCount', 0,
'warningsCount', jsonb_array_length(warning_list),
'errors', warning_list,
'summary', jsonb_build_object(
'total_documents', total_docs,
'matched_documents', matched_docs,
'unmatched_documents', unmatched_docs,
'missing_dates', missing_dates,
'empty_vendor', empty_vendor,
'total_agents', (
SELECT COUNT(DISTINCT movi_user_id)
FROM imported_documents
WHERE batch_id = batch_id_param
AND movi_user_id IS NOT NULL
),
'weeks', COALESCE(weeks_info, '[]'::jsonb),
'has_no_date_documents', missing_dates > 0
)
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_commercial_ticket_rules()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_creator_rol TEXT;
  v_is_commercial_type BOOLEAN;
BEGIN
  v_is_commercial_type := NEW.tipo_tramite IN (
    'renovaciones',
    'cobranza',
    'otros_comercial',
    'correccion_poliza_endoso'
  );

  IF NOT v_is_commercial_type THEN
    RETURN NEW;
  END IF;

  -- Get creator's role
  SELECT rol INTO v_creator_rol
  FROM usuarios
  WHERE id = NEW.creado_por;

  -- Rule 1: Agents can only create commercial tickets for themselves.
  --   agente_usuario_id must match creado_por; creating for other agents is blocked.
  IF v_creator_rol = 'Agente' AND (NEW.agente_usuario_id IS DISTINCT FROM NEW.creado_por) THEN
    RAISE EXCEPTION 'Los agentes no pueden crear trámites comerciales para otros agentes';
  END IF;

  -- Rule 2: Commercial tickets must have a related agent.
  IF NEW.agente_usuario_id IS NULL AND NEW.agente_id IS NULL THEN
    RAISE EXCEPTION 'Los trámites comerciales deben tener un agente relacionado';
  END IF;

  -- Rule 3 intentionally removed: assigned_to_user_id stays NULL when no
  -- ejecutivo was resolved, allowing pool/unassigned behavior.

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_commission_batch(p_batch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
v_batch record;
v_details_sum numeric;
v_vida_sum numeric;
v_sinvida_sum numeric;
v_errors jsonb := '[]'::jsonb;
v_warnings jsonb := '[]'::jsonb;
v_expected_iva numeric;
v_expected_ret_isr numeric;
v_expected_ret_iva numeric;
BEGIN
-- Cargar batch
SELECT * INTO v_batch
FROM commission_batches
WHERE id = p_batch_id;

IF NOT FOUND THEN
RETURN jsonb_build_object(
'valid', false,
'error', 'Batch no encontrado'
);
END IF;

-- Sumar commission_neta de todos los detalles (considerando ajustes)
SELECT
COALESCE(SUM(CASE
WHEN is_manual_adjusted AND adjusted_commission_neta IS NOT NULL
THEN adjusted_commission_neta
ELSE commission_neta
END), 0),
COALESCE(SUM(CASE
WHEN LOWER(ramo) = 'vida' THEN
CASE
WHEN is_manual_adjusted AND adjusted_commission_neta IS NOT NULL
THEN adjusted_commission_neta
ELSE commission_neta
END
ELSE 0
END), 0),
COALESCE(SUM(CASE
WHEN LOWER(ramo) != 'vida' THEN
CASE
WHEN is_manual_adjusted AND adjusted_commission_neta IS NOT NULL
THEN adjusted_commission_neta
ELSE commission_neta
END
ELSE 0
END), 0)
INTO v_details_sum, v_vida_sum, v_sinvida_sum
FROM commission_details
WHERE batch_id = p_batch_id;

-- Validar que suma coincida con batch
IF v_batch.commission_total IS NOT NULL AND
ABS(v_batch.commission_total - v_details_sum) > 0.01 THEN
v_errors := v_errors || jsonb_build_object(
'code', 'TOTAL_MISMATCH',
'message', format('commission_total del batch (%s) no coincide con suma de detalles (%s)',
v_batch.commission_total, v_details_sum),
'expected', v_details_sum,
'actual', v_batch.commission_total
);
END IF;

-- Validar vida + sinvida = total
IF v_batch.commission_vida IS NOT NULL AND v_batch.commission_sinvida IS NOT NULL AND
ABS((v_batch.commission_vida + v_batch.commission_sinvida) - v_batch.commission_total) > 0.01 THEN
v_errors := v_errors || jsonb_build_object(
'code', 'VIDA_SINVIDA_TOTAL_MISMATCH',
'message', format('vida (%s) + sinvida (%s) != total (%s)',
v_batch.commission_vida, v_batch.commission_sinvida, v_batch.commission_total)
);
END IF;

-- Validar valores fiscales existen para lotes cerrados
IF v_batch.status = 'closed' THEN
IF v_batch.calculated_at IS NULL THEN
v_errors := v_errors || jsonb_build_object(
'code', 'MISSING_CALCULATED_AT',
'message', 'Lote cerrado sin fecha de cálculo fiscal'
);
END IF;

IF v_batch.iva IS NULL OR v_batch.ret_isr IS NULL OR
v_batch.ret_iva IS NULL OR v_batch.total_neto IS NULL THEN
v_errors := v_errors || jsonb_build_object(
'code', 'MISSING_FISCAL_VALUES',
'message', 'Lote cerrado sin valores fiscales calculados'
);
END IF;
END IF;

-- Validar fórmulas según régimen
IF v_batch.regimen_fiscal IN ('HONORARIOS', 'RESICO') AND v_batch.calculated_at IS NOT NULL THEN
-- IVA = sinVida × 0.16
v_expected_iva := ROUND((v_batch.commission_sinvida * 0.16)::numeric, 2);
IF v_batch.iva IS NOT NULL AND ABS(v_batch.iva - v_expected_iva) > 0.02 THEN
v_warnings := v_warnings || jsonb_build_object(
'code', 'IVA_FORMULA_MISMATCH',
'message', format('IVA (%s) no coincide con fórmula sinVida × 0.16 = %s',
v_batch.iva, v_expected_iva),
'expected', v_expected_iva,
'actual', v_batch.iva
);
END IF;

-- Ret ISR según régimen
IF v_batch.regimen_fiscal = 'HONORARIOS' THEN
v_expected_ret_isr := ROUND((v_batch.commission_total * 0.10)::numeric, 2);
IF v_batch.ret_isr IS NOT NULL AND ABS(v_batch.ret_isr - v_expected_ret_isr) > 0.02 THEN
v_warnings := v_warnings || jsonb_build_object(
'code', 'RET_ISR_FORMULA_MISMATCH',
'message', format('Ret ISR (%s) no coincide con fórmula total × 0.10 = %s',
v_batch.ret_isr, v_expected_ret_isr),
'expected', v_expected_ret_isr,
'actual', v_batch.ret_isr
);
END IF;
ELSIF v_batch.regimen_fiscal = 'RESICO' THEN
v_expected_ret_isr := ROUND((v_batch.commission_total * 0.0125)::numeric, 2);
IF v_batch.ret_isr IS NOT NULL AND ABS(v_batch.ret_isr - v_expected_ret_isr) > 0.02 THEN
v_warnings := v_warnings || jsonb_build_object(
'code', 'RET_ISR_FORMULA_MISMATCH',
'message', format('Ret ISR (%s) no coincide con fórmula total × 0.0125 = %s',
v_batch.ret_isr, v_expected_ret_isr),
'expected', v_expected_ret_isr,
'actual', v_batch.ret_isr
);
END IF;
END IF;

-- Ret IVA = sinVida × 0.10667
v_expected_ret_iva := ROUND((v_batch.commission_sinvida * 0.10667)::numeric, 2);
IF v_batch.ret_iva IS NOT NULL AND ABS(v_batch.ret_iva - v_expected_ret_iva) > 0.02 THEN
v_warnings := v_warnings || jsonb_build_object(
'code', 'RET_IVA_FORMULA_MISMATCH',
'message', format('Ret IVA (%s) no coincide con fórmula sinVida × 0.10667 = %s',
v_batch.ret_iva, v_expected_ret_iva),
'expected', v_expected_ret_iva,
'actual', v_batch.ret_iva
);
END IF;
END IF;

RETURN jsonb_build_object(
'valid', jsonb_array_length(v_errors) = 0,
'errors', v_errors,
'warnings', v_warnings,
'summary', jsonb_build_object(
'batch_id', p_batch_id,
'regimen_fiscal', v_batch.regimen_fiscal,
'status', v_batch.status,
'details_sum', v_details_sum,
'vida_sum', v_vida_sum,
'sinvida_sum', v_sinvida_sum,
'batch_total', v_batch.commission_total,
'batch_vida', v_batch.commission_vida,
'batch_sinvida', v_batch.commission_sinvida,
'calculated_at', v_batch.calculated_at,
'tax_version', v_batch.tax_version
)
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_commission_bruta_not_prima_neta()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
IF NEW.commission_bruta IS NOT NULL
AND NEW.prima_neta IS NOT NULL
AND NEW.commission_bruta = NEW.prima_neta THEN

IF NOT EXISTS (
SELECT 1 FROM commission_import_config
WHERE active = true AND allow_prima_neta_as_commission_bruta = true
) THEN
NEW.calculation_warnings =
COALESCE(NEW.calculation_warnings, '[]'::jsonb) ||
jsonb_build_array(
jsonb_build_object(
'code', 'SUSPICIOUS_BRUTA_EQUALS_PRIMA',
'message', 'commission_bruta es igual a prima_neta, esto es probablemente un bug',
'detected_at', now()
)
);

NEW.calculation_status = 'error';
END IF;
END IF;

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_registro_actividades()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
-- Skip entirely for cotizacion_emision
IF NEW.tipo_tramite = 'cotizacion_emision' THEN
RETURN NEW;
END IF;

-- Only applies to 'registro_actividad' type
IF NEW.tipo_tramite != 'registro_actividad' THEN
RETURN NEW;
END IF;

-- Validate that user is not Agente (only for registro_actividad)
IF EXISTS (
SELECT 1 FROM usuarios
WHERE id = auth.uid()
AND rol = 'Agente'
) THEN
RAISE EXCEPTION 'Los agentes no pueden crear Registro de Actividades';
END IF;

-- Validate required fields
IF NEW.activity_subtype_id IS NULL THEN
RAISE EXCEPTION 'El tipo de trámite es obligatorio';
END IF;

IF NEW.agente_usuario_id IS NULL THEN
RAISE EXCEPTION 'El agente es obligatorio';
END IF;

IF NEW.insurance_type_id IS NULL THEN
RAISE EXCEPTION 'El tipo de seguro es obligatorio';
END IF;

IF NEW.attending_user_id IS NULL THEN
RAISE EXCEPTION 'Quién atiende es obligatorio';
END IF;

IF NEW.request_datetime IS NULL THEN
RAISE EXCEPTION 'La fecha y hora de solicitud es obligatoria';
END IF;

IF NEW.progress_percent IS NULL THEN
RAISE EXCEPTION 'El avance es obligatorio';
END IF;

-- Validate at least 1 insurer
IF NEW.insurers IS NULL OR jsonb_array_length(NEW.insurers) = 0 THEN
RAISE EXCEPTION 'Debe seleccionar al menos una aseguradora';
END IF;

-- Auto-complete fecha de finalización if progress = 100%
IF NEW.progress_percent = 100 AND NEW.completion_datetime IS NULL THEN
NEW.completion_datetime := now();
END IF;

-- Validate completion date is not before request date
IF NEW.completion_datetime IS NOT NULL AND NEW.completion_datetime < NEW.request_datetime THEN
RAISE EXCEPTION 'La fecha de finalización no puede ser anterior a la fecha de solicitud';
END IF;

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_ticket_file_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_current_count INTEGER;
BEGIN
  SELECT COUNT(*) INTO v_current_count
  FROM ticket_archivos
  WHERE ticket_id = NEW.ticket_id
    AND eliminado_at IS NULL;

  IF v_current_count >= 20 THEN
    RAISE EXCEPTION 'Este trámite permite un máximo de 20 documentos adjuntos. Elimina algún archivo o reduce la cantidad para continuar.';
  END IF;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.verify_qualitas_catalog_sync_token(p_token_hash text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'private', 'pg_temp'
AS $function$ SELECT EXISTS (
  SELECT 1 FROM private.qualitas_catalog_sync_auth
  WHERE singleton = true AND token_hash = p_token_hash
); $function$
;

CREATE OR REPLACE FUNCTION public.whatsapp_cred_get(p_configuracion_id uuid, p_key text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result text;
BEGIN
  SELECT extensions.pgp_sym_decrypt(api_key_cifrada, p_key) INTO v_result
  FROM whatsapp_credenciales
  WHERE configuracion_id = p_configuracion_id;
  RETURN v_result;
EXCEPTION WHEN OTHERS THEN
  RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.whatsapp_cred_set(p_configuracion_id uuid, p_api_key text, p_key text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO whatsapp_credenciales (configuracion_id, api_key_cifrada, updated_at)
  VALUES (p_configuracion_id, extensions.pgp_sym_encrypt(p_api_key, p_key), now())
  ON CONFLICT (configuracion_id) DO UPDATE
    SET api_key_cifrada = excluded.api_key_cifrada, updated_at = now();
END;
$function$
;

