CREATE OR REPLACE VIEW public.bitacora_comercial_view WITH (security_invoker=true) AS  SELECT 'store'::text AS modulo,
    p.id,
    (p.id)::text AS destino_id,
    p.folio_oc AS folio,
    p.created_at AS fecha,
    p.usuario_id AS solicitante_id,
    sol.nombre_completo AS solicitante_nombre,
    sol.oficina_id,
    ofi.nombre AS oficina_nombre,
    resp.nombre_completo AS responsable_nombre,
    COALESCE(d.cantidad_total, (0)::bigint) AS cantidad,
    COALESCE(d.monto_total, (0)::numeric) AS monto,
    p.forma_pago,
    (p.metodo_pago)::text AS metodo_pago,
    COALESCE(pg.pagado, (0)::numeric) AS pagado,
    (COALESCE(d.monto_total, (0)::numeric) - COALESCE(pg.pagado, (0)::numeric)) AS saldo,
    true AS activo,
    NULL::text AS plan,
        CASE
            WHEN (COALESCE(d.monto_total, (0)::numeric) = (0)::numeric) THEN 'sin_monto'::text
            WHEN (abs((COALESCE(pg.pagado, (0)::numeric) - COALESCE(d.monto_total, (0)::numeric))) <= 0.01) THEN 'al_corriente'::text
            WHEN (COALESCE(pg.pagado, (0)::numeric) > COALESCE(d.monto_total, (0)::numeric)) THEN 'a_favor'::text
            ELSE 'debe'::text
        END AS estado_pago
   FROM (((((store_pedidos p
     LEFT JOIN usuarios sol ON ((sol.id = p.usuario_id)))
     LEFT JOIN oficinas ofi ON ((ofi.id = sol.oficina_id)))
     LEFT JOIN usuarios resp ON ((resp.id = p.responsable_pago_id)))
     LEFT JOIN ( SELECT store_pedidos_detalle.pedido_id,
            sum(store_pedidos_detalle.cantidad) AS cantidad_total,
            sum(((store_pedidos_detalle.cantidad)::numeric * store_pedidos_detalle.precio_unitario)) AS monto_total
           FROM store_pedidos_detalle
          GROUP BY store_pedidos_detalle.pedido_id) d ON ((d.pedido_id = p.id)))
     LEFT JOIN ( SELECT store_pedido_pagos.pedido_id,
            sum(store_pedido_pagos.monto) AS pagado
           FROM store_pedido_pagos
          GROUP BY store_pedido_pagos.pedido_id) pg ON ((pg.pedido_id = p.id)))
UNION ALL
 SELECT 'premium'::text AS modulo,
    per.id,
    (per.usuario_id)::text AS destino_id,
    per.folio,
    (per.fecha_inicio)::timestamp with time zone AS fecha,
    per.usuario_id AS solicitante_id,
    u.nombre_completo AS solicitante_nombre,
    u.oficina_id,
    ofi.nombre AS oficina_nombre,
    u.nombre_completo AS responsable_nombre,
    1 AS cantidad,
    mkt_premium_monto_periodo(per.plan) AS monto,
    COALESCE(per.frecuencia_pago, per.plan) AS forma_pago,
    per.metodo_pago,
    COALESCE(pg.pagado, (0)::numeric) AS pagado,
    (mkt_premium_monto_periodo(per.plan) - COALESCE(pg.pagado, (0)::numeric)) AS saldo,
    (per.fecha_fin IS NULL) AS activo,
    per.plan,
        CASE
            WHEN (per.plan IS NULL) THEN 'sin_plan'::text
            WHEN (abs((COALESCE(pg.pagado, (0)::numeric) - mkt_premium_monto_periodo(per.plan))) <= 0.01) THEN 'al_corriente'::text
            WHEN (COALESCE(pg.pagado, (0)::numeric) > mkt_premium_monto_periodo(per.plan)) THEN 'a_favor'::text
            ELSE 'debe'::text
        END AS estado_pago
   FROM (((mkt_premium_periodos per
     LEFT JOIN usuarios u ON ((u.id = per.usuario_id)))
     LEFT JOIN oficinas ofi ON ((ofi.id = u.oficina_id)))
     LEFT JOIN ( SELECT mkt_premium_pagos.periodo_id,
            sum(mkt_premium_pagos.monto) AS pagado
           FROM mkt_premium_pagos
          WHERE (mkt_premium_pagos.periodo_id IS NOT NULL)
          GROUP BY mkt_premium_pagos.periodo_id) pg ON ((pg.periodo_id = per.id)));

CREATE OR REPLACE VIEW public.chava_knowledge_access_summary AS  SELECT t.id AS tier_id,
    t.nombre AS tier_nombre,
    count(DISTINCT c.id) AS carpetas_accesibles,
    count(DISTINCT a.id) AS archivos_accesibles,
    count(DISTINCT ch.id) AS chunks_indexados
   FROM (((chava_access_tiers t
     LEFT JOIN centro_digital_carpetas c ON (((c.activa = true) AND (c.enable_chava_ai = true) AND ((NOT t.solo_externo_filter) OR (c.external_chava_access = true)))))
     LEFT JOIN centro_digital_archivos a ON (((a.carpeta_id = c.id) AND (a.estado = 'activo'::text))))
     LEFT JOIN centro_digital_chunks ch ON ((ch.carpeta_id = c.id)))
  WHERE (t.activo = true)
  GROUP BY t.id, t.nombre;

CREATE OR REPLACE VIEW public.historial_notificaciones_unificado AS  SELECT tnh.id,
    tnt.name AS tipo_notificacion,
    tnh.event_key,
    u.nombre_completo AS destinatario_nombre,
    u.email_laboral AS destinatario_email,
    u.celular_laboral AS destinatario_telefono,
    tnh.email_sent,
    tnh.email_status AS estado_email,
    tnh.whatsapp_sent,
    tnh.whatsapp_status AS estado_whatsapp,
    tnh.variables,
    tnh.created_at AS fecha_envio
   FROM ((transactional_notification_history tnh
     LEFT JOIN usuarios u ON ((tnh.user_id = u.id)))
     LEFT JOIN transactional_notification_templates tnt ON ((tnh.event_key = tnt.event_key)))
  WHERE (tnh.event_key ~~ 'tramite_%'::text)
  ORDER BY tnh.created_at DESC;

CREATE OR REPLACE VIEW public.mis_polizas_view AS  SELECT sd.id,
    sd.id_docto,
    sd.poliza,
    sd.compania,
    sd.ramo,
    sd.subramo,
    sd.cliente,
    sd.vigencia_desde,
    sd.vigencia_hasta,
    sd.prima_neta,
    sd.importe,
    sd.vend_nombre,
    sd.desp_nombre,
    sd.oficina_id,
    sd.usuario_id,
    sd.synced_at,
    sd.created_at,
    o.nombre AS oficina_nombre,
    u.nombre_completo AS vendedor_nombre_completo,
    (EXTRACT(day FROM (sd.vigencia_hasta - (CURRENT_DATE)::timestamp with time zone)))::integer AS dias_hasta_vencimiento,
    (sd.vigencia_hasta >= CURRENT_DATE) AS esta_vigente
   FROM ((sicas_documents sd
     LEFT JOIN oficinas o ON ((sd.oficina_id = o.id)))
     LEFT JOIN usuarios u ON ((sd.usuario_id = u.id)));

CREATE OR REPLACE VIEW public.mkt_premium_bitacora_view WITH (security_invoker=true) AS  SELECT per.id,
    per.folio,
    (per.fecha_inicio)::timestamp with time zone AS fecha,
    per.usuario_id AS solicitante_id,
    u.nombre_completo AS solicitante_nombre,
    per.usuario_id AS responsable_id,
    u.nombre_completo AS responsable_nombre,
    1 AS cantidad,
        CASE per.plan
            WHEN 'anual'::text THEN 2000
            WHEN 'mensual'::text THEN 200
            ELSE 0
        END AS monto,
    COALESCE(per.frecuencia_pago, per.plan) AS forma_pago,
    per.metodo_pago,
    COALESCE(pg.pagado, (0)::numeric) AS pagado,
    ((
        CASE per.plan
            WHEN 'anual'::text THEN 2000
            WHEN 'mensual'::text THEN 200
            ELSE 0
        END)::numeric - COALESCE(pg.pagado, (0)::numeric)) AS saldo,
    per.fecha_fin,
    (per.fecha_fin IS NULL) AS activo,
        CASE
            WHEN (per.plan IS NULL) THEN 'sin_plan'::text
            WHEN ((COALESCE(pg.pagado, (0)::numeric) >= ((
            CASE per.plan
                WHEN 'anual'::text THEN 2000
                WHEN 'mensual'::text THEN 200
                ELSE 0
            END)::numeric - 0.01)) AND (COALESCE(pg.pagado, (0)::numeric) <= ((
            CASE per.plan
                WHEN 'anual'::text THEN 2000
                WHEN 'mensual'::text THEN 200
                ELSE 0
            END)::numeric + 0.01))) THEN 'al_corriente'::text
            WHEN (COALESCE(pg.pagado, (0)::numeric) > ((
            CASE per.plan
                WHEN 'anual'::text THEN 2000
                WHEN 'mensual'::text THEN 200
                ELSE 0
            END)::numeric + 0.01)) THEN 'a_favor'::text
            ELSE 'debe'::text
        END AS estado_pago
   FROM ((mkt_premium_periodos per
     LEFT JOIN usuarios u ON ((u.id = per.usuario_id)))
     LEFT JOIN LATERAL ( SELECT sum(mp.monto) AS pagado
           FROM mkt_premium_pagos mp
          WHERE ((mp.usuario_id = per.usuario_id) AND (mp.fecha >= per.fecha_inicio) AND (mp.fecha < COALESCE(per.fecha_fin, (CURRENT_DATE + 1))))) pg ON (true));

CREATE OR REPLACE VIEW public.sicas_cobranza_pendiente AS  SELECT id,
    cliente,
    poliza AS no_poliza,
    id_docto AS id_documento,
    importe_pendiente,
    fecha_limite,
    dias_vencido AS dias_vencidos,
    estatus AS status,
    usuario_id,
    oficina_id,
    vend_id,
    vend_nombre,
    created_at,
    updated_at
   FROM sicas_receivables
  WHERE (estatus = 'pendiente'::text);

CREATE OR REPLACE VIEW public.sicas_config_view AS  SELECT id,
    endpoint AS sicas_url,
    endpoint,
    sicas_usuario,
    sicas_password,
    sicas_namespace,
    last_test_at,
    last_test_success,
    last_test_message,
    last_sync_despachos_at,
    last_sync_vendedores_at,
    sync_logs,
