    updated_at
   FROM sicas_config;

CREATE OR REPLACE VIEW public.sicas_emitidas_mes_actual AS  SELECT id,
    id_docto AS id_documento,
    poliza AS no_poliza,
    compania AS aseguradora,
    ramo,
    cliente AS contratante,
    vigencia_desde,
    importe AS prima_total,
    usuario_id,
    oficina_id,
    vend_id,
    vend_nombre,
    fecha_captura,
    synced_at,
    created_at,
    updated_at
   FROM sicas_documents
  WHERE ((EXTRACT(year FROM fecha_captura) = EXTRACT(year FROM CURRENT_DATE)) AND (EXTRACT(month FROM fecha_captura) = EXTRACT(month FROM CURRENT_DATE)));

CREATE OR REPLACE VIEW public.sicas_polizas_vigentes AS  SELECT id,
    id_docto AS id_documento,
    poliza AS no_poliza,
    compania AS aseguradora,
    ramo,
    subramo,
    cliente AS contratante,
    cliente AS asegurado,
    vigencia_desde,
    vigencia_hasta,
    prima_neta,
    importe AS prima_total,
    usuario_id,
    oficina_id,
    vend_id,
    vend_nombre,
    desp_nombre,
    oficina_id AS desp_id,
    synced_at,
    created_at,
    updated_at
   FROM sicas_documents
  WHERE (vigencia_hasta >= CURRENT_DATE);

CREATE OR REPLACE VIEW public.sicas_renovaciones_proximas AS  SELECT id,
    id_docto AS id_documento,
    poliza AS no_poliza,
    compania AS aseguradora,
    ramo,
    cliente AS contratante,
    vigencia_hasta,
    importe AS prima_total,
    (EXTRACT(day FROM (vigencia_hasta - (CURRENT_DATE)::timestamp with time zone)))::integer AS dias_para_vencer,
        CASE
            WHEN (vigencia_hasta <= CURRENT_DATE) THEN 'Vencida'::text
            WHEN (vigencia_hasta <= (CURRENT_DATE + '7 days'::interval)) THEN 'Urgente'::text
            WHEN (vigencia_hasta <= (CURRENT_DATE + '30 days'::interval)) THEN 'Alta'::text
            WHEN (vigencia_hasta <= (CURRENT_DATE + '60 days'::interval)) THEN 'Media'::text
            ELSE 'Baja'::text
        END AS prioridad_renovacion,
    usuario_id,
    oficina_id,
    vend_id,
    vend_nombre
   FROM sicas_documents
  WHERE ((vigencia_hasta >= CURRENT_DATE) AND (vigencia_hasta <= (CURRENT_DATE + '90 days'::interval)));

CREATE OR REPLACE VIEW public.store_bitacora_view WITH (security_invoker=true) AS  SELECT p.id,
    p.folio_oc AS folio,
    p.created_at AS fecha,
    p.usuario_id AS solicitante_id,
    sol.nombre_completo AS solicitante_nombre,
    p.responsable_pago_id AS responsable_id,
    resp.nombre_completo AS responsable_nombre,
    COALESCE(d.cantidad_total, (0)::bigint) AS cantidad,
    COALESCE(d.monto_total, (0)::numeric) AS monto,
    p.forma_pago,
    (p.metodo_pago)::text AS metodo_pago,
    COALESCE(pg.pagado, (0)::numeric) AS pagado,
    (COALESCE(d.monto_total, (0)::numeric) - COALESCE(pg.pagado, (0)::numeric)) AS saldo,
        CASE
            WHEN (COALESCE(d.monto_total, (0)::numeric) = (0)::numeric) THEN 'sin_monto'::text
            WHEN ((COALESCE(pg.pagado, (0)::numeric) >= (COALESCE(d.monto_total, (0)::numeric) - 0.01)) AND (COALESCE(pg.pagado, (0)::numeric) <= (COALESCE(d.monto_total, (0)::numeric) + 0.01))) THEN 'al_corriente'::text
            WHEN (COALESCE(pg.pagado, (0)::numeric) > (COALESCE(d.monto_total, (0)::numeric) + 0.01)) THEN 'a_favor'::text
            ELSE 'debe'::text
        END AS estado_pago
   FROM ((((store_pedidos p
     LEFT JOIN usuarios sol ON ((sol.id = p.usuario_id)))
     LEFT JOIN usuarios resp ON ((resp.id = p.responsable_pago_id)))
     LEFT JOIN ( SELECT store_pedidos_detalle.pedido_id,
            sum(store_pedidos_detalle.cantidad) AS cantidad_total,
            sum(((store_pedidos_detalle.cantidad)::numeric * store_pedidos_detalle.precio_unitario)) AS monto_total
           FROM store_pedidos_detalle
          GROUP BY store_pedidos_detalle.pedido_id) d ON ((d.pedido_id = p.id)))
     LEFT JOIN ( SELECT store_pedido_pagos.pedido_id,
            sum(store_pedido_pagos.monto) AS pagado
           FROM store_pedido_pagos
          GROUP BY store_pedido_pagos.pedido_id) pg ON ((pg.pedido_id = p.id)));

CREATE OR REPLACE VIEW public.tramites_productividad_oficina WITH (security_invoker=true) AS  WITH ultima_asignacion AS (
         SELECT DISTINCT ON (ta.ticket_id) ta.ticket_id,
            ta.ejecutivo_id,
            ta.asignado_en
           FROM ticket_asignaciones ta
          ORDER BY ta.ticket_id, ta.asignado_en DESC
        )
 SELECT o.id AS oficina_id,
    o.nombre AS oficina_nombre,
    count(DISTINCT t.id) AS total_tramites,
    count(DISTINCT
        CASE
            WHEN (COALESCE(t.progress_percent, 0) = 0) THEN t.id
            ELSE NULL::uuid
        END) AS tramites_pendientes,
    count(DISTINCT
        CASE
            WHEN ((t.progress_percent > 0) AND (t.progress_percent < 100)) THEN t.id
            ELSE NULL::uuid
        END) AS tramites_en_proceso,
    count(DISTINCT
        CASE
            WHEN (t.progress_percent = 100) THEN t.id
            ELSE NULL::uuid
        END) AS tramites_finalizados,
    COALESCE(round(avg(COALESCE(t.progress_percent, 0)), 2), (0)::numeric) AS avance_promedio,
    COALESCE(round(avg(
        CASE
            WHEN (t.cerrado_en IS NOT NULL) THEN (EXTRACT(epoch FROM (t.cerrado_en - t.fecha_creacion)) / 86400.0)
            ELSE NULL::numeric
        END), 2), (0)::numeric) AS tiempo_promedio_resolucion_dias,
    COALESCE(round((((count(DISTINCT
        CASE
            WHEN (t.progress_percent = 100) THEN t.id
            ELSE NULL::uuid
        END))::numeric / (NULLIF(count(DISTINCT t.id), 0))::numeric) * (100)::numeric), 2), (0)::numeric) AS porcentaje_finalizacion,
    count(DISTINCT u.id) AS usuarios_activos
   FROM (((oficinas o
     LEFT JOIN usuarios u ON (((u.oficina_id = o.id) AND (u.estado = 'activo'::text))))
     LEFT JOIN ultima_asignacion ua ON ((ua.ejecutivo_id = u.id)))
     LEFT JOIN tickets t ON ((ua.ticket_id = t.id)))
  WHERE (o.activa = true)
  GROUP BY o.id, o.nombre
 HAVING (count(DISTINCT t.id) > 0);

CREATE OR REPLACE VIEW public.tramites_productividad_usuario WITH (security_invoker=true) AS  WITH ultima_asignacion AS (
         SELECT DISTINCT ON (ta.ticket_id) ta.ticket_id,
            ta.ejecutivo_id,
            ta.asignado_en
           FROM ticket_asignaciones ta
          ORDER BY ta.ticket_id, ta.asignado_en DESC
        )
 SELECT u.id AS usuario_id,
    u.nombre_completo,
    u.oficina_id,
    o.nombre AS oficina_nombre,
    count(DISTINCT t.id) AS total_tramites,
    count(DISTINCT
        CASE
            WHEN (COALESCE(t.progress_percent, 0) = 0) THEN t.id
            ELSE NULL::uuid
        END) AS tramites_pendientes,
    count(DISTINCT
        CASE
            WHEN ((t.progress_percent > 0) AND (t.progress_percent < 100)) THEN t.id
            ELSE NULL::uuid
        END) AS tramites_en_proceso,
    count(DISTINCT
        CASE
            WHEN (t.progress_percent = 100) THEN t.id
            ELSE NULL::uuid
        END) AS tramites_finalizados,
    COALESCE(round(avg(COALESCE(t.progress_percent, 0)), 2), (0)::numeric) AS avance_promedio,
    COALESCE(round(avg(
        CASE
            WHEN (t.cerrado_en IS NOT NULL) THEN (EXTRACT(epoch FROM (t.cerrado_en - t.fecha_creacion)) / 86400.0)
            ELSE NULL::numeric
        END), 2), (0)::numeric) AS tiempo_promedio_resolucion_dias,
    COALESCE(round((((count(DISTINCT
        CASE
            WHEN (t.progress_percent = 100) THEN t.id
            ELSE NULL::uuid
        END))::numeric / (NULLIF(count(DISTINCT t.id), 0))::numeric) * (100)::numeric), 2), (0)::numeric) AS porcentaje_finalizacion
   FROM (((usuarios u
     LEFT JOIN oficinas o ON ((u.oficina_id = o.id)))
     LEFT JOIN ultima_asignacion ua ON ((ua.ejecutivo_id = u.id)))
     LEFT JOIN tickets t ON ((ua.ticket_id = t.id)))
  WHERE (u.estado = 'activo'::text)
  GROUP BY u.id, u.nombre_completo, u.oficina_id, o.nombre
 HAVING (count(DISTINCT t.id) > 0);

CREATE OR REPLACE VIEW public.tramites_reportes_view WITH (security_invoker=true) AS  SELECT t.id,
    t.folio,
    t.tipo_tramite,
    t.prioridad,
    t.instrucciones,
    t.poliza,
    t.fecha_creacion AS fecha_solicitud,
    COALESCE(t.progress_percent, 0) AS avance,
        CASE
            WHEN (COALESCE(t.progress_percent, 0) = 0) THEN 'Pendiente'::text
            WHEN (t.progress_percent = 100) THEN 'Finalizado'::text
            ELSE 'En Proceso'::text
        END AS estatus_calculado,
    t.cerrado_en AS fecha_finalizacion,
        CASE
            WHEN (t.cerrado_en IS NOT NULL) THEN (EXTRACT(epoch FROM (t.cerrado_en - t.fecha_creacion)) / 86400.0)
            ELSE NULL::numeric
        END AS tiempo_resolucion_dias,
    solicitante.id AS solicitante_id,
    solicitante.nombre_completo AS solicitante_nombre,
    solicitante.oficina_id AS solicitante_oficina_id,
    COALESCE(asignado_directo.id, asignado_agente.id, asignado_tabla.id) AS asignado_id,
    COALESCE(asignado_directo.nombre_completo, asignado_agente.nombre_completo, asignado_tabla.nombre_completo) AS asignado_nombre,
    COALESCE(asignado_directo.oficina_id, asignado_agente.oficina_id, asignado_tabla.oficina_id) AS asignado_oficina_id,
    oficina_asignado.nombre AS oficina_nombre,
    estatus.nombre AS estatus_nombre
   FROM ((((((tickets t
     LEFT JOIN usuarios solicitante ON ((t.creado_por = solicitante.id)))
     LEFT JOIN ticket_estatus estatus ON ((t.estatus_id = estatus.id)))
     LEFT JOIN usuarios asignado_directo ON ((t.assigned_to_user_id = asignado_directo.id)))
     LEFT JOIN usuarios asignado_agente ON ((t.agente_id = asignado_agente.id)))
     LEFT JOIN LATERAL ( SELECT DISTINCT ON (ta.ticket_id) u.id,
            u.nombre_completo,
            u.oficina_id
           FROM (ticket_asignaciones ta
             JOIN usuarios u ON ((ta.ejecutivo_id = u.id)))
          WHERE (ta.ticket_id = t.id)
          ORDER BY ta.ticket_id, ta.asignado_en DESC) asignado_tabla ON (true))
     LEFT JOIN oficinas oficina_asignado ON ((COALESCE(asignado_directo.oficina_id, asignado_agente.oficina_id, asignado_tabla.oficina_id) = oficina_asignado.id)));

CREATE OR REPLACE VIEW public.unified_activity_view AS  SELECT user_activity_logs.id,
    user_activity_logs.user_id,
    user_activity_logs.user_name_snapshot,
    user_activity_logs.email_snapshot,
    user_activity_logs.office_id,
    user_activity_logs.office_name_snapshot,
    user_activity_logs.role_snapshot,
    user_activity_logs.module,
    user_activity_logs.event_type,
    user_activity_logs.action,
    user_activity_logs.entity_type,
    user_activity_logs.entity_id,
    user_activity_logs.summary,
    user_activity_logs.details,
    user_activity_logs.metadata,
    user_activity_logs.status,
    user_activity_logs.created_at
   FROM user_activity_logs
UNION ALL
 SELECT th.id,
    th.usuario_id AS user_id,
    COALESCE(u.nombre_completo, ((u.nombre || ' '::text) || u.apellidos), 'Desconocido'::text) AS user_name_snapshot,
    u.email_laboral AS email_snapshot,
    u.oficina_id AS office_id,
    o.nombre AS office_name_snapshot,
    u.rol AS role_snapshot,
    'tramites'::text AS module,
    'tramites'::text AS event_type,
        CASE
            WHEN (th.tipo_accion = 'estatus'::text) THEN 'tramite_status_change'::text
            WHEN (th.tipo_accion = 'comentario'::text) THEN 'tramite_comment'::text
            WHEN (th.tipo_accion = 'asignacion'::text) THEN 'tramite_assignment'::text
            WHEN (th.tipo_accion = 'archivo'::text) THEN 'tramite_file'::text
            ELSE COALESCE(th.tipo_accion, 'tramite_action'::text)
        END AS action,
    'ticket'::text AS entity_type,
    (th.ticket_id)::text AS entity_id,
    COALESCE(th.descripcion, th.accion, 'Accion en tramite'::text) AS summary,
    COALESCE(th.detalle, '{}'::jsonb) AS details,
    '{}'::jsonb AS metadata,
    'success'::text AS status,
    th.fecha_hora AS created_at
   FROM ((ticket_historial th
     LEFT JOIN usuarios u ON ((u.id = th.usuario_id)))
     LEFT JOIN oficinas o ON ((o.id = u.oficina_id)))
  WHERE (th.usuario_id IS NOT NULL)
UNION ALL
 SELECT al.id,
    al.performed_by AS user_id,
    COALESCE(u.nombre_completo, ((u.nombre || ' '::text) || u.apellidos), 'Desconocido'::text) AS user_name_snapshot,
    u.email_laboral AS email_snapshot,
    u.oficina_id AS office_id,
    o.nombre AS office_name_snapshot,
    u.rol AS role_snapshot,
    'system'::text AS module,
    'system'::text AS event_type,
    al.action,
    COALESCE(al.target_resource_type, 'system'::text) AS entity_type,
    (al.target_user_id)::text AS entity_id,
        CASE
            WHEN (al.action = 'activate_user'::text) THEN ('Activo usuario: '::text || COALESCE((al.details ->> 'target_nombre'::text), ''::text))
            WHEN (al.action = 'deactivate_user'::text) THEN ('Desactivo usuario: '::text || COALESCE((al.details ->> 'target_nombre'::text), ''::text))
            WHEN (al.action = 'soft_delete_user'::text) THEN ('Elimino usuario: '::text || COALESCE((al.details ->> 'target_nombre'::text), ''::text))
            ELSE ('Accion administrativa: '::text || al.action)
        END AS summary,
    COALESCE(al.details, '{}'::jsonb) AS details,
    jsonb_build_object('ip', COALESCE(al.ip_address, ''::text), 'ua', COALESCE(al.user_agent, ''::text)) AS metadata,
    'success'::text AS status,
    al.created_at
   FROM ((audit_logs al
     LEFT JOIN usuarios u ON ((u.id = al.performed_by)))
     LEFT JOIN oficinas o ON ((o.id = u.oficina_id)))
  WHERE (al.performed_by IS NOT NULL)
UNION ALL
 SELECT ch.id,
    COALESCE(ch.enviado_por, ch.usuario_id, ch.destinatario_id) AS user_id,
    COALESCE(ch.destinatario_nombre, u.nombre_completo, 'Sistema'::text) AS user_name_snapshot,
    COALESCE(ch.destinatario_email, u.email_laboral) AS email_snapshot,
    u.oficina_id AS office_id,
    o.nombre AS office_name_snapshot,
    u.rol AS role_snapshot,
    'system'::text AS module,
    'system'::text AS event_type,
    'notification_sent'::text AS action,
    COALESCE(ch.canal_envio, 'correo'::text) AS entity_type,
    ch.tipo_notificacion_codigo AS entity_id,
        CASE
            WHEN (ch.canal_envio = 'whatsapp'::text) THEN ('WhatsApp enviado: '::text || COALESCE(ch.tipo_notificacion_codigo, ''::text))
            ELSE ('Correo enviado: '::text || COALESCE(ch.asunto, ch.tipo_notificacion_codigo, ''::text))
        END AS summary,
    jsonb_build_object('estado', ch.estado, 'canal', ch.canal_envio, 'tipo', ch.tipo_notificacion_codigo) AS details,
    '{}'::jsonb AS metadata,
        CASE
            WHEN (ch.estado = 'enviado'::text) THEN 'success'::text
            WHEN (ch.estado = 'error'::text) THEN 'error'::text
            ELSE 'warning'::text
        END AS status,
    COALESCE(ch.fecha_envio, ch.created_at) AS created_at
   FROM ((correo_historial_envios ch
     LEFT JOIN usuarios u ON ((u.id = COALESCE(ch.enviado_por, ch.usuario_id, ch.destinatario_id))))
     LEFT JOIN oficinas o ON ((o.id = u.oficina_id)))
  WHERE (COALESCE(ch.enviado_por, ch.usuario_id, ch.destinatario_id) IS NOT NULL)
UNION ALL
 SELECT cda.id,
    cda.usuario_id AS user_id,
    COALESCE(u.nombre_completo, ((u.nombre || ' '::text) || u.apellidos), 'Desconocido'::text) AS user_name_snapshot,
    u.email_laboral AS email_snapshot,
    u.oficina_id AS office_id,
    o.nombre AS office_name_snapshot,
    u.rol AS role_snapshot,
    'centro_digital'::text AS module,
    'digital'::text AS event_type,
    cda.accion AS action,
    'file'::text AS entity_type,
    COALESCE((cda.archivo_id)::text, (cda.carpeta_id)::text) AS entity_id,
        CASE
            WHEN (cda.accion = 'archivo_subido'::text) THEN ('Subio archivo: '::text || COALESCE((cda.detalles ->> 'nombre'::text), ''::text))
            WHEN (cda.accion = 'archivo_descargado'::text) THEN ('Descargo archivo: '::text || COALESCE((cda.detalles ->> 'nombre'::text), ''::text))
            WHEN (cda.accion = 'archivo_eliminado'::text) THEN ('Elimino archivo: '::text || COALESCE((cda.detalles ->> 'nombre'::text), ''::text))
            WHEN (cda.accion = 'carpeta_creada'::text) THEN ('Creo carpeta: '::text || COALESCE((cda.detalles ->> 'nombre'::text), ''::text))
            ELSE ('Accion: '::text || cda.accion)
        END AS summary,
    COALESCE(cda.detalles, '{}'::jsonb) AS details,
    '{}'::jsonb AS metadata,
    'success'::text AS status,
    cda.created_at
   FROM ((centro_digital_auditoria cda
     LEFT JOIN usuarios u ON ((u.id = cda.usuario_id)))
     LEFT JOIN oficinas o ON ((o.id = u.oficina_id)))
  WHERE (cda.usuario_id IS NOT NULL);

CREATE OR REPLACE VIEW public.usuarios_con_telefono_normalizado AS  SELECT u.id,
    u.nombre,
    u.apellidos,
    u.email_laboral,
    u.celular_laboral,
    normalizar_telefono_mx(u.celular_laboral) AS telefono_normalizado,
    u.rol,
    o.nombre AS oficina_nombre
   FROM (usuarios u
     LEFT JOIN oficinas o ON ((u.oficina_id = o.id)))
  WHERE ((u.celular_laboral IS NOT NULL) AND (u.celular_laboral <> ''::text));

CREATE OR REPLACE VIEW public.usuarios_eliminados AS  SELECT u.id,
    u.nombre,
    u.apellidos,
    u.email_laboral,
    u.rol,
    o.nombre AS oficina_nombre,
    u.deleted_at,
    u.deleted_by_user_id,
    admin.nombre AS eliminado_por_nombre,
    admin.apellidos AS eliminado_por_apellidos
   FROM ((usuarios u
     LEFT JOIN oficinas o ON ((u.oficina_id = o.id)))
     LEFT JOIN usuarios admin ON ((u.deleted_by_user_id = admin.id)))
  WHERE (u.is_deleted = true)
  ORDER BY u.deleted_at DESC;

CREATE OR REPLACE VIEW public.v_analytics_clases_stats WITH (security_invoker=true) AS  SELECT avs.id AS class_id,
    avs.titulo,
    avs.fecha_inicio,
    avs.instructor_id,
    ui.nombre_completo AS instructor_nombre,
    count(DISTINCT
        CASE
            WHEN (e.event_type = 'class_open'::text) THEN e.user_id
            ELSE NULL::uuid
        END) AS aperturas,
    count(DISTINCT
        CASE
            WHEN (e.event_type = 'class_join_click'::text) THEN e.user_id
            ELSE NULL::uuid
        END) AS clicks_entrar,
    count(DISTINCT
        CASE
            WHEN (e.event_type = 'class_join_success'::text) THEN e.user_id
            ELSE NULL::uuid
        END) AS joins_exitosos,
    count(DISTINCT
        CASE
            WHEN (e.event_type = 'class_recording_open'::text) THEN e.user_id
            ELSE NULL::uuid
        END) AS vistas_grabacion,
    count(DISTINCT e.user_id) AS usuarios_unicos,
    ( SELECT jsonb_agg(jsonb_build_object('oficina_id', sub.oficina_id, 'oficina_nombre', o.nombre, 'count', sub.count) ORDER BY sub.count DESC) AS jsonb_agg
           FROM (( SELECT seguros_education_eventos.oficina_id,
                    count(DISTINCT seguros_education_eventos.user_id) AS count
                   FROM seguros_education_eventos
                  WHERE (seguros_education_eventos.class_id = avs.id)
                  GROUP BY seguros_education_eventos.oficina_id
                  ORDER BY (count(DISTINCT seguros_education_eventos.user_id)) DESC
                 LIMIT 3) sub
             LEFT JOIN oficinas o ON ((o.id = sub.oficina_id)))) AS top_oficinas
   FROM ((aula_virtual_sesiones avs
     LEFT JOIN usuarios ui ON ((ui.id = avs.instructor_id)))
     LEFT JOIN seguros_education_eventos e ON ((e.class_id = avs.id)))
  GROUP BY avs.id, avs.titulo, avs.fecha_inicio, avs.instructor_id, ui.nombre_completo;

CREATE OR REPLACE VIEW public.v_analytics_lecciones_stats WITH (security_invoker=true) AS  SELECT l.id AS lesson_id,
    l.titulo,
    ( SELECT jsonb_agg(jsonb_build_object('id', c.id, 'nombre', c.nombre, 'icono', c.icono)) AS jsonb_agg
           FROM (seguros_lesson_categories slc
             JOIN seguros_categories c ON ((c.id = slc.category_id)))
          WHERE (slc.lesson_id = l.id)) AS categorias,
    count(DISTINCT
        CASE
            WHEN s.es_reproduccion_valida THEN s.user_id
            ELSE NULL::uuid
        END) AS reproducciones,
    count(DISTINCT s.user_id) AS usuarios_unicos,
    count(DISTINCT
        CASE
            WHEN s.completo THEN s.user_id
            ELSE NULL::uuid
        END) AS completadas,
    round(((100.0 * (count(DISTINCT
        CASE
            WHEN s.completo THEN s.user_id
            ELSE NULL::uuid
        END))::numeric) / (NULLIF(count(DISTINCT
        CASE
            WHEN s.es_reproduccion_valida THEN s.user_id
            ELSE NULL::uuid
        END), 0))::numeric), 2) AS completion_rate_percent,
    round(avg(s.duracion_total_segundos)) AS tiempo_promedio_segundos,
    sum(s.duracion_total_segundos) AS tiempo_total_segundos,
    max(s.inicio) AS ultima_visualizacion,
    ( SELECT jsonb_agg(jsonb_build_object('oficina_id', sub.oficina_id, 'oficina_nombre', o.nombre, 'count', sub.count) ORDER BY sub.count DESC) AS jsonb_agg
           FROM (( SELECT seguros_education_sesiones.oficina_id,
                    count(*) AS count
                   FROM seguros_education_sesiones
                  WHERE ((seguros_education_sesiones.lesson_id = l.id) AND seguros_education_sesiones.es_reproduccion_valida)
                  GROUP BY seguros_education_sesiones.oficina_id
                  ORDER BY (count(*)) DESC
                 LIMIT 3) sub
             LEFT JOIN oficinas o ON ((o.id = sub.oficina_id)))) AS top_oficinas
   FROM (seguros_lessons l
     LEFT JOIN seguros_education_sesiones s ON ((s.lesson_id = l.id)))
  GROUP BY l.id, l.titulo;

CREATE OR REPLACE VIEW public.v_analytics_usuarios_stats WITH (security_invoker=true) AS  SELECT u.id AS user_id,
    u.nombre_completo,
    u.email_laboral,
    u.oficina_id,
    o.nombre AS oficina_nombre,
    u.rol,
    count(DISTINCT
        CASE
            WHEN (s.es_reproduccion_valida AND (s.lesson_id IS NOT NULL)) THEN s.lesson_id
            ELSE NULL::uuid
        END) AS lecciones_vistas,
    count(DISTINCT
        CASE
            WHEN (s.completo AND (s.lesson_id IS NOT NULL)) THEN s.lesson_id
            ELSE NULL::uuid
        END) AS lecciones_completadas,
    count(DISTINCT
        CASE
            WHEN (s.class_id IS NOT NULL) THEN s.class_id
            ELSE NULL::uuid
        END) AS clases_abiertas,
    round(((sum(s.duracion_total_segundos))::numeric / (60)::numeric), 1) AS tiempo_total_minutos,
    max(s.inicio) AS ultimo_acceso,
    count(DISTINCT date(s.inicio)) AS dias_activos
   FROM ((usuarios u
     LEFT JOIN oficinas o ON ((o.id = u.oficina_id)))
     LEFT JOIN seguros_education_sesiones s ON ((s.user_id = u.id)))
  WHERE (u.deleted_at IS NULL)
  GROUP BY u.id, u.nombre_completo, u.email_laboral, u.oficina_id, o.nombre, u.rol;

CREATE OR REPLACE VIEW public.v_catalogo_notificaciones AS  SELECT ctn.id,
    ctn.codigo,
    ctn.nombre,
    ctn.descripcion,
    ctn.modulo,
    COALESCE(ctn.nombre_estandar, ctn.nombre) AS nombre_estandar,
    ctn.trigger_event,
    ctn.destinatario_tipo,
    ctn.activo,
    ctn.es_obsoleto,
    ctn.enviar_correo,
    ctn.enviar_whatsapp,
    ctn.enviar_notificacion,
    ctn.created_at,
        CASE
            WHEN (cp.id IS NOT NULL) THEN true
            ELSE false
        END AS tiene_plantilla,
    cp.asunto AS plantilla_asunto,
    cp.id AS plantilla_id
   FROM (correo_tipos_notificacion ctn
     LEFT JOIN correo_plantillas cp ON (((cp.tipo_notificacion_id = ctn.id) AND (cp.es_plantilla_default = true))))
  ORDER BY ctn.modulo, ctn.nombre;

CREATE OR REPLACE VIEW public.v_kpis_cotizacion_emision AS  SELECT date_trunc('month'::text, t.fecha_creacion) AS periodo,
    count(*) FILTER (WHERE (t.resultado = 'ganado'::text)) AS total_emitidos,
    count(*) FILTER (WHERE (t.resultado = 'perdido'::text)) AS total_no_emitidos,
    count(*) FILTER (WHERE (t.resultado = 'en_progreso'::text)) AS total_en_proceso,
    count(*) AS total_tramites,
    round((((count(*) FILTER (WHERE (t.resultado = 'ganado'::text)))::numeric / NULLIF((count(*) FILTER (WHERE (t.resultado = ANY (ARRAY['ganado'::text, 'perdido'::text]))))::numeric, (0)::numeric)) * (100)::numeric), 2) AS tasa_conversion_porcentaje,
    t.creado_por,
    u.nombre_completo AS creado_por_nombre,
    o.nombre AS oficina_nombre
   FROM ((tickets t
     LEFT JOIN usuarios u ON ((t.creado_por = u.id)))
     LEFT JOIN oficinas o ON ((u.oficina_id = o.id)))
  WHERE ((t.tipo_tramite = 'registro_actividad'::text) AND (t.activity_subtype_id IN ( SELECT tramite_activity_types.id
           FROM tramite_activity_types
          WHERE ((lower(tramite_activity_types.nombre) ~~ '%cotizaci%'::text) OR (lower(tramite_activity_types.nombre) ~~ '%emisi%'::text)))))
  GROUP BY (date_trunc('month'::text, t.fecha_creacion)), t.creado_por, u.nombre_completo, o.nombre
  ORDER BY (date_trunc('month'::text, t.fecha_creacion)) DESC;

CREATE OR REPLACE VIEW public.v_tramites_conversion_metrics WITH (security_invoker=true) AS  SELECT count(*) AS total_tramites,
    count(*) FILTER (WHERE (t.resultado = 'ganado'::text)) AS total_emitidos,
    count(*) FILTER (WHERE (t.resultado = 'perdido'::text)) AS total_no_emitidos,
    count(*) FILTER (WHERE (t.resultado = 'en_progreso'::text)) AS total_en_proceso,
    round((((count(*) FILTER (WHERE (t.resultado = 'ganado'::text)))::numeric / NULLIF((count(*) FILTER (WHERE (t.resultado = ANY (ARRAY['ganado'::text, 'perdido'::text]))))::numeric, (0)::numeric)) * (100)::numeric), 1) AS tasa_conversion,
    date_trunc('month'::text, t.fecha_creacion) AS periodo,
    t.creado_por AS usuario_id,
    u.nombre_completo AS usuario_nombre,
    u.oficina_id,
    o.nombre AS oficina_nombre
   FROM ((tickets t
     LEFT JOIN usuarios u ON ((t.creado_por = u.id)))
     LEFT JOIN oficinas o ON ((u.oficina_id = o.id)))
  WHERE ((t.tipo_tramite = 'registro_actividad'::text) AND (t.activity_subtype_id IN ( SELECT tramite_activity_types.id
           FROM tramite_activity_types
          WHERE ((lower(tramite_activity_types.nombre) ~~ '%cotizaci%'::text) OR (lower(tramite_activity_types.nombre) ~~ '%emisi%'::text)))))
  GROUP BY (date_trunc('month'::text, t.fecha_creacion)), t.creado_por, u.nombre_completo, u.oficina_id, o.nombre;

CREATE OR REPLACE VIEW public.v_tramites_ranking_agentes WITH (security_invoker=true) AS  SELECT t.creado_por AS agente_id,
    u.nombre_completo AS agente_nombre,
    u.oficina_id,
    o.nombre AS oficina_nombre,
    count(*) AS total_tramites,
    count(*) FILTER (WHERE (t.resultado = 'ganado'::text)) AS total_emitidos,
    count(*) FILTER (WHERE (t.resultado = 'perdido'::text)) AS total_no_emitidos,
    count(*) FILTER (WHERE (t.resultado = 'en_progreso'::text)) AS total_en_proceso,
    round((((count(*) FILTER (WHERE (t.resultado = 'ganado'::text)))::numeric / NULLIF((count(*) FILTER (WHERE (t.resultado = ANY (ARRAY['ganado'::text, 'perdido'::text]))))::numeric, (0)::numeric)) * (100)::numeric), 1) AS tasa_conversion
   FROM ((tickets t
     LEFT JOIN usuarios u ON ((t.creado_por = u.id)))
     LEFT JOIN oficinas o ON ((u.oficina_id = o.id)))
  WHERE ((t.tipo_tramite = 'registro_actividad'::text) AND (t.activity_subtype_id IN ( SELECT tramite_activity_types.id
           FROM tramite_activity_types
          WHERE ((lower(tramite_activity_types.nombre) ~~ '%cotizaci%'::text) OR (lower(tramite_activity_types.nombre) ~~ '%emisi%'::text)))))
  GROUP BY t.creado_por, u.nombre_completo, u.oficina_id, o.nombre
 HAVING (count(*) > 0)
  ORDER BY (round((((count(*) FILTER (WHERE (t.resultado = 'ganado'::text)))::numeric / NULLIF((count(*) FILTER (WHERE (t.resultado = ANY (ARRAY['ganado'::text, 'perdido'::text]))))::numeric, (0)::numeric)) * (100)::numeric), 1)) DESC NULLS LAST, (count(*)) DESC;

CREATE OR REPLACE VIEW public.vista_comisiones_por_usuario AS  SELECT u.id AS usuario_id,
    u.nombre_completo,
    u.nombre_sicas,
    u.id_sicas,
    u.email_laboral,
    o.nombre AS oficina_nombre,
    rf.name AS regimen_fiscal,
    count(cd.id) AS total_polizas,
    sum(cd.importe_base) AS total_importe_base,
    sum(cd.commission_bruta) AS total_commission_bruta,
    sum(cd.commission_neta) AS total_commission_neta,
    min(cd.created_at) AS primera_comision,
    max(cd.created_at) AS ultima_comision
   FROM (((usuarios u
     LEFT JOIN oficinas o ON ((o.id = u.oficina_id)))
     LEFT JOIN commission_fiscal_regimes rf ON ((rf.id = u.regimen_fiscal_id)))
     LEFT JOIN commission_details cd ON ((cd.usuario_id = u.id)))
  WHERE (u.deleted_at IS NULL)
  GROUP BY u.id, u.nombre_completo, u.nombre_sicas, u.id_sicas, u.email_laboral, o.nombre, rf.name
  ORDER BY (sum(cd.commission_neta)) DESC NULLS LAST;

CREATE OR REPLACE VIEW public.vista_correos_bloqueados AS  SELECT au.id,
    au.email AS correo_retenido,
    u.nombre,
    u.apellidos,
    u.rol,
        CASE
            WHEN (u.id IS NULL) THEN 'sin_ficha_movi'::text
            WHEN u.is_deleted THEN 'eliminado'::text
            WHEN (u.estado = 'eliminado'::text) THEN 'eliminado'::text
            ELSE 'visible'::text
        END AS motivo,
    ( SELECT count(*) AS count
           FROM referencias_de_cuenta(au.id) referencias_de_cuenta(tabla, columna, filas)) AS referencias,
    au.created_at,
    au.last_sign_in_at
   FROM (auth.users au
     LEFT JOIN usuarios u ON ((u.id = au.id)))
  WHERE (((au.email)::text !~~ 'deleted-%@deleted.local'::text) AND ((u.id IS NULL) OR (u.is_deleted = true) OR (u.estado = 'eliminado'::text)));

CREATE OR REPLACE VIEW public.vista_historial_envios_completo AS  SELECT h.id,
    h.tipo_notificacion_codigo,
    ctn.nombre AS tipo_notificacion_nombre,
    h.canal_envio,
    h.destinatario_email,
    h.destinatario_nombre,
    h.numero_destino,
    h.asunto,
    h.estado,
    h.error_mensaje,
    h.fecha_envio,
    h.created_at,
    u.id AS usuario_id,
    u.nombre_completo AS usuario_nombre_completo,
    u.rol AS usuario_rol,
    o.nombre AS oficina_nombre,
    enviador.nombre_completo AS enviado_por_nombre,
    enviador.rol AS enviado_por_rol,
    h.whatsapp_respuesta,
    h.evento_id
   FROM ((((correo_historial_envios h
     LEFT JOIN correo_tipos_notificacion ctn ON ((h.tipo_notificacion_id = ctn.id)))
     LEFT JOIN usuarios u ON ((h.usuario_id = u.id)))
     LEFT JOIN oficinas o ON ((u.oficina_id = o.id)))
     LEFT JOIN usuarios enviador ON ((h.enviado_por = enviador.id)))
  ORDER BY h.fecha_envio DESC;

CREATE OR REPLACE VIEW public.vista_inconsistencias_mapeo_vendedores AS  WITH usuarios_sin_mapeo AS (
         SELECT u.id AS usuario_id,
            u.nombre_completo,
            u.nombre_sicas,
            u.id_sicas,
            'Usuario con nombre_sicas pero sin mapeo en sicas_mapeo_vendedor_usuario'::text AS tipo_inconsistencia,
            NULL::text AS comision_id,
            NULL::uuid AS usuario_id_disponible
           FROM usuarios u
          WHERE ((u.nombre_sicas IS NOT NULL) AND (u.estado <> 'eliminado'::text) AND (NOT (EXISTS ( SELECT 1
                   FROM sicas_mapeo_vendedor_usuario smu
                  WHERE (smu.movi_user_id = u.id)))))
        ), vendedores_sin_comisiones AS (
         SELECT u.id AS usuario_id,
            u.nombre_completo,
            sv.nombre AS nombre_sicas,
            sv.id_sicas,
            'Vendedor SICAS mapeado sin comisiones en últimos 6 meses'::text AS tipo_inconsistencia,
            NULL::text AS comision_id,
            NULL::uuid AS usuario_id_disponible
           FROM ((sicas_mapeo_vendedor_usuario smu
             JOIN usuarios u ON ((u.id = smu.movi_user_id)))
             JOIN sicas_vendedores sv ON ((sv.id_sicas = smu.id_sicas_vendedor)))
          WHERE (NOT (EXISTS ( SELECT 1
                   FROM commission_details cd
                  WHERE ((cd.usuario_id = u.id) AND (cd.created_at >= (now() - '6 mons'::interval))))))
        ), comisiones_sin_usuario AS (
         SELECT NULL::uuid AS usuario_id,
            u.nombre_completo,
            sv.nombre AS nombre_sicas,
            cd.vend_id_sicas AS id_sicas,
            'Comisión sin usuario pero vend_id_sicas tiene mapeo disponible'::text AS tipo_inconsistencia,
            (cd.id)::text AS comision_id,
            u.id AS usuario_id_disponible
           FROM (((commission_details cd
             JOIN sicas_vendedores sv ON ((sv.id_sicas = cd.vend_id_sicas)))
             JOIN sicas_mapeo_vendedor_usuario smu ON ((smu.id_sicas_vendedor = sv.id_sicas)))
             JOIN usuarios u ON ((u.id = smu.movi_user_id)))
          WHERE ((cd.usuario_id IS NULL) AND (cd.vend_id_sicas IS NOT NULL))
        ), nombres_inconsistentes AS (
         SELECT u.id AS usuario_id,
            u.nombre_completo,
            u.nombre_sicas,
            NULL::text AS id_sicas,
            'Nombres inconsistentes entre usuarios.nombre_sicas y sicas_vendedores.nombre'::text AS tipo_inconsistencia,
            NULL::text AS comision_id,
            NULL::uuid AS usuario_id_disponible
           FROM ((usuarios u
             JOIN sicas_mapeo_vendedor_usuario smu ON ((smu.movi_user_id = u.id)))
             JOIN sicas_vendedores sv ON ((sv.id_sicas = smu.id_sicas_vendedor)))
          WHERE ((u.nombre_sicas IS NOT NULL) AND (sv.nombre IS NOT NULL) AND (normalize_person_name(u.nombre_sicas) <> normalize_person_name(sv.nombre)))
        )
 SELECT usuarios_sin_mapeo.usuario_id,
    usuarios_sin_mapeo.nombre_completo,
    usuarios_sin_mapeo.nombre_sicas,
    usuarios_sin_mapeo.id_sicas,
    usuarios_sin_mapeo.tipo_inconsistencia,
    usuarios_sin_mapeo.comision_id,
    usuarios_sin_mapeo.usuario_id_disponible
   FROM usuarios_sin_mapeo
UNION ALL
 SELECT vendedores_sin_comisiones.usuario_id,
    vendedores_sin_comisiones.nombre_completo,
    vendedores_sin_comisiones.nombre_sicas,
    vendedores_sin_comisiones.id_sicas,
    vendedores_sin_comisiones.tipo_inconsistencia,
    vendedores_sin_comisiones.comision_id,
    vendedores_sin_comisiones.usuario_id_disponible
   FROM vendedores_sin_comisiones
UNION ALL
 SELECT comisiones_sin_usuario.usuario_id,
    comisiones_sin_usuario.nombre_completo,
    comisiones_sin_usuario.nombre_sicas,
    comisiones_sin_usuario.id_sicas,
    comisiones_sin_usuario.tipo_inconsistencia,
    comisiones_sin_usuario.comision_id,
    comisiones_sin_usuario.usuario_id_disponible
   FROM comisiones_sin_usuario
UNION ALL
 SELECT nombres_inconsistentes.usuario_id,
    nombres_inconsistentes.nombre_completo,
    nombres_inconsistentes.nombre_sicas,
    nombres_inconsistentes.id_sicas,
    nombres_inconsistentes.tipo_inconsistencia,
    nombres_inconsistentes.comision_id,
    nombres_inconsistentes.usuario_id_disponible
   FROM nombres_inconsistentes;

CREATE OR REPLACE VIEW public.vista_mapeo_usuarios_unificado AS  SELECT u.id AS usuario_id,
    u.nombre_completo AS nombre_movi,
    u.email_laboral,
    u.nombre_sicas,
    u.id_sicas,
    u.oficina_id,
    o.nombre AS oficina_nombre,
    u.regimen_fiscal_id,
    rf.name AS regimen_fiscal_nombre,
    smu.id AS sicas_mapping_id,
    smu.id_sicas_vendedor,
    sv.nombre AS sicas_vendedor_nombre,
    smu.mapped_at AS sicas_mapped_at,
    ( SELECT count(*) AS count
           FROM commission_details cd
          WHERE (cd.usuario_id = u.id)) AS comisiones_count,
    ( SELECT sum(cd.commission_neta) AS sum
           FROM commission_details cd
          WHERE (cd.usuario_id = u.id)) AS comisiones_total,
        CASE
            WHEN (smu.id IS NOT NULL) THEN 'SICAS Mapeado'::text
            WHEN (EXISTS ( SELECT 1
               FROM commission_details cd
              WHERE (cd.usuario_id = u.id))) THEN 'Con Comisiones'::text
            ELSE 'Sin Mapeo'::text
        END AS estado_mapeo,
        CASE
            WHEN ((u.nombre_sicas IS NOT NULL) AND (smu.id IS NULL)) THEN 'INCONSISTENTE: nombre_sicas sin mapeo'::text
            WHEN ((u.nombre_sicas IS NULL) AND (smu.id IS NOT NULL)) THEN 'INCONSISTENTE: mapeo sin nombre_sicas'::text
            WHEN ((u.nombre_sicas IS NOT NULL) AND (sv.nombre IS NOT NULL) AND (u.nombre_sicas <> sv.nombre)) THEN 'INCONSISTENTE: nombres no coinciden'::text
            WHEN ((u.id_sicas IS NOT NULL) AND (smu.id_sicas_vendedor IS NOT NULL) AND (u.id_sicas <> smu.id_sicas_vendedor)) THEN 'INCONSISTENTE: id_sicas no coincide'::text
            ELSE 'CONSISTENTE'::text
        END AS estado_consistencia
   FROM ((((usuarios u
     LEFT JOIN oficinas o ON ((o.id = u.oficina_id)))
     LEFT JOIN commission_fiscal_regimes rf ON ((rf.id = u.regimen_fiscal_id)))
     LEFT JOIN sicas_mapeo_vendedor_usuario smu ON ((smu.movi_user_id = u.id)))
     LEFT JOIN sicas_vendedores sv ON ((sv.id_sicas = smu.id_sicas_vendedor)))
  WHERE (u.deleted_at IS NULL)
  ORDER BY u.nombre_completo;

CREATE OR REPLACE VIEW public.vw_tramites_reporte AS  SELECT t.id,
    t.folio,
    t.tipo_tramite,
    tt.label AS tipo_nombre,
    ta.nombre AS area_nombre,
    tgv.nombre AS equipo_nombre,
    u.nombre_completo AS creado_por,
    t.fecha_creacion AS created_at,
    t.completed_at,
    round((EXTRACT(epoch FROM (COALESCE(t.completed_at, now()) - t.fecha_creacion)) / 3600.0), 2) AS lead_time_horas,
    ( SELECT r2.valor_texto
           FROM (tramite_respuestas r2
             JOIN tramite_tipo_campos c2 ON ((r2.campo_id = c2.id)))
          WHERE ((r2.tramite_id = t.id) AND (c2.sistema_key = 'estatus'::text))
          ORDER BY r2.created_at DESC
         LIMIT 1) AS estatus_actual,
    ( SELECT count(*) AS count
           FROM ticket_historial h
          WHERE (h.ticket_id = t.id)) AS total_eventos,
    jsonb_object_agg(c.key, COALESCE(r.valor_texto, (r.valor_numerico)::text, (r.valor_fecha)::text, (r.valor_json)::text)) FILTER (WHERE ((c.key IS NOT NULL) AND (c.is_sistema = false))) AS respuestas
   FROM ((((((tickets t
     LEFT JOIN ticket_tipos tt ON ((t.tipo_tramite = tt.value)))
     LEFT JOIN tramites_areas ta ON ((tt.area_id = ta.id)))
     LEFT JOIN tramites_grupos_visualizacion tgv ON ((t.grupo_asignado_id = tgv.id)))
     LEFT JOIN usuarios u ON ((t.creado_por = u.id)))
     LEFT JOIN tramite_respuestas r ON ((r.tramite_id = t.id)))
     LEFT JOIN tramite_tipo_campos c ON (((r.campo_id = c.id) AND (c.activo = true))))
  GROUP BY t.id, t.folio, t.tipo_tramite, tt.label, ta.nombre, tgv.nombre, u.nombre_completo, t.fecha_creacion, t.completed_at;

