CREATE POLICY "Admins can delete accesos" ON public.accesos_nacional AS PERMISSIVE FOR DELETE TO authenticated USING ((EXISTS ( SELECT 1
   FROM usuarios
  WHERE ((usuarios.id = ( SELECT auth.uid() AS uid)) AND (usuarios.rol = 'Administrador'::text)))));

CREATE POLICY "Authenticated users can insert accesos" ON public.accesos_nacional AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((EXISTS ( SELECT 1
   FROM usuarios
  WHERE (usuarios.id = ( SELECT auth.uid() AS uid)))));

CREATE POLICY "Authenticated users can update accesos" ON public.accesos_nacional AS PERMISSIVE FOR UPDATE TO authenticated USING (true) WITH CHECK (true);

CREATE POLICY "Authenticated users can view accesos" ON public.accesos_nacional AS PERMISSIVE FOR SELECT TO authenticated USING (true);

CREATE POLICY "Users can view attachments of own emails" ON public.adjuntos_correo AS PERMISSIVE FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM correos_usuario
  WHERE ((correos_usuario.id = adjuntos_correo.correo_id) AND (correos_usuario.usuario_id = ( SELECT auth.uid() AS uid))))));

CREATE POLICY "Admins can create impersonation sessions" ON public.admin_impersonation_sessions AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((admin_user_id = auth.uid()) AND (EXISTS ( SELECT 1
   FROM usuarios
  WHERE ((usuarios.id = auth.uid()) AND (usuarios.rol = 'Administrador'::text) AND (usuarios.deleted_at IS NULL))))));

CREATE POLICY "Admins can end own impersonation sessions" ON public.admin_impersonation_sessions AS PERMISSIVE FOR UPDATE TO authenticated USING (((admin_user_id = auth.uid()) AND (EXISTS ( SELECT 1
   FROM usuarios
  WHERE ((usuarios.id = auth.uid()) AND (usuarios.rol = 'Administrador'::text) AND (usuarios.deleted_at IS NULL)))))) WITH CHECK (((admin_user_id = auth.uid()) AND (EXISTS ( SELECT 1
   FROM usuarios
  WHERE ((usuarios.id = auth.uid()) AND (usuarios.rol = 'Administrador'::text) AND (usuarios.deleted_at IS NULL))))));

CREATE POLICY "Admins can view own impersonation sessions" ON public.admin_impersonation_sessions AS PERMISSIVE FOR SELECT TO authenticated USING (((admin_user_id = auth.uid()) AND (EXISTS ( SELECT 1
   FROM usuarios
  WHERE ((usuarios.id = auth.uid()) AND (usuarios.rol = 'Administrador'::text) AND (usuarios.deleted_at IS NULL))))));

