CREATE POLICY "Admins can delete any, Gerentes own comunicados" ON public.comunicados_publicaciones AS PERMISSIVE FOR DELETE TO authenticated USING (((EXISTS ( SELECT 1
   FROM usuarios
  WHERE ((usuarios.id = ( SELECT auth.uid() AS uid)) AND (usuarios.rol = 'Administrador'::text)))) OR ((creado_por = ( SELECT auth.uid() AS uid)) AND (EXISTS ( SELECT 1
   FROM usuarios
  WHERE ((usuarios.id = ( SELECT auth.uid() AS uid)) AND (usuarios.rol = 'Gerente'::text)))))));

CREATE POLICY "Admins can update any, Gerentes own comunicados" ON public.comunicados_publicaciones AS PERMISSIVE FOR UPDATE TO authenticated USING (((EXISTS ( SELECT 1
   FROM usuarios
  WHERE ((usuarios.id = ( SELECT auth.uid() AS uid)) AND (usuarios.rol = 'Administrador'::text)))) OR ((creado_por = ( SELECT auth.uid() AS uid)) AND (EXISTS ( SELECT 1
   FROM usuarios
  WHERE ((usuarios.id = ( SELECT auth.uid() AS uid)) AND (usuarios.rol = 'Gerente'::text))))))) WITH CHECK (((EXISTS ( SELECT 1
   FROM usuarios
  WHERE ((usuarios.id = ( SELECT auth.uid() AS uid)) AND (usuarios.rol = 'Administrador'::text)))) OR ((creado_por = ( SELECT auth.uid() AS uid)) AND (EXISTS ( SELECT 1
   FROM usuarios
  WHERE ((usuarios.id = ( SELECT auth.uid() AS uid)) AND (usuarios.rol = 'Gerente'::text)))) AND ((fijado = false) OR (fijado IS NULL)))));

