CREATE POLICY "Gerentes view own office and admin comunicados" ON public.comunicados_publicaciones AS PERMISSIVE FOR SELECT TO authenticated USING (((publicado = true) AND (fecha_publicacion <= now()) AND (EXISTS ( SELECT 1
   FROM usuarios u
  WHERE ((u.id = ( SELECT auth.uid() AS uid)) AND (u.rol = 'Gerente'::text) AND ((comunicados_publicaciones.oficina_origen_id IS NULL) OR (comunicados_publicaciones.oficina_origen_id = u.oficina_id)))))));

CREATE POLICY "Users can view comunicados based on visibility" ON public.comunicados_publicaciones AS PERMISSIVE FOR SELECT TO authenticated USING (((publicado = true) AND (fecha_publicacion <= now()) AND ((NOT (EXISTS ( SELECT 1
   FROM comunicados_visibilidad
  WHERE (comunicados_visibilidad.comunicado_id = comunicados_publicaciones.id)))) OR (EXISTS ( SELECT 1
   FROM comunicados_visibilidad
  WHERE ((comunicados_visibilidad.comunicado_id = comunicados_publicaciones.id) AND (comunicados_visibilidad.para_todos = true)))) OR (EXISTS ( SELECT 1
   FROM (comunicados_visibilidad cv
     JOIN usuarios u ON ((u.id = ( SELECT auth.uid() AS uid))))
  WHERE ((cv.comunicado_id = comunicados_publicaciones.id) AND (((cv.rol IS NOT NULL) AND (cv.rol = u.rol)) OR ((cv.oficina_id IS NOT NULL) AND (cv.oficina_id = u.oficina_id)) OR ((cv.usuario_id IS NOT NULL) AND (cv.usuario_id = u.id)))))))));

