CASE get_user_role_for_rls(auth.uid())
    WHEN 'Administrador'::text THEN true
    WHEN 'Ejecutivo'::text THEN true
    WHEN 'Gerente'::text THEN (oficina_id = get_user_oficina_for_rls(auth.uid()))
    WHEN 'Empleado'::text THEN (oficina_id = get_user_oficina_for_rls(auth.uid()))
