CREATE POLICY "Agents insert own renewal followups" ON public.sicas_renewal_followups AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((auth.uid() = usuario_id));

CREATE POLICY "Agents update own renewal followups" ON public.sicas_renewal_followups AS PERMISSIVE FOR UPDATE TO authenticated USING ((auth.uid() = usuario_id)) WITH CHECK ((auth.uid() = usuario_id));

CREATE POLICY "Service role full access renewal followups" ON public.sicas_renewal_followups AS PERMISSIVE FOR ALL TO service_role USING (true) WITH CHECK (true);

CREATE POLICY "Users see scoped renewal followups" ON public.sicas_renewal_followups AS PERMISSIVE FOR SELECT TO authenticated USING (
CASE get_user_role_for_rls(auth.uid())
    WHEN 'Administrador'::text THEN true
    WHEN 'Ejecutivo'::text THEN true
    WHEN 'Gerente'::text THEN (EXISTS ( SELECT 1
       FROM sicas_customer_profiles cp
      WHERE ((cp.id = sicas_renewal_followups.customer_profile_id) AND (cp.oficina_id = get_user_oficina_for_rls(auth.uid())))))
    WHEN 'Empleado'::text THEN (EXISTS ( SELECT 1
       FROM sicas_customer_profiles cp
      WHERE ((cp.id = sicas_renewal_followups.customer_profile_id) AND (cp.oficina_id = get_user_oficina_for_rls(auth.uid())))))
    ELSE (auth.uid() = usuario_id)
END);

