CREATE POLICY tickets_select_policy ON public.tickets AS PERMISSIVE FOR SELECT TO public USING ((is_admin_or_manager() OR ((get_auth_user_role() = 'Empleado'::text) AND ((assigned_to_user_id = auth.uid()) OR (attending_user_id = auth.uid()) OR (assigned_to_user_id IS NULL))) OR (creado_por = auth.uid()) OR (agente_id IN ( SELECT tickets.agente_id
   FROM usuarios
  WHERE ((usuarios.id = auth.uid()) AND (tickets.agente_id IS NOT NULL))))));

CREATE POLICY tickets_select_v8 ON public.tickets AS PERMISSIVE FOR SELECT TO authenticated USING (((get_my_rol() = ANY (ARRAY['Administrador'::text, 'Gerente'::text])) OR (EXISTS ( SELECT 1
   FROM (tramites_grupos_miembros tgm
     JOIN mkt_equipos_acceso mea ON ((mea.grupo_id = tgm.grupo_id)))
  WHERE (tgm.usuario_id = auth.uid()))) OR (agente_id = auth.uid()) OR (creado_por = auth.uid()) OR (assigned_to_user_id = auth.uid()) OR (agente_usuario_id = auth.uid()) OR (attending_user_id = auth.uid()) OR ((assigned_to_user_id IS NULL) AND (attending_user_id IS NULL) AND (grupo_asignado_id IS NOT NULL) AND (grupo_asignado_id = ANY (get_my_grupo_ids()))) OR ((grupo_asignado_id IS NOT NULL) AND (grupo_asignado_id = ANY (get_my_grupos_lider_ids())))));

CREATE POLICY tickets_select_v9 ON public.tickets AS PERMISSIVE FOR SELECT TO authenticated USING (((get_my_rol() = ANY (ARRAY['Administrador'::text, 'Gerente'::text])) OR ((agente_id = auth.uid()) AND (NOT es_reporte_de_bug(id))) OR ((creado_por = auth.uid()) AND (NOT es_reporte_de_bug(id))) OR (assigned_to_user_id = auth.uid()) OR (agente_usuario_id = auth.uid()) OR (attending_user_id = auth.uid()) OR ((assigned_to_user_id IS NULL) AND (attending_user_id IS NULL) AND (grupo_asignado_id IS NOT NULL) AND (grupo_asignado_id = ANY (get_my_grupo_ids()))) OR ((grupo_asignado_id IS NOT NULL) AND (grupo_asignado_id = ANY (get_my_grupos_lider_ids())))));

CREATE POLICY tickets_update_by_role ON public.tickets AS PERMISSIVE FOR UPDATE TO authenticated USING (((( SELECT usuarios.rol
   FROM usuarios
  WHERE (usuarios.id = auth.uid())) = 'Administrador'::text) OR ((( SELECT usuarios.rol
   FROM usuarios
  WHERE (usuarios.id = auth.uid())) = 'Gerente'::text) AND ((agente_id IN ( SELECT usuarios.id
   FROM usuarios
  WHERE (usuarios.oficina_id = ( SELECT usuarios_1.oficina_id
           FROM usuarios usuarios_1
          WHERE (usuarios_1.id = auth.uid()))))) OR (creado_por = auth.uid()) OR (assigned_to_user_id = auth.uid()))) OR ((( SELECT usuarios.rol
   FROM usuarios
  WHERE (usuarios.id = auth.uid())) = ANY (ARRAY['Empleado'::text, 'Ejecutivo'::text])) AND ((creado_por = auth.uid()) OR (assigned_to_user_id = auth.uid()) OR (agente_id = auth.uid()))))) WITH CHECK (((( SELECT usuarios.rol
   FROM usuarios
  WHERE (usuarios.id = auth.uid())) = 'Administrador'::text) OR (( SELECT usuarios.rol
   FROM usuarios
  WHERE (usuarios.id = auth.uid())) = 'Gerente'::text) OR ((( SELECT usuarios.rol
   FROM usuarios
  WHERE (usuarios.id = auth.uid())) = ANY (ARRAY['Empleado'::text, 'Ejecutivo'::text])) AND ((creado_por = auth.uid()) OR (assigned_to_user_id = auth.uid()) OR (agente_id = auth.uid())))));

CREATE POLICY tickets_update_by_role_or_participant ON public.tickets AS PERMISSIVE FOR UPDATE TO authenticated USING (((get_my_rol() = 'Administrador'::text) OR ((get_my_rol() = ANY (ARRAY['Gerente'::text, 'Empleado'::text])) AND ticket_in_office(creado_por, agente_id, agente_usuario_id, attending_user_id, assigned_to_user_id, get_my_oficina_id())) OR (creado_por = auth.uid()) OR (assigned_to_user_id = auth.uid()) OR (agente_id = auth.uid()) OR (agente_usuario_id = auth.uid()) OR (attending_user_id = auth.uid()))) WITH CHECK (((get_my_rol() = 'Administrador'::text) OR ((get_my_rol() = ANY (ARRAY['Gerente'::text, 'Empleado'::text])) AND ticket_in_office(creado_por, agente_id, agente_usuario_id, attending_user_id, assigned_to_user_id, get_my_oficina_id())) OR (creado_por = auth.uid()) OR (assigned_to_user_id = auth.uid()) OR (agente_id = auth.uid()) OR (agente_usuario_id = auth.uid()) OR (attending_user_id = auth.uid())));

