     JOIN store_equipos_acceso sea ON ((sea.grupo_id = tgm.grupo_id)))
  WHERE (tgm.usuario_id = auth.uid()))))));

CREATE POLICY tramite_headers_admin_delete ON storage.objects AS PERMISSIVE FOR DELETE TO authenticated USING (((bucket_id = 'tramite-headers'::text) AND (get_my_rol() = 'Administrador'::text)));

CREATE POLICY tramite_headers_admin_write ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((bucket_id = 'tramite-headers'::text) AND (get_my_rol() = 'Administrador'::text)));

CREATE POLICY tramite_headers_public_read ON storage.objects AS PERMISSIVE FOR SELECT TO public USING ((bucket_id = 'tramite-headers'::text));

CREATE POLICY users_delete_own_avatar ON storage.objects AS PERMISSIVE FOR DELETE TO authenticated USING (((bucket_id = 'usuarios'::text) AND ((storage.foldername(name))[1] = 'avatars'::text)));

CREATE POLICY users_update_own_avatar ON storage.objects AS PERMISSIVE FOR UPDATE TO authenticated USING (((bucket_id = 'usuarios'::text) AND ((storage.foldername(name))[1] = 'avatars'::text))) WITH CHECK (((bucket_id = 'usuarios'::text) AND ((storage.foldername(name))[1] = 'avatars'::text)));

CREATE POLICY users_upload_own_avatar ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((bucket_id = 'usuarios'::text) AND ((storage.foldername(name))[1] = 'avatars'::text)));

