CREATE OR REPLACE FUNCTION public.get_reporte_tramites(p_desde timestamp with time zone, p_hasta timestamp with time zone, p_area_id uuid DEFAULT NULL::uuid, p_tipo_tramite text DEFAULT NULL::text, p_equipo_id uuid DEFAULT NULL::uuid)
 RETURNS SETOF vw_tramites_reporte
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT *
  FROM   public.vw_tramites_reporte
  WHERE  created_at >= p_desde
    AND  created_at <  p_hasta
    AND  (
           p_area_id IS NULL
           OR area_nombre = (
               SELECT nombre FROM public.tramites_areas WHERE id = p_area_id
             )
         )
    AND  (p_tipo_tramite IS NULL OR tipo_tramite = p_tipo_tramite)
    AND  (
           p_equipo_id IS NULL
           OR equipo_nombre = (
               SELECT nombre FROM public.tramites_grupos_visualizacion WHERE id = p_equipo_id
             )
         )
  ORDER BY created_at DESC;
$function$
;

COMMENT ON FUNCTION public.get_reporte_tramites(p_desde timestamp with time zone, p_hasta timestamp with time zone, p_area_id uuid, p_tipo_tramite text, p_equipo_id uuid) IS 'Filtra la vista vw_tramites_reporte por rango de fechas y opcionalmente por área, tipo o equipo.';

REVOKE ALL ON FUNCTION public.get_reporte_tramites(p_desde timestamp with time zone, p_hasta timestamp with time zone, p_area_id uuid, p_tipo_tramite text, p_equipo_id uuid) FROM PUBLIC, anon, authenticated, service_role; GRANT EXECUTE ON FUNCTION public.get_reporte_tramites(p_desde timestamp with time zone, p_hasta timestamp with time zone, p_area_id uuid, p_tipo_tramite text, p_equipo_id uuid) TO PUBLIC; GRANT EXECUTE ON FUNCTION public.get_reporte_tramites(p_desde timestamp with time zone, p_hasta timestamp with time zone, p_area_id uuid, p_tipo_tramite text, p_equipo_id uuid) TO anon; GRANT EXECUTE ON FUNCTION public.get_reporte_tramites(p_desde timestamp with time zone, p_hasta timestamp with time zone, p_area_id uuid, p_tipo_tramite text, p_equipo_id uuid) TO authenticated; GRANT EXECUTE ON FUNCTION public.get_reporte_tramites(p_desde timestamp with time zone, p_hasta timestamp with time zone, p_area_id uuid, p_tipo_tramite text, p_equipo_id uuid) TO service_role;

